(window.GIM_TP=window.GIM_TP||{})["Z.Vayakhel.0"]={"from":0,"a":[[[],[],[]],[["(שמות ל״ה:א׳) וַיַּקְהֵל מֹשֶׁה אֶת כָּל עֲדַת בְּנִי יִשְׂרָאֵל וְגוֹ'. רִבִּי חִיָּיא פָּתַח, (שמואל א ט״ו:ו׳) וַיֹּאמֶר שָׁאוּל אֶל הַקֵּנִי לְכוּ סוּרוּ רְדוּ וְגוֹ'. תָּא חֲזֵי, מָה כְּתִיב בַּעֲמָלֵק, (שמואל א ט״ו:ו׳) פָּקַדְתִּי אֵת אֲשֶׁר עָשָׂה עֲמָלֵק לְיִשְׂרָאֵל וְגוֹ'. וְקוּדְשָׁא בְּרִיךְ הוּא בְּכֻלְּהוּ קְרָבִין דְּעָבְדוּ שְׁאָר עַמְמִין לְגַבַּיְיהוּ דְּיִשְׂרָאֵל, מַאי טַעְמָא לָא אַקְשֵׁי קַמֵּיהּ, כְּהַאי קְרָבָא דְּעָבַד עֲמָלֵק לְגַבַּיְיהוּ. אֶלָּא וַדַּאי, קְרָבָא דְּעֲמָלֵק הֲוָה בְּכָל סִטְרִין, לְעֵילָּא וְתַתָּא, דְּהָא בְּהַהוּא זִמְנָא אִתְתָּקַּף חִוְיָא בִּישָׁא לְעֵילָּא, ואִתְתָּקַּף לְתַתָּא."],[[0,"ויקהל משה את כל עדת וגו':","ר' חייא פתח, ויאמר שאול אל הקני לכו סורו וגו'. בוא וראה, מה כתוב בעמלק, פקדתי את אשר עשה עמלק לישראל וגו'. והקב\"ה, בכל המלחמות שעשו שאר העמים עם ישראל, מה הטעם, שלא היה קשה לפניו כמלחמה זו שעשה עמלק עמהם. ומשיב. אלא ודאי המלחמה של עמלק היתה בכל הצדדים למעלה ולמטה, כי בזמן ההוא נתחזק נחש הרע למעלה ונתחזק למטה בעולם הזה."]],[[0,"","וַיַּקְהֵל מֹשֶׁה אֶת כָּל עֲדַת בְּנֵי יִשְׂרָאֵל וְגוֹ'. רַבִּי חִיָּיא פָּתַח, (שמואל א טו) וַיֹּאמֶר שָׁאוּל אֶל הַקֵּינִי לְכוּ סֻרוּ רְדוּ וְגוֹ'. בֹּא וּרְאֵה מַה כָּתוּב בַּעֲמָלֵק, פָּקַדְתִּי אֵת אֲשֶׁר עָשָׂה עֲמָלֵק לְיִשְׂרָאֵל וְגוֹ'. וְהַקָּדוֹשׁ בָּרוּךְ הוּא, בְּכָל הַקְּרָבוֹת שֶׁעָשׂוּ שְׁאָר הָעַמִּים לְגַבֵּי יִשְׂרָאֵל, מָה הַטַּעַם לֹא הָיָה קָשֶׁה לְפָנָיו כְּמוֹ הַקְּרָב שֶׁעָשָׂה עֲמָלֵק אִתָּם? אֶלָּא וַדַּאי הַקְּרָב שֶׁל עֲמָלֵק הָיָה בְּכָל הַצְּדָדִים, לְמַעְלָה וּלְמַטָּה, שֶׁהֲרֵי בְּאוֹתוֹ זְמַן הִתְחַזֵּק הַנָּחָשׁ הָרָע לְמַעְלָה, וְהִתְחַזֵּק לְמַטָּה."]]],[["מָה חִוְיָא בִּישָׁא כַּמִין עַל פָּרָשַׁת אָרְחִין, אוּף הָכָא נָמֵי עֲמָלֵק, חִוְיָא בִּישָׁא הֲוָה לְגַבַּיְיהוּ דְּיִשְׂרָאֵל, דְּכַמִין לוֹן עַל פָּרָשַׁת אָרְחִין, דִּכְתִּיב, (שמואל א ט״ו:ב׳) אֲשֶׁר שָׂם לוֹ בַּדֶּרֶךְ בַּעֲלוֹתוֹ מִמִּצְרָיִם. כַּמִין הֲוָה לְעֵילָּא, לְסָאֳבָא מַקְדְּשָׁא. וְכָמִין הֲוָה לְתַתָּא, לְסָאֲבָא לְיִשְׂרָאֵל. מְנָלָן, דִּכְתִּיב (דברים כ״ה:י״ח) אֲשֶׁר קָרְךָ בַּדֶּרֶךְ. כְּתִיב הָכָא אֲשֶׁר קָּרְךָ, וּכְתִיב הָתָם (דברים כ״ג:י״א) כִּי יִהְיֶה בְךָ אִישׁ אֲשֶׁר לָא טָהוֹר מִקְרֵה לָיְלָה.","ועַל דָּא בְּבִלְעָם כְּתִיב, (במדבר כ״ג:ד׳) וַיִּקָּר אֱלֹהִים אֶל בִּלְעָם. וַיִּקָּר לִישָׁנָא דִּמְסָאֲבָא נָקַט. וְאִי תֵּימָא, הָא כְּתִיב אֱלהִים. אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא אַזְמִין לֵיהּ הַהוּא אֲתָר דִּמְסָאֲבָא, לְאִסְתַּאֲבָא בֵּיהּ, בְּהַהוּא דַּרְגָּא דְּאִיהוּ אִתְדַּבָּק לְאִסְתַּאֲבָא בֵּיהּ. מָה עֲבַד בִּלְעָם. אִיהוּ חָשִׁיב בְּאִינּוּן קָרְבָּנִין לְסַלְּקָא לְעֵילָּא, מִיַּד זַמִין לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא הַהוּא אֲתָר. אֲמַר לֵיהּ הָא מִסְאֲבוּ לְגַבָּךְ, כְּמָה דְּאִתְחָזֵי לָךְ, וְעַל דָּא וַיִּקָּר אֱלהִים אֶל בִּלְעָם.","כְּגַוְונָא דָּא אֲשֶׁר קָרְךָ בַּדֶּרֶךְ וְגוֹ'. אַזְמִין לְגַבָּךְ הַהוּא חִוְיָא בִּישָׁא לְעֵילָּא, לְסָאֲבָא לְךָ בְּכָל סִטְרִין. וְאִלְמָלֵא דְּאִתְתָּקַּף מֹשֶׁה לְעֵילָּא, וִיהוֹשֻׁעַ לְתַתָּא, לָא יָכִילוּ יִשְׂרָאֵל לֵיהּ. וּבְגִין כַּךְ, נָטִיר קוּדְשָׁא בְּרִיךְ הוּא הַהוּא דְּבָבוּ, לְדָרֵי דָּרִין. מַאי טַעְמָא. בְּגִין דְּחָשִׁיב לְאַעְקְרָא אָת קַיָּימָא מֵאַתְרֵיהּ. וּבְגִין כַּךְ פָּקַדְתִּי, בִּפְקִידָּה, דְּהָא תַּמָּן (ויצא קנ\"ט ע\"ב) אִתְרְמִיז רָזָא דְּאָת קַיָּימָא קַדִּישָׁא.","תָּא חֲזֵי, מָה כְּתִיב, וַיֹּאמֶר שָׁאוּל אֶל הַקֵּנִי. מַאן קֵנִי. דָּא יִתְרוֹ. וְכִי מַאן יָהִיב בְּנֵי יִתְרוֹ הָכָא, לְמֶהוֵי דִּיּוּרֵיהוֹן בַּעֲמָלֵק, וְהָא בִּירִיחוֹ הֲווֹ שַׁרְיָין. אֶלָּא הָא כְּתִיב, (שופטים א׳:ט״ז) וּבְנֵי קֵנִי חֹתֵן מֹשֶׁה עָלוּ מֵעִיר הַתְּמָרִים אֶת בְּנֵי יְהוּדָה מִדְבָּר יְהוּדָה וְגוֹ'. וְכַד עָלוּ מִתַּמָּן, שָׁרוּ בִּתְחוּמָא דַּעֲמָלֵק, עַד הַהוּא זִמְנָא דְּאָתָא שָׁאוּל מַלְכָּא, דִּכְתִּיב וַיָּסַר קֵנִי מִתּוֹךְ עֲמָלֵק.","בְּגִין דְּהָא בְּזִמְנָא דְּחַיָּיבַיָּא אִשְׁתְּכָחוּ, (נ\"א אתענשו) אִינּוּן חֲסִידֵי וְזַכָּאֵי דְּמִשְׁתַּכְחִין בֵּינַיְיהוּ, מִתָּפְסָן בְּחוֹבֵיהוֹן, וְהָא אוּקְמוּהָ. כְּגַוְונָא דָּא, אִלְמָלֵא הַהוּא עִרְבּוּבְיָא דְּאִתְחַבָּרוּ בְּהוּ בְּיִשְׂרָאֵל, לָא אִתְעֲנָשׁוּ יִשְׂרָאֵל, עַל עוֹבָדָא דְּעֶגְלָא.","וְתָּא חֲזֵי מָה כְּתִיב (קצ\"ז, רכ\"ד ע\"א) בְּקַדְמִיתָא, (שמות כ״ה:ב׳) מֵאֵת כָּל אִישׁ אֲשֶׁר יִדְּבֶנּוּ לִבּוֹ, לְאַכְלְלָא כֹּלָּא, בְּגִין דְּבָעָא קוּדְשָׁא בְּרִיךְ הוּא לְמֶעְבַּד עוֹבָדָא דְּמַשְׁכְּנָא מִכָּל סִטְרִין, בְּמוֹחָא וּקְלִיפָה. וּבְגִין דַּהֲווֹ אִינּוּן עֵרֶב רַב בְּגַּוַּויְיהוּ, אִתְּמַר מֵאֵת כָּל אִישׁ אֲשֶׁר יִדְּבֶנּוּ לִבּוֹ, לְאַכְלְלָא לוֹן בֵּינַיְיהוּ דְּיִשְׂרָאֵל, דְּאִינּוּן מוֹחָא. וְכֻלְּהוּ אִתְפְּקָדוּ.","לְבָתַר סָטָא זִינָא לְזִינֵיהּ, וְאָתוּ אִינּוּן עֵרֶב רַב וְעָבָדוּ יַת עֶגְלָא, וְסָטוּ אֲבַתְרַיְיהוּ אִינּוּן דְּמִיתוּ, וְגָרְמוּ לוֹן לְיִשְׂרָאֵל מוֹתָא וְקָטוֹלָא. אָמַר קוּדְשָׁא בְּרִיךְ הוּא, מִכָּאן וּלְהָלְאָה עוֹבָדָא דְּמַשְׁכְּנָא לָא יְהֵא, אֶלָּא (קצ\"ז ע\"א) מִסִּטְרָא דְּיִשְׂרָאֵל בִּלְחוֹדַיְיהוּ. מִיַּד וַיַּקְהֵל מֹשֶׁה אֶת כָּל עֲדַת בְּנִי יִשְׂרָאֵל וְגוֹ'. וּכְתִיב בַּתְרֵיהּ קְחוּ מֵאִתְּכֶם תְּרוּמָה לַיְיָ'. מֵאִתְּכֶם וַדַּאי, וְלָא כְּקַדְמִיתָא דִּכְתִּיב, מֵאֵת כָּל אִישׁ אֲשֶׁר יִדְּבֶנּוּ לִבּוֹ. וַיַּקְהֵל מֹשֶׁה וְגוֹ', מֵאָן אֲתָר כָּנִישׁ לוֹן. אֶלָּא בְּגִין דַּהֲווֹ אִינּוּן עֵרֶב רַב בֵּינַיְיהוּ, אִצְטְרִיךְ מֹשֶׁה לְאַכְנָשָׁא לוֹן, וּלְיַחֲדָא לוֹן מִבֵּינַיְיהוּ.","(שמות ל״ה:א׳) וַיַּקְהֵל מֹשֶׁה. רִבִּי אַבָּא פָּתַח, (דברים ל״א:י״ב) הַקְהֵל אֶת הָעָם הָאֲנָשִׁים וְהַנָּשִׁים וְהַטַּף. מָה לְּהַלָּן כְּלָלָא דְּכֻלְּהוּ יִשְׂרָאֵל, אוּף הָכָא כְּלָלָא דְּכֻלְּהוּ יִשְׂרָאֵל, וּמַאן אִינּוּן. שִׁתִּין רִבּוֹא.","רִבִּי אֶלְעָזָר פָּתַח קְרָא בְּיִשְׂרָאֵל, כַּד נָחִית מֹשֶׁה מִן טוּרָא דְּסִינַי, דִּכְתִּיב, (שמות ל״ב:י״ז) וַיִּשְׁמַע יְהוֹשֻׁעַ אֶת קוֹל הָעָם בְּרֵעֹה וַיֹּאמֶר אֶל מֹשֶׁה קוֹל מִלְחָמָה בַּמַּחֲנֶה. וַיִּשְׁמַע יְהוֹשֻׁעַ, וְכִי יְהוֹשֻׁעַ שָׁמַע, וּמֹשֶׁה לָא שָׁמַע. אֶלָּא וַדַּאי, עַד הַשְׁתָּא יְהוֹשֻׁעַ לָא הֲוָה יָדַע, וּמֹשֶׁה הֲוָה יָדַע. אִי הָכִי מַהוּ בְּרֵעֹה. אֶלָּא בְּרֵעֹה בְּהֵ' כְּתִיב, דְּהַהוּא קַלָּא בְּסִטְרָא אַחֲרָא הֲוָה. וִיהוֹשֻׁעַ דְּהֲוָה אַנְפּוֹי דְּסִיהֲרָא, אִסְתָּכַּל בְּהַהוּא קָלָא, דְּהֲוָה דְּסִטְרָא דְּרָעָה, מִיַּד וַיֹּאמֶר אֶל מֹשֶׁה קוֹל מִלְחָמָה בַּמַּחֲנְה.","בְּהַהִיא שַׁעֲתָא אִתְבָּרוּ תְּרֵין לוּחֵי אַבְנָא דַּהֲווֹ בְּקַדְמִיתָא. וְהָא אוֹקִימְנָא, דְּאִינּוּן אִתְיָיקָרוּ עַל יְדוֹי וְנָפְלוּ וְאִתְבָּרוּ. מַאי טַעְמָא. בְּגִין דְּפָרְחוּ אַתְוָון מִגּוֹ לוּחֵי אֲבָנִין. (פ\"א ע\"א, ויקרא ע\"ו)"],[[0,"מה חויא בישא וכו':","מה נחש הרע אורב על פרשת דרכים אף כן עמלק היה נחש רע לישראל, שארב להם על פרשת דרכים, שכתוב, אשר שם לו בדרך בעלותו ממצרים. וארב הוא למעלה לטמא המקדש שהוא המלכות, וארב למטה לטמא את ישראל. מאין לנו, שכתוב, אשר קרך בדרך. כתוב כאן אשר \u0003קרך,\u0004 וכתוב שם, כי יהיה בך איש אשר לא יהיה טהור \u0003מקרה\u0004 לילה. מה שם טומאה אף כאן טומאה."],[1,"וע\"ד בבלעם כתיב וכו':","וע\"כ בבלעם כתוב, ויקר אלקים אל בלעם. ויקר הוא לשון טומאה. דהיינו מלשון מקרה לילה כנ\"ל. ואם תאמר, הרי כתוב, אלקים שהוא קדש. אלא הקב\"ה הזמין לו מקום ההוא של הטומאה להטמאות בו, באותה המדרגה שהוא נתדבק להטמאות בה. מה עשה בלעם. הוא חשב באלו הקרבנות שהקריב, לעלות למעלה לקדושה, מיד הזמין לו הקב\"ה מקום ההוא של הטומאה. אמר לו, הרי הטומאה אליך, כמו שראוי לך. וע\"כ כתוב, ויקר אלקים אל בלעם."],[2,"כגוונא דא, אשר וכו':","כעין זה, אשר קרך בדרך וגו' שפירושו הזמן לך אותו נחש הרע למעלה לטמא אותך בכל הצדדים. ולולא שנתחזק משה למעלה, ויהושע למטה, לא יכלו לו ישראל. ומשום זה נטר הקב\"ה שנאה ההוא לדורי דורות. מהו הטעם. משום שחשב לעקור אות הברית ממקומו. ומשום זה כתוב, \u0003פקדתי,\u0004 דהיינו בפקידה, שהיא המלכות, כי שם נרמז הסוד של אות ברית קודש."],[3,"ת\"ח מה כתיב וכו':","בוא וראה, מה כתוב, ויאמר שאול אל הקני. מי הוא קני. זה יתרו. שואל, וכי מי נתן בני יתרו כאן, שיהיו דירתם בעמלק, והרי בירחו היו שורים. ומשיב, אלא הרי כתוב, ובני קני חותן משה עלו מעיר התמרים את בני יהודה מדבר יהודה וגו'. וכשעלו משם שרו בתחום של עמלק, עד אותו הזמן שבא שאול המלך. שכתוב, ויסר קני מתוך עמלק."],[4,"בגין דהא בזמנא וכו':","משום, כי בזמן שנמצאים רשעים, אלו החסידים והצדיקים הנמצאים ביניהם נתפשים בעונם. וכבר העמידוהו. וע\"כ הסיר שאול את הקני מתוך עמלק. כעין זה, לולא אותו הערב רב שנתחברו בישראל, לא היו נענשים ישראל על חטא העגל."],[5,"ות\"ח מה כתיב וכו':","ובוא וראה מה כתוב מקודם, מאת כל איש אשר ידבנו לבו, שכולל הכל, ואפילו את הערב רב, משום שרצה הקב\"ה לעשות מעשה המשכן מכל הצדדים, במוח ובקליפה. ומשום שהיו אלו ערב רב ביניהם, נאמר, מאת כל איש אשר ידבנו לבו. לכלול אותם בין ישראל, שהם מוח. וכולם נפקדו להשתתף במשכן."],[6,"לבתר סטא זינא וכו':","אח\"כ נטה מין למינו, ובאו הערב רב ועשו את העגל, ונטו אחריהם מישראל כל אלו שמתו. וגרמו לישראל מות והריגה. אמר הקב\"ה מכאן ולהלאה, מעשה המשכן לא יהיה אלא מצד ישראל בלבד. מיד, ויקהל משה את כל עדת בני ישראל וגו'. וכתוב אחריו קחו מאתכם תרומה לה'. מאתכם ודאי, ולא כמקודם שכתוב, מאת כל איש אשר ידבנו לבו. \u0003ויקהל משה\u0004 וגו'. מאיזה מקום הקהיל אותם. אלא משום שהערב רב ביניהם היה צריך משה להקהיל אותם וליחדם מביניהם."],[7,"ויקהל משה:","רבי אבא פתח, הקהל את העם האנשים ונשים והטף. מה להלאה הוא כלל של כל ישראל, אף כאן הכלל של כל ישראל. מי הם ששים רבוא."],[8,"ר' אלעזר פתח וכו':","ר\"א פתח המקרא, בישראל, כשירד משה מן הר סיני. שכתוב, וישמע יהושע את קול העם ברעה ויאמר אל משה קול מלחמה במחנה. שואל \u0003וישמע יהושע,\u0004 וכי יהושע שמע ומשה לא שמע. ומשיב, אלא עד עתה לא היה יודע, יהושע, ומשה היה יודע, וע\"כ כתוב, וישמע יהושע. שואל, אם כן מהו \u0003ברעה.\u0004 ומשיב, אלא ברעה כתוב עם \u0003ה',\u0004 ללמד, כי הקול הזה היה בסטרא אחרא שנקרא רעה. ויהושע היה פני הלבנה, שהיא המלכות, הסתכל בקול ההוא שהיה מצד \u0003הרעה,\u0004 מיד, ויאמר אל משה קול מלחמה במחנה."],[9,"שההיא שעתא אתברו וכו':","בשעה ההוא נשברו ב' לוחות האבנים הראשונים. והרי העמדנו, שהם הכבידו על ידיו של משה, ונפלו ונשברו. מהו הטעם. משום שפרחו האותיות מן לוחות האבנים, ונשארו האבנים בלי רוח, שהוא האותיות, וע\"כ הוכבדו."]],[[0,"","מָה הַנָּחָשׁ הָרָע אוֹרֵב עַל פָּרָשַׁת דְּרָכִים, אַף כָּאן גַּם עֲמָלֵק נָחָשׁ רָע הָיָה לְיִשְׂרָאֵל, שֶׁאָרַב לָהֶם עַל פָּרָשַׁת דְּרָכִים, שֶׁכָּתוּב (שמואל א טו) אֲשֶׁר שָׂם לוֹ בַּדֶּרֶךְ בַּעֲלֹתוֹ מִמִּצְרָיִם. אוֹרֵב הָיָה לוֹ לְמַעְלָה לְטַמֵּא אֶת הַמִּקְדָּשׁ, וְאוֹרֵב הָיָה לְמַטָּה לְטַמֵּא אֶת יִשְׂרָאֵל. מִנַּיִן לָנוּ? שֶׁכָּתוּב (דברים כה) אֲשֶׁר קָרְךְ בַּדֶּרֶךְ. כָּתוּב כָּאן אֲשֶׁר קָרְךְ, וְכָתוּב שָׁם (שםכג) כִּי יִהְיֶה בְךְ אִישׁ אֲשֶׁר לֹא טָהוֹר מִקְּרֵה לָיְלָה."],[1,"","וְעַל זֶה כָּתוּב בְּבִלְעָם, (במדבר כג) וַיִּקָּר אֱלֹהִים אֶל בִּלְעָם. וַיִּקָּר - לְשׁוֹן טֻמְאָה נָקַט. וְאִם תֹּאמַר, הֲרֵי כָּתוּב אֱלֹהִים, אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא הִזְמִין לוֹ אוֹתוֹ מָקוֹם שֶׁל טֻמְאָה לְהִטָּמֵא בּוֹ בְּאוֹתָהּ דַּרְגָּה שֶׁהוּא נִדְבַּק לְהִטָּמֵא בָּהּ. מֶה עָשָׂה בִּלְעָם? הוּא חָשַׁב בְּאוֹתָם קָרְבָּנוֹת לַעֲלוֹת לְמַעְלָה. מִיָּד הִזְמִין לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹתוֹ מָקוֹם. אָמַר לוֹ, הִנֵּה טֻמְאָה אֵלֶיךְ כְּמוֹ שֶׁרָאוּי לְךְ. וְעַל זֶה וַיִּקָּר אֱלֹהִים אֶל בִּלְעָם."],[2,"","כְּמוֹ כֵן אֲשֶׁר קָרְךְ בַּדֶּרֶךְ וְגוֹ', הִזְמִין לְךְ אוֹתוֹ הַנָּחָשׁ הָרָע לְמַעְלָה לְטַמֵּא אוֹתְךְ בְּכָל הַצְּדָדִים. וְאִלְמָלֵא שֶׁהִתְחַזֵּק מֹשֶׁה לְמַעְלָה וִיהוֹשֻׁעַ לְמַטָּה, לֹא יָכְלוּ לוֹ יִשְׂרָאֵל. וּמִשּׁוּם כָּךְ שָׁמַר הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹתָהּ שִׂנְאָה לְדוֹרֵי דוֹרוֹת. מָה הַטַּעַם? מִשּׁוּם שֶׁחָשַׁב לַעֲקֹר אוֹת הַבְּרִית מִמְּקוֹמָהּ, וּמִשּׁוּם כָּךְ פָּקַדְתִּי, בִּפְקִידָה, שֶׁהֲרֵי שָׁם נִרְמָז סוֹד הָאוֹת הַבְּרִית הַקְּדוֹשָׁה."],[3,"","בֹּא וּרְאֵה מַה כָּתוּב, וַיֹּאמֶר שָׁאוּל אֶל הַקֵּינִי. מִי זֶה הַקֵּינִי? זֶה יִתְרוֹ. וְכִי מִי נָתַן כָּאן אֶת בְּנֵי יִתְרוֹ לִהְיוֹת דִּיּוּרָם בַּעֲמָלֵק, וַהֲרֵי הָיוּ שְׁרוּיִים בִּירִיחוֹ? אֶלָּא הֲרֵי כָּתוּב (שופטים א) וּבְנֵי קֵינִי חֹתֵן מֹשֶׁה עָלוּ מֵעִיר הַתְּמָרִים אֶת בְּנֵי יְהוּדָה מִדְבַּר יְהוּדָה וְגוֹ'. וּכְשֶׁעָלוּ מִשָּׁם, שְׁרוּיִים הָיוּ בִּתְחוּמוֹ שֶׁל עֲמָלֵק עַד לְאוֹתוֹ זְמַן שֶׁבָּא שָׁאוּל הַמֶּלֶךְ, שֶׁכָּתוּב וַיָּסַר קֵינִי מִתּוֹךְ עֲמָלֵק."],[4,"","מִשּׁוּם שֶׁהֲרֵי בִּזְמַן שֶׁנִּמְצָאִים רְשָׁעִים, (נענשו) אוֹתָם חֲסִידִים וְצַדִּיקִים שֶׁנִּמְצָאִים בֵּינֵיהֶם נִתְפָּסִים בַּחֲטָאֵיהֶם, וַהֲרֵי פֵּרְשׁוּהָ. כְּמוֹ זֶה, אִלְמָלֵא אוֹתָהּ עִרְבּוּבְיָה שֶׁהִתְחַבְּרוּ בָהֶם בְּיִשְׂרָאֵל, לֹא נֶעֶנְשׁוּ יִשְׂרָאֵל עַל מַעֲשֵׂה הָעֵגֶל."],[5,"","וּבֹא רְאֵה מַה כָּתוּב בָּרִאשׁוֹנָה, (שמות כה) מֵאֵת כָּל אִישׁ אֲשֶׁר יִדְּבֶנּוּ לִבּוֹ, לְהַכְלִיל אֶת כֻּלָּם, מִשּׁוּם שֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לַעֲשׂוֹת אֶת מַעֲשֵׂה הַמִּשְׁכָּן מִכָּל הַצְּדָדִים, בְּמֹחַ וּקְלִפָּה. וּמִשּׁוּם שֶׁהָיוּ אוֹתָם עֵרֶב רַב עִמָּהֶם, נֶאֱמַר מֵאֵת כָּל אִישׁ אֲשֶׁר יִדְּבֶנּוּ לִבּוֹ, לְהַכְלִילָם בֵּין יִשְׂרָאֵל, שֶׁהֵם מֹחַ, וְכֻלָּם הִצְטַוּוּ."],[6,"","אַחַר כָּךְ סָטָה כָּל מִין לְמִינוֹ, וּבָאוּ אוֹתָם עֵרֶב רַב וְעָשׂוּ אֶת הָעֵגֶל, וְסָטוּ אַחֲרֵיהֶם אוֹתָם שֶׁמֵּתוּ וְגָרְמוּ לְיִשְׂרָאֵל מָוֶת וְהֶרֶג. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, מִכָּאן וָהָלְאָה מַעֲשֵׂה הַמִּשְׁכָּן לֹא יִהְיֶה אֶלָּא רַק מִצִּדָּם שֶׁל יִשְׂרָאֵל לְבַדָּם. מִיָּד - וַיַּקְהֵל מֹשֶׁה אֶת כָּל עֲדַת יִשְׂרָאֵל וְגוֹ'. וְכָתוּב אַחֲרָיו, קְחוּ מֵאִתְּכֶם תְּרוּמָה לַה'. מֵאִתְּכֶם וַדַּאי, וְלֹא כָּרִאשׁוֹנָה שֶׁכָּתוּב מֵאֵת כָּל אִישׁ אֲשֶׁר יִדְּבֶנּוּ לִבּוֹ. וַיַּקְהֵל מֹשֶׁה וְגוֹ', מֵאֵיזֶה מָקוֹם הִקְהִיל אוֹתָם? אֶלָּא מִשּׁוּם שֶׁהָיוּ אוֹתָם עֵרֶב רַב בֵּינֵיהֶם, הִצְטָרֵךְ מֹשֶׁה לְכַנְּסָם וּלְיַחֲדָם מִבֵּינֵיהֶם."],[7,"","וַיַּקְהֵל מֹשֶׁה. רַבִּי אַבָּא פָּתַח, (דברים לא) הַקְהֵל אֶת הָעָם הָאֲנָשִׁים וְהַנָּשִׁים וְהַטַּף. מַה לְּהַלָּן כְּלָל שֶׁל כָּל יִשְׂרָאֵל, אַף כָּאן כְּלָל שֶׁל כָּל יִשְׂרָאֵל. וּמִי הֵם? שִׁשִּׁים רִבּוֹא."],[8,"","רַבִּי אֶלְעָזָר פָּתַח אֶת הַפָּסוּק בְּיִשְׂרָאֵל, כְּשֶׁיָּרַד מֹשֶׁה מֵהַר סִינַי, שֶׁכָּתוּב (שמות לב) וַיִּשְׁמַע יְהוֹשֻׁעַ אֶת קוֹל הָעָם בְּרֵעֹה וַיֹּאמֶר אֶל מֹשֶׁה קוֹל מִלְחָמָה בַּמַּחֲנֶה. וַיִּשְׁמַע יְהוֹשֻׁעַ, וְכִי יְהוֹשֻׁעַ שָׁמַע וּמֹשֶׁה לֹא שָׁמַע?! אֶלָּא וַדַּאי, עַד עַכְשָׁו יְהוֹשֻׁעַ לֹא הָיָה יוֹדֵעַ, וּמֹשֶׁה הָיָה יוֹדֵעַ. אִם כָּךְ, מַה זֶּה בְּרֵעֹה? אֶלָּא בְּרֵעֹה כָּתוּב בְּה', שֶׁאוֹתוֹ קוֹל הָיָה בַּצַּד הָאַחֵר. וִיהוֹשֻׁעַ, שֶׁהָיָה פְּנֵי הַלְּבָנָה, הִתְבּוֹנֵן בְּאוֹתוֹ קוֹל שֶׁהָיָה שֶׁל צַד הָרָעָה, מִיָּד - וַיֹּאמֶר אֶל מֹשֶׁה קוֹל מִלְחָמָה בַּמַּחֲנֶה."],[9,"","בְּאוֹתָהּ שָׁעָה נִשְׁבְּרוּ שְׁנֵי לוּחוֹת הָאֶבֶן שֶׁהָיוּ בָּרִאשׁוֹנָה. וַהֲרֵי בֵּאַרְנוּ, שֶׁהֵם כָּבְדוּ עַל יָדוֹ, וְנָפְלוּ וְנִשְׁבְּרוּ. מָה הַטַּעַם? מִשּׁוּם שֶׁפָּרְחוּ הָאוֹתִיּוֹת מִתּוֹךְ לוּחוֹת הָאֲבָנִים."]]],[["תָּא חֲזֵי, בְּד' תְּקוּפִין דְּשַׁתָּא, קָלָא אִתְּעַר, בְּד' סִטְרִין דְּעָלְמָא, בְּהַהוּא קָלָּא אִתְּעָרוּתָא דְּסִטְרָא אַחֲרָא אִתְּעַר בֵּיהּ. וְהַהוּא אִתְּעָרוּתָא דְּסִטְרָא אַחֲרָא עָאל בֵּין קַלָּא לְקָלָא, וְאִתְחֲשָׁךְ נְהוֹרָא בְּקָלָא דִּלְתַתָּא. בְּגִין דְּלָא מָטָא נְהוֹרָא דְּקָלָא דִּלְעֵילָּא, לְקָלָא דִּלְתַתָּא, כְּדֵין אַקְדִּים הַהוּא אִתְּעָרוּתָא, וְעָאל בֵּין דָּא לְדָא נָחָשׁ דִּמְפַתֵּי לְאִתְּתָא, וְנָטִיל נְהוֹרָא. וְהַהוּא קָלָא, הוּא קוֹל מִלְחָמָה, קוֹל רָעָה. וְדָא אִיהוּ בְּרֵעֹה.","וְעַל דָּא שָׁמַע יְהוֹשֻׁעַ וְלָא מֹשֶׁה, בְּגִין דְּנָטַל הַהוּא רָעָה נְהוֹרָא דְּסִיהֲרָא דְּהֲוָה אָחִיד בָּהּ יְהוֹשֻׁעַ. וּמֹשֶׁה דְּהֲוָה אָחִיד בְּשִׁמְשָׁא, לָא שָׁמַע. וְיִשְׂרָאֵל כֻּלְּהוּ אִתְחֲשָׁךְ נְהוֹרָא דִּילְהוֹן, בְּגִין הַהוּא רָעָה דְּאִתְדַּבְּקָת בְּהוּ. כֵּיוָן דְּמָחַל קוּדְשָׁא בְּרִיךְ הוּא חוֹבֵיהוֹן, כְּדֵין וַיַּקְהֵל מֹשֶׁה אֶת כָּל עֲדַת בְּנֵי יִשְׂרָאֵל וַיֹּאמֶר אֲלֵיהֶם אֵלֶּה הַדְּבָרִים וְגוֹ', דְּהָא הַהוּא עֵרֶב רַב אִתְעַבָּר מִנַּיְיהוּ.","רִבִּי אֶלְעָזָר וְרִבִּי יוֹסֵי הָווֹ יַתְבֵי לֵילְיָא חַד, וְקָא מִתְעַסְקֵי בְּאוֹרַיְיתָא, עַד לָא אִתְפְּלִיג לֵילְיָא. אַדְּהָכִי קָרָא גַּבְרָא, בְּרִיכוּ בִּרְכָתָא, (אמר ליה רבי אלעזר, השתא הוא זמנא דקודשא בריך הוא עאל בגנתא דעדן לאשתעשעא עם צדיקיא, אמר ליה רבי יוסי, אמאי משתעשע קודשא בהך הוא) בָּכָה רִבִּי אֶלְעָזָר וְאָמַר, תָּא חֲזֵי, עַד הַשְׁתָּא קוּדְשָׁא בְּרִיךְ הוּא אִזְדַּעְזָע, תְּלָת מְאָה וְתִשְׁעִין רְקִיעִין, וּבָטַשׁ בְּהוּ, וּבָכָה עַל חָרְבַּן בֵּי מַקְדְּשָׁא, וְאוֹרִיד תְּרֵין (י\"ט ע\"ב) דִּמְעִין לְגוֹ יַמָּא רַבָּא, וְאַדְכַּר לִבְנוֹהִי מִגּוֹ בִּכְיָה.","בְּגִין דְּלִתְלַת סִטְרִין אִתְפְּלַג לֵילְיָא, בִּתְרֵיסַר שַׁעְתֵּי דַּהֲווֹ רְשִׁימִין בֵּיהּ, וְאִי אִתּוֹסְפָן שַׁעְתֵּי בְּלֵילְיָא, אִינּוּן שַׁעְתֵּי דְּמִתּוֹסְפָאן, דִּימָמָא אִינּוּן, וְלָא אִתְחַשִׁיבוּ מִלֵילְיָא, בַּר תְּרֵיסַר דְּאִינּוּן דִּילֵהּ. וְאִינּוּן תְּרֵיסַר, אִתְפְּלָגוּ לִתְלַת סִטְרִין, (זהר רות כ\"ו ע\"א) וּתְלַת מַשִׁרְיָין דְּמַלְאָכִין קַדִּישִׁין, אִתְפְּלָגוּ (ס\"א אתמנון) בְּאִינּוּן תְּלַת סִטְרִין.","מַשִּׁרְיָיא קַדְמָאָה, אִתְמַנָּא בְּד' שַׁעְתֵּי קָמַיְיתָא, דְּשֵׁירוּתָא דְּלֵילְיָא, לְשַׁבְּחָא לְמָארֵיהוֹן, וּמָה קָאַמְרֵי. (תהילים כ״ד:ג׳) לַיְיָ' הָאָרֶץ וּמְלֹאָהּ וְגוֹ', כִּי הוּא עַל יַמִים יְסָדָהּ וְגוֹ', מִי יַעֲלֶה בְהַר יְיָ' וְגוֹ', נְקִי כַפַּיִם וּבַר לֵבָב וְגוֹ'. מַאי טַעְמָא דָּא. בְּגִין דְּכַד לֵילְיָא פָּרִישׂ גַּדְפּוֹי עַל עָלְמָא, כְּדֵין, כָּל בְּנֵי עָלְמָא טַעֲמִין טַעֲמָא דְּמוֹתָא, וְנַפְקֵי נִשְׁמָתַיְיהוּ לְסַלְּקָא לְעֵילָּא, וְאִינּוּן מַלְאָכִין קַיְימִין וְקָא אַמְרֵי, מִי יַעֲלֶה בְהַר יְיָ'. הַר יְיָ', דָּא הַר הַבַּיִת. מְקוֹם קָדְשׁוֹ, דָּא עֲזָרַת יִשְׂרָאֵל. כְּגַוְונָא דִּלְעֵילָּא, הָכִי נָמֵי לְתַתָּא.","בְּגִין דִּבְכָל רְקִיעָא וּרְקִיעָא, כַּמָּה מְמָנָן, וּכְמָּה סַרְכִין קַיְימִין תַּמָּן. וְכַד נִשְׁמָתִין נָפְקִין, בָּעָאן לְסַלְּקָא לְעֵילָּא, וְאִי לָא זַכְיָין אִינּוּן דַּחְיָין לוֹן לְבַר, וְאַזְלִין וְשָׁאטִין בְּעָלְמָא, וְנַטְלִין לוֹן כַּמָה חֲבִילֵי טְהִירִין, וְאוֹדְעִין לוֹן מִלִּין כְּדִיבָן, וּלְזִמְנִין מִלִּין דִּקְשׁוֹט, מִמַּה דְּאָתֵי לִזְמַן (רנ\"ב ע\"ב) קָרִיב, כְּמָה דְּאוּקְמוּהָ.","וְאִינּוּן נִשְׁמָתִין דְּצַדִּיקַיָּיא, אָזְלִין וְשָׁאטָן לְעֵילָּא, וּפַתְחִין לוֹן פִּתְחִין, וְסַלְּקִין לוֹן לְגוֹ הַהוּא אֲתָר דְּאִקְרֵי הַר יְיָ', כְּגַוְונָא דְּרָזָא דְּהַר הַבַּיִת לְתַתָּא. וּמִתַּמָּן עָאלִין לְגוֹ הַהוּא אֲתָר דְּאִקְרֵי מְקוֹם קָדְשׁוֹ. דְּתַמָּן אִתְחַזְיָין כָּל נִשְׁמָתִין לְקָמֵי מָארֵיהוֹן. כְּגַוְונָא דָּא הַהוּא אֲתָר, דְּאִתְחָזוּן יִשְׂרָאֵל קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, אֲתָר דְּאִקְרֵי עֲזָרַת יִשְׂרָאֵל. בְּשַׁעֲתָא דְּנִשְׁמָתִין קַיְימִין תַּמָּן, כְּדֵין חֶדְוָה דְּמָארִיהוֹן, לְאִתְתָּקְנָא בְּהוּ אֲתָר, דְּאִקְרֵי קֹדֶשׁ (רנ\"ח ע\"ב) הַקָּדָשִׁים. וְתַמָּן רְשִׁימִין כָּל עוֹבָדֵיהוֹן וְזַכְוָון דִּלְהוֹן.","מַשִּׁרְיָיא תִּנְיָינָא, אִתְמַנָּא בְּאַרְבַּע שַׁעְתֵּי אַחֲרָנִין, וְלָא אַמְרֵי שִׁירָתָא, בַּר תְּרֵי שַׁעְתֵּי, עַד דְּאִתְפְּלַג לֵילְיָא, וְעָאל קוּדְשָׁא בְּרִיךְ הוּא בְּגִנְתָּא דְּעֵדֶן.","וְאִלֵּין אִינּוּן אֲבֵלֵי צִיּוֹן, וְאִינּוּן דְּבָכוּ עַל חָרְבַּן בֵּי מַקְדְּשָׁא. וּבְשֵׁירוּתָא דְּאַרְבַּע שַׁעְתֵּי אֶמְצָעֲיָּן, פַּתְחֵי וְאַמְרֵי, (תהילים קל״ז:א׳) עַל נַהֲרוֹת בָּבֶל שָׁם יָשַׁבְנוּ גַּם בָּכִינוּ וְגוֹ', וְאִלֵּין אִינּוּן דְּבָכוּ עַל נַהֲרוֹת בָּבֶל, עִמְּהוֹן דְּיִשְׂרָאֵל, מִמַּשְׁמַע דִּכְתִּיב גַּם בָּכִינוּ. וּמְנָלָן דְּבָכוּ תַּמָּן. דִּכְתִּיב, (ישעיהו ל״ג:ז׳) הֵן אֶרְאֶלָּם צָעֲקוּ חוּצָה. מַהוּ חוּצָה. דָּא בָּבֶל, בְּגִין דְּכֻלְּהוּ אוֹזְפוּהָ לִשְׁכִינָה עַד בָּבֶל. וְתַמָּן בָּכוּ עִמְּהוֹן דְּיִשְׂרָאֵל. וְעַל דָּא פַּתְחֵי בְּהַאי, וּמְסַיְּימֵי זְכוֹר יְיָ' לִבְנִי אֱדוֹם וְגוֹ'."],[[0,"ת\"ח בד' תקופין וכו':","בוא וראה, בד' תקופות השנה, שהם חו\"ג תו\"מ, מתעורר קול בד' רוחות העולם. שתקופת ניסן הוא דרום וחסד. ותקופת תשרי, צפון וגבורה. ותקופת תמוז, מזרח ות\"ת. ותקופת טבת, מערב ומלכות. וכל אחת כלולה מכולם. בקול ההוא, מתעורר בו התעוררות של הסטרא אחרא. והתעוררות ההוא של הס\"א, נכנס בין קול לקול, דהיינו בין קול דת\"ת לקול דמלכות. ונחשך האור בקול שלמטה, דהיינו במלכות. ומשום שאינו מגיע האור של קול שלמעלה מת\"ת, אל הקול שלמטה, למלכות, ע\"כ מקדים התעוררות ההיא, של הס\"א, והנחש שפיתה האשה, חוה, נכנס בין זה לזה, בין ת\"ת למלכות, ולוקח אור. וקול ההוא של הס\"א, הוא קול מלחמה. קול רעה. וזה הוא \u0003ברעה.\u0004 דהיינו מ\"ש, וישמע יהושע את קול העם \u0003ברעה.\u0004"],[1,"וע\"ד שמע יהושע וכו':","וע\"כ שמע יהושע, ולא משה. משום ש \u0003רעה\u0004 הזה לקח אור הלבנה, שהיא המלכות, שיהושע היה נאחז בה. ומשה שהיה נאחז בשמש, שהוא ז\"א, לא שמע. וכל ישראל, נחשך האור שלהם, משום \u0003רעה\u0004 ההיא שנתדבקה בהם. כיון שמחל הקב\"ה עונם, אז, ויקהל משה את כל עדת בני ישראל ויאמר אליהם אלה הדברים וגו'. כי ערב רב ההוא נעבר מהם."],[2,"ר' אלעזר ור' יוסי וכו':","ר\"א ור\"י היו יושבים לילה אחד ועוסקים בתורה, מטרם שנחלק הלילה. בתוך כך קרא התרנגול. דהיינו שהגיע חצות לילה. ברכו הברכה, אשר נתן לשכוי בינה וכו'. בכה ר\"א ואמר, בוא וראה, עד עתה הקב\"ה הזדעזע שלש מאה ותשעים רקיעים והכה בהם, והוריד ב' דמעות לתוך ים הגדול, ונזכר בבניו מתוך בכיה. (ועי' הפירוש בהקסה\"ז באות נ\"ו בהסולם)."],[3,"בגין דלתלת סטרין וכו':","משום שלג' צדדים ימין שמאל אמצע, נחלק הלילה בי\"ב שעות הרשומות בו. ואם יש שעות נוספות בלילה, יותר מי\"ב שעות, הם נחשבים של יום, ואינם מלילה, כי רק י\"ב שעות הן שלה. של המלכות הנקראת לילה. ואלו י\"ב שעות נחלקות לג' צדדים. וג' מחנות מלאכים קדושים נחלקים באלו ג' צדדים."],[3,"","סוד י\"ב שעות הלילה כבר נתבאר באורך (ויגש ח' ד\"ה וזה, ע\"ש) כי ד' ספירות הם חו\"ג תו\"מ, ואינם כלולים כל אחת מחו\"ג תו\"מ שיהיה ט\"ז בחינות, משום שהמלכות נעלמה בסוד אלכסון, אלא שכלולים כל אחת רק מחג\"ת, ואינם רק י\"ב בחינות, כי ד\"פ ג' הם י\"ב. ונמצא שעיקר ההארה רק חג\"ת, שה\"ס ג' קוין, אבל הם מאירים בכל אחד מחו\"ג תו\"מ, ואפילו במלכות. עש\"ה. ונמצא שהלילה נחלקת לד' חלקים חו\"ג תו\"מ שבכל חלק יש ג' קוין חג\"ת, וב' ספירות חו\"ג, הם בחצי לילה הראשון, והם ששה, כי בכל אחת ג' קוין. וב' ספירות ת\"ת ומלכות, הם בחצי הלילה השני, הן שש שעות, כי כל אחת כלולה מג' קוין חג\"ת."],[3,"","אמנם הלילה, מבחינת שירת המלאכים, אינו נחלק לד' משמורות שהם חו\"ג תו\"מ, אלא לג' משמורות. והוא מטעם כי המלאכים האומרים שירה בג' משמורות, הם הממשיכים בזה הארת החכמה המאירה בלילה, בסו\"ה ותקם בעוד לילה. ופעולה זו של הארת החכמה אינו נוהג רק בג' קוין בלבד, ולא במלכות, כי המלכות רק מקבלת הארתם ומגלה אותם. אבל אינה פועלת כלום. וע\"כ אין משמורה מבחינתה, שתאמר שירה. וע\"כ נחלק הלילה מבחינה זו רק לג' קוין, שבכל קו חו\"ג תו\"מ, והם י\"ב שעות הלילה מבחינה זו. ונתבאר שמבחינת מציאות הלילה, שהיא פרצוף המלכות, יש בה ד' ספירות חו\"ג תו\"מ. ונחלק על נקודת החצות דהיינו בעת שמתחיל ספירת הת\"ת להאיר, שהוא קו האמצעי. שז\"ס שהקב\"ה נכנס לג\"ע, שהוא קו האמצעי הנכנס למלכות הנקראת ג\"ע. אבל מבחינת האומרים שירה, נחלק הלילה לפי ג' קוין, שבכל קו חו\"ג תו\"מ. משום שהמלכות דמלכות, אינה פועלת, ולא שייך שירה מבחינתה."],[4,"משרייא קדמאה אתמנא וכו':","מחנה הראשונה נתמנה בד' שעות ראשונות של תחילת הלילה לשבח אדונם. דהיינו בקו ימין, שהוא חסד. ומה אומרים. הם אומרים לה' הארץ ומלואה וגו', כי הוא על ימים יסדה וגו', מי יעלה בהר ה' וגו', נקי כפים ובר לבב וגו'. מה הטעם שאומרים זה. הוא משום כשהלילה פורש כנפיו על העולם, אז כל בני העולם טועמים טעם המות, ונשמותיהם יוצאות לעלות למעלה. ואלו המלאכים, עומדים ואומרים, על הנשמות, מי יעלה בהר ה'. \u0003הר ה',\u0004 זהו הר הבית, \u0003מקום קדשו,\u0004 זהו עזרת ישראל. כעין שיש בבית המקדש של מעלה, שהוא המלכות כך יש בבית המקדש למטה. פירוש. כל מה שיש בבית המקדש של מטה, הר הבית, ועזרת ישראל, וקדש הקדשים וכו' הם נמשכים מן הצורות שיש בבית המקדש של מעלה, וכשאנו מסתכלים למטה אנו יודעים מה שיש למעלה. דהיינו שיש גם שם, הר הבית ועזרת ישראל וקדש הקדשים, הנקראים הר ה'. מקום קדשו. וקדש הקדשים כמ\"ש והולך."],[5,"בגין דבכל רקיעא וכו':","משום שבכל רקיע ורקיע כמה ממונים וכמה שוטרים עומדים שם. וכשהנשמות יוצאות, רוצות לעלות למעלה, ואם אינן זוכות, הם דוחים אותן לחוץ, והולכות ומשוטטות בעולם. ולוקחים אותן כמה גדודי רוחות, ומודיעים להם דברי שקר, ולפעמים דברי אמת ממה שיבא בזמן קצר, כמו שהעמידו."],[6,"ואינון נשמתין דצדיקיא וכו':","ואלו נשמות הצדיקים, הולכות ומשוטטות למעלה, ופותחים להן פתחים, ועולות למקום ההוא שנקרא \u0003הר ה',\u0004 שהוא כעין סוד הר הבית למטה. ומשם עולות למקום ההוא שנקרא מקום קדשו. ששם נראות כל הנשמות לפני אדונם. שהוא כעין מקום ההוא למטה, שנראים שם ישראל לפני הקב\"ה, שהוא המקום שנקרא עזרת ישראל. בשעה שהנשמות עומדות שם, אז שמחת רבונם הוא לתקן בהן מקום, הנקרא קדש הקדשים. ושם רשומים כל מעשיהם וזכיותיהם."],[7,"משרייא תניינא אתמנא וכו':","מחנה השניה נתמנה לומר שירה, בארבע שעות השניות, ואינם אומרים שירה רק שתי שעות, עד שנחלק הלילה. והקב\"ה, שהוא קו האמצעי, נכנס בגן עדן."],[7,"","פירוש. כי מחנה מלאכים השניה, ה\"ס הנמשכים מקו שמאל, כי משמרה השניה היא קו שמאל, (כנ\"ל אות ט\"ו) והיו צריכים לומר שירה עד תחילת ארבעה שעות השלישיות. אמנם כיון שמבחינת מציאות המלכות נחלק הלילה על ד' חלקים חו\"ג תו\"מ, שבכל אחת ג' שעות, ונמצא שבנקודת חצות הלילה, נסתיימה ספירת הגבורה שהיא קו השמאל ומתחלת ספירת הת\"ת שהוא קו האמצעי, לפיכך הוכרחו המלאכים שמקו שמאל להפסיק שירתם, כי כבר התחיל שליטת קו האמצעי מבחינת מציאות הלילה, כמו שנתבאר היטב לעיל (באות ט\"ו) וז\"ש, \u0003ולא אמרי שירתא בר תרי שעתי עד דאתפלג ליליא,\u0004 שמוכרחים להפסיק שירתם בנקודת החצות, משום שאז, \u0003ועאל קב\"ה,\u0004 שהוא קו האמצעי, בגנתא דעדן, שהוא המלכות. וכבר עברו זמנם, של הנמשכים מקו שמאל, מלומר שירה."],[8,"ואלין אינון אבלי וכו':","ואלו המלאכים, של משמרה השניה, הם לאחר חורבן הבית, אבלי ציון. שהם הבוכים על חורבן בית המקדש. ובתחילת ארבע שעות האמצעיות, שהם בחינת קו השמאל, שבו נאחז בעיקר הס\"א, פותחים ואומרים, על נהרות בבל שם ישבנו גם בכינו וגו'. ואלו הם שבוכים על נהרות בבל, עם ישראל. שזה משמע משכתוב, \u0003גם\u0004 בכינו. שהמשמעות של \u0003גם\u0004 הוא, ש \u0003גם\u0004 אנו בכינו כמו המלאכים. ומאין לנו שבכו שם. הוא, שכתוב, הן אראלם צעקו חוצה. מהו \u0003חוצה.\u0004 זהו בבל. משום שכל המלאכים ליוו השכינה עד בבל, ושם בכו עם ישראל. וע\"כ פתחו בזה, בעל נהרות בבל, וגמרו, זכור ה' לבני אדום וגו'."]],[[0,"","בֹּא וּרְאֵה, בְּאַרְבַּע תְּקוּפוֹת בַּשָּׁנָה מִתְעוֹרֵר קוֹל בְּאַרְבַּעַת צִדְדֵי הָעוֹלָם, בְּאוֹתוֹ קוֹל שֶׁהִתְעוֹרְרוּת הַצַּד הָאַחֵר מִתְעוֹרֵר בּוֹ, וְאוֹתָהּ הִתְעוֹרְרוּת הַצַּד הָאַחֵר נִכְנֶסֶת בֵּין קוֹל לְקוֹל, וְנֶחְשָׁךְ הָאוֹר בַּקּוֹל שֶׁלְּמַטָּה. מִשּׁוּם שֶׁלֹּא הִגִּיעַ הָאוֹר שֶׁל הַקּוֹל שֶׁלְּמַעְלָה לַקּוֹל שֶׁלְּמַטָּה, אָז מַקְדִּימָה אוֹתָהּ הִתְעוֹרְרוּת, וְנִכְנָס בֵּין זֶה לָזֶה הַנָּחָשׁ שֶׁמְּפַתֶּה אֶת הָאִשָּׁה וְנוֹטֵל אוֹר, וְאוֹתוֹ קוֹל הוּא קוֹל מִלְחָמָה, קוֹל רָעָה, וְזֶהוּ בְּרֵעֹה."],[1,"","וְעַל זֶה שָׁמַע יְהוֹשֻׁעַ וְלֹא מֹשֶׁה, מִשּׁוּם שֶׁנָּטְלָה אוֹתָהּ רָעָה אֶת אוֹר הַלְּבָנָה שֶׁאָחַז בָּהּ יְהוֹשֻׁעַ, וּמֹשֶׁה שֶׁהָיָה אָחוּז בַּשֶּׁמֶשׁ לֹא שָׁמַע, וְכָל הָאוֹר שֶׁל יִשְׂרָאֵל כֻּלָּם נֶחְשַׁךְ מִשּׁוּם אוֹתָהּ רָעָה שֶׁנִּדְבְּקָה בָּהֶם. כֵּיוָן שֶׁמָּחַל הַקָּדוֹשׁ בָּרוּךְ הוּא עַל חֲטָאֵיהֶם, אָז וַיַּקְהֵל מֹשֶׁה אֶת כָּל עֲדַת בְּנֵי יִשְׂרָאֵל וַיֹּאמֶר אֲלֵהֶם אֵלֶּה הַדְּבָרִים וְגוֹ', שֶׁהֲרֵי אוֹתוֹ עֵרֶב רַב הָעֳבַר מֵהֶם."],[2,"","רַבִּי אֶלְעָזָר וְרַבִּי יוֹסֵי הָיוּ יוֹשְׁבִים לַיְלָה אֶחָד וּמִתְעַסְּקִים בַּתּוֹרָה טֶרֶם שֶׁנֶּחֱלַק הַלַּיְלָה. בֵּין כָּךְ קָרָא הַגֶּבֶר. בֵּרְכוּ בְרָכָה. (אמר לו רבי אלעזר, כעת הוא הזמן שהקדוש ברוך הוא נכנס בגן עדן להשתעשע עם הצדיקים. אמר לו רבי יוסי, למה משתעשע הקדוש ברוך הוא) בָּכָה רַבִּי אֶלְעָזָר וְאָמַר, בּא וּרְאֵה, עַד כָּאן זִעְזַע הַקָּדוֹשׁ בָּרוּךְ הוּא שְׁלֹשׁ מֵאוֹת וְתִשְׁעִים רְקִיעִים וְהִכָּה בָּהֶם, וּבָכָה עַל חָרְבַּן בֵּית הַמִּקְדָּשׁ, וְהוֹרִיד שְׁתֵּי דְמָעוֹת לְתוֹךְ הַיָּם הַגָּדוֹל וְנִזְכַּר בְּבָנָיו מִתּוֹךְ בְּכִיָּה."],[3,"","מִשּׁוּם שֶׁהַלַּיְלָה נֶחֱלָק לִשְׁלֹשָׁה צְדָדִים בִּשְׁתֵּים עֶשְׂרֵה שָׁעוֹת שֶׁהָיוּ רְשׁוּמִים בּוֹ, וְאִם נוֹסָפוֹת שְׁעוֹת הַלַּיְלָה, אוֹתָן שָׁעוֹת שֶׁנּוֹסְפוּ הֵן שֶׁל הַיּוֹם, וְלֹא נֶחֱשָׁבוֹת מֵהַלַּיְלָה, פְּרָט לִשְׁתֵּים עֶשְׂרֵה שֶׁהֵן שֶׁלּוֹ. וְאוֹתָן שְׁתֵּים עֶשְׂרֵה נֶחֱלָקוֹת לִשְׁלֹשָׁה צְדָדִים, וּשְׁלֹשָׁה מַחֲנוֹת שֶׁל מַלְאָכִים קְדוֹשִׁים נֶחְלְקוּ (התמגו) בְּאוֹתָם שְׁלֹשָׁה צְדָדִים."],[4,"","מַחֲנֶה רִאשׁוֹן מְמֻנֶּה בְּאַרְבַּע שָׁעוֹת רִאשׁוֹנוֹת שֶׁל רֵאשִׁית הַלַּיְלָה לְשַׁבֵּחַ אֶת אֲדוֹנָם. וּמַה הֵם אוֹמְרִים? (תהלים כד) לַה' הָאָרֶץ וּמְלֹאָהּ וְגוֹ', כִּי הוּא עַל יַמִּים יְסָדָהּ וְגוֹ', מִי יַעֲלֶה בְהַר ה' וְגוֹ', נְקִי כַפַּיִם וּבַר לֵבָב וְגוֹ'. מָה הַטַּעַם שֶׁל זֶה? מִשּׁוּם שֶׁכַּאֲשֶׁר הַלַּיְלָה פּוֹרֵשׂ כְּנָפָיו עַל הָעוֹלָם, אָז כָּל בְּנֵי הָעוֹלָם טוֹעֲמִים טַעַם הַמָּוֶת וְיוֹצֵאת נִשְׁמָתָם לַעֲלוֹת לְמַעְלָה, וְאוֹתָם מַלְאָכִים עוֹמְדִים וְאוֹמְרִים, מִי יַעֲלֶה בְהַר ה'. הַר ה' - זֶה הַר הַבַּיִת. מְקוֹם קָדְשׁוֹ - זֶה עֶזְרַת יִשְׂרָאֵל. כְּמוֹ שֶׁלְּמַעְלָה, כָּךְ גַּם לְמַטָּה."],[5,"","מִשּׁוּם שֶׁבְּכָל רָקִיעַ וְרָקִיעַ כַּמָּה מְמֻנִּים וְכַמָּה שָׂרִים עוֹמְדִים שָׁם, וּכְשֶׁהַנְּשָׁמוֹת יוֹצְאוֹת, רוֹצוֹת לַעֲלוֹת לְמַעְלָה, וְאִם אֵינָן זוֹכוֹת דּוֹחִים אוֹתָן הַחוּצָה, וְהוֹלְכוֹת וּמְשׁוֹטְטוֹת בָּעוֹלָם, וְלוֹקְחִים אוֹתָן כַּמָּה קְבוּצוֹת שֶׁל רוּחוֹת וּמוֹדִיעִים לָהֶם דְּבָרִים כּוֹזְבִים, וְלִפְעָמִים דִּבְרֵי אֱמֶת מִמַּה שֶּׁעָתִיד לָבא בַּזְּמַן הַקָּרוֹב, כְּמוֹ שֶׁבֵּאֲרוּהָ."],[6,"","וְאוֹתָן נִשְׁמוֹת הַצַּדִּיקִים הוֹלְכוֹת וּמְשׁוֹטְטוֹת לְמַעְלָה, וּפוֹתְחִים לָהֶם פְּתָחִים, וּמַעֲלִים אוֹתָן לְתוֹךְ אוֹתוֹ מָקוֹם שֶׁנִּקְרָא הַר ה', כְּמוֹ הַסּוֹד שֶׁל הַר הַבַּיִת לְמַטָּה, וּמִשָּׁם נִכְנָסִים לְתוֹךְ אוֹתוֹ מָקוֹם שֶׁנִּקְרָא מְקוֹם קָדְשׁוֹ, שֶׁשָּׁם נִרְאוֹת כָּל הַנְּשָׁמוֹת לִפְנֵי אֲדוֹנָם. כְּמוֹ כֵן אוֹתוֹ מָקוֹם שֶׁנִּרְאוּ יִשְׂרָאֵל לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, הַמָּקוֹם שֶׁנִּקְרָא עֶזְרַת יִשְׂרָאֵל. בְּשָׁעָה שֶׁהַנְּשָׁמוֹת עוֹמְדוֹת שָׁם, אֲזַי שִׂמְחַת רִבּוֹנָם הִיא, לְתַקֵּן בָּהֶם הַמָּקוֹם שֶׁנִּקְרָא קֹדֶשׁ הַקְּדָשִׁים, וְשָׁם רוֹשְׁמִים אֶת כָּל מַעֲשֵׂיהֶם וּזְכֻיּוֹתֵיהֶם."],[7,"","מַחֲנֶה שֵׁנִי מְמֻנֶּה בְּאַרְבַּע שָׁעוֹת אֲחֵרוֹת, וְאֵינָם אוֹמְרִים שִׁירָה, פְּרָט לִשְׁעָתַיִם, עַד שֶׁנֶּחֱלָק הַלַּיְלָה וְנִכְנָס הַקָּדוֹשׁ בָּרוּךְ הוּא לְגַן עֵדֶן."],[8,"","וְאֵלֶּה הֵם אֲבֵלֵי צִיּוֹן וְאוֹתָם שֶׁבּוֹכִים עַל חֻרְבַּן בֵּית הַמִּקְדָּשׁ. וּבִתְחִלַּת אַרְבַּע הַשָּׁעוֹת הָאֶמְצָעִיּוֹת פּוֹתְחִים וְאוֹמְרִים, (תהלים קלז) עַל נַהֲרוֹת בָּבֶל שָׁם יָשַׁבְנוּ גַּם בָּכִינוּ וְגוֹ', וְאֵלֶּה הֵם שֶׁבּוֹכִים עַל נַהֲרוֹת בָּבֶל עִם יִשְׂרָאֵל, מִמַּשְׁמָע שֶׁכָּתוּב גַּם בָּכִינוּ. וּמִנַּיִן לָנוּ שֶׁבּוֹכִים שָׁם? שֶׁכָּתוּב הֵן אֶרְאֶלָּם צָעֲקוּ חֻצָה. מַה זֶּה חֻצָה? זוֹ בָּבֶל, מִשּׁוּם שֶׁכֻּלָּם לִוּוּ אֶת הַשְּׁכִינָה עַד בָּבֶל, וְשָׁם הֵם בָּכוּ עִם יִשְׂרָאֵל. וְעַל זֶה פּוֹתְחִים בָּזֶה, וּמְסַיְּמִים: זְכֹר ה' לִבְנֵי אֱדוֹם וְגוֹ'."]]],[["כְּדֵין אִתְּעַר קוּדְשָׁא בְּרִיךְ הוּא בְּדַרְגּוֹי, וּבָטַשׁ בִּרְקִיעִין כִּדְאַמָרָן, וְאִזְדַּעֲזָעוּ תְּרֵיסַר אַלְפֵי עָלְמִין, וְגָעֵי וּבָכֵי, דִּכְתִּיב, (ירמיהו כ״ה:ל׳) יְיָ' מִמָּרוֹם יִשְׁאָג וּמִמְּעוֹן קָדְשׁוֹ יִתֵּן קוֹלוֹ שָׁאוֹג יִשְׁאַג עַל נָוִהוּ, וְאַדְכַּר לוֹן לְיִשְׂרָאֵל, וְאָחִית תְּרֵין דִּמְעִין לְגוֹ יַמָּא רַבָּא. וּכְדֵין אִתְּעַר שַׁלְהוֹבִיתָא חַד דְּבִסְטַר צָפוֹן, וּבָטַשׁ רוּחָא חַד דְּבִסְטַר צָפוֹן בְּהַהוּא שַׁלְהוֹבִיתָא, וְאַזְלָא וְשָׁאֲטָא בְּעָלְמָא, וְהַהִיא שַׁעֲתָא אִתְפְּלַג לֵילְיָא, וְשַׁלְהוֹבִיתָא אַזְלָא וּבָטַשׁ בְּגַדְפוֹי דְּתַרְנְגוֹלָא, וְקָארֵי, כְּדֵין קוּדְשָׁא בְּרִיךְ הוּא עָאל בְּגִּנְתָּא דְּעֵדֶן.","וְקוּדְשָׁא בְּרִיךְ הוּא לֵית לֵיהּ נַיְיחָא עַד דְּעָאל לְגִנְתָּא דְּעֵדֶן לְאִשְׁתַּעְשְׁעָא בְּנִשְׁמָתֵהוֹן דְּצַדִּיקַיָּיא. וְסִימָן (אסתר ז׳:ד׳) כִּי נִמְכַּרְנוּ אֲנִי וְעַמִּי וְגוֹ'. וַיֹּאמֶר הַמֶּלֶךְ מִי הוּא זֶה וְגוֹ', וְהַמֶּלֶךְ קָם בַּחֲמָתוֹ מִמִּשְׁתֵּה הַיַּיִן אֶל גִּנַּת הַבִּיתָן וְגוֹ'.","בְּשַׁעֲתָא דְּקוּדְשָׁא בְּרִיךְ הוּא עָאל בְּגִּנְתָּא דְּעֵדֶן, כְּדֵין כָּל אִינּוּן אִילָנִין דְּגִּנְתָּא, וְכָל אִינּוּן נִשְׁמָתִין דְּצַדִּיקַיָּיא, פַּתְחֵי וְאַמְרֵי, (תהילים כ״ד:ז׳) שְׂאוּ שְׁעָרִים רָאשֵׁיכֶם וְגוֹ'. מִי זֶה מֶלֶךְ הַכָּבוֹד וְגוֹ'. שְׂאוּ שְׁעָרִים רָאשֵׁיכֶם וְגוֹ'. וּבְשַׁעֲתָא דְּנִשְׁמָתְהוֹן דְּצַדִּיקַיָּיא דִּי בְּאַרְעָא אָהַדְרוּ לְגוּפַיְיהוּ, כְּדֵין אַתְקִיפוּ בְּהוּ כָּל אִינּוּן מַלְאָכִין, וְאַמְרֵי (תהילים קל״ד:א׳) הִנֵּה בָּרְכוּ אֶת יְיָ' כָּל עַבְדֵּי יְיָ'. וְאוֹלִיפְנָא דְּדָא מַשִּׁרְיָיא תְּלִיתָאָה קָא אַמְרֵי דָּא, בְּאַרְבַּע שַׁעְתֵּי בַּתְרַיְיתָא.","וְקָאֲמְרֵי שִׁירָתָא, עַד דְּסָלִיק נְהוֹרָא דְּצַפְרָא, דִּכְדֵין מְשַׁבְּחִין לְמָרֵיהוֹן כָּל אִינּוּן כֹּכָבַיָא וּמַזָּלֵי, וְכָל אִינּוּן מַלְאָכִין עִלָּאִין, דִּי שֻׁלְטָנֵיהוֹן בִּימָמָא, כֻּלְּהוּ מְשַׁבְּחָן לְמָארִיהוֹן, וְאַמְרֵי שִׁירָתָא. הֲדָא הוּא דִכְתִיב, (איוב ל״ח:ז׳) בְּרָן יַחַד כֹּכְבֵי בֹקֶר וַיָּרִיעוּ כָּל בְּנֵי אֱלֹהִים.","בְּשַׁעֲתָא דְּשִׁמְשָׁא נָפִיק, בִּימָמָא, יִשְׂרָאֵל נַטְלֵי שִׁירָתָא לְתַתָּא, וְשִׁמְשָׁא לְעֵילָּא, דִּכְתִּיב, (תהילים ע״ב:ה׳) יִירָאוּךָ עִם שָׁמֶשׁ. בְּשַׁעֲתָא דְּנָטִיל שִׁמְשָׁא בְּגַלְגְלוֹי, פָּתַח קַל נְעִימוּתָא, וְאָמַר שִׁירָתָא. וּמַאי שִׁירָתָא קָאַמְרֵי. (תהילים ק״ה:א׳) הוֹדוּ לַיְיָ' קִרְאוּ בִשְׁמוֹ וְגוֹ'. (תהילים ק״ה:א׳) שִׁירוּ לוֹ זַמְּרוּ לוֹ וְגוֹ'. וְיִשְׂרָאֵל מְשַׁבְּחָן לְקוּדְשָׁא בְּרִיךְ הוּא בִּימָמָא, עִם שִׁמְשָׁא. הֲדָא הוּא דִכְתִיב יִירָאוּךָ עִם שָׁמֶשׁ, וְאַף עַל גַּב דְּהָא אוֹקִימְנָא לְהַאי קְרָא, אָמַר רִבִּי אֶלְעָזָר, אִלְמָלֵא דִּבְנֵי עָלְמָא אֲטִימִין לִבָּא וּסְתִימִין עַיְינִין לָא יַכְלִין לְמֵיקָם מִקָּל נְעִימוּתָא דְּגַלְגָלָא דְּשִׁמְשָׁא, כַּד נָטִיל (ונפיק) וּמְשַׁבַּח קָמֵי קוּדְשָׁא בְּרִיךְ הוּא.","אַדְּהָכִי דְּאִתְעַסְּקוּ בְּאוֹרַיְיתָא, נָהַר יְמָמָא. קָמוּ וְאָתוּ לְקָמֵיהּ דְּרַבִּי שִׁמְעוֹן, כֵּיוָן דְּחָמָא לוֹן, אָמַר רַבִּי שִׁמְעוֹן, אֶלְעָזָר בְּרִי, אַנְתְּ וְחַבְרַיָּיא אַסְתִּימוּ גַּרְמַיְיכוּ אִלֵּין תְּלַת יוֹמִין, דְּלָא תִּפְקוּן לְבַר בְּגִין דְּמַלְאָךְ הַמָּוֶת אִשְׁתְּכַח בְּמָתָא, וְאִית לֵיהּ רְשׁוּ לְחַבְּלָא, וְכֵיוָן דְּאִתְיְיהִיב לֵיהּ רְשׁוּ לְחַבְּלָא, יָכִיל לְחַבְּלָא, לְכָל מַאן דְּאִתְחָזֵי קַמֵיהּ.","וְתוּ דְּבַר נָשׁ דְּאִתְחָזֵי קַמֵּיהּ, סָלִיק וְאַסְטֵי עָלֵיהּ, וְאַדְכַּר חוֹבוֹי, וּבָעֵי דִּינָא מִקַּמֵּי קוּדְשָׁא בְּרִיךְ הוּא, וְלָא אִתְעָדֵי מִתַּמָּן, עַד דְּאִתְּדָּן הַהוּא בַּר נָשׁ, וְאִתְיְיהִיב לֵיהּ רְשׁוּ וְקָטִיל לֵיהּ.","אָמַר רַבִּי שִׁמְעוֹן, הָאֱלהִים, רוּבָּא דְּעָלְמָא, לָא מִיתוּ, עַד לָא מָטָא זִמְנַיְיהוּ, בַּר דְּלָא יַדְעֵי לְאִסְתַּמְּרָא גַּרְמַיְיהוּ, דְּהָא בְּשַׁעֲתָא דְּמִיתָא אַפְקֵי לֵיהּ מִבֵּיתֵיהּ לְבֵי קִבְרֵי, מַלְאָךְ הַמָּוֶת אִשְׁתְּכַח בֵּינֵי נְשֵׁי, אֲמַאי בֵּינֵי נְשֵׁי. דְּהָכִי (רכ\"ז ע\"א) הוּא אוֹרְחוֹי, מִיּוֹמָא דְּפַתֵּי לְחַוָּה, וּבְגִינָהּ גָּרִים מוֹתָא לְכָל עָלְמָא. וְעַל דָּא (כד) קָטִיל בַּר נָשׁ, וְגוּבְרֵי אִשְׁתְּכָחוּ עִם מִיתָא, עָאל בֵּינֵי נְשֵׁי בְּאָרְחָא.","וְאִית לֵיהּ רְשׁוּ, לְמִקְטַל בְּנֵי נָשָׁא, וְאִסְתָּכַּל בְּאַנְפַּיְיהוּ בְּאָרְחָא דְּאִתְחֲזִיאוּ קַמֵּיהּ, מִשַׁעֲתָא דְּמָפְקֵי לֵיהּ מִבֵּיתֵיהּ לְבֵי קִבְרֵי, עַד דְּאָהַדְרוּ לְבֵיתַיְּיהוּ וּבְגִינֵיהוֹן גָּרִים מוֹתָא לְכַמָּה גּוּבְרִין בְּעָלְמָא, עַד לָא מָטָא זִמְנַיְיהוּ. וְעַל דָּא כְּתִיב, (משלי י״ג:כ״ג) וְיֵשׁ נִסְפֶּה בְּלא מִשְׁפָּט. בְּגִין דְּסָלִיק וְאַסְטִין, וְאַדְכַּר חוֹבוֹי דְּבַר נָשׁ קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, וְאִתְדַן עַל אִינּוּן חוֹבִין וְאִסְתַּלָּק עַד לָא מָטָא זִמְנֵיהּ."],[[0,"כדין אתער קב\"ה וכו':","אז נתעורר הקב\"ה במדרגותיו, ומכה ברקיעים, ומזדעזעים י\"ב אלפים עולמות, ושואג ובוכה. שכתוב, ה' ממרום ישאג וממעון קדשו יתן קולו שאג ישאג על נוהו. וזוכר את ישראל, שהם בגלות, ומוריד ב' דמעות לים הגדול. ואז נתעורר שלהבת אחת שבצד צפון. ורוח אחד שבצד צפון מזדווג עם שלהבת ההוא, והשלהבת הולכת ומשוטטת בעולם, ובשעה ההיא נחלק הלילה, והשלהבת הולכת ומכה בכנפי התרנגול, והוא קורא. ואז נכנס הקב\"ה בגן עדן."],[0,"","פירוש. כבר נתבאר שג' משמורות של הלילה ה\"ס ג' קוין של המלכות. וממשמורה הב' שהוא קו שמאל נמשך דינים עד שבא קו האמצעי ומיחד השמאל עם קו הימין, שהחכמה שבשמאל מתלבשת בחסדים שבימין, ואז מאירה בשלמות. גם נודע שאין קו השמאל נכנע להתיחד עם הימין, עד שקו האמצעי מעלה המסך דחירק, מתחילה מבחינת מלכות דמדת הדין, הנקראת מנעולא, ואח\"כ ממלכות הנמתקת בבינה הנקראת מפתחא. (כנ\"ל פרשת לך דף י\"ג ד\"ה ונתבאר ע\"ש)."],[0,"","וז\"ש, \u0003כדין,\u0004 מחמת הדינים דקו שמאל, \u0003אתער קב\"ה,\u0004 שהוא קו האמצעי, \u0003בדרגוי, ובטש ברקיעין,\u0004 דהיינו שמזדווג במסך דחירק, \u0003ואזדעזעו י\"ב אלף עלמין,\u0004 היינו העולמות הנמשכים מהארת החכמה שבשמאל, נזדעזעים מחמת המסך שממעט אותם לו\"ק. והם במספר י\"ב, כי כל קו וקו כלול מכל י\"ב בחינות המלכות, \u0003וגעי ובכי,\u0004 כי מחמת המסך הממעט לו\"ק שהוא קטנות, נבחן שגעי ובכה, כי הקטנות מכונה \u0003בכיה,\u0004 בסוד אותיות השניות לשם אהיה, שהם השם \u0003בוכו, ואדכר לון לישראל,\u0004 שסובלים גלות מחמת הדינים דקו שמאל. \u0003ואחית תרין דמעין,\u0004 היינו ב' בחינות המלכיות, מפתחא ומנעולא הכלולות במסך דחירק. ומשום שהחכמה מכונה עינים, נבחן מיעוט החכמה לדמעות. \u0003לגו ימא רבא,\u0004 היינו למלכות המכונה ים הגדול."],[0,"","אמנם כדי להמשיך מוחין דו\"ק דחכמה, צריכים לגנוז הדינים דמנעולא והזווג דקו האמצעי צריך להיות רק על מסך דמפתחא, כמ\"ש שם (לך י\"ג ד\"ה ונתבאר ע\"ש) וז\"ש, \u0003וכדין אתער שלהוביתא חד דבסטר צפון,\u0004 הדינים שבמסך דחירק נקראים שלהבת, אמנם מדייק \u0003דבסטר צפון,\u0004 שהוא קו השמאל, שלא יוכל להתעורר שם רק המסך דמפתחא, דהיינו המסך מבחינת מלכות שעלתה לבינה, שמחמת חזרת מלכות ההיא למקומה יצא קו השמאל, ועתה ע\"י קו האמצעי חזרה ונתעוררה שם עלית המלכות לבינה, שה\"ס מסך דמפתחא. \u0003ובטש רוחא חד דבסטר צפון,\u0004 היינו קו האמצעי הנכלל בצפון, הנקרא \u0003רוחא,\u0004 נזדווג בההוא שלהוביתא, דהיינו שמזדווג עם המסך דמפתחא ההוא, ואז חזר ונמשך עליו מוחין דו\"ק דחכמה. \u0003ואזלא ושאטא בעלמא,\u0004 היינו שהמסך דמפתחא, המכונה שלהבת דבסטר צפון, מתפשט בעולם, ובחינת מנעולא נגנזה ונעלמה. \u0003וההיא שעתא אתפלג ליליא,\u0004 שאז מתחיל שליטת הת\"ת שהוא קו האמצעי, והלילה נחלק, כי חצי הראשון הוא בחינת ב' קוין חסד וגבורה, וחצי לילה השני הוא ת\"ת ומלכות. (כנ\"ל אות ט\"ו) \u0003ושלהוביתא אזלא ובטש בגדפוי דתרנגולא,\u0004 ששלהבת הזה, שהיא מסך דמפתחא מכה בכנפי התרנגול, שה\"ס מלאך גבריאל, שנקרא תרנגול. והוא קורא, היינו הכרוז המובא לעיל (פרשת לך אות ו' ע\"ש בהסולם) שהוא לעורר בני אדם משנתם. כי מחמת הדינים דשמאל נמשך שינה לבני אדם, שה\"ס הסתלקות המוחין. וע\"י השלהבת שמעורר קו האמצעי בקו השמאל, מתיחד השמאל עם הימין והמוחין דו\"ק דחכמה, שהם רחמים, מתעוררים, ונפסק השינה מן הצדיקים. ועל זה רומז התרנגול, למטה, שבחצות לילה מגיע השלהבת, דהיינו ההתעוררות, להכות עם ב' כנפיו זו בזו שזה יורה על היחוד דימין ושמאל, והוא קורא, שזה יורה על הכרוז שלמעלה, המפסיק השינה מן הצדיקים. (כמ\"ש לך אות ו') שגם התרנגול שלמטה בקריאה שלו, מעיר קצת אנשים משנתם. וז\"ש \u0003כדין קב\"ה עאל בגנתא דעדן,\u0004 קב\"ה, היינו קו האמצעי, בגן עדן, הוא המלכות. כי אז מתחיל שליטת התפארת שהוא קו האמצעי."],[1,"וקב\"ה לית ליה וכו':","והקב\"ה אין לו נחת עד שנכנס לגן עדן להשתעשע עם נשמות הצדיקים. והסימן ליחוד הזה, הוא מה שאמרה אסתר שהיא המלכות למלך, שהוא ז\"א, כי נמכרנו אני ועמי להשמיד ולהרג ולאבד וגו', שה\"ס שליטת הדינים של קו השמאל, ויאמר המלך מי הוא זה וגו' ואמרה, המן הרע הזה, דהיינו הקליפה הנמשכת מקו שמאל. ואז נעשה הזווג על מסך דחירק דמפתחא ואז נאמר, והמלך קם בחמתו ממשתה היין אל גנת הביתן. \u0003קם\u0004 היינו המשכת מוחין, כמ\"ש, \u0003ותקם\u0004 בעוד לילה. \u0003במשתה היין\u0004 היינו מוחין דו\"ק דחכמה, \u0003בחמתו,\u0004 היינו בהתפעלות מרוב הדינים שנמשכים מקו שמאל, \u0003אל גנת הביתן,\u0004 היינו גן העדן."],[2,"בשעתא דקב\"ה עאל וכו':","בשעה שהקב\"ה נכנס בגן העדן, אז, כל עצי הגן, וכל אלו נשמות הצדיקים, פותחים ואומרים, שאו שערים ראשיכם וגו'. מי זה מלך הכבוד וגו'. שאו שערים ראשיכם וגו', ובשעה שנשמות של הצדיקים שהם בארץ חוזרות לגופיהם, אז מחזקים אותן כל אלו המלאכים, ואומרים, הנה ברכו את ה' כל עבדי ה' ולמדנו שפסוק הזה אומרים \u0003מחנה השלישי,\u0004 בארבעה שעות האחרונים, שהם בחינת קו האמצעי."],[3,"וקאמרי שירתא עד וכו':","ומחנה השלישי אומרים שירה עד שאור הבוקר עולה, שאז, משבחים לרבונם, כל אלו כוכבים ומזלות, וכל אלו מלאכים העליונים השולטים ביום, דהיינו הנמשכים מז\"א, כולם משבחים לרבונם ואומרים שירה. ז\"ש ברן יחד ככבי בקר ויריעו כל בני אלקים. דהיינו כל המלאכים. כי בלילה אומרים שירה רק חלק מן המלאכים, דהיינו אותם הנמשכים ממלכות. אבל ביום אומרים הכל שירה, גם המלאכים הנמשכים מז\"א."],[4,"בשעתא דשמשא נפיק וכו':","בשעה שהשמש יוצא, ביום, אומרים ישראל שירה למטה, והשמש למעלה. שכתוב, ייראוך עם שמש. בשעה שהשמש נוסע בגלגליו, פותח קול נעים, ואומר שירה. ומהו השירה שאומר. הוא, הודו לה' קראו בשמו וגו'. שירו לו זמרו לו וגו'. וישראל משבחים אל הקב\"ה ביום. ז\"ש ייראוך עם שמש. ואע\"פ שהעמדנו מקרא הזה, אמר ר' אלעזר, אם לא היו בני העולם אטומי הלב וסתומי עינים, לא היו יכולים לעמוד מקול הנעימות של גלגל השמש, כשנוסע ומשבח לפני הקב\"ה. וז\"ש ייראוך עם שמש."],[5,"אדהכי דאתעסקו וכו':","בתוך כך שעסקו בתורה, האיר היום. קמו והלכו לפני ר\"ש. כיון שראה אותם, אמר ר\"ש, אלעזר בני, אתה והחברים הסתירו עצמכם אלו ג' ימים, שלא תצאו לחוץ, משום שהמלאך המות נמצא בעיר, ויש לו רשות לחבל, וכיון שניתנה רשות למשחית, יכול להשחית כל מי שנראה לפניו."],[6,"ותו דבר נש וכו':","ועוד, כי האדם הנראה לפניו, המלאך המות עולה ומשטין עליו ומזכיר עונותיו, ומבקש דין מלפני הקב\"ה, ואינו סר משם, עד שאותו האדם נידון, וניתנה לו רשות, והורגו."],[7,"אר\"ש האלקים וכו':","א\"ר שמעון, האלקים, דהיינו שנשבע באלקים, שרוב בני העולם, אינם מתים לפני זמנם, חוץ מאלו שאינם יודעים לשמור את עצמם. כי בשעה שמוציאים המת מביתו לבית הקברות, נמצא מלאך המות בין הנשים. למה נמצא בין הנשים. הוא משום שכך הוא דרכו משום שפיתה את חוה, ובשבילה גרם המות לכל העולם, שע\"כ הוא ממית האדם. והגברים נמצאים עם המת. והמלאך המות נכנס בין הנשים, בהדרך עד בית הקברות."],[8,"ואית ליה רשו וכו':","ויש לו רשות אז, להמית בני אדם, והוא מסתכל בפניהם של הנראים לפניו בדרך לבית הקברות, משעה שמוציאים המת מביתו לבית הקברות, עד שחוזרים לביתם. ומשום זה, גורם מות לכמה אנשים בעולם מטרם שמגיע זמנם. וע\"ז כתוב, ויש נספה בלא משפט. משום שעולה ומסטין ומזכיר עונותיו של האדם לפני הקב\"ה, והוא נידון על אלו העונות, ונסתלק מטרם שמגיע זמנו."]],[[0,"","וְאָז מִתְעוֹרֵר הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמַעֲלוֹתָיו וּמַכֶּה בָּרְקִיעִים, כְּמוֹ שֶׁאָמַרְנוּ, וּמִזְדַּעְזְעִים שְׁנֵים עָשָׂר אַלְפֵי עוֹלָמוֹת וְגוֹעִים וּבוֹכִים, שֶׁכָּתוּב (ירמיה כה) ה' מִמָּרוֹם יִשְׁאָג וּמִמְּעוֹן קָדְשׁוֹ יִתֵּן קוֹלוֹ שָׁאֹג יִשְׁאַג עַל נָוֵהוּ. וְנִזְכָּר בְּיִשְׂרָאֵל, וּמוֹרִיד שְׁתֵּי דְמָעוֹת לְתוֹךְ הַיָּם הַגָּדוֹל, וְאָז מִתְעוֹרֶרֶת שַׁלְהֶבֶת אַחַת שֶׁבְּצַד צָפוֹן, וּמַכֶּה רוּחַ אֶחָד שֶׁבְּצַד צָפוֹן בְּאוֹתָהּ הַשַּׁלְהֶבֶת, וְהוֹלֵךְ וּמְשׁוֹטֵט בָּעוֹלָם. וּבְאוֹתָהּ שָׁעָה נֶחֱלָק הַלַּיְלָה, וְהַשַּׁלְהֶבֶת הוֹלֶכֶת וּמַכָּה בְּכַנְפֵי הַתַּרְנְגוֹל וְקוֹרֵא, אָז הַקָּדוֹשׁ בָּרוּךְ הוּא נִכְנָס לְגַן עֵדֶן."],[1,"","וְלַקָּדוֹשׁ בָּרוּךָ הוּא אֵין מְנוּחָה עַד שֶׁנִּכְנָס לְגַן עֵדֶן לְהִשְׁתַּעֲשֵׁעַ עִם נִשְׁמוֹת הַצַּדִּיקִים. וְהַסִּימָן - כִּי נִמְכַּרְנוּ אֲנִי וְעַמִּי וְגוֹ'. (אסתר ז) וַיֹּאמֶר הַמֶּלֶךְ מִי הוּא זֶה וְגוֹ', וְהַמֶּלֶךְ קָם בַּחֲמָתוֹ מִמִּשְׁתֵּה הַיַּיִן אֶל גִּנַּת הַבִּיתָן וְגוֹ'."],[2,"","בְּשָׁעָה שֶׁנִּכְנָס הַקָּדוֹשׁ בָּרוּךְ הוּא לְגַן עֵדֶן, אָז כָּל אוֹתָם עֲצֵי הַגָּן וְכָל אוֹתָן נִשְׁמוֹת הַצַּדִּיקִים פּוֹתְחִים וְאוֹמְרִים, (תהלים כד) שְׂאוּ שְׁעָרִים רָאשֵׁיכֶם וְגוֹ'. מִי זֶה מֶלֶךְ הַכָּבוֹד וְגוֹ'. שְׂאוּ שְׁעָרִים רָאשֵׁיכֶם גְוֹ'. וּבְשָׁעָה שֶׁנִּשְׁמוֹת הַצַּדִּיקִים שֶׁבָּאָרֶץ חוֹזְרוֹת לְגוּפָן, אָז מַחֲזִיקִים בָּהֶם כָּל אוֹתָם מַלְאָכִים, וְאוֹמְרִים (שם קלד) הִנֵּה בָּרְכוּ אֶת ה' כָּל עַבְדֵי ה'. וְלָמַדְנוּ שֶׁזֶּה הַמַּחֲנֶה הַשְּׁלִישִׁי שֶׁאוֹמֵר אֶת זֶה בְּאַרְבַּע הַשָּׁעוֹת הָאַחֲרוֹנוֹת."],[3,"","וְאוֹמְרִים שִׁירָה עַד שֶׁעוֹלֶה אוֹר הַבֹּקֶר, וְאָז מְשַׁבְּחִים אֶת אֲדוֹנָם כָּל אוֹתָם כּוֹכָבִים וּמַזָּלוֹת, וְכָל אוֹתָם הַמַּלְאָכִים הָעֶלְיוֹנִים שֶׁשִּׁלְטוֹנָם בַּיּוֹם, כֻּלָּם מְשַׁבְּחִים אֶת אֲדוֹנָם וְאוֹמְרִים שִׁירָה. זֶהוּ שֶׁכָּתוּב (איובלח) בְּרָן יַחַד כֹּכְבֵי בֹקֶר וַיָּרִיעוּ כָּל בְּנֵי אֱלֹהִים."],[4,"","בְּשָׁעָה שֶׁיּוֹצֵאת הַשֶּׁמֶשׁ בַּיּוֹם, יִשְׂרָאֵל נוֹטְלִים שִׁירָה לְמַטָּה, וְהַשֶּׁמֶשׁ לְמַעְלָה, שֶׁכָּתוּב יִירָאוּךְ עִם שָׁמֶשׁ. בְּשָׁעָה שֶׁנּוֹסֵעַ הַשֶּׁמֶשׁ בְּגַלְגַּלָּיו, פּוֹתֵחַ בְּקוֹל נְעִימָה וְאוֹמֵר שִׁירָה. וְאֵיזוֹ שִׁירָה אוֹמְרִים. ? (תהליםקד) הוֹדוּ לַה' קִרְאוּ בִשְׁמוֹ וְגוֹ'. (שם) שִׁירוּ לוֹ זַמְּרוּ לוֹ וְגוֹ'. וְיִשְׂרָאֵל מְשַׁבְּחִים אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בַּיּוֹם עִם הַשֶּׁמֶשׁ. זֶהוּ שֶׁכָּתוּב (שםעב) יִירָאוּךְ עִם שָׁמֶשׁ. וְאַף עַל גַּב שֶׁהֲרֵי בֵּאַרְנוּ אֶת הַפָּסוּק הַזֶּה, אָמַר רַבִּי אֶלְעָזָר, אִלְמָלֵא שֶׁבְּנֵי הָעוֹלָם הֵם אֲטוּמֵי לֵב וּסְתוּמֵי עֵינַיִם, לֹא יְכוֹלִים לַעֲמֹד מִקּוֹל הַנְּעִימָה שֶׁל גַּלְגַּל הַשֶּׁמֶשׁ כְּשֶׁנּוֹסֵעַ (ויוצא) וּמְשַׁבֵּחַ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא."],[5,"","בֵּינְתַיִם שֶׁהִתְעַסְּקוּ בַתּוֹרָה, הֵאִיר הַיּוֹם. קָמוּ וְהָלְכוּ לִפְנֵי רַבִּי שִׁמְעוֹן. כֵּיוָן שֶׁרָאָה אוֹתָם, אָמַר רַבִּי שִׁמְעוֹן, אֶלְעָזָר בְּנִי, אַתָּה וְהַחֲבֵרִים, הַסְתִּירוּ עַצְמְכֶם שְׁלֹשֶׁת הַיָּמִים הַלָּלוּ שֶׁלֹּא תֵצְאוּ הַחוּצָה, כִּי מַלְאַךְ הַמָּוֶת נִמְצָא בָּעִיר, וְיֵשׁ לוֹ רְשׁוּת לְהַשְׁחִית, וְכֵיוָן שֶׁנִּתְּנָה לוֹ רְשׁוּת לְהַשְׁחִית, יָכוֹל לְהַשְׁחִית אֶת כָּל מִי שֶׁנִּרְאֶה לְפָנָיו."],[6,"","וְעוֹד, שֶׁאָדָם שֶׁנִּרְאֶה לְפָנָיו, הוּא עוֹלֶה וּמַסְטִין עָלָיו וּמַזְכִּיר חֲטָאָיו, וּמְבַקֵּשׁ דִּין מִלִּפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְלֹא זָז מִשָּׁם עַד שֶׁנִּדּוֹן אוֹתוֹ הָאָדָם וְנִתֶּנֶת לוֹ רְשׁוּת וְהוֹרֵג אוֹתוֹ."],[7,"","אָמַר רַבִּי שִׁמְעוֹן, הָאֱלֹהִים, רֹב הָעוֹלָם לֹא מֵתִים טֶרֶם מַגִּיעַ זְמַנָּם, רַק כְּשֶׁלֹּא יָדְעוּ לִשְׁמֹר עַצְמָם, שֶׁהֲרֵי בְּשָׁעָה שֶׁמּוֹצִיאִים אֶת הַמֵּת מִבֵּיתוֹ לְבֵית הַקְּבָרוֹת, מַלְאַךְ הַמָּוֶת נמְצָא בֵּין הַנָּשִׁים. וְלָמָּה בֵּין הַנָּשִׁים? שֶׁכָּךְ הִיא דַּרְכּוֹ מִיּוֹם שֶׁפִּתָּה אֶת חַוָּה, וּבִגְלָלָהּ גָּרַם מָוֶת לְכָל הָעוֹלָם, וְעַל זֶה (כאשר) הוֹרֵג אָדָם, וְהָאֲנָשִׁים נִמְצָאִים עִם הַמֵּת, וְנִכְנָס בֵּין הַנָּשִׁים בַּדֶּרֶךְ."],[8,"","וְיִשִׁ לוֹ רְשׁוּת לַהֲרֹג בְּנֵי אָדָם, וּמִסְתַּכֵּל בִּפְנֵיהֶם בַּדֶּרֶךְ שֶׁנִּרְאִים לְפָנָיו, מִשָּׁעָה שֶׁמּוֹצִיאִים אוֹתוֹ מִבֵּיתוֹ לְבֵית הַקְּבָרוֹת עַד שֶׁחוֹזְרִים לְבֵיתָם, וּבִגְלָלָם גּוֹרֵם מָוֶת לְכַמָּה גְבָרִים בָּעוֹלָם טֶרֶם שֶׁמַּגִּיעַ זְמַנָּם. וְעַל זֶה כָּתוּב, (משלי יג) וְיֵשׁ נִסְפֶּה בְּלֹא מִשְׁפָּט. מִשּׁוּם שֶׁעוֹלֶה וּמַסְטִין וּמַזְכִּיר חֲטָאֵי הָאָדָם לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְנִדּוֹן עַל אוֹתָם חֲטָאִים וּמִסְתַּלֵּק טֶרֶם הִגִּיעַ זְמַנּוֹ."]]],[["מַאי תַּקָנְתֵּיה. בְּשַׁעֲתָא דְּנַטְלֵי מֵיתָא לְבֵי קִבְרֵי, יֶהְדַּר בַּר נָשׁ אַנְפּוֹי וְיִּשְׁבּוֹק לְנָשֵׁי בָּתַר כַּתְפּוֹי. וְאִי אִינּוּן מְקַדְּמֵי, יְהַךְ לַאֲחוֹרָא, בְּגִין דְּלָא יִתְחָזֵי עִמְּהוֹן אַנְפִּין בְּאַנְפִּין. וּלְבָתַר דִּמְהֲדְרֵי מִבֵּי קִבְרֵי, לָא יֶהְדַּר בְּהַהוּא אָרְחָא דְּנָשֵׁי קַיְימָן, וְלָא יִסְתָּכַּל בְּהוּ כְּלַל, אֶלָּא יִסְטֵי בְּאָרְחָא אַחֲרָא. וּבְגִין דִּבְנֵי נָשָׁא לָא יַדְעֵי, וְלָא מִסְתַּכְּלִן דָּא רוּבָּא דְּעָלְמָא, אִתְדָּנוּ בְּדִינָא, וְאִסְתַּלָּקוּ עַד לָא מָטָא זִמְנַיְיהוּ.","אָמַר רִבִּי אֶלְעָזָר, אִי הָכִי, טָב לֵיהּ לְבַר נָשׁ דְּלָא יוֹזִיף לְמִיתָא. אֲמַר לֵיהּ לָא. דְּהָא בַּר נָשׁ דְּאִסְתָּמַר כְּהַאי גַּוְונָא, אִתְחָזֵי לְאַרְכָּא דְּיוֹמִין, וְכָל שֶׁכֵּן לְעָלְמָא דְּאָתֵי.","תָּא חֲזֵי, לָאו לְמַגָּנָא אַתְקִינוּ קַדְמָאֵי שׁוֹפָר, לְאַמְשָׁכָא מִיתָא מִן בֵּיתָא לְבֵי קִבְרֵי. אִי תֵּימָא דְּעַל מֵיתָא וִיּקָרָא דִּילֵיהּ לְחוּד אִיהוּ. לָא. אֶלָּא, בְּגִין לְאַגָּנָא עַל חַיָּיא, דְּלָא יִשְׁלוֹט עָלַיְיהוּ מַלְאָךְ הַמָּוֶת, לְאַסְטָאָה לְעֵילָּא וְיִסְתַּמְרוּן מִנֵּיהּ.","פָּתַח וְאָמַר, (במדבר י׳:ט׳) וְכִי תָבֹאוּ מִלְחָמָה בְּאַרְצְכֶם עַל הַצָּר הַצּוֹרֵר אֶתְכֶם וְגוֹ', וְדָּיִּיקְנָא עַל הַצָּר, דָּא מַלְאָךְ הַמָּוְת. הַצּוֹרֵר אֶתְכֶם תָּדִיר, וְקָטִיל לִבְנֵי נָשָׁא, (ואעיק לון לחיי) וּבָעֵי לְקָטְלָא אַחֲרָנִין. מַאי תַּקָנְתֵּיהּ. וַהֲרֵעוֹתֶם. אִם בְּרֹאשׁ הַשָּׁנָה, דְּהוּא יוֹמָא דְּדִינָא לְעֵילָּא, הַאי מַלְאָךְ הַמָּוֶת נָחִית לְתַתָּא, בְּגִין לְאַשְׁגָּחָא בְּעוֹבָדִין דִּבְנֵי נָשָׁא, וּלְסַלְּקָא לְעֵילָּא לְאַסְטָאָה לוֹן. וְיִשְׂרָאֵל דְּיַדְעֵי דְּהָא מַלְאָךְ הַמָּוֶת נָחִית לְתַתָּא וְסָלִיק לְעֵילָּא, בְּגִין לְמֶהוֵי קַטֵיגוֹרָא עָלַיְיהוּ. מְקַדְּמֵי בַּשּׁוֹפָר לְיַבְּבָא עָלֵיהּ, דְּלָא יָכִיל לוֹן וּלְאַגָּנָא עָלַיְיהוּ.","וְכָל שֶׁכֵּן בְּשַׁעֲתָא דְּעָבִיד דִּינָא וְקָטִיל בְּנֵי נָשָׁא, וְאִשְׁתְּכַח לְתַתָּא. וְכָל שֶׁכֵּן בְּשַׁעֲתָא דְּאַזְלֵי לְבֵי קִבְרֵי, וְאָהַדְרוּ מִבֵּי קִבְרֵי, דְּהָא בְּשַׁעֲתָא דְּנָשֵׁי נַטְלֵי רַגְלַיְיהוּ עִם מִיתָא, אִיהוּ נָחִית וְאִשְׁתְּכַח קָמַיְיהוּ, דִּכְתִּיב, (משלי ה׳:ה׳) רַגְלֶיהָ יוֹרְדוֹת מָוֶת, יוֹרְדוֹת לְמַאן. לְהַהוּא אֲתָר דְּאִקְרֵי מָוֶת. וְעַל דָּא חַוָּה גַּרְמַת מוֹתָא לְכָל עָלְמָא, רַחֲמָנָא לִשֵׁזְבִינָן.","תָּא חֲזֵי, כְּתִיב (משלי ל׳:כ׳) כֵּן דֶּרֶךְ אִשָּׁה מְנָאָפֶת וְגוֹ'. וְהָא אוֹקִימְנָא. אֲבָל כֵּן דֶּרֶךְ אִשָּׁה מְנָאָפֶת, דָּא הוּא מַלְאָךְ הַמָּוֶת, וְהָכִי הוּא, וְהָכִי אִקְרֵי. אָכְלָה וּמָחֲתָה פִיהָ, אוֹקִידַת עָלְמָא בְּשַׁלְהוֹבוֹי, וְקַטְלַת בְּנֵי נָשָׁא עַד לָא מָטָא זִמְנַיְיהוּ, וְאָמְרָה לֹא פָעַלְתִּי אָוֶן, דְּהָא דִּינָא בָּעָא עָלַיְיהוּ, וְאִשְׁתְּכָחוּ בְּחוֹבִין, וּבְדִינָא קְשׁוֹט מִיתוּ.","בְּשַׁעֲתָא דְּעָבְדוּ יִשְׂרָאֵל יַת עֶגְלָא, וּמִיתוּ כָּל אִינּוּן אוּכְלוֹסִין, הֲוָה מַלְאָךְ הַמָּוֶת אִשְׁתְּכַח בֵּינֵי נְשֵׁי, בְּגוֹ מַשִׁרְיָּיתָא דְּיִשְׂרָאֵל. כֵּיוָן דְּאִסְתָּכַּל מֹשֶׁה, דְּהָא מַלְאָךְ הַמָּוֶת אִשְׁתְּכַח בֵּינִי נְשֵׁי, וּמַשִׁרְיָּיתָא דְּיִשְׂרָאֵל בֵּינַיְיהוּ, מִיַּד כָּנִישׁ לְכָל גּוּבְרִין לְחוֹדַיְיהוּ, הֲדָא הוּא דִכְתִיב וַיַּקְהֵל מֹשֶׁה אֶת כָּל עֲדַת בְּנֵי יִשְׂרָאֵל. אִלֵּין גּוּבְרִין, דְּכָנִישׁ לוֹן וְאַפְרִישׁ לוֹן לְחוֹדַיְיהוּ.","וּמַלְאַךָ הַמָּוֶת לָא הֲוָה מִתְפְּרַשׁ מִגּוֹ נָשִׁין, עַד דְּאִתּוֹקָם מַשְׁכְּנָא, דִּכְתִּיב וַיָּקֶם מֹשֶׁה אֶת הַמִּשְׁכָּן. וַאֲפִילּוּ בְּשַׁעֲתָא דְּנָשִׁין הָווֹ מַיְיתִין נְדָבָה לְמַשְׁכְּנָא, לָא הֲוָה מִתְעֲדֵי מִבֵּינַיְיהוּ, עַד דְּחָמָא מֹשֶׁה, וְיָהַב לְגוּבְרִין עֵיטָא, דְּלָא יִיִתוּן בְּחִבּוּרָא חֲדָא עִמְּהוֹן, וְלָא יִתְחֲזוּן אַנְפִּין בְּאַנְפִּין, אֶלָּא לְבָתַר כִּתְפַּיְיהוּ. הֲדָא הוּא דִכְתִיב וַיָבֹאוּ הָאֲנָשִׁים עַל הַנָּשִׁים (נ\"א ויבואו האנשים על הנשים לא כתיב, אלא ויבואו על) וַיָּבִיאוּ לָא כְּתִיב, אֶלָּא וַיָּבֹאוּ בְּאָרְחָא חֲדָא לָא הָווֹ אַזְלִין, אֶלָּא לְבָתַר כַּתְפַּיְיהוּ. בְּגִין דְּמַלְאָךְ הַמָּוֶת לָא אִתְפְּרַשׁ מִבֵּינַיְיהוּ עַד דְּאִתּוֹקָם מַשְׁכְּנָא.","תָּא חֲזֵי, לָא אִשְׁתְּכַח בֵּינֵי נְשֵׁי, פָּחוּת מִשֶּׁבַע נָשִׁים, וְלָא פָּחוּת מֵעֶשֶׂר. וּבְאָרְחָא בְּאִתְגַּלְּיָא, בְּשֶׁבַע אִשְׁתְּכַח, וּבָעֵי דִּינָא. בְּעֶשֶׂר, אַסְטֵי לְקָטְלָא. וּבְגִין דְּאִשְׁתְּכַח בֵּינַיְיהוּ בְּאָרְחָא בְּאִתְגַּלְּיָא, כְּתִיב וַיָּבֹאוּ הָאֲנָשִׁים עַל הַנָּשִׁים. וְאִסְתְּמָרוּ כָּל הַהוּא יוֹמָא כֻּלְּהוּ חַבְרַיָּיא, וְאִשְׁתָּדָּלוּ בְּאוֹרַיְיתָא.","פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (בראשית ז׳:א׳) וַיֹּאמֶר יְיָ' אֶל נֹחַ בֹּא אַתָּה וְכָל בֵּיתְךָ אֶל הַתֵּבָה. הַאי קְרָא אוֹקִימְנָא, אֲבָל תָּא חֲזֵי, וְכִי לָא יָכִיל קוּדְשָׁא בְּרִיךְ הוּא לְנַטְרָא לֵיהּ לְנֹחַ, בְּאֲתָר חַד בְּעָלְמָא. דִּיְהֵא מַבּוּל בְּכָל עָלְמָא, וְלָא יְהֵא בְּהַהוּא אֲתָר, כְּמָה דִּכְתִּיב בְּגִּדְעוֹן, (שופטים ו׳:מ׳) וַיְהִי חוֹרֶב אֶל הַגִזָּה לְבַדָּהּ. אוֹ לְנַטְרָא לֵיהּ בְּאַרְעָא דְּיִשְׂרָאֵל, דִּכְתִּיב בָּהּ, (יחזקאל כ״ב:כ״ד) לָא גֻּשְׁמָהּ בְּיוֹם זָעַם, דְּלָא נַחְתּוּ עָלָהּ מִי טוֹפָנָא."],[[0,"מאי תקנתיה וכו':","שואל, מהו התקון שלו להשמר מפני מלאך המות, ואומר, בשעה שנושאים המת לבית הקברות, יחזיר אדם את פניו ויעזוב הנשים שיהיו אחר כתפיו. ואם הנשים מקדימים, ילך לאחוריהן, באפן שלא יתראה עמהן פנים בפנים. ואחר שחוזרים מבית הקברות, לא יחזור באותו הדרך שהנשים עומדות, ולא יסתכל בהן כלל, אלא יטה עצמו בדרך אחר. ומשום שבני אדם אינם יודעים ואינם מסתכלים על זה, רוב העולם נידונים בדין ומסתלקים מטרם שבא זמנם."],[1,"א\"ר אלעזר וכו':","אר\"א, אם כן טוב לאדם שלא ילווה המת. א\"ל לא. כי האדם השומר את עצמו כאפן הזה, הוא ראוי לאריכת ימים, וכ\"ש לעולם הבא."],[2,"ת\"ח לאו למגנא וכו':","בוא וראה לא בחנם התקינו הראשונים לתקוע בשופר להוצאת המת מביתו לבית הקברות. אם תאמר, שהוא בשביל המת לכבודו בלבד. לא. אלא שהוא כדי להגן על האנשים החיים, שלא ישלוט עליהם מלאך המות להשטין למעלה, וישמרו ממנו."],[3,"פתח ואמר וכי וכו':","פתח ואמר, וכי תבאו מלחמה בארצכם על הצר הצורר אתכם וגו'. והסתכלתי, \u0003על הצר,\u0004 זהו מלאך המות. \u0003הצורר אתכם\u0004 תמיד וממית בני אדם, ומבקש להמית את הכל. מהו התקון שלו. \u0003והרעותם.\u0004 אם בראש השנה, שהוא יום הדין למעלה, יורד מלאך המות למטה, כדי להסתכל במעשה בני אדם, ולעלות למעלה להסטין עליהם. וישראל, שיודעים שמלאך המות יורד למטה, ועולה למעלה להיות מקטרג עליהם, הם מקדימים לתקוע בשופר ליבב עליו, שלא יוכל להם, ולהגין עליהם."],[4,"וכל שכן בשעתא וכו':","וכל שכן בשעה שעושה דין והורג בני אדם, ונמצא למטה. וכל שכן בשעה שהולכים לבית הקברות וחוזרים מבית הקברות, כי בשעה שנשים נושאות \u0003רגליהם\u0004 עם המת, הוא יורד ונמצא לפניהם. שכתוב, \u0003רגליה\u0004 יורדות מות. יורדות, למי. היינו לאותו מקום שנקרא מות, שמלאך המות בא לפניהם, בשעת נשיאת רגליהם ללוות המת, כי על כן, גרמה חוה המות לכל העולם, הרחמן יצילנו."],[5,"ת\"ח כתיב, כן וכו':","בוא וראה, כתוב, כל דרך אשה מנאפת וגו'. והעמדנוהו. אבל, \u0003כן דרך אשה מנאפת,\u0004 זהו מלאך המות, וכך הוא, וכן נקרא. \u0003אכלה ומחתה פיה,\u0004 ששורף העולם בלהבות שלו, וממית אנשים מטרם שמגיע זמנם, \u0003ואמרה לא פעלתי און,\u0004 כי דין בקש עליהם ונתפשו בעונם, ובדין אמת מתו."],[6,"בשעתא דעבדו ישראל וכו':","בשעה שעשו ישראל את העגל, ומתו כל אלו ההמונים, היה מלאך המות נמצא בין הנשים בתוך מחנה ישראל. כיון שראה משה שמלאך המות נמצא בין הנשים, ומחנה ישראל ביניהן, מיד, הקהיל את כל האנשים בפני עצמם. ז\"ש, ויקהל משה את כל עדת בני ישראל. אלו הם הגברים שהקהילם והפריד אותם בלבדם."],[7,"ומלאך המות לא וכו':","ומה\"מ, לא היה נפרד מן הנשים עד שהוקם בית המקדש, שכתוב, ויקם משה את המשכן. ואפילו בשעה שהנשים היו מביאים נדבה למשכן, לא עבר מהם. עד שראה משה, ונתן עצה אל האנשים, שלא יבואו עמהם בחבור אחד, ולא יתראו פנים בפנים, אלא שילכו לאחורי כתפיהן. ז\"ש ויבאו האנשים על הנשים. ויביאו לא כתוב, אלא ויבאו, ללמד, שהאנשים לא היו הולכים עמהן, בדרך אחד, אלא אחר כתפיהן. משום שמלאך המות לא נפרד מהן עד שהוקם המשכן."],[8,"ת\"ח לא אשתכח וכו':","בוא וראה, אין מלאך המות נמצא בין הנשים, שהן פחות משבע נשים, ולא פחות מעשר. ומפרש, בדרך בגלוי, הוא נמצא בשבע נשים, ומבקש דין. ואם יש עשר נשים הוא מסטין להמית. ומשום שנמצא ביניהן בדרך בגלוי. כתוב, ויבאו האנשים על הנשים. דהיינו לאחורי כתפיהן כנ\"ל. וכל החברים נשמרו כל אותו היום ועסקו בתורה."],[9,"פתח ר\"ש ואמר וכו':","פר\"ש ואמר, ויאמר ה' אל נח בא אתה וכל ביתך אל התבה. מקרא זה העמדנו. אבל בוא וראה, וכי לא יכול הקב\"ה לשמור את נח במקום אחד בעולם, שיהיה מבול בכל העולם, ולא יהיה באותו המקום. כמ\"ש בגדעון, ויהי חורב אל הגזה לבדה. או לשמור אותו בארץ ישראל, שכתוב בה, לא גשמה ביום זעם, שלא ירדו עליה מי המבול."]],[[0,"","וּמַה תַּקָּנָתוֹ? בְּשָׁעָה שֶׁנּוֹטְלִים אֶת הַמֵּת לְבֵית הַקְּבָרוֹת, יַחֲזִיר אָדָם פָּנָיו וְיַעֲזֹב אֶת הַנָּשִׁים אַחַר כְּתֵפָיו. וְאִם הֵן מַקְדִּימוֹת, יֵלֵךְ לְאָחוֹר, כְּדֵי שֶׁלֹּא יִתְרָאֶה עִמָּהֶן פָּנִים בְּפָנִים. וְאַחַר שֶׁחוֹזְרִים מִבֵּית הַקְּבָרוֹת, לֹא יַחֲזר בְּאוֹתָהּ דֶּרֶךְ שֶׁעוֹמְדוֹת הַנָּשִׁים וְלֹא יִסְתַּכֵּל בָּהֶן כְּלָל, אֶלָּא יִסְטֶה לְדֶרֶךְ אַחֶרֶת. וּמִשּׁוּם שֶׁבְּנֵי אָדָם לֹא יוֹדְעִים וְלֹא מִתְבּוֹנְנִים בָּזֶה, רֹב הָעוֹלָם נִדּוֹנִים בְּדִין וּמִסְתַּלְּקִים טֶרֶם הִגִּיעַ זְמַנָּם."],[1,"","אָמַר רַבִּי אֶלְעָזָר, אִם כָּךְ, טוֹב לוֹ לָאָדָם שֶׁלֹּא יְלַוֶּה אֶת הַמֵּת. אָמַר לוֹ, לֹא, שֶׁהֲרֵי אָדָם שֶׁנִּשְׁמָר כְּמוֹ זֶה, רָאוּי לַאֲרִיכוּת יָמִים, וְכָל שֶׁכֵּן לָעוֹלָם הַבָּא."],[2,"","בֹּא וּרְאֵה, לֹא לְחִנָּם תִּקְּנוּ הָרִאשׁוֹנִים שׁוֹפָר לִמְשֹׁךְ מֵת מֵהַבַּיִת לְבֵית הַקְּבָרוֹת. וְאִם תֹּאמַר שֶׁעַל הַמֵּת וּכְבוֹדוֹ לְבַד זֶה - לֹא! אֶלָּא כְּדֵי לְהָגֵן עַל הַחַיִּים שֶׁלֹּא יִשְׁלֹט עֲלֵיהֶם מַלְאַךְ הַמָּוֶת לְהַסְטִין לְמַעְלָה וְיִשָּׁמְרוּ מִמֶּנּוּ."],[3,"","פָּתַח וְאָמַר, (במדבר י) וְכִי תָבאוּ מִלְחָמָה בְּאַרְצְכֶם עַל הַצַּר הַצֹּרֵר אֶתְכֶם וְגוֹ'. וְדִיַּקְנוּ עַל הַצַּר, זֶה מַלְאַךְ הַמָּוֶת, הַצּוֹרֵר אֶתְכֶם תָּמִיד וְהוֹרֵג בְּנֵי אָדָם, (ומציק לחיים) וְרוֹצֶה לַהֲרֹג אֲחֵרִים. מַהִי תַקָּנָתוֹ? וַהֲרֵעֹתֶם. אִם בְּרֹאשׁ הַשָּׁנָה, שֶׁהוּא יוֹם הַדִּין לְמַעְלָה, מַלְאַךְ הַמָּוֶת הַזֶּה יוֹרֵד לְמַטָּה כְּדֵי לְהַשְׁגִּיחַ עַל מַעֲשֵׂי בְּנֵי הָאָדָם וְלַעֲלוֹת לְמַעְלָה לְהַסְטִין עֲלֵיהֶם. וְיִשְׂרָאֵל שֶׁיּוֹדְעִים שֶׁהֲרֵי מַלְאַךְ הַמָּוֶת יוֹרֵד מַטָּה וְעוֹלֶה לְמַעְלָה כְּדֵי לִהְיוֹת קָטֵגוֹר עֲלֵיהֶם, מְקַדְּמִים בַּשּׁוֹפָר לְיַבֵּב עָלָיו שֶׁלֹּא יוּכַל לָהֶם, וּלְהָגֵן עֲלֵיהֶם."],[4,"","וְכָל שֶׁכֵּן בְּשָׁעָה שֶׁעוֹשֶׂה דִין וְהוֹרֵג בְּנֵי אָדָם וְנִמְצָא לְמַטָּה, וְכָל שֶׁכֵּן בְּשָׁעָה שֶׁהוֹלְכִים לְבֵית הַקְּבָרוֹת וְחוֹזְרִים מִבֵּית הַקְּבָרוֹת, שֶׁהֲרֵי בְּשָׁעָה שֶׁנָּשִׁים נוֹטְלוֹת רַגְלֵיהֶן עִם הַמֵּת, הוּא יוֹרֵד וְנִמְצָא לִפְנֵיהֶם, שֶׁכָּתוּב (משלי ה) רַגְלֶיהָ יֹרְדוֹת מָוֶת. יוֹרְדוֹת לְאָן? לְאוֹתוֹ מָקוֹם שֶׁנִּקְרָא מָוֶת. וְעַל זֶה חַוָּה גָּרְמָה מָוֶת לְכָל הָעוֹלָם, הָרַחֲמָן יַצִּילֵנוּ."],[5,"","בֹּא וּרְאֵה, כָּתוּב (שם ל) כֵּן דֶּרֶךְ אִשָּׁה מְנָאָפֶת וְגוֹ'. וַהֲרֵי בֵּאַרְנוּ. אֲבָל כֵּן דֶּרֶךְ אִשָּׁה מְנָאָפֶת - זֶה מַלְאַךְ הַמָּוֶת, וְכָךְ הוּא, וְכָךְ נִקְרָא. אָכְלָה וּמָחֲתָה פִיהָ - שׂוֹרֶפֶת אֶת הָעוֹלָם בְּשַׁלְהֲבוֹתֶיהָ וְהוֹרֶגֶת בְּנֵי אָדָם טֶרֶם שֶׁהִגִּיעַ זְמַנָּם. וְאָמְרָה לֹא פָעַלְתִּי אָוֶל, שֶׁהֲרֵי דִּין צָרִיךְ עֲלֵיהֶם, וְנִמְצְאוּ בַחֲטָאִים, וּבְדִין אֱמֶת הֵם מֵתוּ."],[6,"","בְּשָׁעָה שֶׁעָשׂוּ יִשְׂרָאֵל אֶת הָעֵגֶל וּמֵתוּ כָּל אוֹתָם הֲמוֹנִים, הָיָה מַלְאַךְ הַמָּוֶת נִמְצָא בֵּין הַנָּשִׁים בְּתוֹךְ מַחֲנֵה יִשְׂרָאֵל. כֵּיוָן שֶׁהִסְתַּכֵּל מֹשֶׁה שֶׁהֲרֵי מַלְאַךְ הַמָּוֶת נִמְצָא בֵּין הַנָּשִׁים וּמַחֲנֵה יִשְׂרָאֵל בֵּינֵיהֶם, מִיָּד כִּנֵּס אֶת כָּל הַגְּבָרִים לְבַדָּם. זֶהוּ שֶׁכָּתוּב וַיַּקְהֵל מֹשֶׁה אֶת כָּל עֲדַת בְּנֵי יִשְׂרָאֵל. אֵלּוּ הַגְּבָרִים, שֶׁכִּנֵּס אוֹתָם וְהִפְרִידָם לְבַדָּם."],[7,"","וּמַלְאַךָ הַמָּוֶת לֹא הָיָה נִפְרָד מִתּוֹךְ הַנָּשִׁים עַד שֶׁהוּקַם הַמִּשְׁכָּן, שֶׁכָּתוּב וַיָּקֶם מֹשֶׁה אֶת הַמִּשְׁכָּן. וַאֲפִלּוּ בְּשָׁעָה שֶׁהַנָּשִׁים הָיוּ נוֹתְנוֹת נְדָבָה לַמִּשְׁכָּן, לֹא הָיָה סָר מִבֵּינֵיהֶם, עַד שֶׁרָאָה מֹשֶׁה וְנָתַן לַגְּבָרִים עֵצָה שֶׁלֹּא יָבאוּ בְּחִבּוּר אֶחָד עִמָּהֶם וְלֹא יִתְרָאוּ פָּנִים בְּפָנִים, אֶלָּא אַחַר כִּתְפֵיהֶם. וְזֶהוּ שֶׁכָּתוּב וַיָּבֹאוּ הָאֲנָשִׁים עַל הַנָּשִׁים. (ויבאו האנשים על הנשים לא כתוב, אלא ויבאו על) וַיָּבִיאוּ לֹא כָתוּב, אֶלָּא וַיָּבֹאוּ. לֹא הָיוּ הוֹלְכִים בְּדֶרֶךְ אַחַת, אֶלָּא אַחַר כִּתְפֵיהֶן, מִשּׁוּם שֶׁמַּלְאַךְ הַמָּוֶת לֹא נִפְרַד מִבֵּינֵיהֶן עַד שֶׁהַמִּשְׁכָּן הוּקַם."],[8,"","בֹּא וּרְאֵה, אֵינוֹ נִמְצָא בֵּין הַנָּשִׁים פָּחוֹת מִשֶּׁבַע נָשִׁים, וְלֹא פָּחוֹת מֵעֶשֶׂר. וּבַדֶּרֶךְ בְּגִלּוּי בְּשֶׁבַע הוּא נִמְצָא, וּמְבַקֵּשׁ דִּין. בְּעֶשֶׂר הוּא מַסְטִין לַהֲרֹג. וּמִשּׁוּם שֶׁנִּמְצָא בֵּינֵיהֶן בַּדֶּרֶךְ בְּגִלּוּי, כָּתוּב וַיָּבאוּ הָאֲנָשִׁים עַל הַנָּשִׁים. וְנִשְׁמְרוּ כָּל אוֹתוֹ יוֹם הַחֲבֵרִים וְעָסְקוּ בַתּוֹרָה."],[9,"","פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (בראשית ז) וַיֹּאמֶר ה' אֶל נֹחַ בֹּא אַתָּה וְכָל בֵּיתְךְ אֶל הַתֵּבָה. הֲרֵי בֵּאַרְנוּ הַפָּסוּק, אֲבָל בֹּא וּרְאֵה, וְכִי לֹא יָכֹל הַקָּדוֹשׁ בָּרוּךְ הוּא לִשְׁמֹר אֶת נֹחַ בְּמָקוֹם אֶחָד בָּעוֹלָם, שֶׁיִּהְיֶה הַמַּבּוּל בְּכָל הָעוֹלָם וְלֹא יִהְיֶה בְּאוֹתוֹ מָקוֹם, כְּמוֹ שֶׁכָּתוּב בְּגִדְעוֹן (שופטים ו) וַיְהִי חֹרֶב אֶל הַגִּזָּה לְבַדָּהּ, אוֹ לִשְׁמֹר אוֹתוֹ בְּאֶרֶץ יִשְׂרָאֵל שֶׁכָּתוּב בָּהּ (יחזקאל כב) לֹא גֻשְׁמָהּ בְּיוֹם זָעַם, שֶׁלֹּא יֵרְדוּ עָלֶיהָ מֵי הַמַּבּוּל?"]]],[["אֶלָּא, כֵּיוָן דִּמְחַבְּלָא נָחַת לְעָלְמָא, מַאן דְּלָא סָגִיר גַּרְמֵיהּ, וְאִשְׁתְּכַח קָמֵיהּ בְּאִתְגַּלְיָיא, אִתְחַיָּיב בְּנַפְשֵׁיהּ, דְּאִיהוּ קָטִיל גַּרְמֵיהּ. מְנָא לָן. מִלוֹט, דִּכְתִּיב, (בראשית י״ט:י״ז) הִמָּלֵט עַל נַפְשֶׁךָ אַל תַּבִּיט אַחֲרֶיךָ. מַאי טַעֲמָא אַל תַּבִּיט אַחֲרֶיךָ. בְּגִין דִּמְחַבְּלָא אָזִיל בָּתַר כַּתְפּוֹי, וְאִי אָהֲדָר רֵישֵׁיהּ, וְאִסְתָּכַּל בֵּיהּ אַנְפִּין בְּאַנְפִּין, יָכִיל לְנַזְקָא לֵיהּ.","וְעַל דָּא כְּתִיב, (בראשית ז) וַיִסְגוֹר יְיָ' בַּעֲדוֹ. דְּלָא יִתְחָזֵי קַמֵּי מְחַבְּלָא, וְלֹא יִשְׁלוֹט עָלֵיהּ מַלְאָךְ הַמָּוֶת. וְעַד דְּהַווּ טְמִירִין, מִיתוּ תְּלֵיסָר גּוּבְרִין בְּמָתָא. אָמַר רִבִּי שִׁמְעוֹן, בְּרִיךְ רַחֲמָנָא, דְּלָא אִסְתָּכַּל בְּדִיּוּקְנַיְיכוּ מַלְאָךְ הַמָּוֶת.","(שמות ל״ה:א׳) וַיַּקְהֵל מֹשֶׁה וְגוֹ'. (קצ\"ה ע\"א) אָהֲדָר לוֹן כְּמִלְּקַדְּמִין, עוֹבָדָא דְּמַשְׁכְּנָא. אָמַר רִבִּי חִיָּיא, כֹּלָּא כְּמָה דְּאִתְּמַר. וְעוֹבָדָא דְּמַשְׁכְּנָא לָא אִתְעָבִיד אֶלָּא מִיִשְׂרָאֵל בִּלְחוֹדַיְיהוּ, וְלָא מֵאִינּוּן עֵרֶב רַב, בְּגִין דְּאִינּוּן עֵרֶב רַב אַמְשִׁיכוּ לֵיהּ לְמַלְאַךְ הַמָּוֶת לְנַחְתָּא לְעָלְמָא. כֵּיוָן דְּאִסְתָּכַּל מֹשֶׁה בֵּיהּ, אַשְׁדֵּי לְאִינּוּן עֵרֶב רַב, לְבַר, וְכָנִישׁ לוֹן לְיִשְׂרָאֵל בִּלְחוֹדַיְיהוּ, הֲדָא הוּא דִּכְתִּיב וַיַּקְהֵל מֹשֶׁה וְגוֹ'.","רִבִּי שִׁמְעוֹן פָּתַח, (משלי ל׳:ד׳) מִי עָלָה שָׁמַיִם וַיֵּרַד מִי אָסַף רוּחַ בְּחָפְנָיו מִי צָרַר מַיִם בַּשִּׂמְלָה מִי הֵקִים כָּל אַפְסֵי אָרֶץ מַה שְּׁמוֹ וּמַה שֶּׁם בְּנוֹ כִּי תֵדַע. הַאי קְרָא הָא אוֹקִימְנָא, וְכַמָּה סַמְכִין אִית בֵּיהּ. וְכֹלָּא בְּקוּדְשָׁא בְּרִיךְ הוּא אִתְּמַר, דְּאִיהוּ כֹּלָּא. (ע\"ט ע\"א) וְאִתְּמַר, מָה שְׁמוֹ וּמַה שֵׁם בְּנוֹ כִּי תֵּדַע, דָּא קוּדְשָׁא בְּרִיךְ הוּא. מָה שְׁמוֹ יְדוָֹ\"ד. וּמַה שֵׁם בְּנוֹ, יִשְׂרָאֵל דִּכְתִּיב, (שמות ד) בְּנִי בְּכֹרִי יִשְׂרָאֵל, וְהָא אוֹקִימְנָא. מִי עָלָה שָׁמַיִם. הָא אוּקְמוּהָ, דָּא מֹשֶׁה, דִּכְתִּיב, (שמות כ״ד:א׳) וְאֶל מֹשֶׁה אָמַר עֲלֵהּ אֶל יְיָ'.","דָּבָר אַחֵר מִי עָלָה שָׁמַיִם, דָּא אֵלִיָּהוּ, דִּכְתִּיב בֵּיהּ (מלכים ב ב׳:י״א) וַיַּעַל אֵלִיָּהוּ בַּסֳּעָרָה הַשָּׁמָיִם. וְכִי הֵיךְ יָכִיל אֵלִיָּהוּ לְסַלְּקָא לַשָּׁמַיִם. וְהָא כֻּלְּהוּ שָׁמַיִם, לָא יַכְלִין לְמִסְבַּל, אֲפִילּוּ גַּרְעִינָא כְּחַרְדַּל מִגּוּפָא דְּהַאי עָלְמָא, וְאַתְּ אַמָרְתּ וַיַּעַל אֵלִיָּהוּ בַּסֳּעָרָה הַשָּׁמָיִם.","אֶלָּא כְּמָה דְּאַתְּ אָמַר, (שמות י״ט:י״א) וַיֵּרֶד יְיָ' עַל הַר סִינַי. וּכְתִיב (שמות כ״ד:י״ח) וַיָּבֹא מֹשֶׁה בְּתוֹךְ הֶעָנָן וַיַּעַל אֶל הָהָר. וְכִי קוּדְשָׁא בְּרִיךְ הוּא דְּהֲוָה בְּטוּרָא דְּסִינַי, וּכְתִּיב (שמות כ״ד:י״ז) וּמַרְאֶה כְּבוֹד יְיָ' כָּאֵשׁ אוֹכֶלֶת בְּרֹאשׁ הָהָר, אֵיךְ יָכִיל מֹשֶׁה לְסַלְּקָא לְגַבֵּיהּ. אֶלָּא בְּמֹשֶׁה כְּתִיב, וַיָּבֹא מֹשֶׁה בְּתוֹךְ הֶעָנָן וַיַּעַל אֶל הָהָר. דְּעָאל גּוֹ עֲנָנָא, כְּמַאן דְּאִתְלָבַּשׁ בִּלְבוּשָׁא. הָכִי נָמֵי אִתְלָבָּשׁ בַּעֲנָנָא, וְעָאל בְּגַוֵּיהּ. וּבְעֲנָנָא אִתְקְרִיב לְגַבֵּי אֶשָּׁא, וְיָכִיל לְמִקְרָב. אוּף הָכִי אֵלִיָּהוּ, דִּכְתִּיב וַיַּעַל אֵלִיָּהוּ בַּסֳּעָרָה הַשָּׁמַיִם, דְּעָאל בְּהַהִיא סְעָרָה, וְאִתְלָבַּשׁ בֵּיהּ בְּהַהִיא סְעָרָה, וְסָלִיק לְעֵילָּא.","וְרָזָא אַשְׁכַּחְנָא, בְּסִפְרָא דְּאָדָם קַדְמָאָה, דְּאָמַר בְּאִינּוּן תּוֹלְדוֹת דְּעָלְמָא, רוּחָא חֲדָא יְהֵא דְּיֵּחוֹת לְעָלְמָא בְּאַרְעָא, וְיִתְלַבָּשׁ בְּגוּפָא, וְאֵלִיָּהוּ שְׁמֵיהּ. וּבְהַהוּא גּוּפָא יִסְתָּלַק, וְאִשְׁתְּלִיל מִגוּפֵיהּ, וְיִשְׁתְּאַר בַּסֳּעָרָה. וְגוּפָא דִּנְהוֹרָא אַחֲרָא יִזְדָּמַן לֵיהּ, לְמֶהוֵי גּוֹ מַלְאֲכֵי. וְכַד יֵחוּת, יִתְלַבָּשׁ בְּהַהוּא גּוּפָא, דְּיִשְׁתְּאַר בְּהַהוּא עָלְמָא, וּבְהַהוּא גּוּפָא יִתְחָזֵי לְתַתָּא, וּבְגוּפָא אַחֲרָא יִתְחָזֵי לְעֵילָּא. וְדָא אִיהוּ רָזָא, דְּמִי עָלָה שָׁמַיִם וַיֵּרַד. לָא הֲוָה בַּר נָשׁ דְּסָלִיק לִשְׁמַיָּא רוּחָא דִּילֵיהּ, וְנָחִית לְבָתַר לְתַתָּא, בַּר אֵלִיָּהוּ, דְּאִיהוּ סָלִיק לְעֵילָּא וְנָחִית לְתַתָּא.","דָּבָר אַחֵר מִי עָלָה שָׁמַיִם, דָּא אֵלִיָּהוּ. וַיֵּרַד, דָּא יוֹנָה, דְּנָחַת לֵיהּ נוּנָא גּוֹ תְּהוֹמֵי, לְעִמְקֵי יַמָּא. יוֹנָה מֵחֵילָא דְּאֵלִיָּהוּ קָא אָתָא, אֵלִיָּהוּ סָלִיק, יוֹנָה נָחִית, דָּא שָׁאִיל נַפְשֵׁיהּ לְמֵימַת, וְדָא שָׁאִיל נַפְשֵׁיהּ לְמֵימַת, וּבְגִין כַּךְ אִקְרֵי בֶּן אֲמִתַּי. וּכְתִיב, (מלכים א י״ז:כ״ד) וּדְבַר יְיָ' בְּפִיךָ אֱמֶת.","מִי צָרַר מָיִם, דָּא אֵלִיָּהוּ, דְּצָּרִיר צְרוֹרָא דְּמַיָּא בְּעָלְמָא, וְלָא נַחְתּוּ טַלָּא וּמִטְרָא דִּשְׁמַיָּא. בַּשִּׂמְלָה, דָּא אֵלִיָּהוּ, דְּהֲוָה (נ\"א מחי אדרתיה) מַיְיתֵי אַדַּרְתֵּיהּ לְמֶעְבָּד נִסִּין. מִי אָסַף רוּחַ בְּחָפְנָיו, דָּא אֵלִיָּהוּ, דְּאַהֲדָר רוּחָא דְּבַר נָשׁ לְגוֹ מֵעוֹי. (אסף כמה דאת אמר (מלכים ב ה׳:י״א) ואסף המצורע)."],[[0,"אלא כיון דמחבלא וכו':","ומשיב, אלא כיון שהמשחית ירד לעולם, מי שלא סגר את עצמו, ונמצא לפניו בגלוי, מתחייב בנפשו, כי המית את עצמו. מאין לנו, מלוט, שכתוב, המלט על נפשך אל תביט אחריך. מהו הטעם, אל תביט אחריך, משום שהמשחית הלך אחורי כתפיו, ואם החזיר ראשו והסתכל בו פנים בפנים, היה יכול להזיקו."],[1,"וע\"ד כתיב ויסגור וכו':","וע\"כ כתוב בנח, ויסגור ה' בעדו, שלא יתראה לפני המשחית, ולא ישלוט עליו מלאך המות. ובעוד שהחברים היו נסתרים בבית, מתו י\"ג אנשים בעיר. אמר ר\"ש ברוך הרחמן, שהמלאך המות לא הסתכל בצורתכם."],[2,"ויקהל משה וגו':","חזר שנית על מעשה המשכן, כמקודם בפרשת תרומה. אמר ר' חייא הכל הוא כמו שלמדנו (לעיל אות ח') שמעשה המשכן לא נעשה אלא מישראל לבדם, ולא מערב רב. משום שהערב רב המשיכו בחזרה את המלאך המות לרדת לעולם. כיון שהסתכל משה בזה, השליך הערב רב לחוץ והקהיל את ישראל בלבדם. זהו שכתוב, ויקהל משה. משא\"כ בפרשת תרומה, נאמר, מאת כל איש אשר ידבנו לבו וגו' שגם הערב רב היו בכלל. (כנ\"ל אות ח'). וע\"כ היה צריך לומר מעשה המשכן פעם שנית."],[3,"רבי שמעון פתח וכו':","ר\"ש פתח מי עלה שמים וירד מי אסף רוח בחפניו מי צרר מים בשמלה מי הקים כל אפסי ארץ מה שמו ומה שם בנו כי תדע. מקרא זה העמדנו, וכמה פרושים יש בו. והכל נא' בהקב\"ה, שהוא הכל. ולמדנו, מה שמו ומה שם בנו כי תדע, זהו הקב\"ה, \u0003מה שמו,\u0004 הויה. \u0003ומה שם בנו,\u0004 ישראל. שכתוב, בני בכרי ישראל. וכבר העמדנו. \u0003מי עלה שמים,\u0004 הרי העמדנו, שזה משה, שכתוב, ואל משה אמר עלה אל ה'."],[4,"ד\"א מי עלה שמים:","זהו אליהו. שכתוב בו, ויעל אליהו בסערה השמים. שואל, וכי איך היה יכול אליהו לעלות השמים, והרי השמים כולם אינם יכולים לסבול, אפילו כגודל גרעין חרדל, מגוף של עולם הזה, ואתה אומר, ויעל אליהו בסערה השמים."],[5,"אלא כמה דאת וכו':","ומשיב, אלא כמו שאתה אומר, וירד ה' על הר סיני. וכתוב, ויבא משה בתוך הענן ויעל אל ההר. וכי הקדוש ברוך הוא שהיה בהר סיני וכתוב, ומראה כבוד ה' כאש אוכלת בראש ההר, איך היה יכול משה לעלות אליו. אלא במשה כתוב, ויבא משה בתוך הענן ויעל אל ההר, שנכנס בענן כמי שמתלבש בלבוש. וכאן, בהכתוב, ואל משה אמר עלה אל ה', גם כן נתלבש בענן ונכנס בתוכו. ובענן קרב אל האש, ויכול לקרב. אף כך אליהו, שכתוב ויעל אליהו בסערה השמים, הוא, שנכנס בסערה ההוא, ונתלבש בסערה ההוא, ועלה למעלה."],[6,"ורזא אשכחנא בספרא וכו':","ומצאתי סוד בספרו של אדם הראשון. שאמר באלו תולדות שיבואו לעולם. שיהיה רוח אחד שירד לעולם בארץ, ויתלבש בגוף, ושמו אליהו. ובגוף ההוא יסתלק מן העולם, ויתפשט מגופו וישאר בסערה. וגוף אחר של אור יזדמן לו, להיות בו בין המלאכים. וכאשר ירד לעולם הזה, יתלבש בגוף ההוא שנשאר בעולם ההוא, דהיינו בסערה, ובגוף ההוא יראה למטה, ובגוף האחר של אור, יראה למעלה. וזה הוא סוד של מי עלה שמים וירד, שלא היה אדם שרוח שלו יעלה לשמים אחר הסתלקות הגוף וירד אח\"כ למטה, כמו אליהו, שהוא עלה למעלה וירד למטה."],[7,"ד\"א, מי עלה שמים:","זה אליהו. \u0003וירד,\u0004 זהו יונה. שהורידו הדג לתוך התהומות למעמקי הים. יונה בא מכחו של אליהו, שהיה לו נפש אליהו, לפיכך, אליהו עלה, ויונה ירד, זה שאל נפשו למות וזה שאל נפשו למות. ומשום זה נקרא בן אמתי, שכתוב, ודבר ה' בפיך אמת."],[8,"מי צרר מים:","זה אליהו, שקשר קשר המים בעולם, ולא ירד טל ומטר השמים. \u0003בשמלה\u0004 זה אליהו, שהיה מביא אדרתו לעשות נסים. שבקע בה הוא ואלישע, את הירדן. (מלכים ב' ב') \u0003מי אסף רוח בחפניו,\u0004 זה אליהו, שהחזיר רוחו של אדם לתוך גופו אחר שמת. (מלכים א' י\"ז)."]],[[0,"","אֶלָּא, כֵּיוָן שֶׁהַמַּשְׁחִית יָרַד לָעוֹלָם, מִי שֶׁאֵינוֹ סוֹגֵר אֶת עַצְמוֹ וְנִמְצָא לְפָנָיו בְּגָלוּי - מִתְחַיֵּב בְּנַפְשׁוֹ, שֶׁהוּא הָרַג אֶת עַצְמוֹ. מִנַּיִן לָנוּ? מִלּוֹט, שֶׁכָּתוּב (בראשית יט) הִמָּלֵט עַל נַפְשֶׁךְ אַל תַּבִּיט אַחֲרֶיךְ. מָה הַטַּעַם אַל תַּבִּיט אַחֲרֶיךְ? מִשּׁוּם שֶׁהַמַּשְׁחִית הוֹלֵךְ אַחַר כְּתֵפוֹ, וְאִם מַחֲזִיר רֹאשׁוֹ וּמִתְבּוֹנֵן בּוֹ פָּנִים בְּפָנִים, יָכוֹל לְהַזִּיק לוֹ."],[1,"","וְעַל זֶה כָּתוּב, (שם) וַיִּסְגֹּר ה' בַּעֲדוֹ, שֶׁלֹּא יִתְרָאֶה לִפְנֵי הַמַּשְׁחִית וְלֹא יִשְׁלֹט עָלָיו מַלְאַךְ הַמָּוֶת. וְעַד שֶׁהָיוּ טְמוּנִים, מֵתוּ שְׁלֹשָׁה עָשָׂר אֲנָשִׁים בָּעִיר. אָמַר רַבִּי שִׁמְעוֹן, בָּרוּךְ הָרַחֲמָן שֶׁלֹּא הִסְתַּכֵּל בִּדְיוֹקְנֵיכֶם מַלְאַךְ הַמָּוֶת."],[2,"","וַיַּקְהֵל מֹשֶׁה וְגוֹ'. הֶחֱזִיר לָהֶם כְּמִקֹּדֶם מַעֲשֵׂה הַמִּשְׁכָּן. אָמַר רַבִּי חִיָּיא, הַכֹּל כְּמוֹ שֶׁנִּתְבָּאֵר. וּמַעֲשֵׂה הַמִּשְׁכָּן לֹא נַעֲשָׂה כִּי אִם מִיִּשְׂרָאֵל לְבַדָּם, וְלֹא מֵאוֹתָם עֵרֶב רַב, מִשּׁוּם שֶׁאוֹתָם עֵרֶב רַב מָשְׁכוּ אֶת מַלְאַךְ הַמָּוֶת לָרֶדֶת לָעוֹלָם. כֵּיוָן שֶׁהִסְתַּכֵּל בּוֹ מֹשֶׁה, זָרַק הַחוּצָה אֶת אוֹתָם עֵרֶב רַב, וְכִנֵּס אֶת יִשְׂרָאֵל לְבַדָּם. זֶהוּ שֶׁכָּתוּב וַיַּקְהֵל מֹשֶׁה וְגוֹ'."],[3,"","רַבִּי שִׁמְעוֹן פָּתַח, (משלי ה) מִי עָלָה שָׁמַיִם וַיֵּרַד מִי אָסַף רוּחַ בְּחָפְנָיו מִי צָרַר מַיִם בַּשִּׂמְלָה מִי הֵקִים כָּל אַפְסֵי אָרֶץ מַה שְּׁמוֹ וּמַה שֶּׁם בְּנוֹ כִּי תֵדָע. פָּסוּק זֶה הֲרֵי בֵּאַרְנוּ, וְכַמָּה עַמּוּדִים יֵשׁ בּוֹ. וְהַכֹּל נֶאֱמַר עַל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהוּא הַכֹּל. וְנֶאֱמַר, מַה שְּׁמוֹ וּמַה שֶּׁם בְּנוֹ כִּי תֵדָע - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. מַה שְּׁמוֹ? יהו\"ה. וּמַה שֶּׁם בְּנוֹ? יִשְׂרָאֵל, שֶׁכָּתוּב (שמות ד) בְּנִי בְכֹרִי יִשְׂרָאֵל, וַהֲרֵי בֵּאַרְנוּ. מִי עָלָה שָׁמַיִם, הֲרֵי פֵּרְשׁוּהוּ, זֶה מֹשֶׁה, שֶׁכָּתוּב (שם כד) וְאֶל מֹשֶׁה אָמַר עֲלֵה אֶת ה'."],[4,"","דָּבָר אַחֵר מִי עָלָה שָׁמַיִם - זֶה אֵלִיָּהוּ, שֶׁכָּתוּב בּוֹ (מלכים בב) וַיַּעַל אֵלִיָּהוּ בַּסֳעָרָה הַשָּׁמָיִם. וְכִי אֵיךְ יָכֹל אֵלִיָּהוּ לַעֲלוֹת לַשָּׁמַיִם, וַהֲרֵי כָּל הַשָּׁמַיִם לֹא יְכוֹלִים לִסְבֹּל אֲפִלּוּ גַּרְעִין שֶׁל חַרְדַּל מִגּוּף הָעוֹלָם הַזֶּה, וְאַתָּה אוֹמֵר וַיַּעַל אֵלִיָּהוּ בַּסֳעָרָה הַשָּׁמָיִם?"],[5,"","אֶלָּא כְּמוֹ שֶׁנֶּאֱמַר (שמותיט) וַיֵּרֶד ה' עַל הַר סִינַי. וְכָתוּב (שם כב) וַיָּבֹא מֹשֶׁה בְּתוֹךְ הֶעָנָן וַיַּעַל אֶל הָהָר. וְכִי הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהָיָה בְּהַר סִינַי, וְכָתוּב וּמַרְאֵה כְּבוֹד ה' כְּאֵשׁ אֹכֶלֶת בְּרֹאשׁ הָהָר, אֵיךְ יָכֹל מֹשֶׁה לַעֲלוֹת אֵלָיו? אֶלָּא כָּתוּב בְּמֹשֶׁה, וַיָּבֹא מֹשֶׁה בְּתוֹךְ הֶעָנָן וַיַּעַל אֶל הָהָר. שֶׁנִּכְנַס לְתוֹךְ הֶעָנָן כְּמִי שֶׁמִּתְלַבֵּשׁ בִּלְבוּשׁ, כָּךְ גַּם הִתְלַבֵּשׁ בֶּעָנָן וְנִכְנַס לְתוֹכוֹ, וּבֶעָנָן נִקְרַב לָאֵשׁ וְיָכֹל לִקְרַב. אַף כָּךְ אֵלִיָּהוּ, שֶׁכָּתוּב וַיַּעַל אֵלִיָּהוּ בַּסֳעָרָה הַשָּׁמָיִם, שֶׁנִּכְנַס בְּאוֹתָהּ סֳעָרָה וְהִתְלַבֵּשׁ בְּאוֹתָהּ סֳעָרָה וְעָלָה לְמַעְלָה."],[6,"","וְסוֹד מָצָאנוּ בְּסִפְרוֹ שֶׁל אָדָם הָרִאשׁוֹן, שֶׁאָמַר בְּאוֹתָן תּוֹלְדוֹת הָעוֹלָם, שֶׁתִּהְיֶה רוּחַ אַחַת שֶׁתֵּרֵד לָעוֹלָם לָאָרֶץ וְתִתְלַבֵּשׁ בְּגוּף וּשְׁמוֹ אֵלִיָּהוּ, וּבְאוֹתוֹ גוּף יִסְתַּלֵּק, וְיִשָּׁלֵל מִגּוּפוֹ, וְיִשָּׁאֵר בַּסֳעָרָה, וְגוּף שֶׁל אוֹר אַחֵר יִזְדַּמֵּן לוֹ לִהְיוֹת בְּתוֹךְ הַמַּלְאָכִים. וּכְשֶׁיֵּרֵד, יִתְלַבֵּשׁ בְּאוֹתוֹ גוּף שֶׁיִּשָּׁאֵר בְּאוֹתוֹ הָעוֹלָם, וּבְאוֹתוֹ גוּף יִתְרָאֶה לְמַטָּה, וּבְגוּף אַחֵר יִתְרָאֶה לְמַעְלָה. וְזֶהוּ סוֹד שֶׁל מִי עָלָה שָׁמַיִם וַיֵּרַד. לֹא הָיָה אָדָם שֶׁעָלָה לַשָּׁמַיִם רוּחוֹ וְיָרַד אַחַר כָּךְ לְמַטָּה, פְּרָט לְאֵלִיָּהוּ, שֶׁהוּא עָלָה לְמַעְלָה וְיָרַד לְמַטָּה."],[7,"","דָּבָר אַחֵר מִי עָלָה שָׁמַיִם - זֶה אֵלִיָּהוּ. וַיֵּרַד - זֶה יוֹנָה, שֶׁהוֹרִיד אוֹתוֹ הַדָּג לְתוֹךְ הַתְּהוֹמוֹת לְעִמְקֵי הַיָּם. יוֹנָה בָּא מִכֹּחוֹ שֶׁל אֵלִיָּהוּ. אֵלִיָּהוּ עָלָה, וְיוֹנָה יָרַד. זֶה שָׁאַל נַפְשׁוֹ לָמוּת, וְזֶה שָׁאַל נַפְשׁוֹ לָמוּת. וּמִשּׁוּם כָּךְ נִקְרָא בֶּן אֲמִתַּי, וְכָתוּב (מלכים א יז) וּדְבַר ה' בְּפִיךְ אֱמֶת."],[8,"","מִי צָרַר מַיִם - זֶה אֵלִיָּהוּ, שֶׁצָּרַר אֶת צְרוֹר הַמַּיִם בָּעוֹלָם, וְלֹא יָרְדוּ טַל וּמָטָר מִשָּׁמַיִם. בַּשִּׂמְלָה - זֶה אֵלִיָּהוּ, שֶׁהָיָה (מכה באדרתו) מֵבִיא אַדַּרְתּוֹ לַעֲשׂוֹת נִסִּים. מִי אָסַף רוּחַ בְּחָפְנָיו - זֶה אֵלִיָּהוּ, שֶׁהֶחֱזִיר רוּחוֹ שֶׁל אָדָם לְתוֹךְ מֵעָיו. (אסףכמושגאמר (מלכים ב ה) ואסף המצרע)."]]],[["מִי הֵקִים כָּל אַפְסֵי אָרֶץ. דָּא אֵלִיָּהוּ, דִּלְבָתַר דְּצָרַר מַיִם, וְאוֹמֵי עַל (ס\"א מטרא') שְׁמַיָא לְבָתַר אָהֲדַּר בִּצְלוֹתֵיהּ, וְאוֹקִים כָּל עָלְמָא, וְנָחִית מִטְרָא, וְאִתְיְהִיב מְזוֹנָא לְכֹלָּא. מַה שְּׁמוֹ, דָּא אֵלִיָּהוּ. וּמַה שֶּׁם בְּנוֹ, דָּא אֵלִיָּהוּ. מַה שְּׁמוֹ, כַּד סָלִיק לְעֵילָּא, אֵלִיָּהוּ. וּמַה שֶּׁם בְּנוֹ, כַּד נָחִית לְתַתָּא, וְאִתְעָבִיד שְׁלִיחָא לְמֶעְבַּד נִסִּין, אֵלִיָּהוּ שְׁמֵיהּ.","דָּבָר אַחֵר מִי עָלָה שָׁמַיִם, דָּא קוּדְשָׁא בְּרִיךְ הוּא, כְּמָה דְּאוֹקִימְנָא. וְרָזָא דְּמִלָּה, מִ\"י, וְהָא אוֹקִימְנָא. וְהָכָא אִיהוּ רָזָא דִּרְתִיכָא עִלָּאָה, (כ\"ג ע\"ב) אַרְבַּע סִטְרִין דְּעָלְמָא, דְּאִינּוּן יְסוֹדֵי קַדְמָאֵי דְּכֹלָּא, וְכֻלְּהוּ תַּלְיָין בְּהַהוּא אֲתָר עִלָּאָה דְּאִקְרֵי מִ\"י, כְּמָה דְּאִתְּמַר.","תָּא חֲזֵי, כַּד קַיְּימָא שַׁעֲתָא דִּרְעוּתָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, לְיַחֲדָא רְתִיכָא עִלָּאָה (ס\"א ברתיכא תתאה') לְמֶהוֵי כֹּלָּא חַד. כְּדֵין קָלָא נָפִיק, מֵהַהוּא אֲתָר עִלָּאָה קַדִּישָׁא, דְּאִקְרֵי שָׁמַיִם, וְכָנִישׁ כָּל אִלֵּין קַדִּישִׁין דִּלְתַתָּא, וְכָל אִינּוּן רַבְרְבָן קַדִּישִׁין, וּמַשִׁרְיָין עִלָּאִין, לְמֶהֱוֵי כֻּלְּהוּ זְמִינִין כַּחֲדָא, הֲדָא הוּא דִכְתִיב, וַיַּקְהֵל מֹשֶׁה, דָּא רָזָא דְּשָׁמַיִם. אֶת כָּל עֲדַת בְּנֵי יִשְׂרָאֵל, אִלֵּין אִינּוּן תְּרֵיסַר מַשִׁרְיָין עִלָּאִין קַדִּישִׁין.","וַיֹּאמֶר אֲלֵיהֶם. וּמַאי קָאָמַר זֶה הַדָּבָר וְגוֹ', קְחוּ מֵאִתְּכֶם תְּרוּמָה, אִתְתָּקָנוּ כֻּלְּכוּן, לְסַלְּקָא עָלַיְיכוּ, וּלְמֵיטַל עָלַיְיכוּ, יְקָרָא דְּכֻרְסְיָיא קַדִּישָׁא, לְסַלְּקָא לְעֵילָּא.","אַפְרִישׁוּ מִנַּיְיכוּ אִינּוּן יַקִּירִין, אִינּוּן רַבְרְבִין עִלָּאִין, לְסַלְּקָא לְהַהִיא תְּרוּמָה, רָזָא דְּכֻרְסְיָיא קַדִּישָׁא, לְאִתְחַבְּרָא בַּאֲבָהָן, (נ\"א בבעלה) דְּהָא מַטְרוֹנִיתָא לָא אִתְחֲזֵי לְמֵיתֵי לְבַעְלָהּ, אֶלָּא בְּאִינּוּן בְּתוּלְתָּן עוּלֶמְתָּהָא, דְּיֵיתוּן עִמָּהּ, וּמְדַּבְּרָן לָהּ, עַד דְּמָטַת לְבַעְלָהּ, כְּמָה דְּאַתְּ אָמַר, (תהילים מ״ה:ט״ו) בְּתוּלוֹת אַחֲרֶיהָ רְעוּתֵיהּ וְגוֹ', וְכָל כַּךְ לָמָּה, לְמֵיתֵי לְאִתְחַבְּרָא בְּבַעְלָהּ.","(שמות ל״ה:ה׳) כֹּל נְדִיב לִבּוֹ, אִלֵּין אִינּוּן אַרְבַּע מַשִׁרְיָין עִלָּאִין, דְּבִכְלָלָא דִּלְהוֹן כְּלִילָן, כָּל אִינּוּן שְׁאַר מַשִׁרְיָין, וְאִלֵּין אִינּוּן דְּנַפְקָן בַּאֲבָהָן עִלָּאִין, דְּאִקְרוּן נְדִּיבִים. כְּמָה (ויקרא י\"ט ע\"ב, כ\"ד ע\"א, ק\"נ ע\"ב) דְּאוּקְמוּהָ, דִּכְתִּיב, (במדבר כ״א:י״ח) כָּרוּהָ נְדִיבֵי הָעָם, אִלֵּין אֲבָהָן.","יְבִיאֶהָ, יְבִיאוּהָ לָא כְּתִיב, אֶלָּא יְבִיאֶהָ, לְיַחֲדָא כֹּלָּא כַּחֲדָא. וְכֵן יָבִיא לָא כְּתִיב, אֶלָּא יְבִיאֶהָ, לְסַלְּקָא לָהּ לְגַבֵּי בַּעְלָהּ בִּיקָרָא, כְּמָה דְּאִצְטְרִיךְ. אֵת תְּרוּמַת יְיָ', אֶת לְאַסְגָּאָה, כָּל אִינּוּן מַשִׁרְיָין עִלָּאִין אַחֲרָנִין, לְאִתְחַבְּרָא כֹּלָּא כַּחֲדָא, וְאִינּוּן תְּרֵיסַר בִּכְלָלָא חֲדָא. זָהָב. וָכֶסֶף. וּנְחוֹשֶׁת. תְּכֵלֶת. וְאַרְגָּמָן. וְתוֹלַעַת שָׁנִי. וְשֵׁשׁ וְעִזִּים. וְעֹרֹת אֵלִים מְאָדָּמִים. וְעֹרֹת תְּחָשִׁים. וַעֲצֵי שִׁטִּים. וְשֶׁמֶן לַמָּאוֹר. וּבְשָׂמִים לְשֶׁמֶן הַמִּשְׁחָה. וְלִקְטֹרֶת הַסַּמִּים. אִלֵּין אִינּוּן תְּרֵיסַר מַשִׁרְיָין עִלָּאִין, דִּכְלִילָן כֻּלְּהוּ כַּחֲדָא בִּכְלָלָא דְּאַרְבַּע דְּאִקְרוּן חַיוֹת הַקֹּדֶשׁ כְּמָה דְּאִתְּמַר.","וְכֻלְּהוּ אִלֵּין סַלְּקִין לְכֻרְסְיָיא קַדִּישָׁא, לְאָעֲלָא לָהּ לְעֵילָּא, לְאִתְחַבְּרָא בְּבַעְלָהּ, בְּגִין לְמֶהֱוֵי כֹּלָּא חַד, בְּגִין דְּיִשְׁתְּכַח עִמָּהּ בִּיקָרָא עִלָּאָה. כְּדֵין יָתִיב מַלְכָּא עִלָּאָה עַל כּוּרְסְיָּיא קַדִּישָׁא, וְאִתְחַבְּרָא אִתְּתָא בְּבַעְלָהּ, לְמֶהוֵי כֹּלָּא חַד. וּכְדֵין, אִיהוּ חֶדְוָותָא דְּכֹלָּא.","תָּא חֲזֵי, הָכָא שָׁארֵי לְמִמְנֵי זָהָב בְּקַדְמִיתָא, וְכֶסֶף לְבָתַר, בְּגִין דְּהַאי חֶשְׁבֹּנָא מִתַּתָּא. אֲבָל כַּד אָתֵי לְמִמְנֵי מֵחוּשְׁבָּנָא דִּרְתִיכָא דִּלְעֵילָּא, שָׁארֵי לְמִמְנִי מִימִינָא בְּקַדְמִיתָא, וּלְבָתַר מִן שְׂמָאלָא. מְנָלָן. דִּכְתִּיב, (חגי ב׳:ח׳) לִי הַכֶּסֶף וְלִי הַזָּהָב. כֶּסֶף בְּקַדְמִיתָא, וּלְבָתַר הַזָּהָב. וּבִרְתִיכָא דִּלְתַתָּא, שָׁארוּ מִשְּׂמָאלָא וּלְבָתַר מִימִינָא, דִּכְתִּיב זָהָב וָכֶסֶף וּנְחֹשֶׁת. זָהָב בְּקַדְמִיתָא, וּלְבָתַר כֶּסֶף.","וְכָל אִינּוּן רְתִיכִין אִקְרוּן נְדִיב לֵב. כֹּל: לְאַכְלְלָא כָּל שְׁאַר רְתִיכִין. לֵב. מַאי לֵב. הַיְינוּ רָזָא דִּכְתִּיב, (משלי ט״ו:ט״ו) וְטוֹב לֵב מִשְׁתֶּה תָּמִיד. וְדָא אִיהוּ לִבָּא דְּכֹלָּא, וְדָא כֻּרְסְיָיא קַדִּישָׁא. וְעַל דָּא אִקְרוּן לֵב. כֹּל נְדִיב לֵב, כְּמָה דְּאוֹקִימְנָא, דְּאַרְבַּע מַשִׁרְיָין אִלֵּין, כְּלָלָא דְּכֻלְּהוּ אִקְרוּן בְּרָזָא חֲדָא, נְדִיב לֵב. תְּרוּמַת יְיָ', דָּא כֻּרְסְיָיא קַדִּישָׁא. וּבְגִין דְּאָרִימוּ לָהּ לְעֵילָּא, וְסַלְּקִין לָהּ לְעֵילָּא, אִקְרֵי תְּרוּמַת יְיָ'."],[[0,"מי הקים כל אפסי ארץ:","זה אליהו שאחר שצרר המים, ונשבע על המטר, הנה אח\"כ חזר בתפלה, והקים כל העולם, שירד מטר, וניתן מזון לכל. \u0003מה שמו,\u0004 זה אליהו. \u0003ומה שם בנו,\u0004 זה אליהו, ומפרש מה שמו, כשעלה למעלה, הוא אליהו. ומה שם בנו, היינו כשירד למטה, ונעשה שליח לעשות נסים, שמו אליהו."],[1,"דבר אחר, מ\"י עלה שמים:","זהו הקב\"ה, כמו שלמדנו, וסוד הדבר הוא מ\"ש \u0003מ\"י,\u0004 וכבר העמדנו. שהוא שם הבינה. והפירוש הוא, ששמים שהוא ז\"א מעלה את הבינה שנקראת \u0003מ\"י,\u0004 שכאן יש הסוד של המרכבה העליונה, שהם ד' רוחות העולם, דהיינו ד' ספירות חגת\"מ שמחזה ולמעלה דז\"א, שהם מרכבה לבינה הנקראת \u0003מ\"י\u0004 שהם יסודות הראשונים לכל, וכולם תלוים במקום שנקרא \u0003מ\"י,\u0004 דהיינו שהם מרכבה לה. כמו שלמדנו."],[2,"ת\"ח כד קיימא","וכו': בוא וראה, כשנמצאת שעת רצון לפני הקב\"ה, ליחד מרכבה עליונה במרכבה תחתונה, שתהיינה כולן אחת, אז יוצא קול ממקום קדוש העליון, הנקרא שמים, דהיינו ז\"א, ומקהיל כל אלו הקדושים שלמטה שהם הצדיקים שבעולם הזה, וכל השרים הקדושים, שהם מיכאל גבריאל אוריאל רפאל. וכל מחנות העליונים, שהם המלאכים. שיהיו כולם מוכנים יחד. ז\"ש, \u0003ויקהל משה,\u0004 זהו סוד השמים, דהיינו ז\"א. את כל עדת בני ישראל, אלו הם י\"ב מחנות עליונים הקדושים. שהם המרכבה התחתונה, שהמלכות רוכבת עליהם, והם מעלים, את המלכות לזווג עם ז\"א."],[2,"","וסוד אלו ב' מרכבות, המקבלות זו מזו, נתבאר באורך לעיל (בראשית א' דף פ\"ה ד\"ה ביאור) וסוד מרכבה העליונה, הוא חגת\"ם שלמעלה מחזה דז\"א, שהם ד' רגלי הכסא של הבינה. והם י\"ב, כי כל אחד מחגת\"ם כלול מחג\"ת. ועד\"ז מרכבה תחתונה היא ד' ספירות נהי\"מ של הנוקבא (כמ\"ש בראשית א' דף צ' ד\"ה כורסיא.) שהם נק' ד' חיות או ד' מלאכים מיכאל גבריאל אוריאל רפאל. או ד' מחנות מלאכים. וגם הם סוד י\"ב, כי כל אחד מד' ספירות נהי\"מ כלולה מנה\"י. כמו שנתבאר בחגת\"ם. ועד\"ז ד' המלאכים, וד' המחנות, וה\"ס \u0003תריסר משריין עלאין קדישין,\u0004 שאומר כאן. כי ד' מחנות מלאכים כלול כל מחנה מג' מחנות, והם הנושאות את הכסא, שהוא המלכות, לזווג עם ז\"א (כמ\"ש לעיל ב\"א דף צ' ד\"ה כורסיא)."],[3,"ויאמר אליהם:","ומה אמר, היינו זה הדבר וגו' \u0003קחו מאתכם תרומה,\u0004 שפירושו, התתקנו כלכם להעלות עליכם, ולשאת עליכם, את כבוד הכסא הקדוש, שהוא המלכות, להעלות למעלה, לז\"א."],[4,"אפרישו מנייכו אינון","וכו': הפרישו מכם אלו היקרים, אלו שרים העליונים, שהם מיכאל גבריאל אוריאל רפאל, להעלות תרומה הזו, שהיא סוד הכסא הקדוש, דהיינו מלכות, להתחבר בהאבות, שהם חג\"ת דז\"א. והמטרוניתא שהיא המלכות, אינה ראויה לבא לבעלה, אלא באלו בתולות עלמות הבאות עמה ומנהיגות אותה עד שמגעת לבעלה, ז\"א. כמו שאתה אומר, בתולות אחריה רעותיה וגו', וכל כך למה, הוא להביאה להתחבר בבעלה, ז\"א."],[4,"","פירוש. סוד הבתולות, הן המדרגות הנמשכות מבחינות אחורים דמלכות, והם ז' היכלות דבריאה, שה\"ס ז' הנערות הראויות לתת לה מבית המלך. וה\"ס בתולות אחריה רעותיה מובאות לך. כי להיות המלכות בשעת גדלותה רק בכלים דחסדים, לפיכך היא צריכה לז' הנערות שישלימו את הכלים דאחורים שלה, כי הארת החכמה אינה מתלבשת רק בכלים דאחורים. (כנ\"ל בהקסה\"ז דף ז' ד\"ה ובגין ע\"ש). וז\"ש, \u0003דהא מטרוניתא לא אתחזי למיתי לבעלה אלא באינון בתולתן עולמתהא,\u0004 שהם משלימים הכלים דאחורים שלה."],[5,"כל נדיב לבו:","אלו הם ארבע מחנות מלאכים העליונים, הנמשכים מן נהי\"מ דמלכות, שבכללם כלולים כל אלו שאר המחנות, דהיינו י\"ב המחנות. כי כל אחד מן הארבע כלול מג', הם י\"ב כנ\"ל. ואלו הם היוצאים מן האבות העליונים, חג\"ת, הנקראים נדיבים. כמו שהעמידוהו, שכתוב, בבאר, כרוה נדיבי עם, שהם האבות. כי החג\"ת בנו את הבאר, שהיא המלכות, ותקנו אותה. ונמצא שנהי\"מ דמלכות הם יוצאים מחג\"ת דז\"א. וע\"כ יש בהם סוד י\"ב, כמו בחג\"ת דז\"א."],[6,"יביאה יביאוה וכו':","שואל, יביאה כתוב, ולא כתוב, יביאוה. ואומר, אלא יביאה שהוא לשון יחיד, יורה ליחד הכל כאחד, דהיינו זו\"ן וכן יביא לא כתוב, אלא יביאה, שיורה על המלכות הנקראת תרומה, שיעלה אותה אל בעלה ביקר כמו שצריך. \u0003את תרומת ה',\u0004 את, בא לרבות כל אלו מחנות מלאכים האחרים, להתחבר הכל יחד, והם י\"ב מחנות בכלל אחד, שהם, זהב וכסף ונחשת וגו', שהם י\"ב מינים, אלו הם י\"ב מחנות העליונים, שכלולים כולם יחד בכלל הארבע, הנקראות חיות הקודש. כי כל חיה כלולה מן ג', והם י\"ב. כמ\"ש אצל חג\"ת, כנ\"ל בדבור הסמוך."],[7,"וכלהו אלין סלקין וכו':","וכל אלו עולים אל הכסא הקדוש, שהוא המלכות, להעלותה למעלה להתחבר בבעלה, ז\"א, כדי שיהיה הכל אחד. כדי שימצא עמה ביקר העליון. אז יושב מלך העליון על כסא הקדוש, ונתחברה אשה בבעלה, מלכות בז\"א, להיות הכל אחד. ואז הוא שמחת הכל."],[8,"ת\"ח הכא שארי וכו':","בוא וראה, כאן מתחיל למנות זהב בתחילה ואח\"כ כסף, משום שחשבון ההוא, הוא ממטה למעלה, שנמצא גבורה שהוא זהב קודמת לכסף שהוא חסד. אבל כשבא לחשוב מחשבון המרכבה שלמעלה, מתחיל למנות מימין בתחילה, שהוא כסף, ואח\"כ משמאל, שהוא זהב. מאין לנו כי כתוב, לי הכסף ולי הזהב, כסף תחילה ואח\"כ זהב. משום שהמדובר הוא למעלה. ובמרכבה שלמטה, שהוא המלכות, מתחיל משמאל ואח\"כ מימין, שכתוב, זהב וכסף ונחשת. זהב תחילה ואח\"כ כסף."],[9,"וכל אינון רתיכין וכו':","וכל אלו המרכבות נקראות, \u0003נדיב לב. כל\u0004 מה שנאמר, כל נדיב לב, הוא לכלול כל שאר המרכבות שהם י\"ב. מהו לב. היינו סוד הכתוב, וטוב לב משתה תמיד, שזהו הלב של הכל, וזהו כסא הקדוש. שהוא המלכות. וע\"כ נקראים, לב. \u0003כל נדיב לב.\u0004 הוא כמו שהעמדנו, שארבע מחנות הם כלל כולם, שכל אחת כוללת ג' והם י\"ב, וכולם נקראים בסוד אחד, \u0003נדיב לב. תרומת ה',\u0004 זהו כסא הקדוש. ומשום שהרימו אותו למעלה והעלוה למעלה, לז\"א, הוא נקרא תרומת ה'."]],[[0,"","מִי הֵקִים כָּל אַפְסֵי אָרֶץ - זֶה אֵלִיָּהוּ, שֶׁלְּאַחַר שֶׁצָּרַר מַיִם וְנִשְׁבַּע עַל (המטר) הַשָּׁמַיִם, אַחַר כָּךְ חָזַר בִּתְפִלָּתוֹ וְהֵקִים כָּל הָעוֹלָם וְהוֹרִיד מָטָר וְנִתַּן מָזוֹן לַכֹּל. מַה שְּׁמוֹ - זֶה אֵלִיָּהוּ. וּמַה שֶּׁם בְּנוֹ - זֶה אֵלִיָּהוּ. מַה שְּׁמוֹ - כְּשֶׁעָלָה לְמַעְלָה, אֵלִיָּהוּ. וּמַה שֶּׁם בְּנוֹ - כְּשֶׁיָּרַד לְמַטָּה וְנַעֲשָׂה שָׁלִיחַ לַעֲשׂוֹת נִסִּים, אֵלִיָּהוּ שְׁמוֹ."],[1,"","דָּבָר אַחֵר מִי עָלָה שָׁמַיִם - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁבֵּאַרְנוּ. וְסוֹד הַדָּבָר - מִ\"י, וַהֲרֵי בֵּאַרְנוּ. וְכָאן הוּא סוֹד הַמֶּרְכָּבָה הָעֶלְיוֹנָה, אַרְבָּעָה צִדְדֵי הָעוֹלָם שֶׁהֵם יְסוֹדוֹת רִאשׁוֹנִים שֶׁל הַכֹּל, וְכֻלָּם תְּלוּיִים בְּאוֹתוֹ מָקוֹם עֶלְיוֹן שֶׁנִּקְרָא מִ\"י, כְּמוֹ שֶׁנִּתְבָּאֵר."],[2,"","בֹּא וּרְאֵה, כְּשֶׁעָמְדָה שְׁעַת רָצוֹן לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא לְיַחֵד הַמֶּרְכָּבָה הָעֶלְיוֹנָה (במרכבההתחתונה) לִהְיוֹת הַכֹּל אֶחָד, אָז יָצָא קוֹל מֵאוֹתוֹ מָקוֹם עֶלְיוֹן קָדוֹשׁ שֶׁנִּקְרָא שָׁמַיִם, וְכִנֵּס אֶת כָּל אוֹתָם קְדוֹשִׁים שֶׁלְּמַטָּה, וְכָל אוֹתָם גְּדוֹלִים קְדוֹשִׁים וּמַחֲנוֹת הָעֶלְיוֹנִים, לִהְיוֹת כֻּלָּם מְזֻמָּנִים כְּאֶחָד. זֶהוּ שֶׁכָּתוּב וַיַּקְהֵל מֹשֶׁה, זֶה סוֹד שֶׁל שָׁמַיִם. אֶת כָּל עֲדַת בְּנֵי יִשְׂרָאֵל - אֵלֶּה הֵם שְׁנֵים עָשָׂר מַחֲנוֹת עֶלְיוֹנִים קְדוֹשִׁים."],[3,"","וַיֹּאמֶר אֲלֵהֶם. וּמָה אָמַר? זֶה הַדָּבָר וְגוֹ', קְחוּ מֵאִתְּכֶם תְּרוּמָה. הִתְתַּקְּנוּ כֻלְּכֶם לְהַעֲלוֹת עֲלֵיכֶם וְלִטֹּל עֲלֵיכֶם כְּבוֹד הַכִּסֵּא הַקָּדוֹשׁ לַעֲלוֹת לְמַעְלָה."],[4,"","הַפְרִידוּ מִכֶּם אוֹתָם נִכְבָּדִים, אוֹתָם גְּדוֹלִים עֶלְיוֹנִים לְהַעֲלוֹת אֶת אוֹתָהּ תְּרוּמָה, סוֹד הַכִּסֵּא הַקָּדוֹשׁ, לְהִתְחַבֵּר בָּאָבוֹת (בבעלה), שֶׁהֲרֵי הַגְּבִירָה אֵינָהּ רְאוּיָה לָבֹא לְבַעְלָה אֶלָּא בְּאוֹתָן בְּתוּלוֹת עַלְמוֹתֶיהָ, שֶׁיָּבאוּ עִמָּהּ וּמַנְהִיגוֹת אוֹתָהּ, עַד שֶׁמַּגִּיעָה לְבַעְלָהּ, כְּמוֹ שֶׁנֶּאֱמַר (תהלים מה) בְּתוּלוֹת אַחֲרֶיהָ רֵעוֹתֶיהָ וְגוֹ'. וְכָל כָּךְ לָמָּה? כְּדֵי לָבֹא לְהִתְחַבֵּר עִם בַּעְלָהּ."],[5,"","כֹּל נְדִיב לִבּוֹ - אֵלּוּ אוֹתָם אַרְבָּעָה מַחֲנוֹת עֶלְיוֹנִים שֶׁבִּכְלָלָם כְּלוּלִים כָּל אוֹתָם שְׁאָר הַמַּחֲנוֹת, וְאֵלֶּה הֵם שֶׁיּוֹצְאִים בָּאָבוֹת הָעֶלְיוֹנִים שֶׁנִּקְרָאִים נְדִיבִים, כְּמוֹ שֶׁבֵּאֲרוּהָ, שֶׁכָּתוּב (במדבר כא) כָּרוּהָ נְדִיבֵי הָעָם, אֵלּוּ הָאָבוֹת."],[6,"","יְבִיאֶהָ, לֹא כָתוּב יְבִיאוּהָ, אֶלָּא יְבִיאֶהָ, לְיַחֵד הַכֹּל כְּאֶחָד. וְכֵן לֹא כָתוּב יָבִיא, אֶלָּא יְבִיאֶהָ, לְהַעֲלוֹתָהּ לְבַעְלָהּ בְּכָבוֹד כְּמוֹ שֶׁצָּרִיךְ. אֵת תְּרוּמַת ה' - אֶת, לְרַבּוֹת כָּל אוֹתָם הַמַּחֲנוֹת הָעֶלְיוֹנִים הָאֲחֵרִים, לְחַבֵּר הַכֹּל כְּאֶחָד, וְהֵם שְׁנֵים עָשָׂר בִּכְלָל אֶחָד. זָהָב. וָכֶסֶף. וּנְחֹשֶׁת. תְּכֵלֶת. וְאַרְגָּמָן. וְתוֹלַעַת שָׁנִי. וְשֵׁשׁ וְעִזִּים. וְעֹרֹת אֵילִם מְאָדָּמִים. וְעֹרֹת תְּחָשִׁים. וַעֲצֵי שִׁטִּים. וְשֶׁמֶן לַמָּאוֹר. וּבְשָׂמִים לְשֶׁמֶן הַמִּשְׁחָה. וְלִקְטֹרֶת הַסַּמִּים. אֵלּוּ הֵם שְׁנֵים עָשָׂר מַחֲנוֹת עֶלְיוֹנִים, שֶׁכֻּלָּם כְּלוּלִים כְּאֶחָד בִּכְלָל שֶׁל אַרְבָּעָה שֶׁנִּקְרְאוּ חַיּוֹת הַקֹּדֶשׁ, כְּמוֹ שֶׁנִּתְבָּאֵר."],[7,"","וְכָל אֵלֶּה עוֹלִים לַכִּסֵּא הַקָּדוֹשׁ לְהַעֲלוֹתוֹ לְמַעְלָה לְהִתְחַבֵּר עִם בַּעְלָהּ כְּדֵי לִהְיוֹת הַכֹּל אֶחָד, וּכְדֵי שֶׁיִּמָּצֵא עִמָּהּ בְּכָבוֹד עֶלְיוֹן. וְאָז יוֹשֵׁב הַמֶּלֶךְ הָעֶלְיוֹן עַל הַכִּסֵּא הַקָּדוֹשׁ, וּמִתְחַבֶּרֶת אִשָּׁה עִם בַּעְלָהּ לִהְיוֹת הַכֹּל אֶחָד, וְאָז הִיא שִׂמְחַת הַכֹּל."],[8,"","בֹּא וּרְאֵה, כָּאן מַתְחִיל לִמְנוֹת זָהָב בָּרִאשׁוֹנָה, וְאַחַר כָּךְ כֶּסֶף, מִשּׁוּם שֶׁהַחֶשְׁבּוֹן הַזֶּה מִלְּמַטָּה. אֲבָל כְּשֶׁבָּא לִמְנוֹת מֵחֶשְׁבּוֹן הַמֶּרְכָּבָה הָעֶלְיוֹנָה, מַתְחִיל לִמְנוֹת מִיָּמִין בָּרִאשׁוֹנָה, וְאַחַר כָּךְ מִשְּׂמֹאל. מִנַּיִן לָנוּ? שֶׁכָּתוּב (חגי ב) לִי הַכֶּסֶף וְלִי הַזָּהָב. כֶּסֶף בַּתְּחִלָּה וְאַחַר כָּךְ הַזָּהָב. וּבַמֶּרְכָּבָה שֶׁלְּמַטָּה מַתְחִילִים מִשְּׂמֹאל וְאַחַר כָּךְ מִיָּמִין, שֶׁכָּתוּב זָהָב וָכֶסֶף וּנְחֹשֶׁת. זָהָב בַּתְּחִלָּה וְאַחַר כָּךְ כֶּסֶף."],[9,"","וְכָל אוֹתָן מֶרְכָּבוֹת נִקְרָאוֹת נְדִיב לֵב. כֹּל - לִכְלֹל אֶת כָּל שְׁאָר הַמֶּרְכָּבוֹת. לֵב, מַה זֶּה לֵב? הַיְנוּ סוֹד הַכָּתוּב (משלי טו) וְטוֹב לֵב מִשְׁתֶּה תָּמִיד. וְזֶהוּ הַלֵּב שֶׁל הַכֹּל, וְזֶהוּ הַכִּסֵּא הַקָּדוֹשׁ, וְעַל זֶה נִקְרָאִים לֵב. כֹּל נְדִיב לֵב, כְּמוֹ שֶׁבֵּאַרְנוּ, שֶׁאַרְבַּעַת הַמַּחֲנוֹת הַלָּלוּ הַכְּלָל שֶׁל כֻּלָּם נִקְרָאִים בְּסוֹד אֶחָד, נְדִיב לֵב. תְּרוּמַת ה' - זֶה הַכִּסֵּא הַקָּדוֹשׁ. וּמִשּׁוּם שֶׁהֵרִימוּ אוֹתָהּ לְמַעְלָה וּמַעֲלִים אוֹתָהּ לְמַעְלָה, נִקְרֵאת תְּרוּמַת ה'."]]],[["וְעַל דָּא, כַּד חָמָא יְחֶזְקֵאל רָזָא דְּחַיּוֹת, דַּהֲווֹ סַלְּקִין, לָא חָמָא מַהוּ דְּסַלְּקִין, בְּגִין דְּאִיהִי סַלְּקָא לְגַבֵּי מַלְכָּא עִלָּאָה בִּגְנִיזוּ בִּטְמִירָא בִּיקָרָא עִלָּאָה.","(שמות ל״ה:י׳) וְכָל חָכָם לֵב בָכֶם, אִלֵּין אִינּוּן שִׁתִּין מְקוֹרִין, דְּאַשְׁקְיָיא עָלְמָא, וּמִנְּהוֹן אִתְשָׁקֵי. יָבֹאוּ, אֲמַאי יָבֹאוּ. אֶלָּא דְּיֵיתוּן לְמִנְקַט מֵעִם גְּנָזָא דְּחַיִּין. יָבֹאוּ, וּלְבָתַר וַיַּעֲשׂוּ מָה דְּקוּדְשָׁא בְּרִיךְ הוּא פָּקִיד לוֹן לְאַהֲנָאָה עָלְמָא.","(שמות ל״ה:ה׳) קְחוּ מֵאִתְּכֶם תְּרוּמָה לַיְיָ'. רִבִּי יְהוּדָה פָּתַח, (ישעיהו נ״ח:ז׳) הֲלֹא פָרוֹס לָרָעֵב לַחְמֶךָ וְגוֹ'. תָּא חֲזֵי, זַכָּאָה חוּלָקֵיהּ דְּבַר נָשׁ, כַּד מִסְכְּנָא אִעְרַע לְגַבֵּיהּ. דְּהַהוּא מִסְכְּנָא דּוֹרוֹנָא דְּקוּדְשָׁא בְּרִיךְ הוּא הוֵי, דְּשָׁדַר לֵיהּ. מַאן דִּמְקַבֵּל לֵיהּ לְהַהוּא דּוֹרוֹנָא בְּסֵבֶר אַנְפִּין, זַכָּאָה חוּלָקֵיהּ.","תָּא חֲזֵי, מַאן דְּחָיִיס לְמִסְכְּנָא, וְאָתִיב לֵיהּ נַפְשֵׁיהּ, קוּדְשָׁא בְּרִיךְ הוּא סָלִיק עָלֵיהּ, כְּאִילּוּ הוּא בָּרָא לְנַפְשֵׁיהּ. וְעַל דָּא אַבְרָהָם דְּהֲוָה חָיִיס לְכָל בְּנִי עָלְמָא, סָלִיק עָלֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, כְּאִילּוּ הוּא בָּרָא לוֹן, דִּכְתִּיב, (בראשית י״ב:ה׳) וְאֶת הַנֶּפֶשׁ אֲשֶׁר עָשׂוּ בְחָרָן.","וְאַף עַל גַּב דְּהָא אוֹקִימְנָא הֲלא פָרוֹס, מַאי פָרוֹס, לְמִפְרַס לֵיהּ מַפָּה בְּנָהֲמָא וּמְזוֹנָא לְמֵיכַל. דָּבָר אַחֵר הֲלא פָרוֹס, כְּמָה דְאַתְּ אָמֵר (דניאל ה׳:כ״ח) פְּרֵיס פְּרִיסַת וְגוֹ'. דְּבָעֵי לְמִפְרַס פְּרִיסִין דְּנַהֲמָא קָמֵיהּ, בְּגִין דְּלָא לִכְסִיף. וְיַפְרוֹס קָמֵיהּ בְּעֵינָא טָבָא. לַחְמֶךָ, לֶחֶם לָא כְּתִיב, אֶלָּא לַחְמֶךָ. הַהוּא דִּילָךְ מִמָּמוֹנֶךָ, וְלָא דִּגְזִילוּ, וְלָא דַּעֲשָׁק, וְלָא דִּגְנֵבָה. דְּאִי הָכִי, לָאו זְכוּתָא הוּא, אֶלָּא וַוי לֵיהּ, דְּאָתֵי לְאַדְכְּרָא חוֹבוֹי. כְּגַוְונָא דָּא קְחוּ מֵאִתְּכֶם תְּרוּמָה, לְאָרָמָא מִמָּה דִּלְכוֹן, וְלָא מֵעֹשֶׁק, וְלָא מִגֶּזֶל, וְלָא מִגְּנֵבָה, וְהָא אוּקְמוּהָ.","רִבִּי חִיָּיא וְרִבִּי יִצְחָק וְרִבִּי יוֹסֵי, הֲווֹ אַזְלֵי בְּאָרְחָא, עַד דַּהֲווֹ אָזְלֵי, פָּגַע בְּהוּ רִבִּי אַבָּא. אָמַר רִבִּי חִיָּיא, וַדַּאי שְׁכִינְתָּא בַּהֲדָן. כַּד מָטָא לְגַבַּיְיהוּ, אָמַר רִבִּי אַבָּא, כְּתִיב, (מלכים א ח׳:ט״ז) מִן הַיּוֹם אֲשֶׁר הוֹצֵאתִי אֶת עַמִּי אֶת יִשְׂרָאֵל מִמִּצְרַיִם לֹא בָחַרְתִּי בְעִיר מִכֹּל שִׁבְטֵי יִשְׂרָאֵל וָאֶבְחַר בְּדָוִד וְגוֹ' לִבְנוֹת בַּיִת לִהְיוֹת שְׁמִי שָׁם. הַאי קְרָא, לָאו רֵישֵׁיהּ סֵיפֵיהּ, וְלָאו סֵיפֵיהּ רֵישֵׁיהּ, דִּכְתִּיב לא בָחַרְתִּי בְּעִיר, וָאֶבְחַר בְּדָוִד, מַאי הַאי עִם הַאי. וָאֶבְחַר בִּיְרוּשָׁלַ ם מִבָּעֵי לֵיהּ.","אֶלָּא כַּד קוּדְשָׁא בְּרִיךְ הוּא אִית רְעוּתָא קָמֵּיהּ לְמִבְנִי קַרְתָּא, אִסְתָּכָּל בְּקַדְמִיתָא, בְּהַהוּא רֵישָׁא דְּנָהִיג עַמָּא דְּקַרְתָּא, וּלְבָתַר בְּנִי קַרְתָּא, וְאַיְיתֵי לְעַמָּא בֵּיהּ. הֲדָא הוּא דִכְתִיב לֹא בָחַרְתִּי בְּעִיר, עַד דְּאִסְתַּכַּלְנָא בְּדָוִד, לְמֶהוֵי רַעְיָא עַל יִשְׂרָאֵל. בְּגִין דְּמָתָא וְכָל בְּנִי מָתָא, כֻּלְּהוּ קַיְימִין בְּרַעֲיָּא דְּנָהִיג לְעַמָּא, אִי רַעְיָא אִיהוּ טָבָא, טָב לֵיהּ, טָב לְמָתָא, טָב לְעַמָּא. וְאִי רַעְיָא אִיהוּ בִּישָׁא, וַוי לֵיהּ, וַוי לְמָתָא וַוי לְעַמָּא. וְהַשְׁתָּא אִסְתָּכָּל קוּדְשָׁא בְּרִיךְ הוּא בְּעָלְמָא, וְסָלִיק בִּרְעוּתֵיהּ לְמִבְנֵי לֵיהּ, וְאוֹקִים בְּרֵישָׁא לְדָוִד, הֲדָא הוּא דִכְתִיב וָאֶבְחַר בְּדָוִד עַבְדִי. (ס\"א ואוקים ברישא דדרא לרבי שמעון וחבריה למיקם קמיה)","מִלְּתָא חַדְתָּא שְׁמַעְנָא. פָּתַח וְאָמַר, (תהילים קמ״ו:ה׳) אַשְׁרֵי שֶׁאֵל יַעֲקֹב בְּעֶזְּרוֹ שִׂבְרוֹ עַל יְיָ' אֱלהָיו. וְכִי אֵל יַעֲקֹב, וְלָא אֵל אַבְרָהָם, וְלָא אֵל יִצְחָק, אֶלָּא אֵל יַעֲקֹב. בְּגִין דְּיַעֲקֹב לָא אִתְרְחִיץ בַּאֲבוֹהִי, וְלָא בְּאִמֵיהּ, כַּד עָרַק קַמֵּי אֲחוּי, וְאָזַל יְחִידָאי, בְּלָא מָמוֹנָא, כְּמָה דְאַתְּ אָמֵר (בראשית ל״ב:י״א) כִּי בְמַקְלִי עָבַרְתִּי אֶת הַיַּרְדֵּן הַזֶּה, וְאִיהוּ אִתְרְחִיץ בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, דִּכְתִּיב, (שם כח) אִם יִהְיֶה אֱלֹהִים עִמָּדִי וּשְׁמָרַנִי וְגוֹ'. וְכֹלָּא שָׁאִיל מִקַּמֵּיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, וְיָהַב לֵיהּ.","שִׂבְרוֹ עַל יְיָ' אֱלֹהָיו. שִׂבְרוֹ, וְלָא אָמַר תִּקְוָתוֹ, וְלָא בִּטְחוֹנוֹ, אֶלָּא שִׂבְרוֹ. אַל תִּקְרֵי שִׂבְרוֹ, אֶלָּא שִׁבְרוֹ. דְּנִיחָא לְהוּ לְצַדִּיקַיָּיא, לְתַּבְרָא גַּרְמַיְיהוּ, וּלְאִתְבְּרָא תְּבִירוּ עַל תְּבִירוּ, וְכֹלָּא עַל יְיָ' אֱלהָיו. כְּמָה דְאַתְּ אָמֵר, (תהלים מה) כִּי עָלֶיךָ הוֹרַגְנוּ כָל הַיּוֹם. כִּי עָלֶיךָ נָשָׂאנוּ חֶרְפָּה."],[[0,"ועל דא כד חמא יחזקאל וכו':","ועל כן כשראה יחזקאל סוד החיות, שהיו מעלות את המלכות לזווג, לא ראה מה שמעלות דהיינו המלכות הרוכבת עליהן, משום שהיא עלתה למלך העליון, ז\"א, בהעלם ובסתר ביקר העליון."],[1,"וכל חכם לב בכם:","אלו הם ששים מקורות, דהיינו חג\"ת נה\"י דז\"א שכל אחד כולל עשרה, המשקים את העולם, שהוא מלכות. ומהם היא נשקה. \u0003יבאו,\u0004 למה כתוב יבואו. ומשיב, אלא שיבואו לקבל מן אוצר החיים, שהוא בינה. אח\"כ יעשו מה שהקב\"ה שהיא בינה מצוה אותם להנות העולם."],[2,"קחו מאתכם תרומה לה':","ר' יהודה פתח, הלא פרוס לרעב לחמך וגו'. בוא וראה, אשרי חלקו של אדם כשעני יבא אליו. כי עני ההוא, הוא מתנה שהקב\"ה שלח לו, מי שמקבל מתנה ההיא בקבלת הפנים, אשרי חלקו."],[3,"תא חזי מאן וכו':","בוא וראה. מי שמרחם על העני ומשיב לו נפשו. הקב\"ה מעלה עליו, כאלו הוא ברא את נפשו. וע\"כ אברהם, שהיה מרחם על כל בני העולם, העלה עליו הקב\"ה, כאלו הוא ברא אותם. שכתוב, ואת הנפש אשר עשו בחרן."],[4,"ואע\"ג דהא אוקימנא וכו':","ואע\"פ שהעמדנו הכתוב, \u0003הלא פרוס,\u0004 שמהו פרוס, הוא לפרוש לו מפה בלחם ומזון לאכול, הנה פירוש אחר, \u0003הלא פרוס\u0004 הוא כמש\"א, פריס פריסת וגו', שצריכים לחתוך חתיכות לחם לפניו, כדי שלא יתבייש. ויחתוך לפניו בעין טובה. \u0003לחמך,\u0004 לחם לא כתוב. אלא לחמך, יורה, שהלחם יהיה שלך, מכספך, ולא מגזילה, ולא מעשק ולא מגנבה. כי אם כן, אינו זכות, אלא אוי לו, שבא להזכיר עונו. כעין זה קחו מאתכם תרומה, הוא להרים ולתת ממה שלכם, ולא מעשק, ולא מגזל, ולא מגנבה. וכבר העמדנו."],[5,"רבי חייא ורבי יצחק וכו':","ר\"ח ור\"י ור' יוסי היו הולכים בדרך, בעוד שהיו הולכים פגש בהם ר' אבא. אמר ר' חייא, ודאי השכינה עמנו. כשהגיע אצלם, אמר ר' אבא, כתוב, מן היום אשר הוצאתי את עמי את ישראל ממצרים לא בחרתי בעיר מכל שבטי ישראל, ואבחר בדוד וגו', לבנות בית להיות שמי שם. מקרא זה, אין ראשו סופו ואין סופו ראשו, שכתוב, לא בחרתי בעיר, ואבחר בדוד, מה זה עם זה, היה צריך לומר, ואבחר בירושלים."],[6,"אלא כד קודשא ב\"ה וכו':","אלא כשהקב\"ה יש לו רצון לבנות עיר, מסתכל תחלה בראש ההוא, המנהיג את עם העיר, ואח\"כ בונה את העיר, ומביא בה את העם. ז\"ש לא בחרתי בעיר, עד שהסתכלתי בדוד, שיהיה רועה על ישראל. משום שהעיר וכל בני העיר, כולם תלוים ברועה המנהיג העיר, אם הרועה הוא טוב, טוב לו, טוב לעיר, טוב לעם. ואם הרועה הוא רע, אוי לו, אוי לעיר, אוי לעם, ועתה הסתכל הקב\"ה בעולם ועלה ברצונו לבנותו, והקים תהילה את דוד. ז\"ש ואבחר בדוד עבדי."],[7,"מלתא חדתא שמענא וכו':","דבר חדש שמעתי. פתח ואמר, אשרי שאל יעקב בעזרו שברו על ה' אלקיו. שואל, וכי אל יעקב, ולא אל אברהם, ולא אל יצחק אלא אל יעקב. ומשיב, משום שיעקב לא בטח באביו ולא באמו, כשברח מפני אחיו, והלך יחיד בלי כסף, כמש\"א, כי במקלי עברתי את הירדן הזה. והוא בטח בהקב\"ה, שכתוב, אם יהיה אלקים עמדי ושמרני וגו' והכל בקש מן הקב\"ה ונתן לו."],[8,"שברו על ה' אלקיו:","שואל, אומר שברו ולא אמר תקותו, ולא בטחונו, אלא שברו. ומשיב, אל תקרי שברו, עם ש' שמאלית אלא שברו, עם שין ימנית. כי נעים להם לצדיקים לשבר את עצמם, ולהשבר שבר על שבר, והכל על ה' אלקיו. כמש\"א, כי עליך הורגנו כל היום. כי עליך נשאתי חרפה."]],[[0,"","וְעַל זֶה, כְּשֶׁרָאָה יְחֶזְקֵאל סוֹד הַחַיּוֹת שֶׁהָיוּ עוֹלוֹת, לֹא רָאָה מַה זֶּה שֶׁעוֹלוֹת, מִשּׁוּם שֶׁהִיא עוֹלָה לַמֶּלֶךְ הָעֶלְיוֹן בְּסֵתֶר וּבִטְמִירוּת בְּכָבוֹד עֶלְיוֹן."],[1,"","וְכָל חֲכַם לֵב בָּכֶם - אֵלֶּה הֵם שִׁשִּׁים מְקוֹרוֹת שֶׁמַּשְׁקִים אֶת הָעוֹלָם, וּמֵהֶם הוּא מֻשְׁקֶה. יָבאוּ, לָמָּה יָבאוּ? אֶלָּא שֶׁיָּבֹאוּ לָקַחַת מֵעִם גִּנְזֵי הַחַיִּים. יָבאוּ וְאַחַר כָּךְ וְיַעֲשׂוּ, מַה שֶּׁהַקָּדוֹשׁ בָּרוּךְ הוּא צִוָּה אוֹתָם לֵהָנוֹת אֶת הָעוֹלָם."],[2,"","קְחוּ מֵאִתְּכֶם תְּרוּמָה לַה'. רַבִּי יְהוּדָה פָּתַח, (ישעיה נח) הֲלוֹא פָרֹס לָרָעֵב לַחְמֶךְ וְגוֹ'. בּא וּרְאֵה, אַשְׁרֵי חֶלְקוֹ שֶׁל אָדָם כְּשֶׁעָנִי פּוֹגֵשׁ אוֹתוֹ. שֶׁאוֹתוֹ הֶעָנִי הוּא דּוֹרוֹן שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁשָּׁלַח אֵלָיו. מִי שֶׁמְּקַבֵּל אֶת אוֹתוֹ דוֹרוֹן בְּסֵבֶר פָּנִים, אַשְׁרֵי חֶלְקוֹ!"],[3,"","בֹּא וּרְאֵה, מִי שֶׁחָס עַל הֶעָנִי וּמֵשִׁיב אֶת נַפְשׁוֹ, הַקָּדוֹשׁ בָּרוּךְ הוּא מַעֲלֶה עָלָיו כְּאִלּוּ הוּא בָּרָא אֶת נַפְשׁוֹ. וְעַל כֵּן, אַבְרָהָם שֶׁהָיָה חָס עַל כָּל בְּנֵי הָעוֹלָם, הֶעֱלָה עָלָיו הַקָּדוֹשׁ בָּרוּךְ הוּא כְּאִלּוּ הוּא בָּרָא אוֹתָם, שֶׁכָּתוּב (בראשית יב) וְאֶת הַנֶּפֶשׁ אֲשֶׁר עָשׂוּ בְחָרָן."],[4,"","וְאַף עַל גַּב שֶׁהֲרֵי בֵּאַרְנוּ, הֲלוֹא פָרֹס, מַה זֶּה פָרֹס? לִפְרֹס לוֹ מַפָּה בְּלֶחֶם וּמָזוֹן לֶאֱכֹל. דָּבָר אַחֵר הֲלוֹא פָרֹס, כְּמוֹ שֶׁנֶּאֱמַר (דניאל ה) פְּרֵס פְּרִיסַת וְגוֹ'. שֶׁצָּרִיךְ לִפְרֹס פְּרוּסוֹת לֶחֶם לְפָנָיו כְּדֵי שֶׁלֹּא יִתְבַּיֵּשׁ, וְיִפְרֹס לְפָנָיו בְּעַיִן טוֹבָה. לַחְמֶךְ, לֹא כָתוּב לֶחֶם, אֶלָּא לַחְמֶךְ, אוֹתוֹ שֶׁהוּא שֶׁלְּךְ. מִמָּמוֹנְךְ, וְלֹא שֶׁל גָּזֵל, וְלֹא שֶׁל עֹשֶׁק, וְלֹא שֶׁל גְּנֵבָה. שֶׁאִם כָּךְ, זוֹ אֵינָהּ זְכוּת, אֶלָּא אוֹי לוֹ שֶׁבָּא לְהַזְכִּיר אֶת חֲטָאָיו. כְּמוֹ כֵן קְחוּ מֵאִתְּכֶם תְּרוּמָה, לְהָרִים מִמַּה שֶּׁהוּא שֶׁלָּכֶם, וְלֹא מֵעֹשֶׁק, וְלֹא מִגָּזֵל, וְלֹא מִגְּנֵבָה, וְכָךְ פֵּרְשׁוּהוּ."],[5,"","רַבִּי חִיָּיא וְרַבִּי יִצְחָק וְרַבִּי יוֹסֵי הָיוּ הוֹלְכִים בַּדֶּרֶךְ. עַד שֶׁהָיוּ הוֹלְכִים, פָּגַשׁ בָּהֶם רַבִּי אַבָּא. אָמַר רַבִּי חִיָּיא, וַדַּאי שְׁכִינָה עִמָּנוּ. כְּשֶׁהִגִּיעַ אֲלֵיהֶם, אָמַר רַבִּי אַבָּא, כָּתוּב (מלכים א ב) מִן הַיּוֹם אֲשֶׁר הוֹצֵאתִי אֶת עַמִּי אֶת יִשְׂרָאֵל מִמִּצְרַיִם לֹא בָחַרְתִּי בְעִיר מִכֹּל שִׁבְטֵי יִשְׂרָאֵל וָאֶבְחַר בְּדָוִד וְגוֹ' לִבְנוֹת בַּיִת לִהְיוֹת שְׁמִי שָׁם. פָּסוּק זֶה אֵין רֹאשׁוֹ סוֹפוֹ, וְאֵין סוֹפוֹ רֹאשׁוֹ. שֶׁכָּתוּב לֹא בָחַרְתִּי בְעִיר, וָאֶבְחַר בְּדָוִד. מַה זֶּה עִם זֶה? וָאֶבְחַר בִּירוּשָׁלַיִם הָיָה צָרִיךְ לִהְיוֹת!"],[6,"","אֶלָּא כְּשֶׁיֵּשׁ רָצוֹן לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא לִבְנוֹת עִיר, מִסְתַּכֵּל בָּרִאשׁוֹנָה בְּאוֹתוֹ הָרֹאשׁ שֶׁמַּנְהִיג אֶת הָעָם שֶׁל הָעִיר, וְאַחַר כָּךְ אֶת בְּנֵי הָעִיר, וּמֵבִיא אֶת הָעָם לְשָׁם. זֶהוּ שֶׁכָּתוּב לֹא בָחַרְתִּי בְעִיר, עַד שֶׁהִתְבּוֹנַנְתִּי בְּדָוִד לִהְיוֹת רוֹעֶה עַל יִשְׂרָאֵל, מִשּׁוּם שֶׁהָעִיר וְכָל בְּנֵי הָעִיר כֻּלָּם עוֹמְדִים בִּזְכוּת הָרוֹעֶה שֶׁמַּנְהִיג אֶת הָעָם. אִם הָרוֹעֶה הוּא טוֹב - טוֹב לוֹ, טוֹב לָעִיר, טוֹב לָעָם. וְאִם הָרוֹעֶה הוּא רַע - אוֹי לוֹ, אוֹי לָעִיר וְאוֹי לָעָם! וְעַכְשָׁו הִסְתַּכֵּל הַקָּדוֹשׁ בָּרוּךְ הוּא בָּעוֹלָם, וְעָלָה בִרְצוֹנוֹ לִבְנוֹת אוֹתָהּ, וְהֶעֱמִיד בָּרֹאשׁ אֶת דָּוִד. זֶהוּ שֶׁכָּתוּב וָאֶבְחַר בְּדָוִד עַבְדִּי. (והעמיד בראש הדור את רבי שמעון וחבריו לעמד לפניו)."],[7,"","דָּבָר חָדָשׁ שָׁמַעְנוּ. פָּתַח וְאָמַר, (תהליםקמו) אַשְׁרֵי שֶׁאֵל יַעֲקֹב בְּעֶזְרוֹ שִׂבְרוֹ עַל ה' אֱלֹהָיו. וְכִי אֵל יַעֲקֹב, וְלֹא אֵל אַבְרָהָם, וְלֹא אֵל יִצְחָק? אֶלָּא אֵל יַעֲקֹב, מִשּׁוּם שֶׁיַּעֲקֹב לֹא בָטַח בְּאָבִיו וְלֹא בְאִמּוֹ כְּשֶׁבָּרַח מִלִּפְנֵי אָחִיו וְהָלַךְ יְחִידִי בְּלִי מָמוֹן, כְּמוֹ שֶׁנֶּאֱמַר (בראשית לב) כִּי בְמַקְלִי עָבַרְתִּי אֶת הַיַּרְדֵּן הַזֶּה, וְהוּא בָּטַח בַּקָּדוֹשׁ-בָּרוּךְ-הוּא, שֶׁכָּתוּב (שם כח) אִם יִהְיֶה אֱלֹהִים עִמָּדִי וּשְׁמָרַנִי וְגוֹ'. וְהַכֹּל שָׁאַל מִלִּפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְנָתַן לוֹ."],[8,"","שִׂבְרוֹ עַל ה' אֱלֹהָיו. שִׂבְרוֹ, וְלֹא אָמַר תִּקְוָתוֹ וְלֹא בִטְחוֹנוֹ, אֶלָּא שִׂבְרוֹ. אַל תִּקְרֵי שִׂבְרוֹ אֶלָּא שִׁבְרוֹ, שֶׁנּוֹחַ לַצַּדִּיקִים לִשְׁבֹּר אֶת עַצְמָם וּלְהִשָּׁבֵר שֶׁבֶר עַל שֶׁבֶר, וְהַכֹּל עַל ה' אֱלֹהָיו, כְּמוֹ שֶׁנֶּאֱמַר (תהלים מד) כִּי עָלֶיךְ הֹרַגְנוּ כָל הַיּוֹם. כִּי עָלֶיךְ נָשָׂאנוּ חֶרְפָּה."]]],[["כְּגַוְונָא דְּיַעֲקֹב, דִּכְתִּיב וַיַּרְא יַעֲקֹב כִּי יֵשׁ שֶׁבֶר בְּמִצְרָיִם, דְּהָא תְּבִירוּ דְּגָלוּתָא, חָמָא דְּהֲוָה לֵיהּ בְּמִצְרָיִם, וְשַׁוֵּי תּוּקְפֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא. וּבְנוֹי דְּיַעֲקֹב סַבְלוּ תְּבִירוּ דְּגָלוּתָא, וְלָא אִשְׁתָּנּוּ מִגּוֹ רָזָא דִּמְהֵימְנוּתָא דְּאַבָהֲתְהוֹן וּשְׁמָא דְּקוּדְשָׁא בְּרִיךְ הוּא הֲוָה בְּגָלוּתָא רְגִילָא בְּפוּמַיְיהוּ.","וְעַל דָּא כְּתִיב בְּמֹשֶׁה, (שמות ג) וְאָמְרוּ לִי' מַה' שְּׁמוֹ' מַה'. בְּגִין דַּהֲווֹ יַדְעֵי לֵיהּ, וְלָא אַנְשׁוּ לֵיהּ לְעָלְמִין, וְסַבְלוּ תְּבִירוּ דְּגָלוּתָא עַל קוּדְשָׁא בְּרִיךְ הוּא, וּבְגִין כַּךְ זָכֵי לְפוּרְקָנִין וּלְנִסִין וּלְאַתְוָּון סַגִּיאִין.","וְאַתּוּן קַדִּישִׁין עֶלְיוֹנִין, דְּסָבְלִּין תְּבִירוּ דְּגוּפָא מֵאֲתָר לְאֲתָר עַל קוּדְשָׁא בְּרִיךְ הוּא, עַל אַחַת כַּמָּה וְכַמָּה דְּזַכָּאִין אַתּוּן לְמֶעְבַּד לְכוּ נִסִּין וּפוּרְקָנִין, וְתִזְכּוּן לְחַיֵּי עָלְמָא דְּאָתֵי. אָזְלוּ כֻּלְּהוּ כַּחֲדָא.","פָּתַח וְאָמַר (שמות ל״ה:ה׳) קְחוּ מֵאִתְּכֶם תְּרוּמָה לַיְיָ' כֹּל נְדִיב לִבּוֹ יְבִיאֶהָ וְגוֹ'. תָּא חֲזֵי, בְּשַׁעֲתָא דְּבַר נָשׁ שַׁוֵּי רְעוּתֵיהּ, לְגַבֵּי פּוּלְחָנָא דְּמָארֵיהּ, הַהוּא רְעוּתָא סָלִיק בְּקַדְמִיתָא עַל לִבָּא, דְּאִיהוּ קִיוּמָא וִיסוֹדָא דְּכָל גּוּפָא. לְבָתַר סָלִיק הַהוּא רְעוּתָא טָבָא, עַל כָּל שַׁיְיפֵי גּוּפָא. וּרְעוּתָא דְּכָל שַׁיְיפֵי גּוּפָא, וּרְעוּתָא דְּלִבָּא, מִתְחַבְּרָאן כַּחֲדָא, וְאִינּוּן מַשְׁכִין עָלַיְיהוּ זִיהֲרָא דִּשְׁכִינְתָּא לְדַיְּירָא עִמְּהוֹן, וְהַהוּא בַּר נָשׁ אִיהוּ חוּלָקָא דְּקוּדְשָׁא בְּרִיךְ הוּא הֱוֵי, הֲדָא הוּא דִכְתִיב קְחוּ מֵאִתְּכֶם תְּרוּמָה. מֵאִתְּכֶם הֲוָה אַמְשְׁכוּתָא, לְקַבְּלָא עָלַיְיכוּ הַהִיא תְּרוּמָה, לְמֶהֱוֵי חוּלָקָא לַיְיָ'.","וְאִי תֵּימָא דְּלָאו בִּרְשׁוּתֵיהּ דְּבַּר נָשׁ קַיָּימָא מִלָּה. תָּא חֲזֵי, מַה כְּתִיב כֹּל נְדִיב לִבּוֹ יְבִיאֶהָ אֵת תְּרוּמַת יְיָ'. כֹּל נְדִיב לִבּוֹ וַדַּאי, מַאן דְּיִתְרְעֵי לִבֵּיהּ, יַמְשִׁיךְ לָהּ לִשְׁכִינְתָּא לְגַבֵּיהּ. הֲדָא הוּא דִכְתִיב יְבִיאֶהָ, אַף עַל גַּב דְּאִיהִי בְּאִסְתַּלְּקוּתָא לְעֵילָּא, יְבִיאֶהָ מֵאֲתָר עִלָּאָה, לְאַמְשָׁכָא לְדַיְּירָא עִמֵּיהּ.","וְכַד תֵּיתֵי לְאַשְׁרָאָה עִמֵּיהּ, כַּמָה בִּרְכָּאן וְכַמָּה עֻתְרָא תֵּיתֵי עִמֵּהּ. הֲדָא הוּא דִכְתִיב זָהָב וָכֶסֶף וּנְחֹשֶׁת. לָא יֶחְסַר לֵיהּ כָּל עֻתְרָא דְּעָלְמָא. דָּא לִשְׁאַר בְּנֵי עָלְמָא. אֲבָל אַתּוּן קַדִּישִׁין עֶלְיוֹנִין, קְחוּ מֵאִתְּכֶם תְּרוּמָה לַיְיָ'. אָמַר רִבִּי חִיָּיא, מַאן דְּשָׁרֵי לְאָרָמָא, הוּא יָרִים.","פָּתַח רִבִּי אַבָּא וְאָמַר, (יונה ב) וַיֹּאמֶר יְיָ' לַדָּג וְגוֹ', וְכִי בְּאָן אֲתָר אָמַר לֵיהּ. אֶלָּא בְּשַׁעֲתָא דְּבָרָא קוּדְשָׁא בְּרִיךְ הוּא עָלְמָא בְּעוֹבָדָא דִּבְרֵאשִׁית, בְּיוֹמָא חֲמִישָׁאָה בָּרָא נוּנֵי יַמָּא. כְּדֵין פָּקִיד וְאָמַר, דִּיְּהֵא זַמִין חַד נוּנָא לְמִבְלַע לְיוֹנָה, וִיֵּהֵא בְּמֵעוֹי תְּלָתָא יוֹמִין וּתְלַת לֵילָוָון, וּלְבָתַר דְּיִּרְמֵי לֵיהּ לְבַר.","וְלָא דָּא בִּלְחוֹדוֹי, אֶלָּא כָּל מַה דְּעַבַד קוּדְשָׁא בְּרִיךְ הוּא בְּעוֹבָדָא דִּבְרֵאשִׁית, בְּכֹלָּא אַתְנֵי עִמֵּיהּ. בְּיוֹמָא קַדְמָאָה בָּרָא שְׁמַיָא, אַתְנֵי עִמְּהוֹן דִּיְסַלִיק לְאֵלִיָּהוּ הַשָּׁמַיְמָה בְּגוֹ סְעָרָה, וְכֵן הֲוָה, דִּכְתִּיב, (מלכים ב ב׳:י״א) וַיַּעַל אֵלִיָּהוּ בַּסֳּעָרָה הַשָּׁמָיִם. בְּהַהוּא יוֹמָא בָּרָא נְהוֹרָא, וְאַתְנִי עִמֵּיהּ דְּיַחְשִׁיךְ לְשִׁמְּשָׁא בְּמִצְרַיִם תְּלָתָא יוֹמִין, דִּכְתִּיב, (שמות י׳:כ״ב) וַיְהִי חֹשֶׁךְ אֲפֵלָה בְּכָל אֶרֶץ מִצְרַיִם שְׁלשֶׁת יָמִים.","בְּיוֹמָא תִּנְיָינָא בָּרָא רְקִיעָא, דִּיהֵא מַפְרִישׁ בֵּין מַיָּא לְמַיָּא, כְּדִכְתִיב (בראשית א׳:ו׳) וַיֹּאמֶר אֱלֹהִים יְהִי רָקִיעַ בְּתוֹךְ הַמָּיִם וַיְהִי מַבְדִּיל בֵּין מַיִם לָמָיִם. וְאַתְנִי עִמְּהוֹן קוּדְשָׁא בְּרִיךְ הוּא, דְּמַיָּא יְהוֹן מַפְרִישִׁין לְיִשְׂרָאֵל בֵּין טוּמְאָה לְטָהֳרָה, לְאִתְדַכְּאָה בְּהוּ, וְכַךְ הֲוָה.","בְּיוֹמָא תְּלִיתָאָה אַפִּיק אַרְעָא מִגּוֹ מַיָּא, וְאַכְנִּישׁ לְמַיָּא, וַעֲבַד מֵהַהוּא כְּנִישׁוּ דְּאִתְכְּנָשׁוּ לְאֲתָר חַד, יַמָּא. וְאַתְנֵי בְּיַמָּא לְמֶעְבַּר לְיִשְׂרָאֵל בְּגַוֵּיהּ בְּיַבֶּשְׁתָּא, וּלְמִטְבַּע לְמִצְרָאֵי, וְכַךְ הֲוָה, דִּכְתִּיב, (שמות י״ד:כ״ז) וַיָּשָׁב הַיָּם לִפְנוֹת בֹּקֶר לְאֵיתָנוֹ. אַל תִּקְרֵי לְאֵיתָנוֹ, אֶלָּא לִתְנָאוֹ, לְמַּה דְּאַתְנִי עִמֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא, בְּעוֹבָדָא דִּבְרֵאשִׁית. תּוּ אַתְנֵי בְּאַרְעָא, דְּתִפְתַּח יַת פּוּמָהָא בְּמַחְלְקוֹתָא דְּקֹרַח, וְתִבְלַע לְקֹרַח וּלְכָל כְּנִישָׁתֵיהּ, וְכַךְ הֲוָה, דִּכְתִּיב, (במדבר ט״ז:ל״ב) וַתִּפְתַּח הָאָרֶץ אֶת פִיהָ וְתִבְלַע אוֹתָם וְאֶת קֹרַח.","בְּיוֹמָא רְבִיעָאָה, בָּרָא שִׁמְשָׁא וְסִיהֲרָא, דִּכְתִּיב יְהִי מְאֹרֹת בִּרְקִיעַ הַשָּׁמַיִם, וְאַתְנֵי עִם שִׁמְשָׁא, לְמֶהוֵי קָאִים בְּפַלְגּוּ שְׁמַיָּא בְּיוֹמֵי דִּיהוֹשֻׁעַ, דִּכְתִּיב, (יהושע י יב) וַיַּעֲמוֹד הַשֶּׁמֶשׁ בַּחֲצִי הַשָּׁמַיִם. אַתְנִי בְּכֹכָבַיָּא לְמֶעְבַּד קְרָבָא בְּסִיסְרָא, דִּכְתִּיב, (שופטים ה׳:כ׳) הַכֹּכָבִים מִמְּסִלּוֹתָם נִלְחַמוּ עִם סִיסְרָא."],[[0,"כגוונא דיעקב דכתיב וכו':","כעין יעקב, שכתוב וירא יעקב כי יש שבר במצרים. כי ראה השבר של הגלות שהיה לו במצרים, ושם בטחונו בהקב\"ה. ובני יעקב סבלו השבר של הגלות, ולא נשתנו מסוד אמונת אבותיהם. והשם של הקב\"ה היה רגיל בפיהם."],[1,"וע\"ד כתיב במשה וכו':","וע\"כ כתוב במשה, ואמרו ל \u0003י\u0004 מ \u0003ה\u0004 שמ \u0003ו\u0004 מ \u0003ה,\u0004 שסופי תיבות הוא י\"ה ו\"ה, שהיה רגיל בפיהם. משום שהיו יודעים אותו, ולא שכחו אותו לעולם, וסבלו שבר הגלות בשביל הקב\"ה. ומשום כך, זכו לגאולות ולנסים ולאותות רבים."],[2,"ואתון קדישין עליונין וכו':","ואתם קדושים העליונים, שאתם סובלים שבר הגוף ממקום למקום על הקב\"ה, על אחת כמה וכמה, שאתם ראוים שיעשה לכם נסים וגאולות, ותזכו לחיי עולם הבא. הלכו כולם יחד."],[3,"פתח ואמר, קחו מאתכם תרומה וגו':","פתח ואמר, בוא וראה, בשעה שאדם משים רצונו לעבודת רבונו, רצון הזה עולה תחלה על הלב, שהוא הקיום והיסוד של כל הגוף, ואח\"כ עולה רצון טוב ההוא על כל אברי הגוף, והרצון של כל אברי הגוף והרצון של הלב מתחברים יחד, והם מושכים עליהם זהר השכינה לשכון עמהם. ואדם ההוא, הוא חלקו של הקב\"ה. ז\"ש קחו מאתכם תרומה, מאתכם הוא ההמשכה לקבל עליכם תרומה ההיא, שהיא השכינה, שיהיה האדם חלק לה'."],[4,"ואי תימא דלאו","וכו': ואם תאמר, שאין הדבר עומד ברשותו של האדם. בוא וראה מה כתוב. כל נדיב לבו יביאה את תרומת ה'. \u0003כל נדיב לבו,\u0004 ודאי, כל מי שירצה לבו ימשיך אליו את השכינה. ז\"ש \u0003יביאה,\u0004 אע\"פ שהיא בהתעלות למעלה, \u0003יביאה\u0004 ממקום העליון להמשיכה לשכון עמו."],[5,"וכד תיתי לאשראה וכו':","וכשתבוא לשרות עמו, כמה ברכות וכמה עושר מביאה עמה, ז\"ש זהב וכסף ונחשת, לא יחסר לו כל העושר שבעולם. זהו לשאר בני העולם. אבל אתם קדושים העליונים, קחו מאתכם תרומה לה'. דהיינו שיחדשו חדושי תורה להרמת השכינה. א\"ר חייא, מי שהתחיל להרים הוא ירים."],[6,"פתח ר' אבא וכו':","פתח ר\"א ואמר, ויאמר ה' לדג. שואל וכי באיזה מקום אמר לו. ומשיב, אלא בשעה שברא הקב\"ה העולם במעשה בראשית, ביום החמישי ברא דגי הים, אז צוה ואמר, שיהיה עתיד דג אחד לבלוע את יונה, ויהיה במעיו ג' ימים וג' לילות, ואח\"כ יקיא אותו לחוץ."],[7,"ולא דא בלחודוי וכו':","ולא זה בלבד, אלא כל מה שעשה הקב\"ה במעשה בראשית, בכולם התנה עמהם. ביום הראשון ברא את השמים, התנה עמהם שיעלו את אליהו השמימה בסערה. וכן היה, שכתוב, ויעל אליהו בסערה השמים. ביום ההוא ברא האור, והתנה עמו שיחשיך השמש במצרים ג' ימים, שכתוב, ויהי חשך אפלה בכל ארץ מצרים שלשת ימים."],[8,"ביומא תנינא ברא וכו':","ביום השני ברא הרקיע שיהיה מבדיל בין מים למים. שכתוב, ויאמר אלקים יהי רקיע בתוך המים ויהי מבדיל בין מים למים. והתנה עמהם הקב\"ה, שהמים יבדילו לישראל בין טומאה לטהרה להטהר בהם. וכך היה."],[9,"ביומא תליתאה אפיק וכו':","ביום השלישי הוציא את הארץ מתוך המים, והקוה המים, ועשה ממקוה המים ההוא, שנקוו למקום אחד, את הים. והתנה עם הים להעביר את ישראל בתוכו ביבשה, ולהטביע את המצרים. וכך היה. שכתוב, וישב הים לפנות בוקר לאיתנו, אל תקרא לאיתנו, אלא לתנאו, דהיינו למה שהתנה עמו הקב\"ה במעשה בראשית. עוד התנה עם הארץ, שתפתח את פיה במחלוקת קרח, ותבלע את קרח וכל עדתו. וכך היה. שכתוב, ותפתח הארץ את פיה ותבלע אותם ואת קרח."],[10,"ביומא רביעאה וכו':","ביום הרביעי ברא השמש והלבנה, שכתוב, ויהי מארת ברקיע השמים, והתנה עם השמש, להיות עומד בחצי השמים בימי יהושע. שכתוב, ויעמוד השמש בחצי השמים. התנה עם הככבים לעשות מלחמת עם סיסרא, שכתוב, הככבים ממסלותם נלחמו עם סיסרא."]],[[0,"","כְּמוֹ שֶׁיַּעֲקֹב, שֶׁכָּתוּב וַיַּרְא יַעֲקֹב כִּי יֵשׁ שֶׁבֶר בְּמִצְרָיִם, שֶׁהֲרֵי שִׁבְרוֹן הַגָּלוּת רָאָה שֶׁהָיָה לוֹ בְּמִצְרַיִם, וְשָׂם חָזְקוֹ בַּקָּדוֹשׁ-בָּרוּךְ-הוּא. וּבְנֵי יַעֲקֹב סָבְלוּ אֶת שֶׁבֶר הַגָּלוּת וְלֹא הִשְׁתַּנּוּ מִתּוֹךְ סוֹד הָאֱמוּנָה שֶׁל אֲבוֹתֵיהֶם, וּשְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא הָיָה רָגִיל בַּגָּלוּת בְּפִיהֶם."],[1,"","וְעַל זֶה כָּתוּב בְּמֹשֶׁה, (שמות ג) וְאָמְרוּ לִי' מַה' שְּׁמוֹ' מַה'. מִשּׁוּם שֶׁהָיוּ מַכִּירִים אוֹתוֹ וְלֹא שְׁכָחוּהוּ לְעוֹלָמִים וְסָבְלוּ אֶת שֶׁבֶר הַגָּלוּת עַל הַקָּדוֹשׁ בָּרוּךְ הוּא, וּמִשּׁוּם כָּךְ זוֹכִים לִגְאֻלּוֹת וּלְנִסִּים וּלְאוֹתוֹת רַבִּים."],[2,"","וְאַתֶּם קְדוֹשִׁים עֶלְיוֹנִים, שֶׁסּוֹבְלִים אֶת שֶׁבֶר הַגּוּף מִמָּקוֹם לְמָקוֹם עַל הַקָּדוֹשׁ בָּרוּךְ הוּא, עַל אַחַת כַּמָּה וְכַמָּה שֶׁזַּכָּאִים אַתֶּם לַעֲשׂוֹת לָכֶם נִסִּים וּפֻרְקָן וְשֶׁתִּזְכּוּ לְחַיֵּי הָעוֹלָם הַבָּא. הָלְכוּ כֻלָּם כְּאֶחָד."],[3,"","פָּתַח וְאָמַר, קְחוּ מֵאִתְּכֶם תְּרוּמָה לַה' כֹּל נְדִיב לִבּוֹ יְבִיאֶהָ וְגוֹ'. בֹּא וּרְאֵה, בְּשָׁעָה שֶׁאָדָם שָׂם רְצוֹנוֹ לַעֲבוֹדַת רִבּוֹנוֹ, אוֹתוֹ רָצוֹן עוֹלֶה בָּרִאשׁוֹנָה עַל הַלֵּב, שֶׁהוּא קִיּוּם וִיסוֹד שֶׁל כָּל הַגּוּף. אַחַר כָּךְ עוֹלֶה אוֹתוֹ רָצוֹן טוֹב עַל כָּל אֶבְרֵי הַגּוּף, וּרְצוֹנָם שֶׁל כָּל אֶבְרֵי הַגּוּף וּרְצוֹן הַלֵּב מִתְחַבְּרִים כְּאֶחָד, וְהֵם מוֹשְׁכִים עֲלֵיהֶם אֶת זֹהַר הַשְּׁכִינָה לָדוּר עִמָּהֶם, וְאוֹתוֹ אָדָם הִנּוֹ חֶלְקוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. זֶהוּ שֶׁכָּתוּב קְחוּ מֵאִתְּכֶם תְּרוּמָה. מֵאִתְּכֶם הָיְתָה הַמְשָׁכָה לְקַבֵּל עֲלֵיכֶם אוֹתָהּ תְּרוּמָה לִהְיוֹת חֵלֶק לַה'."],[4,"","וְאִם תֹּאמַר שֶׁלֹּא בִּרְשׁוּת הָאָדָם עוֹמֵד הַדָּבָר - בֹּא וּרְאֵה מַה כָּתוּב, כֹּל נְדִיב לִבּוֹ יְבִיאֶהָ אֵת תְּרוּמַת ה'. כֹּל נְדִיב לִבּוֹ וַדַּאי. מִי שֶׁיִּתְרַצֶּה לִבּוֹ, יַמְשִׁיךְ אֶת הַשְּׁכִינָה אֵלָיו. זֶהוּ שֶׁכָּתוּב יְבִיאֶהָ, אַף עַל גַּב שֶׁהִיא בַּעֲלִיָּה לְמַעְלָה, יְבִיאֶהָ מִמָּקוֹם עֶלְיוֹן לִמְשֹׁךְ אוֹתָהּ לָדוּר עִמּוֹ."],[5,"","וּכְשֶׁתָּבֹא לִשְׁרוֹת עִמּוֹ, כַּמָּה בְרָכוֹת וְכַמָּה עֹשֶׁר תָּבִיא עִמָּהּ. זֶהוּ שֶׁכָּתוּב זָהָב וָכֶסֶף וּנְחֹשֶׁת. לֹא חָסֵר לוֹ כָּל עֹשֶׁר הָעוֹלָם. זֶה לִשְׁאָר בְּנֵי הָעוֹלָם. אֲבָל אַתֶּם קְדוֹשִׁים עֶלְיוֹנִים - קְחוּ מֵאִתְּכֶם תְּרוּמָה לַה'. אָמַר רַבִּי חִיָּיא, מִי שֶׁהִתְחִיל לְהָרִים - הוּא שֶׁיָּרִים."],[6,"","פָּתַח רַבִּי אַבָּא וְאָמַר, (יונהב) וַיֹּאמֶר ה' לַדָּג וְגוֹ'. וְכִי בְּאֵיזֶה מָקוֹם אָמַר לוֹ? אֶלָּא בְּשָׁעָה שֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם בְּמַעֲשֵׂה בְרֵאשִׁית, בַּיּוֹם הַחֲמִישִׁי בָּרָא אֶת דְּגֵי הַיָּם, וְאָז צִוָּה וְאָמַר שֶׁיִּהְיֶה מְזֻמָּן דָּג אֶחָד לִבְלֹעַ אֶת יוֹנָה, וְיִהְיֶה בְמֵעָיו שְׁלֹשָׁה יָמִים וּשְׁלֹשָׁה לֵילוֹת, וְאַחַר כָּךְ יַשְׁלִיכֶנּוּ בַּחוּץ."],[7,"","וְלֹא זֶה לְבַדּוֹ, אֶלָּא כָּל מַה שֶּׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמַעֲשֵׂה בְרֵאשִׁית - בַּכֹּל הִתְנָה עִמּוֹ. בַּיּוֹם הָרִאשׁוֹן בָּרָא שָׁמַיִם, הִתְנָה עִמָּם שֶׁיַּעֲלוּ אֶת אֵלִיָּהוּ הַשָּׁמַיְמָה בְּתוֹךְ סֳעָרָה, וְכָךְ הָיָה, שֶׁכָּתוּב (מלכים ב ב) וַיַּעַל אֵלִיָּהוּ בַּסֳעָרָה הַשָּׁמָיִם. בְּאוֹתוֹ יוֹם בָּרָא אֶת הָאוֹר, וְהִתְנָה עִמּוֹ שֶׁיַּחֲשִׁיךְ לַשֶּׁמֶשׁ בְּמִצְרַיִם שְׁלֹשָׁה יָמִים, שֶׁכָּתוּב (שמות י) וַיְהִי חֹשֶׁךְ אֲפֵלָה בְּכָל אֶרֶץ מִצְרַיִם שְׁלֹשֶׁת יָמִים."],[8,"","בַּיּוֹם הַשֵּׁנִי בָּרָא אֶת הָרָקִיעַ, שֶׁיִּהְיֶה מַפְרִיד בֵּין מַיִם לָמַיִם, כַּכָּתוּב (בראשית א) וַיֹּאמֶר אֱלֹהִים יְהִי רָקִיעַ בְּתוֹךְ הַמָּיִם וִיהִי מַבְדִּיל בֵּין מַיִם לָמָיִם, וְהִתְנָה עִמָּהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהַמַּיִם יִהְיוּ מַפְרִידִים לְיִשְׂרָאֵל בֵּין טֻמְאָה וְטָהֳרָה לְהִטָּהֵר בָּהֶם, וְכָךְ הָיָה."],[9,"","בַּיּוֹם הַשְּׁלִישִׁי הוֹצִיא אֶרֶץ מִתּוֹךְ הַיָּם וְכִנֵּס אֶת הַמַּיִם, וְעָשָׂה מֵאוֹתוֹ קִבּוּץ שֶׁהִתְכַּנְּסוּ לְמָקוֹם אֶחָד אֶת הַיָּם, וְהִתְנָה עִם הַיָּם לְהַעֲבִיר אֶת יִשְׂרָאֵל בְּתוֹכוֹ בַּיַּבָּשָׁה וּלְהַטְבִּיעַ אֶת הַמִּצְרִים, וְכָךְ הָיָה, שֶׁכָּתוּב (שמות יד) וַיָּשָׁב הַיָּם לִפְנוֹת בֹּקֶר לְאֵיתָנוֹ. אַל תִּקְרֵי לְאֵיתָנוֹ אֶלָּא לִתְנָאוֹ, לְמַה שֶּׁהִתְנָה עִמּוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמַעֲשֵׂה בְרֵאשִׁית. עוֹד הִתְנָה עִם הָאָרֶץ, שֶׁתִּפְתַּח אֶת פִּיהָ בְּמַחֲלֻקְתּוֹ שֶׁל קֹרַח וְתִבְלַע אֶת קֹרַח וְאֶת כָּל עֲדָתוֹ, וְכָךְ הָיָה, שֶׁכָּתוּב (במדבר טז) וַתִּפְתַּח הָאָרֶץ אֶת פִּיהָ וַתִּבְלַע אֹתָם, וְאֶת קֹרַח."],[10,"","בַּיּוֹם הָרְבִיעִי בָּרָא שֶׁמֶשׁ וּלְבָנָה, שֶׁכָּתוּב יְהִי מְאֹרֹת בִּרְקִיעַ הַשָּׁמַיִם, וְהִתְנָה עִם הַשֶּׁמֶשׁ לִהְיוֹת עוֹמֶדֶת בַּחֲצִי הַשָּׁמַיִם בִּימֵי יְהוֹשֻׁעַ, שֶׁכָּתוּב (יהושע י) וַיַּעֲמֹד הַשֶּׁמֶשׁ בַּחֲצִי הַשָּׁמַיִם. הִתְנָה עִם הַכּוֹכָבִים לַעֲשׂוֹת קְרָב עִם סִיסְרָא, שֶׁכָּתוּב (שופטים ה) הַכּוֹכָבִים מִמְּסִלּוֹתָם נִלְחֲמוּ עִם סִיסְרָא."]]],[["בְּיוֹמָא חֲמִישָׁאָה בָּרָא נוּנֵי יַמָּא, וְעוֹפֵי דִּשְׁמַיָּא, אַתְנִי בְּעוֹפֵי לְמֵיזָן עוֹרְבִים לְאֵלִיָּהוּ, בְּזִמְנָא דְּעָצַר לִשְׁמַיָּא, דִּכְתִּיב, (מלכים א י״ז:ד׳) וְאֶת הָעוֹרְבִים צִוִּיתִי לְכַלְכְּלְךָ שָׁם. צִוִּיתִי דַּיְיקָא. וְאַתְנֵי בְּנוּנֵי יַמָּא לְאִזְדַּמְּנָא נוּנָא חַד, לְמִבְלַע לֵיהּ לְיוֹנָה, וּלְאַשְׁדָּאָה לֵיהּ לְבַר.","בְּיוֹמָא שְׁתִּיתָאָה בָּרָא לְאָדָם, וְאַתְנֵי עִמֵּיהּ, דְּתִפּוֹק מִנֵּיהּ אִתְּתָא, דְּתֵיזוּן לְאֵלִיָּהוּ, דִּכְתִּיב, (מלכים א י״ז:ט׳) הִנֵּה צִוִּיתִי שָׁם אִשָׁה אַלְמָנָה לְכַלְכְּלֶךָ. הִנֵּה צִוִּיתִי, מִיּוֹמָא דְּאִתְבְּרֵי עָלְמָא. וְכֵן בְּכָל עוֹבָדָא וְעוֹבָדָא דְּאִתְחַדֵּשׁ בְּעָלְמָא, קוּדְשָׁא בְּרִיךְ הוּא פָּקִיד הַהוּא עוֹבָדָא מִיּוֹמָא דְּאִתְבְּרֵי עָלְמָא. אוּף הָכָא, וַיֹּאמֶר יְיָ' לַדָּג. וַיֹּאמֶר, מִשִּׁית יוֹמִין דִּבְרִאשִׁית קָאָמַר לֵיהּ.","הָכָא אִית לָן סֶמֶךְ בְּעָלְמָא, עַל עוֹבָדִין דִּבְנֵי נָשָׁא בְּהַאי עָלְמָא. יוֹנָה דְּנָחַת לַסְּפִינָה, דָּא אִיהִי נִשְׁמְתָא דְּבַר נָשׁ, דְּנַחְתָּא לְהַאי עָלְמָא לְמֶהֱוֵי בְּגוּפָא דְּבַּר נָשׁ. אֲמַאי אִתְקְרֵי יוֹנָה. בְּגִין דְּכֵיוָן דְּאִשְׁתְּתָּפַת בְּגוּפָא, כְּדֵין אִיהִי יוֹנָה בְּהַאי עָלְמָא. כְּמָה דְּאִתְּמַר, (ויקרא כ״ה:י״ז) וְלָא תוֹנוּ אִישׁ אֶת עֲמִיתוֹ. וּכְדֵין בַּר נָשׁ אָזִיל בְּהַאי עָלְמָא, כַּסְּפִינָה בְּגוֹ יַמָּא רַבָּא, דַּחֲשִׁיבַת לְאִתָּבְּרָא, כְּמָה דְאַתְּ אָמֵר (יונה א׳:ד׳) וְהָאֳנִיָּה חִשְּׁבָה לְהִשָּׁבֵר.","וּבַר נָשׁ כַּד אִיהוּ בְּהַאי עָלְמָא חָטֵי, וְחָשִׁיב דְּעָרַק מִקַּמֵּי מָארֵיהּ. וְלָא אַשְׁגַּח בְּהַהוּא עָלְמָא. וּכְדֵין אַטִּיל קוּדְשָׁא בְּרִיךְ הוּא רוּחַ סְעָרָה תַּקִּיפָא. דָּא אִיהִי גְּזֵירַת דִּינָא, דְּקַיְּימָא תָּדִיר קָמֵי קוּדְשָׁא בְּרִיךְ הוּא. וּבָעָאת דִּינָא דְּבַר נָשׁ מִקַּמֵּיה, וְדָא אִיהוּ דְּקָא מָטֵי לַסְּפִינָה, וְאַדְכַּר חוֹבוֹי דְּבַר נָשׁ לְאִתָּפְסָא לֵיהּ.","כֵּיוָן דְּאִתְפַּס בַּר נָשׁ עַל יְדָא דְּהַהִיא סְעָרָה בְּבֵי מַרְעֵיהּ, מַה כְּתִיב וְיוֹנָה יָרַד אֶל יַרְכְּתֵי הַסְּפִינָה וַיִּשְׁכַּב וַיֵּרָדַם. אַף עַל גַּב דְּבַר נָשׁ בְּבֵי מַרְעֵיהּ, נִשְׁמְתָא לָא אִתְּעָרַת לְאָתָבָא קַמֵּי מָארֵיהּ, לְמִפְרַק חוֹבוֹי. מָה כְּתִיב, וַיִּקְרַב אֵלָיו רַב הַחוֹבֵל. מַאן רַב הַחוֹבֵל. דָּא יֵצֶר טוֹב, דְּאִיהוּ מַנְהִיג כֹּלָּא. וַיֹּאמֶר לוֹ מַה לְךָ נִרְדָּם קוּם קְרָא אֶל אֱלהֶיךָ וְגוֹ'. לָאו שַׁעֲתָא הוּא לְמִדְּמָךְ, דְּהָא סַלְּקִין לָךְ לְדִינָא, עַל כָּל מָה דְּעַבְדַּת בְּהַאי עָלְמָא, תּוּב מֵחוֹבָךְ.","אִסְתָּכָּל בְּמִלִּין אִלֵּין, וְתוּב לְמָארָךְ. מָה מְלַאכְתֶּךָ דְּאַתְּ עַסְקַת בָּהּ בְּהַאי עָלְמָא, וְאוֹדֵי עָלָהּ קָמֵי מָארָךְ. וּמֵאַיִן תָּבֹא, אִסְתָּכַּל מֵאַיִן בְּאָת, מִטִּפָּה סְרוּחָה, וְלָא תִּתְגָּאֵי קַמֵּיהּ. מָה אַרְצֶךָ, אִסְתָּכַּל דְּהָא מֵאַרְעָא אִתְבְּרִיאַת, וּלְאַרְעָא תִּיתוּב. וְאִי מִזֶּה עַם אָתָּה, אִסְתָּכַּל אִי אִית לָךְ זְכוּ דַּאֲבָהָן, דְּיָגִין עָלָךְ.","כֵּיוָן דְּסַלְּקִין לֵיהּ לְדִינָא, בְּבֵי דִּינָא דִּלְעֵילָּא, הַהִיא סְעָרָה, דְּאִיהִי גְּזֵרַת דִּינָא, דְּסָעִיר עָלֵיהּ דְּבַר נָשׁ, תַּבְעַת מִן מַלְכָּא לְמֵידָן אִינּוּן תְּפִיסִין דְּמַלְכָּא, וְכֻלְּהוּ אַתְיָין חַד חַד קָמֵיהּ. בֵּיהּ שַׁעֲתָא אִתְקְרִיבוּ בֵּי דִּינָא. אִית מִנְּהוֹן דְּפַתְחֵי בִּזְכוּת, וְאִית מִנְּהוֹן דְּפַתְחֵי בְּחוֹבָה. וּגְזֵרַת דִּינָא תַּבְעַת דִּינָא.","וְאִי הַהוּא בַּר נָשׁ לָא זָכֵי בְּדִינָא, מַה כְּתִיב. וַיַחְתְּרוּ הָאֲנָשִׁים לְהָשִׁיב אֶל הַיַּבָּשָׁה וְלֹא יָכֹלוּ. מִשְׁתַּדְּלִין אִינּוּן דְּאוֹרוּ זְכוּתֵיהּ לְאָתָבָא לֵיהּ לְהַאי עָלְמָא, וְלָא יָכֹלוּ. מַאי טַעֲמָא. כִּי הַיָּם הוֹלֵךְ וְסוֹעֵר עֲלֵיהֶם, גְּזֵרָה דְּדִינָא, אָזִיל וְסָעִיר בְּחוֹבוֹי דְּבַּר נָשׁ, וְאִתְגַּבָּר עָלַיְיהוּ.","כְּדֵין נַחְתִּין עָלֵיהּ תְּלַת שְׁלִיחָן מְמָנָן, חַד, דִּכְתִיב כָּל זַכְוָון, וְכָל חוֹבִין, דְּעָבַד בַּר נָשׁ בְּהַאי עָלְמָא. וְחַד דְּעָבִיד חוּשְׁבָּן יוֹמוֹי. וְחַד דְּהֲוָה אָזִיל עִמֵּיהּ, כַּד הֲוָה בִּמְעֵי אִמֵּיהּ. וְהָא אוֹקִימְנָא דִּגְזֵרַת דִּינָא לָא שָׁכִיךְ, עַד הַהוּא זִמְנָא דִּכְתִּיב, וַיִּשְׂאוּ אֶת יוֹנָה. וַיִּשְׂאוּ: כַּד נַטְלֵי לֵיהּ מִבֵּיתֵיהּ, לְבֵי קִבְרֵי.","כְּדֵין מַכְרִזִיִ עֲלוֹי. אִי אִיהוּ זַכָּאָה, מַכְרִזֵי עָלֵיהּ וְאַמְרֵי, הָבוּ יְקָר לְדִיּוּקְנָא דְּמַלְכָּא, (ישעיהו נ״ז:ב׳) יָבֹא שָׁלוֹם יָנוּחוּ עַל מִשְׁכְּבוֹתָם הֹלֵךְ נְכֹחוֹ. מְנָא לָן. דִּכְתִּיב, (ישעיהו נ״ח:ח׳) וְהָלַךְ לְפָנְיךָ צִדְקֶךָ כְּבוֹד יְיָ' יַאַסְפֶךָ. וְאִי חַיָּיבָא אִיהִי, מַכְרִיזֵי עָלֵיהּ וְאָמְרוּ, וַוי לֵיהּ לִפְלָנְיָא. טָב לֵיהּ דְּלָא יִתְבְּרֵי. כְּדֵין מַה כְּתִיב, וַיְטִלֻהוּ אֶל הַיָּם וַיַּעֲמוֹד הַיָּם מִזַּעְפּוֹ. כַּד עָאלִין לֵיהּ לְבֵי קִבְרֵי דְּאִיהוּ אֲתָר דְּדִינָא. כְּדֵין גְּזֵרַת דִּינָא דְּהֲוָה סָעִיר, שָׁכִיךְ מִזַּעְפֵּיהּ. וְנוּנָא דְּבָלַע לֵיהּ, דָּא אִיהוּ קִבְרָא."],[[0,"ביומא חמישא וכו':","ביום החמשי, ברא דגי הים ועוף השמים. והתנה עם העופות שעורבים יזונו לאליהו, שכתוב, ואת העורבים צויתי לכלכלך שם. צויתי, בדיוק, דהיינו במעשה בראשית. והתנה עם דגי הים, שיזדמן דג אחד לבלוע את יונה, ולהקיאו לחוץ."],[1,"ביומא שתיתאה וכו':","ביום הששי ברא את האדם. והתנה עמו שתצא ממנו אשה שתזין לאליהו. שכתוב, הנה צויתי שם אלמנה לכלכלך. הנה צויתי, היינו מיום שנברא העולם. אף כאן, ויאמר ה' לדג. \u0003ויאמר,\u0004 מששת ימי בראשית אמר לו."],[2,"הכא אית לן סמך וכו':","כאן יש לנו סמך בלבד, כי אין מקרא יוצא מידי פשוטו, על מעשה בני האדם בעולם הזה. יונה שירד לאניה, זה הוא הנשמה של האדם, שיורדת לעולם הזה להיות בגופו של אדם. למה נקראת יונה, משום, שאחר שנשתתפה בגוף, אז היא \u0003יונה\u0004 בעולם הזה, דהיינו שהיא מרומה מן הגוף שמאנה אותה, כמו שנאמר, ולא תונו איש את עמיתו. ואז הולך האדם בעולם הזה כאניה בים הגדול החושבת להשבר. כמש\"א, והאניה חשבה להשבר."],[3,"ובר נש כד וכו':","וכשהאדם הוא בעולם הזה, הוא חוטא, וחושב שהוא ברח מאדונו, כי אדונו אינו משגיח כאן בעולם הזה. ואז מטיל הקב\"ה רוח סערה חזקה, שזה הוא גזירת הדין העומד תמיד לפני הקב\"ה ומבקשת מלפניו דין על האדם. וזה, רוח סערה, הוא שהגיע אל האניה, והזכיר עונותיו של האדם לתפוש אותו."],[4,"כיון דאתפס בר נש וכו':","כיון שנתפש האדם על ידי סערה ההוא בבית חליו, מה כתוב, ויונה ירד אל ירכתי הספינה וישכב וירדם. אע\"פ שהאדם בבית חליו, אין הנשמה מתעוררת לשוב לפני אדונה לפדות עונותיו. מה כתוב, ויקרב אליו רב החובל. מי הוא רב החובל. זהו יצר הטוב, שמנהיג הכל. ויאמר לו מה לך נרדם קום קרא אל אלקיך וגו'. אין השעה לנום, כי מעלים אותך לדין על כל מה שעשית בעולם הזה, שוב מעונותיך."],[5,"אסתכל במלין אלין וכו':","הסתכל בדברים אלו, ושוב לאדונך. \u0003מה מלאכתך,\u0004 שעסקת בה בעולם הזה. ותתודה עליה לפני אדונך. \u0003ומאין תבא,\u0004 הסתכל מאין באת, מטפה סרוחה, ולא תתגאה לפניו. \u0003מה ארצך,\u0004 הסתכל שאתה נברא מארץ, ולארץ תשוב. \u0003ואי מזה עם אתה,\u0004 הסתכל אם יש לך זכות אבות שתגן עליך."],[6,"כיון דסלקין ליה וכו':","כיון שמעלים אותו לדון בבית דין של מעלה, סערה ההיא, שהיא גזרת הדין הסוער על האדם, מבקשת מן המלך לדון אלו האסירים של המלך, וכולם באים לפניו אחד אחד, בה בשעה, נקרב בית הדין. יש מהם שפותחים בזכות, ויש מהם שפותחים בחוב. וגזרת הדין מבקשת דין."],[7,"ואי ההוא ב\"נ וכו':","ואם אדם ההוא לא זכה בדין, מה כתוב, \u0003ויחתרו האנשים להשיב אל היבשה ולא יכלו.\u0004 אלו שלמדו עליו זכות משתדלים להשיבו לעולם הזה ואינם יכולים. מה הטעם, \u0003כי הים הולך וסוער עליהם,\u0004 גזרת הדין הולך וסוער בעונותיו של האדם ומתגבר בשבילם."],[8,"כדין נחתין עליה וכו':","אז יורדים עליו ג' שליחים ממונים, אחד, הכותב כל הזכיות וכל החובות שעשה האדם בעולם הזה. שהוא כנגד ב' קוין ימין ושמאל. שהזכיות בקו ימין והחובות בקו שמאל. ואחד שעושה חשבון הימים, שהוא כנגד קו המכריע השוקל אותם. ואחד שהיה הולך עמו כשהיה במעי אמו. שה\"ס המלכות, בסו\"ה בהלו נרו עלי ראשי, שנאמר על ירחי העיבור. והרי העמדנו שגזרת הדין אינו שוכך, עד עת ההוא שכתוב, \u0003וישאו את יונה,\u0004 וישאו, פירושו, כשנושאים אותו מביתו לבית הקברות."],[9,"כדין מכרזי עלוי וכו':","אז מכריזים עליו. אם הוא צדיק, מכרזים עליו ואומרים, תנו כבוד לצורת המלך. יבא שלום ינוחו על משכבותם הולך נכחו. מאין לנו. כי כתוב, והלך לפניך צדקך כבוד ה' יאספך. ואם הוא רשע, מכריזים עליו האומרים, אוי לו לפלוני, טוב לו שלא נברא. אז מה כתוב, \u0003ויטלהו אל הים ויעמוד הים מזעפו.\u0004 היינו כשמכניסים אותו אל הקבר, שהוא מקום הדין, אז גזרת הדין שהיה סוער ומבקש עליו דין, שכך עתה מזעפו. כי נתקיים מה שחפץ. והדג שבלעו, זהו הקבר."]],[[0,"","בַּיּוֹם הַחֲמִישִׁי בָּרָא אֶת דְּגֵי הַיָּם וְעוֹפוֹת הַשָּׁמַיִם, הִתְנָה עִם הָעוֹפוֹת שֶׁהָעוֹרְבִים יָזוּנוּ אֶת אֵלִיָּהוּ בַּזְּמַן שֶׁעָצַר אֶת הַשָּׁמַיִם, שֶׁכָּתוּב (מלכים א יז) וְאֶת הָעֹרְבִים צִוִּיתִי לְכַלְכֶּלְךְ שָׁם. צִוִּיתִי דַּוְקָא. וְהִתְנָה עִם דְּגֵי הַיָּם לְהַזְמִין דָּג אֶחָד שֶׁיִּבְלַע אֶת יוֹנָה וְלִזְרֹק אוֹתוֹ הַחוּצָה."],[1,"","בַּיּוֹם הַשִּׁשִּׁי בָּרָא אֶת הָאָדָם, וְהִתְנָה עִמּוֹ שֶׁתֵּצֵא מִמֶּנּוּ אִשָּׁה שֶׁתָּזוּן אֶת אֵלִיָּהוּ, שֶׁנֶּאֱמַר הִנֵּה צִוִּיתִי שָׁם אִשָּׁה אַלְמָנָה לְכַלְכְּלֶךְ. הִנֵּה צִוִּיתִי - מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם. וְכָךְ בְּכָל מַעֲשֶׂה וּמַעֲשֶׂה שֶׁהִתְחַדֵּשׁ בָּעוֹלָם, הַקָּדוֹשׁ בָּרוּךְ הוּא צִוָּה אֶת אוֹתוֹ מַעֲשֶׂה מִיּוֹם שֶׁנִּבְרָא הָאָדָם. אַף כָּאן וַיֹּאמֶר ה' לַדָּג, וַיֹּאמֶר - מִשֵּׁשֶׁת יְמֵי בְרֵאשִׁית אָמַר לוֹ."],[2,"","כָּאן יֵשׁ לָנוּ סֶמֶךְ הָעוֹלָם עַל מַעֲשֵׂי בְּנֵי אָדָם בָּעוֹלָם הַזֶּה. יוֹנָה שֶׁיָּרַד לַסְּפִינָה, זוֹהִי נִשְׁמַת הָאָדָם שֶׁיּוֹרֶדֶת לָעוֹלָם הַזֶּה לִהְיוֹת בְּגוּף הָאָדָם. לָמָּה נִקְרֵאת יוֹנָה? מִשּׁוּם שֶׁכֵּיוָן שֶׁמִּשְׁתַּתֶּפֶת בַּגּוּף, אֲזַי הִיא יוֹנָה בָּעוֹלָם הַזֶּה, כְּמוֹ שֶׁנֶּאֱמַר (ויקראכה) וְלֹא תוֹנוּ אִישׁ אֶת עֲמִיתוֹ. וְאָז הָאָדָם הוֹלֵךְ בָּעוֹלָם הַזֶּה כְּמוֹ סְפִינָה בְּתוֹךְ הַיָּם הַגָּדוֹל שֶׁמְּחַשֶּׁבֶת לְהִשָּׁבֵר, כְּמוֹ שֶׁנֶּאֱמַר וְהָאֳנִיָּה חִשְּׁבָה לְהִשָּׁבֵר."],[3,"","וְאָדָם, כְּשֶׁהוּא חוֹטֵא בָּעוֹלָם הַזֶּה וְחוֹשֵׁב שֶׁבּוֹרֵחַ מִלִּפְנֵי אֲדוֹנוֹ וְלֹא שָׂם לֵב לְאוֹתוֹ הָעוֹלָם, וְאָז מַטִּיל הַקָּדוֹשׁ בָּרוּךְ הוּא רוּחַ סְעָרָה חֲזָקָה - זוֹהִי גְּזֵרַת הַדִּין שֶׁעוֹמֶדֶת תָּמִיד לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וּמְבַקֶּשֶׁת אֶת דִּין הָאָדָם מִלְּפָנָיו, וְזוֹהִי שֶׁמַּטָּה אֶת הַסְּפִינָה וּמַזְכִּירָה אֶת חֲטָאֵי הָאָדָם לִתְפֹּס אוֹתוֹ."],[4,"","כֵּיוָן שֶׁנִּתְפָּס אָדָם עַל יְדֵי אוֹתָהּ סְעָרָה בְּבֵית חָלְיוֹ, מַה כָּתוּב? וְיוֹנָה יָרַד אֶל יַרְכְּתֵי הַסְּפִינָה וַיִּשְׁכַּב וַיֵּרָדַם. אַף עַל גַּב שֶׁאָדָם בְּבֵית חָלְיוֹ, הַנְּשָׁמָה לֹא מִתְעוֹרֶרֶת לָשׁוּב לִפְנֵי אֲדוֹנָהּ וְלִפְדּוֹת אֶת חֲטָאָיו. מַה כָּתוּב? וַיִּקְרַב אֵלָיו רַב הַחֹבֵל. מִי זֶה רַב הַחוֹבֵל? זֶה יֵצֶר טוֹב שֶׁמַּנְהִיג אֶת הַכֹּל. וַיֹּאמֶר לוֹ מַה לְּךְ נִרְדָּם קוּם קְרָא אֶל אֱלֹהֶיךְ וְגוֹ'. אֵין הַשָּׁעָה לִישֹׁן, שֶׁהֲרֵי מַעֲלִים אוֹתְךְ לַדִּין עַל כָּל מַה שֶּׁעָשִׂיתָ בָּעוֹלָם הַזֶּה, שׁוּב מֵחֶטְאֲךְ."],[5,"","הִתְבּוֹנֵן בַּדְּבָרִים הַלָּלוּ וְשׁוּב לַאֲדוֹנְךְ. מַה מְּלַאכְתְּךְ - שֶׁאַתָּה עָסַקְתָּ בָּהּ בָּעוֹלָם הַזֶּה, וְהוֹדֶה עָלֶיהָ לִפְנֵי רִבּוֹנְךְ. וּמֵאַיִן תָּבוֹא - הִסְתַּכֵּל מֵאַיִן בָּאתָ, מִטִּפָּה סְרוּחָה, וְאַל תִּתְגָּאֶה לְפָנָיו. מָה אַרְצֶךְ - הִסְתַּכֵּל שֶׁהֲרֵי מֵהָאָרֶץ נִבְרֵאתָ וְלָאָרֶץ תָּשׁוּב. וְאֵי מִזֶּה עַם אָתָּה - הִסְתַּכֵּל אִם יֵשׁ לְךְ זְכוּת אָבוֹת שֶׁתָּגֵן עָלֶיךְ."],[6,"","כֵּיוָן שֶׁמַּעֲלִים אוֹתוֹ לְדִין בְּבֵית דִּין שֶׁל מַעְלָה, אוֹתָהּ סְעָרָה, שֶׁהִיא גְּזֵרַת הַדִּין שֶׁסּוֹעֶרֶת עַל הָאָדָם, מְבַקֶּשֶׁת מֵהַמֶּלֶךְ לָדוּן אוֹתָם הַתְּפוּסִים שֶׁל הַמֶּלֶךְ, וְכֻלָּם בָּאִים אֶחָד אֶחָד לְפָנָיו. בְּאוֹתָהּ שָׁעָה מִתְקָרְבִים בֵּית הַדִּין. יֵשׁ מֵהֶם שֶׁפּוֹתְחִים בִּזְכוּת, וְיֵשׁ מֵהֶם שֶׁפּוֹתְחִים בְּחוֹבָה, וּגְזֵרַת הַדִּין תּוֹבַעַת דִּין."],[7,"","וְאִם אוֹתוֹ אָדָם לֹא זוֹכֶה בַדִּין, מַה כָּתוּב? וַיַּחְתְּרוּ הָאֲנָשִׁים לְהָשִׁיב אֶל הַיַּבָּשָׁה וְלֹא יָכֹלוּ. הֵם מִשְׁתַּדְּלִים אוֹתָם שֶׁמּוֹרִים זְכוּתוֹ לַהֲשִׁיבוֹ אֶל הָעוֹלָם הַזֶּה וְלֹא יָכֹלוּ. מָה הַטַּעַם? כִּי הַיָּם הוֹלֵךְ וְסֹעֵר עֲלֵיהֶם. גְּזֵרַת הַדִּין הוֹלֶכֶת וְסוֹעֶרֶת בַּחֲטָאֵי הָאָדָם וּמִתְגַּבֶּרֶת עֲלֵיהֶם."],[8,"","אֶחָד שֶׁכּוֹתֵב כָּל הַזְּכֻיּוֹת וְכָל הַחֲטָאִים שֶׁעָשָׂה הָאָדָם בָּעוֹלָם הַזֶּה. וְאֶחָד שֶׁעוֹשֶׂה חֶשְׁבּוֹן יָמָיו. וְאֶחָד שֶׁהָיָה הוֹלֵךְ עִמּוֹ כְּשֶׁהָיָה בִּמְעֵי אִמּוֹ, וַהֲרֵי בֵּאַרְנוּ שֶׁגְּזֵרַת הַדִּין לֹא שׁוֹכֶכֶת עַד לְאוֹתוֹ זְמַן, שֶׁכָּתוּב וַיִּשְׂאוּ אֶת יוֹנָה. וַיִּשְׂאוּ, כְּשֶׁנּוֹטְלִים אוֹתוֹ מִבֵּיתוֹ לְבֵית הַקְּבָרוֹת."],[9,"","וְאָז מַכְרִיזִים עָלָיו. אִם הוּא צַדִּיק - מַכְרִיזִים עָלָיו וְאוֹמְרִים: תְּנוּ כָבוֹד לִדְמוּת הַמֶּלֶךְ, (ישעיהנז) יָבוֹא שָׁלוֹם יָנוּחוּ עַל מִשְׁכְּבוֹתָם הֹלֵךְ נְכֹחוֹ. מִנַּיִן לָנוּ? שֶׁכָּתוּב (שם נח) וְהָלַךְ לְפָנֶיךְ צִדְקֶךְ כְּבוֹד ה' יַאַסְפֶךְ. וְאִם הוּא רָשָׁע - מַכְרִיזִים עָלָיו וְאוֹמְרִים: אוֹי לוֹ לִפְלוֹנִי, טוֹב לוֹ שֶׁלֹּא הָיָה נִבְרָא. וְאָז מַה כָּתוּב? וַיְטִלֻהוּ אֶל הַיָּם וַיַּעֲמֹד הַיָּם מִזַּעְפּוֹ. כְּשֶׁמַּכְנִיסִים אוֹתוֹ לְבֵית הַקְּבָרוֹת, שֶׁהוּא מְקוֹם הַדִּין, אָז גְּזֵרַת הַדִּין שֶׁהָיְתָה סוֹעֶרֶת, שׁוֹכֶכֶת מִזַּעְפָּהּ. וְהַדָּג שֶׁבָּלַע אוֹתוֹ זֶהוּ הַקֶּבֶר."]]],[["מַה כְּתִיב, וַיְהִי יוֹנָה בִּמְעֵי הַדָּג. מְעוֹי דְּדָּג, דָּא אִיהוּ בֶּטֶן שְׁאוֹל. מְנָלָן. דִּכְתִּיב, (יונה ב׳:א׳) מִבֶּטֶן שְׁאוֹל שִׁוַּעְתִּי. וְאִיהוּ בִּמְעֵי דְּנוּנָא הֲוָה, וְקָארֵי לֵיהּ בֶּטֶן שְׁאוֹל, שְׁלשָׁה יָמִים וּשְׁלֹשָׁה לֵילוֹת, אִלֵּין תְּלַת יוֹמִין, דְּבַר נָשׁ בְּקִבְרָא, וְאִתְבְּקָעוּ מֵעוֹי.","לְבָתַר תְּלָתָא יוֹמִין, הַהוּא טִנּוּפָא אִתְהַפַּךְ עַל אַנְפּוֹי, וְאוֹמֵר לוֹ טוֹל מַה דִּיְהָבַת בִּי. אַכְלַת וְשָׁתִית כָּל יוֹמָא, וְלָא יָהַבְתְּ לְמִסְכְּנֵי, וְכָל יוֹמָךְ הֲווֹ כְּחַגִּין וּכְמוֹעֲדִין, וּמִסְכְּנֵי הֲווֹ כַּפְנִין, דְּלָא אַכְלוּ בַּהֲדָךְ, טוֹל מַה דִּיְּהָבַת בִּי. הֲדָא הוּא דִּכְתִּיב, (מלאכי ב׳:ג׳) וְזֵרִיתִי פֶרֶשׁ עַל פְּנֵיכֶם וְגוֹ', וְהָא אוֹקִימְנָא.","לְבָתַר דָּא, מִתְּלָתָא יוֹמִין וּלְהָלְאָה, כְּדֵין אִתְדָּן בַּר נָשׁ מְעֵינוֹי, מִיְּדוֹי, וּמֵרַגְּלוֹי, וְאוּקְמוּהָ עַד תְּלָתִין יוֹמִין. כָּל אִינּוּן תְּלָתִין יוֹמִין, אִתְדָּנוּ נַפְשָׁא וְגוּפָא כַּחֲדָא. וּבְגִינֵי כַּךְ אִשְׁתְּכַח נִשְׁמְתָא לְתַתָּא בְּאַרְעָא, דְּלָא סַלְקַת לְאַתְרָהּ. כְּאִתְּתָא דְּיַתְבַת לְבַר, כָּל יוֹמֵי מְסַאֲבוּתָא. לְבָתַר, נִשְׁמְתָא סַלְּקָא, וְגוּפָא אִתְבְּלֵי בְּאַרְעָא. עַד הַהוּא זִמְנָא דְּיִתְּעַר קוּדְשָׁא בְּרִיךְ הוּא לְמֵיתַיָּיא.","וּזְמִינָא קָלָא חֲדָא לְאַתְּעָרָא בְּבֵי קִבְרִי, וְיֵימָא, (ישעיהו כ״ו:י״ט) הָקִיצוּ וְרַנְּנוּ שׁוֹכְנֵי עָפָר כִּי טַל אוֹרוֹת טַלֶּךָ וָאָרֶץ רְפָאִים תַּפִּיל. אֵימָתַי יְהֵא דָּא. בְּזִמְנָא דְּיִתְעַבָּר מַלְאָךְ הַמָּוֶת מֵעָלְמָא, דִּכְתִּיב, (ישעיהו כ״ה:ח׳) בִּלַּע הַמָּוֶת לָנֶצַח וְגוֹ'. כֵּיוָן דְּבִלַּע הַמָּוֶת לָנֶצַח, לְבָתַר, וּמָחָה יְיָ' אֱלֹהִים דִּמְעָה מֵעַל כָּל פָּנִים וְחֶרְפַּת עַמּוֹ יָסִיר מֵעַל כָּל הָאָרֶץ. כְּדֵין כְּתִיב, וַיֹּאמֶר יְיָ' לַדָּג וַיָּקֵא אֶת יוֹנָה אֶל הַיַּבָּשָׁה.","כֵּיוָן דְּאִתְּעַר הַהוּא קָלָא בֵּינֵי קִבְרֵי, כְּדֵין כָּל קִבְרַיָּיא יָקִיאוּ לְאִינּוּן מֵתַיָּיא דִּבְהוֹן לְבַר. הֲדָא הוּא דִכְתִיב וָאָרֶץ רְפָאִים תַּפִּיל. מַאי תַּפִּיל. דְּיָּקִיא לוֹן לְבַר. רְפָאִים, מַהוּ רְפָאִים. דְּקַבִּילוּ. אַסְוָותָא כְּמִלְּקַדְמִין, וְאַתְסִיאוּ גַּרְמִין בְּגַרְמִין. וְאִלֵּין אִקְרוּן רְפָאִים.","וְאִי תֵּימָא, הָא כְּתִיב (בשאר עובדי כוכבים ומזלות) (ישעיהו כ״ו:י״ד) רְפָאִים בַּל יָקוּמוּ. אֶלָּא וַדַּאי כָּל עָלְמָא יִתְּסוּן גַּרְמִין בְּבֵי קִבְרֵי, אֲבָל מִנְהוֹן יְקוּמוּן, וּמִנְהוֹן לָא יְקוּמוּן. וְעַל דָּא כְּתִיב רְפָאִים בַּל יָקוּמוּ. זַכָּאָה חוּלָקֵיהוֹן דְּיִשְׂרָאֵל, דִּכְתִּיב בְּהוּ נְבֵלָתִי יְקוּמוּן. וּבְהַאי נוּנָא, אַשְׁכַּחְנָא מִלִּין לְאַסְוָותָא, דְּכָל עָלְמָא.","הַאי נוּנָא כֵּיוָן דְּבָלַע לְיוֹנָה מִית. וּבֵיהּ הֲוָה יוֹנָה תְּלָתָא יוֹמִין, לְבָתַר אִתְקָיָּים כְּמִלְּקַדְמִין, וְאָקֵי לְיוֹנָה לְבַר, וְהָא אוּקְמוּהָ, דִּכְתִּיב וַיִּתְפַּלֵּל יוֹנָה אֶל יְיָ' אֱלֹהָיו מִמְּעֵי הַדָּגָה. כְּתִיב הָכָא הַדָּגָה, וּכְתִיב הָתָם (שמות ז׳:כ״א) וְהַדָּגָה אֲשֶׁר בַּיְאוֹר מֵתָה, וְהָא אוּקְמוּהָ. כְּגַוְונָא דָּא, זְמִינַת אַרְעָא דְּיִשְׂרָאֵל לְאַתְעֲרָא בְּקַדְמִיתָא, וּלְבָתַר וָאָרֶץ רְפָאִים תַּפִּיל.","וְהָא אוֹקִימְנָא, דְּשִׁבְעָה דִּינִין יַחְלְפוּן עָלֵיהּ דְּבַר נָשׁ, כַּד נָפִיק מֵהַאי עָלְמָא. חַד, הַהוּא דִּינָא עִלָּאָה, כַּד נָפִיק רוּחָא מִן גּוּפָא. ב', כַּד עוֹבָדוֹי וּמִלּוֹי אַזְלִין קַמֵּיהּ וּמַכְרִזֵי עֲלוֹי. ג', כַּד עָיִיִל לְקִבְרָא. ד', דִּינָא דְּקִבְרָא. ה', דִּינָא דְּתוֹלַעֲתָּא. ו', דִּינָא דְּגֵיהִנָּם. ז', דִּינָא דְּרוּחָא דְּאַזְלָא וְשָׁאטַת בְּעָלְמָא, וְלָא אַשְׁכָּחַת אֲתָר נַיְיחָא, עַד דְּיִשְׁתְּלִים עוֹבָדוֹי. בְּגִין דָּא, בָּעֵי בַּר נָשׁ לְאִסְתַּכְּלָא תָּדִיר בְּעוֹבָדוֹי, וְיֵתוּב קָמֵי מָרֵיהּ.","וְכַד אִסְתָּכָּל דָּוִד מַלְכָּא בְּדִינִין אִלֵּין דְּבַר נָשׁ, אַקְדִּים וְאָמַר (תהילים ק״ד:א׳) בָּרְכִי נַפְשִׁי אֶת יְיָ', עַד לָא תִּפּוּק מִן עָלְמָא, בְּעוֹד דְּאַנְתְּ אִשְׁתְּכָחַת עִם גּוּפָא. וְכָל קְרָבַי אֶת שֵׁם קָדְשׁוֹ, אִינּוּן שַׁיְיפֵי גּוּפָא, דְּמִשְׁתַּתְּפֵי כַּחֲדָא בְּרוּחָא. הַשְּׁתָּא דְּתִשְׁתַּכְּחוּן עִמָּהּ, אַקְדִּימוּ לְבָרְכָא שְׁמָא קַדִּישָׁא, עַד לָא יִמְטֵי זִמְנָא דְּלָא תֵּיכְלּוּן לְבָרְכָא, וּלְאָתָבָא בְּתִיּוּבְתָא, וְעַל דָּא אָמַר בָּרְכִי נַפְשִׁי אֶת יְיָ' הַלְלוּיָהּ. אָתוּ אִינּוּן חַבְרַיָּיא וְנַשְׁקוּ רֵישֵׁיהּ."],[[0,"מה כתיב, ויהי וכו':","מה כתוב, \u0003ויהי יונה במעי הדג.\u0004 מעיו של הדג, הם בטן שאול. מאין לנו שכתוב, מבטן שאול שועתי. שהוא היה במעי הדג, וקרא אותו, בטן שאול. \u0003שלשה ימים ושלשה לילות,\u0004 אלו הם ג' ימים שהאדם בקבר ומתבקעים מעיו."],[1,"לבתר תלתא יומין וכו':","אחר ג' ימים, טנוף ההוא שבמעיו, מתהפך על פניו, ואומר לו, קח מה שנתת בי, אכלת ושתית כל היום ולא נתת לעני, וכל ימיך היו כחגים וכמועדים, והעניים היו רעבים, שלא אכלו עמך, קח מה שנתת בי. ז\"ש, וזריתי פרש על פניכם וגו'. וכבר העמדנו."],[2,"לבתר דא מתלתא וכו':","לאח\"ז מג' ימים ולהלאה, אז נידון האדם, מעיניו, על מה שהסתכל במה שאסור. מידיו, על מה שעשה דברים האסורים, ומרגליו, על שהלך לדברי עבירה, והעמדנו, שזה נמשך עד ל' יום. כל אלו ל' יום, נדונים הנפש והגוף יחד. ומשום זה, נמצאת הנשמה למטה בארץ, שאינה עולית למקומה, כמו אשה שיושבת לחוץ כל ימי טומאתה. ואח\"כ הנשמה עולה, והגוף נרקב בעפר. עד זמן ההוא, שיתעורר הקב\"ה להחיות המתים."],[3,"וזמינא קלא חדא וכו':","ועתיד קול אחד, להתעורר בבית הקברות, ויאמר, הקיצו ורננו שוכני עפר כי טל אורות טלך וארץ רפאים תפיל. מתי יהיה זה. הוא בזמן שיהיה נעבר מלאך המות מן העולם, שכתוב, בלע המות לנצח וגו'. כיון דבלע המות לנצח, אחר כך, ומחה ה' אלקים דמעה מעל כל פנים וחרפת עמו יסיר מעל הארץ. אז כתוב, ויאמר ה' לדג ויקא את יונה אל היבשה."],[4,"כיון דאתער ההוא וכו':","כיון שנתעורר קול ההוא בין הקברים, אז כל הקברים יקיאו את המתים שבהם, לחוץ. ז\"ש וארץ רפאים תפיל. מהו תפיל, היינו שיקיא אותו לחוץ. \u0003רפאים,\u0004 מה הם רפאים. היינו אותם שקבלו רפואה, ונתרפאו והיו כמקודם לכן. ונרפאו עצמות אל עצמות (כמ\"ש בזהר פנחס ד\"י רכ\"א:) ואלו נקראים רפאים."],[5,"ואי תימא הא וכו':","ואם תאמר, הרי כתוב רפאים בל יקומו. ומשיב, אלא ודאי, כל בני העולם יתרפאו בעצמם בבית הקברות, אבל מהם יקומו לתחיה, ומהם לא יקומו לתחיה, דהיינו אותם שלא האמינו בתחית המתים. ועל זה כתוב, רפאים בל יקומו. אשרי חלקם של ישראל, שכתוב בהם, נבלתי יקומון. ובדג הזה, שבלע ליונה, מצאתי מרומזים בו דברים, לרפואת כל העולם, דהיינו לתחית המתים. כמבואר."],[6,"האי נונא כיון וכו':","דג הזה כיון שבלע את יונה מת, ובו היה יונה ג' ימים. אח\"כ חזר לתחיה כמקודם, והקיא את יונה לחוץ. והעמדנו, שכתוב ויתפלל יונה אל ה' אלקיו ממעי הדגה. כתוב כאן הדגה, וכתוב שם והדגה אשר ביאור מתה, אף כאן מתה הדגה. והעמדנו, כעין זה עתידה ארץ ישראל להתעורר בתחילה, דהיינו שתטהר מכל הרשעים, שהוא כמו הדגה של יונה, שקמה לתחיה, ואח\"כ, וארץ רפאים תפיל. שאח\"כ תקיאה המתים לתחיה. כנ\"ל."],[7,"והא אוקימנא דשבעה וכו':","והעמדנו, ששבעה דינים יעברו על האדם, כשיוצא ונפטר מן העולם. אחד, דין ההוא העליון כשיוצא הרוח מן הגוף. (כנ\"ל אות פ\"ו) דהיינו הדין של מיתה. ב) כשמעשיו ודבריו הולכים לפניו ומכריזים עליו. (כנ\"ל אות פ\"ח) ג) כשנכנס לקבר (כנ\"ל אות פ\"ח) ד) הדין של הקבר (כנ\"ל פ\"ט צ') ה) דין התולעים שאוכלים אותו. ו) דין הגיהנם. ז) דין הרוח, ההולך ומשטט בעולם, ואין לו מקום מנוחה, עד שיהיו נטהרים ונשלמים מעשיו. משום זה צריך האדם להסתכל תמיד במעשיו וישוב לפני אדונו."],[8,"וכד אסתכל דוד וכו':","וכשנסתכל דוד המלך בדינים אלו של האדם. הקדים ואמר, \u0003ברכי נפשי את ה'\u0004 מטרם שתצא מן העולם, בעוד שאת נמצאת עם הגוף. \u0003וכל קרבי את שם קדשו,\u0004 הם אברי הגוף המשתתפים יחד עם הרוח. עתה שאתם נמצאים עם הנפש, הקדימו לברך את השם הקדוש, מטרם שיגיע הזמן שלא תוכלו לברך ולשוב בתשובה. ועל זה אמר, ברכי נפשי את ה' הללויה. באו החברים ונשקו ראשו."]],[[0,"","מַה כָּתוּב? וַיְהִי יוֹנָה בִּמְעֵי הַדָּג. מְעִי הַדָּג זֶהוּ בֶּטֶן שְׁאוֹל. מִנַּיִן לָנוּ? שֶׁכָּתוּב מִבֶּטֶן שְׁאוֹל שִׁוַּעְתִּי. וְהוּא הָיָה בִּמְעֵי הַדָּג, וְקוֹרֵא לוֹ בֶּטֶן שְׁאוֹל, שְׁלֹשָׁה יָמִים וּשְׁלֹשָׁה לֵילוֹת. אֵלּוּ שְׁלֹשָׁה יָמִים שֶׁאָדָם בַּקֶּבֶר וְנִבְקָעִים מֵעָיו."],[1,"","לְאַחַר שְׁלֹשָׁה יָמִים אוֹתָהּ טִנֹּפֶת נֶהְפֶּכֶת עַל פָּנָיו, וְאוֹמֶרֶת לוֹ: טֹל מַה שֶּׁנָּתַתָּ בִּי. אָכַלְתָּ וְשָׁתִיתָ כָּל יוֹם וְלֹא נָתַתָּ לַעֲנִיִּים, וְכָל יָמֶיךְ הָיוּ כְּמוֹ חַגִּים וּמוֹעֲדִים, וְהָעֲנִיִּים הָיוּ רְעֵבִים, שֶׁלֹּא אָכְלוּ עִמְּךְ. טֹל מַה שֶּׁנָּתַתָּ בִּי. זֶהוּ שֶׁכָּתוּב (מלאכי ב) וְזֵרִיתִי פֶרֶשׁ עַל פְּנֵיכֶם וְגוֹ', וַהֲרֵי בֵּאַרְנוּ."],[2,"","לְאַחַר זֶה, מִשְּׁלֹשָׁה יָמִים וָהָלְאָה, אָז נִדּוֹן הָאָדָם מֵעֵינָיו, מִיָּדָיו, מֵרַגְלָיו, וּפֵרְשׁוּהָ עַד שְׁלֹשִׁים יָמִים. כָּל אוֹתָם שְׁלֹשִׁים יָמִים נִדּוֹנִים הַנֶּפֶשׁ וְהַגּוּף כְּאֶחָד, וּמִשּׁוּם כָּךְ הַנְּשָׁמָה נִמְצֵאת בָּאָרֶץ לְמַטָּה, שֶׁאֵינָהּ עוֹלָה לִמְקוֹמָהּ, כְּאִשָּׁה שֶׁיּוֹשֶׁבֶת בַּחוּץ כָּל יְמֵי הַטֻּמְאָה. אַחַר כָּךְ הַנְּשָׁמָה עוֹלָה, וְהַגּוּף נִרְקָב בָּאָרֶץ, עַד אוֹתוֹ זְמַן שֶׁיָּעִיר הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַמֵּתִים."],[3,"","וְעָתִיד קוֹל אֶחָד לְהָעִיר בְּבֵית הַקְּבָרוֹת וְיֹאמַר, (ישעיה כו) הָקִיצוּ וְרַנְּנוּ שֹׁכְנֵי עָפָר כִּי טַל אוֹרֹת טַלֶּךְ וָאָרֶץ רְפָאִים תַּפִּיל. אֵימָתַי זֶה יִהְיֶה? בִּזְמַן שֶׁיָּעֳבַר מַלְאַךְ הַמָּוֶת מִן הָעוֹלָם, שֶׁכָּתוּב (שם כה) בִּלַּע הַמָּוֶת לָנֶצַח וְגוֹ'. כֵּיוָן שֶׁבִּלַּע הַמָּוֶת לָנֶצַח, אַחַר כָּךְ, וּמָחָה ה' אֱלֹהִים דִּמְעָה מֵעַל כָּל פָּנִים וְחֶרְפַּת עַמּוֹ יָסִיר מֵעַל כָּל הָאָרֶץ. אָז כָּתוּב, וַיֹּאמֶר ה' לַדָּג וַיָּקֵא אֶת יוֹנָה אֶל הַיַּבָּשָׁה."],[4,"","כֵּיוָן שֶׁהִתְעוֹרֵר אוֹתוֹ קוֹל בֵּין הַקְּבָרִים, אֲזַי כָּל הַקְּבָרִים יָקִיאוּ אֶת אוֹתָם הַמֵּתִים שֶׁבָּהֶם הַחוּצָה. זֶהוּ שֶׁכָּתוּב וָאָרֶץ רְפָאִים תַּפִּיל. מַה זֶּה תַּפִּיל? שֶׁתָּקִיא אוֹתָם הַחוּצָה. רְפָאִים, מַה זֶּה רְפָאִים? שֶׁקִּבְּלוּ רְפוּאָה כְּמִקֹּדֶם, וְנִרְפְּאוּ עֲצָמוֹת בַּעֲצָמוֹת, וְאֵלֶּה נִקְרָאִים רְפָאִים."],[5,"","וְאִם תֹּאמַר, הֲרֵי כָּתוּב (בשאר עובדי כוכבים ומזלות) (ישעיה כו) רְפָאִים בַּל יָקוּמוּ? אֶלָּא וַדַּאי כָּל הָעוֹלָם יִתְרַפְּאוּ עַצְמוֹתָם בְּבֵית הַקְּבָרוֹת, אֲבָל מֵהֶם יָקוּמוּ וּמֵהֶם לֹא יָקוּמוּ. וְעַל זֶה כָּתוּב רְפָאִים בַּל יָקוּמוּ. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל, שֶׁכָּתוּב בָּהֶם נְבֵלָתִי יְקוּמוּן. וּבַדָּג הַזֶּה מָצָאנוּ דְבָרִים לִרְפוּאָה שֶׁל כָּל הָעוֹלָם."],[6,"","הַדָּג הַזֶּה, כֵּיוָן שֶׁבָּלַע אֶת יוֹנָה, הוּא מֵת, וּבוֹ הָיָה יוֹנָה שְׁלֹשָׁה יָמִים, וְאַחַר כָּךְ חָזַר לַחַיִּים כְּמִקֹּדֶם וְהֵקִיא אֶת יוֹנָה הַחוּצָה, וַהֲרֵי פֵּרְשׁוּהָ, שֶׁכָּתוּב וַיִּתְפַּלֵּל יוֹנָה אֶל ה' אֱלֹהָיו מִמְּעֵי הַדָּגָה. כָּתוּב כָּאן הַדָּגָה, וְכָתוּב שָׁם (שמות ז) וְהַדָּגָה אֲשֶׁר בַּיְאֹר מֵתָה, וַהֲרֵי פֵּרְשׁוּהָ. כְּמוֹ זֶה עֲתִידָה אֶרֶץ יִשְׂרָאֵל לְהִתְעוֹרֵר בָּרִאשׁוֹנָה, וְאַחַר כָּךְ - וָאָרֶץ רְפָאִים תַּפִּיל."],[7,"","וַהֲרֵי בֵּאַרְנוּ, שֶׁשִּׁבְעָה דִינִים יַחְלְפוּ עַל הָאָדָם כְּשֶׁיּוֹצֵא מִן הָעוֹלָם הַזֶּה. אֶחָד - אוֹתוֹ דִין עֶלְיוֹן כְּשֶׁיּוֹצֵאת הָרוּחַ מִן הַגּוּף. ב' - כְּשֶׁמַּעֲשָׂיו וּדְבָרָיו הוֹלְכִים לְפָנָיו וּמַכְרִיזִים עָלָיו. ג' - כְּשֶׁנִּכְנָס לַקֶּבֶר. ד' - דִּין הַקֶּבֶר. ה' - דִּין הַתּוֹלַעַת. ו' - דִּין הַגֵּיהִנֹּם. ז' - דִּין הָרוּחַ שֶׁהוֹלֶכֶת וּמְשׁוֹטֶטֶת בָּעוֹלָם וְלֹא מוֹצֵאת מְקוֹם מְנוּחָה עַד שֶׁיֻּשְׁלְמוּ מַעֲשָׂיו. מִשּׁוּם זֶה צָרִיךְ אָדָם לְהִתְבּוֹנֵן תָּמִיד בְּמַעֲשָׂיו וִיָשׁוּב לִפְנֵי אֲדוֹנוֹ."],[8,"","וּכְשֶׁהִתְבּוֹנֵןֹ דָּוִד הַמֶּלֶךְ בְּדִינֵי הָאָדָם הַלָּלוּ, הִקְדִּים וְאָמַר, (תהלים קד) בָּרְכִי נַפְשִׁי אֶת ה', בְּטֶרֶם תֵּצֵא מִן הָעוֹלָם, בְּעוֹד שֶׁאַתְּ נִמְצֵאת עִם הַגּוּף. וְכָל קְרָבַי אֶת שֵׁם קָדְשׁוֹ - הֵם אֶבְרֵי הַגּוּף שֶׁמִּשְׁתַּתְּפִים כְּאֶחָד עִם הָרוּחַ. עַכְשָׁו כְּשֶׁתִּמָּצְאוּ עִמָּהּ, הַקְדִּימוּ לְבָרֵךְ אֶת הַשֵּׁם הַקָּדוֹשׁ טֶרֶם שֶׁיָּבא זְמַן שֶׁלֹּא תוּכְלוּ לְבָרֵךְ וְלַחֲזֹר בִּתְשׁוּבָה. וְעַל זֶה אָמַר בָּרְכִי נַפְשִׁי אֶת ה' הַלְלוּיָהּ. בָּאוּ אוֹתָם הַחֲבֵרִים וְנָשְׁקוּ אֶת רֹאשׁוֹ."]]],[["רִבִּי חִיָּיא פָּתַח וְאָמַר, (שמות ל״ה:ה׳) קְחוּ מֵאִתְּכֶם תְּרוּמָה לַיְיָ'. תָּא חֲזֵי קוּדְשָׁא בְּרִיךְ הוּא כַּד בָּרָא עָלְמָא, לָא בָּרָא לֵיהּ, אֶלָּא בְּגִין דְּיִיִתוּן יִשְׂרָאֵל, וִיקַבְּלוּן אוֹרַיְיתָא. בְּאוֹרַיְיתָא אִתְבְּרֵי עָלְמָא, וְעַל אוֹרַיְיתָא קַיְּימָא. הֲדָא הוּא דִּכְתִּיב, (ירמיהו ל״ג:כ״ה) אִם לא בְרִיתִי יוֹמָם וָלָיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ לֹא שָׂמְתִּי. אוֹרַיְיתָא אִיהִי אַרְכָּא דְּחַיֵּי בְּהַאי עָלְמָא, וְאַרְכָּא דְּחַיֵּי בְּעָלְמָא דְּאָתֵי.","וְכָל מַאן דְּאִשְׁתַּדָל בְּאוֹרַיְיתָא, כְּאִלוּ אִשְׁתָּדַּל בְּהֵיכָלֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא. דְּהֵיכְלָא עִלָּאָה דְּקוּדְשָׁא בְּרִיךְ הוּא, אוֹרַיְיתָא אִיהִי. וְכַד בַּר נָשׁ עָסִיק בְּאוֹרַיְיתָא, קוּדְשָׁא בְּרִיךְ הוּא קָאִים תַּמָּן, וְאָצִית לְקָלֵיהּ, כְּמָה דִּכְתִּיב, (מלאכי ג) וַיַּקְשֵׁב יְיָ' וַיִּשְׁמָע וְגוֹ'. וְאִשְׁתְּזִיב בַּר נָשׁ מִתְּלַת דִּינִין: מִדִּינָא דְּהַאי עָלְמָא. וּמִדִּינָא דְּמַלְאָךְ הַמָּוְת, דְּלָא יָכִיל לְשַׁלְּטָאָה עָלֶיהָ. וּמִדִּינָא דְּגֵיהִנָּם.","וַיִּכָּתֵב סֵפֶר (ע' ע\"א) זִכָּרוֹן. מַאי אִיהוּ. אֶלָּא אִית סֵפֶר לְעֵילָּא, וְאִית סֵפֶר לְתַתָּא. זִכָּרוֹן אֲתַר (נ\"א את) קַיָּימָא קַדִּישָׁא, דְּנָטִיל וְכָנִישׁ לְגַבֵּיהּ, כָּל חַיִּין דִּלְעֵילָּא. סֵפֶר זִכָּרוֹן תְּרֵין דַּרְגִּין דְּאִינּוּן חַד, וְרָזָא דָּא שֵׁם יְהוָֹ\"ה שֵׁם חַד. יְהוָֹ\"ה חַד. וְכֹלָּא מִלָּה חֲדָא.","בְּגִין דְּאִית שֵׁם, וְאִית שֵׁם, שֵׁם (קס\"ב ע\"א) לְעֵילָּא, דְּאִיהוּ אִתְרְשִׁים (ס\"א אקרי שם) מִמַּה דְּלָא יְדִיעַ, וְלָא אִתְרְמִיז בִּידִיעָה כְּלַל. וְדָא אִקְרֵי נְקוּדָה (צ\"ג ע\"א) עִלָּאָה. שֵׁם לְתַתָּא, דְּאִקְרֵי שֵׁם, (דברים ד׳:ל״ב) מִקְצֵה הַשָּׁמַיִם וְעַד קְצֵה הַשָּׁמַיִם, בְּגִין דִּקְצֵה הַשָּׁמַיִם אִקְרֵי זִכָּרוֹן. וְהַאי שֵׁם, אִיהוּ נְקוּדָה דִּלְתַתָּא, דְּאִיהוּ שֵׁם מֵהַהוּא זִכָּרוֹן, דְּאִיהוּ קְצֵה הַשָּׁמַיִם, דְּנָטִיל כָּל חַיִּין דִּלְעֵילָּא. וְדָא אִיהוּ קְצֵה הַשָּׁמַיִם דִּלְתַתָּא. וְשֵׁם דִּילֵיהּ אִיהִי נְקוּדָה דִּלְתַתָּא. נְקוּדָה דָּא, אִיהוּ סֵפֶר דְּקַיְּימָא בְּחוּשְׁבָּנָא, וְדָא הוּא וּלְחוֹשְׁבֵי שְׁמוֹ. סֵפֶר דְּקָאָמַרָן, וְשֵׁם, חַד מִלָה הוּא, בְּכָל סִטְרִין.","נְקוּדָה דָּא בְּגִין דְּקַיְּימָא בְּאֶמְצָעִיתָא, אִיהִי עִלָּאָה עַל כָּל דְּאִתְאַחֲדָן בָּה. שִׁית סִטְרִין, אִתְאַחֲדָן בְּסֵפֶר (קל\"ז ע\"ב) עִלָּאָה, וְאִיהוּ עִלָּאָה עָלַיְיהוּ. שִׁית סִטְרִין אִתְאַחֲדָן בְּסֵפֶר תַּתָּאָה, וְאִיהוּ עִלָּאָה עָלַיְיהוּ. וְעַל דָּא, סֵפֶר עִלָּאָה, סֵפֶר תַּתָּאָה, וְכֹלָּא אִקְרֵי תּוֹרָה.","מַה בֵּין הַאי לְהַאי. אֶלָּא, סֵפֶר עִלָּאָה אִיהוּ תּוֹרָה שֶׁבִּכְתָּב. בְּגִין דְּאִיהִי (רי\"ד ע\"א, שמיני מ' ע\"ב) סְתִימָא, וְלָא קַיְּימָא אֶלָּא בִּכְתַב, דְּתַמָּן אִיהוּ אֲתָר לְאִתְגַלָאָה לְתַתָּא. וּמַאן אִיהוּ עָלְמָא דְּאָתֵי. סֵפֶר תַּתָּאָה, דָּא תּוֹרָה דְּאִקְרֵי תּוֹרָה שֶׁבְּעַל פֶּה, וּמַאן אִיהוּ עַל פֶּה, אִלֵּין רְתִיכִין דִּלְתַתָּא, דְּאִיהִי קַיְּימָא עָלַיְיהוּ. וּבְגִין דְּלָאו אִינּוּן בִּכְלָלָא דִּכְתִּיבָה דִּלְעֵילָּא, אִקְרוּן עַל פֶּה.","וְתוֹרָה דָּא קַיְּימָא עַל פֶּה, בְּגִין דִּכְתִּיב, (בראשית ב׳:י׳) וּמִשָּׁם יִפָּרֵד וְהָיָה לְאַרְבָּעָה רָאשִׁים וְתוֹרָה עִלָּאָה, אַף עַל גַּב דְּאִיהִי קַיְּימָא לְעֵילָּא, לָא אִקְרֵי עַל הַכְּתָב, אֶלָּא שֶׁבִּכְתָּב, דְּקַיְּימָא בִּכְתָּב, וְהַהוּא כְּתָב אִתְעָבִיד הֵיכָלָא לְגַבֵּיהּ, וְאִיהִי קַיְּימָא גּוֹ הַהוּא הֵיכָלָא, וְאִתְטַמְּרָת תַּמָּן. וּבְגִין כַּךְ אִקְרֵי תּוֹרָה שֶׁבִּכְתָּב, וְלָא עַל כְּתָב.","אֲבָל תּוֹרָה דִּלְתַתָּא, אִיהִי קַיְּימָא עַל רְתִיכָהָא, וְאִקְרֵי עַל פֶּה, דְּקַיְּימָא עָלַיְיהוּ. וּבְגִין דְּלָא אִתְחַשִׁיבָת (נ\"א אתיהיבת) מִלְּגוֹ, מִכְּלָלָא דִּכְתִּיבָה, לָא אִתְעָבִידוּ הֵיכָלָא לְהַאי נְקוּדָה, כְּהַהִיא נְקוּדָה עִלָּאָה. וּבְגִין דְּקַיְּימָא עָלַיְיהוּ אִקְרֵי תְּרוּמָה.","תּוּ שְׁמַעְנָא מִבּוּצִינָא קַדִּישָׁא. תְּרוּמָה. מַהוּ תְּרוּמָה. כְּמָה דְּאוֹקִימְנָא, תְּרֵי מִמֵּאָה. תָּא חֲזֵי, כָּל אִינּוּן דַּרְגִּין קַדִּישִׁין, דִּי בְּרָזָא דִּמְהֵימְנוּתָא, דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְגְּלֵי בְּהוֹן, אִינּוּן עֶשֶׂר דַּרְגִּין, וְאִינּוּן עֶשֶׂר אֲמִירָן, כְּמָה דְּאוּקְמוּהָ. וְאִלֵּין עֶשֶׂר סַלְּקִין לַמְּאָה, וְכַד אִצְטְרִיךְ לָן לְהַאי נְקוּדָה תַּתָּאָה לְאַרְמָא לָהּ, אָסִיר לָן לְנַטְלָא לָהּ בִּלְחוֹדָהָא. אֶלָּא לָהּ וּלְבַעְלָהּ. וְאִינּוּן תְּרֵי מֵאִינּוּן מֵאָה דְּקָאָמַרָן, בְּגִין דְּלָא אִצְטְרִיךְ לְאַפְרְשָׁא לוֹן כְּלָל, אֶלָּא לְיַחֲדָא לָהּ וּלְבַעְלָהּ. וְעַל דָּא אִתְקְרֵי תְּרוּמָה בִּכְלָלָא חֲדָא.","וְתָא חֲזֵי, בְּכָל יוֹמָא כָּרוֹזָא קָארֵי, כָּל בְּנֵי עָלְמָא, בְּכוּ קַיָּימָא מִלָּה דָּא, וְדָא הוּא (שמות ל״ה:ה׳) קְחוּ מֵאִתְּכֶם תְּרוּמָה לַיְיָ'. וְאִי תֵּימָא דְּקַשְׁיָא מִלָּה עָלַיְיכוּ. כֹּל נְדִיב לִבּוֹ יְבִיאֶהָ."],[[0,"ר' חייא פתח וכו':","ר\"ח פתח ואמר, קחו מאתכם תרומה לה', בוא וראה כשהקב\"ה ברא את העולם, לא ברא אותו אלא כדי שיבואו ישראל ויקבלו התורה. בתורה נברא העולם ועל התורה עומד, ז\"ש אם לא בריתי יומם ולילה חקות שמים וארץ לא שמתי. התורה היא אריכת החיים בעולם הזה, והיא אריכת החיים בעולם הבא."],[1,"וכל מאן דאשתדל וכו':","וכל מי שמשתדל בתורה כאלו משתדל בהיכל הקב\"ה, שהיכל העליון של הקב\"ה, שהוא מלכות, הוא תורה. והיינו תורה שבעל פה, שה\"ס מלכות. וכשהאדם עוסק בתורה, הקב\"ה עומד שם ומקשיב לקולו, כמ\"ש, ויקשב ה' וישמע וגו'. והאדם ניצל מג' דינים, מדין שבעולם הזה, ומדין של מלאך המות, שאינו יכול לשלוט עליו, ומדין של גיהנם."],[2,"ויכתב ספר זכרון:","שואל, מה הוא ספר זכרון. ומשיב, אלא יש ספר למעלה, שהוא חכמה, ויש ספר למטה, שהוא מלכות, \u0003זכרון,\u0004 הוא אות הברית הקדוש, שהוא יסוד, שלוקח ומקבץ אליו כל החיים שלמעלה, דהיינו כל המוחין העליונים \u0003ספר זכרון,\u0004 הם ב' מדרגות שהן אחת. וזה סוד, \u0003שם הויה,\u0004 ש\"ם, הוא אחד, דהיינו המלכות, הוי\"ה הוא אחד, דהיינו ז\"א, והכל מלה אחת הוא, כן ספר זכרון מלה אחת הוא, אבל כולל ב' מדרגות שהן מלכות ויסוד."],[3,"בגין דאית שם","וכו': משום שיש שם, ויש שם, ומפרש יש שם למעלה, שהוא נרשם ממה שלא ידוע ולא נרמז בידיעה, כלל, דהיינו מכתר, וזה נקרא נקודה עליונה, שהיא חכמה. ויש \u0003שם\u0004 למטה, שהיא המלכות, הנקראת \u0003שם.\u0004 שכתוב, מקצה השמים ועד קצה השמים, כי קצה השמים, שהוא יסוד, נקרא זכרון, \u0003ושם\u0004 ההוא הוא נקודה שלמטה מיסוד, דהיינו המלכות, שהיא \u0003שם,\u0004 של זכרון ההוא, שהוא קצה השמים, הנוטל כל החיות שלמעלה, שהם המוחין. וזה הוא קצה השמים למטה, יסוד, וה \u0003שם\u0004 שלו הוא נקודה שלמטה, מלכות, ונקודה זו, הוא ספר העומד בחשבון, דהיינו מוחין החשובים דמספר. (כנ\"ל בהקסה\"ז דף כ\"ב ד\"ה במספר ע\"ש) וזה הוא, \u0003ולחושבי שמו.\u0004 דהיינו ויכתב ספר זכרון לפניו ליראי ה' ולחושבי שמו. שהספר זכרון הוא \u0003לחושבי\u0004 שמו, שמשפיע מוחין \u0003דחשבון\u0004 ומספר. \u0003ספר\u0004 שאמרנו \u0003ושם\u0004 הם דבר אחד מכל הבחינות דהיינו מלכות."],[4,"נקודה דא בגין","וכו': נקודה זו משום שעומדת באמצע, היא עליונה על כל אלו שנתאחדו בה. ומפרש ששה קצוות שהם ישסו\"ת, נתאחדו בספר העליון, שהוא חכמה, והיא עליונה עליהם. ששה קצוות שהם ו' היכלות דבריאה, נתאחדו בספר התחתון, שהוא מלכות, והוא עליון עליהם. וע\"כ ספר עליון, ספר תחתון. והכל נקרא תורה."],[4,"","פירוש. חכמה עלאה, שהוא ספר העליון, מבחינת עצמה נעלמת לגמרי, שה\"ס או\"א עלאין אלא היא מתגלית על ידי הבינה שהיא ישסו\"ת, כי בה מתגלה החכמה, אמנם לא במקומה עצמה, אלא כדי שתשפיע אל המלכות, שה\"ס ספר התחתון. וע\"כ נקראים ישסו\"ת שהם מרכבה אל החכמה עליונה. וגם המלכות אחר שנתקנה בסוד נקודה אמצעית דישובא (כנ\"ל תצוה אות צ\"ח) כבר אין החכמה מתגלה בה עצמה אלא ע\"י ז' היכלות שלה שבבריאה, שהסו\"ה בתולות אחריה רעותיה מובאות לך, כי בהם מתלבשים כלים דאחורים של המלכות ואין מקום גילוי החכמה אלא בכלים דאחורים של המלכות. (כנ\"ל בהקסה\"ז דף ו' ד\"ה ואלמלא ע\"ש). וז\"ש, \u0003נקודה דא בגין דקיימא באמצעיתא,\u0004 דהיינו באמצע הישוב, שחזרה לבחינת פנים, ע\"כ \u0003איהי עלאה על כל דאתאחדן בה.\u0004 שהיא עליונה על ששה קצוות שהם ז' היכלות דבריאה המתאחדים בה, כלומר אע\"פ שאחורים של המלכות מלובשים בהם והם מתאחדים בה, והחכמה מתגלה עליהם אינם מחוברים יחד עם המלכות, כי המלכות היא פנים ובחינת חסדים, והם בחינת אחורים וכלי גילוי לחכמה דשמאל. וע\"כ הזהר מדמה אותה לחכמה עלאה, שה\"ס ספר עליון, שהם או\"א עלאין, שהם עצמם בבחינת חסדים, והחכמה שבהם, מתגלית בכלים דישסו\"ת, שהם ששה קצוות שלהם. כך המלכות היא בבחינת חסדים אחר שנתקנה לבחינת נקודה האמצעית דישוב, והחכמה שלה מתגלית בו\"ק שלה, שהם ז' היכלות דבריאה, וז\"ש \u0003שית סטרין אתאחדן בספר עלאה, ואיהו עלאה עלייהו, שית סטרין אתאחדן בספר תתאה ואיהו עלאה עלייהו.\u0004 שמבחינה זו, ספר העליון וספר התחתון דומים זה לזה. שהם עצמם בבחינת חסדים, והחכמה שבהם מתגלית במרכבה שלהם, כמבואר. וז\"ש וע\"ד, \u0003ספר עלאה ספר תתאה וכלא אקרי תורה,\u0004 וע\"כ נקראים שניהם ספר ושניהם נקראים תורה. כי שוים זה לזה."],[5,"מה בין האי וכו':","שואל, מה ההפרש בין זה לזה, בין ספר עליון לספר תחתון. ומשיב, אלא ספר העליון הוא \u0003תורה שבכתב,\u0004 שהוא חכמה עלאה, משום שהיא סתומה ואינה עומדת אלא בכתב, דהיינו שראוי להתגלות, כי שם הוא מקום, דהיינו ישסו\"ת, שיתגלה החכמה למטה, במלכות, ומי הוא המקום, הוא עולם הבא, דהיינו ישסו\"ת. ספר התחתון, זה הוא תורה הנקראת \u0003תורה שבעל פה,\u0004 ומי הוא על פה, אלו הם המרכבות שלמטה, דהיינו ז' היכלות דבריאה, שהמלכות עומדת עליהם. כנ\"ל בדבור הסמוך, ומשום שאינם בכלל הכתיבה העליונה, כלומר שאינם בבחינת העלם כמו חכמה עלאה שבישסו\"ת הנקרא כתב, ע\"כ נקראים \u0003על פה,\u0004 שהוא הגילוי מה שיש בכתב. כי במקום המלכות מתגלה החכמה בכלים דאחורים שלה, שהם ההיכלות דבריאה."],[6,"ותורה דא קיימא וכו':","ותורה זו עומדת, על פה. דהיינו על ז' היכלות, שהם הפה שלה לגילוי החכמה, משום שכתוב, ומשם יפרד והיה לארבעה ראשים דהיינו שמן הגן, שהוא מלכות ולמטה מתחיל עולם הפירוד, נמצא שז' היכלות דבריאה, כבר הם בעולם הפירוד, ע\"כ המלכות עומדת ממעל להם, דהיינו \u0003על\u0004 פה. ותורה העליונה, שהיא חכמה עלאה, אע\"פ שגם היא עומדת למעלה מן המרכבה שלה, שהם ישסו\"ת, כנ\"ל, מכל מקום לא נקראת תורה שעל הכתב, אלא שבכתב, שעומדת בתוך הכתב, וכתב ההוא, שהוא ישסו\"ת, נעשה היכל על החכמה העליונה והחכמה עליונה עומדת תוך היכל ההוא ונסתרת שם, כלומר, כי הכתב שהוא ישסו\"ת היא ג\"כ עולם אצילות כמו חכמה העליונה, ע\"כ נחשב הכתב, להיכל שלה, ונקראת משום זה, תורה שבכתב ולא תורה שעל הכתב."],[7,"אבל תורה דלתתא וכו':","אבל תורה שלמטה, שהיא המלכות, היא עומדת \u0003על\u0004 המרכבה שלה ונקראת \u0003על\u0004 פה, כי היא עומדת עליהם. ומשום שאינה נחשבת מפנימיות מכלל הכתיבה, כלומר, שאין החכמה שבה נעלמת ע\"י ההיכלות, כמו התורה שבכתב, כי כתיבה יורה העלם עד שבא מי וקורא הכתב ומגלהו, והחכמה שבה מתגלה בהיכלות ואינה נעלמת, ע\"כ לא נעשו ז' היכלות, לבחינת היכל לנקודה ההיא, מלכות, כמו הישסו\"ת שנעשה היכל לנקודה העליונה. כי היכל פירושו כיסוי, והם אינם מכסים. אמנם בפני עצמם נקראים גם הם היכלות, וזהו משום שהחכמה שבהם היא בבחינת אחורים. ומשום שהמלכות עומדת עליהם, היא נקראת \u0003תרומה.\u0004"],[8,"תו שמענא מבוצינא וכו':","עוד שמעתי ממאור הקדוש. \u0003תרומה.\u0004 מהו תרומה. הוא כמו שהעמדנו, בהפרשת התרומה לכהן, שהוא שנים חלקים ממאה חלקים. בוא וראה, כל אלו מדרגות הקדושות שהם בסוד האמונה, שהקב\"ה מתגלה בהם, הן עשר מדרגות, והם עשרה מאמרות, דהיינו עשר ספירות, כמו שהעמדנו, ואלו העשר, עולות למאה, כי כל ספירה כוללת עשר ספירות. וכשאנו צריכים להרים לנקודה התחתונה הזו, דהיינו מלכות, אסור לנו לקחת אותה לבדה, אלא אותה ובעלה, שהוא יסוד, והם שנים, דהיינו שתי ספירות יסוד ומלכות, מאלו המאה שאמרנו. כי לא צריך להפרידה כלל, אלא ליחד אותה ובעלה. וע\"כ נקראת \u0003תרומה,\u0004 בכלל אחד. שהם יסוד ומלכות."],[9,"ותא חזי בכל וכו':","ובוא וראה, בכל יום קורא כרוז, לכל בני העולם, בכם תלוי דבר זה. וזה הוא, \u0003קחו מאתכם תרומה לה'.\u0004 ואם תאמרו, שהדבר קשה מכם, \u0003כל נדיב לב יביאה.\u0004"]],[[0,"","רַבִּי חִיָּיא פָּתַח וְאָמַר, קְחוּ מֵאִתְּכֶם תְּרוּמָה לַה'. בּא וּרְאֵה, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, לֹא בְרָאוֹ אֶלָּא כְּדֵי שֶׁיָּבֹאוּ יִשְׂרָאֵל וִיקַבְּלוּ אֶת הַתּוֹרָה. בַּתּוֹרָה נִבְרָא הָעוֹלָם, וְעַל הַתּוֹרָה הוּא עוֹמֵד. זֶהוּ שֶׁכָּתוּב (ירמיה לג) אִם לֹא בְרִיתִי יוֹמָם וָלַיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ לֹא שָׂמְתִּי. הַתּוֹרָה הִיא אֹרֶךְ חַיִּים בָּעוֹלָם הַזֶּה, וְאֹרֶךְ הַחַיִּים בָּעוֹלָם הַבָּא."],[1,"","וְכָל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, כְּאִלּוּ הִשְׁתַּדֵּל בְּהֵיכָלוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהֵיכָלוֹ הָעֶלְיוֹן שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא הִיא הַתּוֹרָה. וּכְשֶׁאָדָם עוֹסֵק בַּתּוֹרָה, הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹמֵד שָׁם וּמַקְשִׁיב לְקוֹלוֹ, כַּכָּתוּב (מלאכי ג) וַיַּקְשֵׁב ה' וַיִּשְׁמָע וְגוֹ'. וְנִצּוֹל הָאָדָם מִשְּׁלֹשָׁה דִינִים: מִדִּין הָעוֹלָם הַזֶּה, וּמִדִּין מַלְאַךְ הַמָּוֶת שֶׁלֹּא יָכוֹל לִשְׁלֹט עָלָיו, וּמִדִּין הַגֵּיהִנֹּם."],[2,"","וַיִּכָּתֵב סֵפֶר זִכָּרוֹן. מִי הוּא? אֶלָּא יֵשׁ סֵפֶר לְמַעְלָה וְיֵשׁ סֵפֶר לְמַטָּה. זִכָּרוֹן - (אות) הַבְּרִית הַקָּדוֹשׁ שֶׁנּוֹטֵל וְכוֹנֵס אֵלָיו אֶת כָּל הַחַיִּים שֶׁלְּמַעְלָה. סֵפֶר זִכָּרוֹן - שְׁתֵּי דְרָגוֹת שֶׁהֵן אַחַת, וְסוֹד זֶה שֵׁם יְהֹוָ\"ה שֵׁם אֶחָד. יְהֹוָ\"ה אֶחָד. וְהַכֹּל דָּבָר אֶחָד."],[3,"","מִשּׁוּם שֶׁיֵּשׁ שֵׁם וְיֵשׁ שֵׁם. שֵׁם לְמַעְלָה, שֶׁהוּא נִרְשָׁם (נקרא שם) מִמַּה שֶּׁלֹּא יָדוּעַ וְלֹא נִרְמָז בִּידִיעָה כְּלָל, וְזוֹ נִקְרֵאת נְקֻדָּה עֶלְיוֹנָה. שֵׁם לְמַטָּה, שֶׁנִּקְרָא שֵׁם, מִקְצֵה הַשָּׁמיִם וְעַד קְצֵה הַשָּׁמַיִם, מִשּׁוּם שֶׁקְּצֵה הַשָּׁמַיִם נִקְרָא זִכָּרוֹן. וְהַשֵּׁם הַזֶּה הוּא נְקֻדָּה שֶׁלְּמַטָּה, שֶׁהוּא שֵׁם מֵאוֹתוֹ זִכָּרוֹן, שֶׁהוּא קְצֵה הַשָּׁמַיִם, שֶׁנּוֹטֵל אֶת כָּל הַחַיִּים שֶׁלְּמַעְלָה. וְזֶהוּ קְצֵה הַשָּׁמַיִם שֶׁלְּמַטָּה. וְהַשֵּׁם שֶׁלּוֹ הִיא הַנְּקֻדָּה שֶׁלְּמַטָּה. נְקֻדָּה זוֹ הִיא סֵפֶר שֶׁעוֹמֵד בְּחֶשְׁבּוֹן, וְזֶהוּ וּלְחֹשְׁבֵי שְׁמוֹ. הַסֵּפֶר שֶׁאָמַרְנוּ וְשֵׁם - דָּבָר אֶחָד הוּא בְּכָל הַצְּדָדִים."],[4,"","הַנְּקֻדָּה הַזּוֹ, מִשּׁוּם שֶׁהִיא עוֹמֶדֶת בָּאֶמְצַע, הִיא עֶלְיוֹנָה עַל כָּל הַנֶּאֱחָזִים בָּהּ. שִׁשָּׁה צְדָדִים אֲחוּזִים בַּסֵפֶר הָעֶלְיוֹן, וְהוּא עֶלְיוֹן עֲלֵיהֶם. שִׁשָּׁה צְדָדִים נֶאֱחָזִים בַּסֵּפֶר הַתַּחְתּוֹן, וְהוּא עֶלְיוֹן עֲלֵיהֶם. וְעַל זֶה סֵפֶר עֶלְיוֹן וְסֵפֶר תַּחְתּוֹן, וְהַכֹּל נִקְרָא תּוֹרָה."],[5,"","מַה בֵּין זֶה לָזֶה? אֶלָּא, סֵפֶר עֶלְיוֹן הוּא תּוֹרָה שֶׁבִּכְתָב, מִשּׁוּם שֶׁהִיא סְתוּמָה וְלֹא עוֹמֶדֶת, אֶלָּא רַק בִּכְתָב, שֶׁשָּׁם הוּא הַמָּקוֹם לְהִתְגַּלּוֹת לְמַטָּה. וּמִי הוּא הָעוֹלָם הַבָּא? סֵפֶר הַתַּחְתּוֹן, זוֹ תּוֹרָה שֶׁנִּקְרֵאת תּוֹרָה שֶׁבְּעַל פֶּה. וּמִי הוּא עַל פֶּה? אֵלּוּ הַמֶּרְכָּבוֹת שֶׁל מַטָּה, שֶׁהִיא עוֹמֶדֶת עֲלֵיהֶן. וּמִשּׁוּם שֶׁאֵינָן בִּכְלָל שֶׁל כְּתִיבָה שֶׁלְּמַעְלָה, נִקְרָאִים עַל פֶּה."],[6,"","וְתוֹרָה זוֹ עוֹמֶדֶת עַל פֶּה, מִשּׁוּם שֶׁכָּתוּב (בראשית ב) וּמִשָּׁם יִפָּרֵד וְהָיָה לְאַרְבָּעָה רָאשִׁים. וְתוֹרָה הָעֶלְיוֹנָה, אַף עַל גַּב שֶׁהִיא עוֹמֶדֶת לְמַעְלָה, לֹא נִקְרֵאת עַל הַכְּתָב, אֶלָּא שֶׁבִּכְתָב, שֶׁעוֹמֶדֶת בִּכְתָב, וְאוֹתוֹ הַכְּתָב נַעֲשֶׂה הֵיכָל אֵלֶיהָ, וְהִיא עוֹמֶדֶת בְּתוֹךְ אוֹתוֹ הַהֵיכָל וְנִשְׁמֶרֶת שָׁם. וּמִשּׁוּם כָּךְ נִקְרֵאת תּוֹרָה שֶׁבִּכְתָב וְלֹא עַל כְּתָב."],[7,"","אֲבָל הַתּוֹרָה שֶׁלְּמַטָּה הִיא עוֹמֶדֶת עַל מַרְכְּבוֹתֶיהָ, וְנִקְרֵאת עַל פֶּה, שֶׁעוֹמֶדֶת עֲלֵיהֶן. וּמִשּׁוּם שֶׁלֹּא נֶחְשֶׁבֶת (נתנה) מִבִּפְנִים מִכְּלָל שֶׁל כְּתִיבָה, לֹא נַעֲשׂוּ הֵיכָל לַנְּקֻדָּה הַזּוֹ כְּמוֹ אוֹתָהּ נְקֻדָּה עֶלְיוֹנָה. וּמִשּׁוּם שֶׁעוֹמֶדֶת עֲלֵיהֶן נִקְרֵאת תְּרוּמָה."],[8,"","עוֹד שָׁמַעְתִּי מִן הַמְּנוֹרָה הַקְּדוֹשָׁה. תְּרוּמָה, מַה זֶּה תְּרוּמָה? כְּמוֹ שֶׁבֵּאַרְנוּ, שְׁנַיִם מִמֵּאָה. בֹּא וּרְאֵה, כָּל הַדְּרָגוֹת הַלָּלוּ הַקְּדוֹשׁוֹת שֶׁבְּסוֹד הָאֱמוּנָה שֶׁנִּגְלָה בָהֶן הַקָּדוֹשׁ בָּרוּךְ הוּא, הֵן עֶשֶׂר דְּרָגוֹת, וְהֵן עֶשֶׂר אֲמִירוֹת, כְּמוֹ שֶׁבֵּאֲרוּהָ. וְאֵלּוּ הָעֶשֶׂר עוֹלִים לְמֵאָה. וּכְשֶׁאָנוּ צְרִיכִים הַנְּקֻדָּה הַתַּחְתּוֹנָה הַזּוֹ לְהָרִים אוֹתָהּ, אָסוּר לָנוּ לְקַחְתָּהּ לְבַדָּהּ, אֶלָּא אוֹתָהּ עִם בַּעְלָהּ, וְהֵם הַשְּׁנַיִם מֵהַמֵּאָה שֶׁאָמַרְנוּ, מִשּׁוּם שֶׁאֵין צָרִיךְ לְהַפְרִידָם כְּלָל, אֶלָּא לְיַחֲדָהּ עִם בַּעְלָהּ. וְלָכֵן נִקְרֵאת תְּרוּמָה בִּכְלָל אֶחָד."],[9,"","וּבֹא רְאֵה, בְּכָל יוֹם הַכָּרוֹז קוֹרֵא: כָּל בְּנֵי הָעוֹלָם, בָּכֶם עוֹמֵד הַדָּבָר הַזֶּה. וְזֶהוּ קְחוּ מֵאִתְּכֶם תְּרוּמָה לַה'. וְאִם תֹּאמְרוּ שֶׁהַדָּבָר קָשֶׁה עֲלֵיכֶם - כֹּל נְדִיב לִבּוֹ יְבִיאֶהָ."]]],[["מַהוּ יְבִיאֶהָ. אֶלָּא מֵהָכָא אוֹלִיפְנָא רָזָא לִצְלוֹתָא. דְּבַר נָשׁ דְּדָחִיל לְמָארֵיהּ וּמְכַוֵּין לִבֵּיהּ וּרְעוּתֵיהּ בִּצְלוֹתָא, אַתְקִין תִּקּוּנָא דִּלְעֵילָּא, כְּמָה דְּאוּקִימְנָא. בְּקַדְמִיתָא בְּשִׁירִין (קצ\"ז ע\"א) וְתוּשְׁבְּחָן, דְּקָאַמְרִין מַלְאֲכִין עִלָּאִין לְעֵילָּא. וּבְהַהוּא סִדּוּרָא דְּתוּשְׁבְּחָן דְּקָא אַמְרֵי יִשְׂרָאֵל לְתַתָּא, אִיהִי קְשִׁיטַת גַּרְמָהָא, וְאִתַתַּקָּנַת בְּתִקּוּנָהָא. כְּאִתְּתָא דְּאִתְקַשְׁטַת לְבַעְלָהּ.","וּבְסִדּוּרָא דִּצְלוֹתָא, בְּהַהוּא תִּקּוּנָא דִּצְלוֹתָא דִּמְיוּשָׁב, אַתְקִינוּ עוּלֶמְתָּהָא וְכָל אִינּוּן דִּילָהּ. וּמִתְקַשְּׁטָן כָּל אִינּוּן בַּהֲדָהּ, לְבָתַר דְּאִתְתָּקַּן כֹּלָּא וְאִתְסְדָּרוּ, כַּד מָטוּ לֶאֱמֶת וְיַצִּיב, כְּדֵין כֹּלָּא מְתְתַּקְנָא, אִיהִי וְעוּלֶמְתָּהָא, עַד דְּמָטוּ לְגָּאַל יִשְׂרָאֵל, כְּדֵין אִצְטְרִיךְ לְמֵיקָם כֹּלָּא עַל קִיוּמַיְיהוּ.","בְּגִין דְּכַד בַּר נָשׁ מָטֵי לֶאֱמֶת וְיַצִּיב, וְכֹלָּא אִתְתָּקַּן. עוּלֶמְתָּהָא נַטְלֵי לָהּ, וְאִיהִי נְטִילַת גַּרְמָהּ לְגַבֵּי מַלְכָּא עִלָּאָה. כֵּיוָן דְּמָטוּ לְגָּאַל יִשְׂרָאֵל, כְּדֵין מַלְכָּא קַדִּישָׁא עִלָּאָה נָטִיל בְּדַרְגּוֹי, וְנָפִיק לְקַבְּלָא לָהּ.","וַאֲנָן, מִקַּמֵּי מַלְכָּא עִלָּאָה בָּעִינָן לְקַיְּימָא עַל קִיוּמָנָא, בְּאֵימָתָא בִּרְעָדָה. דְּהָא כְּדֵין אוֹשִׁיט יְמִינֵיהּ לְגַבָּהּ, וּלְבָתַר שְׂמָאלֵיהּ, דְּשַׁוֵּי לָהּ תְּחוֹת רֵישֵׁהּ, וּלְבָתַר אִתְחַבְּקוּ תַּרְוַויְיהוּ כַּחֲדָא בִּנְשִׁיקוּ. וְאִלֵּין אִינּוּן תְּלַת קַדְמַיְתָא, וּבָעֵי בַּר נָשׁ לְשַׁוָּואָה לִבֵּיהּ וּרְעוּתֵיהּ, וּלְכַוְונָא בְּכָל הָנֵי תִּקּוּנִין וְסִדוּרִין דִּצְלוֹתָא. פּוּמֵיהּ וְלִבֵּיהּ וּרְעוּתֵיהּ כַּחֲדָא.","הַשְׁתָּא דְּמַלְכָּא עִלָּאָה וּמַטְרוֹנִיתָא אִינּוּן בְּחִבּוּרָא בְּחֶדְוָה בְּאִינּוּן נְשִׁיקִין. מַאן דְּאִצְטְרִיךְ לְמִשְׁאַל שְׁאֶלְתִּין, יִשְׁאַל. דְּהָא כְּדֵין שַׁעֲתָא דִּרְעוּתָא אִיהוּ. כֵּיוָן דְּשָׁאִיל בַּר נָשׁ שְׁאֶלְתּוֹי מִקַּמֵּי מַלְכָּא וּמַטְרוֹנִיתָא, כְּדֵין יַתְקִין גַּרְמֵיהּ בִּרְעוּתֵיהּ וְלִבֵּיהּ לִתְלָתָא אַחֲרָנִין, לְאַתְעֲרָא חֶדְוָה דִּטְמִירוּ, דְּהָא מֵאִלֵּין תְּלַת אִתְבָּרְכָא בִּדְבֵקוּתָא אַחֲרָא. וְיַתְקִין בַּר נָשׁ גַּרְמֵיהּ לְמֵיפַק מִקַּמַּיְיהוּ, וּלְאַנָּחָא לוֹן בְּחֶדְוָה גְּנִיזָא דְּאִלֵּין תְּלָת. וְעִם כָּל דָּא, דִּיהֵא רְעוּתֵיהּ, דְּיִתְבָּרְכוּן תַּתָּאֵי, מֵאִינּוּן בִּרְכָּאן דְּחֶדְוָה טְמִירָא.","וּכְדֵין אִצְטְרִיךְ לְמִנְפַּל עַל אַנְפּוֹי, וּלְמִמְסַר נַפְשֵׁיהּ, בְּשַׁעֲתָא דְּאִיהִי נַקְטָא נַפְשִׁין רוּחִין. כְּדֵין אִיהִי שַׁעֲתָא לְמִמְסָר נַפְשֵׁיהּ בְּגוֹ אִינּוּן נַפְשִׁין דְּאִיהִי נַקְטָא, דְּהָא כְּדֵין צְרוֹרָא דְּחַיֵּי אִיהוּ כְּדְקָא יֵאוֹת.","מִלָּה דָּא שְׁמַעְנָא בְּרָזִין דְּבוּצִינָא קַדִּישָׁא, וְלָא אִתְיְיהִיב לִי רְשׁוּ לְגַלָּאָה, בַּר לְכוּ חֲסִידֵי עֶלְיוֹנִין. דְּאִי בְּהַהִיא שַׁעֲתָא דְּאִיהִי נַקְטָא נַפְשִׁין וְרוּחִין בִּרְעוּ דִּדְבֵיקוּתָא חֲדָא, אִיהוּ יְשַׁוֵּי לִבֵּיהּ וּרְעוּתֵיהּ לְדָא, וְיָהִיב נַפְשֵׁיהּ בִּדְבֵקוּתָא, בְּהַהוּא רְעוּתָא, לְאַכְלְלָא לָהּ בְּהַהוּא דְּבֵקוּתָא. אִי אִתְקַבִּלַת בְּהַהִיא שַׁעֲתָא בְּהַהוּא רְעוּתָא, דְּאִינּוּן נַפְשִׁין רוּחִין וְנִשְׁמָתִין דְּאִיהִי נַקְטָא. הַאי אִיהוּ בַּר נָשׁ דְּאִתְצְרִיר בִּצְרוֹרָא דְּחַיֵּי בְּהַאי עָלְמָא, וּבְעָלְמָא דְּאָתֵי.","וְתוּ דְּבַעְיָא לְאִתְכַּלְּלָא מִכָּל סִטְרִין, מַלְכָּא וּמַטְרוֹנִיתָא, מִלְעֵילָּא (קפ\"ט ע\"א) וּמִתַּתָּא, וּלְאִתְעַטְּרָא בְּנִשְׁמָתִין בְּכָל סִטְרִין. אִתְעַטְּרַת בְּנִשְׁמָתִין מִלְעֵילָּא, וְאִתְעַטְּרַת בְּנִשְׁמָתִין מִתַּתָּא. וְאִי בַּר נָשׁ יְכַוֵּין לִבֵּיהּ וּרְעוּתֵיהּ לְכָל דָּא, וְיִמְסֹר נַפְשֵׁיהּ מִתַּתָּא בִּדְבֵקוּתָא בִּרְעוּתָא כְּמָה דְּאִתְּמַר. כְּדֵין קוּדְשָׁא בְּרִיךְ הוּא קָארֵי לֵיהּ שָׁלוֹם לְתַתָּא, כְּגַוְונָא דְּהַהוּא שָׁלוֹם דִּלְעֵילָּא. הַהוּא דְּבָרִיךְ לָהּ לְמַטְרוֹנִיתָא וְאַכְלִיל לָהּ וְאַעְטַר לָהּ בְּכָל עִטְרִין.","אוּף הָכִי, הַאי בַּר נָשׁ קוּדְשָׁא בְּרִיךְ הוּא קָרֵי לֵיהּ שָׁלוֹם לְתַתָּא, כְּמָה דְאַתְּ אָמֵר (שופטים ו׳:כ״ד) וַיִּקְרָא לוֹ יְיָ' שָׁלוֹם. וְכָל יוֹמוֹי הָכִי קָרָאן לֵיהּ לְעֵילָּא, שָׁלוֹם. בְּגִין דְּאַכְלִיל וְאַעְטַר לְמַטְרוֹנִיתָא לְתַתָּא, כְּגַוְונָא דְּהַהוּא שָׁלוֹם לְעֵילָּא.","וְכַד אִסְתַּלָּק הַהוּא בַּר נָשׁ מֵהַאי עָלְמָא, נִשְׁמָתֵיהּ סַלְּקָא וּבַקְעָא בְּכָל אִינּוּן רְקִיעִין, וְלֵית מַאן דְּיִמְחֵי בִּידָהּ. וְקוּדְשָׁא בְּרִיךְ הוּא קָרֵי לָהּ וְאָמַר (ישעיהו נ״ז:ב׳) יָבֹא שָׁלוֹם. וּשְׁכִינְתָּא אָמְרָה, יָנוּחוּ עַל מִשְׁכְּבוֹתָם וְגוֹ'. וְיִפְתְּחוּן לָהּ תְּלֵיסָר טוּרֵי דְּאֲפַרְסְמוֹנָא דַּכְיָא, וְלָא יְהֵא מַאן דְּיִמְחֵי בִּידָהּ. וְעַל דָּא, זַכָּאָה אִיהוּ מַאן דְּישַׁוֵּי לִבֵּיהּ וּרְעוּתֵיהּ לְדָא. וְעַל דָּא כְּתִיב, כֹּל נְדִיב לִבּוֹ יְבִיאֶהָ אֵת תְּרוּמַת יְיָ' לְגַבֵּי מַלְכָּא עִלָּאָה, כְּמָה דְּאִתְּמַר."],[[0,"מהו יביאה:","שואל מה הפירוש, יביאה. ומשיב, אלא מכאן למדנו הסוד לתפלה. כי אדם הירא מרבונו ומכוון לבו ורצונו בתפלה, הוא מתקן תקון העליון, כמו שהעמדנו. בתחלה בשירות ותשבחות שאומרים מלאכים העליונים למעלה, ובסדר ההוא של תשבחות שאומרים ישראל למטה, המלכות מקשטת עצמה, ומתתקנת בתקוניה, כאשה המתקשטת לבעלה."],[1,"ובסדורא דצלותא וכו':","ובסדר התפלה, בתקון ההוא של תפלה דמיושב, דהיינו מברכת יוצר אור ולמעלה, עד תפלת שמונה עשרה, שהיא בעמידה. התקינו כל אלו העלמות, דהיינו ז' הנערות של המלכות (כמ\"ש לעיל אות נ\"ג ע\"ש) וכל אלו שלה, וכל אלו מתקשטים עמה. לאחר שנתקן הכל ונסתדר, כשמגיעים לאמת ויציב, אז מתתקן הכל, הוא והעלמות שלה, עד שמגיעים לגאל ישראל. ואז צריכים הכל לעמוד על מעמדם."],[2,"בגין דכד בר וכו':","משום כשאדם מגיע לאמת ויציב, והכל כבר נתתקן, העלמות נושאות המלכות, והיא נושאת עצמה אל מלך העליון, שהוא ז\"א. כיון שמגיעים לגאל ישראל, אז מלך הקדוש העליון נוסע במדרגותיו, דהיינו בסדר ג' קוין, המאירים רק בסוד הנסיעה, (עי' בשלח ל\"ט ד\"ה וג'). ויוצא לקבל אותה, את המלכות."],[3,"ואנן מקמי מלכא וכו':","ואנו, מפני מלך העליון, צריכים לעמוד על מעמדינו באימה וברעדה, כי אז מושיט לה ימינו, שהוא בברכת מגן אברהם, שה\"ס קו ימין. ואח\"כ שמאלו שמשים תחת ראשה, בסו\"ה שמאלו תחת לראשי, שהוא בברכת אתה גבור, שהוא קו שמאל. ואח\"כ מתחבקים שניהם יחד בנשיקין, שהוא בברכת האל הקדוש, שהוא קו האמצעי, שמשם ומעלה ה\"ס נשיקין עד ג' אחרונות, ואלו הם שלש ברכות הראשונות של תפלת שמנה עשרה. וצריך האדם לשום לבו ורצונו, ולכוון בכל אלו התקונים והסדרים של התפלה, פיו ולבו ורצונו יחד."],[4,"השתא דמלכא עלאה וכו':","עתה שמלך העליון והמלכות הם בחבור בחדוה באלו הנשיקין, מי שצריך לשאול שאלות ובקשות ישאל כי אז הוא שעת רצון. כיון שבקש האדם בקשותיו מלפני המלך והמלכה, דהיינו בי\"ב ברכות האמצעיות, אז יתקין עצמו ברצונו ולבו לשלש ברכות האחרונות לעורר חדוה שבסתר, כי מאלו שלש ברכות, הוא מתברך בדבקות אחרת, שה\"ס הזווג, והאדם יתקן את עצמו לצאת מפניהם ולהניחם בחדוה מסותרת שבאלו שלש ברכות. כמ\"ש באורך (לעיל תרומה אות מ\"ה עש\"ה). ועכ\"ז צריך להיות רצונו שהתחתונים יתברכו מאלו הברכות של חדוה המסותרת."],[5,"וכדין אצטריך למנפל וכו':","ואז צריך לנפול על פניו, ולמסור את נפשו בשעה שהמלכות אוחזת הנפשות והרוחות, אז היא השעה למסור נפשו בתוך אלו הנפשות שאוחזת, כי אז צרור החיים, שהיא המלכות, הוא כראוי. וסוד נפילת אפים נתבאר לעיל (תרומה אות מ\"ה בהסולם ע\"ש)."],[6,"מלה דא שמענא וכו':","דבר זה שמעתי בין הסודות של מאור הקדוש, ולא ניתנה לי רשות לגלות, חוץ מכם חסידים העליונים, שאם בשעה ההיא שהמלכות אוחזת הנפשות והרוחות של בני האדם, ברצון אחד של הדביקות, משים האדם לבו ורצונו לזה, ונותן נפשו בדבקות ברצון ההוא, דהיינו לכלול נפשו באותה הדבקות, אם התקבלה מסירת נפשו, בשעה ההיא, ברצון הנפשות והרוחות והנשמות שאוחזת, זה הוא אדם שנצרר בצרור החיים, בעולם הזה, ובעולם הבא."],[7,"ותו דבעיא לאתכללא וכו':","ועוד שהמלך והמטרוניתא שהם תו\"מ, צריכים להכלל מכל הצדדים מלמעלה ומלמטה, ולהתעטר בנשמות בכל הצדדים, היא מתעטרת בנשמות מלמעלה ומתעטרת בנשמות מלמטה, דהיינו מאותם שמוסרים לה נשמתם, ואם האדם מכוון לבו ורצונו לכל זה, ומוסר לה נפשו מלמטה בדביקות וברצון, כמו שאמרנו, אז הקב\"ה קורא לו שלום למטה, כעין שלום ההיא של מעלה, שהוא יסוד הנקרא שלום, אותו השלום, המברך את המלכה, ומכליל אותה ומעטיר אותה מכל הצדדים."],[8,"אוף הכי האי וכו':","אף כך אדם הזה, הקב\"ה קורא לו שלום. כמש\"א, ויקרא לו ה' שלום. וכל ימיו קוראים אותו כך למעלה, שלום. משום שהכליל והעטיר את המלכה מלמטה, כעין שלום הזה שלמעלה שהוא יסוד. כנ\"ל בדבור הסמוך."],[9,"וכד אסתלק ההוא וכו':","וכשהאדם ההוא מסתלק מעולם הזה, נשמתו עולה ובוקעת בכל אלו הרקיעים ואין מי שיעכב בידה. והקב\"ה קוראה ואומר, יבא שלום. והשכינה אומרת, ינוחו על משכבותם וגו'. ויפתחו לה י\"ג הרים של אפרסמון הטהור. ולא יהיה מי שיעכב בידה. וע\"כ אשרי הוא, מי ששם לבו ורצונו לזה. וע\"כ כתוב, כל נדיב לבו יביאה את תרומת ה' אל מלך העליון, דהיינו, כמו שאמרתי."]],[[0,"","מַה זֶּה יְבִיאֶהָ? אֶלָּא מִכָּאן לָמַדְנוּ אֶת סוֹד הַתְּפִלָּה, שֶׁאָדָם שֶׁפּוֹחֵד מֵרִבּוֹנוֹ וּמְכַוֵּן לִבּוֹ וּרְצוֹנוֹ בַּתְּפִלָּה, מְתַקֵּן תִּקּוּן הָעֶלְיוֹן, כְּמוֹ שֶׁבֵּאַרְנוּ. בָּרִאשׁוֹנָה בְּשִׁירוֹת וְתִשְׁבָּחוֹת שֶׁאוֹמְרִים הַמַּלְאָכִים הָעֶלְיוֹנִים לְמַעְלָה. וּבְאוֹתָהּ עֲרִיכַת הַתִּשְׁבָּחוֹת שֶׁאוֹמְרִים יִשְׂרָאֵל לְמַטָּה, הִיא מְקַשֶּׁטֶת אֶת עַצְמָהּ וּמִתְתַּקֶּנֶת בְּתִקּוּנֶיהָ כְּמוֹ אִשָּׁה שֶׁמִּתְקַשֶּׁטֶת לְבַעְלָהּ."],[1,"","וּבְסִדּוּר הַתְּפִלָּה, בְּאוֹתוֹ הַתִּקּוּן שֶׁל תְּפִלַּת מְיֻשָּׁב, מַתְקִינִים אֶת עַלְמוֹתֶיהָ וְכָל אֵלּוּ שֶׁלָּהּ. וּמִתְקַשְּׁטוֹת כָּל עַלְמוֹתֶיהָ, וְאַחַר כָּךְ הַכֹּל מְתֻקָּנִים וּמְסֻדָּרִים. וּכְשֶׁמַּגִּיעִים לֶאֱמֶת וְיַצִּיב, אָז הַכֹּל מְתֻקָּנִים, הִיא וְעַלְמוֹתֶיהָ, עַד שֶׁמַּגִּיעִים לְגָאַל יִשְׂרָאֵל, וְאָז צָרִיךְ לַעֲמֹד הַכֹּל עַל מְקוֹמָם."],[2,"","מִשּׁוּם שֶׁכַּאֲשֶׁר מַגִּיעַ אָדָם לֶאֱמֶת וְיַצִּיב וְהַכֹּל מְתֻקָּן, עַלְמוֹתֶיהָ נוֹטְלוֹת אוֹתָהּ, וְהִיא נוֹטֶלֶת אֶת עַצְמָהּ לַמֶּלֶךְ הָעֶלְיוֹן. כֵּיוָן שֶׁמַּגִּיעִים לְגָאַל יִשְׂרָאֵל, אֲזַי הַמֶּלֶךְ הַקָּדוֹשׁ הָעֶלְיוֹן נוֹסֵעַ בְּדַרְגוֹתָיו וְיוֹצֵא לְקַבֵּל אוֹתָהּ."],[3,"","וְאָנוּ מִלִּפְנֵי הַמֶּלֶךְ הָעֶלְיוֹן צְרִיכִים לַעֲמֹד עַל מְקוֹמֵנוּ בְּאֵימָה בִּרְעָדָה, שֶׁהֲרֵי אָז הוּא מוֹשִׁיט יְמִינוֹ אֵלֶיהָ, וְאַחַר כָּךְ אֶת שְׂמֹאלוֹ שֶׁשָּׂם לָהּ תַּחַת רֹאשָׁהּ, וְאַחַר כָּךְ מִתְחַבְּקִים שְׁנֵיהֶם כְּאֶחָד בִּנְשִׁיקָה. וְאֵלֶּה הֵן הַשָּׁלֹשׁ הָרִאשׁוֹנוֹת, וְצָרִיךְ אָדָם לָשִׂים לִבּוֹ וּרְצוֹנוֹ וּלְכַוֵּן בְּכָל הַתִּקּוּנִים וְהַסִּדּוּרִים הַלָּלוּ שֶׁל הַתְּפִלָּה, פִּיו וְלִבּוֹ וּרְצוֹנוֹ כְּאֶחָד."],[4,"","עַכְשָׁו שֶׁהַמֶּלֶךְ הָעֶלְיוֹן וְהַגְּבִירָה הֵם בְּחִבּוּר אֶחָד בְּשִׂמְחָה בְּאוֹתָן נְשִׁיקוֹת - מִי שֶׁצָּרִיךְ לְבַקֵּשׁ בַּקָּשׁוֹת, יְבַקֵּשׁ, שֶׁהֲרֵי אָז שְׁעַת רָצוֹן הִיא. כֵּיוָן שֶׁשּׁוֹאֵל אָדָם שְׁאֵלוֹתָיו מִלִּפְנֵי הַמֶּלֶךְ וְהַגְּבִירָה, אָז יַתְקִין עַצְמוֹ בִּרְצוֹנוֹ וְלִבּוֹ לְשָׁלֹשׁ אֲחֵרוֹת לְעוֹרֵר שִׂמְחָה שֶׁבַּסֵּתֶר, שֶׁהֲרֵי מֵאֵלּוּ הַשָּׁלֹשׁ הוּא מִתְבָּרֵךְ בִּדְבֵקוּת אַחֶרֶת. וְיַתְקִין אָדָם אֶת עַצְמוֹ לָצֵאת מִפְּנֵיהֶם, וּלְהַנִּיחָם בְּשִׂמְחָה גְּנוּזָה שֶׁל אֵלּוּ הַשָּׁלֹשׁ. וְעִם כָּל זֶה, שֶׁיִּהְיֶה רְצוֹנוֹ שֶׁיִּתְבָּרְכוּ הַתַּחְתּוֹנִים מֵאוֹתָן בְּרָכוֹת שֶׁל שִׂמְחָה נִסְתֶּרֶת."],[5,"","וְאָז צָרִיךְ לִפֹּל עַל פָּנָיו וְלִמְסֹר אֶת נַפְשׁוֹ בְּשָׁעָה שֶׁהִיא לוֹקַחַת אֶת הַנְּפָשׁוֹת וְהָרוּחוֹת. אָז זוֹ הַשָּׁעָה לִמְסֹר נַפְשׁוֹ בְּתוֹךְ אוֹתָן נְפָשׁוֹת שֶׁהִיא לוֹקַחַת, שֶׁהֲרֵי אָז צְרוֹר הַחַיִּים הוּא כָּרָאוּי."],[6,"","דָּבָר זֶה שָׁמַעְתִּי בַּסּוֹדוֹת שֶׁל הַמְּנוֹרָה הַקְּדוֹשָׁה, וְלֹא נִתְּנָה לִי רְשׁוּת לְגַלּוֹת, פְּרָט לָכֶם חֲסִידִים עֶלְיוֹנִים. שֶׁאִם בְּאוֹתָהּ שָׁעָה שֶׁהִיא לוֹקַחַת נְפָשׁוֹת וְרוּחוֹת בְּרָצוֹן שֶׁל דְּבֵקוּת אַחַת, הוּא יָשִׂים לִבּוֹ וּרְצוֹנוֹ לָזֶה, וְנוֹתֵן נַפְשׁוֹ בִּדְבֵקוּת בְּאוֹתוֹ הָרָצוֹן לְהַכְלִילָהּ בְּאוֹתָהּ הַדְּבֵקוּת. אִם מִתְקַבֶּלֶת בְּאוֹתָהּ שָׁעָה בְּאוֹתוֹ הָרָצוֹן שֶׁל אוֹתָן נְפָשׁוֹת רוּחוֹת וּנְשָׁמוֹת שֶׁהִיא לוֹקַחַת, זֶהוּ אָדָם שֶׁנִּצְרָר בִּצְרוֹר הַחַיִּים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא."],[7,"","וְעוֹד, שֶׁצָּרִיךְ לְהִכָּלֵל מִכָּל הַצְּדָדִים, הַמֶּלֶךְ וְהַגְּבִירָה, מִלְמַעְלָה וּמִלְּמַטָּה, וּלְהִתְעַטֵּר בַּנְּשָׁמוֹת בְּכָל הַצְּדָדִים. מִתְעַטֶּרֶת בַּנְּשָׁמוֹת מִלְמַעְלָה, וּמִתְעַטֶּרֶת בַּנְּשָׁמוֹת מִלְּמַטָּה. וְאִם אָדָם יְכַוֵּן לִבּוֹ וּרְצוֹנוֹ לְכָל זֶה וְיִמְסֹר נַפְשׁוֹ מִלְּמַטָּה בִּדְבֵקוּת וּבְרָצוֹן כְּמוֹ שֶׁנֶּאֱמַר, אֲזַי הַקָּדוֹשׁ בָּרוּךְ הוּא קוֹרֵא לוֹ שָׁלוֹם לְמַטָּה, כְּמוֹ שֶׁאוֹתוֹ הַשָּׁלוֹם שֶׁלְּמַעְלָה, לְאוֹתוֹ שֶׁמְּבָרֵךְ אֶת הַגְּבִירָה וּמַכְלִיל אוֹתָהּ וּמְעַטֵּר אוֹתָהּ בְּכָל הָעֲטָרוֹת."],[8,"","אַף כָּךְ, לָאִישׁ הַזֶּה הַקָּדוֹשׁ בָּרוּךְ הוּא קוֹרֵא לוֹ שָׁלוֹם לְמַטָּה, כְּמוֹ שֶׁנֶּאֱמַר (שופטים ו) וַיִּקְרָא לוֹ ה' שָׁלוֹם. וְכָל יָמָיו כָּךְ קוֹרְאִים לוֹ לְמַעְלָה - שָׁלוֹם, מִשּׁוּם שֶׁהִכְלִיל וְעִטֵּר אֶת הַגְּבִירָה לְמַטָּה כְּמוֹ שֶׁאוֹתוֹ שָׁלוֹם לְמַעְלָה."],[9,"","וְכַאֲשֶׁר אוֹתוֹ הָאָדָם מִסְתַּלֵּק מִן הָעוֹלָם הַזֶּה, נִשְׁמָתוֹ עוֹלָה וּבוֹקַעַת אֶת כָּל אוֹתָם הָרְקִיעִים וְאֵין מוֹחֶה בְּיָדָהּ. וְהַקָּדוֹשׁ בָּרוּךְ הוּא קוֹרֵא לָהּ וְאוֹמֵר, (ישעיה נז) יָבוֹא שָׁלוֹם. וְהַשְּׁכִינָה אוֹמֶרֶת, יָנוּחוּ עַל מִשְׁכְּבוֹתָם וְגוֹ'. וְיִפְתְּחוּ לָהּ שְׁלֹשָׁה עָשָׂר נַהֲרוֹת אֲפַרְסְמוֹן טָהוֹר, וְלֹא יִהְיֶה מִי שֶׁיִּמְחֶה בְיָדָהּ. וְעַל כָּךְ, אַשְׁרֵי מִי שֶׁיָּשִׂים לִבּוֹ וּרְצוֹנוֹ לָזֶה, וְעַל זֶה כָּתוּב, כֹּל נְדִיב לִבּוֹ יְבִיאֶהָ אֵת תְּרוּמַת ה' לַמֶּלֶךְ הָעֶלְיוֹן, כְּמוֹ שֶׁנִּתְבָּאֵר."]]],[["אָרִים רִבִּי אַבָּא קָלֵיהּ, וְאָמַר, וַוי רִבִּי שִׁמְעוֹן, אַנְתְּ בַּחַיִּין, וַאֲנָא בָּכֵינָא עֲלָךְ. לָא עֲלָךְ בָּכֵינָא, אֶלָּא בָּכֵינָא עַל חַבְרַיָּיא, וּבָכֵינָא עַל עָלְמָא. רִבִּי שִׁמְעוֹן כְּבוּצִינָא דִּשְׁרָגָּא, דְּאַדְלִיק לְעֵילָּא וְאַדְלִיק לְתַתָּא. וּבִנְהוֹרָא דְּאַדְלִיק לְתַתָּא, נְהִירִין כָּל בְּנֵי עָלְמָא, (נ\"א נהיר לעילא) וַוי לְעָלְמָא, כַּד יִסְתָּלַק נְהוֹרָא דִּלְתַתָּא בִּנְהוֹרָא דִּלְעֵילָּא. מַאן יַנְהִיר נְהוֹרָא דְּאוֹרַיְיתָא לְעָלְמָא. קָם רִבִּי אַבָּא וְנָשִׁיק לְרִבִּי חִיָּיא. אֲמַר לֵיהּ מִלִּין אִלֵּין הֲווֹ תְּחוֹת יְדָךְ, וְעַל דָּא קוּדְשָׁא בְּרִיךְ הוּא שָׁדַרְנִי עַד הָכָא, לְאִתְחַבְּרָא עִמְּכוֹן זַכָּאָה חוּלָקִי.","רִבִּי יוֹסֵי פָּתַח קְרָא אֲבַתְרִיהּ וְאָמַר, (שמות ל״ה:י׳) וְכָל חֲכַם לֵב בָּכֶם יָבֹאוּ וְיַּעֲשׂוּ וְגוֹ', הַאי קְרָא אוּקְמוּהָ. אֲבָל תָּא חֲזֵי, בְּשַׁעֲתָא דְּאָמַר קוּדְשָׁא בְּרִיךְ הוּא לְמֹשֶׁה, (דברים א׳:י״ג) הָבוּ לָכֶם אֲנָשִׁים חֲכָמִים וּנְבוֹנִים, אַשְׁגַּח בְּכָל יִשְׂרָאֵל, וְלָא אַשְׁכַּח נְבוֹנִים, הֲדָא הוּא דִּכְתִּיב, וָאֶקַּח אֶת רָאשֵׁי שִׁבְטֵיכֶם אֲנָשִׁים חֲכָמִים וִידוּעִים, וְאִלּוּ נְבוֹנִים לָא כְּתִיב. וְאִי תֵּימָא דְּנָבוֹן אִיהוּ דַּרְגָּא עִלָּאָה מֵחָכָם, הָכִי אִיהוּ וַדַּאי.","מַה בֵּין הַאי לְהַאי. חָכָם, הָא אוּקְמוּהָ, דְּאֲפִילּוּ תַּלְמִיד הַמַּחְכִּים לְרַבֵּיהּ אִקְרֵי חָכָם. חָכָם, דְּיָדַע לְגַרְמֵיהּ כָּל מַה דְּאִצְטְרִיךְ. נָבוֹן כַּמָה דַּרְגִּין אִית בֵּיהּ, דְּאִסְתָּכַּל בְּכֹלָּא, וְיָדַע בְּדִילֵיהּ וּבְאַחֲרָנִין. וְסִימָנִךְ, (משלי י״ב:י׳) יוֹדֵעַ צַדִּיק נֶפֶשׁ בְּהֶמְתּוֹ. (שמואל ב כ״ג:ג׳) צַדִּיק מוֹשֵׁל יִרְאַת אֱלֹהִים. וְהָכָא חֲכַם לֵב דַּיְיקָא. בַּלֵּב חָכָם, וְלָא בְּאַתְרָא אַחֲרָא, בְּגִין דְּקַיְּימָא בַּלֵּב, וְנָבוֹן לְעֵילָּא וְתַתָּא, אִסְתָּכַּל בְּדִילֵיהּ וּבְאַחֲרָנִין.","פָּתַח וְאָמַר, (ישעיהו מ״ט:ג׳) וַיֹּאמֶר לִי עַבְדִּי אַתָּה וְגוֹ', הָכָא בִּצְלוֹתָא דְּבָעֵי בַּר נָשׁ לְצַלָּאָה קַמֵּיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, דְּאִיהִי פּוּלְחָנָא חֲדָא רַבָּא וְיַקִּירָא, מֵאִינּוּן פּוּלְחָנִין דְּמָארֵיהּ. תָּא חֲזֵי, אִית פּוּלְחָנָא דְּקוּדְשָׁא בְּרִיךְ הוּא, דְּקַיְּימָא בְּעוֹבָדָא, דְּאִיהוּ פּוּלְחָנָא דְּקַיְּימָא בְּעוֹבָדָא דְּגוּפָא, וְאִיהוּ פּוּלְחָנָא. וְאִית פּוּלְחָנָא דְּקוּדְשָׁא בְּרִיךְ הוּא, דְּאִיהוּ פּוּלְחָנָא פְּנִימָאָה יַתִּיר, דְּאִיהוּ עִקָרָא דְּכֹלָּא, קַיְּימָא בְּהַהוּא פּוּלְחָנָא פְּנִימָאָה, דְּאִיהוּ עִקָּרָא דְּכֹלָּא.","בְּגוּפָא אִית (בראשית ט\"ז ע\"א) תְּרֵיסָר שַׁיְיפִין, דְּקַיְימִין בְּעוֹבָדָא דְּגוּפָא, כְּמָה דְּאוֹקִימְנָא. וְאִינּוּן שַׁיְיפִין דְּגוּפָא, וּפוּלְחָנָא דְּקוּדְשָׁא בְּרִיךְ הוּא, דְּעוֹבָדָא קַיְּימָא בְּהוּ. בְּגִין דְּפוּלְחָנָא דְּקוּדְשָׁא בְּרִיךְ הוּא, בִּתְרֵין סִטְרִין, שַׁיְיפִין דְּגוּפָא לְבַר, וְאִית תְּרֵיסָר שַׁיְיפִין אַחֲרָנִין, פְּנִימָאִין לְגוֹ מִן גּוּפָא. וְאִינּוּן תִּקּוּנִין פְּנִימָאִין לְגוֹ מִן גּוּפָא, לְאִתְתַּקְנָא בְּהוּ תִּקּוּנָא דְּרוּחָא, דְּאִיהוּ פּוּלְחָנָא יַקִּירָא פְּנִימָאָה דְּקוּדְשָׁא בְּרִיךְ הוּא, כְּמָה דְּאוֹקִימְנָא גּוֹ רָזִין פְּנִימָאִין דְּקָאָמַר רַבִּי שִׁמְעוֹן, וְאִינּוּן רָזָא דְּחָכְמְתָא עִלָּאָה, וְאִתְיְדִיעוּ בֵּינֵי חַבְרַיָּא, זַכָּאָה חוּלָקֵיהוֹן.","צְלוֹתָא דְּבַר נָשׁ, אִיהוּ פּוּלְחָנָא דְּרוּחָא, וְאִיהוּ קַיְּימָא בְּרָזִין עִלָּאִין, וּבְנֵי נָשָׁא לָא יַדְעִין, דְּהָא צְלוֹתָא דְּבַר נָשׁ בַּקְעָת אֲוִירִין, בַּקְעָת רְקִיעִין, פַּתְחָת פִּתְחִין, וְסַלְּקָא לְעֵילָּא.","בְּשַׁעֲתָא דְּנָהִיר נְהוֹרָא, וְאִתְפְּרָשׁ נְהוֹרָא מִן חֲשׁוֹכָא, כְּדֵין כָּרוֹזָא אָזְלָא בְּכֻלְּהוּ רְקִיעִין, אִתְתָּקָנוּ מָארֵי דְּפִתְחִין, מָארֵיהוֹן דְּהֵיכָלִין, כָּל חַד וְחַד עַל מַטְרֵיהּ. בְּגִין דְּאִינּוּן דְּשֻׁלְטָנִיהוֹן בִּימָמָא, לָאו אִינּוּן דְּשֻׁלְטָנֵיהוֹן בְּלֵילְיָא. וְכַד עָאל לֵילְיָא, אִתְעַבְרוּ שׁוּלְטָנִין דִּימָמָא, וְאִתְמְנוּן שֻׁלְטָנִין אַחֲרָנִין, דְּשָׁלִיטִין בְּלֵילְיָא, וְאִתְחַלְּפָן אִלֵּין בְּאִלֵּין.","וְרָזָא דָּא, (בראשית א׳:ט״ז) אֶת הַמָּאוֹר הַגָּדוֹל לְמֶמְשֶׁלֶת הַיּוֹם וְגוֹ'. וּמֶמְשֶׁלֶת הַיּוֹם וּמֶמְשֶׁלֶת הַלַּיְלָה, שׁוּלְטָנִין אִינּוּן דִּי מְמָנָן בִּימָמָא, וְשׁוּלְטָנִין אִינּוּן דִּי מְמָנָן בְּלֵילְיָא. וְאִלֵּין אִקְרוּן מֶמְשֶׁלֶת הַיּוֹם. וְאִלֵּין אִקְרוּן מֶמְשֶׁלֶת הַלַּיְלָה."],[[0,"ארים ר' אבא וכו':","הרים ר\"א קולו ואמר, אוי ר' שמעון, אתה בחיים, ואני כבר בוכה עליך. לא עליך אני בוכה, אלא אני בוכה על החברים, ואני בוכה על העולם. שישארו יתומים ממך אחר פטירתך מן העולם. ר' שמעון הוא כאור הנר הדולק למעלה ודולק למטה. ובאור שהדליק למטה מאירים כל בני העולם. אוי לעולם כשיסתלק האור שלמטה ויבא בתוך האור של מעלה. מי יאיר אור התורה לעולם. קם ר' אבא ונשק לר' חייא. אמר לו דברים אלו היו תחת ידך, ע\"כ, שלחני ה' עד כאן להתחבר עמך, אשרי חלקי."],[1,"ר' יוסי פתח וכו':","ר\"י פתח מקרא אחריו, ואמר, וכל חכם לב בכם יבאו ויעשו וגו'. מקרא זה העמידוהו, אבל בוא וראה, בשעה שהקב\"ה אמר למשה, הבו לכם אנשים חכמים ונבונים, הסתכל בכל ישראל ולא מצא נבונים. ז\"ש, ואקח את ראשי שבטיכם אנשים חכמים וידועים, ואלו נבונים לא כתוב, ואם תאמר שנבון הוא מדרגה עליונה מחכם, כי ע\"כ לא מצא נבונים. כך הוא ודאי. שנבון חשוב מחכם."],[2,"מה בין האי וכו':","שואל, מה ההבדל בין זה לזה. בין חכם לנבון. ומשיב, חכם, הרי העמדנו, שאפילו תלמיד המחכים לרבו נקרא חכם. \u0003חכם,\u0004 היינו היודע בשל עצמו כל מה שצריך. \u0003נבון,\u0004 כמה מדרגות יש בו, כי מסתכל בכל דבר, ויודע בעצמו ובאחרים. וסימנך, יודע צדיק נפש בהמתו, שהצדיק שהוא יסוד משפיע אל המלכות שה\"ס הויה דב\"ן, שבהמה היא בגימטריא ב\"ן. וכן צדיק מושל יראת אלקים. שהצדיק, שהוא יסוד מושל ומשפיע אל המלכות הנקראת יראת אלקים. וכאן, \u0003חכם\u0004 לב בדיוק, דהיינו שחכם הנאמר כאן, הוא מבחינת המלכות שנקראת חכם לב. חכם בלב, שהוא מלכות, ולא במקום אחר. משום שהחכמה נמצאת בלב, שהוא מלכות ולא במקום אחר. ו \u0003נבון\u0004 הוא למעלה ולמטה, הוא מסתכל בשל עצמו ובאחרים."],[2,"","פירוש. חכם, ה\"ס מלכות שממנה מתגלה החכמה. ונבון ה\"ס יסוד צדיק. וז\"ש (באות קיט) \u0003דנבון איהו דרגא עלאה מחכם.\u0004 כי חכם הוא מלכות ונבון שהוא יסוד גבוה ממנה. ונודע שהחכמה שבמלכות מאירה רק ממטה למעלה. וז\"ש, \u0003חכם דידע לגרמיה כל מה דאצטריך,\u0004 דהיינו שמאירה בו ממטה למעלה, ויודע רק לעצמו, ואינו יכול להשפיע למטה דהיינו לאחרים. וז\"ש, \u0003בלב חכם ולא באתרא אחרא,\u0004 כי הלב, שהוא המלכות, מקבלת ממטה למעלה, ולא ממעלה למטה, שהוא מקום אחר. וז\"ש, \u0003ונבון, לעילא ותתא,\u0004 כי היסוד שהוא נבון, משפיע החסדים ממעלה למטה, \u0003אסתכל בדיליה ואחרנין,\u0004 שמקבל לעצמו ומשפיע למטה לאחרים. דהיינו למלכות בסו\"ה, יודע צדיק נפש בהמתו. צדיק מושל יראת אלקים."],[3,"פתח ואמר ויאמר וכו':","פו\"א, ויאמר לי עבדי אתה וגו'. המדובר הוא כאן, בתפלה שהאדם צריך להתפלל לפני הקב\"ה, שהיא עבודה אחת גדולה ויקרה מעבודות אדונו. בוא וראה, יש עבודת הקב\"ה העומדת במעשה, שהיא עבודה העומדת במעשה הגוף, דהיינו המצות התלויות במעשה. והיא עבודה. ויש עבודת הקב\"ה, שהיא עבודה פנימית יותר, שהיא עיקר הכל, והיא עומדת בעבודה הפנימית ההיא שהיא עיקר הכל. דהיינו מצות התלויות בדבור וברצון הלב."],[4,"בגופא אית תריסר","וכו': בגוף יש שנים עשר אברים העומדים במעשה הגוף, כמו שהעמדנו, שהם ב' ידים וב' רגלים שבכל אחת מהן ג' פרקים, וד\"פ ג' הם י\"ב. ואלו הם אברי הגוף ועבודת הקב\"ה, שמצות התלויות במעשה עומדת בהם. משום שעבודת הקב\"ה הוא בב' בחינות, א', באברי הגוף שמבחוץ, שהם י\"ב אברים שבירים ורגלים. ב' ויש שנים עשר אברים אחרים פנימים שהם בפנימיות הגוף, דהיינו, מוח, לב, כבד, פה, לשון, חמש כנפי ריאה, ושתי כליות. והם תקונים פנימים לפנים מן הגוף. להתקין בהם תקון הרוח, שהוא עבודה פנימית היקרה של הקב\"ה, דהיינו מצוות התלויות בדבור, כגון תפלה וברכות והודאות. כמו שהעמדנו תוך סודות הפנימים שאמר ר' שמעון, והוא סוד החכמה העליונה, ונודעים בין החברים, אשרי חלקם."],[5,"צלותא דבר נש","וכו': תפלתו של אדם הוא עבודת הרוח, שהוא עבודה מבחינה ב' הנ\"ל התלויה בדבור. והיא עומדת בסודות עליונים, ובני אדם אינם יודעים שתפלתו של אדם בוקעת אוירים ובוקעת רקיעים, פותחת פתחים ועולה למעלה."],[6,"בשעתא דנהיר נהורא","וכו': בשעה שמאיר האור, של הבוקר, והאור נפרד מן החשך, אז הולך כרוז בכל הרקיעים: התתקנו שליטי הפתחים, שליטי ההיכלות כל אחד ואחד על משמרתו, משום שאלו השולטים ביום אינם אלו השולטים בלילה. וכשבא הלילה נעברו שליטים של יום ומתמנים שליטים אחרים השולטים בלילה, ונחלפים אלו באלו."],[7,"ורזא דא את וכו':","וזה סוד, את המאור הגדול לממשלת היום וגו'. וממשלת היום וממשלת הלילה, פירושו, שליטים שהם ממונים ביום ושליטים שהם ממונים בלילה. אלו נקראים ממשלת היום, ואלו נקראים ממשלת הלילה."]],[[0,"","הֵרִים רַבִּי אַבָּא אֶת קוֹלוֹ וְאָמַר, אוֹי, רַבִּי שִׁמְעוֹן, אַתָּה בַּחַיִּים, וַאֲנִי בּוֹכֶה עָלֶיךְ. לֹא עָלֶיךְ אֲנִי בּוֹכֶה, אֶלָּא אֲנִי בּוֹכֶה עַל הַחֲבֵרִים וּבוֹכֶה עַל הָעוֹלָם. רַבִּי שִׁמְעוֹן הוּא כְּמוֹ מְנוֹרָה שֶׁל נֵר שֶׁדּוֹלֵק לְמַעְלָה וְדוֹלֵק לְמַטָּה, וּבָאוֹר שֶׁדּוֹלֵק לְמַטָּה מְאִירִים לְכָל הָעוֹלָם. (מאיר למעלה) אוֹי לָעוֹלָם כְּשֶׁיִּסְתַּלֵּק הָאוֹר שֶׁלְּמַטָּה לָאוֹר שֶׁלְּמַעְלָה, מִי יָאִיר לָנוּ אֶת אוֹר הַתּוֹרָה לָעוֹלָם? קָם רַבִּי אַבָּא וְנָשַׁק אֶת רַבִּי חִיָּיא. אָמַר לוֹ, הַדְּבָרִים הַלָּלוּ הָיוּ תַחַת יָדְךְ, וְעַל כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא שְׁלָחַנִי עַד לְכָאן לְהִתְחַבֵּר עִמָּכֶם. אַשְׁרֵי חֶלְקִי."],[1,"","רַבִּי יוֹסֵי פָּתַח פָּסוּק אַחֲרָיו וְאָמַר, וְכָל חֲכַם לֵב בָּכֶם יָבֹאוּ וְיַעֲשׂוּ וְגוֹ'. פָּסוּק זֶה פֵּרְשׁוּהוּ. אֲבָל בֹּא וּרְאֵה, בְּשָׁעָה שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה, (דברים א) הָבוּ לָכֶם אֲנָשִׁים חֲכָמִים וּנְבֹנִים, בָּחַן אֶת כָּל יִשְׂרָאֵל וְלֹא מָצָא נְבוֹנִים. זֶהוּ שֶׁכָּתוּב וָאֶקַּח אֶת רָאשֵׁי שִׁבְטֵיכֶם אֲנָשִׁים חֲכָמִים וִידֻעִים, וְאִלּוּ נְבוֹנִים לֹא כָתוּב. וְאִם תֹּאמַר שֶׁנָּבוֹן הִיא דַּרְגָּה יוֹתֵר עֶלְיוֹנָה מֵחָכָם - כָּךְ זֶה וַדַּאי!"],[2,"","מַה בֵּין זֶה לָזֶה? חָכָם, הֲרֵי פֵּרְשׁוּהָ, שֶׁאֲפִלּוּ תַּלְמִיד הַמַּחְכִּים אֶת רַבּוֹ נִקְרָא חָכָם. חָכָם, שֶׁיּוֹדֵעַ לְעַצְמוֹ כָּל מַה שֶּׁצָּרִיךְ. בְּנָבוֹן יֵשׁ כַּמָּה דְרָגוֹת - שֶׁמִּסְתַּכֵּל בַּכֹּל, וְיוֹדֵעַ בְּשֶׁלּוֹ וּבַאֲחֵרִים, וְסִימָנְךְ - (משלי יב) יוֹדֵעַ צַדִּיק נֶפֶשׁ בְּהֶמְתּוֹ. (שמואל ב כג) צַדִּיק מוֹשֵׁל יִרְאַת אֱלֹהִים. וְכָאן חֲכַם לֵב דַּוְקָא. בַּלֵּב חָכָם, וְלֹא בְמָקוֹם אַחֵר, מִשּׁוּם שֶׁעוֹמֵד בַּלֵּב, וְנָבוֹן לְמַעְלָה וּלְמַטָּה, מִסְתַּכֵּל בְּעַצְמוֹ וּבְשֶׁל אֲחֵ רִים."],[3,"","פָּתַח וְאָמַר, (ישעיה מט) וַיֹּאמֶר לִי עַבְדִּי אָתָּה וְגוֹ'. כָּאן בַּתְּפִלָּה שֶׁצָּרִיךְ אָדָם לְהִתְפַּלֵּל לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהִיא עֲבוֹדָה אַחַת גְּדוֹלָה וְנִכְבָּדָה מֵאוֹתָן הָעֲבוֹדוֹת שֶׁל רִבּוֹנוֹ. בֹּא וּרְאֵה, יֵשׁ עֲבוֹדָה שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁעוֹמֶדֶת בְּמַעֲשֶׂה, שֶׁהִיא עֲבוֹדָה שֶׁעוֹמֶדֶת בְּמַעֲשֵׂה הַגּוּף וְהִיא עֲבוֹדָה. וְיֵשׁ עֲבוֹדָה שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהִיא עֲבוֹדָה יוֹתֵר פְּנִימִית, שֶׁהִיא עִקַּר הַכֹּל, וְעוֹמֶדֶת בְּאוֹתָהּ עֲבוֹדָה פְּנִימִית שֶׁהִיא עִקַּר הַכֹּל."],[4,"","בַּגּוּף יֵשׁ שְׁנֵים עָשָׂר אֵיבָרִים שֶׁעוֹמְדִים בְּמַעֲשֵׂה הַגּוּף, כְּמוֹ שֶׁבֵּאַרְנוּ, וְאֵלּוּ הֵם אֶבְרֵי הַגּוּף וַעֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהַמַּעֲשֶׂה עוֹמֵד בָּהֶם. מִשּׁוּם שֶׁעֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא הִיא בִּשְׁנֵי צְדָדִים, בְּאֶבְרֵי הַגּוּף הַחִיצוֹנִיִּים, וְיֵשׁ שְׁנֵים עָשָׂר אֵיבָרִים אֲחֵרִים פְּנִימִיִּים לִפְנִים מֵהַגּוּף. וְהֵם תִּקּוּנִים פְּנִימִיִּים לִפְנִים מֵהַגּוּף לְתַקֵּן בָּהֶם הַתִּקּוּן שֶׁל הָרוּחַ, שֶׁהִיא עֲבוֹדָה נִכְבָּדָה פְּנִימִית שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁבֵּאַרְנוּ בְּתוֹךְ הַסּוֹדוֹת הַפְּנִימִיִּים שֶׁאָמַר רַבִּי שִׁמְעוֹן, וְהֵם סוֹד הַחָכְמָה הָעֶלְיוֹנָה, וְנוֹדְעוּ בֵּין הַחֲבֵרִים, אַשְׁרֵי חֶלְקָם."],[5,"","תְּפִלַּת הָאָדָם הִיא עֲבוֹדַת הָרוּחַ, וְהִיא עוֹמֶדֶת בְּסוֹדוֹת עֶלְיוֹנִים, וַאֲנָשִׁים לֹא יוֹדְעִים, שֶׁהֲרֵי תְּפִלַּת הָאָדָם בּוֹקַעַת אֲוִירִים וּבוֹקַעַת רְקִיעִים וּפוֹתַחַת פְּתָחִים וְעוֹלָה לְמַעְלָה."],[6,"","בְּשָׁעָה שֶׁמֵּאִיר הָאוֹר וְנִפְרָד הָאוֹר מִן הַחֲשֵׁכָה, אֲזַי הַכָּרוֹז הוֹלֵךְ בְּכָל הָרְקִיעִים: הִתְתַּקְּנוּ בַּעֲלֵי הַפְּתָחִים, בַּעֲלֵי הַהֵיכָלוֹת, כָּל אֶחָד וְאֶחָד עַל מִשְׁמַרְתּוֹ, מִשּׁוּם שֶׁאוֹתָם שֶׁשּׁוֹלְטִים בַּיּוֹם אֵינָם שׁוֹלְטִים בַּלַּיְלָה. וּכְשֶׁנִּכְנָס הַלַּיְלָה, מָעֳבָרִים שַׁלִּיטֵי הַיּוֹם, וּמִתְמַנִּים שַׁלִּיטִים אֲחֵרִים שֶׁשּׁוֹלְטִים בַּלַּיְלָה, וּמִתְחַלְּפִים אֵלֶּה בְּאֵלֶּה."],[7,"","וְסוֹד זֶה - (בראשית א) אֶת הַמָּאוֹר הַגָּדֹל לְמֶמְשֶׁלֶת הַיּוֹם וְגוֹ'. וּמֶמְשֶׁלֶת הַיּוֹם וּמֶמְשֶׁלֶת הַלַּיְלָה, יֵשׁ שַׁלִּיטִים שֶׁמְּמֻנִּים בַּיּוֹם, וְיֵשׁ שַׁלִּיטִים שֶׁמְּמֻנִּים בַּלַּיְלָה. וְאֵלּוּ נִקְרְאוּ מֶמְשֶׁלֶת הַיּוֹם, וְאֵלּוּ נִקְרָאִים מֶמְשֶׁלֶת הַלַּיְלָה."]]],[["כַּד עָאל לֵילְיָא, כָּרוֹזָא נָפְקָא, אִתְתָּקָנוּ שׁוּלְטָנִין דְּלֵילְיָא, כָּל חַד וְחַד לְאַתְרֵיהּ. וְכַד נָהִיר יְמָמָא, כָּרוֹזָא נָפְקָא, אִתְתָּקָנוּ שׁוּלְטָנִין דִּימָמָא, כָּל חַד וְחַד לְאַתְרֵיהּ. (כדין מתעברי שלטנין דליליא ואתפקדון שלטנין דיממא) וְכַד כָּרוֹזָא אַכְרִיז, כְּדֵין כֻּלְּהוּ כָּל חַד וְחַד, אִתְפְּקַּד עַל הַהוּא אֲתָר דְּאִתְחָזֵי לֵיהּ. כְּדֵין שְׁכִינְתָּא קַדְמָא, וְנַחְתָּא, וְיִשְׂרָאֵל עָאלִין לְבֵי כְּנִישְׁתָּא, לְשַׁבְּחָא לְמָארֵיהוֹן, פַּתְחִין בְּשִׁירִין וְתוּשְׁבְּחָן.","דְּבָעֵי לֵיהּ לְבַּר נָשׁ, (ויקרא ק\"כ ע\"ב) כֵּיוָן דְּאַתְקִין גַּרְמֵיהּ בְּפוּלְחָנָא דְּעוֹבָדָא, בְּתִקּוּנֵי דְּמִצְוָה וּקְדוּשָׁה, לְיַחֲדָא לִבֵּיהּ בְּתִקּוּנָא דְּפוּלְחָנָא פְּנִימָאָה דְּמָארֵיהּ, וּלְשַׁוָּאָה לִבֵּיהּ וּרְעוּתֵיהּ בְּהַהוּא פּוּלְחָנָא דְּאִינּוּן מִלִּין, (ד\"א דקאמר) דְּהָא מִלָּה סַלְּקָא.","וְאִינּוּן מְמָנָן דְּקַיְימִין בַּאֲוִירָא, אִתְמְנּוּן לְד' סִטְרֵי עָלְמָא. לִסְטַר מִזְרָח אִתְמַנָּא מְמָנָא חַד, דְּקַיְּימָא בַּאֲוִירָא לְהַהוּא סִטְרָא, גְּזַרְדִּיָ\"א שְׁמֵיהּ, וְעִמֵּיהּ סַרְכִין מְמָנָן אַחֲרָנִין, דְּאִינּוּן מְחַכָּאן לְהַהִיא מִלָּה דִּצְלוֹתָא, וְסַלְּקָא בַּאֲוִירָא בְּהַהוּא סִטְרָא, וְנָטִיל לָהּ הַאי מְמָנָא.","אִי הִיא מִלָּה כַּדְקָא יֵאוֹת, הוּא, וְכָל אִינּוּן סַרְכִין נַשְׁקִין לְהַהִיא מִלָּה, וְסַלְּקִין עִמָּהּ עַד הַהוּא אֲוִירָא דִּרְקִיעָא לְעֵילָּא, דְּתַמָּן מְמָנָן סַרְכִין אַחֲרָנִין. בְּשַׁעֲתָא דְּנַשְּׁקֵי לְהַהִיא מִלָּה, פַּתְחֵי וְאַמְרֵי, זַכָּאִין אַתּוּן יִשְׂרָאֵל, דְּיַדְעִיתּוּ לְאַעְטְרָא לְמָארֵיכוֹן בְּעִטְרִין קַדִּישִׁין זַכָּאָה אִיהוּ פּוּמָא, דְּמִלָּה דְּעַטְרָא דָּא נָפְקָא מִנֵּיהּ.","כְּדֵין פַּרְחִין אַתְוָון דְּקַיְימִין בַּאֲוִירָא, דְּבִשְׁמָא קַדִּישָׁא דִּתְרֵיסָר אַתְוָון, דְּהַהוּא שְׁמָא שַׁלִּיט בַּאֲוִירָא, וְהַאי אִיהוּ (בראשית ט\"ז ע\"א) שְׁמָא, דְּהֲוָה טָאס בֵּיהּ אֵלִיָּה\"וּ, עַד דְּאִסְתַּלָּק לִשְׁמַיָּא. וְהַיְינוּ דְּקָאמַר עוֹבַדְיָה לְאֵלִיָּהוּ, (מלכים א יח) וְרוּחַ יְיָ' יִשָּׂאֲךָ. בְּגִין דְּבִשְׁמָא דָּא, הֲוָה אֵלִיָּהוּ טָאס בֵּיהּ בַּאֲוִירָא, וְהַאי אִיהוּ שְׁמָא דְּשַׁלִּיט בַּאֲוִירָא.","וְאִינּוּן אַתְוָון פַּרְחִין וְסַלְּקִין בְּהַהִיא מִלָּה, וְהַהוּא מְמָנָא דְּמַפְתְּחָן דְּאַוִּירָא בִּידֵיהּ, וְכָל אִינּוּן מְמָנָן אַחֲרָנִין, כֻּלְּהוּ סַלְּקִין בֵּיהּ עַד רְקִיעָא, וְאִתְמְסָר בִּידָא דִּמְמָנָא אַחֲרָא, לְסַלְּקָא לְעֵילָּא.","לִסְטַר דָּרוֹם, אִית מְמָנָא אַחֲרָא דְּשַׁלְטָא בַּאֲוִירָא לְהַהוּא סְטָר, וְכַמָּה מְמָנָן אַחֲרָנִין וְסַרְכִין עִמֵּיהּ. פְּסַגְנִיָ\"ה שְׁמֵיהּ, וּבֵיהּ מִתְאַחֲדָן (נ\"א וליה אתמסראן) מַפְתְּחָן דְּאַוִּירָא לְהַהוּא סְטָר. וְכָל אִינּוּן מָארֵי דְּעָקוּ, דְּצַלָּאן צְלוֹתָא לְמָארֵיהוֹן מִגּוֹ עַקְתָּא, מִגּוֹ תְּבִירוּ דְּלִבָּא, אִי הַהִיא מִלָּה כְּדְקָא יֵאוֹת, סָלְקָא לַאֲוִירָא בְּהַהוּא סִטְרָא, וְנָטִיל לָהּ הַאי מְמָנָא, וְנָשִׁיק לָהּ (ס\"א בגין דסלקא בההוא סטרא) כַּד נָשִּׁיק לָהּ, פָּתַח וְאָמַר, קוּדְשָׁא בְּרִיךְ הוּא יָחוֹס לְקָבְלָךְ (נ\"א ועלך') וּבְגִינָךְ יִתְמְלֵי רַחֲמִין.","סַלְּקִין עִמָּהּ כָּל אִינּוּן מְמָנָן קַדִּישִׁין, וְכָל אִינּוּן סַרְכִין דְּהַהוּא סִטְרָא. וּפַרְחִין אַתְוָון דִּשְׁמָא קַדִּישָׁא, דְּאִינּוּן ד' אַתְוָון, דְּמִתְעַטְּרִין וְשַׁלְטִין בְּהַהוּא סִטְרָא דַּאֲוִירָא, וְסַלְּקִין בְּהַהוּא סִטְרָא דַּאֲוִירָא, עַד רְקִיעָא, עַד הַהוּא מְמָנָא דִּרְקִיעָא דְּשַׁלִּיט בְּהַהוּא סִטְרָא.","לִסְטַר צָפוֹן, אִית מְמָנָא אַחֲרָא, וְעִמֵּיהּ כַּמָה סַרְכִין מְמָנָן דְּשַׁלְטִין בַּאֲוִירָא, וְהַהוּא מְמָנָא פְּתַחְיָ\"ה שְׁמֵיהּ, וְהַאי אִתְמַנָּא בַּאֲוִירָא לְהַהוּא סִטְרָא, וְכָל אִינּוּן דִּמְצַלָּאן צְלוֹתִין עַל בַּעֲלֵי דְּבָבוּ דְּעָקִין לוֹן, וְכַד מִלָּה דְּהַהִיא צְלוֹתָא סַלְּקָא לַאֲוִירָא בְּהַהוּא סִטְרָא, אִי זַכָּאָה הוּא, נָטִיל לָהּ הַאי מְמָנָא, וְנָשִׁיק לָהּ.","כְּדֵין אִתְּעַר רוּחָא חֲדָא דְּנָפְקָא מִגּוֹ תְּהוֹמָא בְּסִטְרָא דְּצָפוֹן, וְהַהוּא רוּחָא קָארֵי בְּכָל אִינּוּן אֲוִירִין, וְנַטְלֵי כֻּלְּהוּ הַהִיא מִלָּה, וְסַלְּקִין לָהּ עַד רְקִיעָא וְנַשְּׁקִין לָהּ. פָּתְחֵי וְאַמְרֵי, מָרָךְ יִרְמֵי שַׂנְאָךְ לְקָמָךְ.","וְאָזְלָא וְסַלְּקָא וּבַקְעָא רְקִיעִין (ס\"א אוירין) עַד דְּסַלְּקִין עִמָּהּ לְגַבֵּי רְקִיעָא קַדְמָאָה סַלְּקָא צְלוֹתָא, וּמָטָאת לְגַבֵּי חַד מְמָנָא, דְּאִתְמָנָא לִסְטַר מַעֲרָב, וְתַמָּן קַיָּימִין תִּשְׁעָה פִּתְחִין, וּבְהוּ קַיְימִין כַּמָה סַרְכִין, וְכַמָּה מְמָנָן, וְעָלַיְיהוּ מְמָנָא חַד דִּי שְׁמֵיהּ זְבוּלִי\"אֵל.","וְדָא אִיהוּ דְּבָעֵי לְשַׁמְּשָׁא בְּהַאי רְקִיעָא בִּימָמָא, וְלָא אִתְיְהִיב לֵיהּ רְשׁוּ, עַד דְּסָלִיק נְהוֹרָא דְּסִיהֲרָא, וּכְדֵין אַפִּיק כָּל אִינּוּן חֵילִין, וְכָל אִינּוּן מְמָנָן. וְכַד נָהִיר יְמָמָא, עָאלִין כֻּלְּהוּ בְּפִתְחָא חֲדָא, דְּאִינּוּן ט' פִּתְחִין, דְּאִיהוּ פִּתְחָא עִלָּאָה עַל כֻּלְּהוּ. וְכַד צְלוֹתָא סַלְּקָא, עָאלַת בְּהַהוּא פִּתְחָא, וְכֻלְּהוּ סַרְכִין, וְכֻלְּהוּ מְמָנָן, נָפְקִין מֵהַהוּא פִּתְחָא. וַעֲלֵיהוֹן זְבוּלִיאֵ\"ל, הַהוּא רַב מְמָנָא, וְנַפְקֵי כֻּלְּהוּ וְנַשְּׁקֵי לָהּ, וּמָטָאן עִמָּהּ עַד רְקִיעָא תִּנְיָינָא."],[[0,"כד עאל ליליא וכו':","כשבא הלילה, יוצא כרוז התתקנו שליטים של לילה, כל אחד ואחד על מקומו. וכשמאיר היום יוצא כרוז, התתקנו שליטים של יום, כל אחד ואחד על מקומו, וכשהכרוז מכריז, אז כל אחד ואחד נפקד על מקום ההוא הראוי לו. אז מקדמת השכינה ויורדת, וישראל נכנסים לבית הכנסת לשבח לרבונם ופותחים בשירות ותשבחות."],[1,"דבעי ליה לב\"נ וכו':","שהאדם צריך, אחר שהתקין עצמו בעבודת המעשה, דהיינו בחינה א' הנ\"ל (באות קכב) בתקוני מצוה וקדושה, שהם ציצית ותפילין, הוא צריך ליחד לבו בתקון עבודה הפנימית של רבונו, דהיינו בחינה ב' (שבאות קכב) ולשום לבו ורצונו בעבודה ההיא של אלו הדבורים שבתשבחות. כי הדבור עולה למעלה."],[2,"ואינון ממנן דקיימין וכו':","ואלו הממונים העומדים באויר, נתמנו לד' רוחות העולם. לצד מזרח נתמנה ממונה אחד העומד באויר בצד ההוא, ששמו \u0003גזרדיא.\u0004 ועמו שרים ממונים אחרים, שהם מחכים לדבור ההוא של התפלה, שעולה באויר בצד ההוא. וממונה ההוא לוקח אותה."],[3,"אי היא מלה וכו':","אם היא דיבור כראוי, כל אלו השרים נושקים לדבור ההוא, ועולים עמו עד אויר ההוא של הרקיע למעלה, ששם ממונים שרים אחרים. בשעה שנושקים לדבור ההוא, פותחים ואומרים, אשריכם ישראל, שאתם יודעים לעטר לאדונכם בעטרות קדושות. אשרי הוא הפה, שהדבור של עטרה הזו יצא ממנו."],[4,"כדין פרחין אתוון וכו':","אז פורחות האותיות העומדות באויר, שבשם הקדוש של י\"ב אותיות, ששם הזה שולט באויר. וזהו השם שאליהו היה פורח בו עד שעלה השמימה. וז\"ש עובדיה לאליהו, ורוח ה' ישאך. משום שבשם הזה היה אליהו פורח בו באויר, וזה הוא שם השולט באויר."],[5,"ואינון אתוון פרחין וכו':","ואלו האותיות פורחות ועולות עם מלה ההוא, ואותו הממונה, שהמפתחות של האויר בידו, וכל הממונים האחרים כולם עולים עמה עד הרקיע, ושם נמסר ביד ממונה אחר להעלותה למעלה."],[5,"","ביאור המאמר. כי אחר סוד הנסירה המובא בשער הכונות לראש השנה, נתקן ז\"א, כולו חסדים, דהיינו בחינת קו ימין. והמלכות, כולה גבורות, דהיינו בחינת קו שמאל. ולפיכך כמו שב' הקוין ימין ושמאל דבינה הם במחלוקת (כנ\"ל בראשית א' נ\"ז ד\"ה וזה ע\"ש) עד שעולה ז\"א בבחינת קו האמצעי ועושה שלום ביניהם ומייחדם זה בזה. כך, ז\"א ומלכות, שהם ג\"כ בחינת ב' קוין ימין ושמאל, צריכים לקו אמצעי שיעשה שלום ביניהם וייחד אותם זה בזה. והיינו ע\"י המ\"ן שמעלים הצדיקים, ע\"י תפלתם, שלהיותם מבחינת עוה\"ז הם נושאים סוד המסך דחירק, של קו האמצעי, הגורם לקו שמאל להתיחד עם הימין, וכן לנוקבא להתיחד עם ז\"א."],[5,"","וז\"ש, לעיל (אות ק\"ח) \u0003ובההוא סדורא דתושבחן דקאמרי ישראל לתתא איהי קשיטת גרמהא ואתתקנת בתקונהא כאתתא דמתקשטת לבעלה,\u0004 כי התפלה נעשית בחינת מ\"ן וקו אמצעי העושה שלום ומייחד המלכות עם ז\"א בעלה. וז\"ש לעיל (באות קטו) \u0003ואי בר נש יכוין לביה\u0004 וכו' \u0003כדין קב\"ה קרי ליה שלום לתתא\u0004 וכו' \u0003בנין דאכליל ואעטר למטרוניתא לתתא כגוונא דההוא שלום לעילא.\u0004 כי כמו שהיסוד למעלה הוא בחינת קו האמצעי העושה שלום ומייחד קב\"ה ושכינתיה, כן התפלה שאדם מעלה, היא מתקנת בחינת קו אמצעי, ועושית שלום בין קב\"ה ושכינתיה ליחד אותם ביחוד אחד. וע\"כ נקרא האדם שלום כמו היסוד שלמעלה. ולא עוד, אלא שהשלום של מטה, קודם להשלום של מעלה שהוא היסוד, כי אתערותא דלתתא קודמת לאתערותא דלעילא, כנודע. כי אין אתערותא למעלה מטרם שיעלה התעוררות לזה מן התחתונים."],[5,"","והנה דבורי התפלה, הם חלקי נפשו של האדם, דהיינו נפשו ממש המלובשת בגוף, בסו\"ה נפשי יצאה בדברו. ולפי\"ז, יש לתמוה, כיון שהתפלה, היא בחינת נפש של האדם שבעוה\"ז, שהיא בבחינת ו\"ק דנפש ממלכות דמלכות שבמלכות שבעולם עשיה. איך אפשר שתעלה דרך כל המדרגות שבג' עולמות בי\"ע, ותגיע עד למדרגת המלכות דאצילות, לשמש שם בבחינת מ\"ן וקו אמצעי, ליחד אותה עם ז\"א דאצילות. הלא נודע, ששום מדרגה אינה יכולה להתעלות למעלה ממדרגתה כמלא נימא. מכל שכן קפיצה גדולה כל כך, מתחתית כל המדרגות עד עולם האצילות."],[5,"","וזהו שאומר באות (קכג) \u0003דהא צלותא דבר נש, בוקעת אוירין, בקעת רקיעין, פתחת פתחין, וסלקין לעילא.\u0004 וצריכים תחלה להבין, מה הם אוירים, ומה הם רקיעים, ומה הם פתחים. ואח\"כ נבאר איך הם נבקעים. והענין הוא, כי כבר ידעת, שעל ידי עלית המלכות לבינה, בסוד נקודת החולם, נבקעות הע\"ס שבכל המדרגות לשתים, שכתר וחכמה שבע\"ס דכל מדרגה, נשארים במדרגה, ובינה ות\"ת ומלכות שבע\"ס דכל מדרגה נופלים אל המדרגה שמתחתיה. (כמ\"ש לעיל ב\"א דף ד' ד\"ה ביאור) והוא מטעם, כי המלכות שעלתה לבינה, עשתה שם סיום חדש במדרגה, מחמת הצמצום הרוכב על המלכות שלא לקבל אור. וכיון שבינה ותו\"מ נמצאים מתחת סיום החדש הזה של המדרגה, על כן נבחנים למדרגה שמתחתיה. ואח\"כ ע\"י מ\"ן שמעלים התחתונים מתפשטת הארה מזווג ע\"ב ס\"ג דא\"ק, שהארה זו מוציאה המלכות ממקום בינה ומחזירה למקומה כבתחילה בסיום ע\"ס של כל מדרגה, ואז נמצאים בינה ותו\"מ הנפולים מכל מדרגה שחזרו ועלו למדרגתם כמטרם שנפלו, כי כבר נתבטל סיום החדש שהיה במקום בינה. ונמצא שכל המדרגות חזרו ונשלמו בע\"ס שלמות כמקודם. (כמ\"ש ב\"א דף צ' ד\"ה בגין). אמנם אע\"פ שהמלכות שה\"ס סיום החדש שנעשה בכל מדרגה מחמת עליתה לבינה, חוזרת ויורדת למקומה בסיום ע\"ס, עכ\"ז אין סיום החדש שעשתה, מתבטל לגמרי, ממקום בינה. ולפיכך אין בינה ותו\"מ מתחברים במדרגתם כשהם למטה מסיום החדש אלא צריכים לעלות למעלה מסיום החדש, ונעשים שמה לקו שמאל, אל כתר וחכמה שמעולם לא נפלו מן המדרגה, שהם קו ימין."],[5,"","ולפיכך הסיום החדש הנשאר קבוע וקיים בכל מדרגה אפילו אחר ירידת המלכות משם, הוא נקרא \u0003רקיע.\u0004 ואותם בינה ותו\"מ שנפלו מכל מדרגה בעת עלית המלכות לבינה, וחזרו ועלו למדרגתם אחר ירידת המלכות למקומה, הם נקראים \u0003אויר,\u0004 או רוח, והטעם הוא כי כל מדרגה תחתונה נבחנת לבחינת קומת ו\"ק שנקרא \u0003רוח,\u0004 כלפי המדרגה העליונה ממנה. ולפי\"ז בינה ותו\"מ שנפלו מכל מדרגה למדרגה שמתחתיה, הרי נעשו בזה לקומת רוח כמו המדרגה התחתונה שנפלו שמה. ואחרי ירידת המלכות ממקום בינה, נבחן שהרוח דהיינו \u0003האויר,\u0004 שהם בינה ותו\"מ שהיו מתחת הרקיע, התנשא עתה ועלה למעלה מרקיע ונעשו שם לקו שמאל, כנ\"ל. גם ידעת שבעת שבינה ותו\"מ מתנשאים ועולים למדרגתם מרקיע ולמעלה הם לוקחים עמהם את המדרגה התחתונה, שהלבישה אותם בעת שהיו נפולים בה ומעלים גם אותה למעלה מרקיע. (כמ\"ש בהקדמת ספר הזהר דף כ' ד\"ה ואמא ע\"ש). והוא מטעם מחמת שבינה ותו\"מ דעליון שנשתוו עם התחתון בעת הנפילה, שוב אינם נפרדים מהם גם בעת העליה. ונמצא שע\"י עלית המלכות לבינה, נעשה בשביל מדרגה תחתונה \u0003פתח,\u0004 שתוכל לעלות לעליונה. כי משום זה אח\"כ, בעת ירידת המלכות מבינה, תוכל כל מדרגה תחתונה לעלות לעליונה עם בינה ותו\"מ דעליונה שהיו נפולים ומלובשים בה. באופן, שבסבת עלית המלכות למקום בינה, וחזרתה למקומה בעת הארת ע\"ב ס\"ג, נעשו בכל מדרגה ג' בחינות, א) \u0003אוירים,\u0004 שהם בינה ותו\"מ דכל מדרגה שנפלו לתחתונה. ב) \u0003רקיעים,\u0004 שהם סיום החדש שנעשה בכל מדרגה מחמת עלית המלכות לבינה, שאיני מתבטל לעולם, והוא קבוע וקיים אפילו אחר ירידת המלכות מבינה. ג) \u0003פתחים,\u0004 שהם חידוש \u0003הפתח\u0004 בשביל מדרגה התחתונה, שנעשה בכל מדרגה עם עלית מלכות לבינה שלה. שזולת זה לא היתה שום מציאות שמדרגה תחתונה תוכל פעם לעלות לעליון ממנה. כי אין מדרגה יכולה להתנשאות משהו למעלה ממדרגתה."],[5,"","וענין \u0003בקיעת אוירין\u0004 שאומר (באות קכג) אין הפירוש שהאויר נבקע, אלא הגבול, שעל האויר, שהוא בינה ותו\"מ דעליונה, שנעשה מתוך עלית המלכות למקום בינה, אותו הגבול נבקע ע\"י ירידת המלכות משם למקומה, כי אז עולה האויר למעלה מרקיע ומשיג שם בחינת ג\"ר, כנ\"ל. ואז נעשה ג\"כ, \u0003בקיעת רקיעין,\u0004 כי הרקיע שה\"ס הגבול מסיום החדש שהיה דוחה את הבינה ותו\"מ, שה\"ס האויר, למדרגה תחתונה, והיה מעכב עליהם שלא יחזרו למדרגתם, נמצא \u0003שנבקע\u0004 ע\"י ירידת המלכות למקומה, ואינו מעכב עוד על בינה ותו\"מ שיעלו ויתחברו במדרגתם. ואז נעשה ג\"כ \u0003פתיחת הפתחים,\u0004 בשביל מדרגה התחתונה, כי ע\"י ירידת המלכות למקומה ובקיעת הרקיע, עולים בינה ותו\"מ למררגתם למעלה מרקיע ומקבלים עמהם גם מדרגה התחתונה כנ\"ל. נמצא שנפתח \u0003פתח\u0004 בשביל מדרגה התחתונה לעלות לעליונה."],[5,"","והארה זו המורידה את המלכות ממקום בינה, ומחזירה למקומה בסיום ע\"ס, הוא באה מזווג ע\"ב ס\"ג דא\"ק, שהם חכמה ובינה דא\"ק, כי ענין עלית המלכות למקום בינה, מתחילה בבינה דא\"ק, וע\"ס דחכמה דא\"ק לא נפגמו כלום, והמלכות נמצאת שם במקומה, וע\"כ כשחכמה זו מזדווגת עם בינה דא\"ק נדחה גם בה המלכות ממקום בינה למקומה, ומבינה דא\"ק נמשכה ההארה לבינה דאצילות, שנקראת \u0003אהי\"ה\u0004 ומבינה דאצילות נמשכה ההארה לכל המדרגות דאבי\"ע והן מורידים המלכות מבינה שבהן למקומה, וע\"כ נבחן שם \u0003אהי\"ה\u0004 הזה שהוא שולט באויר, כלומר, שהשם הזה מעביר הגבול מן האויר ע\"י הורדת המלכות מבינה למקומה. וכיון שיש ד' בחינות כוללות חו\"ב תו\"מ, או חו\"ג תו\"מ בכל עולם ועולם, אשר בכל בחינה יש ע\"ס, שע\"י עלית המלכות לבינה דכל בחינה, נפלו הבינה ותו\"מ דכל בחינה למדרגה שמתחתיה, ע\"כ יש ד' אוירים בכל עולם, שבהם שולטים ג' שמות \u0003אהי\"ה,\u0004 שהם: אהיה באויר דחסד, ואהיה באויר הגבורה, ואהיה באויר הת\"ת, ובמלכות המקבלת מהם, שולטים כל ג' אהיה האלו ביחד באויר שלה. וג\"פ \u0003אהי\"ה\u0004 ה\"ס י\"ב אותיות. וז\"ס השם בן י\"ב אותיות השולט באויר."],[5,"","וזה אמרו (באות ק\"ל) \u0003כדין פרחין אתוון דקיימין באוירא, דבשמא קדישא דתריסר אתוון,\u0004 דהיינו י\"ב אותיות שבג' שמות אהיה, \u0003דההוא שמא שליט באוירא,\u0004 כי השם אהיה שולט באויר, דהיינו להוריד המלכות מבינה למקומה ולהחזיר הבינה ותו\"מ הנפולים, הנקראים \u0003אויר,\u0004 למדרגתם למעלה מרקיע. \u0003והאי איהו שמא דהוה טאס ביה אליהו עד דאסתלק לשמיא,\u0004 כי נתבאר לעיל שע\"י עלית המלכות לבינה נעשה פתח לתחתון שיוכל לעלות לעליון בעת שהפתח נפתח, דהיינו בעת חזרת המלכות למקומה. עש\"ה. ולפיכך בעת שאליהו רצה לעוף השמימה, עלתה המלכות של כל מדרגה, לבינה דאותה המדרגה, ובינה ותו\"מ נפלו למדרגה שמתחתיה, וביניהם הופרס רקיע כנ\"ל ע\"ש. ונמצא שכל מדרגה \u0003נתכפלה:\u0004 א) מדרגת עצמה, ב) בינה ותו\"מ דעליונה שנפלו ונתלבשו בה. וזה נעשה בכל מדרגה ומדרגה מאבי\"ע, עד שבינה ותו\"מ דמלכות דעשיה נפלו ויצאו ממלכות לבחינת עוה\"ז, והמלכות דעשיה נסתיימה על הרקיע שלה שהוא הסיום החדש במקום בינה. וגם נתכפלה מחמת שבינה ותו\"מ דיסוד דעשיה נפלו ונתלבשו במדרגתה. ועד\"ז יסוד דעשיה מסתיים ברקיע שלו ויש בו גם בינה ותו\"מ דהוד דעשיה. ועד\"ז נצח דעשיה נתכפלה וכו' עד בינה דאצילות. וע\"כ אליהו עלה ונתדבק בבינה ותו\"מ שנפלו ממלכות דעשיה לעוה\"ז, ונשתוה אליהם והלבישם עד שנעשו כמדרגתו. ואז פעל השם י\"ב, שחזר והוריד המלכות ממקום בינה דמלכות דעשיה למקומה בסיום ע\"ס שלה, ועלו בינה ותו\"מ למדרגתם כבתחילה למעלה מרקיע המלכות, וכיון שאליהו היה דבוק באויר הזה, שהם בינה ותו\"מ שעלו, נמצא שהעלה עמו גם את אליהו למעלה מרקיע של המלכות, מטעם ההשתוות, כנ\"ל."],[5,"","וכיון שעלה למעלה מרקיע של המלכות דעשיה, הרי פגע שם את האויר של היסוד דעשיה, דהיינו הבינה ותו\"מ של היסיד שנפלו שמה. ואז נתדבק באויר הזה ונתלבש בו להיותו עמו כבר במדרגה אחת. ואח\"כ פעל השם בן י\"ב, שהוריד המלכות מבינה דיסוד דעשיה למקומה בסיום ע\"ס דיסוד דעשיה, ואז עלו בינה ותו\"מ, שהם האויר דיסוד למעלה מרקיע דיסוד, וכיון שאליהו היה כבר דבוק באויר הזה, נמצא שגם אליהו עלה עמו למעלה מרקיע דיסוד דעשיה, מטעם ההשתוות."],[5,"","וכיון שעלה למעלה מרקיע דיסוד דעשיה, פגש שם האויר דהוד דעשיה, דהיינו בינה ותו\"מ דהוד דעשיה שנפלו שמה, ואז נתדבק באויר הזה ונתלבש בו להיותו עמו במקום אחד. וע\"כ אח\"כ שפעל השם בן י\"ב והחזיר המלכות בסיום ע\"ס דהוד דעשיה, והאויר, דהיינו בינה ותו\"מ שלו, חזרו למעלה מרקיע דהוד דעשיה, ולקחו עמהם גם את אליהו שהיה דבוק בהם, והעלוהו לרקיע דהוד דעשיה, מטעם ההשתוות."],[5,"","ואחר שכבר היה ברקיע דהוד דעשיה הרי פגש שם האויר של נצח דעשיה, ונתדבק בו. וכשפעל השם בן י\"ב והחזיר המלכות למקומה עלה האויר דנצח למעלה מרקיע והעלה עמו יחד גם את אליהו שהיה דבוק בו. ואחר שכבר היה ברקיע דנצח פגש שם האויר של ת\"ת וכו' עד שעלה עם האויר למעלה מרקיע דת\"ת דעשיה, וכן עד\"ז העלה אותו האויר דכל מדרגה למדרגה העליונה ממנה עד סיום מדרגות דעשיה, ומשם למלכות דיצירה, ומשם לכל המדרגות דיצירה ודבריאה עד שעלה השמים, שהוא ז\"א דאצילות. וז\"ש, \u0003והיינו דקאמר עובדיה לאליהו ורוח ה' ישאך,\u0004 כי רוח ה', שה\"ס בינה ותו\"מ דעליון המכונים רוח או אויר, שנפלו למקום מדרגת התחתון, \u0003הרוח הזה,\u0004 ממש \u0003נשא\u0004 אותו ממדרגה למדרגה, דרך כל פרטי המדרגות מתחתית עשיה עד האצילות. כמו שנתבאר."],[5,"","וזה אמרו. (באות קכ\"ח) \u0003ואינון ממנן דקיימין באוירא אתמנון לד' סטרי עלמא, לסטר מזרח\u0004 וכו'. כי יש ממונים בכל אויר ואויר שבד' רוחות העולם, דהיינו בחו\"ג תו\"מ, שבידם \u0003המפתחות\u0004 לעורר את השם בן י\"ב לפעול, ולהוריד המלכות מבינה למקומה. והזוהר אינו חושב את ד' רוחות על הסדר, אלא מערבב הסדר, מטעם שדרכו להעלים הדברים, כנודע. אמנם הסדר של ד' אוירים, הוא ממטה למעלה, שהם מערב, מזרח, צפון, ודרום. שהם, מלכות, ות\"ת הכולל נה\"י, וגבורה, וחסד. גם אין הפירוש, שהממונים מעלים התפלה מאויר לאויר ואח\"כ מרקיע לרקיע, כמו שמסודר לכאורה בהזהר, אלא האוירים מעלים התפילה לרקיעים, כל אויר לרקיע שלו. וז\"ש, \u0003וההוא ממנא, דמפתחן דאוירא בידיה,\u0004 וכו', \u0003סלקין ביה עד רקיעא, ואתמסר בידא דממנא אחרא.\u0004 באפן, שתחילה עולה התפילה אל האויר של המלכות דעשיה, דהיינו לבינה ותו\"מ שנפלו ממלכות דעשיה לעולם הזה, שהיא כמו בחינת התפלה בעצמה כנ\"ל, ולהיות האויר הזה בבחינה שוה עם התפלה, ע\"כ נתדבקו זה בזה כמדרגה אחת, ואז הממונה \u0003זבוליא\"ל\u0004 אשר שם, מעורר השם בן י\"ב, שמוריד המלכות מבינה דעשיה למקומה, שאז חוזר האויר למדרגתו ועולה למעלה מרקיע דעשיה, וכיון שהאויר כבר נשתווה למדרגת התפלה הוא לוקח עמו גם התפלה למעלה מרקיע דמלכות דעשיה. כמו שבארנו לעיל אצל אליהו. וכיון שהתפלה כבר באה לרקיע דעשיה, הרי פוגשת שם האויר דיסוד דעשיה שנפל שם, כנ\"ל באליהו. גם פוגשת שם בממונה השולט באויר של מזרח שנקרא \u0003גזרדיא\u0004 כי מזרח שהוא ת\"ת, כולל גם את היסוד, משום שהוא כולל נה\"י. והממונה הזה מעורר השם בן י\"ב ומוריד המלכות מבינה דיסוד לסיום שלו, ואז עולה האויר דיסוד למדרגתו, לרקיע דיסוד, ומחמת שכבר נשתוה עם התפלה במדרגה אחת, הוא לוקח גם את התפלה ומעלה אותה עמו ביחד למעלה מרקיע דיסוד. ועד\"ז באויר ורקיע דנצח והוד, ובאויר ורקיע דתפארת."],[5,"","וכיון שהתפלה עלתה לרקיע דת\"ת, היא פוגשת שם האויר של צפון, שהוא בינה ותו\"מ דגבורה דעשיה, שנפל שם. והיא משתוית עם אויר הזה במדרגה אחת. ואז הממונה \u0003פתחיה\u0004 השולט בצפון, מעורר השם בן י\"ב ומוריד המלכות מבינה למקומה, והאויר חוזר ועולה לרקיע דגבורה, ולוקח עמו ביחד גם התפלה שנשתוה עמה במדרגה אחת בשעת הנפילה. וכיון שהתפלה היא ברקיע דגבורה היא פוגשת שם האויר דדרום, שהוא בינה ותו\"מ דחסד דעשיה, שנפל שמה, והיא מתדבקת עם האויר הזה, ואז הממונה \u0003פסגניה,\u0004 השולט על האויר דדרום, שהוא חסד דעשיה, מעורר השם בן י\"ב ומוריד המלכות מבינה דחסד דעשיה למקומה, והאויר דדרום חוזר ועולה למדרגתו לרקיע הששי, שהוא חסד דעשיה הנקרא דרום."],[5,"","וכיון שהתפלה היא ברקיע הששי פוגשת שם האויר, שנפל מרקיע השביעי שהיא בינה הכולל ג\"ר, והיא מתדבקת באויר הזה. וכשהשם בן י\"ב מוריד המלכות מבינה דרקיע הז' למקומה, חוזר האויר למדרגתו לרקיע הז' ולוקח עמו גם התפלה הדבוקה עמו מעת הנפילה. וכיון שהיא ברקיע הז' היא פוגשת ומתדבקת באויר שנפל ממלכות דיצירה, ואז לוקח אותה סנדלפון שהוא הממונה הכללי על כל העשיה, ומעורר השם בן י\"ב, שמוריד המלכות ממלכות דיצירה למקומה, ועולה האויר וחוזר למדרגתו לרקיע דמלכות דיצירה, ולוקח עמו גם התפלה, ומעלה אותה לרקיע דמלכות דיצירה. ועד\"ז בכל ז' היכלות דיצירה ודבריאה עד האצילות. ונתבאר היטב מה שהקשינו, איך התפלה יכולה לעלות מתחתית העשיה עד האצילות, והלא שום מדרגה אינה יכולה להתנשאות למעלה ממדרגתה אפילו כמלא נימא. ובהאמור מובן היטב, כי כיון שנתדבקה באויר הראשון שנפל ממלכות דעשיה לבחינת עולם הזה, הרי האויר הזה נשא אותה לרקיע של המלכות, והאויר דיסוד דעשיה לרקיע דיסוד וכו', באפן, שהאוירים, שהתפלה עלתה ונתדבקה בהם, הם נשאוה והעלוה עד למלכות דאצילות. בסוה\"כ ורוח ה' ישאך. וזכור הדברים עד סיום המאמר, כי לא אכפול אותם עוד."],[6,"לסטר דרום אית וכו':","לצד דרום, שהוא חסד, יש ממונה אחר השולט באויר בצד ההוא, וכמה ממונים ושרים אחרים עמו. ושמו \u0003פסגניה.\u0004 לו נמסרו מפתחות האויר שלצד ההוא, וכל אלו שיש להם צרות, המתפללים תפלה לאדונם מתוך צרתם, מתוך שבירת הלב, אם הדבור ההוא הוא כראוי, הוא עולה לאויר בצד ההוא, ומקבל אותו הממונה ההוא ונושק אותו. כשנושק אותו, פתח ואמר, הקב\"ה ירחם עליך ויתמלא רחמים בשבילך."],[7,"סלקין עמה כל וכו':","עולים עמו, כל אלו ממונים הקדושים וכל אלו השרים שבצד ההוא, פורחות האותיות של השם הקדוש, אהיה, של השם בן י\"ב, שהם ד' אותיות אהיה לכל צד כנ\"ל, המתעטרים ושולטים בצד ההוא של האויר, ועולים בצד ההוא של האויר, עד הרקיע של הדרום, שהוא חסד דהיינו רקיע הששי, כמ\"ש לעיל בארוכה, עד ממונה ההוא של הרקיע השולט בצד ההוא, דרום. כי ברקיע דדרום כבר יש שם ממונה אחר, ששמו \u0003ענפיאל\u0004 (כמ\"ש באות קמז)."],[8,"לסטר צפון אית וכו':","לצד צפון שהוא גבורה יש ממונה אחר השולט באויר, ועמו כמה שרים ממונים השולטים באויר. וממונה ההוא שמו \u0003פתחיה.\u0004 והוא נתמנה באויר לצד ההוא. וכל אלו שמתפללים תפלות על שונאים שמצירים להם, וכשהדבור של תפלה ההיא עולה לאויר בצד ההוא, אם הוא צדיק, מקבל אותו ממונה ההוא ונושקו."],[9,"כדין אתער רוחא וכו':","אז נתעורר רוח אחד היוצא מתוך התהום שבצד צפון, ורוח ההוא קורא לכל אלו אוירים, ולוקחים כולם את הדבור ההוא, ומעלים אותו עד הרקיע דצפון, שהוא רקיע החמשי, ונושקים אותו, ופותחים ואומרים, אדונך יפיל שונאך לפניך."],[9,"","פירוש, אחר שהממונה על האויר קבל התפלה ונשקה, דהיינו שנתדבקה במדרגת האויר והממונה, אז \u0003נתעורר האויר מתוך התהום שבצד צפון,\u0004 כלומר, הסיום שעשתה המלכות במקום בינה, נקרא \u0003תהום\u0004 מלשון תוהו, שע\"י השם בן י\"ב ירדה המלכות מבינה דגבורה דעשיה למקומה כנ\"ל, ואז נתעורר האויר שנפל בבחינת דינין דתהום הזה, לעלות לרקיע דגבורה, וכל המדרגות שהיו דבוקים עמו בעת הנפילה העלה עמו לרקיע דגבורה מחמת ההשתוות, כנ\"ל באורך. וז\"ש \u0003וההוא רוחא קארי בכל אינון אוירין,\u0004 דהיינו בכל המדרגות שהיו דבוקים באויר הזה, והיה להם קומת אויר. \u0003ונטלי כלהו ההיא מלה וסלקין לה עד רקיעא,\u0004 שכל המדרגות נתדבקו באויר דצפון העולה לרקיע דצפון, ולקחו עמהם גם התפלה שהיתה דבוקה עמהם, והעלוה לרקיע. דהיינו לרקיע החמשי."],[10,"ואזלא וסלקא ובקעא וכו':","ומכאן מתחיל סדר עלית התפלה. (כמ\"ש לעיל באות ק\"ל), והולכת התפלה ועולית ובוקעת אוירין, היינו האויר שנפל ממלכות דעשיה לבחינת עוה\"ז, עד שעולים עמה לרקיע הראשון, שהוא רקיע דמלכות דעשיה, עולית התפלה ומגעת לממונה אחד שנתמנה לצד מערב, שהוא המלכות, ושם נמצאים תשעה פתחים, ובהם עומדים כמה שרים וכמה ממונים, ועליהם ממונה אחד ששמו \u0003זבוליאל.\u0004"],[10,"","פירוש. ט' פתחים הם בעשר ספירות של המלכות. ואינם עשרה פתחים. מטעם שהמלכות דמלכות מצד היותה מדת הדין הוא כלולה ביסוד דמלכות (כנ\"ל בהקסה\"ז דף מ\"ז ד\"ה גו). וע\"כ יש ליסוד ומלכות רק פתח אחד, והם ט' פתחים. אמנם יש לשאול מה השינוי שבכאן, שבכל הרוחות יש ממונה מיוחד על האויר וממונה מיוחד על הרקיע, כגון במזרח, יש ממונה על האויר דמזרח ששמו גזרדיא, (כמ\"ש באות קכ\"ח), וממונה מיוחד מיוחד ברקיע דמזרח, שהוא ת\"ת רקיע הרביעי, ששמו שמשיאל. (כמ\"ש להלן באות קמ\"ה), וכן בדרום יש ממונה על האויר ששמו פסגניה, (כמ\"ש באות קל\"ב), וממונה מיוחד על הרקיע ששמו ענפיאל (כמ\"ש באות קמ\"ז), וכן בצפון יש ממונה על האויר ששמו פתחיה (כמ\"ש באות קל\"ד), וממונה מיוחד על הרקיע ששמו גדריאל (כמ\"ש באות קמ\"ו) וכאן במלכות אין יותר מממונה אחד על האויר ועל הרקיע יחד, ששמו זבוליאל."],[10,"","והענין הוא, כי נתבאר שמחמת עלית המלכות לבינה, יצאו בינה ותו\"מ מכל המדרגות ונפלו למדרגה שמתחתיה וירדו לקומת אויר. ולא כל הבינה נפלה רק מחציתה, דהיינו ז\"ת שלה, באפן, שכתר חכמה וחצי בינה נשארו בהמדרגה, וחצי בינה, ותו\"מ נפלו מנה ונעשו לבחינת אויר. ולפיכך נתמנו ב' ממונים, אחד במחצית המדרגה העליונה שנשארה במדרגה למעלה מרקיע, וממונה אחד במחצית המדרגה התחתונה שיצאה מן המדרגה ונעשה לאויר. מה שאין כן מדרגת המלכות, שממנה נפלו כל ט' ספירות תחתוניות שלה למדרגה שמתחתיה, בעת עלית המלכות לבינה, ולא נשאר במדרגתה כי אם הכתר שלה, שנשאר בבחינת נקודה תחת יסוד. וגם נקודה זו שנשארה, נחשב יותר על בחינת יסוד, מעל בחינת מלכות. וע\"כ אין בה אלא בחינת אויר בלבד, והיא כולה אויר, חוץ מהכתר שלה. ולפיכך אין בה אלא ממונה אחד על שניהם."],[11,"ודא איהו דבעי וכו':","וזה רוצה לשמש ברקיע הזה ביום, ולא ניתנה לו רשות עד שעולה האור של הלבנה, דהיינו בלילה. ואז הוא מוציא כל אלו הצבאות וכל אלו הממונים. וכשהאיר היום עולים כולם בפתח אחד מאלו ט' פתחים, שהוא פתח העליון על כולם, דהיינו בנקודת כתר שנשארה במדרגה, שמתחתיה עומד הרקיע, כנ\"ל בדבור הסמוך, וכשהתפלה עולה היא נכנסת בפתח ההוא, העליון על כולם, וכל השרים וכל הממונים יוצאים מפתח ההוא, ועליהם זבוליאל ההוא ממונה העליון, כלומר שאין שם ממונה אחר אלא אותו זבוליאל הממונה באויר, הוא ממונה ג\"כ בפתח העליון, שהוא למעלה מרקיע המלכות דעשיה. ויוצאים כולם ונושקים אותה, ומגיעים עמה עד רקיע השני, שהוא יסוד דעשיה."],[11,"","פירוש המלכות היא בחינת קו שמאל, דהיינו חכמה בלי חסדים, וע\"כ בשעה שהיא מושלת אין אור אלא חשך, כי החכמה אינה מאירה בלי חסדים. וזסו\"ה, ותקם בעוד לילה. שזמן קימתה, דהיינו שליטתה, הוא בלילה. וז\"ש. \u0003ודא איהו דבעי לשמשא בהאי רקיע ביממא ולא אתיהיב ליה רשו,\u0004 כי בשעה שהמלכות שולטת היא לילה ולא יום, מטעם הנ\"ל, \u0003עד דסליק נהורא דסיהרא,\u0004 דהיינו עד הלילה. \u0003וכדין אפיק כל אינון חילין וכל אינון ממנן,\u0004 כי בלילה שולטים כל הט\"ס תחתוניות של המלכות, ונמשכים מהם צבאות וממונים המושלים מכח השמאל."],[11,"","וז\"ש \u0003וכד נהיר יממא,\u0004 והמלכות יורדת מבינה למקומה, אע\"פ שט\"ס תחתוניות הם בלי פגם, כי כבר ירדה המלכות מן הרקיע שצמצם אותם לבחינת אויר, עכ\"ז אין להם שליטה במקומם אלא שצריכים לעלות מרקיע ולמעלה, לפתח העליון שבכולם שהוא הכתר. ששם הם נכללים בימין בחסדים. ועמהם הולכת ועולית גם התפלה, מחמת ההשתוות שהשיגה עמהם בהיותם למטה מרקיע, (כנ\"ל בביאור באות קל\"א ע\"ש). וכיון שהתפלה עלתה למעלה מרקיע דמלכות, היא פוגשת שם את האויר של הרקיע השני, שנפל שם, שאח\"כ אחר ירידת המלכות מבינה דיסוד דעשיה למקומה, מתנשא האויר ועולה לרקיע היסוד, ולוקח עמו יחד, כל הצבאות והממונים והתפלה שהיו דבוקים בו בשעת הנפילה, ומעלה אותם לרקיע היסוד. וז\"ש \u0003ונפקי כלהו ונשקי לה ומטאן עמה עד רקיעא תנינא.\u0004 שהוא רקיע של היסוד דעשיה."]],[[0,"","כְּשֶׁנִּכְנָס הַלַּיְלָה, יוֹצֵא כָּרוֹז: הִתְתַּקְּנוּ שַׁלִּיטֵי הַלַּיְלָה כָּל אֶחָד וְאֶחָד לִמְקוֹמוֹ. וּכְשֶׁמֵּאִיר הַיּוֹם, כָּרוֹז יוֹצֵא: הִתְתַּקְּנוּ שַׁלִּיטֵי הַיּוֹם כָּל אֶחָד וְאֶחָד לִמְקוֹמוֹ. (אז מעברים שליטי הלילה ומתמגים שליטי היום) וּכְשֶׁהַכָּרוֹז מַכְרִיז, אָז כֻּלָּם, כָּל אֶחָד וְאֶחָד נִפְקָד עַל אוֹתוֹ מָקוֹם שֶׁרָאוּי לוֹ. אֲזַי הַשְּׁכִינָה מַקְדִּימָה וְיוֹרֶדֶת, וְיִשְׂרָאֵל נִכְנָסִים לְבֵית הַכְּנֶסֶת לְשַׁבֵּחַ אֶת רִבּוֹנָם וּפוֹתְחִים בְּשִׁירוֹת וְתִשְׁבָּחוֹת."],[1,"","שֶׁצָרִיךָ לוֹ לָאָדָם, שֶׁכֵּיוָן שֶׁהִתְקִין עַצְמוֹ לַעֲבוֹדַת הַמַּעֲשֶׂה בְּתִקּוּנֵי מִצְוָה וּקְדֻשָּׁה, לְיַחֵד לִבּוֹ בַּתִּקּוּן שֶׁל הָעֲבוֹדָה הַפְּנִימִית שֶׁל אֲדוֹנוֹ, וְלָשִׂים אֶת לִבּוֹ וּרְצוֹנוֹ בְּאוֹתָהּ עֲבוֹדָה שֶׁל אוֹתָם דְּבָרִים (שאומר), שֶׁהֲרֵי הַדִּבּוּר עוֹלֶה."],[2,"","וְאוֹתָם הַמְמֻנִּים שֶׁעוֹמְדִים בָּאֲוִיר, הִתְמַנּוּ לְאַרְבַּעַת צִדְדֵי הָעוֹלָם. לְצַד מִזְרָח הִתְמַנָּה מְמֻנֶּה אֶחָד שֶׁעוֹמֵד בָּאֲוִיר לְאוֹתוֹ צַד, וּשְׁמוֹ גְּזַרְדִּיָּ\"א, וְעִמּוֹ שָׂרִים מְמֻנִּים אֲחֵרִים, שֶׁהֵם מְחַכִּים לְאוֹתוֹ דִבּוּר שֶׁל תְּפִלָּה, וְעוֹלֶה בָּאֲוִיר בְּאוֹתוֹ צַד, וְנוֹטֵל אוֹתוֹ אוֹתוֹ הַמְמֻנֶּה."],[3,"","אִם הַדִּבּוּר הַזֶּה הוּא כָּרָאוּי, וְכָל אוֹתָם שָׂרִים נוֹשְׁקִים אֶת אוֹתוֹ דִבּוּר וְעוֹלִים עִמּוֹ עַד לְאוֹתוֹ אֲוִיר שֶׁל הָרָקִיעַ לְמַעְלָה, שֶׁשָּׁם מְמֻנִּים שָׂרִים אֲחֵרִים - בְּשָׁעָה שֶׁנּוֹשְׁקִים אֶת אוֹתוֹ דִבּוּר, פּוֹתְחִים וְאוֹמְרִים: אַשְׁרֵיכֶם יִשְׂרָאֵל שֶׁאַתֶּם יוֹדְעִים לְעַטֵּר אֶת אֲדוֹנְכֶם בַּעֲטָרוֹת קְדוֹשׁוֹת. אַשְׁרֵי הַפֶּה שֶׁדִּבּוּר שֶׁל הָעֲטָרָה הַזּוֹ יָצָא מִמֶּנּוּ."],[4,"","וְאָז פּוֹרְחוֹת הָאוֹתִיּוֹת שֶׁעוֹמְדוֹת בָּאֲוִיר שֶׁבַּשֵּׁם הַקָּדוֹשׁ שֶׁל שְׁתֵּים עֶשְׂרֵה אוֹתִיּוֹת, שֶׁאוֹתוֹ שֵׁם שׁוֹלֵט בָּאֲוִיר, וְזֶהוּ שֵׁם שֶׁהָיָה טָס בּוֹ אֵלִיָּהוּ עַד שֶׁעָלָה לַשָּׁמַיִם. וְזֶהוּ מַה שֶּׁאָמַר עוֹבַדְיָה לְאֵלִיָּהוּ, (מלכים א יח) וְרוּחַ ה' יִשָּׂאֲךְ. מִשּׁוּם שֶׁבַּשֵּׁם הַזֶּה הָיָה טָס בּוֹ אֵלִיָּהוּ בָּאֲוִיר, וְזֶהוּ הַשֵּׁם שֶׁשּׁוֹלֵט בָּאֲוִיר."],[5,"","וְאוֹתָן הָאוֹתִיּוֹת פּוֹרְחוֹת וְעוֹלוֹת בְּאוֹתוֹ דִבּוּר, וְאוֹתוֹ הַמְמֻנֶּה שֶׁמַּפְתְּחוֹת הָאֲוִיר בְּיָדוֹ, וְכָל אוֹתָם הַמְמֻנִּים הָאֲחֵרִים, כֻּלָּם עוֹלִים בּוֹ עַד לָרָקִיעַ, וְנִמְסָר בְּיַד מְמֻנֶּה אַחֵר לְהַעֲלוֹתוֹ לְמַעְלָה."],[6,"","לְצַד דָּרוֹם יֵשׁ מְמֻנֶּה אַחֵר שֶׁשּׁוֹלֵט בָּאֲוִיר לְאוֹתוֹ הַצַּד, וְכַמָּה מְמֻנִּים וְשָׂרִים אֲחֵרִים עִמּוֹ, וּשְׁמוֹ פְּסַגְנִיָּ\"ה, וּבוֹ נֶאֱחָזִים (ולו נמסרו) מַפְתְּחוֹת הָאֲוִיר שֶׁל אוֹתוֹ צַד. וְכָל אוֹתָם בַּעֲלֵי צָרָה שֶׁמִּתְפַּלְלִים תְּפִלָּה לַאֲדוֹנָם מִתּוֹךְ צָרָה, מִתּוֹךְ שִׁבְרוֹן הַלֵּב - אִם אוֹתוֹ הַדִּבּוּר כָּרָאוּי, הוּא עוֹלֶה לָאֲוִיר בְּאוֹתוֹ צַד, וְהַמְמֻנֶּה הַזֶּה נוֹטֵל אוֹתוֹ וְנוֹשֵׁק אוֹתוֹ (משום שעלה באותו צד). וּכְשֶׁנּוֹשֵׁק אוֹתוֹ, פּוֹתֵחַ וְאוֹמֵר: הַקָּדוֹשׁ בָּרוּךְ הוּא יָחוּס כְּנֶגְדְּךְ (ועליך), וּבִשְׁבִילְךְ יִתְמַלֵּא בְרַחֲמִים."],[7,"","עוֹלִים עִמָּהּ כָּל אוֹתָם מְמֻנִּים קְדוֹשִׁים וְכָל אוֹתָם שָׂרִים שֶׁל אוֹתוֹ הַצַּד, וּפוֹרְחוֹת הָאוֹתִיּוֹת שֶׁל הַשֵּׁם הַקָּדוֹשׁ, שֶׁהֵן אַרְבַּע אוֹתִיּוֹת שֶׁמִּתְעַטְּרוֹת וְשׁוֹלְטוֹת בְּאוֹתוֹ צַד שֶׁל הָאֲוִיר, וְעוֹלִים בְּאוֹתוֹ הַצַּד שֶׁל הָאֲוִיר עַד לָרָקִיעַ, עַד לְאוֹתוֹ הַמְמֻנֶּה שֶׁל הָרָקִיעַ שֶׁשּׁוֹלֵט בְּאוֹתוֹ הַצַּד."],[8,"","לְצַד צָפוֹן יֵשׁ מְמֻנֶּה אַחֵר, וְעִמּוֹ כַּמָּה שָׂרִים מְמֻנִּים שֶׁשּׁוֹלְטִים בָּאֲוִיר, וּשְׁמוֹ שֶׁל אוֹתוֹ מְמֻנֶּה פְּתַחְיָ\"ה, וְזֶהוּ שֶׁהִתְמַנָּה בָּאֲוִיר שֶׁל אוֹתוֹ צַד, וְכָל אוֹתָם שֶׁמִּתְפַּלְלִים תְּפִלּוֹת עַל שׂוֹנְאִים שֶׁמְּצִיקִים לָהֶם, וּכְשֶׁדִּבּוּר שֶׁל אוֹתָהּ תְּפִלָּה עוֹלֶה לָאֲוִיר בְּאוֹתוֹ צַד - אִם הוּא צַדִּיק, נוֹטֵל אוֹתוֹ הַמְמֻנֶּה הַזֶּה וְנוֹשֵׁק אוֹתוֹ."],[9,"","אֲזַי מִתְעוֹרֶרֶת רוּחַ אַחַת שֶׁיּוֹצֵאת מִתּוֹךְ הַתְּהוֹם שֶׁבְּצַד הַצָּפוֹן, וְאוֹתָהּ רוּחַ קוֹרֵאת בְּכָל אוֹתָם הָאֲוִירִים, וְכֻלָּם נוֹטְלִים אוֹתוֹ דִבּוּר וּמַעֲלִים אוֹתוֹ עַד לָרָקִיעַ וְנוֹשְׁקִים אוֹתוֹ, וּפוֹתְחִים וְאוֹמְרִים: רִבּוֹנְךְ יַפִּיל שׂוֹנַאֲךְ לְפָנֶיךְ."],[10,"","וְהוֹלֵךָ וְעוֹלֶה וּבוֹקֵעַ רְקִיעִים (אוירים). עַד שֶׁעוֹלִים עִמּוֹ לָרָקִיעַ הָרִאשׁוֹן, עוֹלָה הַתְּפִלָּה וּמַגִּיעָה לִמְמֻנֶּה אֶחָד שֶׁהִתְמַנָּה לְצַד מַעֲרָב, וְשָׁם עוֹמְדִים תִּשְׁעָה פְתָחִים, שֶׁבָּהֶם עוֹמְדִים כַּמָּה שָׂרִים וְכַמָּה מְמֻנִּים, וַעֲלֵיהֶם מְמֻנֶּה אֶחָד שֶׁשְּׁמוֹ זְבוּלִיאֵ\"ל."],[11,"","וְזְהִוּ שֶׁרוֹצֶה לְשַׁמֵּשׁ בָּרָקִיעַ הַזֶּה בַּיּוֹם, וְלֹא נִתֶּנֶת לוֹ רְשׁוּת, עַד שֶׁעוֹלֶה אוֹר הַלְּבָנָה, וְאָז הוּא מוֹצִיא כָּל אוֹתָם הַחֲיָלוֹת וְכָל אוֹתָם מְמֻנִּים. וּכְשֶׁמֵּאִיר הַיּוֹם, נִכְנָסִים כֻּלָּם לְפֶתַח אֶחָד, שֶׁהֵם תִּשְׁעָה פְתָחִים, שֶׁהוּא פֶּתַח עֶלְיוֹן עַל כֻּלָּם. וּכְשֶׁהַתְּפִלָּה עוֹלָה, הִיא נִכְנֶסֶת בְּאוֹתוֹ פֶּתַח, וְכָל הַשָּׂרִים וְכָל הַמְמֻנִּים יוֹצְאִים מֵאוֹתוֹ פֶתַח. וַעֲלֵיהֶם זְבוּלִיאֵ\"ל, אוֹתוֹ מְמֻנֶּה גָּדוֹל, וְיוֹצְאִים כֻּלָּם וְנוֹשְׁקִים אוֹתוֹ, וּמַגִּיעִים עִמּוֹ עַד לָרָקִיעַ הַשֵּׁנִי."]]],[["(ס\"א ברקיעא תניינא סלקא צלותא עד ההוא רקיע ואתפתחו) וְכַד סַלְּקָא צְלוֹתָא עַד הַהוּא רְקִיעָא, אִתְפְּתָחוּ תְּרֵיסָר תַּרְעִין דְּהַהוּא רְקִיעָא. וּבְהַהוּא תַּרְעָא דִּתְרֵיסָר, קָאִים מְמָנָא חַד, דִּשְׁמֵיהּ עָנָ\"אֵל, וְהַאי מְמָנָא עַל כַּמָה חַיָּילִין, עַל כַּמָה מַשִּׁרְיָין, וְכַד צְלוֹתָא סַלְּקָא, קָאִים הַאי מְמָנָא וְכָרִיז עַל כָּל אִינּוּן פִּתְחִין וְאָמַר, (ישעיהו כ״ו:ב׳) פִּתְחוּ שְׁעָרִים וְגוֹ', וְכֻלְּהוּ תַּרְעִין פְּתִיחִין, וְעָאלַת צְלוֹתָא בְּכָל אִינּוּן פִּתְחִין.","כְּדֵין, אַתְעַר חַד מְמָנָא סָבָא דְּיוֹמִין, דְּקָאִים לִסְטַר דָּרוֹם, דִּשְׁמֵיהּ עַזְרִיאֵ\"ל סָבָא, וּלְזִמְנִין אִתְקְרֵי מַחֲנִיאֵ\"ל, בְּגִין דְּאִתְמַנָא עַל שִׁתִּין רִבּוֹא מַשִׁרְיָין, וְכֻלְּהוּ מָארֵי דְּגַדְפִין, מָארֵי דְּמַשִׁרְיָין, מַלְיָין עַיְינִין. וּלְגַבַּיְיהוּ קַיְּימִין אִינּוּן מַשִׁרְיָין מָארֵיהוֹן דְּאוּדְנִין. וְאִקְרוּן אוּדְנִין, בְּגִין דְּאִינּוּן צַיְיתִין, כָּל אִינּוּן דִּמְצַלָאן צְלוֹתְהוֹן בִּלְחִישׁוּ, בִּרְעוּתָא דְּלִבָּא, דְּלָא אִשְׁתְּמַע הַהוּא צְלוֹתָא לְאַחֲרָא. הַאי צְלוֹתָא סַלְּקָא, וְצַיְיתִין לָהּ כָּל אִינּוּן דְּאִקְרוּן מָארֵי דְּאוּדְנִין.","וְאִי הַהִיא צְלוֹתָא אִשְׁתְּמַע לְאוּדְנִין דְּבַר נָשׁ, לֵית מַאן דְצַיִית לָהּ לְעֵילָּא, וְלָא צַיְיתִין לָהּ אַחֲרָנִין, בַּר מַאן דְּשָׁמַע בְּקַדְמִיתָא, בְּגִין כָּךְ בָּעֵי לְאִסְתַּמְּרָא דְּלָא יִשְׁמְעוּן לְהַהִיא צְלוֹתָא בְּנֵי נָשָׁא. וְתוּ, דְּמִלָּה דִּצְלוֹתָא אִתְאַחֲדָא בְּעָלְמָא עִלָּאָה, וּמִלָּה דְּעָלְמָא עִלָּאָה, (בראשית ג' ע\"ב) לָא אִצְטְרִיךְ לְמִשְׁמַע.","כְּגַוְונָא דָּא, מַאן דְּקָרֵי בְּסִפְרָא דְּאוֹרַיְיתָא, חַד קָרֵי, וְחַד לִשְׁתּוֹק, וְאִי תְּרֵי קָרָאן בְּאוֹרַיְיתָא, גַּרְעֵי מְהֵימְנוּתָא דִּלְעֵילָּא, בְּגִין דְּחַד קָלָא וְדִיבּוּר כֹּלָּא חַד כְּדֵין תְּרֵין קָלִין וּתְרֵין דִּבּוּרִין, אִיהוּ גְּרִיעוּתָא דִּמְהֵימְנוּתָא. אֶלָּא דִּיְּהֵא קָלָא וְדִבּוּר חַד כְּמָה דְּאִצְטְרִיךְ, בְּגִין דִּיְּהֵא הַהוּא קָלָא וְהַהוּא דִּבּוּר חַד.","וְהַהוּא מְמָנָא, שְׁמֵיהּ עַזְרִי\"אֵל סָבָא. כַּד הַהִיא צְלוֹתָא סַלְּקָא בִּלְחִישׁוּ, כָּל אִינּוּן שִׁתִּין רִבּוֹא מַשִׁרְיָין, וְכָל אִינּוּן מָארֵי דְּעַיְינִין, וְכָל אִינּוּן מָארֵי דְּאוּדְנִין, כֻּלְּהוּ נַפְקֵי וְנַשְּׁקֵי לְהַהִיא מִלָּה דִּצְלוֹתָא דְּסַלְּקָא. הֲדָא הוּא דִכְתִיב, (תהלים לה) עֵינֵי יְיָ' אֶל צַדִּיקִים וְאָזְנָיו אֶל שַׁוְעָתָם. עֵינֵי יְיָ' אֶל צַדִּיקִים, אִלֵּין מָארֵי דְּעַיְינִין דִּלְתַתָּא, בְּגִין דְּאִית (נ\"א דלית) מָארֵי דְּעַיְינִין לְעֵילָּא. וְאָזְנָיו אֶל שַׁוְעָתָם, אִלֵּין מָארֵיהוֹן דְּאוּדְנִין.","רְקִיעָא תְּלִיתָאָה, הַהִיא צְלוֹתָא סַלְּקָא וּמָטֵי לְהַהוּא רְקִיעָא, וְתַמָּן הַהוּא מְמָנָא דְּאִקְרֵי גְּדַרְיָ\"ה, וְעִמֵּיהּ כַּמָה סַרְכִין וְכַמָּה מְמָנָן. וְאִיהוּ מְשַׁמֵשׁ ג' זִמְנִין בְּיוֹמָא, לָקֳבֵל חַד שַׁרְבִיטָא דְּזִיהֲרָא דְּנָפִיק, סָלִיק וְנָחִית וְלָא קַיְּימָא בַּאֲתָר חַד, וְהַאי אִיהוּ שַׁרְבִיטָא דְּנָטִיל ג' זִמְנִין וְאִתְגְּנִיז. וְכַד צְלוֹתָא סַלְּקָא, נָחִית הַהוּא שַׁרְבִיטָא, וְסָגִיד קַמֵּי הַהוּא צְלוֹתָא, וְאִקְרֵי הַאי רְקִיעָא, רְקִיעָא דְּשַׁרְבִיטָא.","וְכַד סַלְּקָא הַהִיא צְלוֹתָא, הַהוּא מְמָנָא בָּתַר דְּסָגִיד, בָּטַשׁ, בְּהַהוּא שַׁרְבִיטָא בְּטִינָרָא, תַּקִּיפָא דְּזָהִיר, דְּאִיהוּ קָאִים בְּאֶמְצָעִיתָא דְּהַהוּא רְקִיעָא, וְנַפְקוּ מִגּוֹ הַהוּא טִינָרָא, תְּלַת מְאָה וְשִׁבְעִין וְחָמֵשׁ חַיָּילִין דְּאִינּוּן גְּנִיזִין תַּמָּן מִן יוֹמָא דְּאוֹרַיְיתָא נַחְתַּת לְאַרְעָא, בְּגִין דְּאִתְתָּקָפוּ לְחַבְּרָא (ס\"א לסרבא) דְּלָא תֵּחוֹת לְאַרְעָא, וְאָנְזִיף בְּהוּ קוּדְשָׁא בְּרִיךְ הוּא, וְעָאלוּ גּוֹ הַהוּא טִינָרָא. וְלָא נָפְקִין בַּר הַהוּא זִמְנָא דִּצְלוֹתָא סַלְּקָא, פָּתְחֵי וְאַמְרֵי (תהילים ח׳:ב׳) יְיָ' אֲדוֹנֵינוּ מַה אַדִּיר שִׁמְךָ וְגוֹ'. דָּא הִיא צְלוֹתָא, דְּסַלְּקָא עַל כָּל אִינּוּן רְקִיעִין. כְּדֵין סַגְדִּין לְגַבָּהּ.","מִכָּאן וּלְהָלְאָה, צְלוֹתָא מִתְעַטְּרָא בְּעִטְרִין עִלָּאִין, וְסַלְּקָא לְגוֹ רְקִיעָא רְבִיעָאָה, וּכְדֵין שִׁמְשָׁא נָפִיק בְּדַרְגּוֹי, וְשַׁמְשִׁי\"אֵל רַב מְמָנָא נָפִיק, וּתְלַת מְאָה וְשִׁתִּין וְחָמֵשׁ מַשִׁרְיָין סַלְּקִין עִמֵּיהּ, לְגוֹ הַהוּא רְקִיעָא, וְאִקְרוּן יְמוֹת הַחַמָּה, וְכֻלְּהוּ מְעַטְּרָן לְהַהִיא צְלוֹתָא, בְּעִטְרִין דְּבוּסְמִין דְּגִּנְתָּא דְּעֵדֶן.","וְתַמָּן אִתְעַכָּבַת צְלוֹתָא, עַד דְּכֻלְּהוּ מַשִׁרְיָין סַלְּקִין עִמָּהּ לְגוֹ הַהוּא רְקִיעָא חֲמִישָׁאָה, וְתַמָּן אִיהוּ מְמָנָא חַד גַּדְרִי\"אֵל שְׁמֵיהּ, וְהוּא מָארֵי קְרָבִין דִּשְׁאַר עַמִּין. וְכַד צְלוֹתָא סַלְּקָא, כְּדֵין אִזְדַּעְזָע הוּא, וְכָל מַשִׁרְיָין דִּילֵיהּ, וְאִתְבַּר חֵילַיְיהוּ, וְנַפְקֵי וְסַגְדֵּי, וּמְעַטְּרִין לְהַהִיא צְלוֹתָא."],[[0,"וכד סלקא צלותא וכו':","וכשהתפלה עולה אל רקיע ההוא, יסוד, נפתחו י\"ב שערים של רקיע ההוא, ובשער הי\"ב עומד ממונה אחד ששמו \u0003ענאל,\u0004 והוא ממונה על כמה צבאות ועל כמה מחנות. וכשהתפלה עולה, עומד ממונה הזה ומכריז על כל אלו הפתחים, ואומר, פתחו שערים וגו', וכל השערים נפתחים. והתפלה נכנסת בכל אלו השערים."],[0,"","פירוש. שבת\"ת יש י\"ב גבולי אלכסון, שה\"ס הו\"ג תו\"מ שבכל אחד מהם ג' קוים חג\"ת, שהם י\"ב, ונקראים גבולי אלכסון, מטעם הנתבאר לעיל (פרשת לך דף ח' ד\"ה וזה, ע\"ש), וכל מה שיש בת\"ת יש גם ביסוד, והם נקראים ביסוד י\"ב שערים. וז\"ש, \u0003ועאלת צלותא בכל אינון פתחין.\u0004"],[1,"כדין אתער חד וכו':","אז נתעורר ממונה אחד זקן בימים, העומד לצד דרום, ששמו \u0003עזריאל סבא,\u0004 ולפעמים נקרא \u0003מחניאל,\u0004 משום שנתמנה על ששים רבוא מחנות. וכולם בעלי כנפים, בעלי מחנות המלאים עינים. ואצלם עומדים אלו המחנות שהם בעלי אזנים, ונקראים אזנים, משום שהם מקשיבים לכל אלו שמתפללים תפלתם בחשאי, ברצון הלב, שלא נשמע התפלה לאחר, תפלה זו עולה ומקשיבים לה כל אלו הנקראים בעלי אזנים."],[1,"","פירוש. כי יש גילוי מיוחד בספירת היסוד מחסד העליון הנקרא, חסד דמתגליא אפומא דאמה. והוא נמשך מקו ימין שבבינה. וע\"כ נקרא הממונה על חסד הזה בשם \u0003עזריאל סבא,\u0004 כי חכמה ובינה נקראים זקנים. והוא ממונה על ששים רבוא מחנות, דהיינו שש מאות אלף. כי שש מאות נמשכים לו מחג\"ת נה\"י דבינה, שספירותיה בסוד מאות. ואלף, ה\"ס הארת חכמה, המכונה אלף, שכל אחת כלולה ממנה. וע\"כ הם ששים רבוא. ובחינת ג\"ר דתבונה נקראים אזנים, שבהם מאירים חסדים ולא חכמה. וו\"ק דתבונה מכונים עינים, שבהם מאירה החכמה. וע\"כ הוא מושך מבינה ב' בחינות אלו. וז\"ש, \u0003מארי דמשריין\u0004 וכו' \u0003מליין עיינין, ולגבייהו\u0004 וכו' \u0003משריין מאריהון דאודנין.\u0004 ונודע שבאזנים נתתקנה דרגא עקימא למשמע טב וביש. כנ\"ל (בספרא דצניעותא תקון ז' דז\"ת גלגלתא דז\"א) ודרגא עקימא פירושו אלכסון דהיינו שמלכות ובינה שה\"ס ב' רוחות מערב וצפון נכללו זה בזה ונעשו אלכסון (כמ\"ש לעיל פרשת לך דף ח' ד\"ה ומכח ע\"ש). שה\"ס עירוב ומתוק דמדת הדין במדת הרחמים, וע\"כ שומעים טוב למי שזוכה, דהיינו שמקבלים תפלתו במדת הרחמים שבאלכסון, ושומעים רע למי שלא זכה, שמקבלים תפלתו במדת הדין. וז\"ש, \u0003ואקרון אודנין, בגין דאינון צייתין כל אינון דמצלאן צלותהון\u0004 וכו' כמו שמפרש והולך (עי' באות ק\"מ)."],[2,"ואי ההיא צלותא וכו':","ואם תפלה ההיא נשמעת לאזניו של אדם, אין מי שיקבל אותה למעלה, ושוב אין מקבלים אותה אחרים ממי ששמע אותה תחילה. דהיינו אחרים מאותו האדם. משום זה צריכים להשמר, שלא ישמע התפלה לבני אדם. ועוד, כי דבור התפלה מתאחד בעולם העליון, בז\"א, ודבור דעולם העליון אינו צריך להשמע."],[3,"כגוונא דא מאן וכו':","כעין זה, מי שקורא בספר התורה, אחד קורא, והאחר שותק. ואם שנים קוראים בתורה, גורעים האמונה שלמעלה, משום דקול ודבור אחד הכל אחד, אבל שני קולות ושני דבורים הוא גרעון ופגם באמונה. שהיא המלכות, אלא שיהיה קול ודבור אחד כמו שצריך, כדי שיהיה קול ההוא, ז\"א שנקרא קול, ודבור ההוא, המלכות הנקראת דבור, יהיו אחד."],[3,"","פירוש. שאומר ב' טעמים על מה שהתפלה צריכה להיות בדבור בלי קול, שלא ישמע לאזן אדם. א) כי המלכות, שממנה נמשכים בני האדם, הוא מתוקנת מב' נקודות, שהם ממלכות דמדת הדין, שאינה ראויה לקבל אור, וממלכות המתוקנת בבינה, שהיא מדת הרחמים ואז ראויה לקבל האור. וגם האדם מעורב מב' נקודות אלו. ואם זכה אז המדת הדין בגניזו ומדת הרחמים בגלוי. והוא ראוי לקבל אור העליון. ואם לא זכי נתגלה בו מדת הדין, וכל האורות פורחים ממנו. (כנ\"ל בהקסה\"ז דף קכ\"ד אות קכ\"ג). וע\"כ נתקן אזן העליון בדרגא עקימא, לקבל תפלת אדם צדיק, שזכה שמדת הדין שלו הוא בגניזו, (כנ\"ל אות קל\"ט) כדי שהאזן המקשיב לא יעורר מדת הדין הגנוז בדבורי התפלה. ולפיכך אם אדם אחר שומע התפלה מטרם שתעלה למעלה, הרי אדם ההוא מעורר מדת הדין הגנוז בדבור התפלה. ואז כבר אינה יכולה להשמע למעלה. כי אינה ראויה לקבלת שפע. וז\"ש \u0003ואי ההיא צלותא אשתמע לאודנין דבר נש, לית מאן דציית לה לעילא.\u0004"],[3,"","טעם ב' הוא, כי דבור התפלה היא בחינת מלכות והמתפלל צריך להיות מרכבה לבחינת מלכות, וע\"כ התפלה צריכה לעלות ולהכלל במלכות העליונה הנקראת דבור, ואז המלכות מתייחדת עם ז\"א הנקרא \u0003קול,\u0004 והתפלה מתקבלת, דהיינו שמקבלת השפע מז\"א. ולפיכך אסור לעורר קול של אדם בתפלה, כדי שישרה בה קול העליון, שהוא ז\"א. וז\"ש \u0003ותו, דמלה דצלותא אתאחדא בעלמא עלאה\u0004 שהוא ז\"א. שהדבור עולה למלכות ומתאחד עם ז\"א ע\"י המלכות ומקבל קול ממותק לגמרי מן ז\"א, ואז ראויה התפלה לקבלת השפע וז\"ש \u0003ומלה דעלמא עלאה לא אצטריך למשמע,\u0004 על ידי קול של אדם. כמבואר."],[3,"","וכעין זה הקורא בתורה, צריך להיות מרכבה לז\"א שנקרא תורה, והקול של הקורא הוא במקום הקול של ז\"א, וע\"כ אסור להשמע קול אחר עמו, שהוא קול אדם המעורב במדת הדין. וז\"ש \u0003ואי תרין קראן באורייתא גרעי מהימנותא דלעילא,\u0004 כי קול האדם פוגם את קול הקורא בתורה, והמלכות של מעלה אינה ראויה לקבל שפע מז\"א. וז\"ש, \u0003בגין דיהא ההוא קלא וההוא דבור חד.\u0004 שגורם למעלה שהקול שנקרא ז\"א, והדבור שנקרא מלכות, מזדווגים בזווג אחד. ואם מתחבר עמו קול ודבור של אדם פוגם זווג הזה כמבואר."],[4,"וההוא ממנא שמיה וכו':","וממונה ההוא, שמו עזריאל סבא, וכשהתפלה עולה בחשאי, כל אלו ששים רבוא מחנות וכל אלו בעלי העינים וכל אלו בעלי אזנים, כולם יוצאים ונושקים מלה ההיא של התפלה העולה. ז\"ש, עיני ה' אל צדיקים ואזניו אל שועתם. \u0003עיני ה'\u0004 אל צדיקים, אלו הם בעלי העינים שלמטה, דהיינו המלאכים הנ\"ל שברקיע \u0003היסוד\u0004 דעשיה. משום שיש בעלי עינים למעלה בבחינת ג\"ר, כי עינים הוא חכמה, אבל אלו העינים הן עיני היסוד. וע\"כ כתוב עיני ה' אל צדיקים, כי היסוד נקרא צדיק. \u0003ואזניו\u0004 אל שועתם, אלו הם בעלי האזנים."],[5,"רקיעא תליתאה וכו':","רקיע השלישי, שהוא נצח והוד דעשיה, תפלה ההיא עולה ומגיע לרקיע ההוא. ושם יש ממונה ההוא שנקרא \u0003גדרי\"ה,\u0004 ועמו כמה שרים וכמה ממונים. והוא משמש ג' פעמים ביום, דהיינו בשעת נסיעת ג' קוין למעלה באצילות, כנגד שרביט אחד של אור היוצא, עולה ויורד ואינו עומד על מקום אחד. דהיינו שכונתו להמשיך הארת החכמה שבשמאל, המכונה שרביט של אור. כי המלה מורכבת מן שתים, דהיינו, \u0003שר ביט,\u0004 אשר \u0003שר\u0004 הוא ראיה, מלשון ישר על אנשים (איוב ל\"ג) וכן \u0003ביט\u0004 היא ראיה מלשון הבטה. והארת החכמה נק' ראיה. וזהו השרביט הנוסע ג' פעמים ונגנז. כי אין החכמה נגלית רק בשעת נסיעת ג' קוין בג' דוכתי, חולם, שורק, חירק. (כנ\"ל בשלח ל\"ט ד\"ה וג' ע\"ש) וככלות הנסיעה תיכף נגנזת. וכשהתפלה עולה, שהיא בחינת קו האמצעי הנושאת מסך דחירק, (כנ\"ל אות ק\"ל בסולם ע\"ש) יורד השרביט, שהוא הארת השמאל, ומשתהוה לפני התפלה הזו. דהיינו שמרכין ראשו, שפירושו שמעלים הג\"ר שלו הנק' ראש. כי קו האמצעי ממעט את השמאל מג\"ר ע\"י מסך דחירק. (כנ\"ל לך י\"ג ד\"ה ונתבאר) ורקיע הזה השלישי, שהוא נצח והוד דעשיה, נקרא רקיע השרביט. על שם השרביט הפועל בו."],[6,"וכד סלקא ההיא וכו':","וכשתפלה ההיא עולה, אותו הממונה, אחר שהשתחוה אל התפלה, מאותו הטעם האמור בהשרביט, הכה עם שרביט ההוא בסלע חזק המאיר, שהוא עומד באמצע הרקיע ההוא, ויוצאים מתוך הסלע שע\"ה חילות, שהיו גנוזים שם מיום שירדה התורה לארץ, משום שהתעקשו למאן ולעכב שלא תרד התורה לארץ, וגער בהם הקב\"ה, ונכנסו תוך סלע ההוא. ואינם יוצאים משם חוץ מבאותו הזמן שהתפלה עולה למעלה. אז פותחים ואומרים ה' אדוננו מה \u0003אדיר\u0004 שמך וגו'. זו היא התפלה, שנקראת \u0003אדיר,\u0004 משום שהיא עולה על כל אלו הרקיעים. אז, הם משתחוים לה."],[6,"","פירוש. אלו המלאכים, שקטרגו על התורה, שה\"ס קו אמצעי, שלא תמשך לארץ, שה\"ס המלכות, ולעולמות בי\"ע, היו נמשכים מקו השמאל. ורצו שבמלכות ובבי\"ע תהיה השליטה לשמאל, ולא לקו אמצעי שנקרא תורה, שהוא ממעט הג\"ר מהארת השמאל. וז\"ש, \u0003דאתתקפו לסרבא דלא תחות לארעא,\u0004 דהיינו למלכות שנקרא ארץ, הכוללת כל בי\"ע, אבל, \u0003ואנזיף בהו הקב\"ה,\u0004 שהקב\"ה שה\"ס קו אמצעי גער בהם והכריחם לקבל את הארת קו האמצעי, ולהתעלם. \u0003ואז ועאלו גו ההוא טנרא,\u0004 דהיינו שנתעלמו בתוך סלע ההוא, שה\"ס כח הדין שבקו האמצעי, וז\"ש \u0003בטנרא תקיפא דזהיר, דאיהו קאים באמצעיתא דההוא רקיעא\u0004 כח הדין נקרא \u0003טנרא תקיפא,\u0004 שהוא עומד באמצע הרקיע, היינו קו האמצעי."],[6,"","וז\"ש, \u0003ולא נפקין בר ההוא זמנא דצלותא סלקא.\u0004 כי אין התפלה עולה אלא בהתעוררות קו השמאל, שהיא בינה ותו\"מ שנפלו לתחתון וחזרו למעלה מרקיע ונעשו קו שמאל, שהם לוקחים עמהם גם התפלה שהיתה דבוקה בהם בעת נפילתם (כנ\"ל באות קל\"א בהסולם באורך) וע\"כ מקבל הממונה אז את השרביט שהוא הארת השמאל. הרי שבעת עלית התפלה יוצא הארת השמאל לשליטתו. וז\"ש, \u0003בטש בההוא שרביטא בטינרא תקיפא\u0004 וכו' \u0003ונפקי מגו ההוא טנרא שע\"ה חיילין,\u0004 שאז הם מתעוררים ומקבלים הארת השמאל, מן השרביט, וז\"ש, \u0003פתחי ואמרי ה' אדוננו מה אדיר\u0004 וכו', שהתפלה העולה על הרקיעים היא \u0003אדירה,\u0004 משום שכוללת בתוכה המסך דחירק דקו אמצעי, הממעט בכח את קו השמאל, מג\"ר. (כנ\"ל באות קל\"א בסולם) וע\"כ, \u0003כדין סגדין לגבה,\u0004 דהיינו שמרכינים ראשם, שה\"ס שאינם ממשיכים מן הג\"ר דהארת החכמה, אלא מהו\"ק בלבד. ונקראים \u0003שע\"ה\u0004 חילות, שהסו\"ה ואל קין ומנחתו לא \u0003שעה.\u0004 כי מנחתו היתה מבחינת שע\"ה חילות הללו, שגער בהם הקב\"ה ונעלמו בסלע, ונפלו פניהם. וע\"כ גם קין נפלו פניו."],[7,"מכאן ולהלאה צלותא וכו':","מכאן ולהלאה מתעטרת התפלה בעטרות עליונות ועולה \u0003לרקיע הרביעי,\u0004 שהוא תפארת. ואז יוצא השמש שהוא ת\"ת במדרגותיו, \u0003ושמשיאל\u0004 ממונה העליון יוצא, ושס\"ה מחנות עולים עמו לתוך הרקיע ההוא, ונקראים, ימות החמה. משום שהם מדרגות נמשכות מן החמה, שהוא ת\"ת. וכולם מעטרים את התפלה בעטרות בשמים של גן העדן."],[8,"ותמן אתעכבת צלותא וכו':","ושם מתעכבת התפלה, כדי להדבק באויר דגבורה בהמדרגות אשר שם, כי ברקיעים הקודמים, נה\"י לא היתה צריכה להתעכב כל כך מפני שהם נכללים בת\"ת (כנ\"ל באות קל\"א בסולם) עד שכל המחנות עולים עמה \u0003לרקיע החמישי,\u0004 שהוא גבורה, ושם ממונה אחד ששמו \u0003גדריאל,\u0004 והוא בעל מלחמות של שאר העמים, כי הגבורה ה\"ס קו שמאל שהעמים נאחזים בו. וכשהתפלה עולה, שנושאת בתוכה המסך דקו אמצעי, הממעט את קו השמאל, מג\"ר כנ\"ל, אז נזדעזע הוא וכל המחנות שלו, ונשבר כחם, ויוצאים ומשתחוים, דהיינו שמרכינים ראשם, שהוא הג\"ר שלהם, ומעטרים לתפלה ההיא."]],[[0,"","(ברקיע השני עולה התפלה עד אותו רקיע, ונפתחים) וּכְשֶׁעוֹלָה הַתְּפִלָּה עַד לְאוֹתוֹ רָקִיעַ, נִפְתָּחִים שְׁנֵים עָשָׂר שַׁעֲרֵי אוֹתוֹ הָרָקִיעַ, וּבְאוֹתוֹ הַשַּׁעַר הַשְּׁנֵים עָשָׂר עוֹמֵד מְמֻנֶּה אֶחָד שֶׁשְּׁמוֹ עָנָאֵ\"ל, וְזֶה מְמֻנֶּה עַל כַּמָּה חֲיָלוֹת, עַל כַּמָּה מַחֲנוֹת, וּכְשֶׁתְּפִלָּה עוֹלָה, עוֹמֵד הַמְמֻנֶּה הַזֶּה וּמַכְרִיז עַל כָּל אוֹתָם פְּתָחִים וְאוֹמֵר: (ישעיה כו) פִּתְחוּ שְׁעָרִים וְגוֹ', וְכָל הַשְּׁעָרִים נִפְתָּחִים, וְנִכְנֶסֶת הַתְּפִלָּה לְכָל אוֹתָם הַפְּתָחִים."],[1,"","וְאָז מִתְעוֹרֵר מְמֻנֶּה אֶחָד זָקֵן לְיָמִים שֶׁעוֹמֵד לְצַד דָּרוֹם, שֶׁשְּׁמוֹ עַזְרִיאֵ\"ל הַזָּקֵן, וְלִפְעָמִים הוּא נִקְרָא מַחֲנִיאֵ\"ל, מִשּׁוּם שֶׁהִתְמַנָּה עַל שִׁשִּׁים רִבּוֹא מַחֲנוֹת, וְכֻלָּם בַּעֲלֵי כְנָפַיִם, בַּעֲלֵי מַחֲנוֹת, מְלֵאִים עֵינַיִם. וְאֶצְלָם עוֹמְדִים אוֹתָם מַחֲנוֹת בַּעֲלֵי אָזְנַיִם. וְנִקְרָאִים אָזְנַיִם, מִשּׁוּם שֶׁהֵם מַקְשִׁיבִים לְכָל אוֹתָם שֶׁמִּתְפַּלְלִים תְּפִלָּתָם בְּלַחַשׁ וּבִרְצוֹן הַלֵּב, שֶׁלֹּא נִשְׁמַעַת אוֹתָהּ תְּפִלָּה לְאַחֵר. הַתְּפִלָּה הַזּוֹ עוֹלָה, וּמַקְשִׁיבִים לָהּ כָּל אוֹתָם שֶׁנִּקְרָאִים בַּעֲלֵי אָזְנַיִם."],[2,"","וְאִם אוֹתָהּ תְּפִלָּה נִשְׁמַעַת לְאָזְנֵי אָדָם, אֵין מִי שֶׁמַּקְשִׁיב לָהּ לְמַעְלָה, וְלֹא מַקְשִׁיבִים לָהּ אֲחֵרִים, פְּרָט לְמִי שֶׁשּׁוֹמֵעַ בָּרִאשׁוֹנָה. מִשּׁוּם כָּךְ צָרִיךְ לְהִשָּׁמֵר שֶׁלֹּא יִשְׁמְעוּ אֶת אוֹתָהּ תְּפִלָּה בְּנֵי אָדָם. וְעוֹד, שֶׁדִּבּוּר שֶׁל תְּפִלָּה נֶאֱחָז בָּעוֹלָם הָעֶלְיוֹן, וְדָבָר שֶׁל הָעוֹלָם הָעֶלְיוֹן אֵין צָרִיךְ לִשְׁמֹעַ."],[3,"","כְּמוֹ זֶה מִי שֶׁקּוֹרֵא בְּסֵפֶר תּוֹרָה, אֶחָד קוֹרֵא וְאֶחָד לִשְׁתֹּק. וְאִם שְׁנַיִם קוֹרְאִים בַּתּוֹרָה, הֵם גּוֹרְעִים בָּאֱמוּנָה שֶׁלְּמַעְלָה, מִשּׁוּם שֶׁאֶחָד קוֹל וְאֶחָד דִּבּוּר הַכֹּל אֶחָד, אָז שְׁנֵי קוֹלוֹת וּשְׁנֵי דִבּוּרִים זוֹ גְרִיעוּת הָאֱמוּנָה. אֶלָּא שֶׁיִּהְיֶה קוֹל וְדִבּוּר אֶחָד כְּמוֹ שֶׁצָּרִיךְ, כְּדֵי שֶׁיִּהְיֶה אוֹתוֹ קוֹל וְאוֹתוֹ דִבּוּר אֶחָד."],[4,"","וְאוֹתוֹ הַמְמֻנֶּה שֶׁשְּׁמוֹ עַזְרִיאֵ\"ל הַזָּקֵן, כְּשֶׁאוֹתָהּ תְּפִלָּה עוֹלָה בְּלַחַשׁ, כָּל אוֹתָן שִׁשִּׁים רִבּוֹא מַחֲנוֹת, וְכָל אוֹתָם בַּעֲלֵי עֵינַיִם, וְכָל אוֹתָם בַּעֲלֵי אָזְנַיִם, כֻּלָּם יוֹצְאִים וְנוֹשְׁקִים אוֹתוֹ דִבּוּר שֶׁל תְּפִלָּהה שֶׁעוֹלֶה. זֶהוּ שֶׁכָּתוּב (תהלים לד) עֵינֵי ה' אֶל צַדִּיקִים וְאָזְנָיו אֶל שַׁוְעָתָם. עֵינֵי ה' אֶל צַדִּיקִים - אֵלּוּ בַּעֲלֵי הָעֵינַיִם שֶׁלְּמַטָּה, מִשּׁוּם שֶׁיֵּשׁ (שאין) בַּעֲלֵי עֵינַיִם שֶׁלְּמַעְלָה. וְאָזְנָיו אֶל שַׁוִעָתָם - אֵלֶּה בַּעֲלֵי הָאָזְנַיִם."],[5,"","הָרָקִֹיעַ הַשְּׁלִישִׁי, אוֹתָהּ תְּפִלָּה עוֹלָה וּמַגִּיעָה לְאוֹתוֹ רָקִיעַ, וְשָׁם אוֹתוֹ אוֹתוֹ שֶׁנִּקְרָא גְּדַרְיָ\"ה, וְעִמּוֹ כַּמָּה שָׂרִים וְכַמָּה מְמֻנִּים, וְהוּא מְשַׁמֵּשׁ שָׁלֹשׁ פְּעָמִים בְּיוֹם כְּנֶגֶד שַׁרְבִיט אֶחָד שֶׁל זֹהַר שֶׁיּוֹצֵא, עוֹלֶה וְיוֹרֵד, וְלֹא עוֹמֵד בְּמָקוֹם אֶחָד, וְזֶהוּ שַׁרְבִיט שֶׁנּוֹסֵעַ שָׁלֹשׁ פְּעָמִים וְנִגְנָז. וּכְשֶׁתְּפִלָּה עוֹלָה, יוֹרֵד אוֹתוֹ שַׁרְבִיט וּמִשְׁתַּחֲוֶה לִפְנֵי אוֹתָהּ תְּפִלָּה, וְהָרָקִיעַ הַזֶּה נִקְרָא רְקִיעַ הַשַּׁרְבִיט."],[6,"","וּכְשֶׁעוֹלָה אוֹתָהּ תְּפִלָּה, אוֹתוֹ הַמְמֻנֶּה לְאַחַר שֶׁהִשְׁתַּחֲוָה, מַכֶּה בְּאוֹתוֹ הַשַּׁרְבִיט בַּסֶּלַע הֶחָזָק שֶׁמֵּאִיר וְעוֹמֵד בְּאֶמְצַע הָרָקִיעַ, וְיוֹצְאִים מִתּוֹךְ אוֹתוֹ סֶלַע שְׁלֹשׁ מֵאוֹת וְשִׁבְעִים וַחֲמִשָּׁה חֲיָלוֹת שֶׁגְּנוּזִים שָׁם מִיּוֹם שֶׁיָּרְדָה תוֹרָה לָאָרֶץ, מִשּׁוּם שֶׁהִתְחַזְּקוּ לְהִתְחַבֵּר (לסרב) שֶׁלֹּא תֵרֵד לָאָרֶץ, וְנָזַף בָּהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא, וְנִכְנְסוּ לְתוֹךְ אוֹתוֹ סֶלַע, וְאֵינָם יוֹצְאִים, פְּרָט לְאוֹתוֹ זְמַן שֶׁהַתְּפִלָּה עוֹלָה, פּוֹתְחִים וְאוֹמְרִים: (שם ח) ה' אֲדנֵינוּ מָה אַדִּיר שִׁמְךְ וְגוֹ'. זוֹהִי תְפִלָּה שֶׁעוֹלָה עַל כָּל אוֹתָם רְקִיעִים. אָז מִשְׁתַּחֲוִים אֵלֶיהָ."],[7,"","מִכָּאן וָהָלְאָה, הַתְּפִלָּה מִתְעַטֶּרֶת בַּעֲטָרוֹת עֶלְיוֹנוֹת, וְעוֹלָה לְתוֹךְ הָרָקִיעַ הָרְבִיעִי, וְאָז הַשֶּׁמֶשׁ יוֹצֵא בְּדַרְגוֹתָיו, וְשַׁמְשִׁיאֵ\"ל הַמְמֻנֶּה הַגָּדוֹל יוֹצֵא, וּשְׁלֹשׁ מֵאוֹת וְשִׁשִּׁים וַחֲמִשָּׁה מַחֲנוֹת עִמּוֹ, לְתוֹךְ אוֹתוֹ רָקִיעַ, וְהֵם נִקְרָאִים יְמוֹת הַחַמָּה, וְכֻלָּם מְעַטְּרִים אֶת אוֹתָהּ תְּפִלָּה בַּעֲטָרוֹת שֶׁל בְּשָׂמִים שֶׁל גַּן עֵדֶן."],[8,"","וְשָׁם מִתְעַכֶּבֶת הַתְּפִלָּה, עַד שֶׁכָּל הַמַּחֲנוֹת עוֹלִים עִמּוֹ לְתוֹךְ אוֹתוֹ הָרָקִיעַ הַחֲמִישִׁי, וְשָׁם נִמְצָא מְמֻנֶּה אֶחָד שֶׁשְּׁמוֹ גַּדְרִיאֵ\"ל, וְהוּא בַּעַל הַקְּרָבוֹת שֶׁל שְׁאָר הָעַמִּים. וּכְשֶׁתְּפִלָּה עוֹלָה, אָז הוּא מִזְדַּעֲזֵעַ עִם כָּל מַחֲנוֹתָיו, וְנִשְׁבָּר כֹּחָם, וְיוֹצְאִים וּמִשְׁתַּחֲוִים וּמְעַטְּרִים אֶת אוֹתָהּ הַתְּפִלָּה."]]],[["וְסַלְּקִין עִמָּהּ עַד דְּמָטוּ לְגַבֵּי רְקִיעָא שְׁתִּיתָאָה, וּכְדֵין נָפְקִין כַּמָה חַיָּילִין, וְכַמָּה מַשִׁרְיָין, וּמְקַבְּלִין לְהַהוּא צְלוֹתָא, וְסַלְּקִין בַּהֲדָהּ, עַד דְּמָטוּ לְשִׁבְעִין תַּרְעִין, דְּתַמָּן קָאִים חַד מְמָנָא, דִּי שְׁמֵיהּ עַנְפִי\"אֵל, רַב מְמָנָא. וְאִיהוּ מְעַטֵּר לְהַהִיא צְלוֹתָא, בְּשִׁבְעִין עִטְרִין.","וְכֵיוָן דְּמִתְעַטְּרָא צְלוֹתָא בְּכָל הָנֵי עִטְרִין, כְּדֵין מִתְחַבְּרָן כָּל אִינּוּן חַיָּילִין דְּכֻלְּהוּ רְקִיעִין, וְסַלְּקִין לְהַהִיא צְלוֹתָא דְּמִתְעַטְּרָא בְּכָל עִטְרִין, לְגַבֵּי רְקִיעָא שְׁבִיעָאָה. וּכְדֵין עָאלַת צְלוֹתָא, וְסַנְדַּלְפֹ\"ן רַב יַקִּירָא עִלָּאָה דְּכָל מַפְתְּחָן דְּמָארֵיהּ בִּידֵיהּ, אָעִיל לְהַהוּא צְלוֹתָא, לְגוֹ שִׁבְעָה הֵיכָלִין.","תָּא חֲזֵי אָמַר רַבִּי שִׁמְעוֹן שִׁבְעָא מְדוֹרִין אִינוּן וכו', (אמרו המגיהים כבר נדפסו בפרשת בראשית דף מ\"א ע\"ש) שִׁבְעָה הֵיכָלִין אִלֵּין, אִינּוּן הֵיכָלִין דְּמַלְכָּא, וְהַאי צְלוֹתָא כַּד מִתְעַטְּרָא בְּכָל הָנִי עִטְרִין, כַּד עָאלַת, מְחַבָּר לוֹן כַּחֲדָא, לְאִתְעַטְרָא לְעֵילָּא לְמֶהוֵי כֹּלָּא חַד כְּדְקָא יֵאוֹת. וּשְׁמָא דְּקוּדְשָׁא בְּרִיךְ הוּא, מִתְעַטְּרָא בְּכָל עִטְרִין, עֵילָּא וְתַתָּא, לְמֶהוֵי חַד, וּכְדֵין (משלי י׳:ו׳) בְּרָכוֹת לְרֹאשׁ (בראשית כ\"ו ע\"א) צַדִּיק כְּתִיב.","זַכָּאָה חוּלָקֵיהּ דְּבַר נָשׁ, דְּיָדַע לְסַדְּרָא צְלוֹתֵיהּ כְּדְקָא יֵאוֹת. בְּהַאי צְלוֹתָא דְּמִתְעַטְּרָא בֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא, אִיהוּ מְחַכֶּה עַד דְּיִסְתַּיְּימוּן כָּל צְלוֹתְהוֹן דְּיִשְׂרָאֵל, וּכְדֵין כֹּלָּא אִיהוּ בִּשְׁלִימוּ כְּדְקָא יֵאוֹת, עֵילָּא וְתַתָּא. עַד הָכָא מִלִּין דִּצְלוֹתָא, לְמִנְדַּע רָזִין עִלָּאִין, מִכָּאן וּלְהָלְאָה אִית פִּקּוּדֵי אוֹרַיְיתָא, דְּאִינּוּן קַיְּימִין בְּמִלָּה, כְּמָה דְּקַיְימִין בְּעוֹבָדָא.","וְאִינּוּן שִׁית פִּקוּדִין, וְקַיְימִין אוּף הָכָא בִּצְלוֹתָא. חַד, (דברים כ״ח:נ״ח) לְיִרְאָה אֶת הַשֵּׁם הַנִּכְבָּד וְהַנּוֹרָא. תִּנְיָינָא, לְאַהֲבָה אוֹתוֹ. תְּלִיתָאָה, לְבָרְכוֹ. רְבִיעָאָה, לְיַחֲדוֹ. חֲמִישָׁאָה, לְבָרֵךְ כַּהֲנָא יַת עַמָּא. שְׁתִיתָאָה, לִמְסוֹר נִשְׁמָתֵיהּ לֵיהּ. וְאִלֵּין שִׁית פִּקוּדִין דְּקַיְימִין בִּצְלוֹתָא דְּמִלָּה, בַּר אִינּוּן פִּקוּדִין (רי\"ו ע\"א) דְּקַיְימִין בְּעוֹבָדָא, כְּגַוְונָא דְּצִיצִית וּתְפִלִין.","לְיִרְאָה אֶת הַשֵּׁם, פִּקּוּדָא דָּא קַיְּימָא בְּאִלֵּין תּוּשְׁבְּחָן דְּקָאָמַר דָּוִד מַלְכָּא, וּבְאִינּוּן קָרְבָּנִין דְּאוֹרַיְיתָא, דְּתַמָּן בָּעֵי בַּר נָשׁ לְדַחֲלָא מִקַּמֵּי מָארֵיהּ, בְּגִין דְּאִינּוּן שִׁירִין קַיְּימִין בְּהַהוּא אֲתָר דְּאִקְרֵי יִרְאָה. וְכָל אִינּוּן הַלְלוּיָהּ, דְּאִינּוּן רָזָא דְּיִרְאָה דְּקוּדְשָׁא בְּרִיךְ הוּא. וּבָעֵי בַּר נָשׁ לְשַׁוָּאָה רְעוּתֵיהּ בְּאִינּוּן שִׁירִין בְּיִרְאָה, וְאוּקְמוּהָ חַבְרַיָּיא כָּל אִינּוּן רָזִין דְּשִׁירִין וְתוּשְׁבְּחָן, וְכָל אִינּוּן רָזִין דְּהַלְלוּיָהּ.","כֵּיוָן דְּמָטֵי בַּר נָשׁ לְיִשְׁתַּבַּח, יְשַׁוֵּי רְעוּתֵיהּ לְבָרְכָא לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, כְּגוֹן יוֹצֵר אוֹר, יוֹצֵר הַמְּאוֹרוֹת. לְאַהֲבָה אוֹתוֹ, כַּד מָטֵי לְאַהֲבַת עוֹלָם, (דברים ו׳:ה׳) וְאָהַבְתָּ אֶת יְיָ' אֱלֹהֶיךָ, דְּדָא אִיהוּ רָזָא דִּרְחִימוּ דְּקוּדְשָׁא בְּרִיךְ הוּא, וְהָא אוּקְמוּהָ. לְיַחֲדָא לֵיהּ, שְׁמַע יִשְׂרָאֵל יְיָ' אֱלהֵינוּ יְיָ' אֶחָד, דְּהָכָא קַיְּימָא רָזָא דְּיִחוּדָא דְּקוּדְשָׁא בְּרִיךְ הוּא, לְיַחֲדָא שְׁמֵיהּ בִּרְעוּתָא דְּלִבָּא כַּדְקָא חֲזֵי. וּמִתַּמָּן וּלְהָלְאָה אַדְכָּרוּתָא דִּיצִיאַת מִצְרַיִם, דְּאִיהוּ פִּקּוּדָא לְאַדְכְּרָא יְצִיאַת מִצְרַיִם דִּכְתִּיב, (דברים ה׳:ט״ו) וְזָכַרְתָּ כִּי עֶבֶד הָיִיתָ בְּאֶרֶץ מִצְרָיִם.","לְבָרְכָא כַּהֲנָא יַת עַמָּא, בְּגִין לְאַכְלְלָא יִשְׂרָאֵל כַּחֲדָא, בְּשַׁעֲתָא דְּנַטְלִין בִּרְכָאן לְעֵילָּא, דְּהָא בְּהַהִיא שַׁעֲתָא נַטְלָא כְּנֶסֶת יִשְׂרָאֵל בִּרְכָאן, וְשַׁעֲתָא דִּרְעוּתָא הוּא, לִמְסוֹר נַפְשֵׁיהּ לְגַבֵּיהּ, וּלְמֵיהַב לֵיהּ נִשְׁמְתָא בִּרְעוּתָא דְּלִבָּא, כַּד נַפְלִין עַל אַנְפִּין, וְאָמְרִין (תהילים כ״ה:א׳) אֵלֶיךָ יְיָ' נַפְשִׁי אֶשָּׂא, דִּיכַוֵּין לִבֵּיהּ וּרְעוּתֵיהּ לְגַבֵּיהּ, לְמִמְסַר לֵיהּ נַפְשָׁא בִּרְעוּתָא שְׁלִים. וְאִלֵּין אִינּוּן שִׁית פִּקוּדִין דְּקַיְימִין בִּצְלוֹתָא, דְּסַלְּקִין לְגַבֵּי שִׁית מֵאָה פִּקוּדִין דְּאוֹרַיְיתָא.","וְאִי תֵּימָא תְּלֵיסָר אַחֲרָנִין יַתִּיר. אִינּוּן קַיְּימִין לְאַמְשָׁכָא תְּלֵיסָר מְכִילָן דְּרַחֲמֵי, דְּכֹלָּא כְּלִילָן בְּהוּ. (ס\"א בהני) שִׁית פִּקוּדִין אִלֵּין, דִּצְלוֹתָא מִתְעַטְּרָא בְּהוּ."],[[0,"וסלקין עמה עד וכו':","ועולים עמה עד שמגיעים \u0003לרקיע הששי,\u0004 שהוא החסד, אז יוצאים כמה צבאות וכמה מחנות ומקבלים את התפלה ההיא עד שמגיעים לשבעים שערים, שהם חג\"ת נהי\"מ שכל אחת כלולה מעשר. כי החסד כולל כל ז\"ס תחתונות. ששם עומד ממונה אחד ושמו \u0003ענפיאל\u0004 ממונה העליון, והוא מעטר התפלה בשבעים עטרות."],[1,"וכיון דמתעטרא צלותא וכו':","וכיון שהתפלה מתעטרת בכל אלו העטרות, אז מתחברים כל אלו חיילים של כל הרקיעים שליוו את התפלה עד כאן, מרקיע לרקיע, ומעלים את התפלה \u0003לרקיע השביעי\u0004 שהוא בינה הכוללת ג\"ר. ואז נכנסת התפלה שמה. וסנדלפון, שר היקר העליון, שכל מפתחות אדוניו בידו מכניס את התפלה לשבעה היכלות דיצירה. (וכבר נתבאר זה באות קל\"א בהסולם ע\"ש). (חסר כאן המדורים וההיכלות, שכבר נדפסו בפרשת בראשית ב' בתחלתו.)."],[2,"שבעה היכלין אלין וכו':","ז' היכלות אלו הם היכלות של המלך, דהיינו ז' היכלות דמלכות דאצילות ששם מזדווג המלך שהוא ז\"א. ותפלה ההיא, כשמתעטרת בכל אלו העטרות, כשעולה שמה, מחברת ז\"א ומלכות ביחד, להתעטר למעלה, להיות הכל אחד כראוי, והשם של הקב\"ה שהוא המלכות, יתעטר מכל הצדדים למעלה ולמטה להיות אחד עם ז\"א. ואז, ברכות לראש צדיק, כתוב, שהיסוד שנקרא צדיק משפיע ברכות בהמלכות."],[3,"זכאה חולקיה דבר נש וכו':","אשרי חלקו של אדם שיודע לסדר תפלתו כראוי בתפלה זו שהיא כראוי. שמתעטר בה הקב\"ה, הוא מחכה עד שיגמרו כל תפלות ישראל לעלות, ונכללות בתפלה השלמה, ואז הכל הוא בשלמות כראוי למעלה ולמטה. עד כאן הם עניני התפלה לדעת סודות עליונים שבה. מכאן ולהלאה, יש מצות התורה התלויות בדבור, כמו שיש אחרות התלויות במעשה."],[4,"ואינון שית פקודין וכו':","והם שש מצות, ונוהגים גם כאן בתפלה, א) ליראה את השם הנכבד והנורא. ב) לאהבה אותו. ג) לברכו. ד) ליחדו. ה) שיברך הכהן את העם. ו) למסור נשמתו לו. ואלו שש מצות הנוהגות בתפלה הן תלויות בדבור, חוץ מאלו המצות התלויות במעשה, כמו ציצית ותפלין."],[5,"ליראה את השם:","ומפרש שש מצות הנ\"ל, א) מצוה זו נוהגת באלו התשבחות שאמר דוד המלך, ובקרבנות שבתורה, ששם צריך האדם לירא מפני אדונו. משום ששירים ההם עומדים במקום ההוא שנקרא יראה. שהיא המלכות. וכל אלו הללויה שכתוב, הם סוד יראת הקב\"ה, שהיא המלכות, וצריך האדם לשום רצונו בשירים אלו, ביראה. וכבר העמידו החברים כל אלו הסודות של שירות ותשבחות, וכל אלו הסודות של הללויה."],[6,"כיון דמטי ב\"נ וכו':","ב) כיון שהגיע האדם לישתבח, ישים רצונו לברך אל הקב\"ה, כמו יוצר אור יוצר המאורות. ג) לאהבה אותו, היינו כשמגיע לאהבת עולם, ואל, ואהבת את ה' אלקיך. שזה סוד אהבת הקב\"ה. ד) ליחד אותו, היינו שמע ישראל ה' אלקינו ה' אחד. שכאן נמצא סוד היחוד של הקב\"ה, ליחד שמו ברצון הלב כראוי. ומשם ולהלאה, זכרון של יציאת מצרים, שהיא מצוה להזכיר יציאת מצרים, שכתוב, וזכרת כי עבד היית בארץ מצרים."],[7,"לברכא כהנא ית וכו':","ה) שיברך הכהן את העם, הוא, כדי לכלול ישראל יחד בשעה שלוקחים ברכות שלמעלה, כי באותה שעה מקבלת כנסת ישראל, שהיא המלכות, ברכות. ו) ושעת רצון היא למסור לו נפשו ולתת לו הנשמה ברצון הלב, כשנופלים על פניהם ואומרים, אליך ה' נפשי אשא, שיכוין אליו לבו ורצונו למסור לו הנפש ברצון שלם. ואלו הן שש מצוות העומדות בתפלה העולות כנגד שש מאות מצות התורה."],[8,"ואי תימא תליסר וכו':","ואם תאמר, שי\"ג אחרות יותר יש בתורה, כי יש תרי\"ג מצות, ולמה אומר ששש מצות הם כנגד שש מאות. ומשיב, י\"ג מצות אלו עומדים להמשיך י\"ג מדות הרחמים שהכל כלולים בהם. כלומר, שי\"ג מדות הרחמים שאנו אומרים הן כנגדם. ושש מצות אלו הם שהתפלה מתעטרת בהם, דהיינו כנגד חג\"ת נה\"י, שהתפלה שה\"ס המלכות מקבלת מז\"א."]],[[0,"","וְעוֹלִים עִמָּהּ עַד שֶׁמַּגִּיעִים לָרָקִיעַ הַשִּׁשִּׁי, וְאָז יוֹצְאִים כַּמָּה חֲיָלוֹת וְכַמָּה מַחֲנוֹת וּמְקַבְּלִים אֶת אוֹתָהּ תְּפִלָּה, וְעוֹלִים עִמָּהּ עַד שֶׁמַּגִּיעִים לְשִׁבְעִים שְׁעָרִים, שֶׁשָּׁם עוֹמֵד מְמֻנֶּה אֶחָד שֶׁשְּׁמוֹ עַנְפִיאֵ\"ל, מְמֻנֶּה גָּדוֹל, וְהוּא מְעַטֵּר אֶת אוֹתָהּ תְּפִלָּה בְּשִׁבְעִים עֲטָרוֹת."],[1,"","וְכֵיוָן שֶׁהַתְּפִלָּה מִתְעַטֶּרֶת בְּכָל הָעֲטָרוֹת הַלָּלוּ, אֲזַי מִתְחַבְּרִים כָּל אוֹתָם הַחֲיָלוֹת שֶׁל כָּל הָרְקִיעִים, וּמַעֲלִים אֶת אוֹתָהּ הַתְּפִלָּה שֶׁמִּתְעַטֶּרֶת בְּכָל הָעֲטָרוֹת לָרָקִיעַ הַשְּׁבִיעִי, וְאָז נִכְנֶסֶת הַתְּפִלָּה, וְסַנְדַּלְפוֹ\"ן נִכְבָּד גָּדוֹל, שֶׁכָּל מַפְתְּחוֹת אֲדוֹנָיו בְּיָדוֹ, מַכְנִיס אֶת אוֹתָהּ תְּפִלָּה לְתוֹךְ שִׁבְעָה הֵיכָלוֹת."],[2,"","בֹא וּרְאֶה אָמַר רַבִּי שִׁמְעוֹן שִׁבְעָה מְדוֹרִים הֵם וכו'. שִׁבְעַת הַהֵיכָלוֹת הַלָּלוּ הֵם הֵיכְלוֹת הַמֶּלֶךְ, וּכְשֶׁהַתְּפִלָּה הַזּוֹ מִתְעַטֶּרֶת בְּכָל הָעֲטָרוֹת הַלָּלוּ כְּשֶׁנִּכְנֶסֶת, מְחַבֵּר אוֹתָם כְּאֶחָד, לְהִתְעַטֵּר לְמַעְלָה לִהְיוֹת הַכֹּל אֶחָד כָּרָאוּי. וּשְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא מִתְעַטֵּר בְּכָל הָעֲטָרוֹת, מַעְלָה וּמַטָּה, לִהְיוֹת אֶחָד, וְאָז כָּתוּב בְּרָכוֹת לְרֹאשׁ צַדִּיק."],[3,"","אַשְׁרֵי חֶלְקוֹ שֶׁל אָדָם שֶׁיּוֹדֵעַ לְסַדֵּר תְּפִלָּתוֹ כָּרָאוּי. בַּתְּפִלָּה הַזּוֹ שֶׁמִּתְעַטֵּר בָּהּ הַקָּדוֹשׁ בָּרוּךְ הוּא, הוּא מְחַכֶּה עַד שֶׁיִּסְתַּיְּמוּ כָּל תְּפִלּוֹתֵיהֶם שֶׁל יִשְׂרָאֵל, וְאָז הַכֹּל הוּא בִּשְׁלֵמוּת כָּרָאוּי מַעְלָה וּמַטָּה. עַד כָּאן דִּבְרֵי הַתְּפִלָּה לָדַעַת סוֹדוֹת עֶלְיוֹנִים. מִכָּאן וָהָלְאָה יֵשׁ אֶת מִצְווֹת הַתּוֹרָה, שֶׁהֵן עוֹמְדוֹת בְּדִבּוּר כְּמוֹ שֶׁעוֹמְדוֹת בְּמַעֲשֶׂה."],[4,"","וְהֵן שֵׁשׁ מִצְווֹת, וְעוֹמְדוֹת אַף כָּאן בַּתְּפִלָּה. אַחַת - לְיִרְאָה אֶת הַשֵּׁם הַנִּכְבָּד וְהַנּוֹרָא. שְׁתַּיִם - לְאַהֲבָה אוֹתוֹ. שְׁלִישִׁית - לְבָרְכוֹ. רְבִיעִית - לְיַחֲדוֹ. חֲמִישִׁית - שֶׁיְּבָרֵךְ הַכֹּהֵן אֶת הָעָם. שִׁשִּׁית - לִמְסֹר לוֹ אֶת נִשְׁמָתוֹ. וְאֵלּוּ שֵׁשׁ מִצְווֹת שֶׁעוֹמְדוֹת בִּתְפִלָּה שֶׁל דִּבּוּר, פְּרָט לְאוֹתָן מִצְווֹת שֶׁעוֹמְדוֹת בְּמַעֲשֶׂה, כְּמוֹ צִיצִית וּתְפִלִּין."],[5,"","לְיִרְאָה אֶת ה' - מִצְוָה זוֹ עוֹמֶדֶת בַּתִּשְׁבָּחוֹת הַלָּלוּ שֶׁאָמַר דָּוִד הַמֶּלֶךְ וּבְאוֹתָם קָרְבָּנוֹת שֶׁל הַתּוֹרָה, שֶׁשָּׁם צָרִיךְ אָדָם לִפְחֹד מִלִּפְנֵי אֲדוֹנוֹ, מִשּׁוּם שֶׁאוֹתָן שִׁירוֹת עוֹמְדוֹת בְּאוֹתוֹ מָקוֹם שֶׁנִּקְרָא יִרְאָה, וְכָל אוֹתָם הַלְלוּיָהּ שֶׁהֵם סוֹד שֶׁל יִרְאַת הַקָּדוֹשׁ בָּרוּךְ הוּא. וְצָרִיךְ אָדָם לָשִׂים רְצוֹנוֹ בְּאוֹתָן שִׁירוֹת בְּיִרְאָה, וּפֵרְשׁוּהָ הַחֲבֵרִים, כָּל אוֹתָם הַסּוֹדוֹת שֶׁל שִׁירוֹת וְתִשְׁבָּחוֹת וְכָל אוֹתָם סוֹדוֹת שֶׁל הַלְלוּיָהּ."],[6,"","כֵּיוָן שֶׁמַּגִּיעַ אָדָם לְיִשְׁתַּבַּח, יָשִׂים רְצוֹנוֹ לְבָרֵךְ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ יוֹצֵר אוֹר, יוֹצֵר הַמְּאוֹרוֹת, לְאַהֲבָה אוֹתוֹ, כְּשֶׁמַּגִּיעַ לְאַהֲבַת עוֹלָם, וְאָהַבְתָּ אֵת ה' אֱלֹהֶיךְ (דברים ו), שֶׁזֶּהוּ סוֹד שֶׁל אַהֲבַת הַקָּדוֹשׁ בָּרוּךְ הוּא, וַהֲרֵי פֵּרְשׁוּהָ. לְיַחֲדוֹ - שְׁמַע יִשְׂרָאֵל ה' אֱלֹהֵינוּ ה' אֶחָד, שֶׁכָּאן עוֹמֵד סוֹד הַיִּחוּד שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, לְיַחֵד אֶת שְׁמוֹ בִּרְצוֹן הַלֵּב כָּרָאוּי, וּמִשָּׁם וָהָלְאָה אַזְכָּרַת יְצִיאַת מִצְרַיִם, שֶׁהִיא מִצְוָה לְהַזְכִּיר אֶת יְצִיאַת מִצְרַיִם, שֶׁכָּתוּב (שם כד) וְזָכַרְתָּ כִּי עֶבֶד הָיִיתָ בְּאֶרֶץ מִצְרָיִם."],[7,"","שֶׁהַכֹּהֵן יְבָרֵךְ אֶת הָעָם - כְּדֵי לְהַכְלִיל אֶת יִשְׂרָאֵל כְּאֶחָד בְּשָׁעָה שֶׁנּוֹטְלִים בְּרָכוֹת מִלְמַעְלָה, שֶׁהֲרֵי בְּאוֹתָהּ שָׁעָה נוֹטֶלֶת כְּנֶסֶת יִשְׂרָאֵל בְּרָכוֹת, וּשְׁעַת רָצוֹן הִיא לִמְסֹר נַפְשׁוֹ אֵלָיו וְלָתֵת לוֹ אֶת הַנְּשָׁמָה בִּרְצוֹן הַלֵּב. כְּשֶׁנּוֹפְלִים אַפַּיִם וְאוֹמְרִים (תהלים כה) אֵלֶיךְ ה' נַפְשִׁי אֶשָּׂא, שֶׁיְּכַוֵּן לִבּוֹ וּרְצוֹנוֹ אֵלָיו לִמְסֹר לוֹ הַנֶּפֶשׁ בְּרָצוֹן שָׁלֵם. וְאֵלּוּ הֵן שֵׁשׁ מִצְווֹת שֶׁעוֹמְדוֹת בַּתְּפִלָּה, שֶׁעוֹלוֹת לְשֵׁשׁ מֵאוֹת מִצְווֹת שֶׁל הַתּוֹרָה."],[8,"","וְאִם תֹּאמַר, שְׁלֹשׁ עֶשְׂרֵה אֲחֵרוֹת יוֹתֵר? אֵלּוּ עוֹמְדִים לְהַמְשִׁיךְ שְׁלֹשׁ עֶשְׂרֵה מִדּוֹת הָרַחֲמִים, שֶׁהַכֹּל כָּלוּל בָּהֶן. (באלו) שֵׁשׁ הַמִּצְווֹת הַלָּלוּ שֶׁהַתְּפִלָּה מִתְעַטֶּרֶת בָּהֶן."]]],[["זַכָּאָה חוּלָקֵיהּ, מַאן דִּישַׁוֵּי לִבֵּיהּ וּרְעוּתֵיהּ לְדָא, וּלְאַשְׁלְמָא לוֹן בְּכָל יוֹמָא. וּבְאִלֵּין תַּלְיָין אַחֲרָנִין סַגִּיאִין. אֲבָל כַּד מָטֵי בַּר נָשׁ לְאַתְרִין אִלֵּין, אִצְטְרִיךְ לֵיהּ לְכַוְּונָא לִבֵּיהּ וּרְעוּתֵיהּ, לְאַשְׁלְמָא הַהוּא פִּקּוּדָא דְּקַיְּימָא בְּהַהוּא מִלָּה. וּכְדֵין אַכְרִיזוּ עָלֵיהּ וְאַמְרֵי, (ישעיהו מ״ט:ג׳) וַיֹּאמֶר לִי עַבְדִי אַתָּה יִשְׂרָאֵל אֲשֶׁר בְּךָ אֶתְפָּאָר. אָתָא רִבִּי אַבָּא וּנְשָׁקֵיהּ.","פָּתַח רִבִּי יִצְחָק אֲבַתְרֵיהּ וְאָמַר, (שמות ל״ה:א׳) וַיַּקְהֵל מֹשֶׁה אֶת כָּל עֲדַת בְּנֵי יִשְׂרָאֵל וְגוֹ'. אֲמַאי כָּנִישׁ לוֹן. בְּגִין לְמִמְסַר לוֹן שַׁבָּת כְּמִלְּקַדְּמִין, דְּהָא בְּקַדְמִיתָא עַד לָא עָבְדוּ בְּנֵי יִשְׂרָאֵל יַת עֶגְלָא, מָסַר לוֹן אֶת הַשַּׁבָּת. וְדָא אִיהוּ דְּלָא נַטְרוּ אִינּוּן עֵרֶב רַב. כֵּיוָן דְּשַׁמְעוּ בֵּינִי וּבֵין בְּנֵי יִשְׂרָאֵל, אָמְרוּ וַאֲנָן מִלָּה דָּא אִתְמָנַּע מִינָן, מִיַּד (שמות ל״ב:א׳) וַיִּקָּהֵל הָעָם עַל אַהֲרֹן וְגוֹ', וְאִתְמְשָׁכוּ סַגִּיאִין אֲבַתְרַיְיהוּ. לְבָתַר דְּמִיתוּ אִינּוּן דְּמִיתוּ, כָּנִישׁ מֹשֶׁה לִבְנִי יִשְׂרָאֵל בִּלְחוֹדַיְיהוּ, וְיָהַב לוֹן שַׁבָּת כְּמִלְּקַדְמִין, הֲדָא הוּא דִּכְתִּיב שֵׁשֶׁת יָמִים תֵּעָשֶׂה מְלָאכָה וְגוֹ'.","לֹא תְבַעֲרוּ אֵשׁ בְּכָל מוֹשְׁבוֹתֵיכֶם, הָכָא אִית רָזָא דְּרָזִין, לְאִינּוּן דְּיַדְעֵי חָכְמְתָא עִלָּאָה, רָזָא דְּשַׁבָּת הָא אוּקְמוּהָ חַבְרַיָּיא. אֲבָל רָזָא דָּא, אִתְמְסָר לְחַכִּימֵי עֶלְיוֹנִין, דְּהָא שַׁבָּת רָזָא עִלָּאָה הוּא.","תָּא חֲזֵי (ס\"א ביומא שתיתאה בשעתא דמטי) בְּשַׁעֲתָא דְּיוֹמָא שְׁתִּיתָאָה מָטָא זִמְנָא דְּעֶרֶב, כְּדֵין, כֹּכָבָא חַד מִסִּטְרָא דְּצָפוֹן נָהִיר, וְעִמֵּיהּ שִׁבְעִין כֹּכָבִין אַחֲרָנִין, וְהַהוּא כֹּכָבָא בָּטַשׁ בְּאִינּוּן כֹּכָבִין אַחֲרָנִין, וְאִתְכָּלְילוּ כֻּלְּהוּ בְּהַהוּא כֹּכָבָא, וְאִתְעָבִיד חַד כְּלָלָא דְּשִׁבְעִין. וְהַהוּא כֹּכָבָא אִתְפָּשַׁט, וְאִתְעָבִיד כְּמָדוּרָא חֲדָא, לְהִיטָא בְּכָל סִטְרִין. כְּדֵין אִתְפָּשַׁט הַהוּא מָדוּרָא סַחֲרָנַיְיהוּ דְּאֶלֶף טוּרִין, וְקַיְּימָא כְּחַד חוּטָא דְּסָחֲרָא.","וְהַאי מָדוּרָא דְּאֶשָּׁא, מָשִׁיךְ לְגַבֵּיהּ גַּוְונִין אַחֲרָנִין דִּלְגוֹ מִנֵּיהּ. גּוָֹון קַדְמָאָה יְרוֹקָא. כֵּיוָן דְּקַיְּימָא הַאי גַּוְונָא, סַלְּקָא הַהוּא מָדוּרָא דְּאֶשָּׁא, וְדָלִיג לְעֵילָּא עַל הַהוּא גּוָֹון יְרוֹקָא, וְעָאל לְגוֹ מִנֵּיהּ, וְשַׁדֵּי לְהַהוּא גּוָֹון יְרוֹקָא לְבַר, וְקַיְּימָא יְרוֹקָא לְבַר, וְהַהוּא מָדוּרָא דְּאֶשָּׁא דְּכֹכָבָא כְּלִילָא לְגוֹ.","לְבָתַר, אַמְשִׁיךְ אֲבַתְרֵיהּ גּוָֹון אַחֲרָא תִּנְיָינָא חִוָּורָא, וְהַהוּא חִוָּורָא עָאל לְגוֹ, כֵּיוָן דְּקַיְּימָא הַאי גּוָֹון, סַלְּקָא הַהוּא מָדוּרָא דְּאֶשָּׁא דְּהַהוּא כֹּכָבָא, וְשַׁדֵּי לְהַהוּא חִוָּורָא לְבַר, וְעָאל אִיהוּ לְגוֹ. וְכֵן כָּל אִינּוּן גַּוְונִין, עַד דְּשַׁדֵי לוֹן לְבַר, וְעָיִיל אִיהוּ לְגוֹ, וְקָרִיב לְגַבֵּי הַהִיא נְקוּדָה טְמִירָא, לְמֵיטָל נְהוֹרָא.","פָּתַח וְאָמַר, (יחזקאל א׳:ד׳) וָאֵרֶא וְהִנִּה רוּחַ סְעָרָה בָּאָה מִן הַצָּפוֹן וְגוֹ'. יְחֶזְקֵאל חָמָא לְהַאי חֵיזוּ, בְּתִקּוּנָא דְּלָא קַיְּימָא, בַּר בְּשַׁעֲתָא דְּשַׁלִּיט הַהוּא כֹּכָבָא כִּדְקָאָמְרָן, אֲבָל הַאי קְרָא אוּקְמוּהָ. וְהִנֵּה רוּחַ סְעָרָה, אוּקְמוּהָ, דְּהֲוָה אָתֵי לְמִכְבַּשׁ כָּל עָלְמָא, לְקַמֵּיהּ דִּנְבוּכַדְנֶצַר חַיָּיבָא. אֲבָל רוּחַ סְעָרָה דָּא, אִיהוּ הַהוּא כֹּכָבָא דְּקָאָמְרָן, דְּבָלַע שִׁבְעִין כֹּכָבִין אַחֲרָנִין, וְדָא אִיהוּ רוּחַ סְעָרָה דְּחָמָא אֵלִיָּהוּ, (מלכים א י״ט:י״א) מְפָרֵק הָרִים וּמְשַׁבֵּר סְלָעִים, וְדָא דְּקַיְּימָא תָּדִיר קֳדָם כֹּלָּא, לְמֵיטַר הַהוּא דִּלְגוֹ, כִּקְלִיפָה לְמוֹחָא.","וַאֲמַאי אִקְרֵי סְעָרָה. דְּסָעִיר כֹּלָּא, עֵילָּא וְתַתָּא. בָּאָה מִן הַצָּפוֹן, דְּהָא מִן הַהוּא סִטְרָא קָא אַתְיָא, וְסִימָנִךְ, (ירמיהו א׳:י״ד) מִצָּפוֹן תִּפָּתַח הָרָעָה, דְּהָא כַּמָה סִטְרִין אַחֲרָנִין אִתְאַחֲדָן בְּהַהוּא רוּחַ סְעָרָה, וּבְּגִין כָּךְ נָפְקָא מִן הַצָּפוֹן.","עָנָן, בְּגִין דְּאִיהִי סוּסְפִיתָא דְּדַהֲבָא. וּמִסִּטְרָא דְּצָפוֹן אִתְאַחֲדָא דָּא. וְהַאי אִיהִי נְקוּדָה (קפ\"ד ע\"ב) אֶמְצָעִיתָא, דְּקַיְּימָא בְּחוּרְבָּא. וּבְגִין דְּיָדַע לִמְפָתֵּי, שַׁלִּיט בְּגוֹ נְקוּדָה דִּישׁוּבָא, וְכָל מִלִּין דִּישׁוּבָא. בַּר אַרְעָא דְּיִשְׂרָאֵל, כַּד שָׁרָאן יִשְׂרָאֵל בְּגַוָּהּ, אִיהוּ (ד\"א לא) שַׁלְטָא עָלַיְיהוּ, וּלְבָתַר (קמ\"א ע\"א) דְּחָבוּ יִשְׂרָאֵל (ד\"א לא) שַׁלְטָא עַל אַרְעָא קַדִּישָׁא, בְּגִין דִּכְתִּיב, (איכה ב׳:ג׳) הֵשִׁיב אָחוֹר יְמִינוֹ מִפְּנֵי אוֹיֵב."],[[0,"זכאה חולקיה מאן וכו':","אשרי חלקו מי שישים לבו ורצונו לזה ולהשלים אותם בכל יום, ובאלו תלוים דברים אחרים רבים, אבל כשמגיע האדם למקומות אלו הנ\"ל, צריך לכוין לבו ורצונו להשלים מצוה ההיא התלויה במלה ההיא, ואז מכריזים עליו ואומרים, ויאמר לי עבדי אתה ישראל אשר בך אתפאר. בא ר' אבא ונשקו."],[1,"פתח ר' יצחק אבתריה וכו':","פר\"י אחריו ואמר, ויקהל משה את כל עדת וגו'. שואל, למה הקהיל אותם. ומשיב, כדי למסור להם שבת כמקודם. כי מקודם, מטרם שעשו ישראל את העגל, מסר להם את השבת. וזה הוא שלא שמרו הערב רב, כיון ששמעו ביני ובין בני ישראל, אמרו, ואנו, נמנע ממנו דבר הזה, מיד ויקהל העם על אהרן וגו' דהיינו לעשות העגל, ונמשכו אחריהם רבים. ואחר שמתו אלו שמתו מעובדי העגל, הקהיל משה את בני ישראל בלבד, ונתן להם השבת כמקודם. זהו שכתוב, ששת ימים תעשה מלאכה וגו'."],[2,"לא תבערו אש בכל וגו':","כאן יש סודי סודות לאלו שיודעים חכמה עליונה. סוד השבת כבר העמידו החברים. אבל סוד זה נמסר לחכמים העליונים, כי שבת סוד עליון הוא."],[3,"ת\"ח בשעתא דיומא וכו':","בוא וראה, בשעה שהגיע יום הששי לעת ערב, אז כוכב אחד מצד צפון מאיר, ועמו ע' כוכבים אחרים, וכוכב ההוא מכה באלו ע' כוכבים האחרים ונכללו כולם בכוכב ההוא ונעשו בו כל השבעים אחד, וכוכב ההוא נתפשט ונעשה מדורה אחת לוהטת מכל הצדדים. אז נתפשט מדורה ההיא סביב אלף הרים, ועומדת עליהם, כמו חוט אחד המקיף אותם."],[3,"","פיריש. ששת ימים ה\"ס חג\"ת נה\"י, ויום הששי הוא יסוד. ולעת ערב, היינו בסיום היסוד, שהערלה, שה\"ס ג' קליפות כמ\"ש לפנינו, מתגברת בשליטתה להפריד הזווג במלכות, שה\"ס השבת. וז\"ש, \u0003בשעתא דיומא שתיתאה,\u0004 שהוא יסוד, מטא זמנא דערב, דהיינו בסיומו. \u0003כדין ככבא חד מסטרא דצפון נהיר,\u0004 שככב הזה הוא הקליפה רוח סערה, כמ\"ש הזהר לפנינו, שיש בו דינים קשים ממסך דמלכות דמדת הדין, ומתגבר להאיר מצד צפון, דהיינו מקו שמאל, להמשיך משם החכמה מלמעלה למטה, כדרך כל הקליפות, ועמו ע' ככבים אחרים, שהם הע' שרים הנמשכים מהארת השמאל, ואין בהם מדת הדין הקשה דרוח סערה, אלא, \u0003וההוא ככבא בטש באינון ככבין אחרנין,\u0004 דהיינו שהזדווג עמהם, \u0003ואתכלילו כלהו בההוא כוכבא,\u0004 שמדת הדין הקשה שבכוכב נתפשט בכולם, \u0003ואתעביד חד\u0004 וכו' \u0003ואתעביד כמדורא חדא להיטא מכל סטרין,\u0004 שבחיבור עם ע' ככבים נעשה למדורת אש, שהוא דין קשה, הלוהט ושורף לכל הצדדים. כי דינין אלו קשים וחזקים מאד, ואין מי שיעמוד בפניהם, ואין לו תקון אלא גניזה. כמ\"ש לפנינו (באות קע\"ב)."],[3,"","וג' ספירות נה\"י מכונים הרים, (כנ\"ל משפטים אות רצ\"א) וכשממשיכים חכמה הם בסוד \u0003אלף הרים,\u0004 כי אלף היא כינוי לחכמה בסו\"ה ואאלפך חכמה. וז\"ש \u0003כדין אתפשט ההוא מדורא סחרנייהו דאלף טורין, וקיימא כחד חוטא דסהרא,\u0004 דהיינו שנתפשט מסביב לנה\"י, כדי לינק מהם."],[4,"והאי מדורא דאשא וכו':","ומדורת אש הזו, מושך אצלו גוונים אחרים, מן נה\"י כנ\"ל, שהם בפנימיות ממנו מן הגוון שלו, גוון א' הוא ירוק, שהוא הארת קו אמצעי. כיון שכבר עומד גוון הזה, עולה מדורת האש ומדלג למעלה על גוון הירוק הזה ונכנס לפנים ממנו, ומשליך את גוון הירוק לחוץ. ועומד גוון הירוק לחוץ, ומדורת האש של הכוכב הכלול מע' כוכבים עומד בפנים. כלומר שביטל הארת קו אמצעי ודחה אותה ושלט במקומה. שהוא מטעם, שבכל מקום שמתדבקים הדינים דמדת הדין הקשה, תיכף מסתלקים משם האורות. (כנ\"ל ויצא י\"ג ד\"ה סתרא)."],[5,"לבתר אמשיך אבתריה וכו':","אח\"כ המשיך אחריו גוון אחר שני לבן, שהוא הארה מקו ימין. ולבן הזה האיר בפנימיות. כיון שכבר עמד הגוון ההוא עלה מדורת אש הזו של הכוכב, והשליך את גוון הלבן לחוץ, והוא נכנס בפנימיות, וכן כל שאר הגוונין, השליך אותם לחוץ והוא נכנס בפנים וקרב אל נקודה הנסתרת, שה\"ס עטרת יסוד, לקבל אור. כי אם היה קרב, היה האור מסתלק מן היסוד, מטעם הנ\"ל שבדבור הסמוך, והוא היה מקבלו, כנ\"ל בגוונים. אמנם נעשה תקון שלא יוכל לקרב כנ\"ל."],[6,"פתח ואמר וארא וגו':","פו\"א, וארא והנה רוח סערה באה מן הצפון וגו'. יחזקאל ראה מראה ההוא, בתקון שאינו עומד אלא בשעה שכוכב ההוא שולט, כמו שאמרנו. כי אינו שולט תמיד, כי נגנז (כמ\"ש באות קע\"ב) אבל מקרא הזה העמידוהו, והנה רוח סערה, העמידו, שרוח הזה בא לכבוש כל העולם לפני נבוכדנצר. אבל \u0003רוח סערה,\u0004 זה הוא כוכב ההוא שאמרנו, שבלע ע' כוכבים אחרים. וזה הוא רוח סערה שראה אליהו, שנאמר עליו, מפרק הרים ומשבר סלעים, כי אין כח שיעמוד לפניו (כנ\"ל באות קנ\"ח) וזהו העומד תמיד לפני כל הקליפות מבחוץ, כדי לשמור אותם שמבפנים הימנו כקליפה השומרת המוח. פירוש. אע\"פ שנגנז, נמצא כחו תמיד מחוץ כל הדינים, כדי לשמרם. והוא מטעם היותו שורש כל הדינים. ואם הוא היה מתבטל היו מתבטלים עמו כל הדינים."],[7,"ואמאי אקרי סערה וכו':","ולמה נקרא סערה, משום שסוער הכל למעלה ולמטה, ואין מי שיעמוד לפניו. \u0003באה מן הצפון,\u0004 כי מצד הזה הוא בא. וסימנך, מצפון תפתח הרעה. כלומר הוא עצמו היא בחינת דינים קשים של המסך דמלכות דמדת הדין, אבל הוא בא מן הצפון, דהיינו למשוך חכמה מקו שמאל כדרך כל הקליפות. כי כמה בחינות אחרות חוץ מצפון, נאחזים ברוח סערה ההוא. וע\"כ אוה\"כ עליהם, יוצא מן הצפון. כלומר, שקבל גם דינים דצפון."],[8,"ענן, בגין דאיהי וכו':","ענן, דהיינו קליפה השניה שביחזקאל הנקראת \u0003ענן גדול.\u0004 היא נקראת ענן משום שהוא פסולת הזהב. וזו נאחזת בצד צפון. דהיינו בקו שמאל, וזו היא נקודה האמצעית העומדת במקומות החרבים. ומשום שידע לפתות את חוה. הוא שולט בנקודה האמצעית של הישוב ובכל דברי הישוב, חוץ מארץ ישראל. בזמן שישראל שרו בתוכה לא שלטה עליה, ולאח\"כ שחטאו ישראל, שלטה גם על ארץ הקדושה. משום שכתוב השיב אחור ימינו מפני אויב."],[8,"","פירוש, הקליפה הנקראת \u0003ענן,\u0004 היא בחינת פסולת הזהב, דהיינו מקו שמאל ממש, כמו שהזהר עצמו מפרש (בפקודי רכ\"ד ע\"ב, ד\"י) וזה לשונו, \u0003וכד איהו בארמותא,\u0004 שהארת החכמה מקו שמאל המכונה זהב, מאיר ממטה למעלה, \u0003כדין איהו דהב טב, וכל ההוא דלתתא,\u0004 דהיינו כמו שאומר מקודם לכן, שמתפשטא לתתא, דהיינו שהארת החכמה נמשכת ממעלה למטה, אז הוא נעשה \u0003סוספיתא דדהבא,\u0004 דהיינו פסולת הזהב, \u0003והיא התוכא דיליה.\u0004 הרי שענן גדול, שהיא פסולת הזהב היא מעצם קו השמאל ממש. עש\"ה. אבל רוח סערה היא מבחינת דינין דנוקבא, דהיינו ממסך דמלכות, אלא שבא מן הצפון. כנ\"ל. והיא נקראת נקודה דחורבא, (כנ\"ל תצוה אות צ\"ז) וז\"ש, \u0003ובגין דידע למפתי,\u0004 שפיתה את חוה להמשיך ממעלה למטה, שזה היה חטא עצה\"ד. משום זה, \u0003שליט בגו נקודה דישובא,\u0004 שנאחז בהמלכות, שה\"ס נקודת הישוב. וכן על ארץ ישראל אחר החורבן. כי היא שולטת בכל מקומות החורבן. (כנ\"ל תצוה אות צ\"ח)."]],[[0,"","אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁשָּׂם לִבּוֹ וּרְצוֹנוֹ לָזֶה וּלְהַשְׁלִים אוֹתָם בְּכָל יוֹם. וּבָאֵלּוּ תְּלוּיוֹת אֲחֵרוֹת רַבּוֹת. אֲבָל כְּשֶׁמַּגִּיעַ אָדָם לַמְּקוֹמוֹת הַלָּלוּ, צָרִיךְ לְכַוֵּן לִבּוֹ וּרְצוֹנוֹ לְהַשְׁלִים אוֹתָהּ מִצְוָה שֶׁעוֹמֶדֶת בְּאוֹתוֹ דִּבּוּר, וְאָז מַכְרִיזִים עָלָיו וְאוֹמְרִים: (ישעיה מט) וַיֹּאמֶר לִי עַבְדִּי אָתָּה יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר. בָּא רַבִּי אַבָּא וּנְשָׁקוֹ."],[1,"","פָּתַח רַבִּי יִצְחָק אַחֲרָיו וְאָמַר, וַיַּקְהֵל מֹשֶׁה אֶת כָּל עֲדַת בְּנֵי יִשְׂרָאֵל וְגוֹ'. לָמָּה כִּנֵּס אוֹתָם? כְּדֵי לִמְסֹר לָהֶם אֶת הַשַּׁבָּת כְּמִקֹּדֶם, שֶׁהֲרֵי בָּרִאשׁוֹנָה טֶרֶם שֶׁעָשׂוּ יִשְׂרָאֵל אֶת הָעֵגֶל, מָסַר לָהֶם אֶת הַשַּׁבָּת, וְזֶהוּ שֶׁלֹּא שָׁמְרוּ אוֹתָם הָעֵרֶב רַב. כֵּיוָן שֶׁשָּׁמְעוּ בֵּינִי וּבֵין בְּנֵי יִשְׂרָאֵל, אָמְרוּ: וְאָנוּ נִמְנָע מִמֶּנּוּ הַדָּבָר הַזֶּה?! מִיָּד - (שמות לב) וַיִּקָּהֵל הָעָם עַל אַהֲרֹן וְגוֹ', וְנִמְשְׁכוּ רַבִּים אַחֲרֵיהֶם. אַחַר שֶׁמֵּתוּ אוֹתָם שֶׁמֵּתוּ, כִּנֵּס מֹשֶׁה אֶת בְּנֵי יִשְׂרָאֵל לְבַדָּם, וְנָתַן לָהֶם שַׁבָּת כְּמִקֹּדֶם. זֶהוּ שֶׁכָּתוּב שֵׁשֶׁת יָמִים תֵּעָשֶׂה מְלָאכָה וְגוֹ'."],[2,"","לֹא תְבַעֲרוּ אֵשׁ בְּכֹל מֹשְׁבֹתֵיכֶם. כָּאן יֵשׁ סוֹד הַסּוֹדוֹת לְאוֹתָם שֶׁיּוֹדְעִים הַחָכְמָה הָעֶלְיוֹנָה. אֶת סוֹד הַשַּׁבָּת הֲרֵי בֵּאֲרוּ הַחֲבֵרִים, אֲבָל סוֹד זֶה נִמְסַר לַחֲכָמִים עֶלְיוֹנִים, שֶׁהֲרֵי שַׁבָּת הִיא סוֹד עֶלְיוֹן."],[3,"","בֹּא וּרְאֵה, (ביום הששי בשעה שמגיע) בְּשָׁעָה שֶׁבְּיוֹם שִׁשִּׁי מַגִּיעַ הָעֶרֶב, אָז כּוֹכָב אֶחָד מִצַּד צָפוֹן מֵאִיר, וְעִמּוֹ שִׁבְעִים כּוֹכָבִים אֲחֵרִים, וְאוֹתוֹ כּוֹכָב מַכֶּה בְּאוֹתָם הַכּוֹכָבִים הָאֲחרִים, וְכֻלָּם נִכְלָלִים בְּאוֹתוֹ כּוֹכָב, וְנַעֲשֶׂה כְּלָל אֶחָד שֶׁל שִׁבְעִים. וְאוֹתוֹ כּוֹכָב מִתְפַּשֵּׁט וְנַעֲשֶׂה כִּמְדוּרָה אַחַת לוֹהֶטֶת בְּכָל הַצְּדָדִים. אֲזַי מִתְפַּשֶּׁטֶת אוֹתָהּ מְדוּרָה סְבִיב אֶלֶף הָרִים, וְעוֹמֶדֶת כְּחוּט אֶחָד שֶׁמַּקִּיף."],[4,"","וּמְדוּרַת הָאֵשׁ הַזּוֹ מוֹשֶׁכֶת אֵלֶיהָ גְּוָנִים אֲחֵרִים שֶׁהֵם לְתוֹךְ מִמֶּנָּה. גָּוֶן רִאשׁוֹן יָרֹק. כֵּיוָן שֶׁעוֹמֵד גָּוֶן זֶה, עוֹלָהּ אוֹתָהּ מְדוּרַת אֵשׁ וּמְדַלֶּגֶת לְמַעְלָה עַל אוֹתוֹ גָּוֶן יָרֹק, וְנִכְנֶסֶת לִפְנִים מִמֶּנּוּ, וְזוֹרֶקֶת אוֹתוֹ גָּוֶן יָרֹק הַחוּצָה, וְעוֹמֵד הַיָּרֹק בַּחוּץ, וְאוֹתָהּ מְדוּרַת אֵשׁ שֶׁל הַכּוֹכָב הַכָּלוּל לִפְנִים."],[5,"","אַחַר כָּךְ מַמְשִׁיכָה אַחֲרֶיהָ גָּוֶן שֵׁנִי לָבָן, וְאוֹתוֹ לָבָן נִכְנָס פְּנִימָה. כֵּיוָן שֶׁעוֹמֵד הַגָּוֶן הַזֶּה, עוֹלָה אוֹתָהּ מְדוּרַת אֵשׁ שֶׁל אוֹתוֹ כּוֹכָב, וְזוֹרֶקֶת אֶת אוֹתוֹ לָבָן הַחוּצָה, וְהִיא נִכְנֶסֶת פְּנִימָה. וְכָךְ כָּל אוֹתָם הַגְּוָנִים, עַד שֶׁזּוֹרֶקֶת אוֹתָם הַחוּצָה, וְהִיא נִכְנֶסֶת פְּנִימָה וּקְרֵבָה לְאוֹתָהּ נְקֻדָּה טְמִירָה לִטֹּל אוֹר."],[6,"","פָּתַח וְאָמַר, (יחזקאל א) וָאֵרֶא וְהִנֵּה רוּחַ סְעָרָה בָּאָה מִן הַצָּפוֹן וְגוֹ'. יְחֶזְקֵאל רָאָה אֶת הַמַּרְאֶה הַזֶּה בְּתִקּוּן שֶׁלֹּא עוֹמֵד, פְּרָט לְשָׁעָה שֶׁעוֹמֵד אוֹתוֹ כּוֹכָב שֶׁאָמַרְנוּ, אֲבָל הַפָּסוּק הַזֶּה פֵּרְשׁוּהוּ. וְהִנֵּה רוּחַ סְעָרָה, פֵּרְשׁוּהוּ שֶׁהָיָה בָּא לִכְבֹּשׁ אֶת כָּל הָעוֹלָם לִפְנֵי נְבוּכַדְנֶצַּר הָרָשָׁע. אֲבָל רוּחַ הַסְּעָרָה הַזּוֹ הִיא הַכּוֹכָב שֶׁאָמַרְנוּ, שֶׁבּוֹלֵעַ שִׁבְעִים כּוֹכָבִים, וְזוֹ רוּחַ הַסְּעָרָה שֶׁרָאָה אֵלִיָּהוּ, (מלכים א יט) מְפָרֵק הָרִים וּמְשַׁבֵּר סְלָעִים, וְזֶה שֶׁעוֹמֵד תָּמִיד לִפְנֵי הַכֹּל לִשְׁמֹר אוֹתוֹ שֶׁבִּפְנִים כְּמוֹ קְלִפָּה לַמֹּחַ."],[7,"","וְלָמָּה נִקְרֵאת סְעָרָה? שֶׁמַּסְעִירָה הַכֹּל, מַעְלָה וּמַטָּה. בָּאָה מִן הַצָּפוֹן, שֶׁהֲרֵי מֵאוֹתוֹ צַד הִיא בָּאָה, וְסִימָנְךְ - (ירמיה א) מִצָּפוֹן תִּפָּתַח הָרָעָה, שֶׁהֲרֵי כַּמָּה צְדָדִים אֲחֵרִים נֶאֱחָזִים בְּאוֹתָהּ רוּחַ סְעָרָה, וּמִשּׁוּם כָּךְ יוֹצֵאת מִן הַצָּפוֹן."],[8,"","עָנָן, מִשּׁוּם שֶׁהִיא פְּסֹלֶת הַזָּהָב. וּמִצַּד הַצָּפוֹן זֶה נֶאֱחָז. וְזוֹהִי הַנְּקֻדָּה הָאֶמְצָעִית שֶׁעוֹמֶדֶת בְּחָרְבָּה. וּמִשּׁוּם שֶׁיּוֹדֵעַ לְפַתּוֹת, שׁוֹלֵט בְּתוֹךְ אוֹתָהּ נְקֻדָּה שֶׁל יִשּׁוּב וְכָל דִּבְרֵי הַיִּשּׁוּב, פְּרָט לְאֶרֶץ יִשְׂרָאֵל. כְּשֶׁיִּשְׂרָאֵל שׁוֹרִים בְּתוֹכָהּ, הוּא (לא) שׁוֹלֵט עֲלֵיהֶם. וְאַחַר שֶׁחָטְאוּ יִשְׂרָאֵל, (לא) שׁוֹלֵט עַל הָאָרֶץ הַקְּדוֹשָׁה, מִשּׁוּם שֶׁכָּתוּב הֵשִׁיב אָחוֹר יְמִינוֹ מִפְּנֵי אוֹיֵב."]]],[["עָנָן גָּדוֹל דָּא, אִיהוּ עֲנָנָא דְּחַשׁוֹכָא, דְּאַחֲשִׁיךְ כָּל עָלְמָא. תָּא חֲזֵי, מַה בֵּין עֲנָנָא לַעֲנָנָא. הַהוּא עֲנָנָא דִּכְתִּיב (במדבר י׳:ל״ד) וַעֲנַן יְיָ' עֲלֵיהֶם יוֹמָם. (במדבר י״ד:י״ד) וַעֲנָנְךָ עוֹמֵד עֲלֵיהֶם. (ויקרא ק\"ג ע\"א, ג' ע\"ב) הַאי אִיהוּ עֲנָנָא דְּנָהִיר וְזָהִיר, וְכָל נְהוֹרִין אִתְחָזוּן גּוֹ הַהוּא עֲנָנָא. אֲבָל עֲנָנָא דָּא, עֲנָנָא חָשׁוּךְ, דְּלָא נָהִיר כְּלָל, אֲבָל מָנַע כָּל נְהוֹרִין, דְּלָא יַכְלִין לְאִתְחֲזָאָה קַמֵּיהּ.","גָּדוֹל, אֲמַאי אִקְרֵי גָּדוֹל, וְהָא זְעֵיר אִיהוּ. אֶלָּא גָּדוֹל אִיהוּ, כֵּיוָן דְּשַׁלִּיט. דָּבָר אַחֵר גָּדוֹל, הַהוּא חֲשׁוֹכָא גָּדוֹל, כֵּיוָן דְּכַסֵּי כָּל נְהוֹרִין וְלָא אִתְחָזוּן קַמֵּיהּ, וְאִיהוּ גָּדוֹל (נ\"א שליט) עַל כָּל עוֹבָדִין דְּעָלְמָא.","וְאֵשׁ מִתְלַקַּחַת, דְּהָא אֶשָּׁא דְּדִינָא קַשְׁיָא, לָא אַעְדֵּי מִנֵיהּ לְעָלְמִין. וְנֹגַהּ לוֹ סָבִיב, אַף עַל גַּב דְּכָל הַאי קַיְּימָא בֵּיהּ, נֹגַהּ לוֹ סָבִיב. מֵהָכָא אוֹלִיפְנָא, דְּאַף עַל גַּב דְּלֵית סִטְרָא דָּא, אֶלָּא סִטְרָא (ס\"ט ע\"א) דִּמְסָאֳבוּ, נֹגַהּ לוֹ סָבִיב, וְלָא אִצְטְרִיךְ לֵיהּ לְבַר נָשׁ, לְדַחְיָיא לֵיהּ לְבַר. מַאי טַעְמָא. בְּגִין דְּנֹגַהּ לוֹ סָבִיב, סִטְרָא דִּקְדוּשָּׁה דִּמְהֵימְנוּתָא אִית לֵיהּ, וְלָא אִצְטְרִיךְ לְאַנְהָגָא בֵּיהּ קְלָנָא. וְעַל דָּא אִצְטְרִיךְ לְמֵיהַב לֵיהּ חוּלָקָא, בְּסִטְרָא דִּקְדוּשָּׁא דִּמְהֵימְנוּתָא.","רַב הַמְנוּנָא סָבָא, הָכִי אָמַר, וְכִי נֹגַהּ לוֹ סָבִיב, וְאִצְטְרִיךְ לְאַנְהָגָא בֵּיהּ קְלָנָא, הַאי נֹגַהּ לוֹ, לְגוֹ אִיהוּ, וְלָא קַיְּימָא לְבַר. וּבְגִין דְּקַיְּימָא הַהוּא נֹגַהּ לוֹ מִגּוֹ, כְּתִיב וּמִתּוֹכָהּ כְּעֵין הַחַשְׁמַל מִתּוֹךְ הָאֵשׁ. מִתּוֹכָה דְּמַאן. מִתּוֹכָה דְּהַהוּא נֹגַהּ. כְּעֵין הַחַשְׁמַל: חָשׁ, מָל, הָא אוּקְמוּהָ, חֵיוָון דְּאֶשָּׁא (פ\"א ע\"ב) מְמַלְּלָא.","אֲבָל מִבּוּצִינָא קַדִּישָׁא שְׁמַעְנָא עָלָה רָזָא דְּרָזִין. כַּד עָרְלָה שָׁרֵי עַל קַיְּימָא קַדִּישָׁא לְסָאֲבָא מַקְדְּשָׁא, כְּדֵין הַהוּא מַקְדְּשָׁא, אִתְעַכָּב מִלְּגַלָּאָה רָזָא דְּאָת קַיָּימָא, מִגּוֹ עָרְלָה. וְכַד הַאי נֹגַהּ עָאל לְגוֹ, וְאַפְרִישׁ בֵּין עָרְלָה, וּבֵין מַקְדְּשָׁא, כְּדֵין אִקְרֵי חַשְׁמַל חָשׁ וְאִתְגַּלְיָא. מָל, מַהוּ מָל. כְּמָה דְאַתְּ אָמֵר (יהושע ה׳:ד׳) מָל יְהוֹשֻׁעַ. רָזָא דְּאָת קַיָּימָא, אִתְעַכָּב מִלְּאִתְגַלָּאָה מִגּוֹ עָרְלָה.","וְאִית רָזָא אַחֲרָא, דְּהָא נְהוֹרָא דִּילֵיהּ, אִתְחָזֵי וְלָא אִתְחָזֵי, וְכַד אִתְגַּלְיָא חַשְׁמַל אִתְעֲבָּר נְהוֹרֵיהּ. אֲבָל רָזָא קַדְמָאָה, אִיהוּ בְּרָזָא דִּקְרָא כְּדְקָא יֵאוֹת, וְכֹלָּא שַׁפִּיר אִיהוּ, וְיָאוּת הוּא.","בְּהַאי נֹגַהּ, מְפַתֵּי לְאִתְּתָא, לְנַטְלָא נְהוֹרָא. וְעַל דָּא כְּתִיב, (משלי ה׳:ג׳) וְחָלָק מִשֶּׁמֶן חִכָּהּ, שַׁוֵּי הַהוּא נְהוֹרָא לָקֳבְלֵיהּ דִּבְרִית. וּבְגִינֵי כַּךְ מְפַתֵּי לֵיהּ, וְנַטְלָא נְהוֹרֵיהּ. וְדָא אִיהוּ פִּתּוּיָא דִּמְפַתֵּי לְאִתְּתָא, דִּכְתִּיב, (משלי ה׳:ג׳) נֹפֶת תִּטֹּפְנָה שִׂפְתֵי זָרָה וְגוֹ'.","תָּא חֲזֵי, בְּיוֹמָא שְׁתִיתָאָה כַּד מָטָא זִמְנָא דְּעֶרֶב, דָּלִיג לְגוֹ הַהוּא (נ\"א מדורא) נְהוֹרָא דְּאֶשָּׁא, וְסַלְּקָא לְעֵילָּא לְאַעֲלָא גּוֹ גַּוְונִין. כְּדֵין מְתְתַּקְּנִין יִשְׂרָאֵל לְתַתָּא, וּמְסַדְּרִין סְעוּדָתִין, וּמַתְקְנִין פָּתוֹרִין, כָּל חַד וְחַד פָּתוֹרֵיהּ. כְּדֵין חַד שַׁלְהוֹבָא נָפִיק וּבָטַשׁ בְּהַהוּא מָדוּרָא, כֵּיוָן דְּבָטַשׁ בֵּיהּ, מִתְגַּלְגְּלָן הַהוּא שַׁלְהוֹבָא, וְהַהוּא מָדּוּרָא וְעָאלִין בְּנוּקְבָּא דִּתְהוֹמָא רַבָּא, וְאִתְטַמְּרָן וְיַתְבַת תַּמָן.","וְהַהוּא שַׁלְהוֹבָא אִיהוּ מִסִּטְרָא דִּימִינָא, וּבְגִין דְּהוּא מִסִּטְרָא דִּימִינָא, אַעְבָּר לְהַהוּא מָדּוּרָא, וְאָעִיל לֵיהּ לְנוּקְבָּא דִּתְהוֹמָא רַבָּא, וְיָתִיב תַּמָּן עַד דְּנָפִיק שַׁבְּתָא. כֵּיוָן דְּנָפַק שַׁבְּתָא, אִצְטְרִיךְ לְהוּ לְעַמָּא דְּיִשְׂרָאֵל לְבָרְכָא עַל אֶשָּׁא, וְנָפְקָא הַהוּא שַׁלְהוֹבָא, בְּבִרְכְתָא דִּלְתַתָּא, וְשָׁלִיט עַל הַהוּא מָדּוּרָא כָּל הַהוּא לֵילְיָא, וְאִתְכַּפְיָא הַהוּא מָדּוּרָא.","תָּא חֲזֵי, כֵּיוָן דְּעָאל שַׁבְּתָא, וְאִתְטָמַּר הַהוּא מָדּוּרָא, כָּל אֶשִּׁין דְּאֶשָּׁא קַשְׁיָא אִתְטְמָרוּ וְאִתְכַּפְיָין, וַאֲפִילּוּ אֶשָּׁא דְּגֵיהִנָּם, וְחַיָּיבִין דְּגֵיהִנָּם, אִית לוֹן נַיְיחָא. וְכֹלָּא תַּתָּא וְעֵילָּא אִית לְהוּ נַיְיחָא. כַּד נָפַק שַׁבְּתָא, וּמְבָרְכִין יִשְׂרָאֵל עַל נוּרָא, כְּדֵין נָפְקִין כָּל אֶשִּׁין דְּמִתְטַמְּרָן, כָּל חַד וְחַד לְאַתְרֵיהּ. וּבְגִין דְּלָא לְאִתְּעָרָא אֶשָּׁא אַחֲרָא, כְּתִיב (שמות ל״ה:ג׳) לֹא תְבַעֲרוּ אֵשׁ בְּכָל מוֹשְׁבוֹתֵיכֶם בְּיוֹם הַשַּׁבָּת, וְהָא אוּקְמוּהָ, אֶשָּׁא דְּמַדְבְּחָא אֲמַאי.","אֶלָּא כַּד עָאל שַׁבְּתָא, כָּרוֹזָא קָרֵי בְּכוּלְּהוּ רְקִיעִין, אִתְתְּקָנוּ רְתִיכִין, אִתְתְּקָנוּ מַשִׁרְיָין, לְקַדְמוּת מָארֵיכוֹן. כְּדֵין נָפִיק חַד רוּחָא מִסִּטְרָא דְּדָרוֹם, וְהַהוּא רוּחָא אִתְפְּרַשׁ עַל כָּל אִינּוּן חֵילִין וּמַשִׁרְיָין דְּלִסְטַר יְמִינָא, וְאִתְלַבְּשָׁן בֵּיהּ, וְהַהוּא רוּחָא אִקְרֵי לְבוּשָׁא דִּיקָר דְּשַׁבְּתָא. כְּדֵין פָּתוֹרֵי דְּהַאי עָלְמָא, מִתְתַּקְּנָן בְּחַד הֵיכָלָא. זַכָּאָה חוּלָקֵיהּ דְּהַהוּא בַּר נָשׁ, דְּסִדּוּרָא דְּפָתוֹרֵיהּ אִתְחָזֵי תַּמָּן כְּדְקָא יָאוּת, וְקַיְּימָא כֹּלָּא מִתְתַּקְּנָא, בְּלָא כִּסּוּפָא, אִינִשׁ כְּפוּם חֵילֵיהּ."],[[0,"ענן גדול דא וכו':","שואל, למה נקרא ענן גדול. ומשיב, שהוא ענן של חושך, שהחשיך כל העולם. בוא וראה, מה בין ענן לענן. ענן ההוא, שכתוב, וענן ה' עליהם יומם. ועננך עומד עליהם, זה הוא ענן המאיר ומזהיר וכל האורות נראים בו בתוך ענן ההוא. אבל ענן זה דקליפות, הוא ענן חושך שאינו מאיר כלום. אבל מונע כל האורות, שאינם יכולים להראות מפניו."],[1,"גדול, אמאי אקרי וכו':","שואל, הוא נקרא \u0003גדול,\u0004 ואם הוא חושך, למה נקרא גדול, והרי קטן הוא. ומשיב, אלא הוא \u0003גדול,\u0004 משום ששולט. כלומר, שהוא גדול בשליטה, להיותו נמשך מן החכמה שבקו שמאל, כי הוא סוספיתא דדהבא כנ\"ל. דבר אחר, הוא נקרא גדול משום שהחושך שבו הוא גדול, כיון שמכסה כל האורות ואינם נראים לפניו. והוא גדול, מכל הדברים הנעשים בעולם."],[2,"ואש מתלקחת וכו':","היינו שהאש דדין קשה אינה עוזבת אותו לעולם. כלומר, הקליפה עצמה אינה אש, דהיינו שאינה דין קשה, אלא שהאש עלתה מלמטה מרוח סערה והתלקחה בה ואינה עוזבת אותה לעולם. \u0003ונגה לו סביב.\u0004 משמיענו, אע\"פ שכל זה נמצא בה, בקליפה דאש מתלקחת, מ\"מ, נוגה לו סביב. מכאן למדנו, שאע\"פ שאין צד הזה אלא צד הטומאה, נגה לו סביב, שיש נגה והארת הקדושה מסביב, וע\"כ אין האדם צריך לדחותו לחוץ. מהו הטעם. משום שנגה לו סביב, דהיינו שיש לו צד קדושה של האמונה, ואין צריך לנהוג בו בזיון, וע\"כ צריך לתת לו חלק בצד הקדושה של האמונה."],[2,"","פירוש. כי ג' קליפות אלו הם נגד הדינים שבמלכות ובז\"א ובבינה. כי הרוח סערה נגד הדין קשה שבמלכות. והענן גדול, נגד הדין קשה שבגבורה דז\"א. ואש מתלקחת, נגד הדינים שבבינה שהמלכות עלתה בה. ועל קליפה ג' הזו אומר הכתוב, ונגה לו סביב. ללמד שהיא קרובה לקדושה, כי היא נמשכת מן המוקש שמשימים על פני התנין, כדי שלא יקטרג בזנב שלו כמבואר לעיל (פרשת וארא אות ק\"ט ואות ק\"י בהסולם עש\"ה). ונמצא שהוא משמש לקדושה, וז\"ש הכתוב, ונגה לו סביב. וע\"כ אין צריך לנהוג בקליפה זו בזיון, אלא לתת לו חלק בקדושה, דהיינו שמניחים אותה להתאחז בבינה, אע\"פ שבבינה עצמה אין דינין כלל. אלא שהוא מחמת המלכות שעלתה שמה. כי זה בחינת מוקש לקליפות, כמו שמבואר שם בארוכה."],[3,"רב המנונא סבא וכו':","רה\"ס, אמר כך. שהכתוב נאמר בדרך תמיהא, וכי נגה לו סביב. ע\"כ צריך לנהוג בו בזיון, כי נגה לו, הזה, היא בפנים ואינו עומד מחוץ ומסביב לאש מתלקחת. ומשום שנגה לו, הזה, הוא בפנים, כתוב, ומתוכה כעין החשמל מתוך האש. \u0003מתוכה,\u0004 של מי. מתוכה של נגה ההוא. \u0003כעין החשמל,\u0004 היינו אותיות \u0003חש מל,\u0004 וכבר העמידו, חיות אש ממללות."],[3,"","פירוש. רב המנונא סבא חולק, ואומר, שצריכים לנהוג בזיון בקליפה אש מתלקחת, אע\"פ שמשמשות לקדושה, כי הקדושה אינה מחוץ לקליפה, כלומר שאין הקדושה מתגלה אלא אחר שנתבטלה הקליפה ונדחית, שזה נחשב שהקדושה היא בפנימיות הקליפה והקליפה שומרת ומסבבה בחוץ. ע\"כ אומר רב המנונא שצריכים להנהיג בה בזיון ולדחותה כדי שתתגלה הקדושה."],[3,"","ומ\"ש, \u0003מתוכה דההוא נגה,\u0004 הוא חולק על ר' יוסי לעיל, (יתרו אות שי\"א) שאומר שהחשמל הוא מתוך האש מתלקחת. ע\"ש. ומ\"ש \u0003חיון דאשא ממללא,\u0004 היינו שנמשך הארתם מזווג קול ודבור, שהם זו\"ן."],[4,"אבל מבוצינא קדישא וכו':","אבל ממאור הקדוש, שמענו עליה סודי סודות, כשהערלה שורה על ברית הקדוש, לטמא את המקדש, דהיינו העטרה שה\"ס המלכות, אז מקדש ההוא מתעכב מלגלות סוד אות ברית, דהיינו אורות חסדים המגולים בהארת חכמה, מתוך הערלה. וכשנגה הזה נכנס בפנים, ומפריד בין הערלה ובין המקדש, אז נקרא חשמל, שפירושו חש ונתגלה. שואל, הרי כתוב גם \u0003מל\u0004 בחשמל, מהו מל. ומשיב, הוא כמש\"א מל יהושע, ורומז על סוד אות הברית, שנתעכב מלגלות אורותיו מחמת הערלה, ועתה כיון שכבר \u0003מל\u0004 נתגלה. ויהיה פירושו, \u0003חש\u0004 לגלות משום שכבר \u0003מל\u0004 הערלה."],[4,"","פירוש. הערלה, כוללת ג' קליפות הנ\"ל רוח סערה, ענן גדול, אש מתלקחת, וכשהיא קרובה ליסוד, ורוצה לינק משם, אז כל האורות נסתמים. ונגה, ה\"ס הארת חכמה, כשהוא נכנס לפנים אל היסוד הוא מבטל ומפריד כל הקליפות, והן בורחות, כמו שהחשך בורח מפני האור. ואז מתגלים החסדים המגולים מן היסוד. שה\"ס קו האמצעי. ונקרא האור חשמל, מחמת ש \u0003חש\u0004 להגלות בשעה ש \u0003מל\u0004 את הערלה."],[5,"ואית רזא אחרא וכו':","ויש סוד אחר, כי האור שלו של הקליפות, היו נראים ואינם נראים, כלומר שעוד היתה בהם נהירו דקיק, שהיתה נראית פעם, וכאשר נתגלה החשמל, נעבר אור שלהם לגמרי, אבל סוד הראשון שאמרנו הוא נמצא בסוד הכתוב כראוי. וסוד הזה אינו מתישב בכתוב. והכל יפה הוא ונכון הוא, ששניהם אמתים."],[6,"בהאי נגה מפתי לאתתא וכו':","בנגה הזה, פיתה הנחש את האשה, חוה, לקחת אור. וע\"כ כתוב, וחלק משמן חכה, כי שם אור הזה כנגד הברית, ומשום זה פיתה אותה ולקחה אורו. וזהו הפיתוי שפיתה את האשה, שכתוב, נפת תטפנה שפתי זרה וגו'."],[6,"","פירוש. כי לעיל (אות קס\"ד) אומר אשר הקליפה דענן גדול, פיתה את חוה לעץ הדעת, שאומר, \u0003בגין דידע למפתי שליט בגו נקודה דישובא.\u0004 וכאן אומר, \u0003בהאי נגה מפתי לאתתא,\u0004 אמנם אין הפירוש, שנגה פיתה אותה, אלא הקליפה דענן גדול, שהוא הנחש, הוא שפתה אותה, כמו שאומר לעיל, אלא כאן מפרש, באיזה אור, וכיצד, פיתה אותה, וז\"ש, \u0003בהאי נגה מפתי\u0004 וכו' שפיתה אותה להמשיך ולקחת אור הנגה הזה. וז\"ש, \u0003שוי ההוא נהורא לקבליה דברית,\u0004 דהיינו שהראה לה איך הנגה הזה מאיר על הברית, ומפריד ומבריח כל הקליפות (כנ\"ל אות קס\"ט) ומבער כל הרע, להיותו הארת החכמה. ומחמת זה היה כחו של הנחש יפה, לפתות אותה לקחת אור הזה. אמנם כשהנגה מאיר בסוד הברית, הוא מאיר ממטה למעלה, כדרך קו האמצעי שהוא הברית, דהיינו יסוד. אבל הנחש, שהוא בחינת הקליפה דענן גדול, פיתה אותה להמשיך אור נגה הזה ממעלה למטה, בדרך הענן גדול (כנ\"ל אות קס\"ד) ובזה הכשילה. וז\"ס שאמרו חז\"ל שחטא עצה\"ד היה שסחטה ענבים. דהיינו שהמשיכה הארת חכמה ממעלה למטה, כדרך הקליפה דענן גדול. וז\"ס, שהנגה חציו קדושה וחציו קליפה. פירוש אם הוא דבוק בברית קדש, שמאיר רק ממטה למעלה, שהוא בחינת החצי דו\"ק דג\"ר, הוא קדושה גדולה. ואם הקליפות מתקרבים למשוך ממנו חציו השני שהוא ג\"ר דג\"ר הנמשך ממעלה למטה, אז היא קליפה טמאה, דהיינו ממש בחינת ענן גדול."],[7,"ת\"ח ביומא שתיתאה וכו':","בוא וראה, ביום הששי שהוא יסוד, כשמגיע עת הערב, היינו בסיומו, מדלג מדורת אש ההוא, שהוא רוח סערה, לפנים, ועולה למעלה לכנוס תוך הגוונין. (כנ\"ל אות קנ\"ט) אז מתתקנים ישראל למטה, ומסדרים סעודות, ועורכים שלחנות כל אחד ואחד שלחנו, אז יוצא שלהבת אחת, שהיא מבחינת הדינים דמלכות הממותקת בבינה, ומכה במדורת אש ההיא, כלומר שמתחבר עמו, כיון שהכה בו ונתחברו, מתגלגלים יחד שלהבת ההיא ומדורה ההיא ונכנסים בנקב תהום הגדול, ונסתרים ויושבים שם."],[7,"","פירוש. אחר ששלהבת מצד מלכות הממותקת בבינה הכה ונתחברה עם מדורת האש, שהוא רוח סערה ממסך דמלכות דמדת הדין הקשה, אז קבלה המדורה בחינת דינים הממותקים בבינה מבחינת השלהבת ודיניה עצמה הקשים נבטלו, וע\"כ נתגלגלו שניהם לתהומא רבא. ששם מקום דינים דבינה. כי מקום דינים דמלכות נקראים תהומא זוטא. וכיון שנתבטלו דינים הקשים דמדורת אש, אז יכלו להתגלות אורות השבת."],[8,"וההוא שלהובא איהו","וכו': ושלהבת ההיא, היא מצד ימין, שה\"ס נקודת החולט, שבה עלתה המלכות לבינה ונמתקה, (כנ\"ל ב\"א ט\"ו ד\"ה ההיא) ומשום שהיא מצד ימין, העביר הדינים של אותה המדורה, והכניסה לנקב תהום הגדול. והוא מטעם כי הקליפה רוצה להתאחז תמיד במקום יותר עליון, וע\"כ כיון שניתן מקום לקליפה דמדורת אש להתאחז בבינה ע\"י חיבורה עם השלהבת, תיכף עזבה הדינים שלה של המלכות, ועלתה לדינים דשלהבת שהם נאחזים בבינה ונתחברה עמה. (כנ\"ל וארא אות ק\"ט ק\"י בהסולם) ויושבת שם בתהום הגדול עד שיוצא השבת. כיון שיוצא השבת, צריכים עם ישראל לברך על האש. וע\"י הברכה מלמטה יוצא השלהבת ויוצא ושולט על מדורה ההיא כל לילה ההוא דמוצאי שבת. ומדורה ההיא נכנע, כלומר שכחה נגנז."],[9,"תא חזי כיון וכו':","בוא וראה, כיון שנכנס השבת ומדורה ההיא נסתתרה בתהום הגדול, אז כל האשות דאש קשה נסתתרו ונכנעו, כי המדורה שהיא רוח סערה, היא שורש כל הדינים הקשים (כנ\"ל אות קס\"א בהסולם) ואפילו האש של גיהנם, ורשעים שבגיהנם יש להם מנוחה, והכל, שלמעלה ושלמטה יש להם מנוחה. כשיוצא השבת, וישראל מברכין על האש, אז יוצאות כל האשות שנסתתרו, כל אחת ואחת למקומה. וכדי שלא לעורר אש אחרת מאלו שנסתתרו, כתוב, לא תבערו אש בכל מושבותיכם ביום השבת. וכבר העמידוהו למה מותר בשבת אש המזבח. (להלן אות רנ\"ח)."],[10,"אלא כד עאל וכו':","אלא כשנכנס השבת, הכרוז קורא בכל הרקיעים, התתקנו המרכבות, התתקנו המחנות, לפני אדוניכם. אז יוצא רוח אחד מצד דרום, שהוא אור החסד, ורוח ההוא נפרש על כל אלו הצבאות והמחנות שבצד ימין, ומתלבשים בו. ורוח ההוא נקרא, לבוש יקר של שבת. אז השלחנות שבני אדם עורכים בעולם הזה מתתקנים בהיכל אחד. שהוא המלכות, אשרי חלקו של אדם ההוא שעריכת שלחנו נראה שם כראוי, והכל נמצא מתוקן בלי בושה, איש לפי כחו."]],[[0,"","הֶעָנָן הַגָּדוֹל הַזֶּה הוּא עָנָן שֶׁל חֲשֵׁכָה שֶׁמַּחְשִׁיךְ אֶת כָּל הָעוֹלָם. בּא וּרְאֵה מַה בֵּין עָנָן לְעָנָן. אוֹתוֹ עָנָן שֶׁכָּתוּב (במדברי) וַעֲנַן ה' עֲלֵיהֶם יוֹמָם. (שם יד) וַעֲנָנְךְ עֹמֵד עֲלֵהֶם. זֶהוּ עָנָן שֶׁמֵּאִיר וְזוֹהֵר, וְכָל הָאוֹרוֹת נִרְאִים בְּתוֹךְ אוֹתוֹ עָנָן. אֲבָל הֶעָנָן הַזֶּה הוּא עָנָן חָשׁוּךְ שֶׁלֹּא מֵאִיר כְּלָל, אֲבָל מוֹנֵעַ אֶת כָּל הָאוֹרוֹת שֶׁלֹּא יְכוֹלִים לְהֵרָאוֹת לְפָנָיו."],[1,"","גָּדוֹל, לָמָּה נִקְרָא גָדוֹל, וַהֲרֵי הוּא קָטָן? אֶלָּא הוּא גָּדוֹל כֵּיוָן שֶׁשּׁוֹלֵט. דָּבָר אַחֵר גָּדוֹל - אוֹתוֹ חֹשֶׁךְ גָּדוֹל, כֵּיוָן שֶׁמְּכַסֶּה אֶת כָּל הָאוֹרוֹת וְאֵינָם נִרְאִים לְפָנָיו, וְהוּא גָּדוֹל (שולט) עַל כָּל מַעֲשֵׂי הָעוֹלָם."],[2,"","וְאֵשׁ מִתְלַקַּחַת, שֶׁהֲרֵי הָאֵשׁ שֶׁל הַדִּין הַקָּשֶׁה לֹא זָזָה מִמֶּנּוּ לְעוֹלָמִים. וְנֹגַהּ לוֹ סָבִיב, אַף עַל גַב שֶׁכָּל זֶה עוֹמֵד בּוֹ - נֹגַהּ לוֹ סָבִיב. מִכָּאן לָמַדְנוּ, שֶׁאַף עַל גַּב שֶׁאֵין זֶה צַד, אֶלָּא צַד שֶׁל טֻמְאָה - נֹגַהּ לוֹ סָבִיב, וְלֹא צָרִיךְ לָאָדָם לִדְחוֹתוֹ הַחוּצָה. מָה הַטַּעַם? מִשּׁוּם שֶׁנֹּגַהּ לוֹ סָבִיב, צַד שֶׁל קְדֻשָּׁה שֶׁל אֱמוּנָה יֵשׁ לוֹ, וְלֹא צָרִיךְ לִנְהֹג בּוֹ קָלוֹן, וְלָכֵן צָרִיךְ לָתֵת לוֹ חֵלֶק בְּצַד הַקְּדֻשָּׁה שֶׁל הָאֱמוּנָה."],[3,"","רַב הַמְנוּנָא סָבָא כָּךְ אָמַר, וְכִי נֹגַהּ לוֹ סָבִיב, וְצָרִיךְ לִנְהֹג בּוֹ קָלוֹן, הַנֹּגַהּ לוֹ הַזֶּה הוּא בִּפְנִים, וְלֹא עוֹמֵד בַּחוּץ. וּמִשּׁוּם שֶׁהַנֹּגַהּ לוֹ הַזֶּה עוֹמֵד בִּפְנִים, כָּתוּב וּמִתּוֹכָהּ כְּעֵין הַחַשְׁמַל מִתּוֹךְ הָאֵשׁ. מִתּוֹכָהּ שֶׁל מִי? מִתּוֹכָהּ שֶׁל אוֹתוֹ נֹגַהּ. כְּעֵין הַחַשְׁמַל - חָשׁ מָל, הֲרֵי פֵּרְשׁוּהָ, חַיּוֹת שֶׁל אֵשׁ מְמַלְּלוֹת."],[4,"","אֲבָל מֵהַמְּנוֹרָה הַקְּדוֹשָׁה שָׁמַעְתִּי עָלֶיהָ סוֹד הַסּוֹדוֹת. כְּשֶׁעָרְלָה שׁוֹרָה עַל הַבְּרִית הַקְּדוֹשָׁה לְטַמֵּא אֶת הַמִּקְדָּשׁ, אָז אוֹתוֹ מִקְדָּשׁ מִתְעַכֵּב מִלְּגַלּוֹת אֶת סוֹד אוֹת הַבְּרִית מִתּוֹךְ הָעָרְלָה, וּכְשֶׁהַנֹּגַהּ הַזֶּה נִכְנָס פְּנִימָה וּמַפְרִיד בֵּין הָעָרְלָה לְבֵין הַמִּקְדָּשׁ, אָז נִקְרָא חַשְׁמַל, חָשׁ וְנִגְלֶה, מָל. מַה זֶּה מָל? כְּמוֹ שֶׁנֶּאֱמַר (יהושע ה) מָל יְהוֹשֻׁעַ. סוֹד שֶׁל אוֹת בְּרִית מִתְעַכֵּב מִלְּהִתְגַּלּוֹת מִתּוֹךְ עָרְלָה."],[5,"","וְיִשִׁ סוֹד אַחֵר, שֶׁהֲרֵי אוֹרוֹ נִרְאֶה וְלֹא נִרְאֶה, וּכְשֶׁמִּתְגַּלֶּה חַשְׁמַל, מָעֳבָר אוֹרוֹ. אֲבָל הַסּוֹד הָרִאשׁוֹן הוּא בְּסוֹד הַכָּתוּב כָּרָאוּי, וְהַכֹּל הוּא יָפֶה, וְנָאֶה הוּא."],[6,"","בַּנֹּגַהּ הַזֶּה מְפַתֶּה אֶת הָאִשָּׁה לִטֹּל אֶת אוֹרָהּ, וְעַל כֵּן כָּתוּב, (משלי ה) וְחָלָק מִשֶּׁמֶן חִכָּהּ. שָׂם אֶת אוֹתוֹ הָאוֹר כְּנֶגֶד הַבְּרִית, וּמִשּׁוּם כָּךְ מְפַתֶּה אוֹתָהּ וְנוֹטֶלֶת אֶת אוֹרוֹ. וְזֶהוּ הַפִּתּוּי שֶׁמְּפַתֶּה אֶת הָאִשָּׁה, שֶׁכָּתוּב נֹפֶת תִּ פְנָה שִׂפְתֵי זָרָה וְגוֹ'."],[7,"","בֹּא וּרְאֵה, בַּיּוֹם הַשִּׁשִּׁי כְּשֶׁמַּגִּיעַ זְמַן הָעֶרֶב, קוֹפֵץ בִּפְנִים אוֹתוֹ (מדורת) אוֹר הָאֵשׁ, וְעוֹלָה לְמַעְלָה לְהִכָּנֵס לְתוֹךְ הַגְּוָנִים. אָז מִתְתַּקְּנִים יִשְׂרָאֵל לְמַטָּה, וּמְסַדְּרִים סְעוּדוֹת וּמַתְקִינִים שֻׁלְחָנוֹת, כָּל אֶחָד וְאֶחָד אֶת שֻׁלְחָנוֹ. אָז שַׁלְהֶבֶת אַחַת יוֹצֵאת וּמַכָּה בְּאוֹתָהּ מְדוּרָה. כֵּיוָן שֶׁמַּכָּה בָּהּ, מִתְגַּלְגְּלוֹת אוֹתָהּ שַׁלְהֶבֶת וְאוֹתָהּ מְדוּרָה, וְנִכְנָסוֹת לְנֶקֶב תְּהוֹם רַבָּה, וְנִטְמָנוֹת שָׁם וְיוֹשְׁבוֹת שָׁם."],[8,"","וְאוֹתָהּ שַׁלְהֶבֶת הִיא מִצַּד הַיָּמִין, וּמִשּׁוּם שֶׁהִיא מִצַּד הַיָּמִין, מַעֲבִירָה אֶת אוֹתָהּ מְדוּרָה, וּמַכְנִיסָה אוֹתָהּ לְנֶקֶב תְּהוֹם רַבָּה, וְיוֹשֶׁבֶת שָׁם עַד צֵאת הַשַּׁבָּת. כֵּיוָן שֶׁיּוֹצֵאת הַשַּׁבָּת, צָרִיךְ לְעַם יִשְׂרָאֵל לְבָרֵךְ עַל הָאֵשׁ, וְיוֹצֵאת אוֹתָהּ שַׁלְהֶבֶת בַּבְּרָכָה שֶׁלְּמַטָּה, וְשׁוֹלֶטֶת עַל אוֹתָהּ מְדוּרָה כָּל אוֹתוֹ הַלַּיְלָה, וְנִכְנַעַת אוֹתָהּ מְדוּרָה."],[9,"","בֹּא וּרְאֵה, כֵּיוָן שֶׁנִּכְנֶסֶת שַׁבָּת וְנִטְמֶנֶת אוֹתָהּ מְדוּרָה, כָּל הָאִשִּׁים שֶׁל הָאֵשׁ הַקָּשָׁה נִטְמָנוֹת וְנִכְנָעוֹת, וַאֲפִלּוּ אֵשׁ הַגֵּיהִנֹּם וְהָרְשָׁעִים שֶׁבַּגֵּיהִנֹּם יֵשׁ לָהֶם מְנוּחָה, וְכֻלָּם מַעְלָה וּמַטָּה יֵשׁ לָהֶם מְנוּחָה. כְּשֶׁיּוֹצֵאת שַׁבָּת וְיִשְׂרָאֵל מְבָרְכִים עַל הָאֵשׁ, אָז יוֹצְאִים כָּל הָאִשִּׁים שֶׁטְּמוּנִים, כָּל אֶחָד וְאֶחָד לִמְקוֹמוֹ. וּכְדֵי שֶׁלֹּא לְעוֹרֵר אֵשׁ אַחֶרֶת, כָּתוּב לֹא תְבַעֲרוּ אֵשׁ בְּכֹל מֹשְׁבֹתֵיכֶם בְּיוֹם הַשַּׁבָּת, וַהֲרֵי פֵּרְשׁוּהָ, וְאֵשׁ הַמִּזְבֵּחַ לָמָּה?"],[10,"","הִתְתַּקְּנוּ מֶרְכָּבוֹת, הִתְתַּקְּנוּ מַחֲנוֹת כְּנֶגֶד רִבּוֹנְכֶם. אָז יוֹצֵאת רוּחַ אַחַת מִצַּד הַדָּרוֹם, וְאוֹתָהּ רוּחַ נִפְרֶשֶׁת עַל כָּל אוֹתָם חֲיָלוֹת וּמַחֲנוֹת שֶׁל צַד יָמִין, וּמִתְלַבְּשׁוֹת בּוֹ, וְאוֹתָהּ רוּחַ נִקְרֵאת לְבוּשׁ כָּבוֹד שֶׁל שַׁבָּת. אָז הַשֻּׁלְחָנוֹת שֶׁל הָעוֹלָם הַזֶּה מְתֻקָּנוֹת בְּהֵיכָל אֶחָד. אַשְׁרֵי חֶלְקוֹ שֶׁל אוֹתוֹ אָדָם שֶׁסִּדּוּר שֻׁלְחָנוֹ נִרְאֶה שָׁם כָּרָאוּי, וְהַכֹּל עוֹמֵד מְתֻקָּן בְּלִי בוּשָׁה, אִישׁ כְּפִי כֹחוֹ."]]],[["כַּד עָאל שַׁבְּתָא, אִצְטְרִיכוּ אִינּוּן עַמָּא קַדִּישָׁא לְאַסְחָאָה גַּרְמַיְיהוּ (קל\"ו ע\"ב) מִשִּׁמוּשָׁא דְּחוֹל, מַאי טַעֲמָא. בְּגִין דִּבְחוֹל, רוּחָא אַחֲרָא אַזְלָא וְשַׁטְיָא וְשָׁרָא עַל עַמָּא. וְכַד בָּעֵי בַּר נָשׁ לְנָפְקָא מִן הַהוּא רוּחָא, וּלְאַעֲלָא בְּרוּחָא אַחֲרָא קַדִּישָׁא עִלָּאָה, בָּעֵי לְאַסְחָאָה גַּרְמֵיהּ, לְמִשְׁרֵי עָלֵיהּ הַהוּא רוּחָא עִלָּאָה קַדִּישָׁא.","תָּא חֲזֵי רָזָא עִלָּאָה דְּמִלָּה, כָּל אִינּוּן שִׁית יוֹמִין, (קימא מלה דכלא) אִתְאַחֲדָן בְּרָזָא דְּחָד נְקוּדָה קַדִּישָׁא, וְכֻלְּהוּ יוֹמִין אִתְאַחֲדָן בֵּיהּ. וְאִית יוֹמִין אַחֲרָנִין, דְּקַיְימִין לְבַר בְּסִטְרָא אַחֲרָא. וְאִית יוֹמִין אַחֲרָנִין, דְּקַיְימִין לְגוֹ (הקדמה ה' ע\"ב) מֵעִגּוּלָא קַדִּישָׁא, וְאִתְאַחֲדָן בִּנְקוּדָה קַדִּישָׁא.","וְיִשְׂרָאֵל קַדִּישִׁין, וְכָל אִינּוּן דְּמִתְעַסְּקִין בִּקְדוּשָּׁה, כָּל יוֹמָא דְּשַׁבְּתָא, אִתְאַחֲדָן כָּל אִינּוּן שִׁית יוֹמִין, בְּאִינּוּן שִׁית יוֹמִין דִּלְגוֹ דְּאִתְאַחֲדָן בְּהַהִיא נְקוּדָה, אִתְאַחֲדָן בְּהַאי, בְּגִין לְנַטְרָא לוֹן. וְכָל אִינּוּן שִׁית יוֹמִין (ד\"א ואינון שית יומין דלגו) דְּשַׁבְּתָא, הַהִיא נְקוּדָה טְמִירָא אִיהִי. כֵּיוָן דְּעָאל שַׁבְּתָא, כְּדֵין סַלְּקָא הַהִיא נְקוּדָה, וְאִתְעַטְּרָא וְאִתְאַחֲדָא לְעֵילָּא, וְכֻלְּהוּ טְמִירִין בְּגַוָּהּ.","תָּא חֲזֵי, אִית יָמִים וְאִית יָמִים. יְמֵי חוֹל, כְּמָה דְּאִתְּמַר, וְאִלֵּין קַיְּימִין לְבַר לְעַמִּין. יְמֵי הַשַּׁבָּת, דְּאִינּוּן יְמֵי הַשָׁבוּעַ, קַיְּימִין לְיִשְׂרָאֵל. וְכַד סַלְּקָא הַאי נְקוּדָה, כֹּלָּא אִתְגְּנִיז, וְאִיהִי סַלְּקָא, כֵּיוָן דְּאִיהִי סַלְּקָא, אִקְרֵי שַׁבָּת.","מַהוּ שַׁבָּת. אִי תֵּימָא בְּגִין שְׁבִיתָה, דִּכְתִּיב כִּי בוֹ שָׁבַת, יָאוּת הוּא. אֲבָל רָזָא דְּמִלָּה, כֵּיוָן דְּסַלְּקָא הַאי נְקוּדָה, וּנְהוֹרָא נָהִיר, כְּדֵין מִתְעַטְּרָא אִיהִי בַּאֲבָהָן, כֵּיוָן דְּמִתְעַטְּרָא אִיהִי בַּאֲבָהָן, כְּדֵין אִתְחַבְּרַת וְאִתְאַחֲדַת בְּהוּ, לְמֶהוֵי חַד, וְאִקְרֵי כֹּלָּא שַׁבָּת. שַׁבָּת: ש' בַּת. ש' הָא אוּקְמוּהָ, רָזָא דִּתְלַת אֲבָהָן, דְּמִתְאַחֲדָן בְּבַת יְחִידָה, וְאִיהִי מִתְעַטְּרָא בְּהוּ, וְאִינּוּן בְּעָלְמָא דְּאָתֵי. וְכֹלָּא אִיהוּ חַד. וְדָא אִיהוּ ש' בַּת, לְמֶהֱוֵי כֹּלָּא חַד.","וְאִי תֵּימָא, שַׁבָּת הַגָּדוֹל, וְאִיהוּ לְעֵילָּא, אֲמַאי אִקְרֵי שַׁבָּת. אֶלָּא וַדַּאי הָכִי הוּא. וְרָזָא דְּמִלָּה, בְּכָל אֲתָר נְקוּדָה דְּאִיהִי עִקָּרָא דְּכָל עֵינָא, אִקְרֵי בַּת. כְּמָה דְאַתְּ אָמֵר, (תהילים י״ז:ח׳) שָׁמְרֵנִי כְּאִישׁוֹן בַּת עָיִן, בְּגִין דְּאִיהִי (נקודה) עִקָּרָא דְּכָל עֵינָא, אִקְרֵי בַּת.","עָלְמָא דְּאָתֵי, אִיהוּ (ק\"פ ע\"א) הֵיכָלָא לְהַהִיא נְקוּדָה עִלָּאָה, וְכַד אִיהִי קַיְּימָא, וְנַטְלָא בְּגַדְפָּהָא לַאֲבָהָן, לְאִתְעַטְּרָא לְעֵילָּא אִקְרֵי כֹּלָּא שַׁבָּת. וְכַד אֲבָהָן מִתְעַטְּרָן לְעֵילָּא, בְּגוֹ נְקוּדָה עִלָּאָה, אִקְרֵי שַׁבָּת. נְקוּדָה תַּתָּאָה (ע' ע\"ב) כַּד מִתְעַטְּרָא בַּאֲבָהָן אִקְרֵי שַׁבָּת.","הַאי נְקוּדָה תַּתָּאָה כַּד סַלְּקָא וְאִתְחַזִית, וְאִתְקַשִּׁיטַת. (ס\"א האי נקודה תתאה כד סלקא לאתעטרא באבהן) כְּדֵין כָּל חֶדְוָה אִשְׁתְּכַח לְעֵילָּא וְתַתָּא, וְעָלְמִין כֻּלְּהוּ בְּחֶדְוָה. וּבְהַאי לֵילְיָא, הַאי נְקוּדָה אִתְפָּשַׁט נְהוֹרָאָה, וּפָרִישׂ גַּדְפּוֹי עַל עָלְמָא, וְכָל שִׁלְטוֹנִין אַחֲרָנִין מִתְעַבְּרָן, וּנְטִירוּ אִשְׁתְּכַח עַל עָלְמָא.","וּכְדֵין אִתּוֹסָף רוּחַ נִשְׁמְתָא בְּיִשְׂרָאֵל, עַל כָּל חַד וְחַד, וּבְהַהִיא נִשְׁמְתָא יְתֵירָא, נַשְׁיָין כָּל עִצְבָּא וְחֵימָתָא, וְלָא אִשְׁתְּכַח בַּר חֶדְוָה, לְעֵילָּא וְתַתָּא. הַהוּא רוּחָא דְּנָחִית וְאִתּוֹסַף בִּבְנֵי עָלְמָא, כַּד נָחִית, אִתְסָחֵי בְּבוּסְמִין דְּגִּנְתָּא דְּעֵדֶן, וְנָחִית וְשָׁרָא עַל עַמָּא קַדִּישָׁא, זַכָּאִין אִינּוּן, כַּד הַאי רוּחָא אִתְעָר.","בְּהַהִיא שַׁעֲתָא דְּהַהוּא רוּחָא נָחִית נַחְתִּין עִמָּהּ לְגוֹ גִּנְתָּא דְּעֵדֶן, שִׁתִּין רְתִיכִין, מִתְעַטְּרִין לְשִׁית סִטְרִין. וְכַד מָטֵי לְגִנְתָּא דְּעֵדֶן, כְּדֵין כָּל אִינּוּן רוּחִין וְנִשְׁמָתִין דְּגִּנְתָּא דְּעֵדֶן, כֻּלְּהוּ (מתערי לההוא מתעטרי (נ\"א בההוא)) רוּחָא. כְּרוּזֵי קָרֵי וְאָמַר, זַכָּאִין אַתּוּן יִשְׂרָאֵל, עַמָּא קַדִּישָׁא, דִּרְעוּתָא דְּמָארִיכוֹן אִתְּעַר לְגַּבַּיְיכוּ."],[[0,"כד עאל שבתא וכו':","כשבא השבת, צריכים עם קדוש לרחוץ עצמם משמוש של חול. מה הטעם. הוא משום שבחול רוח אחר הולך ומשוטט ושורה על העם, וכשאדם רוצה לצאת מרוח ההוא, ולבא ברוח אחר קדוש עליון, הוא צריך לרחוץ עצמו, שישרה עליו רוח עליון הקדוש ההוא."],[1,"ת\"ח רזא עלאה וכו':","בוא וראה סוד עליון של הדבר. כל אלו ששה ימים, חג\"ת נה\"י דז\"א, מתאחדים בסוד נקודה אחת קדושה, שהיא המלכות, וכל הימים התאחדו בה. ויש ימים אחרים העומדים בחוץ בסטרא אחרא. דהיינו חג\"ת נה\"י דקליפות. ויש ימים אחרים העומדים בפנים מעגול הקדוש, שהם חג\"ת נה\"י דמלכות, ומתאחדים בנקודה הקדושה שהיא המלכות דמלכות."],[2,"וישראל קדישין וכל וכו':","וישראל הקדושים וכל אלו העוסקים בקדושה, בכל ימי השבת, מתאחדים כל אלו ששת הימים שלהם, באלו ששת ימים שבפנים, שהם חג\"ת נה\"י דמלכות, המתאחדים בנקודת המלכות דמלכות, ומתאחדים בה כדי לשמרה, וכל אלו ששת ימי השבת, הם של נקודה הנסתרת ההיא. שהם חג\"ת נה\"י דמלכות. כיון שבא השבת אז עולה נקודה ההיא, שהיא המלכות דמלכות, ומתעטרת ומתאחדת למעלה וכולם נסתרים בה."],[2,"","פירוש. המלכות, שנקראת נקודה, מקבלת מז\"א ששת ימים שבו, הנקראים חג\"ת נה\"י. וא\"כ יש בה ב' בחינות, א' חג\"ת נה\"י שקבלה מז\"א. ב' היא בחינתה עצמה, דהיינו המלכות. וההפרש ביניהם הוא, כי חג\"ת נה\"י שקבלה מז\"א, ה\"ס אור החסדים. ובחינתה עצמה, הנקראת נקודה, ה\"ס אור החכמה. ולפיכך ששת ימי המעשה, הם בחינת חג\"ת נה\"י דמלכות, שקבלה מז\"א, ושבת, היא בחינת שליטת נקודתה עצמה, ובחינת ששת ימי המעשה, שהם חג\"ת נה\"י שלה, הם נסתרים בה, כלומר שאינם שולטים ואינם נראים, ורק המלכות מבחינתה עצמה היא השולטת. והיא הנראית."],[3,"ת\"ח אית ימים וכו':","בוא וראה, יש ימים ויש ימים, יש ימי חול, כמו שלמדנו לעיל, שהם חג\"ת נה\"י דס\"א, והם עומדים לחוץ, אל העמים. ימי השבת, שהם ששת ימי השבוע, עומדים לישראל, שהם חג\"ת נה\"י דמלכות כנ\"ל. וכשעולה נקודה הזו, שהיא מלכות דמלכות, דהיינו המלכות מבחינתה עצמה, הכל נגנז, דהיינו כל שש הספירות חג\"ת נה\"י שבה נגנזות והיא עולה, כנ\"ל בדבור הסמך, כיון שהיא עולה, נקראת שבת."],[4,"מהו שבת וכו':","שואל, מהו שבת. דהיינו למה נקראת בשם שבת. אם תאמר משום השביתה, שכתוב, כי בו שבת, יפה הוא. אלא סוד הדבר, כיון שעלתה נקודה זו ואורה מאיר, אז היא מתעטרת באבות, שהם חג\"ת דז\"א, כיון שהיא מתעטרת באבות, אז היא מתחברת ומתאחדת בהם להיות אחד, ונקרא הכל שבת, דהיינו המלכות עם האבות ביחד נקראים שבת, \u0003שבת,\u0004 היא אותיות \u0003ש' בת, ש'\u0004 הרי העמידוה שה\"ס שלשה אבות המתאחדים בבת יחידה שהיא המלכות, כי ג' ווין שב \u0003ש'\u0004 רומזים על ג' אבות, חג\"ת. והיא שנקראת \u0003בת\u0004 מתעטרת בהם. והם, האבות מתעטרים בעולם הבא, שהיא בינה. והכל הוא אחד. וזהו \u0003ש' בת,\u0004 שיהיו הכל אחד."],[4,"","פירוש. אין המלכות מקבלת חכמה אלא בעלותה מחזה ולמעלה דז\"א, ששם חג\"ת שלו, ויש בזה ב' מצבים, א) כשהוא בסוד ב' מאורות הגדולים. (כנ\"ל בראשית א' דף ק\"ד ד\"ה את ע\"ש) שאז קומתם שוה, באופן שאין זה צריך לזה ואין מקבלים זה מזה, חג\"ת דז\"א מקבלים מקו ימין דאמא, דהיינו חסדים. והמלכות מקבלת מקו שמאל דאמא, דהיינו חכמה. ומצב הזה נבחן לאחורים, כי החכמה להיותה לבדה בלי חסדים אינה מאירה כמ\"ש שם. ומצב ב' הוא, שכבר ירדה המלכות לבחינת מחזה ולמטה דז\"א, שאז מקבלת חסדים, ואחר שיש לה חסדים, הז\"א מעלה אותה לחג\"ת שלו, ששם מאיר השם ע\"ב דויסע ויבא ויט, ומקבלת מהם חכמה. ומצב זה נבחן למוחין דפנים בפנים."],[4,"","וזה אמרו, \u0003כיון דסלקא האי נקודה, ונהורא נהיר,\u0004 כיון שעולה לחג\"ת אחר שאור החסדים מאיר בה, דהיינו במצב ב' דפב\"פ, \u0003כדין מתעטרא איהי באבהן,\u0004 וכו', דהיינו שמקבלת מהם חכמה מהשם ע\"ב שבהם, \u0003כדין אתחברת ואתאחדת בהו למהוי חד.\u0004 דהיינו לא כמצב הא' דאחורים, שהיו נפרדים זה מזה, שחג\"ת היו מקבלים חסדים מקו ימין דאמא, והמלכות היתה מקבלת חכמה מקו שמאל דאמא, אלא עתה במצב הב' היא מתחברת ומתאחדת עם החג\"ת להיות עמהם אחד, וז\"ש \u0003ואיהי מתעטרא בהו,\u0004 בחג\"ת, \u0003ואינון,\u0004 החג\"ת, מתעטרים \u0003בעלמא דאתי\u0004 כלומר שעתה אין המלכות עצמה מקבלת החכמה מעולם הבא, שהוא בינה, כמו במצב הא', אלא המלכות מקבלת החכמה מחג\"ת דז\"א. והחג\"ת, הם המקבלים החכמה מעולם הבא, ומשפיעים למלכות. וז\"ש, \u0003ודא איהו ש' בת, למהוי כלא חד.\u0004 דע\"כ מרומזים האבות, שה\"ס \u0003ש',\u0004 והמלכות שה\"ס \u0003בת,\u0004 בשם אחד \u0003שבת,\u0004 להורות, שהם עתה במצב הב', אחד, ולא נפרדים במצב הא'. וז\"ס \u0003שבת.\u0004"],[5,"ואי תימא שבת וכו':","ואם תאמר, שבת הגדול, שהוא בינה הנקראת ג\"כ שבת, והיא למעלה, ששם החכמה נסתרת ואינה מגולה, למה נקראת היא \u0003שבת.\u0004 ומשיב, אלא ודאי כך הוא, שנקראת שבת, וסוד הדבר, כי נקודה, בכל מקום שהיא היא עיקר העין, כלומר, שיש בה חכמה המכונה עינים, היא נקראת \u0003בת,\u0004 כמש\"א שמרני כאישון בת עין, כי משום שהיא העיקר של כל העין, היא נקראת בת. פירוש. ג' גוונין יש בעין שהם חג\"ת, וגוון הד' היא נקודה שחורה, שהיא המלכות, ובה לבד מתגלה החכמה הנקראת עין, ע\"כ היא העיקר של כל גווני העין."],[6,"עלמא דאתי איהו וכו':","עולם הבא, שהוא בינה, היא היכל לנקודה ההיא העליונה, דהיינו לחכמה העליונה. וכשהיא עומדת ולוקחת בכנפיה את האבות, לעטרם למעלה, אז נקראים הכל \u0003שבת.\u0004 באופן, כשהאבות מתעטרים למעלה בנקודה העליונה, נקראים \u0003שבת,\u0004 וכשהנקודה התחתונה, מלכות, מתעטרת באבות, נק' \u0003שבת.\u0004"],[6,"","פירוש. נקודה רומזת תמיד על חכמה, והרמז היא על נקודה השחורה שבעין, הנקראת ג\"כ בת עין, שהיא העיקר הראויה להקרא בשם עין, שהוא חכמה. משום ששאר ג' גוונים שבעין, ה\"ס חג\"ת, שאין החכמה המכונה ראיה מתגלית בהם. לפיכך יש בפרצופי אצילות ב' פרצופים המכונים בשם נקודה, א', היא \u0003חכמה עלאה,\u0004 שהם או\"א. ב' \u0003חכמה תתאה,\u0004 שהיא המלכות. אמנם אע\"פ שאו\"א הם חכמה עלאה, אינם מגלים החכמה בפרצופם עצמם, (כנ\"ל ב\"א דף רנ\"א ד\"ה נחית), אלא בפרצוף ישסו\"ת, שהם נקראים \u0003בינה.\u0004"],[6,"","וז\"ש \u0003עלמא דאתי איהו היכלא לההיא נקודה עלאה,\u0004 שהבינה, שה\"ס ישסו\"ת הם היכל לנקודה העליונה שה\"ס או\"א. כלומר, שאין או\"א מגלים החכמה שבהם אלא בסוד ההיכל שהוא בינה. אמנם גם בבינה אין החכמה מתגלה אלא על ג' קוין שהם חג\"ת המכונים \u0003אבות.\u0004 ונמצא שנקודה עליונה אינה מגלה החכמה שבה אלא לבינה, כשהיא מעטרת ומשפעת חכמה בג' קוין שלה שהם האבות."],[6,"","וז\"ש \u0003וכד איהי קיימא ונטלא בגדפהא לאבהן לאתעטרא לעילא,\u0004 דהיינו שהבינה מקבלת ג' קוין שהם האבות לעטר אותם בחכמה עליונה, \u0003אקרי כלא שבת,\u0004 כי נקודה עלאה, שה\"ס חכמה עליונה המתגלית על האבות נקראת \u0003בת,\u0004 והאבות עצמם נק' \u0003ש,\u0004 וביחד הם \u0003שבת.\u0004 ונמצא \u0003וכד אבהן ממעטרן לעילא בגו נקודה עלאה, הם נקראים ביחד שבת. ונקודה תתאה,\u0004 מלכות, \u0003כד מתעטרא,\u0004 שמקבלת חכמה, \u0003באבהן, אקרי שבת.\u0004 כי שבת, כולל בתוכה הארת החכמה הנקראת \u0003בת\u0004 והארת האבות הנק' \u0003ש'.\u0004 שזה נוהג הן בבינה והן במלכות, וע\"כ נקראים שניהם שבת."],[7,"האי נקודה תתאה","וכו': נקודה התחתונה הזו, שהיא מלכות, כשעולה ונראית, דהיינו שמקבלת חכמה, הנקראת ראיה, ומתקשטת במוחין העליונים, אז כל חדוה נמצאת למעלה ולמטה, והעולמות כולם הם בשמחה. ובלילה הזה של שבת, מתפשטת נקודה הזו באורותיה, ופורשת כנפיה על העולם, וכל שליטים אחרים נעברים, ושמירה נמצאת על העולם."],[8,"וכדין אתוסף רוח וכו':","ואז נתוסף רוח הנשמה בישראל, על כל אחד ואחד, ובנשמה יתירה ההוא שוכחים כל עצב וחימה, ולא נמצא למעלה ולמטה רק שמחה. רוח ההוא שירד ונתוסף בבני העולם, כשיורד, הוא מתרחץ בבשמים של גן העדן, ויורד ושורה על עם הקדוש, אשריהם כשהרוח ההוא נתעורר."],[9,"בההיא שעתא דההוא וכו':","בשעה ההיא, שרוח ההוא יורד, יורדין עמו לגן עדן, ששים מרכבות המתעטרים לששה קצוות, חג\"ת נה\"י. שכל אחד כולל עשר, הם ששים. וכשמגיע לגן עדן, אז כל אלו רוחות ונשמות שבגן עדן, כולם מתעטרים ברוח ההוא. הכרוז קורא ואומר, אשריכם ישראל עם קדוש שרצון אדונכם נתעורר אליכם."]],[[0,"","כְּשֶׁנִּכְנֶסֶת שַׁבָּת, צְרִיכִים אוֹתוֹ עַם קָדוֹשׁ לִרְחֹץ עַצְמָם מִשִּׁמּוּשׁ הַחֹל. מָה הַטַּעַם? מִשּׁוּם שֶׁבַּחֹל רוּחַ אַחֶרֶת הוֹלֶכֶת וּמְשׁוֹטֶטֶת וְשׁוֹרָה עַל הָעָם, וּכְשֶׁרוֹצֶה אָדָם לָצֵאת מֵאוֹתָהּ רוּחַ וּלְהִכָּנֵס בְּרוּחַ אַחֶרֶת קְדוֹשָׁה עֶלְיוֹנָה, צָרִיךְ לִרְחֹץ עַצְמוֹ כְּדֵי לְהַשְׁרוֹת עָלָיו אוֹתָהּ רוּחַ עֶלְיוֹנָה קְדוֹשָׁה."],[1,"","בֹּא וּרְאֵה הַסּוֹד הָעֶלְיוֹן שֶׁל הַדָּבָר. כָּל אוֹתָם שִׁשָּׁה יָמִים (עומד הדבר של הכל) נֶאֱחָזִים בְּסוֹד שֶׁל נְקֻדָּה קְדוֹשָׁה אַחַת, וְכָל הַיָּמִים אֲחוּזִים בּוֹ. וְיֵשׁ יָמִים אֲחֵרִים שֶׁעוֹמְדִים מִבַּחוּץ בַּצַּד הָאַחֵר, וְיֵשׁ יָמִים אֲחֵרִים שֶׁעוֹמְדִים בִּפְנִים מֵעִגּוּל קָדוֹשׁ, וַאֲחוּזִים בִּנְקֻדָּה קְדוֹשָׁה."],[2,"","וְיִשְׂרָאֵל קְדוֹשִׁים, וְכָל אֵלּוּ שֶׁמִּתְעַסְּקִים בַּקְּדֻשָּׁה, כָּל יְמֵי הַשָּׁבוּעַ, נֶאֱחָזִים כָּל אֵלּוּ הַשִּׁשָּׁה יָמִים, בְּאֵלּוּ הַשִּׁשָּׁה יָמִים שֶׁבִּפְנִים שֶׁמְּאֻחָדִים בַּנְּקֻדָּה הַהִיא, נֶאֱחָזִים בָּזוֹ כְּדֵי לִשְׁמֹר אוֹתָם, וְכָל אוֹתָם שֵׁשֶׁת יְמֵי (ואותם ששה ימים שבפנים) הַשַּׁבָּת אוֹתָהּ נְקֻדָּה הִיא נִסְתֶּרֶת. כֵּיוָן שֶׁנִּכְנֶסֶת שַׁבָּת, אָז עוֹלָה אוֹתָהּ נְקֻדָּה וּמִתְעַטֶּרֶת וְנֶאֱחֶזֶת לְמַעְלָה, וְכֻלָּם טְמוּנִים בְּתוֹכָהּ."],[3,"","בֹּא וּרְאֵה, יֵשׁ יָמִים וְיֵשׁ יָמִים. יְמֵי חֹל, כְּמוֹ שֶׁנֶּאֱמַר, וְאֵלֶּה עוֹמְדִים מִחוּץ לָעַמִּים. יְמֵי הַשַּׁבָּת, שֶׁהֵם יְמֵי הַשָּׁבוּעַ, עוֹמְדִים לְיִשְׂרָאֵל. וּכְשֶׁעוֹלָה הַנְּקֻדָּה הַזּוֹ, הַכֹּל נִגְנָז, וְהִיא עוֹלָה. כֵּיוָן שֶׁהִיא עוֹלָה, אָז נִקְרֵאת שַׁבָּת."],[4,"","מַה זֶּה שַׁבָּת? אִם תֹּאמַר בִּשְׁבִיל שְׁבִיתָה, שֶׁכָּתוּב כִּי בוֹ שָׁבַת - יָפֶה הוּא. אֲבָל סוֹד הַדָּבָר - כֵּיוָן שֶׁעוֹלָה הַנְּקֻדָּה הַזּוֹ וְהָאוֹר מֵאִיר, אָז הִיא מִתְעַטֶּרֶת בָּאָבוֹת. כֵּיוָן שֶׁהִיא מִתְעַטֶּרֶת בָּאָבוֹת, אָז מִתְחַבֶּרֶת וְנֶאֱחֶזֶת בָּהֶם לִהְיוֹת אֶחָד, וְהַכֹּל נִקְרָא שַׁבָּת. שַׁבָּת - ש' בַּת. ש' הֲרֵי פֵּרְשׁוּהָ, הַסּוֹד שֶׁל שְׁלֹשָׁה אָבוֹת שֶׁנֶּאֱחָזִים בְּבַת יְחִידָה, וְהִיא מִתְעַטֶּרֶת בָּהֶם, וְהֵם בָּעוֹלָם הַבָּא, וְהַכֹּל אֶחָד הוּא. וְזֶהוּ ש' בַּת, לִהְיוֹת הַכֹּל אֶחָד."],[5,"","וְאִם תֹּאמַר, שַׁבָּת הַגָּדוֹל, וְהוּא לְמַעְלָה, לָמָּה נִקְרָא שַׁבָּת? אֶלָּא וַדַּאי כָּךְ הוּא. וְסוֹד הַדָּבָר - בְּכָל מָקוֹם הַנְּקֻדָּה, שֶׁהִיא עִקָּר שֶׁל כָּל הָעַיִן, נִקְרֵאת בַּת, כְּמוֹ שֶׁנֶּאֱמַר (תהלים יז) שָׁמְרֵנִי כְּאִישׁוֹן בַּת עָיִן, מִשּׁוּם שֶׁהִיא (נקדה) הָעִקָּר שֶׁל כָּל הָעַיִן, וְהִיא נִקְרֵאת בַּת."],[6,"","הָעוֹלָם הַבָּא הוּא הֵיכָל לְאוֹתָהּ נְקֻדָּה עֶלְיוֹנָה, וּכְשֶׁהִיא עוֹמֶדֶת וְנוֹטֶלֶת בִּכְנָפֶיהָ אֶת הָאָבוֹת לְהִתְעַטֵּר לְמַעְלָה, הַכֹּל נִקְרָא שַׁבָּת. וּכְשֶׁהָאָבוֹת מִתְעַטְּרִים לְמַעְלָה בְּתוֹךְ הַנְּקֻדָּה הָעֶלְיוֹנָה, נִקְרָא שַׁבָּת. וּכְשֶׁנְּקֻדָּה תַּחְתּוֹנָה מִתְעַטֶּרֵת בָּאָבוֹת, נִקְרָא שַׁבָּת."],[7,"","כְּשֶׁהַנְּקֹֻדָּה הַתַּחְתּוֹנָה הַזּוֹ עוֹלָה, וְנִרְאֵית וּמִתְקַשֶּׁטֶת, (אותה נקדה תחתונהכאשרעולהלהתעטרבאבות) אָז כָּל הַשִּׂמְחָה נִמְצֵאת לְמַעְלָה וּלְמַטָּה, וְכָל הָעוֹלָמוֹת בְּשִׂמְחָה. וּבַלַּיְלָה הַזֶּה הַנְּקֻדָּה הַזּוֹ אוֹרָהּ מִתְפַּשֵּׁט, וּפוֹרֵשׂ כְּנָפָיו עַל הָעוֹלָם, וְכָל הַשַּׁלִּיטִים הָאֲחֵרִים מָעֳבָרִים, וְנִמְצֵאת שְׁמִירָה עַל הָעוֹלָם."],[8,"","וְאָז נוֹסֶפֶת רוּחַ נְשָׁמָה בְּיִשְׂרָאֵל לְכָל אֶחָד וְאֶחָד, וּבְאוֹתָהּ נְשָׁמָה יְתֵרָה שׁוֹכְחִים כָּל הָעֶצֶב וְהַחֵמָה, וּכְלוּם לֹא נִמְצָא פְּרָט לַשִּׂמְחָה לְמַעְלָה וּלְמַטָּה. אוֹתָהּ רוּחַ שֶׁיּוֹרֶדֶת וְנוֹסֶפֶת בִּבְנֵי הָעוֹלָם, כְּשֶׁיּוֹרֶדֶת, רוֹחֶצֶת בַּבְּשָׂמִים שֶׁל גַּן עֵדֶן, וְיוֹרֶדֶת וְשׁוֹרָה עַל הָעָם הַקָּדוֹשׁ. אַשְׁרֵיהֶם כְּשֶׁהָרוּחַ הַזּוֹ מִתְעוֹרֶרֶת."],[9,"","בְּאוֹתָהּ שָׁעָה שֶׁאוֹתָהּ רוּחַ יוֹרֶדֶת, יוֹרְדִים עִמָּהּ לְתוֹךְ גַּן הָעֵדֶן שִׁשִּׁים מֶרְכָּבוֹת מְעֻטָּרוֹת לְשִׁשָּׁה צְדָדִים. וּכְשֶׁמַּגִּיעִים לְגַן עֵדֶן, אֲזַי כָּל אוֹתָן הָרוּחוֹת וְהַנְּשָׁמוֹת שֶׁבְּגַן עֵדֶן, כֻּלָּן מִתְעוֹרְרוֹת לְאוֹתָהּ (מתעטרות באותה) רוּחַ. הַכָּרוֹזִים קוֹרְאִים וְאוֹמְרִים: אַשְׁרֵיכֶם יִשְׂרָאֵל, הָעָם הַקָּדוֹשׁ, שֶׁרְצוֹן רִבּוֹנְכֶם מִתְעוֹרֵר אֲלֵיכֶם."]]],[["רָזָא דְּרָזִין לְיַדְעֵי חָכְמְתָא, זַכָּאִין אִינּוּן כַּד הַאי רוּחָא אִתְעָר. הַאי רוּחָא אִיהוּ אִתְפַּשְּׁטוּתָא דְּהַאי נְקוּדָה, וְנָפְקָא מִינָּהּ, וְאִתְפַּשְּׁטָא בְּעָלְמָא, וְהַהוּא הֲוֵי רָזָא דְּשַׁבָּת, דְּשָׁרָא לְתַתָּא, וְעַל דָּא כְּתִיב בֵּיהּ שְׁמִירָה, (שמות ל״א:ט״ז) וְשָׁמְרוּ בְנֵי יִשְׂרָאֵל אֶת הַשַּׁבָּת, וְהָא אוּקְמוּהָ, שַׁבָּת לָא כְּתִיב, אֶלָּא אֶת הַשַּׁבָּת, לְאַסְגָּאָה הַהוּא רוּחָא דְּשָׁרֵי עַל כֹּלָּא, וְאִצְטְרִיךְ לְנַטְרָא לֵיהּ, הוֹאִיל וְקַיְּימָא עִמֵּיהּ דְּבַר נָשׁ, וְעַל דָּא כְּתִיב, (ישעיהו נ״ו:ו׳) כָּל שׁוֹמֵר שַׁבָּת מֵחַלְּלוֹ.","בְּהַאי רָזָא אִית רָזָא אַחֲרָא. הַאי רוּחָא, אִתְהֲנִי בְּהַאי יוֹמָא, מֵהֲנָאוֹתָן דְּיִשְׂרָאֵל, וּמֵעִנּוּגָא דִּלְהוֹן, וּבְגִין דָּא, בָּעֵי לְמֵיהַב לֵיהּ עִנּוּגָא, בְּמֵיכְלָא וּבְמִשְׁתְּיָא, תְּלָת זִמְנִין, בִּתְלַת סְעוּדָתִין, דִּתְלַת דַּרְגֵּי מְהֵימְנוּתָא, כְּמָה דְּאוּקְמוּהָ. וְהַאי נָטִיל חֶדְוָה וְעִנּוּגָא, בְּאִינּוּן סְעוּדָתֵי דְּיִשְׂרָאֵל. זַכָּאָה חוּלָקֵיהּ, מַאן דְּאַהֲנֵי לֵיהּ, וּמְעַנֵג לֵיהּ, בְּהַאי יוֹמָא.","הַאי רוּחָא, אִתְהֲנֵי כָּל שִׁיתָא יוֹמִין, מֵרוּחָא עִלָּאָה דְּעַתִּיקָא דְּכָל עַתִּיקִין. וּבְיוֹמָא דְּשַׁבְּתָא, כֵּיוָן דְּנָחִית, וְאִתְסָחֵי בְּגִנְתָּא דְּעֵדֶן בְּלֵילְיָא, אִתְעַנָּג (ר\"ח ע\"א, צ\"ח ע\"ב) מֵעִנּוּגָא דְּגוּפָא, בִּסְעוּדָתֵי דִּמְהֵימְנוּתָא, וְאִתְעַטָּר (נ\"א ואתענג) הַאי רוּחָא מֵעֵילָּא וְתַתָּא, וְאִתְרַוֵי בְּכָל סִטְרִין, בְּעִטְרָא דִּלְעֵילָּא וְתַתָּא.","וְהוֹאִיל וְקַיְּימָא עִמֵּיהּ דְּבַר נָשׁ, אִצְטְרִיךְ לֵיהּ לְנַטְרָא לֵיהּ. וְעַל דָּא כְּתִיב וְשָׁמְרוּ בְנֵי יִשְׂרָאֵל אֶת הַשַּׁבָּת. שַׁבָּת, דָּא הוּא הַהִיא נְקוּדָה תַּתָּאָה. אֶת הַשַּׁבָּת, דָּא הוּא הַאי רוּחָא, אִתְפַּשְּׁטוּתָא דְּהַהִיא נְקוּדָה. הַהוּא אִתְפַּשְּׁטוּתָא, כַּד אִתּוֹסָף קִדּוּשָׁן וּבִרְכָּאן מִלְּעֵילָּא, עַל הַהִיא נְקוּדָה, אִתְנְהִיר כֹּלָּא, וְאִתְעָבִיד רוּחָא נְהִירָא בְּכָל סִטְרִין, אִתְפְּלַג לְעֵילָּא וְנָהִיר. וְאִתְפְּלַג לְתַתָּא וְנָהִיר. וְדָא הוּא דִּכְתִּיב בֵּינִי וּבֵין בְּנִי יִשְׂרָאֵל חוּלָק אַחֲסָנָא אִית לָן כַּחֲדָא.","חוּלָקָא דִּלְעֵילָּא, אִתְעֲטָּר בְּהַאי יוֹמָא, מֵעִנּוּגָא עִלָּאָה קַדִּישָׁא, וְאִתְהֲנֵי מִזִּיוָא עִלָּאָה דְּעַתִּיקָא דְּכָל עַתִּיקִין. חוּלָקָא תַּתָּאָה, אִתְעֲטָּר בְּהַאי יוֹמָא, מֵעִנּוּגָא דִּלְתַּתָּא, דְּאִתְהֲנֵי בְּהָנֵי סְעוּדָתֵי. וְעַל דָּא, בָּעֵי לְעַנְּגָא לֵיהּ, בְּמֵיכְלָא וּבְמִשְׁתְּיָא בִּלְבוּשֵׁי יְקָר, וּבְחֶדְוָה דְּכֹלָּא.","וְכַד מִתְעַטְּרָא הַאי חוּלָקָא לְתַתָּא, וְאִתְנְטִיר כְּמָה דְּאִצְטְרִיךְ, סַלְּקָא לְעֵילָּא, וְאִתְחַבְּרָא בְּהַהוּא חוּלָקָא אַחֲרָא. וְהַאי נְקוּדָה נָטִיל כֹּלָּא מֵעֵילָּא וְתַתָּא, וְאִתְכְּלִילָא מִכָּל סִטְרִין. וּבְגִין דְּמִתְעַטְּרָא בְּשַׁבָּת, מֵעֵילָּא וּמִתַּתָּא, כָּל שְׁאָר יוֹמִין יָהִיב חֵילָא לְכֹלָּא, וְאִתְיְיהִיב לֵיהּ שׁוּלְטָנוּ מֵעֵילָּא וּמִתַּתָּא. וּבְרָזִין דְּסִפְרָא דִּשְׁלֹמֹה מַלְכָּא, אִשְׁתְּכַח רָזָא דָּא, וְאוּקְמוּהָ בּוּצִינָא קַדִּישָׁא, זַכָּאָה חוּלָקֵיהוֹן דְּיִשְׂרָאֵל.","כְּתִיב וַיִּנָּפַשׁ, וְאוּקְמוּהָ וַוי נֶפֶשׁ דְּאַבְדַת וְשַׁפִּיר אִיהוּ. אֲבָל אִי הָכִי וַוי גּוּפָא אִצְטְרִיךְ לְמֵימַר, דְּמִנֵּיהּ אַבְדַת נֶפֶשׁ. אֲבָל רָזָא דְּמִלָּה, בְּבַר נָשׁ אִית נֶפֶשׁ, דְּנַטְלָא וּמָשִׁיךְ לְגַבֵּיהּ לְהַאי רוּחָא מֵעֶרֶב שַׁבָּת. וְהַהוּא רוּחָא שַׁרְיָא בְּגַוָּוה דְּהַהִיא נֶפֶשׁ, וְדַיְירָא בָּהּ כָּל יוֹמָא דְּשַׁבְּתָא. וּכְדֵין, הַהוּא נֶפֶשׁ, יְתֵירָה בְּרִבּוּיָא וְתוֹעַלְתָּא יַתִּיר מִמַּה דְּהֲוָה.","וְעַל דָּא תָּנִינָן, כָּל נַפְשָׁאן דְּיִשְׂרָאֵל מִתְעַטְּרָן בְּיוֹמָא דְּשַׁבְּתָא, וְעִטְרָא דִּלְהוֹן, דְּשַׁרְיָא הַאי רוּחָא בְּגַּוַּויְיהוּ. כֵּיוָן דְּנָפַק שַׁבְּתָא, וְהַהוּא רוּחָא סַלְּקָא לְעֵילָּא, כְּדֵין וַוי לְנֶפֶשׁ, דְּאַבְדַת מַה דְּאַבְדַת. אַבְדַת הַהוּא עִטְרָא עִלָּאָה, וְהַהוּא חֵילָא קַדִּישָׁא דְּהֲוָה בָּה, וְדָא הוּא וַיִּנָּפַשׁ, וַוי נֶפֶשׁ, דְּאַבְדַת מַה דְּאַבְדַת.","עוֹנָתָן דְּחַכִּימִין, דְּיַדְעֵי רָזִין עִלָּאִין, מִלֵילְיָא דְּשַׁבְּתָא לְלֵילְיָא דְּשַׁבְּתָא, וְאוֹקְמוּהָ. אֲבָל מִלָּה דָּא שָׁאִילְנָא לְבוּצִינָא קַדִּישָׁא, דְּהָא חָזֵינָן דְּהַאי כִּתְרָא תַּתָּאָה, נַקְטָא מַה דְּנַקְטָא בִּימָמָא, וּבְלֵילְיָא יָהִיב מְזוֹנָא לְכָל חֵילֵיהּ, כְּמָה דְּאוּקְמוּהָ, דִּכְתִּיב, (משלי ל״א:ט״ו) וַתָּקָם בְּעוֹד לַיְלָה וַתִּתֵּן טֶרֶף לְבֵיתָהּ וְחֹק לְנַעֲרוֹתֶיהָ. נַקְטָא בִּימָמָא, וְיָהֲבָא בְּלֵילְיָא. וְהַשְׁתָּא אָמַר מַר דְּזִוּוּגָא אִשְׁתְּכַח בְּהַאי לֵילְיָא."],[[0,"רזא דרזין לידעי וכו':","סוד הסודות הוא ליודעי החכמה. אשרי הם כשהרוח הזה נתעורר. רוח הזה הוא התפשטות של נקודה הזו, מלכות, ויוצא ממנה ומתפשט בעולם. ורוח ההוא, הוא סוד השבת השורה למטה. וע\"כ כתוב בו שמירה, ושמרו בני ישראל את השבת. והרי העמידוהו, שבת לא כתוב, אלא \u0003את\u0004 השבת, הוא לרבות רוח ההוא השורה על הכל, וצריכים לשמרו, משום שנמצא עם האדם, וע\"כ כתוב, כל שומר שבת מחללו."],[1,"בהאי רזא אית וכו':","בסוד הזה יש סוד אחר, רוח הזה, נהנה ביום הזה מן ההנאות של ישראל, ומתענוגיהם. ומשום זה צריכים לתת לו עונג במאכל ומשתה ג' פעמים בג' סעודות של ג' מדרגות האמונה. כמו שהעמידוהו (לעיל יתרו אות תנ\"ה תנ\"ו תנ\"ז) ורוח הזה מקבל שמחה ותענוג באלו הסעודות של ישראל. אשרי חלקו מי שמהנהו ומענגו ביום הזה."],[2,"האי רוחא אתהני וכו':","רוח הזה נהנה כל ששת הימים מרוח עליון של עתיק דכל עתיקין. וביום השבת כיון שירד ורחץ בגן עדן בלילה, הוא מתענג מתענוג הגוף בסעודת האמונה, ונתעטר רוח הזה מלמעלה ומלמטה, ומקומו בכל הצדדים, דהיינו בחכמה ובחסדים, בעטרה של מעלה שהוא חסדים ובעטרה של מטה שהיא חכמה."],[3,"והואיל וקיימא עמיה וכו':","וכיון שנמצא עם האדם, צריכים לשמרו, וע\"כ כתוב, ושמרו בני ישראל את השבת. שבת זה, היא נקודה תחתונה, שהיא מלכות. \u0003את\u0004 השבת, זה הוא רוח הזה, שהוא התפשטות של נקודה ההיא, התפשטות ההוא, כשנתוסף קדושה וברכות מלמעלה על נקודה ההיא הואר הכל, וההתפשטות נעשה רוח המאיר מכל הצדדים, חציו מתחלק למעלה ומאיר, וחציו מתחלק למטה ומאיר. וז\"ש ביני ובין בני ישראל, דהיינו שהרוח נתחלק בינו לבין ישראל, חלק ונחלה יש לנו יחד."],[4,"חולקא דלעילא וכו':","החלק של מעלה, התעטר ביום ההוא מעונג העליון הקדוש. ונהנה מזיו העליון של עתיקא דכל עתיקין, שהוא כתר. חלק התחתון, מתעטר ביום ההוא מעונג של מטה, שנהנה באלו הסעודות שעושים ישראל, וע\"כ צריכים לענגו במאכל ובמשתה, בלבושי כבוד, וברוב שמחה."],[5,"וכד מתעטרא האי","וכו': וכשמתעטר חלק ההוא שלמטה, ונשמר כמו שצריך, הוא עולה למעלה, ומתחבר בחלק האחר העליון. ונקודה הזו שהיא מלכות, לוקחת הכל מן הרוח, מחלק שלמעלה ומחלק שלמטה, ונכללת מכל הצדדים. ומשום שמתעטרת בשבת מלמעלה ומלמטה, כל שאר הימים, שהם חג\"ת נה\"י, נותנים כח לכל וניתנה לה, להמלכות, שליטה, מלמעלה ומלמטה. ובסודות ספרו של שלמה המלך נמצא סוד הזה, והעמידו המאור הקדוש, דהיינו ר\"ש. אשרי חלקם של ישראל."],[6,"כתיב וינפש, ואוקמוה וכו':","כתוב, וינפש, והעמידוהו, אוי שאבדה הנפש. והוא יפה. אבל אם כן, אוי לגוף היה צריך לומר שממנו אבדה הנפש ובוינפש, לא נזכרה רק הנפש. ומשיב, אבל סוד הדבר, באדם יש נפש, שמקבלת ומושכת אליה לרוח הזה הנ\"ל, מערב שבת. ורוח הזה שורה בתוך נפש ההיא ושוכן בה כל יום השבת. ואז נפש ההיא בגדלות ותועלת יתירה ממה שהיתה."],[7,"ועל דא תנינן וכו':","וע\"כ למדנו, כל נפשות ישראל מתעטרות ביום השבת, והעטרה שלהם היא, רוח הזה הנ\"ל, השוכן בתוכם. כיון שיוצא השבת ורוח ההוא עולה למעלה, אז \u0003אוי לנפש\u0004 שאבדה מה שאבדה, דהיינו עטרה העליונה ההיא וכח הקדוש ההוא שהיה בה, וזה הוא, וינפש, שפירושו, אוי לנפש. שאבדה מה שאבדה."],[8,"עונתן דחכימין דידעי וכו':","עונתם של חכמים היודעים סודות עליונים, הוא, מליל שבת לליל שבת. והעמידוהו. אבל דבר זה שאלתי למאור הקדוש, שהרי אנו רואים שכתר התחתון הזה, שהוא מלכות, מקבלת מה שמקבלת מז\"א בזווג של יום, ובלילה היא נותנת מזון לכל צבאותיה, כמו שהעמדנו, שכתוב, ותקם בעוד לילה ותתן טרף לביתה וחק לנערותיה. לוקחת בזווג של יום, ונותנת בלילה, הרי שאין זווג בלילה. ועתה אמר אדוני שזווג נמצא בלילה הזה של שבת."]],[[0,"","סוֹד הַסּוֹדוֹת לְיוֹדְעֵי הַחָכְמָה. אַשְׁרֵיהֶם כְּשֶׁרוּחַ זוֹ מִתְעוֹרֶרֶת. הָרוּחַ הַזּוֹ הִיא הִתְפַּשְּׁטוּת הַנְּקֻדָּה הַזּוֹ, וְיוֹצֵאת מִמֶּנָּה וּמִתְפַּשֶּׁטֶת בָּעוֹלָם, וְאוֹתָהּ הִיא סוֹד הַשַּׁבָּת שֶׁשָּׁרוּי לְמַטָּה, וְעַל כָּךְ כָּתוּב בּוֹ שְׁמִירָה, (שמות לא) וְשָׁמְרוּ בְנֵי יִשְׂרָאֵל אֶת הַשַּׁבָּת, וַהֲרֵי פֵּרְשׁוּהָ, לֹא כָתוּב שַׁבָּת, אֶלָּא אֶת הַשַּׁבָּת, לְרַבּוֹת אוֹתָהּ רוּחַ שֶׁשּׁוֹרָה עַל הַכֹּל, וְצָרִיךְ לִשְׁמֹר אוֹתָהּ הוֹאִיל וְעוֹמֶדֶת עִם הָאָדָם. וְעַל זֶה כָּתוּב, (ישעיה נו) כָּל שֹׁמֵר שַׁבָּת מֵחַלְּלוֹ."],[1,"","בַּסּוֹד הַזֶּה יֵשׁ סוֹד אַחֵר. הָרוּחָ הַזּוֹ נֶהֱנֵית בַּיּוֹם הַזֶּה מֵהֲנָאָתָם שֶׁל יִשְׂרָאֵל וּמֵהָעֹנֶשׁ שֶׁלָּהֶם, וּמִשּׁוּם כָּךְ צָרִיךְ לָתֵת לָהּ עֹנֶג בְּמַאֲכָל וּבְמִשְׁתֶּה שָׁלֹשׁ פְּעָמִים בְּשָׁלֹשׁ סְעוּדוֹת שֶׁל שְׁלֹשׁ דַּרְגוֹת הָאֱמוּנָה, כְּמוֹ שֶׁבֵּאֲרוּהָ, וְזוֹ נוֹטֶלֶת שִׂמְחָה וָעֹנֶג בְּאוֹתָן סְעוּדוֹת שֶׁל יִשְׂרָאֵל. אַשְׁרֵי חֶלְקוֹ מִי שֶׁמְּהַנֶּה אוֹתָהּ וּמְעַנֵּג אוֹתָהּ בַּיּוֹם הַזֶּה."],[2,"","הָרוּחַ הַזּוֹ נֶהֱנֵית כָּל שֵׁשֶׁת הַיָּמִים מֵהָרוּחַ הָעֶלְיוֹנָה שֶׁל עַתִּיק כָּל הָעַתִּיקִים, וְכֵיוָן שֶׁיּוֹרֶדֶת בְּיוֹם הַשַּׁבָּת וְרוֹחֶצֶת בְּגַן עֵדֶן בַּלַּיְלָה, מִתְעַנֶּגֶת מֵעֹנֶג הַגּוּף בַּסְּעוּדוֹת שֶׁל הָאֱמוּנָה, וּמִתְעַטֶּרֶת (ומתעגגת) הָרוּחַ הַזּוֹ מִמַּעְלָה וּמִמַּטָּה, וְנִרְוֵית בְּכָל הַצְּדָדִים בָּעֲטָרָה (בענג) שֶׁלְּמַעְלָה וּמַטָּה."],[3,"","וְהוֹאִיל וְעוֹמֵד עִם הָאָדָם, צָרִיךְ לוֹ לִשְׁמֹר אוֹתוֹ, וְעַל זֶה כָּתוּב וְשָׁמְרוּ בְנֵי יִשְׂרָאֵל אֶת הַשַּׁבָּת. אֶת הַשַּׁבָּת - שַׁבָּת זוֹ הִיא נְקֻדָּה תַּחְתּוֹנָה. אֶת הַשַּׁבָּת - זוֹהִי אוֹתָהּ רוּחַ, הִתְפַּשְּׁטוּתָהּ שֶׁל אוֹתָהּ נְקֻדָּה. אוֹתָהּ הַהִתְפַּשְּׁטוּת, כְּשֶׁנּוֹסָפוֹת קְדֻשּׁוֹת וּבְרָכוֹת מִלְמַעְלָה עַל אוֹתָהּ נְקֻדָּה, הַכֹּל נָאוֹר, וְנַעֲשֵׂית רוּחַ מְאִירָה בְּכָל הַצְּדָדִים, מִתְחַלֵּק לְמַעְלָה וּמֵאִיר, וְנֶחֱלָק לְמַטָּה וּמֵאִיר. וְזֶהוּ שֶׁכָּתוּב בֵּינִי וּבֵין בְּנֵי יִשְׂרָאֵל, חֵלֶק יְרֻשָּׁה יֵשׁ לָנוּ כְּאֶחָד."],[4,"","הַחֵלֶק שֶׁלְּמַעְלָה מִתְעַטֵּר בַּיּוֹם הַזֶּה מֵהָעֹנֶג הָעֶלְיוֹן הַקָּדוֹשׁ, וְנֶהֱנֶה מֵהַזִּיו הָעֶלְיוֹן שֶׁל עַתִּיק כָּל הָעַתִּיקִים. הַחֵלֶק הַתַּחְתּוֹן מִתְעַטֵּר בַּיּוֹם הַזֶּה מֵהָעֹנֶג שֶׁלְּמַטָּה שֶׁנֶּהֱנֶה בַּסְּעוּדוֹת הַלָּלוּ, וְעַל כֵּן צָרִיךְ לְעַנְּגוֹ בְּמַאֲכָל וּבְמִשְׁתֶּה, בִּלְבוּשֵׁי כָבוֹד וּבְשִׂמְחַת הַכֹּל."],[5,"","וּכְשֶׁמִּתְעַטֵר הַחֵלֶק הַזֶּה לְמַטָּה וְנִשְׁמָר כְּמוֹ שֶׁצָּרִיךְ, עוֹלֶה לְמַעְלָה, וּמִתְחַבֵּר בְּאוֹתוֹ חֵלֶק אַחֵר. וְהַנְּקֻדָּה הַזּוֹ נוֹטֶלֶת הַכֹּל מִמַּעְלָה וּמִמַּטָּה, וְנִכְלֶלֶת מִכָּל הַצְּדָדִים. וּמִשּׁוּם שֶׁמִּתְעַטֶּרֶת בְּשַׁבָּת מִמַּעְלָה וּמִמַּטָּה, כָּל שְׁאָר הַיָּמִים נוֹתְנִים כֹּחַ לַכֹּל, וְנוֹתְנִים לָהּ שִׁלְטוֹן מִמַּעְלָה וּמִמַּטָּה. וּבְסוֹדוֹת סִפְרוֹ שֶׁל שְׁלֹמֹה הַמֶּלֶךְ נִמְצָא הַסּוֹד הַזֶּה, וּבֵאֵר אוֹתוֹ הַמְּנוֹרָה הַקְּדוֹשָׁה. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל."],[6,"","כָּתוּב וַיִּנָּפַשׁ, וּפֵרְשׁוּהָ - וַי נֶפֶשׁ שֶׁאָבְדָה, וְיָפֶה הוּא. אֲבָל אִם כָּךְ, וַי לַגּוּף הָיָה צָרִיךְ לוֹמַר, שֶׁמִּמֶּנּוּ אָבְדָה נֶפֶשׁ! אֲבָל סוֹד הַדָּבָר - בָּאָדָם יֵשׁ נֶפֶשׁ שֶׁנּוֹטֶלֶת וּמוֹשֶׁכֶת אֵלָיו אֶת הָרוּחַ הַזּוֹ מֵעֶרֶב שַׁבָּת, וְאוֹתָהּ הָרוּחַ שְׁרוּיָה בְּתוֹךְ אוֹתָהּ הַנֶּפֶשׁ וְדָרָה בָּהּ כָּל יוֹם הַשַּׁבָּת, וְאָז אוֹתָהּ נֶפֶשׁ יְתֵרָה הִיא בְּרִבּוּי וְתוֹעֶלֶת יוֹתֵר מִמַּה שֶּׁהָיְתָה."],[7,"","וְעַל זֶה שָׁנִינוּ, כָּל נַפְשׁוֹת יִשְׂרָאֵל מִתְעַטְּרוֹת בְּיוֹם הַשַּׁבָּת, וְהָעֲטָרָה שֶׁלָּהֶם, שֶׁשּׁוֹרָה הָרוּחַ הַזּוֹ בְּתוֹכָם. כֵּיוָן שֶׁיּוֹצֵאת שַׁבָּת וְאוֹתָהּ רוּחַ עוֹלָה לְמַעְלָה, אֲזַי וַי לַנֶּפֶשׁ שֶׁאִבְּדָה מַה שֶּׁאִבְּדָה. אִבְּדָה אוֹתָהּ עֲטָרָה עֶלְיוֹנָה וְאוֹתוֹ כֹּחַ קָדוֹשׁ שֶׁהָיָה בָּהּ. וְזֶהוּ וַיִּנָּפַשׁ, וַי נֶפֶשׁ, שֶׁאִבְּדָה מַה שֶּׁאִבְּדָה."],[8,"","עוֹנַת הַחֲכָמִים שֶׁיּוֹדְעִים הַסּוֹדוֹת הָעֶלְיוֹנִים, מִלֵּיל שַׁבָּת לְלֵיל שַׁבָּת, וּפֵרְשׁוּהָ. אֲבָל סוֹד זֶה שָׁאַלְתִּי אֶת הַמְּנוֹרָה הַקְּדוֹשָׁה, שֶׁהֲרֵי רָאִינוּ שֶׁהַכֶּתֶר הַתַּחְתּוֹן הַזֶּה לוֹקֵחַ מַה שֶּׁלּוֹקֵחַ בַּיּוֹם, וּבַלַּיְלָה נוֹתֵן מָזוֹן לְכָל צְבָאוֹ, כְּמוֹ שֶׁבֵּאֲרוּהָ, שֶׁכָּתוּב (משלי לא) וַתָּקָם בְּעוֹד לַיְלָה וַתִּתֵּן טֶרֶף לְבֵיתָהּ וְחֹק לְנַעֲרוֹתֶיהָ. לוֹקַחַת בַּיּוֹם וְנוֹתֶנֶת בַּלַּיְלָה. וְעַכְשָׁו אָמַר מֹר, שֶׁהַזִּוּוּג נִמְצָא בַּלַּיְלָה הַזֶּה?"]]],[["אָמַר, וַדַּאי זִוּוּגָא אִשְׁתְּכַח בְּלֵילְיָא דָּא. מַאי טַעְמָא. בְּגִין דְּהַאי לֵילְיָא, אַפְרִישַׁת נִשְׁמָתִין לְכָל אִינּוּן חַכִּימִין, דְּיַדְעִין רָזִין דְּחָכְמְתָא. וְחִבּוּרָא, וְזִוּוּגָא, לָא אִשְׁתְּכַח בְּיוֹמָא אַחֲרָא בְּכָל חֶדְוָה, בְּלָא עִרְבּוּבְיָא (ס\"א אלא בגין דא) אַחֲרָא, כְּגוֹן דָּא. בְּגִין דְּאִינּוּן נִשְׁמָתִין דִּפְלִיגַת, פְלִיגַת לוֹן בְּחַכִּימִין, בְּצַדִּיקִים, בַּחֲסִידֵי כְּדְקָא יֵאוֹת. (ס\"א ותו בכל) וּבְכָל לֵילְיָא וְלֵילְיָא, זִוּוּגָא אִשְׁתְּכַח וַדַּאי. אֵימָתַי בְּפַלְגוּת לֵילְיָא. וְהָא אוֹקִימְנָא. אֲבָל לָא בְּכָל סִטְרִין כְּהַאי זִוּוּגָא.","וּבְגִין דָּא, חַכִּימִין דְּיַדְעִין רָזִין, בַּעְיָין לְסַדְּרָא שִׁמּוּשָׁא דִּלְהוֹן, בְּהַאי לֵילְיָא. מַאי טַעֲמָא. בְּגִין דְּכָל יוֹמֵי דְּשַׁבְּתָא, אִית לוֹן רוּחָא אַחֲרָא דְּשָׁרָא עַל עָלְמָא, וּבְהַאי לֵילְיָא אִית לוֹן רוּחָא אַחֲרָא קַדִּישָׁא עִלָּאָה, דְּנַחְתָּא לִבְנִי קַדִּישִׁין, וְהַהוּא רוּחָא נָשִׁיב מֵעַתִּיקָא דְּכָל עַתִּיקִין, וְנַחְתָּא לְגוֹ נְקוּדָה תַּתָּאָה, לְמֵיהַב בָּהּ נַיְיחָא לְכֹלָּא, וְדָא אִתְפְּלִיג לְכָל סִטְרִין, לְעֵילָּא וְתַתָּא, כְּמָה דְּאַתְּ אָמַר בֵּינִי וּבֵין בְּנֵי יִשְׂרָאֵל.","וְכַד אִינּוּן חַכִּימִין, יַתְבִין בְּהַהוּא רוּחָא קַדִּישָׁא, רוּחָא עִלָּאָה, בָּעָאן לְשַׁמְּשָׁא עַרְסַיְיהוּ, דְּהַאי רוּחָא אַמְשִׁיךְ אֲבַתְרֵיהּ לְתַתָּא, כָּל אִינּוּן נִשְׁמָתִין קַדִּישִׁין, וְיָרְתִין קַדִּישֵׁי עֶלְיוֹנִין, בְּהַאי רוּחָא, נִשְׁמָתִין קַדִּישִׁין לִבְנֵיהוֹן כְּדְקָא יֵאוֹת.","כֵּיוָן דְּהַאי רוּחָא שָׁרָא עַל עָלְמָא, כָּל רוּחִין בִּישִׁין, וְכָל מְקַטְרְגִין בִּישִׁין, אִסְתָּלָקוּ מֵעָלְמָא וְלָא בָּעֵינָן לְצַלָּאָה עַל נְטוּרָא, בְּגִין דְּיִשְׂרָאֵל אִינּוּן נְטִירִין בְּהַהוּא רוּחָא, וְסֻכַּת שָׁלוֹם פְּרִיסָת גַּדְפָהָא עָלַיְיהוּ, וְאִינּוּן נְטִירִין מִכֹּלָּא.","וְאִי תֵּימָא, הָא תָּנֵינָן, דְּלָא יִפּוּק בַּר נָשׁ יְחִידָאי, לָא בְּלֵילְיָא רְבִיעָאָה דְּשַׁבְּתָא, וְלָא בְּלֵילְיָא דְּשַׁבְּתָא, וּבָעֵי בַּר נָשׁ לְאִסְתַּמְּרָא. וְהָא אַמָרָן, דִּבְלֵילְיָא דְּשַׁבְּתָא נְטִירִין בְּנֵי נָשָׁא מִכָּל מְקַטְרְגִין דְּעָלְמָא, וְלָא בָּעִינָן לְצַלָּאָה עַל נְטוּרָא.","תָּא חֲזֵי, הָכִי הוּא וַדַּאי, לֵילְיָא רְבִיעָאָה דְּשַׁבְּתָא, בָּעֵינָן לְאִסְתַּמְּרָא מִנַּיְיהוּ, מַאי טַעְמָא. בְּגִין דִּכְתִּיב, (בראשית א׳:י״ד) יְהִי מְאֹרֹת, מְאֵרַת כְּתִיב חָסֵר, וְהָא אוּקְמוּהָ, דִּבְגִין דְּהִיא חֲסֵרָה, כַּמָה חֲבִילֵי טְהִירִין אִתְכְּלִילָן בְּהַאי מְאֹרֹת. לְוָוטִין וּמְאֹרֹת אִינּוּן בִּגְרִיעוּתָא דְּסִיהֲרָא, וְכֻלְּהוּ שַׁלִּיטִין בְּהַהוּא לֵילְיָא.","בְּלֵילְיָא דְּשַׁבְּתָא, כֵּיוָן דְּכֻלְּהוּ מִתְבָּדְרָן לְאַעֲלָא בְּנוּקְבָּא דְּעַפְרָא, דְּלָא יַכְלִין לְשַׁלְּטָאָה, בָּעֵי בַּר נָשׁ יְחִידָאי, לְאִסְתַּמְּרָא. וְתוּ, אַף עַל גַּב דְּלָא יַכְלִין לְשַׁלְּטָאָה, אִתְחַזְיָין לְזִמְנִין, וּבַר נָשׁ יְחִידָאי בָּעֵי לְאִסְתַּמְּרָא.","מִלָּה דָּא הָכִי תָּנֵינָן, וְאִי הָכִי גְּרִיעוּתָא דִּנְטוּרָא אִיהוּ. אֲבָל בְּשַׁבְּתָא נְטִירוּ אִשְׁתְּכַח לְעַמָּא קַדִּישָׁא, וְקוּדְשָׁא בְּרִיךְ הוּא כַּד עָאל שַׁבְּתָא, מְעַטֵּר לְכָל חַד וְחַד מִיִשְׂרָאֵל, וּבָעֵי דְּיִנְטְרוּן לֵיהּ לְהַאי עִטְרָא קַדִּישָׁא, דְּאִתְעַטָּרוּ בֵּיהּ, וְאַף עַל גַּב דְּאִינּוּן לָא אִשְׁתְּכָחוּ בְּיִשּׁוּבָא, לְזִמְנִין לְבַר נָשׁ יְחִידָאי אִתְחָזוּן, וְאִתְּרַע מַזָּלֵיהּ. וְאִצְטְרִיךְ לֵיהּ לְבַר נָשׁ, לְאִתְעַטְּרָא בְּעִטְרָא קַדִּישָׁא, וּלְנַטְרָא לֵיהּ.","סוֹף סוֹף, נְטִירוּ אִשְׁתְּכַח בְּהַהוּא לֵילְיָא לְעַמָּא קַדִּישָׁא, הוֹאִיל וְסֻכַּת שָׁלוֹם פְּרִיסָא עַל עַמָּא, דְּהָא תָּנֵינָן, בְּכָל אֲתָר דְּסֻכַּת שָׁלוֹם אִשְׁתְּכַח, סִטְרָא אַחֲרָא לָא אִשְׁתְּכַח תַּמָּן. וְעַל דָּא נְטוּרָא אִיהוּ וּנְטוּרָא שְׁכִיחַ.","יוֹמָא דְּשַׁבְּתָא, חֶדְוָה אִיהוּ לְכֹלָּא, וְכֹלָּא אִתְנְטָר לְעֵילָּא וְתַתָּא. וּנְהוֹרָא (נ\"א ונקודה) תַּתָּאָה נַהֲרָא לְסַלְּקָא לְעֵילָּא, בִּשְׁפִירוּ דְּעִטְרִין שִׁבְעִין חוּלָקִין יַתִּיר, וְסָבָא דְּכָל סָבִין אִתְּעַר.","כְּדֵין כַּד סָלִיק נְהוֹרָא, עַמָּא קַדִּישָׁא מְקַדְּמֵי לְבֵי כְּנִישְׁתָּא בִּלְבוּשׁ יְקָר בְּחֶדְוָה, מִתְעַטְּרָן בְּעִטְרָא קַדִּישָׁא דִּלְעֵילָּא, בְּהַהוּא רוּחָא דְּקַיְּימָא עָלַיְיהוּ לְתַתָּא, מְשַׁבְּחָן בְּשִׁירִין וְתוּשְׁבְּחָן, וְסַלְּקִין תּוּשְׁבְּחָן לְעֵילָּא, וְעִלָּאִין וְתַתָּאִין כֻּלְּהוּ בְּחֶדְוָה, וּמִתְעַטְּרָן כֻּלְּהוּ כַּחֲדָא. פַּתְחֵי עִלָּאֵי וְאַמְרֵי, זַכָּאִין אַתּוּן עַמָּא קַדִּישָׁא בְּאַרְעָא, דְּמָארֵיכוֹן אִתְעֲטָּר עָלַיְיכוּ, וְכָל חֵילִין קַדִּישִׁין, מִתְעַטְּרִין בְּגִינֵיכוֹן.","הַאי יוֹמָא, יוֹמָא דְּנִשְׁמָתִין אִיהוּ, וְלָאו יוֹמָא דְּגוּפָא, בְּגִין דְּשֻׁלְטָנוּ דִּצְרוֹרָא דְּנִשְׁמָתִין אִיהוּ, וְקַיְימָן עִלָּאִין וְתַתָּאִין כֻּלְּהוּ בְּזִוּוּגָא חֲדָא, בְּעִטְרָא דְּרוּחָא יְתֵירָא עִלָּאָה קַדִּישָׁא."],[[0,"אמר ודאי זווגא וכו':","אמר, ודאי שנמצא זווג בלילה הזה. מה הטעם, הוא משום שלילה הזה של שבת, שהוא המלכות, מחלקת נשמות לכל אלו החכמים היודעים סוד החכמה, ולא נמצא זווג ביום אחר בשמחה שלמה בלי עירוב אחר מס\"א, כמו בלילה הזה, משום שאלו הנשמות שהיא מחלקת, היא מחלקת אותן בחכמים, בצדיקים, בחסידים, כראוי. וכן בכל לילה ולילה נמצא ודאי זווג ז\"א עם המלכות. מתי. הוא בחצות לילה. וכבר העמדנו. אבל אינו שלם בכל הצדדים כזווג הזה של ליל שבת."],[1,"ובגין דא חכימין וכו':","ומשום זה, החכמים שיודעים סודות, צריכים לסדר השמוש שלהם בלילה הזה. מהו הטעם. הוא משום שבכל ימי השבת יש לנו רוח אחר השורה על העולם (כנ\"ל אות קע\"ו) ובלילה הזה, יש לנו רוח אחר קדוש, עליון, היורד לבנים הקדושים. ורוח ההוא נושב מעתיקא דכל עתיקין, שהוא הכתר, ויורד לנקודה התחתונה לתת בה מנוחה לכל. ורוח הזה נחלק לכל הצדדים למעלה ולמטה, כש\"א, ביני ובין בני ישראל. (כנ\"ל אות קפ\"ט)."],[2,"וכד אינון חכימין וכו':","וכשאלו החכמים יושבים ברוח הקדוש ההוא, רוח העליון, צריכים לשמש מטתם. כי רוח הזה ממשיך אחריו למטה, כל אלו נשמות הקדושות וקדושים העליונים יורשים ברוח הזה, נשמות קדושות לבניהם כראוי."],[3,"כיון דהאי רוחא וכו':","כיון שרוח הזה שורה על ועולם, כל רוחות הרעות וכל מקטרגים הרעים מסתלקים מן העולם, ואין אנו צריכים להתפלל על שמירה, משום שישראל הם שמורים ברוח ההוא, וסכת שלום, שהיא המלכות, פורשת כנפיה עליהם, והם נשמרים מכל."],[4,"דאי תימא הא","וכו': ואם תאמר, הרי למדנו, שלא יצא אדם יחידי לא בליל ד' של השבוע, היא בליל שבת. והאדם צריך להשמר. והרי אמרנו שבליל שבת משומרים בני אדם מכל מקטרגי העולם ואין אנו צריכים להתפלל על שמירה."],[5,"תא חזי הכי וכו':","ומשיב, בוא וראה, כך הוא ודאי, שליל רביעי שבשבת צריכים להשמר מהם מס\"א. מהו הטעם. משום שכתוב, יהי מארת. כתוב מארת חסר ו', הרומז על מיעוט הלבנה, שמשום שהלבנה שהיא המלכות, חסרה, כמה מחנות רוחות נכללו במארת הזה. קללות ומארת הם במיעוטה של הלבנה, וכולם שולטים בלילה ההוא, וע\"כ אסור לצאת יחידי."],[6,"בליליא דשבתא כיון וכו':","בליל שבת, כיון שכל המזיקים מתפזרים להכנס בנקב העפר, כדי שלא יוכלו לשלוט ולהזיק, משמע שמטרם שנכנסים בנקב העפר הם יכולים להזיק, לפיכך צריך אדם יחיד להזהר שלא יצא יחידי. כי יוכלו להזיקו בעודם בדרכם, בטרם יכנסו לנקב העפר. ועוד, אע\"פ שאינם יכולים לשלוט, הם יכולים להראות לפעמים, ואדם יחיד צריך לשמור את עצמו שלא יראה אותם. שיכול להנזק על ידי הראיה."],[7,"מלה דא הכי וכו':","ומזכיר את הלשון ממה שלמד בענין קושיא זו, ואומר, שכך למד ענין הזה. וזה לשונו. ששואל, ואם כן, אם אדם אסור לצאת בליל שבת יחידי הרי הוא חסרון של השמירה. ומשיב. אבל בשבת נמצא שמירה לעם הקדוש. והקב\"ה, כשנכנס השבת הוא מעטר לכל אחד ואחד מישראל, בנשמה יתירה, וצריכים לשמור לאותה עטרה הקדושה שנתעטרו בהם. ואע\"פ שהם, המזיקים, אינם נמצאים במקום ישוב, עכ\"ז לפעמים, לאדם יחידי, הם נראים, ונחלש מזלו. וצריך האדם להתעטר בעטרה הקדושה ולשמור אותה."],[8,"סוף סוף נטירו","וכו': סוף סוף, שמירה נמצאת לעם הקדוש, משום שסוכת שלום, שהוא בינה, פרושה על העם. כי למדנו, כי בכל מקום שסכת שלום נמצא, הסטרא אחרא אינו נמצא שם. וע\"כ היא שמירה, והשמירה נמצאת."],[9,"יומא דשבתא חדוה","וכו': יום השבת, הוא שמחה לכל, והכל נשמר למעלה ולמטה. ונקודה התחתונה, שהיא המלכות, מאירה לעלות למעלה לאו\"א ביופי ע' עטרות, שמקבלת מז\"ת דאו\"א שכ\"א כלול מעשר, שהם חלקים יתירים מבליל שבת. והזקן מכל הזקנים נתעורר, שהוא הכתר. להשפיע אליה."],[10,"כדין כד סליק וכו':","אז כשעולה האור, עם הקדוש מקדימים לבית הכנסת בלבוש יקר, בשמחה, ומתעטרים בעטרה הקדושה שלמעלה, וברוח הזה, שהוא הנשמה יתירה, העומד עליהם למטה, משבחים בשירות ותשבחות, והתשבחות עולות למעלה, ועליונים ותחתונים כולם הם בשמחה, ומתעטרים כולם יחד. פותחים העליונים ואומרים, אשריכם עם קדוש בארץ, שאדוניכם מתעטר עליכם, וכל הצבאות הקדושים מתעטרים בשבילכם."],[11,"האי יומא יומא וכו':","יום הזה הוא יום של הנשמות, ואינו יום הגוף, משום שהוא שליטת צרור הנשמות, שהוא הבינה ועומדים עליונים ותחתונים כולם בזווג אחד, בעטרה של רוח יתירה, העליון הקדוש."]],[[0,"","אָמַר, וַדַּאי שֶׁהַזִּוּוּג נִמְצָא בַּלַּיְלָה הַזֶּה. מָה הַטַּעַם? מִשּׁוּם שֶׁבַּלַּיְלָה הַזֶּה מַפְרִישָׁה נְשָׁמוֹת לְכָל אוֹתָם הַחֲכָמִים שֶׁיּוֹדְעִים אֶת סוֹדוֹת הַחָכְמָה, וְהַחִבּוּר וְהַזִּוּוּג לֹא נִמְצָא בְּיוֹם אַחֵר בְּכָל הַשִּׂמְחָה בְּלִי עִרְבּוּבְיָה (אלא בשביל זה) אַחֶרֶת כְּמוֹ זֶה. מִשּׁוּם שֶׁאוֹתָן נְשָׁמוֹת שֶׁמְּחַלֶּקֶת, מְחַלֶּקֶת אוֹתָן לַחֲכָמִים, לְצַדִּיקִים וְלַחֲסִידִים כָּרָאוּי. (ועוד, בכל) וּבְכָל לַיְלָה וְלַיְלָה נִמְצָא זִוּוּג וַדַּאי. מָתַי? בַּחֲצוֹת הַלַּיְלָה. וַהֲרֵי בֵּאַרְנוּ. אֲבָל לֹא בְּכָל הַצְּדָדִים כְּמוֹ בַּזִּוּוּג הַזֶּה."],[1,"","וּמִשּׁוּם כָּךְ, הַחֲכָמִים שֶׁיּוֹדְעִים הַסּוֹדוֹת, צְרִיכִים לְסַדֵּר תַּשְׁמִישָׁם בַּלַּיְלָה הַזֶּה. מָה הַטַּעַם? מִשּׁוּם שֶׁכָּל יְמוֹת הַשַּׁבָּת יֵשׁ לָהֶם רוּחַ אַחֶרֶת שֶׁשּׁוֹרָה עַל הָעוֹלָם, וּבַלַּיְלָה הַזֶּה יֵשׁ לָהֶם רוּחַ אַחֶרֶת קְדוֹשָׁה עֶלְיוֹנָה שֶׁיּוֹרֶדֶת לְבָנִים קְדוֹשִׁים, וְאוֹתָהּ רוּחַ נוֹשֶׁבֶת מֵעַתִּיק (הקדוש) כָּל הָעַתִּיקִים, וְיוֹרֶדֶת לְתוֹךְ הַנְּקֵדָּה הַתַּחְתּוֹנָה לָתֵת לָהּ מְנוּחָה לַכֹּל. וְזֶה מִתְחַלֵּק לְכָל הַצְּדָדִים, לְמַעְלָה וּלְמַטָּה, כְּמוֹ שֶׁנֶּאֱמַר בֵּינִי וּבֵין בְּנֵי יִשְׂרָאֵל."],[2,"","וּכְשֶׁאוֹתָם חֲכָמִים יוֹשְׁבִים בְּאוֹתָהּ רוּחַ קְדוֹשָׁה, הָרוּחַ הָעֶלְיוֹנָה, צְרִיכִים לְשַׁמֵּשׁ אֶת מִטָּתָם, שֶׁהָרוּחַ הַזּוֹ מַמְשִׁיכָה אַחֲרֶיהָ לְמַטָּה אֶת כָּל אוֹתָן נְשָׁמוֹת קְדוֹשׁוֹת, וְיוֹרְשִׁים קְדוֹשִׁים עֶלְיוֹנִים בָּרוּחַ הַזּוֹ נְשָׁמוֹת קְדוֹשׁוֹת לִבְנֵיהֶם כָּרָאוּי."],[3,"","כֵּיוָן שֶׁהָרוּחַ הַזּוֹ שׁוֹרָה עַל הָעוֹלָם, כָּל הָרוּחוֹת הָרָעוֹת וְכָל הַמְקַטְרְגִים הָרָעִים הִסְתַּלְּקוּ מִן הָעוֹלָם, וְלֹא צְרִיכִים לְהִתְפַּלֵּל עַל שְׁמִירָה, מִשּׁוּם שֶׁיִּשְׂרָאֵל שְׁמוּרִים בְּאוֹתָהּ רוּחַ, וְסֻכַּת שָׁלוֹם פּוֹרֶסֶת כְּנָפֶיהָ עֲלֵיהֶם, וְהֵם שְׁמוּרִים מֵהַכֹּל."],[4,"","וְאִם תֹּאמַר, הֲרֵי שָׁנִינוּ שֶׁלֹּא יֵצֵא אָדָם יְחִידִי, לֹא בְּלֵיל רְבִיעִי שֶׁל שַׁבָּת וְלֹא בְּלֵיל שַׁבָּת, וְצָרִיךְ אָדָם לְהִשָּׁמֵר. וַהֲרֵי אָמַרְנוּ, שֶׁבְּלֵיל הַשַּׁבָּת שְׁמוּרִים אֲנָשִׁים מִכָּל הַמְקַטְרְגִים שֶׁל הָעוֹלָם וְלֹא צְרִיכִים לְהִתְפַּלֵּל עַל שְׁמִירָה?"],[5,"","בֹּא וּרְאֵה, כָּךְ זֶה וַדַּאי, לֵיל רְבִיעִי שֶׁל שַׁבָּת צְרִיכִים לְהִשָּׁמֵר מֵהֶם. מָה הַטַּעַם? מִשּׁוּם שֶׁכָּתוּב (בראשית א) יְהִי מְאֹרֹת. מְאֵרַת כָּתוּב חָסֵר, וַהֲרֵי פֵּרְשׁוּהָ, שֶׁבִּגְלַל שֶׁהִיא חֲסֵרָה, כַּמָּה קְבוּצוֹת שֶׁל רוּחוֹת נִכְלְלוּ בַּמְּאֹרֹת הַזֶּה. קְלָלוֹת וּמְאֵרֹת הֵן בִּפְגִימַת הַלְּבָנָה, וְכֻלָּם שׁוֹלְטִים בְּאוֹתוֹ הַלַּיְלָה."],[6,"","בְּלֵיל הַשַּׁבָּת, כֵּיוָן שֶׁכֻּלָּם מִתְפַּזְּרִים לְהִכָּנֵס לַנֶּקֶב שֶׁל הֶעָפָר, שֶׁלֹּא יְכוֹלִים לִשְׁלֹט, צָרִיךְ אָדָם יְחִידִי לְהִשָּׁמֵר. וְעוֹד, אַף עַל גַּב שֶׁלֹּא יְכוֹלִים לִשְׁלֹט, נִרְאִים לִפְעָמִים, וּבֶן אָדָם יְחִידִי צָרִיךְ לְהִשָּׁמֵר."],[7,"","דָּבָר זֶה כָּךְ שָׁנִינוּ, וְאִם כָּךְ, זֶה חִסָּרוֹן שֶׁל הַשְּׁמִירָה. אֲבָל בְּשַׁבָּת הַשְּׁמִירָה מְצוּיָה לָעָם הַקָּדוֹשׁ, וּכְשֶׁנִּכְנֶסֶת שַׁבָּת, הַקָּדוֹשׁ בָּרוּךְ הוּא מְעַטֵּר כָּל אֶחָד וְאֶחָד מִיִּשְׂרָאֵל, וְרוֹצֶה שֶׁיִּשְׁמְרוּ אֶת הָעֲטָרָה הַקְּדוֹשָׁה הַזּוֹ שֶׁהִתְעַטְּרוּ בָהּ. וְאַף עַל גַּב שֶׁהֵם אֵינָם נִמְצָאִים בְּיִשּׁוּב, לִפְעָמִים הֵם נִרְאִים לְאָדָם יְחִידִי וּמוּרָע מַזָּלוֹ. וְצָרִיךְ לְאָדָם לְהִתְעַטֵּר בַּעֲטָרָה קְדוֹשָׁה וְלִשְׁמֹר אוֹתָהּ."],[8,"","סוֹף סוֹף, שְׁמִירָה נִמְצֵאת בְּאוֹתוֹ לַיְלָה לָעָם הַקָּדוֹשׁ, הוֹאִיל וְסֻכַּת שָׁלוֹם פְּרוּסָה עַל הָעָם, שֶׁהֲרֵי שָׁנִינוּ, בְּכָל מָקוֹם שֶׁנִּמְצֵאת סֻכַּת שָׁלוֹם, הַצַּד הָאַחֵר לֹא נִמְצָא שָׁם, וְלָכֵן שְׁמִירָה הִיא וּשְׁמִירָה מְצוּיָה."],[9,"","יוֹם הַשַּׁבָּת שִׂמְחָה הִיא לַכֹּל, וְהַכֹּל נִשְׁמָר לְמַעְלָה וּלְמַטָּה. וְהָאוֹר (והגקדה) הַתַּחְתּוֹן מֵאִיר לַעֲלוֹת לְמַעְלָה בַּיֹּפִי שֶׁל שִׁבְעִים הָעֲטָרוֹת שֶׁהֵן הַחֲלָקִים הַיְתֵרִים, וְהַזָּקֵן שֶׁל כָּל הַזְּקֵנִים מִתְעוֹרֵר."],[10,"","אָז כְּשֶׁעוֹלֶה הָאוֹר, הָעָם הַקָּדוֹשׁ מַקְדִּימִים לְבֵית הַכְּנֶסֶת בִּלְבוּשׁ כָּבוֹד בְּשִׂמְחָה, מִתְעַטְּרִים בַּעֲטָרָה קְדוֹשָׁה שֶׁלְּמַעְלָה בְּאוֹתָהּ רוּחַ שֶׁעוֹמֶדֶת עֲלֵיהֶם לְמַטָּה, מְשַׁבְּחִים בְּשִׁירוֹת וְתִשְׁבָּחוֹת, וְהַתִּשְׁבָּחוֹת עוֹלוֹת לְמַעְלָה, וְכָל הָעֶלְיוֹנִים וְהַתַּחְתוֹנִים בְּשִׂמְחָה, וְכֻלָּם מִתְעַטְּרִים כְּאֶחָד. פּוֹתְחִים הָעֶלְיוֹנִים וְאוֹמְרִים: אַשְׁרֵיכֶם הָעָם הַקָּדוֹשׁ בָּאָרֶץ, שֶׁרִבּוֹנְכֶם הִתְעַטֵּר עֲלֵיכֶם, וְכָל הַחֲיָלוֹת הַקְּדוֹשִׁים מִתְעַטְּרִים בִּשְׁבִילְכֶם."],[11,"","הַיּוֹם הַזֶּה הוּא יוֹם הַנְּשָׁמוֹת, וְלֹא יוֹם הַגּוּף, מִשּׁוּם שֶׁשִּׁלְטוֹן צְרוֹר הַנְּשָׁמוֹת הוּא, וְכָל הָעֶלְיוֹנִים וְהַתְּתּוֹנִים עוֹמְדִים בְּזִוּוּג אֶחָד, בַּעֲטָרָה שֶׁל רוּחַ יְתֵרָה עֶלְיוֹנָה קְדוֹשָׁה."]]],[["צְלוֹתָא דְּשַׁבְּתָא, דְּעַמָּא קַדִּישָׁא, תְּלַת צְלוֹתִין אִשְׁתְּכָחוּ בְּהַאי יוֹמָא, לָקֳבֵל תְּלַת שַׁבָּתֵי, וְאוּקְמוּהָ, וְכֻלְּהוּ חַד. כֵּיוָן דְּעָאלוּ עַמָּא קַדִּישָׁא לְבֵי כְּנִישְׁתָּא, אָסִיר לְאִשְׁתַּדְּלָא אֲפִילּוּ בְּצוֹרֶךְ בֵּי כְּנִישְׁתָּא, אֶלָּא בְּמִלֵּי תּוּשְׁבְּחָן וּצְלוֹתָא, וְאוֹרַיְיתָא, וְכַדְקָא חֲזֵי לוֹן.","וּמַאן (ר\"ו ע\"א, אמור ק\"ה ע\"א) דְּאִשְׁתָּדַּל בְּמִלִּין אַחֲרָנִין, וּבְמִלִּין דְּעָלְמָא, דָּא אִיהוּ בַּר נָשׁ דְּקָא מְחַלֵּל שַׁבְּתָא, לֵית לֵיהּ חוּלָקָא בְּעַמָּא דְּיִשְׂרָאֵל. תְּרֵין מַלְאֲכִין מְמָנָן עַל דָּא, בְּיוֹמָא דְּשַׁבְּתָא, וְאִינּוּן שַׁווּ יְדֵיהוֹן עַל רֵישֵׁיהּ, וְאַמְרֵי, וַוי לִפְלַנְיָּא, דְּלֵית לֵיהּ חוּלָקָא בְּקוּדְשָׁא בְּרִיךְ הוּא. וְעַל דָּא, בָּעֵי לְאִשְׁתַּדְּלָא בִּצְלוֹתָא וּבְשִׁירִין וּבְתוּשְׁבְּחָן דְּמָארֵיהוֹן, וּלְאִשְׁתַּדְּלָא בְּאוֹרַיְיתָא.","הַאי יוֹמָא, אִיהוּ יוֹמָא דְּנִשְׁמָתִין, דְּאִתְעַטְּרָא הַהוּא צְרוֹרָא דְּנִשְׁמָתִין. (בתושבחן דמאריהון) בְּגִין כָּךְ מְשַׁבְּחֵי בְּתוּשְׁבְּחָן תֻּשְׁבַּחְתָּא דְּנִשְׁמְתָא, וְהַיְינוּ (קל\"ח ע\"א) נִשְׁמַת כָּל חַי תְּבָרֵךְ אֶת שִׁמְךָ יְיָ' אֱלֹהֵינוּ וְרוּחַ כָּל בָּשָׂר וְכוּ'. וְלֵית תּוּשְׁבַּחְתָּא אֶלָּא בְּסִטְרָא דְּנִשְׁמְתָא וְרוּחָא, וְהַאי יוֹמָא, קַיְּימָא בְּרוּחָא וְנִשְׁמְתָא, וְלָאו דְּגוּפָא.","תּוּשְׁבַּחְתָּא דְּדַרְגָא אַחֲרָא עִלָּאָה, רָזָא דְּיוֹמָא, שִׁמְשָׁא קַדִּישָׁא דְּאִיהוּ נְהוֹרָא דִּימָמָא, הַיְינוּ יוֹצֵר אוֹר. רָזָא דִּנְהוֹרָא דְּנָהִיר, דְּמִנֵּיהּ אִתְזְנָן וְנָהֲרִין כָּל אִינּוּן חַיָּילִין, רְתִיכִין, וְכֹכָבַיָּא וּמַזָּלֵי, וְכָל אִינּוּן דְּשַׁלְטִין עַל עָלְמָא.","תּוּשְׁבַּחְתָּא דְּעָלְמָא דְּאָתֵי בְּיוֹמָא דָּא, הַיְינוּ אֵל אָדוֹן. וְתוּשְׁבַּחְתָּא דָּא, אִיהוּ בְּרָזָא דְּעֶשְׂרִין וּתְרֵין אַתְוָון עִלָּאִין קַדִּישִׁין, דְּמִתְעַטְּרָן בַּאֲבָהָן וּבִרְתִיכָא עִלָּאָה קַדִּישָׁא.","אַתְוָון (הקדמה ג' ע\"ב) זְעִירִין, אִינּוּן עֶשְׂרִין וּתְרֵין אַתְוָון, דְּאִינּוּן בְּעָלְמָא תַּתָּאָה, דְּאִינּוּן אֵל בָּרוּךְ גְּדוֹל דֵּעָה וְכוּ', וְלָא אִית בֵּין תֵּיבָה לַתֵּיבָה, רְוָוחָא אַחֲרָא, אֶלָּא אָת רְשִׁימָא בְּכָל תֵּיבָה וְתֵיבָה. (קל\"ב ע\"ב) וּבְעָלְמָא עִלָּאָה, אִית רְוָוחָא, וְסִטְרִין קַדִּישִׁין, בֵּין אָת לְאָת. וְדָא אִיהוּ, תּוּשְׁבַּחְתָּא עַל תּוּשְׁבַּחְתָּא, דְּאַתְוָון עִלָּאִין דְּיוֹמָא שְׁבִיעָאָה, (ר\"ד ע\"א) קָא מְשַׁבַּח וְאָמַר לְמַלְכָּא עִלָּאָה יוֹצֵר בְּרֵאשִׁית.","כַּד תּוּשְׁבַּחְתָּא דָּא סַלְּקָא לְעֵילָּא, שִׁתִין רְתִיכִין עִלָּאִין דְּקָאָמַרָן, מִזְדַּמְּנִין וְנַטְלֵי לְהַאי תּוּשְׁבַּחְתָּא מֵעַמָּא קַדִּישָׁא, וְסַלְקֵי לָהּ לְאִתְעַטְּרָא בָּה, בְּכַמָּה רְתִיכִין עִלָּאִין, דִּי מְמָנָן, וְכָל אִינּוּן צַדִּיקַיָּיא דִּבְגִנְתָּא דְּעֵדֶן, כֻּלְּהוּ מִתְעַטְּרִן בְּתוּשְׁבַּחְתָּא דָּא, וְכָל אִינּוּן רְתִיכִין, וְכָל אִינּוּן נִשְׁמָתִין דְּצַדִּיקַיָּיא, כֻּלְּהוּ סַלְּקִין בְּתוּשְׁבַּחְתָּא דָּא, עַד רָזָא דְּכוּרְסְיָּיא.","כַּד מָטָא לְכוּרְסְיָיא קַדִּישָׁא, תּוּשְׁבַּחְתָּא דָּא דְּכָל יִשְׂרָאֵל, קַיְּימָא תַּמָּן, עַד זִמְנָא דְּקַאמְרֵי קְדוּשָּׁה עִלָּאָה דְּמוּסָף. וּכְדֵין סִלּוּקָא דִּלְתַתָּא לְעֵילָּא, לְאִתְאַחֲדָא כֹּלָּא לְעֵילָּא לְעֵילָּא, לְמֶהֱוֵי כֹּלָּא חַד. דָּא אִיהִי תּוּשְׁבַּחְתָּא, דְּסַלְּקָא עַל כֻּלְּהוּ תּוּשְׁבְּחָן.","מִכָּאן וּלְהָלְאָה, סִדּוּרָא דִּצְלוֹתָא דִּשְׁאַר יוֹמֵי, עַד יִשְׂמַח מֹשֶׁה וְכוּ', חֶדְוָותָא דְּדַרְגָא עִלָּאָה, עִקָּרָא דַּאֲבָהָן, דְּחַדֵּי בְּהַהוּא עַדְבָא דִּילֵיהּ, כַּד סָלִיק כּוּרְסְיָּיא לְגַבֵּיהּ, וְנָטִיל לָהּ, וּמִתְחַבְּרָאן כַּחֲדָא. וְדָא אִיהוּ חֶדְוָה דְּאוֹרַיְיתָא עִלָּאָה דִּלְעֵילָּא, תּוֹרָה שֶׁבִּכְתָּב. דְּחַדֵּי בְּאוֹרַיְיתָא דִּלְתַתָּא, תּוֹרָה שֶׁבְּעַל פֶּה, וְאִתְחַבָּרוּ דָּא בְּדָא.","כֵּיוָן דְּאִתְחַבָּרוּ כַּחֲדָא, בָּעֵי בַּר נָשׁ לְאַכְלְלָא בְּהַהוּא חֶדְוָה לְעַמָּא קַדִּישָׁא, יִשְׂמְחוּ בְמַלְכוּתָךְ שׁוֹמְרֵי שַׁבָּת וְכוּ', אֱלהֵינוּ וֵאלהֵי אֲבוֹתֵינוּ רְצֵה נָא בִמְנוּחָתֵנוּ.","רָזָא דְּסֵפֶר תּוֹרָה בְּיוֹמָא דָּא, הָא אוּקְמוּהָ תָּנֵינָן כְּתִיב, (נחמיה ח׳:ח׳) וְיִקְרְאוּ בְּסֵפֶר בְּתוֹרַת הָאֱלהִים מְפוֹרָשׁ וְשׂוֹם שֶׂכֶל וַיָּבִינוּ בַמִּקְרָא וְהָא אוּקְמוּהָ רָזָא, דְּאִינּוּן פִּסּוּקֵי טַעֲמֵי, וּמַסּוֹרֶת, וְכָל אִינּוּן דִּיוּקִין, (נ\"א תקונין) וְרָזִין עִלָּאִין, כֹּלָּא אִתְמְסָר לְמֹשֶׁה מִסִּינַי. אִי בְכָל הָנֵי דִּיוּקִין אִתְמְסָר אוֹרַיְיתָא לְמֹשֶׁה, סֵפֶר תּוֹרָה דְּאִיהוּ בְכָל אִינּוּן קְדוּשָׁאן, אֲמַאי אִיהוּ חָסֵר מִכָּל הָנֵי תִּקּוּנִין וְרָזִין דְּאִתְמְסָרוּ לֵיהּ לְמֹשֶׁה בְּאוֹרַיְיתָא."],[[0,"צלותא דשבתא וכו':","תפלת השבת של עם הקדוש. ג' תפלות נמצאים ביום הזה כנגד ג' שבתות, שהש בינה ז\"א ומלכות, השולטים ביחד, (כנ\"ל יתרו אות תק\"ל ע\"ש) והעמידוהו. וכולם אחד. וכיון שבאו העם הקדוש לבית הכנסת, אסור לעסוק אפילו בצרכי בית הכנסת אלא בדברי תשבחות, תפלה ותורה, וכראוי להם."],[1,"ומאן האשתדל במלין וכו':","ומי שעוסק בדברים אחרים ובדברי העולם, זה הוא אדם שמחלל שבת, אין לו חלק בעם ישראל. שני מלאכים ממונים על זה ביום השבת, והם משימים ידיהם על ראשו, ואומרים, אוי לפלוני, שאין לו חלק בהקב\"ה. וע\"כ צריכים להשתדל בתפלות ושירות ותשבחות לאדונם, ולעסוק בתורה."],[2,"האי יומא איהו וכו':","יום הזה הוא יום של הנשמות, שנתעטר צרור ההוא של הנשמות, שהוא הבינה, וע\"כ משבחים בתשבחות התשבחה של הנשמה, והיינו, \u0003נשמת\u0004 כל חי תברך את שמך ה' אלקינו ורוח וכו'. ואין תשבחה אלא מצד הנשמה והרוח. ויום הזה עומד בבחינת רוח ונשמה, ואינו של הגוף."],[3,"תושבחתא דדרגא","וכו': התשבחה של מדרגה אחרת עליונה, שהוא סוד היום, השמש הקדוש, שהוא ז\"א, שהוא אור של יום, היינו ברכת \u0003יוצר אור.\u0004 שהוא סוד אור המאיר, שממנו נזונים ומאירים כל אלו הצבאות והמרכבות וככבים ומזלות, וכל אלו השולטים על העולם."],[4,"תושבחתא דעלמא דאתי וכו':","השבח של עולם הבא, שהוא בינה, ביום הזה, היינו, \u0003אל אדון.\u0004 ושבח הזה, הוא בסוד כ\"ב אותיות עליונות הקדושות המתעטרות באבות, שהם חג\"ת ובמרכבה העליונה הקדושה שהיא בינה. (כמ\"ש לעיל אות קפ\"ב ע\"ש)."],[5,"אתוון זעירין וכו':","אותיות קטנות, הן כ\"ב אותיות של עולם התחתון, שהוא מלכות, שהם, אל ברוך גדול דעה וכו'. ולא יש בין תיבה לתיבה ריוח אחר רק אות אחת מכ\"ב אותיות רשומה בכל תיבה ותיבה. דהיינו \u0003א\u0004 ל \u0003ב\u0004 רוך \u0003ג\u0004 דול וכו'. ובעולם העליון, בינה, יש ריוח וצדדים קדושים בין אות לאות. (כנ\"ל תרומה אות ק\"ד). כי ב \u0003א'\u0004 יש חמשה תיבות, דהיינו \u0003א\u0004 ל אדון על כל המעשים. וב \u0003ב'\u0004 יש חמשה תיבות, \u0003ב\u0004 רוך ומבורך בפי כל הנשמה, וב \u0003ג'\u0004 יש ארבע תיבות, \u0003ג\u0004 דלו וטובו מלא עולם וכו' כמ\"ש שם. וזהו שבח על התשבחות, שאותיות עליונות של יום השביעי שהוא בינה משבח ואומר למלך העליון יוצר בראשית. שהוא חכמה. (כמ\"ש לעיל אות קפ\"ב עש\"ה) דהיינו נקודה עלאה."],[6,"כד תושבחתא דא וכו':","כששבח הזה עולה למעלה, ששים מרכבות עליונות שבג\"ע שאמרנו לעיל (אות קפ\"ד) מזדווגים ולוקחים השבח ההוא. מן עם הקדוש, ומעלים אותה להתעטר בה בכמה מרכבות עליונות, שהממונים וכל הצדיקים שבגן עדן, כולם מתעטרים בשבח הזה, וכל אלו המרכבות, וכל אלו נשמות הצדיקים כולם עולים בשבח הזה עד סוד הכסא, שהוא המלכות."],[7,"כד מטא לכורסייא וכו':","כשהשבח מגיע לכסא הקדוש, שהוא המלכות, הנה השבח הזה שאומרים כל ישראל, עומד שם, עד הזמן שאומרים ישראל קדושה עליונה של מוסף, דהיינו כתר יתנו לך וכו'. ואז יש עליה לאלו שלמטה לעלות למעלה, דהיינו שהמלכות שהיא הכסא עולה לאמא, שהיא בינה, וז\"א עולה לאבא, שה\"ס נקודה עלאה, כדי שהכל יתאחד למעלה למעלה, באו\"א, להיות כולם אחד. ואז נמצא שהשבח הזה אל אדון, שכבר עלה עם המלכות לבינה, אומרת אותו הבינה למלך העליון שהוא חכמה, (כנ\"ל אות רי\"ג) זה היא תשבחה העולה על כל התשבחות."],[8,"מכאן ולהלאה סדורא וכו':","מכאן ולהלאה, הוא סדר התפלה כבשאר הימים, עד \u0003ישמח משה\u0004 וכו'. דהיינו שמחת מדרגה עליונה שהוא ת\"ת, הנקרא משה, וה\"ס יעקב, שהוא עיקר האבות שהוא קו המכריע המיחד חו\"ג, המכונים אברהם ויצחק. שהוא שמח בחלק ההוא שלו, שהוא המלכות, כשהכסא שהיא המלכות, עולה אליו ולוקח אותה, ומתחברים יחד. וזה הוא שמחת תורה שלמעלה, שהיא תורה שבכתב, שהוא ת\"ת, השמח בתורה שלמטה, שהיא תורה שבעל פה, שהיא המלכות, ומתחברים זה בזה."],[9,"כיון דאתחברו וכו':","כיון שנתחברו יחד, צריך האדם לכלול בשמחה ההוא את עם הקדוש, ולומר, \u0003ישמחו במלכותך\u0004 שומרי שבת וכו'. \u0003או\"א רצה נא במנוחתנו.\u0004"],[10,"רזא דס\"ת ביומא וכו':","סוד ספר התורה ביום הזה. כבר העמדנו. למדנו. כתוב, ויקראו בספר תורת אלקים מפורש ושום שכל ויבינו במקרא. והעמדנו, שהסוד של הפסק הטעמים והמסורת וכל אלו הדיוקים, וסודות עליונים, הכל נמסר למשה מסיני. שואל, אם התורה נמסרה למשה בכל אלו הדיוקים, ספר תורה, שהוא בכל הקדושות האלו, למה הוא חסר מכל אלו התקונים והסודות שנמסרו למשה בתורה."]],[[0,"","תְּפִלַּת הַשַּׁבָּת שֶׁל הָעָם הַקָּדוֹשׁ, שָׁלֹשׁ תְּפִלּוֹת נִמְצָאוֹת בַּיּוֹם הַזֶּה כְּנֶגֶד שָׁלֹשׁ שַׁבָּתוֹת, וּפֵרְשׁוּהָ, וְהַכֹּל אֶחָד. כֵּיוָן שֶׁנִּכְנְסוּ הָעָם הַקָּדוֹשׁ לְבֵית הַכְּנֶסֶת, אָסוּר לְהִשְׁתַּדֵּל אֲפִלּוּ בְּצֹרֶךְ בֵּית הַכְּנֶסֶת, אֶלָּא בְּדִבְרֵי תִשְׁבָּחוֹת וּתְפִלָּה וְתוֹרָה וְכָרָאוּי לָהֶם."],[1,"","וּמִי שֶׁמִּשְׁתַּדֵּל בִּדְבָרִים אֲחֵרִים וּבְדִבְרֵי הָעוֹלָם, זֶהוּ אָדָם שֶׁמְּחַלֵּל שַׁבָּת, וְאֵין לוֹ חֵלֶק בְּעַם יִשְׂרָאֵל. שְׁנֵי מַלְאָכִים מְמֻנִּים עַל זֶה בְּיוֹם הַשַּׁבָּת, וְהֵם שָׂמִים יְדֵיהֶם עַל רֹאשׁוֹ וְאוֹמְרִים: אוֹי לִפְלוֹנִי שֶׁאֵין לוֹ חֵלֶק בַּקָּדוֹשׁ-בָּרוּךְ-הוּא. וְעַל זֶה צָרִיךְ לְהִשְׁתַּדֵּל בִּתְפִלָּה וּבְשִׁירִים וּבְתִשְׁבָּחוֹת שֶׁל אֲדוֹנָם, וּלְהִשְׁתַּדֵּל בַּתּוֹרָה."],[2,"","הַיּוֹם הַזֶּה הוּא יוֹם הַנְּשָׁמוֹת שֶׁמִּתְעַטֵּר אוֹתוֹ צְרוֹר הַנְּשָׁמוֹת (בתשבחות של אדונם). מִשּׁוּם כָּךְ מְשַׁבְּחִים בְּתִשְׁבָּחוֹת תִּשְׁבַּחַת הַנְּשָׁמָה, וְהַיְנוּ נִשְׁמַת כָּל חַי תְּבָרֵךְ אֶת שִׁמְךְ ה' אֱלֹהֵינוּ וְרוּחַ כָּל בָּשָׂר וְכוּ'. וְאֵין הַתִּשְׁבַּחַת אֶלָּא בְּצַד שֶׁל נְשָׁמָה וְרוּחַ, וְהַיּוֹם הַזֶּה עוֹמֵד בְּרוּחַ וּנְשָׁמָה, וְלֹא שֶׁל גּוּף."],[3,"","הַתִּשְׁבַּחַת שֶׁל דַּרְגָּה אַחֶרֶת עֶלְיוֹנָה, סוֹד הַיּוֹם, שֶׁמֶשׁ קְדוֹשָׁה שֶׁהִיא אוֹר הַיּוֹם, הַיְנוּ יוֹצֵר אוֹר. סוֹד הָאוֹר הַמֵּאִיר, שֶׁמִּמֶּנּוּ נִזּוֹנִים וּמְאִירִים כָּל אוֹתָן הַצְּבָאוֹת, הַמֶּרְכָּבוֹת, וְהַכּוֹכָבִים וְהַמַּזָּלוֹת, וְכָל אוֹתָם שֶׁשּׁוֹלְטִים עַל הָעוֹלָם."],[4,"","תִּשְׁבַּחְתּוֹ שֶׁל הָעוֹלָם הַבָּא בַּיּוֹם הַזֶּה, הַיְנוּ אֵל אָדוֹן. וְהַתִּשְׁבַּחַת הַזּוֹ הִיא בְּסוֹד עֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת עֶלְיוֹנוֹת קְדוֹשׁוֹת שֶׁמִּתְעַטְּרוֹת בָּאָבוֹת וּבַמֶּרְכָּבָה הָעֶלְיוֹנָה הַקְּדוֹשָׁה."],[5,"","הָאוֹתִיּוֹת הַקְּטַנּוֹת הֵן עֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת, שֶׁהֵן הָעוֹלָם הַתַּחְתּוֹן, שֶׁהֵן אֵל בָּרוּךְ גְּדוֹל דֵּעָה וְכוּ', וְאֵין בֵּין תֵּבָה לְתֵבָה רֶוַח אַחֵר, אֶלָּא אוֹת רְשׁוּמָה בְּכָל תֵּבָה וְתֵבָה. וּבָעוֹלָם הָעֶלְיוֹן יֵשׁ רֶוַח, וְהַצְּדָדִים הַקְּדוֹשִׁים בֵּין אוֹת לְאוֹת. וְזוֹהִי תִשְׁבַּחַת עַל תִּשְׁבַּחַת, שֶׁהָאוֹתִיּוֹת הָעֶלְיוֹנוֹת שֶׁל הַיּוֹם הַשְּׁבִיעִי מְשַׁבְּחוֹת וְאוֹמְרוֹת לַמֶּלֶךְ הָעֶלְיוֹן יוֹצֵר בְּרֵאשִׁית."],[6,"","כְּשֶׁהַתִּשְׁבַּחַת הַזּוֹ עוֹלָה לְמַעְלָה, שִׁשִּׁים מֶרְכָּבוֹת עֶלְיוֹנוֹת שֶׁאָמַרְנוּ, מִזְדַּמְּנוֹת וְלוֹקְחוֹת אֶת הַתִּשְׁבַּחַת הַזּוֹ מֵהָעָם הַקָּדוֹשׁ, וּמַעֲלִים אוֹתָהּ לְהִתְעַטֵּר בָּהּ בְּכַמָּה מֶרְכָּבוֹת עֶלְיוֹנוֹת שֶׁמְּמֻנּוֹת. וְכָל אוֹתָם הַצַּדִּיקִים שֶׁבְּגַן עֵדֶן, כֻּלָּם מִתְעַטְּרִים בַּתִּשְׁבַּחַת הַ את, וְכָל אוֹתָן מֶרְכָּבוֹת וְכָל אוֹתָן נִשְׁמוֹת הַצַּדִּיקִים, כֻּלָּם עוֹלִים בַּתִּשְׁבַּחַת הַזּוֹ עַד סוֹד הַכִּסֵּא."],[7,"","וּכְשֶׁמַּגִּיעָה לַכִּסֵּא הַקָּדוֹשׁ הַתִּשְׁבַּחַת הַזּוֹ שֶׁל כָּל יִשְׂרָאֵל, עוֹמֶדֶת שָׁם עַד הַזְּמַן שֶׁאוֹמְרִים הַקְּדֻשָּׁה הָעֶלְיוֹנָה שֶׁל מוּסָף. וְאָז הָעֲלִיָּה שֶׁלְּמַטָּה לְמַעְלָה, לְהֵאָחֵז הַכֹּל לְמַעְלָה לְמַעְלָה לִהְיוֹת הַכֹּל אֶחָד. זוֹהִי הַתִּשְׁבַּחַת שֶׁעוֹלָה עַל כָּל הַתִּשְׁבָּחוֹת."],[8,"","מִכָּאן וָהָלְאָה סִדּוּר הַתְּפִלָּה שֶׁל שְׁאָר הַיָּמִים, עַד יִשְׂמַח מֹשֶׁה וְכוּ', הַשִּׂמְחָה שֶׁל הַדַּרְגָּה הָעֶלְיוֹנָה, עִקַּר הָאָבוֹת, שֶׁשָּׂמֵחַ בְּאוֹתוֹ חֵלֶק שֶׁלּוֹ כְּשֶׁהַכִּסֵּא עוֹלֶה אֵלָיו וְנוֹטֵל אוֹתָהּ, וּמִתְחַבְּרִים כְּאֶחָד. וְזוֹהִי שִׂמְחַת הַתּוֹרָה הָעֶלְיוֹנָה שֶׁלְּמַעְלָה, תּוֹרָה שֶׁבִּכְתָב. שֶׁשָּׂמֵחַ בַּתּוֹרָה שֶׁלְּמַטָּה, תּוֹרָה שֶׁבְּעַל פֶּה, וּמִתְחַבְּרִים זֶה עִם זוֹ."],[9,"","כֵּיוָן שֶׁהִתְחַבְּרוּ כְּאֶחָד, צָרִיךְ אָדָם לְהַכְלִיל בְּאוֹתָהּ שִׂמְחָה אֶת הָעָם הַקָּדוֹשׁ, יִשְׂמְחוּ בְמַלְכוּתְךְ שׁוֹמְרֵי שַׁבָּת וְכוּ', אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ רְצֵה נָא בִמְנוּחָתֵנוּ."],[10,"","סוֹד סֵפֶר הַתּוֹרָה בַּיּוֹם הַזֶּה הֲרֵי פֵּרְשׁוּהוּ, שֶׁשָּׁנִינוּ כָּתוּב (נחמיה ח) וַיִּקְרְאוּ בַסֵפֶר בְּתוֹרַת הָאֱלֹהִים מְפֹרָשׁ וְשׂוֹם שֶׂכֶל וַיָּבִינוּ בַּמִּקְרָא, וַהֲרֵי בֵּאֲרוּ אֶת הַסּוֹד, שֶׁהֵם פִּסּוּקִים, טְעָמִים וּמָסֹרֶת, וְכָל אוֹתָם דִּיּוּקִים (תקונים) וְסוֹדוֹת עֶלְיוֹנִים, הַכֹּל נִמְסַר לְמֹשֶׁה מִסִּינַי. אִם בְּכָל הַדִּיּוּקִים הַלָּלוּ נִמְסְרָה תוֹרָה לְמֹשֶׁה, אָז סֵפֶר תּוֹרָה שֶׁהוּא בְּכָל אוֹתָן קְדֻשּׁוֹת, לָמָּה הוּא חָסֵר מִכָּל הַתִּקּוּנִים הָאֵלּוּ וְהַסּוֹדוֹת שֶׁנִּמְסְרוּ לוֹ לְמֹשֶׁה בַּתּוֹרָה?"]]],[["אֶלָּא רָזָא דָּא, כַּד כּוּרְסְיָּיא קַדִּישָׁא מִתְעַטְּרָא, וְאִתְכְּלִילַת בַּתּוֹרָה שֶׁבִּכְתָּב, כָּל אִינּוּן דִּיוּקְנִין, וְכָל אִינּוּן טַעֲמִין וּמַסּוֹרוֹת, כֻּלְּהוּ עָאלִין בִּגְנִיזוּ, וְאִתְרְשִׁימוּ בְּגוֹ כּוּרְסְיָּיא קַדִּישָׁא, וְאִינּוּן דִּיוּקְנִין, דְּאָעִיל אוֹרַיְיתָא דְּבִכְתָב, בְּאוֹרַיְיתָא דִּבְעַל פֶּה, וּבְהוּ אִתְעַבְּרַת, כְּאִתְּתָא דְּאִתְעַבְּרָת מִן דְּכוּרָא, וְאִשְׁתָּאָרוּ אַתְוָון עִלָּאִין לְחוֹדַיְיהוּ בִּקְדוּשָׁיְיהוּ כַּדְקָא חֲזֵי. וּלְאִתְחֲזָאָה בְּבֵי כְּנִישְׁתָּא, דְּהָא אִתְבָּרְכַת וְאִתְעַטְּרַת כּוּרְסְיָּיא מֵרָזָא דְּתוֹרָה שֶׁבִּכְתָּב, וְתַמָּן אָעִיל כָּל אִינּוּן דִּיוּקְנִין, וְאִיהִי אִתְקַדְשַׁת מִנֵּיהּ, בָּעֵי לְאִתְחֲזָאָה בְּאַתְוָון לְחוֹדַיְיהוּ כַּדְקָא יֵאוֹת.","וּכְדֵין, כֹּלָּא אִתְקַדָּשׁ בִּקְדוּשָּׁה עִלָּאָה כַּדְקָא חֲזֵי, כָּל שֶׁכֵּן וְכָּל שֶׁכֵּן בְּהַאי יוֹמָא. בְּהַאי יוֹמָא בָּעֵי לְסַלְּקָא שִׁבְעָה גּוּבְרִין, לָקֳבֵל שִׁבְעָה קָלִין, דְּאִינּוּן רָזָא דְּאוֹרַיְיתָא. וּבִזְמָנִין וּבְמוֹעֲדִין חָמֵשׁ, גּוֹ רָזָא דָּא. בְּיוֹמָא דְּכִפּוּרֵי שִׁית. גּוֹ רָזָא עִלָּאָה דָּא.","וְכֹלָּא רָזָא חֲדָא. חָמֵשׁ, דְּאִינּוּן חָמֵשׁ דַּרְגִּין לְתַתָּא, מִדַּרְגָּא דְּאוֹר קַדְמָאָה לְתַתָּא, וְאִינּוּן רָזָא דְּאוֹרַיְיתָא. שִׁית, דְּאִינּוּן שִׁית סִטְרִין וְכֹלָּא רָזָא חֲדָא. שֶׁבַע אִינּוּן שֶׁבַע קַלִין. וְכֻלְּהוּ רָזָא חֲדָא, אִלֵּין וְאִלֵּין.","בְּרֹאשׁ חֹדֶשׁ אִתּוֹסָף חַד עַל תְּלָתָא, בְּגִין שִׁמְשָׁא, דְּנָהִיר בְּהַהוּא זִמְנָא, לְסִיהֲרָא, וְאִתּוֹסַף נְהוֹרָא עַל סִיהֲרָא, וְהַיְינוּ רָזָא (בראשית י\"ז ע\"א) דְּמוּסָף. בְּסֵפֶר תּוֹרָה, בָּעֵי לִשְׁתְּמַע חַד קָלָא וְדִבּוּר.","סִדּוּרָא לְסַדְּרָא עַמָּא קַדִּישָׁא בְּיוֹמָא דָּא, וּבִשְׁאַר יוֹמִין דְּסֵפֶר תּוֹרָה בָּעֵי לְסַדְּרָא וּלְתַקְּנָא תִּקּוּנָא, בְּחַד כֻּרְסְיָּיא דְּאִקְרֵי תֵּיבָה, וְהַהוּא כֻּרְסְיָּיא דְּלִהֱוֵי בְּשִׁית (י\"ד ע\"ב, מ\"ג ע\"א, שלח קס\"ד ע\"ב) דַּרְגִּין, לְסַלְּקָא בְּהוּ וְלָא יַתִּיר, דִּכְתִּיב, (דברי הימים ב ט׳:י״ח) וְשֵׁשׁ מַעֲלוֹת לַכִּסֵּא. וְדַרְגָּא חַד לְעֵילָּא, לְשַׁוָּאָה עָלֵיהּ סֵפֶר תּוֹרָה, וּלְאַחֲזָאָה לֵיהּ לְכֹלָּא.","כַּד סָלִיק סֵפֶר תּוֹרָה לְתַמָּן, כְּדֵין בָּעָאן כָּל עַמָּא לְסַדְּרָא גַּרְמַיְיהוּ לְתַתָּא, בְּאֵימָתָא בִּדְחִילוּ בְּרֶתֶת בְּזִיעַ, וּלְכַוְונָא לִבַּיְיהוּ, כְּמָּה דְּהַשְׁתָּא קַיָּימִין עַל טוּרָא דְּסִינַי לְקַבְּלָא אוֹרַיְיתָא, וְיֵהוֹן צַיְיתִין וְיִרְכוּן אוּדְנַיְיהוּ. וְלֵית רְשׁוּ לְעַמָּא לְמִפְתַּח פּוּמֵיהוֹן, אֲפִילּוּ בְּמִילֵּי דְּאוֹרַיְיתָא, וְכָל שֶׁכֵּן בְּמִלָּה אַחֲרָא, אֶלָּא כֻּלְּהוּ בְּאֵימָתָא, כְּמַאן דְּלֵית לֵיהּ פּוּמָא וְהָא אוּקְמוּהָ, דִּכְתִּיב, (נחמיה ח׳:ה׳) וּכְפִתְחוֹ עָמְדוּ כָל הָעָם. (נחמיה ח׳:ג׳) וְאָזְנֵי כָל הָעָם אֶל סֵפֶר הַתּוֹרָה.","אָמַר רַבִּי שִׁמְעוֹן, כַּד מַפְקִין סֵפֶר תּוֹרָה בְּצִבּוּרָא, לְמִקְרֵא בֵּיהּ, מִתְפַּתְּחָן תַּרְעֵי שְׁמַיָיא דְּרַחֲמִין, וּמְעוֹרְרִין אֶת הָאַהֲבָה לְעֵילָּא, וְאִבְעֵי לֵיהּ לְבַר נָשׁ לְמֵימַר הָכִי.","בְּרִיךָ שְׁמֵיהּ דְּמָארֵי עָלְמָא, בְּרִיךְ כִּתְרָךְ וְאַתְרָךְ, יְהֵא רְעוּתָךְ עִם עַמָּךְ יִשְׂרָאֵל לְעָלַם, וּפוּרְקַן יְמִינָךְ, אַחְזֵי לְעַמְּךָ בְּבֵית מִקְדָּשְׁךָ, וּלְאַמְטוֹיֵי לָנָא מִטּוֹב נְהוֹרָךְ, וּלְקַבְּלָא צְלוֹתָנָא בְּרַחֲמִין. יְהֵא רַעֲוָא קֳדָמָךְ, דְּתוֹרִיךְ לָן חַיִּים בְּטִיבוּ, וְלֶהֱוֵי אֲנָא פְּקִידָא בְּגוֹ צַדִּיקַיָּא, לְמִרְחַם עָלַי, וּלְמִנְטַר יָתִי, וְיַת כָּל דִּילִי, וְדִי לְעַמָּךָ יִשְׂרָאֵל. אַתְּ הוּא זָן לְכֹלָּא, וּמְפַרְנֵס לְכֹלָּא, אַתְּ הוּא שַׁלִּיט עַל כֹּלָּא, אַתְּ הוּא דְּשַׁלִּיט עַל מַלְכַיָּא, וּמַלְכוּתָא דִּילָךְ הוּא. אֲנָא עַבְדָּא דְּקוּדְשָׁא בְּרִיךְ הוּא, דְּסָגִידְנָא קַמֵּיהּ, וּמִקַּמֵּי דִּיקָר אוֹרַיְיתֵיהּ, בְכָל עִידָּן וְעִידָּן. לָא עַל אֱינַשׁ רָחִיצְנָא, וְלָא עַל בַּר אֱלָהִין סָמִיכְנָא, אֶלָּא בֶּאֱלָהָא דִּשְׁמַיָּא, דְּהוּא אֱלָהָא קְשׁוֹט, וְאוֹרַיְיתֵיהּ קְשׁוֹט, וּנְבִיאוֹהִי קְשׁוֹט, וּמַסְגֵּי לְמֶעְבַּד טַבְוָון וּקְשׁוֹט. בֵּיהּ אֲנָא רָחִיץ, וְלִשְׁמֵיהּ קַדִּישָׁא יַקִּירָא אֲנָא אֵימַר תּוּשְׁבְּחָן. יְהֵא רַעֲוָא קֳדָמָךְ, דְּתִפְתַּח לִבָּאי בְּאוֹרַיְיתָךְ וְתֵיהַב לִי בְּנִין דִּכְרִין דְּעַבְדִין רְעוּתָךְ. וְתַשְׁלִים מִשְׁאֲלִין דְּלִבָּאי, וְלִבָּא דְּכָל עַמָּךְ יִשְׂרָאֵל לְטָב וּלְחַיִּין וְלִשְׁלָם אָמֵן.","וְאָסִיר לְמִקְרֵי בְּסִפְרָא דְּאוֹרַיְיתָא, בַּר חַד בִּלְחוֹדוֹי, וְכֹלָּא צַיְיתִין וְשַׁתְקִין, בְּגִין דְּיִשְׁמְעוּן מִלִּין מִפּוּמֵיהּ, כְּאִילּוּ קַבִּילוּ לָהּ הַהִיא שַׁעֲתָא מִטּוּרָא דְּסִינַי. וּמַאן דְּקָרֵי בְּאוֹרַיְיתָא, לֶהוֵי חַד קָאִים עָלֵיהּ, וְשָׁתִיק. דְּלָא יִשְׁתַּמָע בַּר דִּבּוּר חַד בִּלְחוֹדוֹי, לָא תְּרֵין דִּבּוּרִין, לְשׁוֹן קֹדֶשׁ חַד, וְחַד הוּא, וְלָא תְּרֵין דִּבּוּרִין, וְאִי תְּרֵין מִשְׁתַּכְּחִין בְּסֵפֶר תּוֹרָה, גְּרִיעוּתָא דְּרָזָא דִּמְהֵימְנוּתָא אִיהוּ וּגְרִיעוּתָא דִּיְקָרָא דְּאוֹרַיְיתָא אִשְׁתְּכַח בְּסֵפֶר תּוֹרָה, וּבָעֵי חַד קָלָא. מְתַרְגֵם חַד. וְרָזָא דָּא קְלִיפָה וּמוֹחָא. (רזא דעלמא דא ורזא דעלמא דאתי).","כֹּלָּא שַׁתְקִין, וְחַד קָארֵי, דִּכְתִּיב, (שמות כ׳:א׳) וַיְדַבֵּר אֱלֹהִים אֵת כָּל הַדְּבָרִים הָאֵלֶּה לֵאמֹר אִיהוּ לְעֵילָּא, וְכָל עַמָּא לְתַתָּא, דִּכְתִּיב, (שמות י״ט:י״ז) וַיִתְיַצְּבוּ בְּתַחְתִּית הָהָר. וּכְתִיב (שמות י״ט:ג׳) וּמֹשֶׁה עָלָה אֶל הָאֱלהִים."],[[0,"אלא רזא דא וכו':","ומשיב, אלא סוד הזה הוא, כשהכסא הקדוש, שהוא המלכות, מתעתר ונכלל בתורה שבכתב, שהוא ת\"ת, אז כל אלו הצורות וכל אלו טעמים ומסורות, כולם נכנסים גנוזים ונרשמים בתוך כסא הקדוש מן הת\"ת. ואלו הצורות שהכניס תורה שבכתב, שהוא ת\"ת, בתורה שבעל פה, שהיא המלכות, היא מתעברת מהם, כאשה המתעברת מזכר, ונשארו אותיות עליונות, שבתורה שבכתב, בלבדם בקדושתם כראוי. בלי שום צורה. ולהראות בביהכ\"נ, כי הכסא, שהוא המלכות, מתברכת ומתעטרת מסוד תורה שבכתב ושם במלכות הכניס כל אלו הצורות שהן הטעמים והמסורות כנ\"ל, והיא מתקדשת ממנו. וצריך להראות בהאותיות לבדן כראוי."],[1,"וכדין כלא אתקדש וכו':","ואז, נתקדש הכל בקדושה העליונה כראוי. כל שכן וכל שכן ביום הזה, שבת. ביום הזה צריכים לעלות לתורה ז' אנשים כנגד ז' קולות, שהם חג\"ת נהי\"מ דז\"א, שהם סוד התורה, שהוא ז\"א. ובזמנים ובמועדים, צריכים לעלות חמשה אנשים בתוך סוד הזה. כי עיקרם של ז' ספירות אינם אלא חמש, חג\"ת נ\"ה, ויסוד היא כולל שלהם מצד המשפיע, והמלכות היא כוללת אותם מצד המקבל, וביוהכ\"פ ששה אנשים בתוך סוד העליון הזה. דהיינו חג\"ת נה\"י דז\"א."],[2,"וכלא רזא חדא וכו':","ומפרש, והכל הוא סוד אחד. כי חמשה דמועדים הם חמש מדרגות חג\"ת נ\"ה, למטה ממדרגת אור קדמאה, שהיא בינה וג\"ר, אלא למטה בז\"א, והם סוד התורה, כי ז\"א נקרא תורה. ששה דיוה\"כ, הם ששה קצוות, דהיינו שמחשבים גם את הכולל שלהם שהוא יסוד. והכל הוא סוד אחד. שהרי אין כאן תוספת על ה' ספירות העיקריות. שבעה של יום השבת, הם שבעה קולות, דהיינו שמחשבים גם את כולל הב' שהוא מלכות. והכל סוד אחד אלו ואלו, דהיינו שמרמזים על ספירות ז\"א."],[3,"בר\"ח אתוסף חד וכו':","בראש החדש, נתוסף אחד שהוא כנגד המלכות, על ג' שבימות החול, הרומזים על חג\"ת דז\"א, משום שהשמש שהוא ז\"א, מאיר בזמן ההוא ללבנה, שהיא מלכות. וז\"ס \u0003המוסף,\u0004 שיש בר\"ח, שהוא נגד התוספת האמורה. בספר תורה צריך להשמע רק קול ודבור אחד. (כנ\"ל אות קמ\"א)."],[4,"סדורא לסדרא עמא וכו':","הסדור שעם הקדיש צריך לסדר ביום הזה, ובשאר ימים שיש קריאת ספר תורה, הוא, שצריכים לסדר ולתקן תקון בכסא אחד הנקרא תיבה. וכסא ההוא צריך להיות בשש מדרגות חג\"ת נה\"י, דמלכות, לעלות עליהם ולא יותר, שכתוב ושש מעלות לכסא, שה\"ס מלכות, ומדרגה אחת למעלה כנגד החכמה שבה, שהיא התיבה, לשום עליה ספר התורה ולהראותה לכל. כי התיבה שה\"ס חכמה דמלכות, נותות ראיה לס\"ת, שה\"ס ז\"א. (כנ\"ל ב\"א דף רע\"ו ד\"ה ועוד) שאין ראיה אלא במלכות."],[5,"כד סליק ס\"ת וכו':","כשעולה שם ספר התורה, אז צריכים כל העם לסדר את עצמם למטה, באימה וביראה ברתת ובזיע, ולכוון את לבם, כמו שהיו עומדים עתה על הר סיני לקבל התורה, ויהיו מקשיבים ויטו אזניהם. ואין רשות לעם לפתוח פיהם אפילו בדברי תורה, וכל שכן בדברים אחרים. אלא כולם באימה, כמי שאין לו פה. וכבר העמדנו, שכתוב, וכפתחו עמדו כל העם. ואזני כל העם אל ספר התורה."],[6,"אר\"ש כד מפקין וכו':","אמר ר' שמעון, כשמוציאים התורה בצבור לקרות בו, נפתחים שערי השמים של רחמים, ומעוררים את האהבה למעלה, וצריך האדם לומר כך."],[7,"בריך שמיה דמארי וכו':","ברוך שמו של רבון העולם. ברוך כתרך ומקומך. יהי רצונך עם עמך ישראל לעולם, שגאולת ימינך תראה לעמך בבית מקדשך, ולהשפיע לנו ממיטב אורך, ולקבל תפלותינו ברחמים. יהי רצון מלפניך שתאריך לנו חיים בטוב, ושאני עבדך יהיה נפקד בין הצדיקים, לרחם עלי, ולשמור אותי ואת כל אשר לי, ושל עמך ישראל. אתה הוא הזן את הכל ומפרנס את הכל. אתה הוא השולט על הכל. אתה הוא השולט על מלכים, והמלכות שלך הוא. אני עבד הקב\"ה, שאני משתחוה לפניו ומלפני כבוד תורתו בכל עת ועת. לא על אדם אני בוטח, ולא על בני אלקים אני סומך, אלא על אלקים שבשמים, שהוא אלקים אמת, ותורתו אמת, ונביאיו אמת, ומרבה לעשות חסד ואמת. בו אני בוטח, ולשמו הקדוש והיקר אני אומר תשבחות. יהי רצון מלפניך, שתפתח לבי בתורתך, ותתן לי בנים זכרים עושי רצונך, ותמלא משאלות לבי, ולב כל עמך ישראל, לטוב, לחיים, ולשלום, אמן."],[8,"ואסיר למקרי בספרא וכו':","ואסור לקרות בספר התורה, רק אחד לבד, וכולם מקשיבים ושותקים, כדי שישמעו דבריו מפיו, כאלו קבלו אותה עתה מהר סיני. ומי שקורא בתורה, יהיה אחד עומד עליו דהיינו העולה לתורה, ושותק, שלא ישמע רק דבור אחד בלבד ולא שני דיבורים. (כנ\"ל אות קמ\"א) לשון קדש צריך להיות קורא אחד, והוא אחד ולא שני דיבורים, ואם נמצאים שנים בספר תורה, הוא גרעון סוד האמונה, וגרעון כבוד התורה נמצא בספר תורה. שצריכים רק קול אחד. וכן צריך להיות מתרגם אחד. וזה סוד, קליפה ומוח. כי המתרגם הוא בחינת קליפה, והקורא בלשון הקדש הוא מוח. ואין מוח בלי קליפה."],[9,"כלא שתקין וחד וכו':","הכל שותקים ואחד קורא. שכתוב, וידבר אלקים את כל הדברים האלה לאמר. הוא למעלה בראש ההר, וכל העם למטה, שכתוב ויתיצבו בתחתית ההר. וכתוב, ומשה עלה אל האלקים. הרי שהיה קורא אחד, ועולה לתורה אחד, למעלה בראש ההר, וכל העם בתחתית ההר מקשיבים ושותקים. וכן צריך להיות בס\"ת."]],[[0,"","אֶלָּא סוֹד זֶה, כְּשֶׁהַכִּסֵּא הַקָּדוֹשׁ מִתְעַטֵּר, וְנִכְלֶלֶת בַּתּוֹרָה שֶׁבִּכְתָב כָּל אוֹתָן דְּמֻיּוֹת, וְכָל אוֹתָם טְעָמִים וּמָסוֹרוֹת, כֻּלָּם נִכְנָסִים בִּגְנִיזָה וְנִרְשְׁמוּ בְּתוֹךְ הַכִּסֵּא הַקָּדוֹשׁ, וְאוֹתָן דְּיוֹקְנָאוֹת שֶׁהִכְנִיסָה תוֹרָה שֶׁבִּכְתָב בַּתּוֹרָה שֶׁבְּעַל פֶּה, וּבָהֶם הִתְעַבְּרָה כְּמוֹ אִשָּׁה שֶׁהִתְעַבְּרָה מֵהַזָּכָר, וְנִשְׁאֲרוּ הָאוֹתִיּוֹת הָעֶלְיוֹנוֹת לְבַדָּן בִּקְדֻשָּׁתָן כָּרָאוּי. וּלְהֵרָאוֹת בְּבֵית הַכְּנֶסֶת, שֶׁהֲרֵי מִתְבָּרֶכֶת וּמִתְעַטֶּרֶת הַכִּסֵּא מִסּוֹד תּוֹרָה שֶׁבִּכְתָב, וְשָׁם מַכְנִיסָה כָּל אוֹתָן דְּמֻיּוֹת וּמִתְקַדֶּשֶׁת מִמֶּנּוּ, צָרִיךְ לְהֵרָאוֹת בָּאוֹתִיּוֹת לְבַדָּן כָּרָאוּי."],[1,"","וְאָז הַכֹּל מִתְקַדֵּשׁ בִּקְדֻשָּׁה עֶלְיוֹנָה כָּרָאוּי, כָּל שֶׁכֵּן וְכָל שֶׁכֵּן בַּיּוֹם הַזֶּה. בַּיּוֹם הַזֶּה צָרִיךְ לְהַעֲלוֹת שִׁבְעָה אֲנָשִׁים כְּנֶגֶד שִׁבְעָה קוֹלוֹת, שֶׁהֵם סוֹד הַתּוֹרָה, וּבִזְמַנִּים וּבְמוֹעֲדִים חָמֵשׁ תּוֹךְ סוֹד זֶה. בְּיוֹם הַכִּפּוּרִים שֵׁשׁ תּוֹךְ הַסּוֹד הָעֶלְיוֹן הַזֶּה."],[2,"","וְהַסֹל סוֹד אֶחָד. חָמֵשׁ, שֶׁהֵם חָמֵשׁ דְּרָגוֹת לְמַטָּה מִדַּרְגַּת הָאוֹר הָרִאשׁוֹן לְמַטָּה, וְהֵם סוֹד הַתּוֹרָה. שֵׁשׁ, שֶׁהֵם שִׁשָּׁה צְדָדִים, וְהַכֹּל סוֹד אֶחָד. שֶׁבַע הֵם שִׁבְעָה קוֹלוֹת, וְכֻלָּם סוֹד אֶחָד אֵלֶּה וְאֵלֶּה."],[3,"","בְּרֹאשׁ חֹדֶשׁ נוֹסָף אֶחָד עַל שְׁלֹשָׁה בִּשְׁבִיל הַשֶּׁמֶשׁ שֶׁמֵּאִיר בְּאוֹתוֹ זְמַן לַלְּבָנָה, וְנוֹסָף אוֹר עַל הַלְּבָנָה, וְזֶהוּ סוֹד מוּסָף. בְּסֵפֶר תּוֹרָה צָרִיךְ לְהִשָּׁמַע קוֹל אֶחָד וְדִבּוּר."],[4,"","הַסִּדּוּר לְסַדֵּר הָעָם הַקָּדוֹשׁ בַּיּוֹם הַזֶּה וּבִשְׁאָר הַיָּמִים שֶׁלַּסֵּפֶר תּוֹרָה צָרִיךְ לְסַדֵּר וּלְתַקֵּן תִּקּוּן בְּכִסֵּא אֶחָד שֶׁנִּקְרָא תֵּבָה, וְאוֹתוֹ כִּסֵּא שֶׁיִּהְיֶה בְּשֵׁשׁ דְּרָגוֹת לַעֲלוֹת בָּהֶם, וְלֹא יוֹתֵר, שֶׁכָּתוּב וְשֵׁשׁ מַעֲלוֹת לַכִּסֵּא. וְדַרְגָּה אַחַת לְמַעְלָה לָשִׂים עָלָיו סֵפֶר תּוֹרָה וּלְהַרְאוֹתוֹ לַכֹּל."],[5,"","כְּשֶׁעוֹלֶה לְשָׁם סֵפֶר תּוֹרָה, אָז צְרִיכִים כָּל הָעָם לְסַדֵּר עַצְמָם לְמַטָּה בְּאֵימָה וָפַחַד, בְּרֶתֶת וּבְזִיעַ וּלְכַוֵּן לִבָּם, כְּאִלּוּ שֶׁכָּעֵת עוֹמְדִים עַל הַר סִינַי לְקַבֵּל תּוֹרָה, וְיִהְיוּ מַקְשִׁיבִים וּמַטִּים אָזְנֵיהֶם. וְאֵין רְשׁוּת לָעָם לִפְתֹּחַ פִּיהֶם אֲפִלּוּ בְּדִבְרֵי תוֹרָה, כָּל שֶׁכֵּן בְּדָבָר אַחֵר, אֶלָּא כֻּלָּם בְּאֵימָה, כְּמִי שֶׁאֵין לוֹ פֶּה, וַהֲרֵי פֵּרְשׁוּהָ, שֶׁכָּתוּב (נחמיה ח) וּכְפִתְחוֹ עָמְדוּ כָל הָעָם. (שם) וְאָזְנֵי כָל הָעָם אֶל סֵפֶר הַתּוֹרָה."],[6,"","אָמַר רַבִּי שִׁמְעוֹן, כְּשֶׁמּוֹצִיאִים סֵפֶר תּוֹרָה בְּצִבּוּר לִקְרֹא בוֹ, נִפְתָּחִים שַׁעֲרֵי רַחֲמִים בַּשָּׁמַיִם, וּמְעוֹרְרִים אֶת הָאַהֲבָה לְמַעְלָה, וְצָרִיךְ אָדָם לוֹמַר כָּךְ."],[7,"","בָּרוּךָ שְׁמוֹ שֶׁל רִבּוֹן הָעוֹלָם, בָּרוּךְ כִּתְרְךְ וּמְקוֹמְךְ, יִהְיֶה רְצוֹנְךְ עִם עַמְּךְ יִשְׂרָאֵל לְעוֹלָם, וּפְדוּת יְמִינְךְ הַרְאֵה לְעַמְּךְ בְּבֵית מִקְדָּשְׁךְ, וּלְהַגִּיעַ לָנוּ מִטּוּב אוֹרְךְ וּלְקַבֵּל תְּפִלּוֹתֵינוּ בְּרַחֲמִים. יְהִי רָצוֹן מִלְּפָנֶיךְ, שֶׁתַּאֲרִיךְ לָנוּ חַיִּים בְּטוֹב, וְלִהְיוֹתִי נִפְקָד בֵּין הַצַּדִּיקִים לְרַחֵם עָלַי וְלִשְׁמֹר אוֹתִי, וְאֶת כָּל שֶׁלִּי וְשֶׁל כָּל עַמְּךְ יִשְׂרָאֵל. אַתָּה הוּא הַזָּן אֶת הַכֹּל, אַתָּה הוּא הַשּׁוֹלֵט עַל הַמְּלָכִים וּמְפַרְנֵס אֶת הַכֹּל. אַתָּה הוּא הַשּׁוֹלֵט עַל הַכֹּל, וְהַמַּלְכוּת שֶׁלְּךְ הִיא. אֲנִי עַבְדּוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁמִּשְׁתַּחֲוֶה לְפָנָיו וּמִלִּפְנֵי כְּבוֹד תּוֹרָתֵנוּ בְּכָל זְמַן וּזְמַן. לֹא עַל אִישׁ אֲנִי בּוֹטֵחַ וְלֹא עַל בְּנֵי אֱלֹהִים אֲנִי סוֹמֵךְ, אֶלָּא בֵּאלֹהֵי הַשָּׁמַיִם, שֶׁהוּא אֱלֹהֵי אֱמֶת וְתוֹרָתוֹ אֱמֶת וּנְבִיאָיו אֱמֶת, וּמַרְבֶּה לַעֲשׂוֹת טוֹבוֹת וֶאֱמֶת. בּוֹ אֲנִי בּוֹטֵחַ, וְלִשְׁמוֹ הַקָּדוֹשׁ וְהַנִּכְבָּד אֲנִי אוֹמֵר תִּשְׁבָּחוֹת. יְהִי רָצוֹן מִלְּפָנֶיךְ, שֶׁתִּפְתַּח לִבִּי בְּתוֹרָתְךְ, וְתִתֵּן לִי בָּנִים זְכָרִים שֶׁעוֹשִׂים רְצוֹנְךְ, וְתַשְׁלִים מִשְׁאֲלוֹת לִבִּי וְלֵב כָּל עַמְּךְ יִשְׂרָאֵל לְטוֹב וּלְחַיִּים וּלְשָׁלוֹם, אָמֵן."],[8,"","וְאָסוּר לִקְרֹא בְּסֵפֶר תּוֹרָה, רַק אֶחָד לְבַדּוֹ, וְכֻלָּם מַקְשִׁיבִים וְשׁוֹתְקִים, כְּדֵי שֶׁיִּשְׁמְעוּ הַדְּבָרִים מִפִּיו כְּאִלּוּ קִבְּלוּ אוֹתָהּ בְּאוֹתָהּ שָׁעָה מֵהַר סִינַי. וּמִי שֶׁקּוֹרֵא בַתּוֹרָה, שֶׁיִּהְיֶה אֶחָד עוֹמֵד עָלָיו וְשׁוֹתֵק, שֶׁלֹּא יִשָּׁמַע - רַק דִּבּוּר אֶחָד לְבַדּוֹ וְלֹא שְׁנֵי דִבּוּרִים. לְשׁוֹן קֹדֶשׁ אַחַת, וְאֶחָד הוּא, וְלֹא שְׁנֵי דִבּוּרִים. וְאִם נִמְצָאִים שְׁנַיִם בַּסֵּפֶר תּוֹרָה, זֶהוּ חִסָּרוֹן שֶׁל סוֹד הָאֱמוּנָה, וְחֶסְרוֹן כְּבוֹד הַתּוֹרָה נִמְצָא בַּסֵּפֶר תּוֹרָה. וְצָרִיךְ קוֹל אֶחָד, מְתַרְגֵּם אֶחָד, וְסוֹד זֶה - קְלִפָּה וּמֹחַ. (סוד העולם וסוד העולם הבא)."],[9,"","כֻּלָּם שׁוֹתְקִים וְאֶחָד קוֹרֵא, שֶׁכָּתוּב (שמות כ) וַיְדַבֵּר אֱלֹהִים אֵת כָּל הַדְּבָרִים הָאֵלֶּה לֵאמֹר. הוּא לְמַעְלָה, וְכָל הָעָם לְמַטָּה, שֶׁכָּתוּב (שמות יט) וַיִּתְיַצְּבוּ בְּתַחְתִּית הָהָר. וְכָתוּב וּמֹשֶׁה עָלָה אֶל הָאֱלֹהִים."]]],[["וְהַהוּא דְּקָארֵי בְּאוֹרַיְיתָא, יְשַׁוֵּי לִבֵּיהּ וּרְעוּתֵיהּ לְאִינּוּן מִלִּין, וְכִי אִיהוּ שְׁלִיחָא דְּמָארֵיהּ, בְּסִדוּרָא דְּהָנִי מִלִּין, לְמִשְׁמַע לְכָל עַמָּא, דְּהָא אִיהוּ קָאִים כְּדוּגְמָא עִלָּאָה. בְּגִין כַּךְ, מַאן דְּסָלִיק לְמִקְרֵי בְּאוֹרַיְיתָא, יְסַדֵר אִינּוּן מִלִּין בְּקַדְמִיתָא בְּבֵיתֵיהּ, וְאִי לָאו, לָא יִקְרֵי בְּאוֹרַיְיתָא, מְנָלָן מֵהַהוּא דִּבּוּר, עַד לָא יָשְׁמַע אוֹרַיְיתָא לְעַמָּא קַדִּישָׁא מַה כְּתִיב, (איוב כ״ח:כ״ז-כ״ח) אָז רָאָה וַיְסַפְּרָהּ הכִינָהּ וְגַם חֲקָרָהּ, וּלְבָתַר, וַיֹּאמֶר לָאָדָם הֵן יִרְאַת יְיָ' הִיא חָכְמָה וְגוֹ'.","אָסִיר לֵיהּ לְמַאן דְּקָארֵי בְּאוֹרַיְיתָא לְמִפְסַק פַּרְשְׁתָּא, אוֹ אֲפִילּוּ מִלָּה חֲדָא, אֶלָּא בַּאֲתָר דְּפָסַק מֹשֶׁה פַּרְשְׁתָּא לְעַמָּא קַדִּישָׁא, יַפְסִיק. וְלָא יַפְסִיק מִלִּין דְּפַרְשְׁתָּא דְּשַׁבְּתָא דָּא, בְּפַרְשְׁתָּא דְּשַׁבְּתָא אַחֲרָא.","רָזָא דָּא, בְּשַׁעֲתָא דְּאִיפְסִיקוּ פַּרְשִׁיָין, כָּל חַד וְחַד אִתְעַטְּרָא וְקַיְּימָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא. כֵּיוָן דְּאַשְׁלִימוּ לְמִפְסַק הָנִי פַּרְשִׁיָין דְּכָל שַׁתָּא, אִתְעַטָּרוּ קַמֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא, וְאַמְרֵי אֲנָא מִשַּׁבָּת פְּלוֹנִי, (ס\"א מצבורא פלוני) וַאֲנָא מִשַּׁבָּת פְּלוֹנִי. (מצבורא פלוני)","בְּהַהִיא שַׁעֲתָא, קְרָא לְיוּפִיאֵ\"ל רַב מְמָנָא, וּלְחַמְשִׁין וּתְלַת רְתִיכִין קַדִּישִׁין דִּתְחוֹת יְדֵיהּ, דְּאִתְמָנוּן בְּשִׁמוּשָׁא דְּאוֹרַיְיתָא, וְכָל רְתִיכָא וּרְתִיכָא מָנִי לֵיהּ, לְהַאי רְתִיכָא עַל פַּרְשְׁתָּא פְּלַנְיָא, דִּבְשַׁבָּת פְּלוֹנִי. וּרְתִיכָא פְּלוֹנִי, עַל פַּרְשְׁתָּא פְּלַנְיָא, דְּשַׁבָּת פְּלוֹנִי. וְכָל חַד וְחַד, מְשַׁמְּשָׁא לְאוֹרַיְיתָא, דְּהַהוּא שַׁבָּת דִּילֵיהּ. וְאָסִיר לָן לְעָרְבָא אִלֵּין בְּאִלֵּין, וְלָא לְאַעֲלָא רְתִיכָא בִּרְתִּיכָא דְּחַבְרֵיהּ, אֲפִילּוּ כִּמְלֹא נִימָא. וַאֲפִילּוּ בְּחַד תֵּיבָה, אוֹ אֲפִילּוּ בְּאָת חַד, אֶלָּא כָּל חַד וְחַד, כְּמָּה דְּפָסִיק לוֹן קוּדְשָׁא בְּרִיךְ הוּא, וּכְמָּה דְּמָנֵי לוֹן בְּאִינּוּן פַּרְשְׁיָין, כָּל חַד וְחַד עַל מַטְרֵיהּ.","וְעַל דָּא, כַּד מִתְעַטְּרָא פַּרְשְׁתָּא דָּא, סַלְקָן אִינּוּן מִלִּין דְּהַהִיא פַּרְשְׁתָּא, דְּאִשְׁתְּלִים בְּצִבּוּרָא, וְנָטִיל לוֹן הַהוּא רְתִיכָא, דִּמְמָנָא בְּהַהִיא פַּרְשְׁתָּא, וְסָלִיק לוֹן קַמֵי קוּדְשָׁא בְּרִיךְ הוּא, וְאִלֵּין מִלִּין מַמָּשׁ, קַיְימִין קַמֵּיהּ וְאָמְרִין, אֲנָא פַּרְשְׁתָּא פְּלַנְיָא, דְּאַשְׁלִימוּ לִי צִבּוּרָא פְּלוֹנִי, הָכִי וְהָכִי.","אִי אִשְׁתְּלִים כַּדְקָא חֲזֵי לֵיהּ, סַלְּקִין אִינּוּן מִלִּין, וּמִתְעַטְּרָן עַל כּוּרְסְיָיא קַדִּישָׁא, וְהַהוּא רְתִיכָא מְשַׁמְּשָׁא קַמֵּיהּ, כָּל רְתִיכָא וּרְתִיכָא, פַּרְשְׁתָּא דְּכָל שַׁבְּתָא וְשַׁבְּתָא, וְכֻלְּהוּ מִתְעַטְּרָן בְּגוֹ כּוּרְסְיָּיא קַדִּישָׁא, וּבְהוּ אִיהִי סַלְּקָא לְאִתְיַחֲדָא לְעֵילָּא לְעֵילָּא, וְאִתְעָבִיד כֹּלָּא כְּלָלָא חֲדָא. בְּגִין כַּךְ, זַכָּאָה חוּלָקֵיהּ מַאן דְּאַשְׁלִים פַּרְשְׁתָּא דְּכָל שַׁבְּתָא וְשַׁבְּתָא, כַּדְקָא יָאוּת, כְּמָה דְּאַפְסִיקוּ לְעֵילָּא.","תְּרֵי זִמְנֵי, קָרֵינָן בְּסֵפֶר תּוֹרָה בְּשַׁבְּתָא, בַּמִּנְחָה, בְּשַׁעֲתָא דְּדִינָא תַּלְיָא, לְעִידַן עֶרֶב. צְרִיכִין לְאַכְלְלָא שְׂמָאלָא בִּימִינָא, דְּהָא אוֹרַיְיתָא מִתְּרִין (פ\"ד ע\"א) סִטְרִין אִתְיְיהִיבַת, דִּכְתִּיב, (דברים לג) מִימִינוֹ אֵשׁ דָּת לָמוֹ, יְמִינָא וּשְׂמָאלָא. בְּגִין כָּךְ סֵפֶר תּוֹרָה בַּמִּנְחָה דַּי בַּעֲשָׂרָה פְּסוּקִין, אוֹ יַתִּיר, אֲבָל לָא שְׁלִימוּ דְּפַרְשְׁתָּא, דְּהָא שְׁלִימוּ דְּפַרְשְׁתָּא לָא הֱוֵי, אֶלָּא בִּימִינָא, וִימִינָא תַּלְיָיא עַד שַׁעֲתָא דְּמִנְחָה, וְהָא אוּקְמוּהָ.","בַּשֵּׁנִי בְּשַׁבְּתָא, וּבַחֲמִישִׁי בְּשַׁבְּתָא, בְּגִין דְּקָא נַחְתִּין דַּרְגִּין לְתַתָּא, דְּאִינּוּן כְּלָלָא דְּאוֹרַיְיתָא. וְאִי תֵּימָא, הָא נְבִיאִין מִתְפָּרְשָׁן לְתַתָּא. אֶלָּא הָכִי הוּא וַדַּאי, אֲבָל הָנֵי דִּלְתַתָּא, כֻּלְּהוּ כְּלָלָא דְּאוֹרַיְיתָא, וְכָל חַד וְחַד כָּלִיל לְכָל חַד וְחַד.","וְרָזָא דְּמִלָּה, אִלֵּין דַּרְגִּין עִלָּאִין, אִינּוּן אִקְרוּן פַּרְשְׁתָּא חֲדָא, וּלְבָתַר נָפְקִין מִנַּיְיהוּ תְּשַׁע דַּרְגִּין, דְּאִתְאַחֲדָן כַּחֲדָא, וּבְגִין כַּךְ תִּשְׁעָה גּוּבְרִין, תְּלַת בְּשַׁבְּתָא בַּמִּנְחָה, וּתְלַת בְּיוֹמָא תִּנְיָינָא, וּתְלַת בְּיוֹמָא חֲמִשָׁאָה, הָא תִּשְׁעָה.","וּבְסִפְרָא דְּרַב יֵיבָא סָבָא, בַּמִּנְחָה בְּשַׁבְּתָא, הָא אִתְעַר רָזָא דִּשְׂמָאלָא, (כ\"ד ע\"א) וּנְקוּדָה תַּתָּאָה, בְּהַהוּא סִטְרָא דִּשְׂמָאלָא, מְקַבְּלָא רָזָא דְּאוֹרַיְיתָא, כְּדֵין בְּהַהִיא שַׁעֲתָא, נַטְלָא מִסִּטְרָא דִּשְׂמָאלָא, וּמִדִּילֵיהּ קָרֵינָן."],[[0,"וההוא דקארי באורייתא וכו':","ואותו הקורא בתורה, צריך לשום לבו ורצונו, לאלו הדברים שקורא, וכי שהוא שליח אדונו בסדר דברים להשמיע לכל העם, שהרי הוא עומד כדמיון עליון, כמו הקב\"ה במתן תורה. משום זה מי שעולה לקרות בתורה צריך לסדר הדברים תחילה בביתו. ואם לא סידר, לא יקרא בתורה. מאין לנו. הוא מאותו דבור של הקב\"ה מטרם שהשמיע התורה לעם הקדוש, מה כתוב, אז ראה ויספרה הכינה וגם חקרה, ואח\"כ, ויאמר לאדם הן יראת ה' היא חכמה וגו'. הרי שמטרם שהשמיע אותה לאדם, סידר כל דבור בפני עצמו. וכן מחויב כל קורא בתורה לעשות."],[1,"אסיר ליה למאן וכו':","אסור לו למי שקורא בתורה להפסיק פרשה או אפילו מלה אחת, אלא במקום שפסק משה הפרשה לעם הקדוש, יפסיק. ולא יפסיק דברי הפרשה של שבת הזה בפרשה של שבת אחר."],[2,"רזא דא בשעתא וכו':","הסוד הוא, כי בשעה שהפסיקו הפרשיות, כל אחת ואחת התעטרה ועמדה לפני הקב\"ה. כיון שהשלימו להפסיק הפרשיות של כל השנה, התעטרו לפני הקב\"ה ואמרו, אני משבת פלוני, אני משבת פלוני."],[3,"בההיא שעתא קרא וכו':","בשעה ההיא קרא הקב\"ה ליופיאל הממונה העליון, ולנ\"ג מרכבות הקדושות שתחת ידו, שהם כנגד נ\"ג פרשיות שבתורה, שנתמנו בשמוש לתורה, וכל מרכבה ומרכבה נתמנתה, מרכבה זו, על פרשה פלונית שבשבת פלוני, ומרכבה פלונית, על פרשה פלונית שבשבת פלוני. וכל אחת ואחת משמשת אל התורה של השבת שלה, ואסור לנו לערב אלו באלו ולא להכניס מרכבה במרכבה אחרת אפילו כמלא שערה, ואפילו בתיבה אחת, או אפילו באות אחת, אלא כל אחת ואחת כמו שפסק אותם הקב\"ה, דהיינו כמו שנתעטרו לפניו, כנ\"ל בסמוך. וכמו שהפקיד אותן, את המרכבות, על פרשיות האלו, כל אחת ואחת על משמרתה."],[4,"ועל דא כד וכו':","וע\"כ כשמתעטר פרשה זו, עולות המלות של פרשה ההיא שנשלמה בצבור, ומקבלת אותן מרכבה ההיא הממונה על פרשה ההוא, ומעלה אותן לפני הקב\"ה. ואלו המלות ממש עומדות לפניו, ואומרות, אני פרשה פלונית שהשלימו אותי צבור פלוני, כך וכך. כלומר, אם כהלכתה או שלא כהלכתה."],[5,"אי אשתלים כדקא וכו':","אם נשלמה הפרשה כראוי לה, עולות מלות אלו ומתעטרות על כסא הקדוש, שהוא המלכות, ומרכבה ההיא משמשת לפניה, כל מרכבה ומרכבה משמשת לפרשה של כל שבת ושבת, כלומר כל מרכבה לפרשה שלה. וכולן מתעטרות בתוך כסא הקדוש, ועמהן הוא עולה להתיחד למעלה למעלה, לז\"א, ונעשה הכל, דהיינו הפרשה והכסא וז\"א, כלל אחד. משום זה אשרי חלקו מי שמשלים הפרשה כל שבת ושבת כראוי, כמו שהפסיקו אותה למעלה."],[6,"תרי זמני קרינן וכו':","ב' פעמים קוראים בתורה בשבת, א' בבוקר, ב' במנחה, בשעה שהדין תלוי בימות החול, לעת ערב. כי צריכים לכלול השמאל בימין, כי התורה ניתנה מב' הצדדים, שכתוב, מימינו אש דת למו. הרי שהתורה היא \u0003אש,\u0004 שהיא שמאל, \u0003ומימינו.\u0004 הוינו ימין ושמאל. וע\"כ קוראים בה בבוקר שהוא ימין, ובמנחה שהיא שמאל. וע\"כ ספר תורה במנחה היא בעשרה פסוקים או יותר, אבל לא פרשה שלמה, כי פרשה שלמה אינה אלא בימין, והימין תלוי מטרם שעת המנחה. אבל במנחה היא שמאל. וכבר העמידוה."],[7,"בשני בשבתא ובחמשי וכו':","בשני בשבת ובחמשי בשבת, משום שהמדרגות יורדות למטה, כי בימות החול משמשים יעקב ורחל במקום זו\"ן הגדולים, שהם מלבישים מחזה ולמטה דז\"א, שהם כלל התורה, כי יעקב הוא בחינת תורה כמו ז\"א. ואם תאמר הרי נביאים נתפרשו למטה. כלומר שיעקב מלביש רק נה\"י דז\"א שהם בחינת נביאים ולא תורה, כי תורה היא בחינת חג\"ת. וא\"כ למה קוראים בתורה. ומשיב, אלא כך הוא ודאי שיעקב מלביש על נה\"י דז\"א, אבל אלו שלמטה, דהיינו ט\"ס דיעקב, כולם הם כלל התורה. כלומר שיעקב בכללו הוא בחינת חג\"ת, שהוא תורה, כמו ז\"א. וכל ספירה וספירה כלולה מכל ספירה וספירה. וכיון שכלולים זו מזו הרי יש בכל אחת חג\"ת שהוא תורה."],[8,"ורזא דמלה אלין וכו':","וסוד הדבר, אלו מדרגות העליונות, שהן ז' ספירות חג\"ת נה\"י דז\"א (כנ\"ל אות ר\"כ) הן נקראות פרשה אחת, דהיינו פרשת השבוע, ואח\"כ יוצאות מהן תשעה מדרגות המאוחדות יחד. שהם תשע ספירות דיעקב, ובשביל זה קורים ט' אנשים, ג' בשבת במנחה, שהם נגד חב\"ד דיעקב. וג' ביום השני, שהם נגד חג\"ת דיעקב. וג' ביום ה', שהם כנגד נה\"י דיעקב. הרי תשעה. וכבר נתבאר בדבור הסמוך, שהט' ספירות נכללות זו מזו, וע\"כ יש בכל אחת חג\"ת שהוא תורה, ואפילו בנה\"י."],[9,"ובספרא דרב ייבא וכו':","בספרו של ר' ייבא הזקן, כתוב, במנחה בשבת נתעורר סוד השמאל, ונקודה תחתונה, שהיא המלכות, מקבלת בצד שמאל ההוא את סוד התורה. אז בשעה ההיא המלכות נוסעת מצד שמאל, ומצדו אנו קורים בתורה. כלומר אע\"פ שהמלכות בעצמה אינה בחינת תורה שבכתב, כיון שמקבלת מצד שמאל דז\"א בחינת התורה שבכתב, ע\"כ אנו קורים בתורה."]],[[0,"","וְאוֹתוֹ שֶׁקּוֹרֵא בַתּוֹרָה, יָשִׂים לִבּוֹ וּרְצוֹנוֹ לְאוֹתָם דְּבָרִים, וְכִי הוּא שְׁלִיחַ רִבּוֹנוֹ בְּסִדּוּרָם שֶׁל הַדְּבָרִים הַלָּלוּ לְהַשְׁמִיעַ לְכָל הָעָם, שֶׁהֲרֵי הוּא עוֹמֵד כְּדֻגְמָה עֶלְיוֹנָה. מִשּׁוּם כָּךְ, מִי שֶׁעוֹלֶה לִקְרֹא בַתּוֹרָה, יְסַדֵּר אוֹתָם דְּבָרִים בָּרִאשׁוֹנָה בְּבֵיתוֹ, וְאִם לֹא, לֹא יִקְרָא בַתּוֹרָה. מִנַּיִן לָנוּ? מֵאוֹתוֹ דִּבּוּר, שֶׁטֶּרֶם יַשְׁמִיעַ תּוֹרָה לָעָם הַקָּדוֹשׁ, מַה כָּתוּב? (איוב כח) אָז רָאָהּ וַיְסַפְּרָהּ הֱכִינָהּ וְגַם חֲקָרָהּ. וְאַחַר כָּךְ, וַיֹּאמֶר לָאָדָם הֵן יִרְאַת ה' הִיא חָכְמָה וְגוֹ'."],[1,"","אָסוּר לוֹ לְמִי שֶׁקּוֹרֵא בַתּוֹרָה לְהַפְסִיק בַּפָּרָשָׁה אוֹ אֲפִלּוּ דָּבָר אֶחָד, אֶלָּא רַק בְּמָקוֹם שֶׁהִפְסִיק מֹשֶׁה אֶת הַפָּרָשָׁה לָעָם הַקָּדוֹשׁ - יַפְסִיק, וְלֹא יַפְסִיק דִּבְרֵי פָּרָשַׁת שַׁבָּת זוֹ בְּפָרָשַׁת שַׁבָּת אַחֶרֶת."],[2,"","הַסּוֹד הַזֶּה, בְּשָׁעָה שֶׁהִפְסִיקוּ פָרָשִׁיּוֹת, כָּל אַחַת וְאַחַת מִתְעַטֶּרֶת וְעוֹמֶדֶת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. כֵּיוָן שֶׁהִשְׁלִימוּ לְהַפְסִיק לְכָל הַשָּׁנָה אֶת הַפָּרָשִׁיּוֹת הַלָּלוּ, הִתְעַטְּרוּ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְאוֹמְרוֹת: אֲנִי מִשַּׁבָּת פְּלוֹנִי (מצבור פלוני), וַאֲנִי מִשַּׁבָּת פְּלוֹנִי (מצבור פלוני)."],[3,"","בְּאוֹתָהּ שָׁעָה קוֹרֵא לְיוּפִיאֵ\"ל מְמֻנֶּה הַגָּדוֹל, וְלַחֲמִשִּׁים וְשָׁלֹשׁ מֶרְכָּבוֹת קְדוֹשׁוֹת שֶׁתַּחַת יָדוֹ שֶׁהִתְמַנּוּ לְשִׁמּוּשָׁהּ שֶׁל תּוֹרָה, וְכָל מֶרְכָּבָה וּמֶרְכָּבָה מִנָּה אוֹתָהּ אֶת הַמֶּרְכָּבָה הַזּוֹ עַל פָּרָשָׁה פְּלוֹנִית שֶׁבְּשַׁבָּת פְּלוֹנִית, וּמֶרְכָּבָה פְּלוֹנִית עַל פָּרָשָׁה פְּלוֹנִית שֶׁל שַׁבָּת פְּלוֹנִית. וְכָל אַחַת וְאַחַת מְשַׁמֶּשֶׁת אֶת הַתּוֹרָה שֶׁל אוֹתָהּ שַׁבָּת שֶׁלָּהּ, וְאָסוּר לָנוּ לְעָרֵב אֵלֶּה בְּאֵלֶּה, וְלֹא לְהַכְנִיס מֶרְכָּבָה לְמֶרְכֶּבֶת חֲבֶרְתָּהּ אֲפִלּוּ כִּמְלֹא נִימָה, וַאֲפִלּוּ בְּתֵבָה אַחַת אוֹ אֲפִלּוּ בְּאוֹת אַחַת. אֶלָּא כָּל אַחַת וְאַחַת כְּפִי שֶׁפָּסַק לָהֶן הַקָּדוֹשׁ בָּרוּךְ הוּא, וּכְמוֹ שֶׁמִּנָּה אוֹתָן בְּאוֹתָן פָּרָשִׁיּוֹת, כָּל אַחַת וְאַחַת עַל מִשְׁמַרְתָּהּ."],[4,"","וְלָכֵן כְּשֶׁמִּתְעַטֶּרֶת פָּרָשָׁה זוֹ, עוֹלוֹת אוֹתָן הַמִּלִּים שֶׁל אוֹתָהּ הַפָּרָשָׁה שֶׁנִּשְׁלְמָה בַּצִּבּוּר, וְאוֹתָהּ מֶרְכָּבָה לוֹקַחַת אוֹתָם, זוֹ שֶׁמְּמֻנָּה עַל אוֹתָהּ פָּרָשָׁה, וּמַעֲלָה אוֹתָם לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְאוֹתָם מִלִּים מַמָּשׁ עוֹמְדוֹת לְפָנָיו וְאוֹמְרוֹת: אֲנִי פָּרָשָׁה פְּלוֹנִית שֶׁהִשְׁלִימוּנִי צִבּוּר פְּלוֹנִי כָּךְ וְכָךְ."],[5,"","אִם הִשְׁתַּלְּמָה כָּרָאוּי לָהּ, מַעֲלִים אֶת אוֹתָן מִלִּים, וּמִתְעַטְּרוֹת עַל הַכִּסֵּא הַקָּדוֹשׁ, וְאוֹתָהּ מֶרְכָּבָה מְשַׁמֶּשֶׁת לְפָנָיו, כָּל מֶרְכָּבָה וּמֶרְכָּבָה, הַפָּרָשָׁה שֶׁל כָּל שַׁבָּת וְשַׁבָּת, וְכֻלָּן מִתְעַטְּרוֹת בְּתוֹךְ הַכִּסֵּא הַקָּדוֹשׁ, וּבָהֶן הִיא עוֹלָה לְהִתְיַחֵד לְמַעְלָה לְמַעְלָה, וְהַכֹּל נַעֲשֶׂה כְּלָל אֶחָד. מִשּׁוּם כָּךְ, אַשְׁרֵי חֶלְקוֹ מִי שֶׁמַּשְׁלִים פָּרָשַׁת כָּל שַׁבָּת וְשַׁבָּת כָּרָאוּי כְּמוֹ שֶׁפִּסְּקוּ אוֹתָהּ לְמַעְלָה."],[6,"","פַּעָמַיִם קוֹרְאִים בְּסֵפֶר תּוֹרָה בְּשַׁבָּת; בַּמִּנְחָה, בְּשָׁעָה שֶׁהַדִּין תָּלוּי לְעֵת עֶרֶב, צְרִיכִים לְהַכְלִיל שְׂמֹאל בְּיָמִין, שֶׁהֲרֵי תּוֹרָה נִתְּנָה מִשְּׁנֵי צְדָדִים, שֶׁכָּתוּב (דברים לג) מִימִינוֹ אֵשׁ דָּת לָמוֹ, מִיָּמִין וּשְׂמֹאל. מִשּׁוּם כָּךְ לְסֵפֶר הַתּוֹרָה בְּמִנְחָה דַּי בַּעֲשָׂרָה פְסוּקִים אוֹ יוֹתֵר, אֲבָל לֹא שְׁלֵמוּת הַפָּרָשָׁה, שֶׁהֲרֵי שְׁלֵמוּת הַפָּרָשָׁה אֵינָהּ אֶלָּא בְּיָמִין, וְהַיָּמִין תָּלוּי עַד שְׁעַת הַמִּנְחָה, וַהֲרֵי פֵּרְשׁוּהָ."],[7,"","בַּשֵּׁנִי בְּשַׁבָּת וּבַחֲמִישִׁי בְּשַׁבָּת, מִשּׁוּם שֶׁיּוֹרְדוֹת הַדְּרָגוֹת לְמַטָּה, שֶׁהֵם כְּלַל הַתּוֹרָה. וְאִם תֹּאמַר, הֲרֵי נְבִיאִים הִתְפָּרְשׁוּ לְמַטָּה - אֶלָּא כָּךְ זֶה וַדַּאי. אֲבָל אֵלֶּה שֶׁלְּמַטָּה, כֻּלָּם כְּלָל שֶׁל הַתּוֹרָה, וְכָל אֶחָד וְאֶחָד כּוֹלֵל כָּל אֶחָד וְאֶחָד."],[8,"","וְסוֹד הַדָּבָר - הַדְּרָגוֹת הָעֶלְיוֹנוֹת הַלָּלוּ הֵן נִקְרָאוֹת פָּרָשָׁה אַחַת, וְאַחַר כָּךְ יוֹצְאוֹת מֵהֶן תֵּשַׁע דְּרָגוֹת שֶׁנֶּאֱחָזוֹת כְּאחָד, וּמִשּׁוּם כָּךְ תִּשְׁעָה אֲנָשִׁים; שְׁלֹשָׁה בְּמִנְחָה בְּשַׁבָּת, וּשְׁלֹשָׁה בְּיוֹם שֵׁנִי, וּשְׁלֹשָׁה בְּיוֹם חֲמִישִׁי. הֲרֵי תִּשְׁעָה."],[9,"","וּבַסֵּפֶר שֶׁל רַב יֵיבָא סָבָא, בְּמִנְחָה בְּשַׁבָּת הֲרֵי הִתְעוֹרְרוּת שֶׁל שְׂמֹאל, וְהַנְּקֻדָּה הַתַּחְתּוֹנָה בְּאוֹתוֹ צַד הַשְּׂמֹאל מְקַבֶּלֶת סוֹד הַתּוֹרָה. אָז בְּאוֹתָהּ שָׁעָה נוֹסַעַת מִצַּד שְׂמֹאל, וּמִשֶּׁלָּהּ אָנוּ קוֹרְאִים."]]],[["דְּהָא אִיהִי קַיְּימָא בְּרָזָא דְּתֵשַׁע, (נ\"א ספיראן) וְקָרֵינָן תֵּשַׁע, וְאִינּוּן שִׁית דְּחוֹל, וּתְלַת בְּשַׁעֲתָא דְּאִתְּעַר שְׂמָאלָא בְּשַׁבְּתָא, וּלְאִתְכַּלְלָא כֹּלָּא כַּחֲדָא. וְאִיהִי מִתְעַטְּרָא בְּהוּ, בִּתְלַת סִטְרִין, כְּגַוְונָא דִּתְלַת סִטְרִין עִלָּאִין, דְּאִינּוּן כְּלָלָא דְּפַרְשְׁתָּא דְּשַׁבְּתָא. זַכָּאָה חוּלָקֵיהּ מַאן דְּזָכֵי לִיקָרָא דְּשַׁבְּתָא, זַכָּאָה אִיהוּ בִּתְרֵין עָלְמִין, בְּעָלְמָא דֵּין, וּבְעָלְמָא דְּאָתֵי.","כְּתִיב (שמות ט״ז:כ״ט) אַל יֵצֵא אִישׁ מִמְּקוֹמוֹ בַּיוֹם הַשְּׁבִיעִי מַהוּ מִמְּקוֹמוֹ. תָּנֵינָן, מִמְּקוֹמוֹ מֵהַהוּא אֲתָר דְּאִתְחָזֵי לִמֵהַךְ. וְרָזָא דְּמִלָּה, דִּכְתִּיב, (יחזקאל ג׳:י״ב) בָּרוּךְ כְּבוֹד יְיָ' מִמְּקוֹמוֹ. וְדָא אִיהוּ מָקוֹם, וְדָא אִיהוּ רָזָא דִּכְתִּיב, (שמות ג׳:ה׳) כִּי הַמָּקוֹם אֲשֶׁר אַתָּה עוֹמֵד עָלָיו. אֲתָר יְדִיעָא אִיהוּ לְעֵילָּא, וְקָרֵינָן לֵיהּ מָקוֹם, דְּאִשְׁתְּמוֹדָע בֵּיהּ יְקָרָא עִלָּאָה דִּלְעֵילָּא. וּבְּגִין כָּךְ, אַזְהָרוּתָא לְבַּר נָשׁ דְּהָא מִתְעַטְּרָא בְּעִטְרָא קַדִּישָׁא דִּלְעֵילָּא, דְּלָא יִפּוֹק מִינֵּיהּ דְּאִי (יפוק מפומיה מילולא דחול) יִפּוֹק מִנֵיהּ, קָא מְחַלֵּל שַׁבְּתָא. בִּידוֹי, בַּעֲבִידְתָּא. כְּמָה דְּאוֹקִימְנָא. בְּרַגְלוֹי, לְמֵהַךְ לְבַר מִתְּרֵי אַלְפִין אַמִּין, כָּל אִלֵּין חִלּוּלָא דְּשַׁבְּתָא אִיהוּ.","אַל יֵצֵא אִישׁ מִמְּקוֹמוֹ, דָּא אִיהוּ אֲתָר יְקָרָא דִּקְדוּשָּׁה דָּא, דְּהָא מִנֵּיהּ לְבַר, אֲתָר דֶּאֱלהִים אֲחֵרִים אִיהוּ. בָּרוּךְ כְּבוֹד יְיָ' מִמְּקוֹמוֹ. כְּבוֹד יְיָ' (בראשית כ\"ה ע\"א) דִּלְעֵילָּא. מִמְּקוֹמוֹ, דָּא כְּבוֹד דִּלְתַתָּא וְדָא אִיהוּ רָזָא דַּעֲטָּרָא דְּשַׁבְּתָא, בְּגִין כָּךְ אַל יֵצֵא אִישׁ מִמְּקוֹמוֹ, בְּרִיךְ הוּא לְעָלַם וּלְעָלְמֵי עָלְמִין.","כְּתִיב (שמות ל״ג:כ״א) הִנֵּה מָקוֹם אִתִּי, מָקוֹם אִתִּי, וַדַּאי דָּא אִיהוּ מָקוֹם טָמִיר וְגָנִיז, דְּלָא אִתְיְידָע כְּלַל. מַשְׁמַע דִּכְתִּיב אִתִּי, אֲתָר דְּלָא אִתְגַּלְיָא, וְקַיְּימָא טְמִירָא, וְדָא אִיהוּ אֲתָר עִלָּאָה לְעֵילָּא לְעֵילָּא, הֵיכָלָא עִלָּאָה טָמִיר וְגָנִיז. אֲבָל דָּא, אִיהוּ אֲתָר לְתַתָּא כִּדְקָאָמְרָן. וְדָא אִיהוּ מָקוֹם דְּאִתְפְּרַשׁ לְעֵילָּא, וְאִתְפְּרַשׁ לְתַתָּא, וּבְּגִין כָּךְ אַל יֵצֵא אִישׁ מִמְּקוֹמוֹ בַּיוֹם הַשְּׁבִיעִי.","(במדבר ל״ה:ה׳) וּמַדֹתֶם מִחוּץ לָעִיר אֶת פְּאַת קֵדְמָה אַלְפַּיִם בָּאַמָּה וְגוֹ', (רט) הָא אוּקְמוּהָ בְּאִינּוּן רָזִין עִלָּאִין. אֲבָל אַלְפַּיִם בָּאַמָּה, דְּיָרְתָה תְּרֵין (הקדמה ה' ע\"א) סִטְרִין לְכָל סְטָר, וְאִיהִי מִתְעַטְּרָא תָּדִיר בִּתְרֵין סִטְרִין, בֵּין לְעֵילָּא בֵּין לְתַתָּא. וְסִימָנִךְ שְׁכִינָה לָא שַׁרְיָא לְבַר מִתְּחוּמָא דְּאִתְחָזֵי לָהּ.","כַּד נָפַק שַׁבְּתָא, צְרִיכִין יִשְׂרָאֵל דִּלְתַתָּא, לְאַעְכָּבָא, דְּהָא יוֹמָא רַבָּא עִלָּאָה אִיהוּ. (אצטריך לאתעכבא עליה) וּבְהַאי יוֹמָא, אוּשְׁפִּיזָא רַבָּא וְיַקִּירָא, קָא שַׁרְיָא עָלֵיהּ, בְּגִין כַּךְ בָּעֵי לְאִתְעַכְּבָא, לְאִתְחֲזָאָה דְּלָא דָּחֲקִין בְּאוּשְׁפִּיזָא קַדִּישָׁא. כְּדֵין פַּתְחֵי יִשְׂרָאֵל וְאַמְרֵי, (תהילים ע״ח:ל״ח) וְהוּא רַחוּם יְכַפֵּר עָוֹן וְגוֹ', דְּתִקּוּנָא שַׁפִּירָא אִיהוּ בְּהַאי לֵילְיָא, כֵּיוָן דְּדִינָא אִתְהַדָּר לְאַתְרֵיהּ, מַה דְּלָא אִתְחָזֵי כַּד עָיִיִל שַׁבְּתָא, דְּדִינָא אִסְתַּלָּק, וְלָא אִשְׁתְּכַח.","בְּשַׁעֲתָא דְּפַתְחֵי יִשְׂרָאֵל וַיְהִי נוֹעַם, וּקְדוּשָׁתָא דְּסִדְרָא, כָּל אִינּוּן חַיָּיבִין דְּגֵיהִנָּם, פַּתְחִין וְאַמְרִי, זַכָּאִין אַתּוּן יִשְׂרָאֵל עַמָּא קַדִּישָׁא, זַכָּאִין אַתּוּן צַדִּיקַיָּיא, דְּנַטְרֵי פִּקּוּדֵי אוֹרַיְיתָא. וַוי לוֹן לְחַיָּיבַיָּא, דְּלָא זָכוּ לְמֵיטַר אוֹרַיְיתָא, כְּדֵין דומ\"ה קָדִים, וְכָרוֹזָא אִתְּעַר וְאָמַר, (תהילים ט׳:י״ח) יָשׁוּבוּ רְשָׁעִים לִשְׁאוֹלָה כָּל גּוֹיִם שְׁכֵחֵי אֱלהִים. וְכָל אִלֵּין חֲבִילֵי טְהִירִין, טַרְדִין לוֹן בְּגֵיהִנָּם, וְלֵית מַאן דִּמְרַחֵם עֲלֵיהוֹן. זַכָּאִין אִינּוּן כָּל נַטְרֵי שַׁבְּתָא בְּהַאי עָלְמָא, וְקָא מְעַנְּגֵי לְהַהוּא עֹנְג דְּשַׁרְיָא מִלְּעֵילָּא, כִּדְקָאַמְרָן.","הַאי מַאן דְּשָׁרֵי בְּתַעֲנִיתָא בְּשַׁבְּתָא, תְּרֵי מִתְעָרֵי עָלֵיהּ קַמֵּי מַלְכָּא קַדִּישָׁא. חַד, הַהוּא רוּחָא עִלָּאָה קַדִּישָׁא דְּאִצְטְרִיךְ לְאִתְעַנְּגָא, וְלָא אִתְעַנָּג. וְחַד, הַהוּא מְמָנָא דְּקַיְּימָא עַל מַאן דְּשָׁרֵי בְּתַעֲנִיתָא, וְסַנְגַּרְיָ\"הּ שְׁמֵיהּ. וְסַלְּקִין קָמֵי מַלְכָּא קַדִּישָׁא, וּמִתְעָרֵי עָלֵיהּ.","וְהַהוּא רוּחָא אִסְתַּלָּק גְּרִיעַ מֵהַהוּא אִתְהֲנוּתָא דִּלְתַתָּא. וְכַד הַאי רוּחָא לָא אִשְׁתְּלִים לְתַתָּא, רוּחָא אַחֲרָא דִּלְעֵילָּא לָא אִשְׁתְּלִים. כֵּיוָן דְּלָא אִשְׁתְּלִים לְתַתָּא וּלְעֵילָּא, כְּדֵין אִתְחָזֵי הַהוּא בַּר נָשׁ לְאִתְלַטְּיָא, וּלְאִתְעָנְּשָׁא. אֶלָּא כֵּיוָן דְּאִשְׁתְּלִים זִמְנָא אַחֲרָא, וְהַהוּא מְמָנָא דְּאִתְמַנָא עַל עִנּוּיָּיא וְתַעֲנִיתָא, אִשְׁתְּלִים גּוֹ אִינּוּן מְמָנָן אַחֲרָנִין, בְּעִנּוּגָא דִּלְעֵילָּא, קוֹרְעִין לֵיהּ כָּל גְּזַר דִּינָא, דְּאִתְגְּזַר מֵאִינּוּן שִׁבְעִין שְׁנִין עִלָּאִין."],[[0,"דהא איהי קיימא וכו':","כי המלכות עומדת בסוד תשע ספירות, וע\"כ קוראים אנו תשעה אנשים, שהם ששה אנשים שהם חג\"ת נה\"י שלה בחול, בב' ובה', ושלשה אנשים שהם ג\"ר שלה, בשעה שנתעורר השמאל בשבת, דהיינו במנחה בשבת, ולכלול כולם כאחד. והיא מתעטרת בהם בג' צדדים ימין שמאל, אמצע, כמו ג' צדדים עליונים, חג\"ת שהם בכלל הפרשה של שבת, שאנו קורים בבוקר. פירוש. אע\"פ שאנו אומרים, שבמנחה דשבת המלכות מקבלת מצד שמאל, אין הפירוש מצד שמאל לבד, אלא שמקבלת מכל ג' הקוין, והכוונה היא רק בשליטת השמאל. אשרי חלקו מי שזכה ליקרו של שבת, אשרי הוא בב' עולמות, בעולם הזה ובעולם הבא."],[1,"כתיב אל יצא וכו':","כתוב, אל יצא איש ממקומו ביום השביעי. שואל, מהו ממקומו. ומשיב, למדנו, \u0003ממקומו,\u0004 פירושו ממקום ההוא הראוי ללכת. דהיינו מחוץ לכל העיר, ואלפים אמה שלה. וסוד הדבר הוא, שכתוב, ברוך כבוד ה' ממקומו. וזהו מקום. וזה הוא סוד שכתוב כי \u0003המקום\u0004 אשר אתה עומד עליו. כי מקום ידוע יש למעלה, שהוא המלכות, וקוראים לו \u0003מקום,\u0004 שנודע בו כבוד העליון של מעלה, שהיא המלכות, וע\"כ, אזהרה היא לאדם המתעטר בעטרה הקדושה שלמעלה, שלא יצא מן \u0003המקום,\u0004 שאם יצא ממנו הוא מחלל שבת (כנ\"ל בשלח אות תי\"ט) ולא בידיו בעבודה, כמו שהעמדנו. ולא ברגליו, ללכת חוץ מב' אלפים אמה. כל אלו הם חלול שבת."],[2,"אל יצא איש ממקומו:","זה הוא מקום כבוד הקדוש הזה, דהיינו המלכות, כי מחוץ ממנו הוא מקום של אלהים אחרים. \u0003ברוך כבוד ה' ממקומו,\u0004 כבוד ה', הוא כבוד שלמעלה שהיא בינה. \u0003ממקומו,\u0004 זהו כבוד שלמטה, שהוא המלכות. וזה הוא סוד העטרה של שבת, ועל כן אל יצא איש ממקומו. ברוך הוא לעולם ולעולמי עולמים."],[3,"כתיב, הנה מקום אתי:","מקום אתי, ודאי זה הוא מקום נסתר וגנוז שלא נודע כלל, שהוא בינה. זה משמע, משכתוב \u0003אתי,\u0004 יורה שהוא מקום שלא נגלה, ועומד בסתר, וזה הוא מקום עליון למעלה למעלה דהיינו היכל העליון הנסתר והגנוז, שהיא בינה עלאה, אבל מקום זה שבכאן, הוא מקום שלמטה, דהיינו המלכות, כמו שאמרנו. וזה הוא מקום שמתפרש למעלה בבינה ומתפרש למטה במלכות. וע\"כ אל יצא איש ממקומו ביום השביעי."],[4,"ומדתם מחוץ לעיל וכו':","כתוב, ומדתם מחוץ לעיר את פאת קדמה אלפים באמה וגו'. הרי העמידוהו באלו סודות העליונים. אבל אלפים אמה, הוא, משום שהמלכות המכונה עיר, ירשה ב' צדדים שהם ימין ושמאל, שהחכמה מלובשת בחסדים והחסדים בחכמה, והם ב' אלפים כי ספירות החכמה הן בסוד אלף. והמלכות מתעטרת תמיד בב' צדדים בין למעלה ובין למטה, וסימנך, שהשכינה אינה שורה חוץ מתחום הראוי לה. שהוא ב' קוין."],[5,"כד נפק שבתא וכו':","כשיצא השבת צריכים ישראל שלמטה להתעכב, דהיינו להוסיף מחול על הקודש, כי יום גדול עליון הוא, וביום הזה אורה גדול ויקר שורה עליו, שהוא נשמה היתירה, משום זה צריך להתעכב ולהראות שאין דוחקים האורח הקדוש להוציאו. אז פותחים ישראל ואומרים והוא רחום יכפר עון וגו'. שהוא תקון יפה בלילה הזה, כיון שהדין חוזר למקומו, מה שלא היה נראה בביאת השבת, שהדין היה אז מסתלק ולא נמצא."],[6,"בשעתא דפתחי ישראל","וכו': בשעה שפותחים ישראל ואומרים ויהי נועם, וקדושה דסדרא, דהיינו ואתה קדוש וכו', כל אלו רשעים שבגיהנם, פותחים ואומרים אשריכם ישראל עם קדוש, אשריכם צדיקים השומרים מצות התורה. אוי להם לרשעים שלא זכו לשמור התורה. אז מקדים דומה, וכרוז מתעורר, ישובו רשעים לשאולה כל גוים שכחי אלקים. וכל אלו גדודים מלאכי חבלה מענים אותם בגיהנם, ואין מי שירחם עליהם, אשריהם כל שומרי שבת בעולם הזה, ומענגים ענג ההוא השורה מלמעלה, דהיינו רוח העליון, כמו שאמרנו (לעיל אות קפ\"ז)."],[7,"האי מאן דשרי וכו':","מי ששורה בתענית בשבת, שנים מתעוררים עליו, לפני מלך הקדוש. אחד, הוא רוח העליון הקדוש שצריכים לענגו ולא נתענג. ואחד, הוא, ממונה ההוא העומד על מי ששורה בתענית, ושמו סנגריה. ועולים לפני המלך הקדוש והם מעוררים עליו."],[8,"וההוא רוחא אסתלק וכו':","ורוח ההוא נסתלק בחסרון מתענוג והנאה ההיא שלמטה, וכשרוח הזה אינו נשלם מלמטה, רוח אחר עליון לא נשלם. כיון שלא נשלם למעלה ולמטה, אז ראוי איש ההוא להתקלל ולהיות נענש. אלא כיון שנשלם בזמן אחר, ע\"י אותו אדם, וממונה ההוא שנתמנה על עינוי ותענית, הוא נשלם בין ממונים אחרים בתענוג העליון, ע\"כ קורעים לו כל גזר דין שנגזר מאלו ע' שנים עליונים, שהם חג\"ת נהי\"מ."]],[[0,"","שֶׁהֲרֵי הִיא עוֹמֶדֶת בַּסּוֹד שֶׁל תֵּשַׁע (ספירות), וְקוֹרְאִים תִּשְׁעָה, וְהֵם שִׁשָּׁה שֶׁל חֹל וּשְׁלֹשָׁה בְּשָׁעָה שֶׁהַשְּׂמֹאל מִתְעוֹרֵר בְּשַׁבָּת, וּלְהַכְלִיל הַכֹּל כְּאֶחָד. וְהִיא מִתְעַטֶּרֶת בָּהֶם בִּשְׁלֹשָׁה צְדָדִים, כְּמוֹ שְׁלֹשֶׁת הַצְּדָדִים הָעֶלְיוֹנִים שֶׁהֵם כְּלָל שֶׁל פָּרָשַׁת הַשַּׁבָּת. אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁזּוֹכה לִכְבוֹד הַשַּׁבָּת. אַשְׁרָיו בִּשְׁנֵי הָעוֹלָמוֹת, בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא."],[1,"","כָּתוּב (שמות טז) אַל יֵצֵא אִישׁ מִמְּקֹמוֹ בַּיּוֹם הַשְּׁבִיעִי. מַה זֶּה מִמְּקֹמוֹ? שָׁנִינוּ, מִמְּקֹמוֹ - מֵאוֹתוֹ מָקוֹם שֶׁרָאוּי לָלֶכֶת. וְסוֹד הַדָּבָר - שֶׁכָּתוּב (יחזקאל ג) בָּרוּךְ כְּבוֹד ה' מִמְּקוֹמוֹ. וְזֶה הַמָּקוֹם. וְזֶהוּ סוֹד הַכָּתוּב (שמות ג) כִּי הַמָּקוֹם אֲשֶׁר אַתָּה עוֹמֵד עָלָיו. מָקוֹם יָדוּעַ הוּא לְמַעְלָה, וְקוֹרְאִים לוֹ מָקוֹם, שֶׁנּוֹדָע בּוֹ הַכָּבוֹד הָעֶלְיוֹן שֶׁלְּמַעְלָה. וּמִשּׁוּם כָּךְ אַזְהָרָה לָאָדָם, שֶׁהֲרֵי מִתְעַטֵּר בַּעֲטָרָה קְדוֹשָׁה שֶׁל מַעְלָה, שֶׁלֹּא יֵצֵא מִמֶּנּוּ. שֶׁאִם (יצא מפיו דבור של חל) יֵצֵא מִמֶּנּוּ, הוּא מְחַלֵּל שַׁבָּת. בְּיָדוֹ - בְּמַעֲשֶׂה, כְּמוֹ שֶׁבֵּאַרְנוּ. בְּרַגְלוֹ - לָלֶכֶת מִחוּץ לְאַלְפַּיִם אַמָּה. כָּל אֵלֶּה הֵם חִלּוּל שַׁבָּת."],[2,"","אַל יֵצֵא אִישׁ מִמְּקֹמוֹ, זֶהוּ מְקוֹם כְּבוֹד הַקְּדֻשָּׁה הַזּוֹ, שֶׁהֲרֵי מִמֶּנּוּ לַחוּץ הוּא מָקוֹם שֶׁל אֱלֹהִים אֲחֵרִים. בָּרוּךְ כְּבוֹד ה' מִמְּקוֹמוֹ. כְּבוֹד ה' שֶׁלְּמַעְלָה. מִמְּקוֹמוֹ - זֶה כָּבוֹד שֶׁלְּמַטָּה, וְזֶהוּ סוֹד שֶׁל עֲטֶרֶת שַׁבָּת. וּמִשּׁוּם כָּךְ, אַל יֵצֵא אִישׁ מִמְּקֹמוֹ. בָּרוּךְ הוּא לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים."],[3,"","כָּתוּב, (שמות לג) הִנֵּה מָקוֹם אִתִּי. מָקוֹם אִתִּי, וַדַּאי זֶהוּ מָקוֹם טָמִיר וְגָנוּז שֶׁלֹּא נוֹדָע כְּלָל. מִמַּשְׁמָע שֶׁכָּתוּב אִתִּי - מָקוֹם שֶׁלֹּא הִתְגַּלָּה וְעוֹמֵד טָמִיר, וְזֶהוּ מָקוֹם עֶלְיוֹן לְמַעְלָה לְמַעְלָה, הֵיכָל עֶלְיוֹן טָמִיר וְגָנוּז. אֲבָל זֶהוּ מָקוֹם לְמַטָּה, כְּפִי שֶׁאָמַרְנוּ. וְזֶהוּ מָקוֹם שֶׁנִּפְרָד לְמַעְלָה וְנִפְרָד לְמַטָּה, וּמִשּׁוּם כָּךְ אַל יֵצֵא אִישׁ מִמְּקֹמוֹ בַּיּוֹם הַשְּׁבִיעִי."],[4,"","וּמַדֹּתֶם מִחוּץ לָעִיר אֶת פְּאַת קֵדְמָה אַלְפַּיִם בָּאַמָּה וְגוֹ' (במדבר לה), הֲרֵי פֵּרְשׁוּהָ בְּאוֹתָם סוֹדוֹת עֶלְיוֹנִים. אֲבָל אַלְפַּיִם בָּאַמָּה - שֶׁיָּרְשָׁה שְׁנֵי צְדָדִים לְכָל צַד, וְהִיא מִתְעַטֶּרֶת תָּמִיד בִּשְׁנֵי צְדָדִים, בֵּין לְמַעְלָה בֵּין לְמַטָּה. וְסִימָנְךְ - שְׁכִינָה לֹא שׁוֹרָה מִחוּץ לַתְּחוּם הָרָאוּי לָהּ."],[5,"","כְּשֶׁיּוֹצֵאת שַׁבָּת, צְרִיכִים יִשְׂרָאֵל שֶׁלְּמַטָּה לְהִתְעַכֵּב, שֶׁהֲרֵי הוּא יוֹם גָּדוֹל עֶלְיוֹן, (צריךלהתעכבעליו) וּבַיּוֹם הַזֶּה שׁוֹרֶה עָלָיו אוֹרֵחַ גָּדוֹל וְנִכְבָּד, וּמִשּׁוּם כָּךְ צָרִיךְ לְהִתְעַכֵּב, לְהַרְאוֹת שֶׁלֹּא דוֹחֲקִים בָּאוֹרֵחַ הַקָּדוֹשׁ. אָז פּוֹתְחִים יִשְׂרָאֵל וְאוֹמְרִים, (תהלים עח) וְהוּא רַחוּם יְכַפֵּר עָון וְגוֹ'. שֶׁתִּקּוּן יָפֶה הוּא בַּלַּיְלָה הַזֶּה, כֵּיוָן שֶׁהַדִּין חוֹזֵר לִמְקוֹמוֹ - מַה שֶּׁלֹּא רָאוּי כְּשֶׁנִּכְנֶסֶת שַׁבָּת, כְּשֶׁהַדִּין מִסְתַּלֵּק וְלֹא נִמְצָא."],[6,"","בְּשָׁעָה שֶׁפּוֹתְחִים יִשְׂרָאֵל \"וִיהִי נֹעַם\" וְסֵדֶר הַקְּדֻשָּׁה, כָּל אוֹתָם רִשְׁעֵי הַגֵּיהִנֹּם פּוֹתְחִים וְאוֹמְרִים: אַשְׁרֵיכֶם יִשְׂרָאֵל, הָעָם הַקָּדוֹשׁ. אַשְׁרֵיכֶם הַצַּדִּיקִים הַשּׁוֹמְרִים אֶת מִצְווֹת הַתּוֹרָה. אוֹי לָרְשָׁעִים שֶׁלֹּא זָכוּ לִשְׁמֹר תּוֹרָה. אָז דּוּמָ\"ה מַקְדִּים, וּמִתְעוֹרֵר כָּרוֹז וְאוֹמֵר: (שם ט) יָשׁוּבוּ רְשָׁעִים לִשְׁאוֹלָה כָּל גּוֹיִם שְׁכֵחֵי אֱלֹהִים. וְכָל קְבוּצוֹת הָרוּחוֹת הַלָּלוּ טוֹרְדוֹת אוֹתָם בַּגֵּיהִנֹּם, וְאֵין מִי שֶׁמְּרַחֵם עֲלֵיהֶם. אַשְׁרֵיהֶם כָּל שׁוֹמְרֵי הַשַּׁבָּת בָּעוֹלָם הַזֶּה, וּמְעַנְּגִים אֶת אוֹתוֹ הָעֹנֶג שֶׁשּׁוֹרֶה מִלְמַעְלָה, כְּפִי שֶׁאָמַ רְנוּ."],[7,"","זְהִ מִי שֶׁשּׁוֹרֶה בְתַעֲנִית בְּשַׁבָּת, שְׁנַיִם מִתְעוֹרְרִים עָלָיו לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ. אֶחָד, אוֹתָהּ רוּחַ עֶלְיוֹנָה קְדוֹשָׁה שֶׁהִצְטָרֵךְ לְהִתְעַנֵּג וְלֹא הִתְעַנֵּג. וְאֶחָד, אוֹתוֹ מְמֻנֶּה שֶׁעוֹמֵד עַל מִי שֶׁשָּׁרוּי בְּתַעֲנִית, וּשְׁמוֹ סַנְגַּרְיָ\"ה. וְעוֹלִים לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ וּמִתְעוֹרְרִים עָלָיו."],[8,"","וְאוֹתָהּ רוּחַ מִסְתַּלֶּקֶת חֲסֵרָה מֵאוֹתָהּ הֲנָאָה שֶׁלְּמַטָּה. וּכְשֶׁהָרוּחַ הַזּוֹ לֹא נִשְׁלְמָה לְמַטָּה, רוּחַ אַחֶרֶת שֶׁלְּמַעְלָה לֹא נִשְׁלְמָה. כֵּיוָן שֶׁלֹּא נִשְׁלְמוּ לְמַטָּה וּלְמַעְלָה, אָז רָאוּי אוֹתוֹ אָדָם לְהִתְקַלֵּל וּלְהֵעָנֵשׁ. אֶלָּא כֵּיוָן שֶׁנִּשְׁלַם בִּזְמַן אַחֵר, וְאוֹתוֹ מְמֻנֶּה שֶׁהִתְמַנָּה עַל עִנּוּי וְתַעֲנִית נִשְׁלָם בְּתוֹךְ אוֹתָם מְמֻנִּים אֲחֵרִים בָּעֹנֶג שֶׁלְּמַעְלָה, קוֹרְעִים לוֹ כָּל גְּזַר דִּינוֹ שֶׁנִּגְזַר מֵאוֹתָם שִׁבְעִים שָׁנִים עֶלְיוֹנִים."]]],[["לְמַלְכָּא דְּחַדֵּי בְּהִלּוּלָא דִּילֵיהּ, וְכָל בְּנֵי נָשָׁא חַדָּאן עִמֵּיהּ, חָמָא חַד בַּר נָשׁ יָהִיב בְּקוֹלָר, פָּקִיד עֲלוֹי, וְשַׁרְייוּהוּ. בְּגִין דְּיִשְׁתַּכְּחוּן כּוֹלָּא בְּחֶדְוָה.","וּלְבָתַר, מִתְהַדְּרִין אִלֵּין מְמָנָן דְּעַנְשִׁין לִבְנֵי נָשָׁא, וְאִתְפָּרְעִין מִנֵּיהּ דְּבַּר נָשׁ, עַל דְּאִשְׁתְּכַח בְּגִינֵיהּ גְּרִיעוּתָא עֵילָּא וְתַתָּא. מַאי תָּקַּנְתֵּיהּ. לֵיתִיב תַּעֲנִיתָא עַל תַּעֲנִיתָא. מַאי טַעֲמָא. דָּא בָּטִּיל עִנּוּגָא דְּשַׁבְּתָא, יְבַטֵּל עִנּוּגָא דְּחוֹל.","וְאִי אִיהוּ מְבַטֵּל עִנּוּגָא דְּשַׁבְּתָא, וְקָא מִתְעַנֵּג בַּחוֹל, דָּמֵי כְּמַאן דְּחָשַׁב לְמִלָּה אַחֲרָא, יַתִּיר מִמַּה דְּחָשִׁיב לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא. רוּחָא עִלָּאָה, קַדִּישָׁא דְּקוּדְשִׁין דְּשַׁרְיָא עָלֵיהּ, לָא עָנִיג, וּבָטִּיל לֵיהּ מִנֵּיהּ. רוּחָא אַחֲרָא דְּחוֹל, דְּשַׁרְיָא לְבָתַר עַל עָלְמָא, חָשִׁיב וְקָא מְעַנְגָא לֵיהּ. כְּדֵין מְהַדְּרִין וּמִתְפָּרְעִין מִנֵּיהּ, בְּהַאי עָלְמָא, וּבְעָלְמָא דְּאָתֵי.","בְּגִין כַּךְ, אִצְטְרִיךְ תַּעֲנִיתָא אַחֲרִינָא, בְּיוֹמָא קַדְמָאָה דְּחוֹל, בְּזִמְנָא דְּשַׁרְיָא עַל עָלְמָא הַהוּא רוּחָא דְּחוֹל. וּבְהַאי אִית לֵיהּ אַסְוָותָא, כֵּיוָן דְּלָא חָשִׁיב לְרוּחָא דְּחוֹל. וְסִימָנִיךְ (ויקרא ה׳:כ״ג) וְהֵשִׁיב אֶת הַגְּזֵלָה אֲשֶׁר גָּזָל וְגוֹ'. גַּזְלָן, לָא חָשִׁיב לְקוּדְשָׁא בְּרִיךְ הוּא, לָא חָשִׁיב לִבְנִי נָשָׁא, בְּגִין כַּךְ לֵית לֵיהּ עוֹנְשָׁא כַּגַּנָּב. גַּנָּב, דְּחָשִׁיב לִבְנִי נָשָׁא, יַתִּיר מְקוּדְשָׁא בְּרִיךְ הוּא, אִית לֵיהּ עוֹנְשָׁא בְּהַאי עָלְמָא, וּבְעָלְמָא דְּאָתֵי. זַכָּאָה אִיהוּ, מַאן דְּאִשְׁתְּלִים לְתַתָּא, לְהַהוּא עוֹנֶג עִלָּאָה כַּדְקָא חֲזֵי.","יוֹמָא דָּא, מִתְעַטְּרָא בְּשִׁבְעִין עִטְרִין, וּשְׁמָא עִלָּאָה (פ\"ח ע\"ב) קַדִּישָׁא, אִשְׁתְּלִים בְכָל סִטְרִין, וְאִתְנְהִירוּ כֻּלְּהוּ דַּרְגִּין, וְכֹלָּא בְּחֶדְוָה דְּבִרְכָּאן, וּבִקְדוּשָּׁה עַל קְדוּשָׁה, וְתוֹסֶפֶת דִּקְדוּשָּׁה.","קִדוּשָׁה דְּמַעֲלֵי שַׁבְּתָא, דָּא אִיהִי קְדוּשָּׁה דְּשַׁבָּת בְּרֵאשִׁית. דְּהָא אִתְקַדָּשׁ מִתְּלָתִין וּתְרֵין שְׁבִילִין, וּתְלַת דַּרְגִּין דְּתַפּוּחִין (ויחי רמ\"ט ע\"ב) קַדִּישִׁין. וּבָעֵינָן לְאַדְכְּרָא עַל הַאי קִדוּשָׁה, כְּלָלָא דְּעוֹבָדָא דִּבְרֵאשִׁית, וְנַיְיחָא בְּרָזָא דִּתְלָתִין וּתְרֵין שְׁבִילִין, וּתְלַת דַּרְגִּין דְּאִתְכְּלִילָן בְּהוּ, רָזָא דְּסַהֲדוּתָא דְּעוֹבָדָא דִּבְרֵאשִׁית, דְּהַיְינוּ (בראשית ב׳:א׳-ב׳) וַיְכֻלּוּ הַשָּׁמַיִם וְהָאָרֶץ וְכָל צְבָאָם וְגוֹ'. וַיְכַל אֱלהִים, דְּאִית בְּסַהֲדוּתָא דָּא, תְּלָתִין (הקדמה ה' ע\"ב) וַחֲמֵשׁ תֵּיבִין. תְּלָתִין וּתְרֵין שְׁבִילִין, וּתְלַת דַּרְגִּין דְּתַפּוּחִין קַדִּישִׁין.","תְּלַת דַּרְגִּין, דְּאִינּוּן: שְׁבִיעִי. שְׁבִיעִי. שְׁבִיעִי. וְאִית בֵּיהּ רָזָא דְּעָלְמָא עִלָּאָה, וְרָזָא דְּעָלְמָא תַּתָּאָה, וְרָזָא דְּכָל מְהֵימְנוּתָא. תְּלַת זִמְנִין אֱלֹהִים, חַד, עָלְמָא תַּתָּאָה. וְחַד, פַּחַד יִצְחָק. וְחַד, עָלְמָא עִלָּאָה קַדִּישָׁא, קֹדֶשׁ קוּדְשִׁין. בָּעֵי בַּר נָשׁ לְמִסְהַד סַהֲדוּתָא דָּא, בְּחֶדְוָה, בִּרְעוּתָא דְּלִבָּא, לְאַסְהֲדָא קַמֵּי מָארֵיהּ דִּמְהֵימְנוּתָא. וְכָל מַאן דְּיַסְהִיד דָּא, וְיִשָׁוֵי לִבֵּיהּ וּרְעוּתֵיהּ לְדָא, מְכַפֵּר עַל כָּל חוֹבוֹי.","בָּרוּךָ אַתָּה יָיְ אֱלֹקֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְרָצָה בָנוּ וְכוּ', הַאי קִידּוּשָׁא אִיהוּ בְּחַד מַתְקְלָא, לָקֳבֵל סַהֲדוּתָא דִּמְהֵימְנוּתָא, וְאִינּוּן תְּלָתִין וַחֲמֵשׁ תֵּיבִין אַחֲרָנִין, כַּמָה דְּאִית בְּוַיְכֻלּוּ. כֹּלָּא סַלְּקִין לְשִׁבְעִין תֵּיבִין, (קל\"ב ע\"ב) לְאִתְעַטְּרָא בְּהוּ שַׁבָּת, דְּמַעֲלֵי שַׁבְּתָא. זַכָּאָה חוּלָקֵיהּ דְּבַר נָשׁ, דִּיְּכַוֵּון רְעוּתֵיהּ לְמִלִּין אִלֵּין, לִיקָרָא דְּמָארֵיהּ.","קִידּוּשָׁא דְּיוֹמָא, הָא אוּקְמוּהָ בּוֹרֵא פְּרִי הַגֶּפֶן, וְלָא יַתִּיר. דְּהָא יוֹמָא קָאִים לְקַדְּשָׁא לֵיהּ, מַה דְּלֵית הָכִי בְּלֵילְיָא, דְּאֲנָן צְרִיכִין לְקַדְּשָׁא לֵיהּ, בְּהָנִי מִלִּין, כְּמָה דְּאוֹקִימְנָא. וְלָא אִתְקַדָּשׁ הַאי לֵילְיָא, אֶלָּא בְּעַמָּא קַדִּישָׁא לְתַתָּא, כַּד שַׁרְיָא עָלַיְיהוּ הַהוּא רוּחָא עִלָּאָה. וַאֲנָן בָּעֵינָן לְקַדְּשָׁא לֵיהּ בִּרְעוּתָא דְּלִבָּא, לְכַוְּונָא דַּעְתָּא לְהַאי.","וְיוֹמָא אִיהוּ קָא מְקַדְּשָׁא לֵיהּ. וְיִשְׂרָאֵל מְקַדְּשֵׁי בִּצְלוֹתִין וּבָעוּתִין, וּמִתְקַדְשִׁין בִּקְדוּשָׁתֵיהּ, בְּהַאי יוֹמָא. זַכָּאִין יִשְׂרָאֵל, עַמָּא קַדִּישָׁא, דְּאַחֲסִינוּ יוֹמָא דָּא, אַחֲסָנַת יְרוּתָא לְעָלְמִין.","לְבָתַר דְּנָפִיק שַׁבְּתָא, בָּעֵי בַּר נָשׁ לְאַפְרָשָׁא, בֵּין קֹדֶשׁ לְחוֹל. אֲמַאי. דְּהָא אִתְיְהִיב רְשׁוּ לִמְמָנָן דִּלְתַתָּא לְשַׁלְּטָאָה עַל עָלְמָא, וּבְכָל עוֹבָדִין דְּעָלְמָא, לְאַחֲזָאָה יִחוּדָא, בְּאֲתָר קַדִּישָׁא, בִּקְדוּשָּׁה עִלָּאָה, וּלְאַפְרְשָׁא לְתַתָּא מִיִחוּדָא עִלָּאָה, וּלְבָרְכָא עַל נְהוֹרָא דְּאֶשָּׁא."],[[0,"למלכא דחדי בהלולא וכו':","בדומה למלך השמח במשתה שלו, וכל בני אדם שמחים עמו. ראה איש אחד יושב אסור בכבלים, פקד עליו והתירוהו. כדי שימצאו כולם בשמחה."],[1,"ולבתר מתהדרין אלין וכו':","ולאחר כך, חוזרים אלו הממונים המענישים בני אדם, ונפרעים מן האדם על מה שנמצא בשבילו חסרון למעלה ולמטה, מחמת שלא נתענג בשבת. מהו התקנה שלו. הוא שישב תענית על תעניתו שבשבת. מהו הטעם. הוא, כי זה ביטל עונג שבת, יבטל משום זה עונג חול."],[2,"ואי איהו מבטל וכו':","ואם הוא מבטל עונג שבת, ומתענג בחול, הוא דומה כמי שמחשיב דבר אחר יותר ממה שמחשיב להקב\"ה. כי רוח העליון קדש קדשים השורה עליו לא העניגו, וביטל אותו ממנו, ורוח אחר של חול, השורה אח\"כ על העולם, הוא מחשיב ומענג אותו. אז חוזרים ונפרעים ממנו בעולם הזה ובעולם הבא."],[3,"בגין כך, אצטריך וכו':","משום זה צריך תענית אחר ביום ראשון מימות החול, בשעה ששורה על העולם, הרוח של חול, ובזה יש לו רפואה, כיון שלא החשיב את הרוח של חול, יותר משל שבת, וסימנך והשיב את הגזלה אשר גזל וגו'. גזלן אינו מתחשב עם הקב\"ה ואינו מתחשב עם בני אדם, ע\"כ אין עונשו גדול כגנב. גנב, המחשיב בני אדם יותר מהקב\"ה, יש לו עונש בעולם הזה ובעולם הבא. אשרי הוא, מי שמשלים למטה את עונג העליון ההוא כראוי."],[4,"יומא דא מתעטרא וכו':","יום הזה מתעטר בע' עטרות, כי הוא יום השביעי, שנשלמו ונתעטרו בו, חג\"ת נהי\"מ שכל אחד כולל עשרה, והם ע' עטרות. ושם העליון הקדוש, שהוא בינה, נשלם מכל הצדדים, דהיינו מג' קוין שה\"ס האבות, (כנ\"ל אות קפ\"א) והאירו כל המדרגות, וכולן בשמחת הברכות, ובקדושה על קדושה, ותוספת קדושה. הברכות נמשכות מבינה, והקדושות מחכמה."],[5,"קדושה דמעלי שבתא וכו':","הקדושה של כניסת השבת, שהיא המלכות, זו היא הקדושה של שבת בראשית שה\"ס בינה, (כנ\"ל אות קפ\"ב) שה\"ס ל\"ב אלקים דמעשה בראשית, שנתקדשו מל\"ב שבילין שבחכמה, וכן נתקדשה המלכות מל\"ב שבילי החכמה, וג' מדרגות של תפוחים הקדושים, שה\"ס ג' קוין, שבהם ג' גווני התפוח, לבן אדום ירוק, הממשיכים חכמה, שה\"ס קדושה. וע\"כ נקראים תפוחים קדושים. ומלכות המקבלתם נקראת חקל תפוחין קדישין. וצריכים להזכיר על קדושה זו, הכלל של מעשה בראשית, והמנוחה שביום השביעי, בסוד ל\"ב שבילי החכמה וג' מדרגות התפוחים הנכללים בהם, שה\"ס העדות שבמעשה בראשית דהיינו ויכלו השמים והארץ וכל צבאם וגו'. ויכל אלקים וגו', שיש בעדות הזו ל\"ה תבות, כנגד ל\"ב שבילים, ושלש מדרגות דתפוחים הקדושים."],[6,"תלת דרגין דאינון וכו':","ג' מדרגות שהן, \u0003שביעי, שביעי, שביעי,\u0004 שיש בויכלו השמים, יש בהם סוד עולם העליון, שהוא בינה, הנקראת שביעי ממטה למעלה כשמתחילים למנות מן יסוד. וסוד עולם התחתון, שהוא מלכות הנקראת שביעי, כשמתחילים מחסד. וסוד של כל האמונה, שהיא עטרת יסוד דז\"א, שהיא בחינת מלכות דז\"א הנקראת שביעי. \u0003ג' פעמים אלקים,\u0004 שיש בויכלו השמים, אחד, הוא עולם התחתון, שהוא מלכות הנקראת אלקים. ואחד, פחד יצחק, שהוא גבורה דז\"א הנקרא אלקים. ואחד עולם העליון הקדוש, קודש קדשים, שהיא בינה הנקראת אלקים. וצריך האדם להעיד עדות זו, בשמחה ברצון הלב, להעיד לפני אדון האמונה. וכל מי שמעיד זה ומשים לבו ורצונו לזה, מכפר זה על כל עונותיו."],[7,"בא\"י אמ\"ה אק\"ב וכו':","ברוך אתה ה' אלקינו מלך העולם אשר קדשנו במצותיו ורצה בנו, וכו'. קידוש זה, הוא במשקל אחד כנגד עדות האמונה, דהיינו ויכלו השמים, והם ל\"ה תיבות אחרות כמו שיש בויכלו הכל ביחד עולה ע' תבות, לעטר בהם את השבת של כניסת השבת, שהיא המלכות. אשרי חלקו של אדם המכוון רצונו לדברים אלו לכבוד רבונו."],[8,"קידושא דיומא הא","וכו': קידוש של יום, הרי העמידוהו, שהוא, בורא פרי הגפן, ולא יותר. כי היום, שהוא ז\"א, עומד לקדש את המלכות, שה\"ס כוס של קידוש. כי ביום עולים זו\"ן עד או\"א, שה\"ס קדש, מתקדשים על ידיהם. מה שאין כן בלילה, שאנו צריכים לקדש את המלכות באלו הדברים כמו שהעמדנו, דהיינו ע' תיבות (כנ\"ל אות רנ\"ג) והלילה הזה, שהיא המלכות, אינה מתקדשת, אלא ע\"י עם הקדוש למטה, בשעה ששורה עליהם רוח העליון, שהוא תוספת נשמה, ואנו צריכים לקדש אותה ברצון הלב ולכוון הדעת לכך. כי בלילה עוד לא עלו אלא עד ישסו\"ת. וצריכים להמשיך הקדושה."],[9,"ויומא איהו קא","וכו': והיום שבת, שה\"ס ז\"א שעלה לאו\"א עלאין ונעשה קדש כמהם, הוא מקדש את המלכות, שנקראת כוס. ולא אנו. וישראל מקדשי בצלותין ובעותין, שע\"י התפלות שחרית ומוסף וחזרת הש\"ץ, אנו מעלים את זו\"ן עד או\"א. ואין צריכים עתה בקידוש לקדשם יותר, אלא שמתקדשים בקדושת ז\"א שבאו\"א, ביום הזה. אשריהם ישראל, עם קדוש, שירשו יום הזה ירושת עולם."],[10,"לבתר דנפיק שבתא וכו':","אחר שיצא השבת, צריך האדם להבדיל בין קדש לחול. למה. הוא משום שניתנה רשות להממונים שלמטה לשלוט על העולם, ובכל מעשה העולם, וצריכים להראות היחוד במקום קדוש בקדושה העליונה, שהוא השבת, ולהבדיל את התחתונים מיחוד העליון, ולברך על מאור האש."]],[[0,"","לְמֶלֶךָ שֶׁשָּׂמַח בַּהִלּוּלָא שֶׁלּוֹ, וְכָל בְּנֵי הָאָדָם שְׂמֵחִים עִמּוֹ. רָאָה אִישׁ אֶחָד נָתוּן בְּקוֹלָר, צִוָּה עָלָיו וְהִתִּירוּהוּ, כְּדֵי שֶׁכֻּלָּם יִמָּצְאוּ בְשִׂמְחָה."],[1,"","וְאַחַר כָּךְ חוֹזְרִים הַמְמֻנִּים הַלָּלוּ שֶׁמַּעֲנִישִׁים בְּנֵי אָדָם, וְנִפְרָעִים מִן הָאָדָם עַל שֶׁנִּמְצָא בִּגְלָלוֹ חִסָּרוֹן לְמַעְלָה וּמַטָּה. מַה תַּקָּנָתוֹ? לֵישֵׁב תַּעֲנִית עַל תַּעֲנִית. מָה הַטַּעַם? זֶה בִּטֵּל עֹנֶג שַׁבָּת - יְבַטֵּל עֹנֶג שֶׁל חֹל."],[2,"","וְאִם הוּא מְבַטֵּל עֹנֶג שַׁבָּת וּמִתְעַנֵּג בַּחֹל, דּוֹמֶה כְּמוֹ שֶׁמַּחֲשִׁיב עַל דָּבָר אַחֵר יוֹתֵר מִמַּה שֶּׁמַּחֲשִׁיב אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא. הָרוּחַ הָעֶלְיוֹנָה, קֹדֶשׁ הַקְּדָשִׁים שֶׁשּׁוֹרָה עָלָיו לֹא עִנֵּג, וּבִטְּלָהּ מִמֶּנּוּ. רוּחַ אַחֶרֶת שֶׁל חֹל שֶׁשּׁוֹרָה אַחַר כָּךְ עַל הָעוֹלָם מַחֲשִׁיב וּמְעַנֵּג אוֹתוֹ, אָז חוֹזְרִים וְנִפְרָעִים מִמֶּנּוּ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא."],[3,"","מִשּׁוּם כָּךְ צָרִיךְ תַּעֲנִית אַחֶרֶת בְּיוֹם רִאשׁוֹן שֶׁל חֹל, בִּזְמַן שֶׁשּׁוֹרָה עַל הָעוֹלָם אוֹתָהּ רוּחַ שֶׁל חֹל, וּבָזֶה יֵשׁ לוֹ רְפוּאָה, כֵּיוָן שֶׁלֹּא הֶחֱשִׁיב אֶת רוּחַ הַחֹל. וְסִימָנְךְ - (ויקרא ה) וְהֵשִׁיב אֶת הַגְּזֵלָה אֲשֶׁר גָּזָל וְגוֹ'. גַּזְלָן אֵינוֹ מַחֲשִׁיב אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, אֵינוֹ מַחֲשִׁיב בְּנֵי אָדָם, לָכֵן אֵין לֹא עֹנֶשׁ כְּגַנָּב. גַּנָּב שֶׁמַּחֲשִׁיב בְּנֵי אָדָם יוֹתֵר מֵהַקָּדוֹשׁ בָּרוּךְ הוּא, יאשׁ לוֹ עֹנֶשׁ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. אַשְׁרֵי מִי שֶׁמַּשְׁלִים לְמַטָּה אֶת אוֹתוֹ עֹנֶג עֶלְיוֹן כָּרָאוּי."],[4,"","הַיּוֹם הַזֶּה מִתְעַטֵּר בְּשִׁבְעִים עֲטָרוֹת, וְהַשֵּׁם הָעֶלְיוֹן הַקָּדוֹשׁ נִשְׁתַּלֵּם בְּכָל הַצְּדָדִים, וְכָל הַדְּרָגוֹת מוּאָרוֹת, וְהַכֹּל בְּשִׂמְחַת הַבְּרָכוֹת וּבִקְדֻשָּׁה עַל קְדֻשָּׁה וְתוֹסֶפֶת שֶׁל קְדֻשָּׁה."],[5,"","קְדֻשָּׁה שֶׁל עֶרֶב שַׁבָּת זוֹהִי קְדֻשָּׁה שֶׁל שַׁבַּת בְּרֵאשִׁית. שֶׁהֲרֵי מִתְקַדֵּשׁ מִשְּׁלֹשִׁים וּשְׁנַיִם שְׁבִילִים, וְשָׁלֹשׁ דְּרָגוֹת שֶׁל תַּפּוּחִים הַקְּדוֹשִׁים. וּצְרִיכִים לְהַזְכִּיר עַל הַקְּדֻשָּׁה הַזּוֹ אֶת כְּלַל מַעֲשֵׂה בְרֵאשִׁית, וּמְנוּחָה בְּסוֹד שֶׁל שְׁלֹשִׁים וּשְׁנַיִם הַשְּׁבִילִים וּשְׁלֹשׁ הַדְּרָגוֹת שֶׁנִּכְלָלוֹת בָּהֶם, סוֹד הָעֵדוּת שֶׁל מַעֲשֵׂה בְרֵאשִׁית, דְּהַיְנוּ (בראשית ב) וַיְכֻלּוּ הַשָּׁמַיִם וְהָאָרֶץ וְכָל צְבָאָם וְגוֹ'. וַיְכַל אֱלֹהִים, שֶׁיֵּשׁ בָּעֵדוּת הַזּוֹ שְׁלֹשִׁים וְחָמֵשׁ תֵּבוֹת, שְׁלֹשִׁים וּשְׁנַיִם שְׁבִילִים עִם שְׁלֹשׁ הַדְּרָגוֹת שֶׁל הַתַּפּוּחִים הַקְּדוֹשִׁים."],[6,"","שָׁלש דְּרָגוֹת, שֶׁהֵן: שְׁבִיעִי. שְׁבִיעִי. שְׁבִיעִי. וְיֵשׁ בּוֹ סוֹד שֶׁל הָעוֹלָם הָעֶלְיוֹן, וְסוֹד שֶׁל הָעוֹלָם הַתַּחְתּוֹן, וְסוֹד כָּל הָאֱמוּנָה. שָׁלֹשׁ פְּעָמִים אֱלֹהִים: אֶחָד הָעוֹלָם הַתַּחְתּוֹן. אֶחָד פַּחַד יִצְחָק. וְאֶחָד הָעוֹלָם הָעֶלְיוֹן הַקָּדוֹשׁ, קֹדֶשׁ קָדָשִׁים. צָרִיךְ אָדָם לְהָעִיר אֶת הָעֵדוּת הַזּוֹ בְּשִׂמְחָה וּרְצוֹן הַלֵּב, לְהָעִיד לִפְנֵי בַעְלָהּ שֶׁל הָאֱמוּנָה. וְכָל מִי שֶׁמֵּעִיד אֶת זֶה וְיָשִׂים לִבּוֹ וּרְצוֹנוֹ לָזֶה, מְכַפֵּר עַל כָּל חֲטָאָיו."],[7,"","בָּרוּךְ אַתָּה ה' אֱלֹקֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר קִדְּשָׁנוּ בְמִצְותָיו וְרָצָה בָנוּ וְכוּ', קִדּוּשׁ זֶה הוּא בְּמִשְׁקָל אֶחָד כְּנֶגֶד עֵדוּת הָאֱמוּנָה, וְהֵם שְׁלֹשִׁים וְחָמֵשׁ תֵּבוֹת אֲחֵרוֹת, כְּמוֹ שֶׁיֵּשׁ בְּוַיְכֻלּוֹ. הַכֹּל עוֹלֶה לְשִׁבְעִים תֵּבוֹת לְהִתְעַטֵּר בָּהֶם שַׁבָּת שֶׁל עֶרֶב שַׁבָּת. אַשְׁרֵי חֶלְקוֹ שֶׁל אָדָם שֶׁיְּכַוֵּן רְצוֹנוֹ לַדְּבָרִים הַלָּלוּ לִכְבוֹד רִבּוֹנוֹ."],[8,"","קִדּוּשׁ הַיּוֹם, הֲרֵי פֵּרְשׁוּהוּ בּוֹרֵא פְּרִי הַגֶּפֶן, וְלֹא יוֹתֵר. שֶׁהֲרֵי הַיּוֹם עוֹמֵד לְקַדֵּשׁ אוֹתוֹ. מַה שֶּׁאֵין כֵּן בַּלַּיְלָה, שֶׁאָנוּ צְרִיכִים לְקַדֵּשׁ אוֹתוֹ בַּדְּבָרִים הַלָּלוּ, כְּמוֹ שֶׁבֵּאַרְנוּ. וְלֹא מִתְקַדֵּשׁ הַלַּיְלָה הַזֶּה, אֶלָּא רַק בָּעָם הַקָּדוֹשׁ לְמַטָּה, כְּשֶׁשּׁוֹרָה עֲלֵיהֶם אוֹתָהּ רוּחַ עֶלְיוֹנָה. וְאָנוּ צְרִיכִים לְקַדְּשׁוֹ בִּרְצוֹן הַלֵּב, וּלְכַוֵּן הַדַּעַת לָזֶה."],[9,"","וְהַיּוֹם מְקַדֵּשׁ אוֹתוֹ, וְיִשְׂרָאֵל מְקַדְּשִׁים בִּתְפִלּוֹת וּבַקָּשׁוֹת וּמִתְקַדְּשִׁים בִּקְדֻשָּׁתוֹ בַּיּוֹם הַזֶּה. אַשְׁרֵי יִשְׂרָאֵל הָעָם הַקָּדוֹשׁ שֶׁיָּרְשׁוּ יוֹם הַזֶּה נַחֲלַת יְרֻשָּׁה לְעוֹלָמִים."],[10,"","אַחַר שֶׁיּוֹצֵאת שַׁבָּת, צָרִיךְ אָדָם לְהַבְדִּיל בֵּין קֹדֶשׁ לְחֹל. לָמָּה? שֶׁהֲרֵי נִתְּנָה רְשׁוּת לַמְמֻנִּים שֶׁלְּמַטָּה לִשְׁלֹט עַל הָעוֹלָם, וּבְכָל מַעֲשֵׂי הָעוֹלָם לְהַרְאוֹת יִחוּד בְּמָקוֹם קָדוֹשׁ, בִּקְדֻשָּׁה עֶלְיוֹנָה, וּלְהַפְרִיד לְמַטָּה מִיִּחוּד הָעֶלְיוֹן, וּלְבָרֵךְ עַל מְאוֹרֵי הָאֵשׁ."]]],[["בְּגִין דְּכָל אֶשִּׁין אַחֲרָנִין, אִתְטְמָרוּ וְאִתְגְּנִיזוּ בְּיוֹמָא דְּשַׁבְּתָא, בַּר אֶשָּׁא חַד דִּקְדוּשָּׁה עִלָּאָה, דְּאִתְגַּלְיָא וְאִתְכְּלִילָא בִּקְדוּשָׁא דְּשַׁבְּתָא. וְכַד הַאי אֶשָּׁא אִתְגַּלְיָיא, כָּל אֶשִּׁין אַחֲרָנִין אִתְטְמָרוּ, וְאִתְגְּנִיזוּ קַמֵּיהּ. וְהַאי אֶשָּׁא, אִיהִי דַּעֲקֵידָה דְּיִצְחָק, דְּאִתְלָהֲטָא עַל גַּבֵּי מַדְבְּחָא. בְּגִין כַּךְ, בָּעֵי לְבָרְכָא עַל נְהוֹרָא דְּאֶשָּׁא. וְהַאי אֶשָּׁא, לָא בָּעֵי אֶשָּׁא דְּחוֹל, אֶלָּא אֶשָּׁא דְּשַׁבָּת, וְהַאי אֶשָּׁא, אִיהוּ אֶשָּׁא דְּנָפִיק מֵהַהוּא אֶשָּׂא דִּלְעֵילָּא.","וְדָא אִיהוּ אֶשָּׁא דְּסָבִיל אֶשָּׁא. וְכֵיוָן דְּהַאי אֶשָּׁא דְּנָפִיק מֵאֶשָּׁא דִּלְעֵילָּא אִתְבָּרְכָא בִּבְרָכָה דִּנְהוֹרָא, כְּדֵין כָּל שְׁאַר אֶשִּׁין אַחֲרָנִין נָפְקִין, וְאִתְמַנָּן בְּדוּכְתַּיְיהוּ, וְאִתְיְיהִיב לוֹן רְשׁוּתָא לְאַנְהָרָא.","בְּהַהִיא שַׁעֲתָא דְּקָא מְבָרְכִין עַל אֶשָּׁא, אִזְדַּמְּנָן אַרְבַּע רְתִיכִין, אַרְבַּע מַשִׁרְיָין לְתַתָּא, לְאַנְהָרָא מֵהַהוּא אֶשָּׁא מְבָרְכָא, וְאִינּוּן אִקְרוּן מְאוֹרֵי הָאֵשׁ. בְּגִין כַּךְ, בָּעֵינָן לְאַכְפְּיָא ד' אֶצְבְּעָאן דִּידָא דִּימִינָא, וּלְאַנְהֲרָא לוֹן מִגּוֹ הַהוּא נְהוֹרָא דִּשְׁרָגָא דְּמִתְבָּרְכָא.","וְאִינּוּן אֶצְבְּעָאן, רֶמֶז לְאִינּוּן מְאוֹרֵי הָאֵשׁ, דִּנְהִירֵי וְשַׁלְטֵי מֵהַהוּא נְהוֹרָא דִּשְׁרָגָא דְּמִתְבָּרְכָא. וּבְגִין דְּאִינּוּן דַּרְגִּין לְתַתָּא, כַּד אַחְזֵי בַּר נָשׁ אֶצְבְּעָאן קַמֵּי הַהוּא נְהוֹרָא דִּשְׁרָגָא, בָּעֵי לְאַכְפְּיָיא לוֹן קַמֵּיהּ, בְּגִין דְּהַהוּא נְהוֹרָא שַׁלְטָא עָלַיְיהוּ, וְאִינּוּן נָהֲרִין מִנֵּיהּ.","בִּשְׁאַר בִּרְכָאן בָּעֵינָן לְזַקְפָא לוֹן לְאֶצְבְּעָאן, בְּגִין לְאַחֲזָאָה קְדוּשָּׁה עִלָּאָה, דְּדַרְגִּין עִלָּאִין, דְּשַׁלְטִין עַל כֹּלָּא, דִּשְׁמָא קַדִּישָׁא אִתְעֲטָּר בְּהוּ וְאִתְקַדָּשׁ בְּהוּ, וְאִתְבָּרְכָן כֻּלְּהוּ דַּרְגִּין כַּחֲדָא, וְנָהֲרִין מִגּוֹ בּוּצִינָא עִלָּאָה דְּכֹלָּא, וּבְּגִין כָּךְ בָּעֵינָן לְזַקְפָא לוֹן לְעֵילָּא. וְהָכָא בָּעֵינָן לְאַכְפְּיָיא אֶצְבְּעָאן קָמֵי שַׁרְגָּא, בְּגִין לְאַחֲזָאָה דַּרְגִּין דִּלְתַתָּא, דְּנָהֲרִין מִגּוֹ בּוּצִינָא דִּלְעֵילָּא, וּמֵהָכָא שַׁלְטִין וְנָהֲרִין מִנָּהּ, וְאִינּוּן מְאוֹרֵי הָאֵשׁ.","בְכָל יוֹמָא אֲנָן מְבָרְכֵינָן מְאוֹרֵי אוֹר, דְּאִינּוּן נְהוֹרִין עִלָּאִין, דְּקַיְימָן בְּהַהוּא אוֹר קַדְמָאָה, וְאִתְבָּרְכָן כֻּלְּהוּ דַּרְגִּין, וְנָהֲרִין כֻּלְּהוּ כַּחֲדָא, מִגּוֹ בּוּצִינָא עִלָּאָה. וְהָנִי אִקְרוּן מְאוֹרֵי הָאֵשׁ. וּבְגִינֵי רָזָא דָּא, מְבָרְכִין בּוֹרֵא מְאוֹרֵי הָאֵשׁ.","וְאִי תֵּימָא, אֲמַאי בּוֹרֵא, וְלָא אָמְרוּ מֵאִיר מְאוֹרֵי הָאֵשׁ. הוֹאִיל וְקָא נַהֲרִין מֵהַהוּא אֵשׁ, מֵהַהוּא בּוּצִינָא מְבָרְכָא. אֶלָּא כֵּיוָן דְּעָאל שַׁבְּתָא, כָּל אִינּוּן דַּרְגִּין דִּלְתַתָּא, וְכָל אִינּוּן דְּנָהֲרִין וְשַׁלְטִין, כֻּלְּהוּ עָאלִין וְאִתְכְּלִילוּ בְּהַאי שַׁרְגָּא, וְאִתְטָמָרוּ וְאִתְגְּנִיזוּ, וְאִתְנְּטָרוּ בֵּיהּ, וְלָא יִתְחֲזוּן בֵּיהּ, אֶלָּא הַהוּא נְקוּדָה בִּלְחוֹדָהָא, וְכֻלְּהוּ אִתְטְמָרוּ בְּגַוָּוה, כָּל יוֹמָא דְּשַׁבְּתָא.","כֵּיוָן דְּנָפַק שַׁבְּתָא, אַפִּיק לוֹן לְכָל חַד וְחַד, כְּאִילּוּ הַהִיא שַׁעֲתָא אִתְבְּרִיאוּ, וְנַפְקוּ כֻּלְּהוּ וְאִתְבְּרִיאוּ כְּמִלְקַדְּמִין, וְאִתְמְנִיאוּ עַל דּוּכְתַּיְיהוּ לְשַׁלְּטָאָה כְּדֵין אִתְבָּרְכָא הַאי שַׁרְגָּא, וְאִתְכַּפְיָין קַמֵּיהּ, לְאַנְהָרָא. כֵּיוָן דְּנָהֲרִין, כְּדֵין אִתְמְנּוּן כָּל חַד וְחַד עַל דּוּכְתֵּיהּ.","כְּגַוְונָא דָּא, אִינּוּן דַּרְגִּין עִלָּאִין, דְּאִקְרוּן מְאוֹרֵי אוֹר, שַׁלְטִין בִּימָמָא, וְנָהֲרִין מִגּוֹ בּוּצִינָא עִלָּאָה. בְּשַׁעֲתָא דְּרָמַשׁ לֵילְיָא, הַהוּא בּוּצִינָא עִלָּאָה כָּנִישׁ לוֹן, וְאָעִיל לוֹן בְּגַוֵּיהּ, עַד דְּנָהִיר יְמָמָא. כֵּיוָן דִּמְבָרְכִין יִשְׂרָאֵל עַל נְהוֹרָא בִּימָמָא, כְּדֵין אַפִּיק לוֹן בִּשְׁלִימוּ דִּנְהוֹרָא. וְעַל דָּא מְבָרְכִין יוֹצֵר הַמְּאוֹרוֹת, וְלָא אַמְרֵי בּוֹרֵא, (ס\"א אלא יוצר) (קנ\"א ע\"א) וְהָכָא בּוֹרֵא מְאוֹרֵי הָאֵשׁ. בְּגִין דְּאִינּוּן דַּרְגִּין לְתַתָּא.","וְכֹלָּא אִיהוּ רָזָא דְּאֶצְבְּעָאן, בְּהוּ רָמִיז דַּרְגִּין עִלָּאִין, וְדַרְגִּין תַּתָּאִין. (קצ\"ב ע\"ב, תיקון י\"ח, ס\"ז ע\"א) דַּרְגִּין עִלָּאִין אִשְׁתְּמוֹדְעַאן, בִּזְקִיפוּ דְּאֶצְבְּעָאן לְעֵילָּא. וּבִזְקִיפוּ דְּאֶצְבְּעָאן, אִתְבָּרְכָן דַּרְגִּין עִלָּאִין, וְדַרְגִּין תַּתָּאִין כַּחֲדָא. וּבִמְאִיכוּ דְּאֶצְבְּעָאן, אִתְבָּרְכָן לְאַנְהָרָא דַּרְגִּין תַּתָּאִין לְחוֹדַיְיהוּ.","וְרָזָא דָּא, טוּפְרֵי דַּאֲחוֹרֵי אֶצְבְּעָאן. וְאֶצְבְּעָאן לְחוֹדַיְיהוּ לְגוֹ. טוּפְרֵי דַּאֲחוֹרֵי אֶצְבְּעָאן, אִינּוּן אַנְפִּין אַחֲרָנִין, דְּאִצְטְרִיכוּ לְאַנְהָרָא מִגּוֹ הַהוּא שְׁרָגָא, וְאִינּוּן אַנְפִּין דְּאִקְרוּן אֲחוֹרַיִים. אֶצְבְּעָאן לְגוֹ בְּלָא טוּפְרִין, אִלֵּין אִינּוּן אַנְפִּין פְּנִימָאִן אִתְכַּסְיָין. וְרָזָא דָּא, (שמות ל״ג:כ״ג) וְרָאִיתָ אֶת אֲחוֹרָי. אִלֵּין אֲחוֹרֵי, (בראשית ר\"א ע\"א) אֶצְבְּעָאן, לַאֲחוֹרָא בְּטוּפְרֵיהוֹן. וּפָנַי לֹא יֵרָאוּ, אִלֵּין אֶצְבְּעָאן לְגוֹ, בְּלָא טוּפְרִין, דְּאִינּוּן אַנְפִּין פְּנִימָאִין."],[[0,"בגין דכל אשין וכו':","משום שכל אש אחרת נסתרת ונגנזת ביום השבת חוץ מאש אחת שבקדושה עליונה שנתגלה, שהיא ממסך דחירק שבקו אמצעי דבינה שחזרה לחכמה, ונכללת בקדושת השבת, שהיא המלכות המלבשת את הבינה. וכשאש הזאת מתגלה, כל אשים אחרות נסתרות ונגנזות לפניו. ואש ההיא היא של עקדת יצחק, דהיינו של קו אמצעי העוקד וקושר את קו השמאל שנקרא יצחק, שלא יאיר אלא ממטה למעלה, כדי שיכלול בימין. שהיא מתלהט על המזבח ביום השבת. כלומר שאש המזבח הבוער גם בשבת הוא נמשך מאש הזה דקו האמצעי, למלכות הנקראת מזבח. ומשום זה צריך לברך על מאור האש, במוצאי שבת. ואש הזו אין הכוונה על אש של חול אלא על אש של שבת, שאש הזאת היא אש היוצאת מאש של מעלה, שנמשך מקו אמצעי אל המזבח, שהיא המלכות. כנ\"ל."],[1,"ודא איהו אשא וכו':","וזו היא אש הסובלת אש, שהיא האש שבמלכות, וכיון שאש זה היוצא מאש של מעלה, מקו האמצעי, מתברך בברכת האור, אז כל שאר אשים האחרות יוצאות ונתמנות במקומן, דהיינו שניתנה להם רשות להאיר."],[1,"","פירוש. הדינים מכונים אש, כי הם משולים לאש, מה אש הגשמי, בעת שהיא מתוקנת כראוי, אין לך דבר טוב בעולם יותר ממנה לקיום כל המציאות, ואם אינה מתוקנת כראוי, אין לך משחית ומכלה את המציאות גדול ממנה. כך הדינים העליונים, בעת שהם מתוקנים כראוי, כל שלמות קיום מציאות הרוחני תלויה בהם. כגון, הדינים המתוקנים בקו האמצעי, שבהם כופה את קו השמאל להתחבר עם קו הימין. נמצא גורם בזה להארת החכמה, (כנ\"ל לך י\"ג ד\"ה ונתבאר) אשר אינה מאירה כלל בלי חסדים שבימין. והארת החכמה היא מקור כל המוחין דגדלות שבפרצופין העליונים, כנודע. הרי שכל השלימות תלויה בדינים ההם המתוקנים. ואם אינם מתוקנים, כל העונשים וכל הסתלקות האורות מעליונים באים מהם, (כנ\"ל ויצא דף י\"ג ד\"ה סתרא) ובזה תבין סוד הברכה \u0003בורא מאורי האש\u0004 שאנו מברכים במוצאי שבת, שהוא על אש המתוקן הזה שבמלכות, \u0003דנפיק מאשא דלעילא,\u0004 דהיינו מקו האמצעי, ואז נעשה תקון בזה לכל האשים היוצאות ממלכות שיכלו להאיר, כגון ארבע מלאכי המרכבה דמלכות, שהם מיכאל גבריאל אוריאל רפאל, שהם מאירים, שאז הארת החכמה שבמלכות הרוכבת עליהם, מתגלה. כמ\"ש לפנינו."],[2,"בההיא שעתא דקא וכו':","באותה שעה שאנו מברכים על האש, מזדמנים ארבע מרכבות, ארבע מחנות למטה, שהם, מיכאל גבריאל אוריאל רפאל, שכל אחד מהם ממונה על מחנה מלאכים. ומאירים מאש ההיא שבמלכות שנתברכה, והם נקראים מאורי האש. משום שהארתם נמשכת מאש של המלכות שנתברכה, משום זה צריכים לכוף ד' אצבעות של יד ימין ולהאיר אותם מתוך אור הנר שנתברך. פירוש. כי זה רומז, אשר אש הזאת המתברכת, הנמשכת מאש של מעלה שהיא קו האמצעי, גורמת למיעוט הנ\"ר שבהארת החכמה שבשמאל, (כנ\"ל לך דף י\"ג ד\"ה ונתבאר) \u0003וכפיפת אצבעות,\u0004 רומזת למיעוט הג\"ר. כמ\"ש עוד לפנינו."],[3,"ואינון אצבעאן רמז וכו':","ואלו אצבעות רומזים לאלו מאורי האש, דהיינו לארבע מרכבות הנ\"ל. שמאירים ושולטים מתוך אור הנר ההיא שנתברכה, ומשום שהן מדרגות שלמטה, לכן, כשהאדם מראה אצבעותיו לפני אור הנר ההוא, צריך לכוף אותן לפניו, משום שאור הזה שולט עליהן והן מאירות ממנו."],[3,"","פירוש. הארת החכמה שבמלכות מכונה, מאור האש. והוא מטעם, כי אין הארת חכמה יוצאת אלא מקו שמאל (כנ\"ל ב\"א דף נ\"ז ד\"ה והנה) ואין קו שמאל יכול להאיר אלא ע\"י הכרעת קו האמצעי במסך דחירק שלו, שה\"ס אש, (כנ\"ל לך דף י\"ג ד\"ה ונתבאר) הרי שהארת החכמה אינה מאירה זולת על ידי האש דקו האמצעי, וע\"כ מכונה חכמה זו בשם, \u0003מאור האש.\u0004 ונודע שאין החכמה מאירה אלא במלכות ע\"כ מכונה המלכות מאור האש, או אור הנר."],[3,"","וסוד ד' מלאכים מיכאל גבריאל אוריאל רפאל, ה\"ס ג' קוין נה\"י ומלכות המקבלתם בעת שהם עולים ומלבישים נהי\"מ של המלכות ואז מתגלה עליהם המלכות בהארת חכמה שלה, כמו המלך המתגלה להעם במרכבה שלו. ולפיכך הם נקראים מרכבה של המלכות. וד' אצבעותיו של אדם מצד אחוריהן, שבמקום הצפרנים רומזות לאלו ד' מלאכים מרכבת המלכות שעליהם מתגלה הארת החכמה שבמלכות. וז\"ש, \u0003ואינון אצבעאן רמז לאינון מאורי האש,\u0004 דהיינו ד' מלאכים הנ\"ל, שעליהם מתגלה הארת החכמה שבמלכות, בסו\"ה, \u0003וראית את אחורי\u0004 (כמ\"ש להלן באות רס\"ח) וז\"ש, \u0003בעי לאכפייא לון קמיה,\u0004 הרומז על מיעוט הג\"ר שבהארת החכמה המתגלה על האצבעות, כי להיות המלכות בבחינת מאור האש, זה גורם להם כפיפה, שפירושו מיעוט הג\"ר. וז\"ש, \u0003בגין דההוא נהורא שלטא עלייהו,\u0004 דהיינו מאור האש, שה\"ס חכמה שבמלכות המכונה כן, משום שאינה מאירה זולתו, כנ\"ל. וא\"כ היא מוכרחת להאיר כהכרעת קו האמצעי (כנ\"ל ב\"א דף ס' ד\"ה מחלוקת ע\"ש) רק בו\"ק דג\"ר, דהיינו רק ממטה למעלה, בסוד כפיפת אצבעות ולא ממעלה למטה שה\"ס ג\"ר דג\"ר. שה\"ס זקיפת האצבעות. כמ\"ש לפנינו."],[4,"בשאר ברכאן בעינן וכו':","בשאר הברכות, כגון בברכת כהנים, צריכים לזקוף האצבעות. כדי להראות קדושה עליונה של מדרגות העליונות השולטות על הכל, שה\"ס המדרגות דימין דז\"א הממשיכות קדושתן מאו\"א עלאין שה\"ס קדש. שהשם הקדוש, שהוא המלכות, נתעטר בהן ונתקדש בהן, ונתברכו כל המדרגות יחד ומאירים מתוך המאור העליון על כל, שהוא ג\"ר דבינה שורש כל החסדים, ומשום זה צריכים לזקוף האצבעות למעלה. וכאן צריכים לכוף האצבעות לפני הנר, כדי להראות המדרגות של מטה שהן ד' המרכבות הנ\"ל, המאירים מתוך המאור שלמעלה, שהיא המלכות, שמכאן שולטים ומאירים ממנה, והם מאורי האש."],[4,"","פירוש. כי ע\"י הכרעת קו האמצעי את ב' הקוין ימין ושמאל, מתתקנים אורותיהם, שהאור דקו ימין, שהוא חסדים, יאיר ממעלה למטה בבחינה ג\"ר ממש. והאור דקו שמאל, שהוא הארת חכמה, לא יאיר אלא ממטה למעלה, שהוא בחינת ו\"ק דחכמה. (כנ\"ל בראשית א' דף ס' ד\"ה מחלוקת) והארת החכמה אינה מאירה אלא במלכות (כנ\"ל ב\"א דף רע\"ו ד\"ה ועוד) בעת שהיא רוכבת בד' מרכבות שלה, שהם מיכאל גבריאל אוריאל רפאל. ונמצא שהאורות שלמעלה ממלכות, שהם אור החסדים ובחינת קו ימין, הם מאירים מלמעלה למטה, שז\"ס \u0003זקיפת האצבעות.\u0004 וז\"ש, \u0003בשאר ברכאן בעינן לזקפא לון לאצבעאן.\u0004 משא\"כ באור המלכות, שהוא הארת החכמה, וקו שמאל, המתוקנת להאיר רק ממטה למעלה, צריכים \u0003לכוף האצבעות\u0004, המורה על הרכנת הג\"ר ומיעוטם. וז\"ש \u0003והכא בעינן לאכפיא אצבען\u0004 וכו' דנהרין מגו בוצינא דלעילא. שהוא המלכות. שהארתה רק ו\"ק דחכמה."],[5,"בכל יומא אנן וכו':","בכל יום אנו מברכים, מאורי אור. דהיינו יוצר אור יוצר המאורות, שהם אורות עליונים שעומדים באור הראשון ההוא, שהוא חסד. ומתברכים כל המדרגות ומאירים כולם יחד ממאור העליון, שהוא בינה. אבל אלו שבכאן, נקראים מאורי האש. ומשום סוד הזה אנו מברכים, בורא מאורי האש."],[6,"ואי תימא אמאי וכו':","ואם תאמר, למה \u0003בורא\u0004 מאורי האש ולא אמרו מאיר מאורי האש. ומשיב, שהואיל והם מאירים מאש ההוא של המאור המבורכת, שהוא האש הנמשכת לה מקו האמצעי. (כנ\"ל אות רנ\"ז ע\"ש) אלא כיון שנכנס השבת, אז כל המדרגות שלמטה, שהם ד' מרכבות הנ\"ל, וכל אלו המאירים ושולטים מהארת האש הזאת, כולם נכנסים ונכללים בנר ההוא שהוא המלכות, ונסתרים ונגנזים ונשמרים בה, ואינם נראים בה אלא נקודה ההיא לבדה, שהיא המלכות, וכולם נסתרים בה בכל יום השבת."],[6,"","פירוש. ביום השבת המלכות הוא עם ז\"א בזווג פנים בפנים, ואין ניכר בה בחינת שמאל כלל ולא עוד אלא כל המדרגות שנמשכות מבחינת הארת החכמה שלה הנקראת מאורי האש כולן נכללות ונבלעות בח ואינן נראות. באפן שלא נשאר במלכות מבחינתה עצמה, רק עצם הנקודה שבה. וז\"ש, \u0003ולא יתחזון ביה אלא ההיא נקודה בלחודהא,\u0004 ועי' כל זה לעיל (בראשית א' אות קכ\"ח) שנתבאר זה באורך."],[7,"כיון דנפק שבתא וכו':","כיון שיוצא השבת, המלכות מוציאה אותם מאורי האש, לכל אחד אחד, כאלו נבראו בשעה ההיא. ויוצאים כולם ונבראו כבתחילה, ונתמנו על מקומותיהם לשלוט. אז מתברכת נר ההוא (כנ\"ל אות רנ\"ט) והם מתכופפים לפניה, להאיר. דהיינו בסוד כפיפת האצבעות (כנ\"ל אות רס\"ב) כיון שמאירים אז מתמנים כל אחד ואחד על מקומו."],[8,"כגוונא דא אינון וכו':","כעין זה, אלו מדרגות העליונות הנקראות מאורי אור, שולטים ביום, ומאירים ממאור העליון, שהוא בינה, ובשעה שהחשיך הלילה, מאור העליון ההוא מאסף אותם ומכניסם בתוכו, עד שמאיר היום. כיון שמברכים ישראל על האור ביום, אז מוציא אותם בשלימות הארתם. ועכ\"ז מברכים יוצר המאורות, ולא אומרים, בורא, אע\"פ שמתחדשים בכל בקר, וכאן במוצאי שבת, אומרים בורא ומשיב הוא משום שהן מדרגות של מטה. פירוש. שיש כאן טעם ב' על מה שאומרים בורא במוצאי שבת, שהוא משום שמאורי האש הם מדרגות שלמטה, דהיינו של אחורים, כמ\"ש לפנינו, ובאורות דאחורים יתכן לשון בורא, כמו בורא חשך."],[9,"וכלא איהו רזא וכו':","והכל הוא סוד האצבעות, בהם נרמז מדרגות עליונות, דמאורי אור, ומדרגות תחתונות, דמאורי אש. מדרגות העליונות נודעות בזקיפת האצבעות למעלה, הרומז על הארת ג\"ר שהיא ממעלה למטה, (כנ\"ל אות רס\"ב בהסולם) ובזקיפת האצבעות מתברכות מדרגות עליונות ומדרגות תחתונות יחד. ובהשפלת האצבעות, הרומז על ו\"ק שאינו מאיר אלא ממטה למעלה (כנ\"ל אות רס\"ב) מתברכות להאיר רק מדרגות תחתונות לבד, דהיינו המלכות והמרכבות הנמשכות ממנה. כי אין הארת החכמה נגלית רק במלכות. (כנ\"ל ב\"א דף רע\"ו ד\"ה ועוד כמה)."],[10,"ורזא דא טופרי וכו':","וזה סוד הצפרנים שבאחורי האצבעות, שה\"ס מאורי האש, והאצבעות בעצמם בפנים היד, שה\"ס מאורי אור. ומפרש הצפרנים שבאחורי האצבעות הן פנים אחרים, הצריכים להאיר מתוך הנר, שהיא המלכות, והפנים האלו הם הנקראים \u0003אחורים.\u0004 האצבעות שבפנים היד, שהם בלי צפרנים, אלו הן פנים פנימים המתכסים, שאין בהם בחינת ראיה שהיא חכמה. וז\"ס, \u0003וראית את אחורי\u0004, שאלו \u0003אחורי,\u0004 פירושו, אחורי האצבעות בצפרניהן. \u0003ופני לא יראו,\u0004 אלו הם האצבעות בפנימית היד שהן בלי צפרנים, שהם פנים פנימים."]],[[0,"","מִשּׁוּם שֶׁכָּל הָאִשִּׁים הָאֲחֵרִים נִטְמְנוּ וְנִגְנְזוּ בְּיוֹם הַשַּׁבָּת, פְּרָט לְאֵשׁ אַחַת שֶׁל קְדֻשָּׁה עֶלְיוֹנָה שֶׁנִּגְלְתָה וְנִכְלְלָה בִּקְדֻשַּׁת הַשַּׁבָּת. וּכְשֶׁהָאֵשׁ הַזּוֹ מִתְגַּלָּה, כָּל יֶתֶר הָאִשּׁוֹת נִטְמָנוֹת וְנִגְנָזוֹת לְפָנֶיהָ. וְהָאֵשׁ הַזּוֹ הִיא שֶׁל עֲקֵדַת יִצְחָק, שֶׁלּוֹהֶטֶת עַל גַּבֵּי הַמִּזְבֵּחַ. מִשּׁוּם כָּךְ צָרִיךְ לְבָרֵךְ עַל מְאוֹרֵי הָאֵשׁ. וְהָאֵשׁ הַזּוֹ לֹא צְרִיכָה אֵשׁ שֶׁל חֹל, אֶלָּא אֵשׁ שֶׁל שַׁבָּת, וְהָאֵשׁ הַזּוֹ הִיא אֵשׁ שֶׁיּוֹצֵאת מֵאוֹתָהּ הָאֵשׁ שֶׁלְּמַעְלָה."],[1,"","וְזוֹהִי אֵשׁ שֶׁסּוֹבֶלֶת אֵשׁ. וְכֵיוָן שֶׁהָאֵשׁ הַזּוֹ שֶׁיּוֹצֵאת מֵהָאֵשׁ שֶׁלְּמַעְלָה מִתְבָּרֶכֶת בְּבִרְכַּת הָאוֹר, אָז כָּל שְׁאָר הָאִשּׁוֹת הָאֲחֵרוֹת יוֹצְאוֹת וְנִתְמַנּוֹת בִּמְקוֹמָן, וְנִתֶּנֶת לָהֶן רְשׁוּת לְהָאִיר."],[2,"","בְּאוֹתָהּ שָׁעָה שֶׁמְּבָרְכִים עַל הָאֵשׁ, מִזְדַּמְּנוֹת אַרְבַּע מֶרְכָּבוֹת, אַרְבַּע מַחֲנוֹת לְמַטָּה, לְהָאִיר מֵאוֹתָהּ אֵשׁ מְבֹרֶכֶת, וְהֵם נִקְרָאִים מְאוֹרֵי הָאֵשׁ. מִשּׁוּם כָּךְ צָרִיךְ לִכְפֹּף אַרְבַּע אֶצְבָּעוֹת שֶׁל יַד יָמִין, וּלְהָאִיר לָהֶם מִתּוֹךְ אוֹתוֹ אוֹר הַנֵּר שֶׁמִּתְבָּרֵךְ."],[3,"","וְאוֹתָן אֶצְבָּעוֹת רֶמֶז לְאוֹתָם מְאוֹרֵי הָאֵשׁ שֶׁמְּאִירִים וְשׁוֹלְטִים מֵאוֹתוֹ הָאוֹר שֶׁל הַנֵּר שֶׁמִּתְבָּרֵךְ. וּמִשּׁוּם שֶׁהֵן דְּרָגוֹת שֶׁלְּמַטָּה, כְּשֶׁמַּרְאֶה אָדָם הָאֶצְבָּעוֹת לִפְנֵי אוֹתוֹ אוֹר הַנֵּר, צָרִיךְ לְכָפְפָם לְפָנָיו, מִשּׁוּם שֶׁאוֹתוֹ אוֹר שׁוֹלֵט עֲלֵיהֶם, וְהֵם מְאִירִים מִמֶּנּוּ."],[4,"","בִּשְׁאָר הַבְּרָכוֹת צָרִיךְ לִזְקֹף אֶת הָאֶצְבָּעוֹת כְּדֵי לְהַרְאוֹת קְדֻשָּׁה עֶלְיוֹנָה שֶׁל הַדְּרָגוֹת הָעֶלְיוֹנוֹת שֶׁשּׁוֹלְטוֹת עַל הַכֹּל, שֶׁהַשֵּׁם הַקָּדוֹשׁ הִתְעַטֵּר בָּהֶן וְהִתְקַדֵּשׁ בָּהֶן, וְכָל הַדְּרָגוֹת מִתְבָּרְכוֹת כְּאֶחָד, וּמְאִירִים מִתּוֹךְ הַמְּנוֹרָה הָעֶלְיוֹנָה שֶׁל הַכֹּל, וּמִשּׁוּם כָּךְ צְרִיכִים לְזָקְפָם לְמַעְלָה. וְכָאן צָרִיךְ לְכוֹפֵף אֶת הָאֶצְבָּעוֹת לִפְנֵי הַנֵּר כְּדֵי לְהַרְאוֹת אֶת הַדְּרָגוֹת שֶׁלְּמַטָּה שֶׁמְּאִירִים מִתּוֹךְ הַמָּאוֹר הָעֶלְיוֹן, וּמִכָּאן שׁוֹלְטִים וּמְאִירִים מִמֶּנָּה, וְהֵם מְאוֹרֵי הָאֵשׁ."],[5,"","בְּכָל יוֹם אָנוּ מְבָרְכִים מְאוֹרֵי אוֹר, שֶׁהֵם אוֹרוֹת עֶלְיוֹנִים שֶׁעוֹמְדִים בְּאוֹתוֹ אוֹר רִאשׁוֹן, וְכָל הַדְּרָגוֹת מִתְבָּרְכוֹת וּמְאִירוֹת כֻּלָּן כְּאַחַת מִתּוֹךְ הַמָּאוֹר הָעֶלְיוֹן, וְאֵלֶּה נִקְרָאִים מְאוֹרֵי הָאֵשׁ. וּמִשּׁוּם הַסּוֹד הַזֶּה מְבָרְכִים בּוֹרֵא מְאוֹרֵי הָאֵשׁ."],[6,"","וְאִם תֹּאמַר, לָמָּה בּוֹרֵא, וְלֹא אוֹמְרִים מֵאִיר מְאוֹרֵי הָאֵשׁ, הוֹאִיל וּמְאִירִים מֵאוֹתָהּ הָאֵשׁ, מֵאוֹתָהּ מְנוֹרָה מְברֶכֶת? אֶלָּא, כֵּיוָן שֶׁנִּכְנֶסֶת שַׁבָּת, כָּל אוֹתָן הַדְּרָגוֹת שֶׁלְּמַטָּה וְכָל אוֹתָם שֶׁמְּאִירִים וְשׁוֹלְטִים, כֻּלָּם נִכְנָסִים וְנִכְלָלִים בַּנֵּר הַזֶּה, וְנִטְמָנִים וְנִגְנָזִים וְנִשְׁמָרִים בּוֹ וְלֹא נִרְאִים בּוֹ, אֶלָּא רַק אוֹתָהּ נְקֻדָּה לְבַדָּהּ, וְכֻלָּם נִטְמְנוּ בְתוֹכָהּ בְּכָל יוֹם הַשַּׁבָּת."],[7,"","כֵּיוָן שֶׁיּוֹצֵאת הַשַּׁבָּת, הוּא מוֹצִיא אוֹתָם כָּל אֶחָד וְאֶחָד כְּאִלּוּ נִבְרְאוּ בְּאוֹתָהּ שָׁעָה, וְכֻלָּם יָצְאוּ וְנִבְרְאוּ כְּמִקֹּדֶם וְהִתְמַנּוּ עַל מְקוֹמָם לִשְׁלֹט, וְאָז הַנֵּר הַזֶּה מִתְבָּרֵךְ, וְנִכְנָעִים לְפָנָיו לְהָאִיר. כֵּיוָן שֶׁמְּאִירִים, אָז הֵם מִתְמַנִּים כָּל אֶחָד וְאֶחָד עַל מְקוֹמוֹ."],[8,"","כְּמוֹ זֶה אוֹתָן דְּרָגוֹת עֶלְיוֹנוֹת שֶׁנִּקְרָאוֹת מְאוֹרֵי אוֹר, שׁוֹלְטוֹת בַּיּוֹם וּמְאִירוֹת מִתוֹךְ הַמָּאוֹר הָעֶלְיוֹן. בְּשָׁעָה שֶׁיּוֹרֵד הַלַּיְלָה, אוֹתוֹ מָאוֹר עֶלְיוֹן כּוֹנֵס אוֹתָם וּמַכְנִיס אוֹתָם לְתוֹכוֹ עַד שֶׁמֵּאִיר הַיּוֹם. כֵּיוָן שֶׁיִּשְׂרָאֵל מְבָרְכִים עַל הָאוֹר בַּיּוֹם, אָז מוֹצִיא אוֹתָם בִּשְׁלֵמוּת הָאוֹר, וְלָכֵן מְבָרְכִים יוֹצֵר הַמְּאוֹרוֹת וְלֹא אוֹמְרִים בּוֹרֵא (אלאיוצר). וְכָאן בּוֹרֵא מְאוֹרֵי הָאֵשׁ, מִשּׁוּם אוֹתָן הַדְּרָגוֹת שֶׁלְּמַטָּה."],[9,"","וְהַסֹל הוּא סוֹד הָאֶצְבָּעוֹת, בָּהֶן רְמוּזוֹת הַדְּרָגוֹת הָעֶלְיוֹנוֹת וְהַדְּרָגוֹת הַתַּחְתּוֹנוֹת. הַדְּרָגוֹת הָעֶלְיוֹנוֹת נוֹדָעוֹת בִּזְקִיפַת הָאֶצְבָּעוֹת לְמַעְלָה, וּבִזְקִיפַת הָאֶצְבָּעוֹת מִתְבָּרְכוֹת הַדְּרָגוֹת הָעֶלְיוֹנוֹת וְהַדְּרָגוֹת הַתַּחְתּוֹנוֹת כְּאֶחָד, וּבְהַנְמָכַת הָאֶצְבָּעוֹת מִתְבָּרְכִים לְהָאִיר הַדְּרָגוֹת הַתַּחְתּוֹנוֹת לְבַדָּן."],[10,"","וְהַסּוֹד הַזֶּה, הַצִּפָּרְנַיִם שֶׁל אֲחוֹרֵי הָאֶצְבָּעוֹת. וְהָאֶצְבָּעוֹת לְבַדָּן לִפְנִים. הַצִּפָּרְנַיִם שֶׁל אֲחוֹרֵי הָאֶצְבָּעוֹת הֵם פָּנִים אֲחֵרוֹת שֶׁצְּרִיכוֹת לְהָאִיר מִתּוֹךְ אוֹתוֹ נֵר, וְאוֹתָם פָּנִים שֶׁנִּקְרָאִים אֲחוֹרַיִם. הָאֶצְבָּעוֹת לִפְנִים בְּלִי צִפָּרְנַיִם, אֵלּוּ הֵן הַפָּנִים הַפְּנִימִיִּים הַמְכֻסִּים. וְסוֹד זֶה - (שמות לג) וְרָאִיתָ אֶת אֲחֹרָי. אֵלֶּה אֲחוֹרֵי הָאֶצְבָּעוֹת לְאָחוֹר בְּצִפָּרְנֵיהֶן. וּפָנַי לֹא יֵרָאוּ, אֵלֶּה הָאֶצְבָּעוֹת לִפְנִים בְּלִי צִפָּרְנַיִם, שֶׁהֵן הַפָּנִים הַפְּנִימִיִּים."]]],[["וְכַד מְבָרְכֵינָן עַל שְׁרָגָא, בָּעֵי לְאַחֲזָאָה אֲחוֹרֵי אֶצְבְּעָאן בְּטוּפְרִין, לְאִתְנָהֲרָא מִגּוֹ הַהוּא שְׁרָגָא, וּפְנִימָאֵי דְּאֶצְבְּעָאן, לָא אִצְטְרִיכוּ לְאַכְפַּיָּא (נ\"א לאחזאה) לוֹן לְאִתְנָהֲרָא מִגּוֹ הַהוּא שְׁרָגָא, דְּהָא אִינּוּן לָא נַהֲרִין, אֶלָּא מִגּוֹ שְׁרָגָא עִלָּאָה דִּלְעֵילָּא לְעֵילָּא, דְּאִיהִי טְמִירָא וּגְנִיזָא דְּלָא אִתְגַּלְיָיא כְּלַל. וְאִינּוּן לָא נַהֲרִין מִגּוֹ שְׁרָגָא דְּאִתְגַּלְיָא כְּלַל, בְּגִין כַּךְ בָּעֵי לְאַחֲזָאָה אֲחוֹרֵי אֶצְבְּעָאן בְּטוּפְרִין. וּפְנִימָאֵי דְּאֶצְבְּעָאן, לָא בָּעֵי לְאַחֲזָאָה קַמֵּי הַאי שְׁרָגָא. טְמִירִין אִינּוּן, וּבִטְמִירוּ אִתְנָהֲרִין. פְּנִימָאִין אִינּוּן, וּמִפְּנִימָאָה אִתְנָהֲרָן. עִלָּאִין אִינּוּן, וּמְעִלָּאָה אִתְנָהֲרָן. זַכָּאִין אִינּוּן יִשְׂרָאֵל, בְּעָלְמָא דֵּין, וּבְעָלְמָא דְּאָתֵי.","וּבָעֵי לְאָרְחָא בְּבוּסְמִין, כַּד נָפִיק שַׁבְּתָא, עַל דְּאִסְתַּלָּק הַהוּא רוּחָא, וְנַפְשָׁא דְּבַר נָשׁ אִשְׁתְּאָרַת בְּעַרְטוּלָא, (ס\"א אשתנית בקרטופא) בְּגִין הַהוּא סְלִיקוּ, דְּאִסְתַּלָּק רוּחָא מִנֵּיהּ וְהָא אוּקְמוּהָ.","כְּתִיב (בראשית כ״ז:כ״ז) וַיָּרַח אֶת רֵיחַ בְּגָדָיו וַיְבָרֲכֵהוּ וְגוֹ'. הַאי קְרָא אוּקְמוּהָ וְאִתְּמַר, אֲבָל תָּא חֲזֵי, רֵיחָא אִיהוּ קִיוּמָא דְּנַפְשָׁא, בְּגִין דְּאִיהוּ מִלָּה דְּאָעִיל לְנַפְשָׁא, וְלָא לְגוּפָא. תָּא חֲזֵי, כְּתִיב וַיָּרַח אֶת רֵיחַ בְּגָדָיו, הָא אוּקְמוּהָ, אִינּוּן לְבוּשֵׁי דְּאָדָם קַדְמָאָה הֲווֹ, דְּיָהַב לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְאַלְבָּשָׁא לוֹן.","בְּגִין דְּהָא כַּד חָב אָדָם, אִתְעָדֵי מִנִּיהּ הַהוּא לְבוּשָׁא יַקִּירָא, דְּאִתְלָבַּשׁ בֵּיהּ בְּקַדְמִיתָא, כַּד אָעִיל לֵיהּ בְּגִנְתָּא דְּעֵדֶן. וּלְבָתַר דְּחַב, אַלְבִּישׁ לֵיהּ בִּלְבוּשָׁא אַחֲרָא, לְבוּשָׁא קַדְמָאָה, דְּאִתְלָבַּשׁ בֵּיהּ אָדָם בְּגִנְתָּא דְּעֵדֶן, אִיהוּ הֲוָה (מאינון מלבושין) מֵאִינּוּן רְתִיכִין, דְּאִקְרוּן אֲחוֹרַיִים, וְאִינּוּן לְבוּשִׁין דְּאִקְרוּן לְבוּשֵׁי טוּפְרָא.","וְכַד הֲוָה בְּגִנְתָּא דְּעֵדֶן, כָּל אִינּוּן רְתִיכִין, וְכָל אִינּוּן מַשִׁרְיָין קַדִּישִׁין, כֻּלְּהוּ סָחֲרִין לֵיהּ לְאָדָם, וְאִתְנְטִיר מִכֹּלָּא, וְלָא הֲוָה יָכִיל מִלָּה בִּישָׁא לְאִתְקָרְבָא בַּהֲדֵיהּ. כֵּיוָן דְּחַב, וְאִתְעַדוּ מִנֵּיהּ אִינּוּן לְבוּשִׁין, (ס\"א ואתלבש בלבושין דחול ממלין כו') דָּחִיל מִמִּלִּין בִּישִׁין, וְרוּחִין בִּישִׁין, וְאִסְתָּלָּקוּ מִנֵּיהּ אִינּוּן מַשִׁרְיָין קַדִּישִׁין, וְלָא אִשְׁתָּאֲרוּ בֵּיהּ, אֶלָּא אִינּוּן רָאשֵׁי טוּפְרֵי דְּאֶצְבְּעָאן, דְּסַחֲרִין לוֹן לְטוּפְרִין סָחְרָנוּ דְּזוּהֲמָא אַחֲרָא.","וּבְגִין כַּךְ, לָא לִיבְעֵי לֵיהּ לְבַר נָשׁ לְרַבָּאָה אִינּוּן טוּפְרִין דְּזוּהֲמָא, דְּהָא כְּמָה דְּאַסְגִּיאוּ, הָכִי נָמֵי אַסְגֵּי עֲלֵיהּ קִסְטוּרָא, וְיִדְאַג בְכָל יוֹמָא, וּבָעֵי לְסַפְּרָא לוֹן, וְלָא יִרְמֵי לוֹן, דְּלָא יַעְבִיד קְלָנָא בְּהַהוּא אֲתָר, דְּיָכִיל הַהוּא בַּר נָשׁ לְאַתְּזְקָא. וְכֹלָּא כְּגַוְונָא עִלָּאָה. דְּהָא לְכֻלְּהוּ אֲחוֹרַיִים, סַחֲרָא סִטְרָא אַחֲרָא, וְלָא אִצְטְרִיךְ לֵיהּ בַּאֲתָר דְּעָלְמָא.","לְבָתַר עֲבַד לֵיהּ לְאָדָם, לְבוּשִׁין אַחֲרָנִין, מִטַּרְפֵּי אִילָנִין דְּגִּנְתָּא דְּעֵדֶן דְּאַרְעָא. דְּהָא בְּקַדְמִיתָא הֲווֹ אִינּוּן לְבוּשִׁין, מֵאִינּוּן אֲחוֹרַיִים דְּגִנְתָּא דִּלְעֵילָּא, וְהַשְׁתָּא מִגִּנְתָּא דְּאַרְעָא, וְנַפְקֵי מִגִּנְתָּא. וְאִינּוּן לְבוּשִׁין הֲווֹ סַלְּקִין רֵיחִין וּבוּסְמִין דְּגִּנְתָּא, דְּנַפְשָׁא מִתְיַישְּׁבָא בְּהוּ, וְחַדֵּי בְּהוּ. הֲדָא הוּא דִכְתִיב וַיָּרַח אֶת רֵיחַ בְּגָדָיו וַיְבָרַכֵהוּ, דְּהָא אִתְיַישְׁבָא נַפְשֵׁיהּ וְרוּחֵיהּ דְּיִצְחָק בְּהַהוּא רֵיחָא.","בְּגִין דָּא כַּד נָפַק שַׁבְּתָא, בָּעֵי לְאָרְחָא בְּבוּסְמִין, לְאִתְיַשְּׁבָא נַפְשֵׁיהּ בְּהַהוּא רֵיחָא, עַל הַהוּא רֵיחָא עִלָּאָה קַדִּישָׁא דְּאִסְתַּלָּק מִינָּהּ. וְהַהוּא רֵיחָא מְעַלְּיָא דְּבוּסְמִין אִיהוּ הֲדַס. דְּהָא קִיוּמָא דַּאֲתָר קַדִּישָׁא דְּנִשְׁמָתִין נָפְקִין מִנֵּיהּ, הֲדַס אִיהוּ. וְדָא אִיהוּ קִיוּמָא דְּנַפְשָׁא, כְּגַוְונָא דִּלְעֵילָּא, לְאִתְקַיְּימָא מֵהַהוּא עִרְטוּלָא דְּאִשְׁתְּאָרַת.","כַּד נָפַק שַׁבְּתָא, אִתְלָבָּשׁ אָדָם, בְּאִינּוּן לְבוּשִׁין דְּגִּנְתָּא דְּעֵדֶן דְּאַרְעָא, דְּסַלְּקִין רֵיחִין וּבוּסְמִין, לְקַיְּימָא נַפְשֵׁיהּ, עַל הַהוּא רוּחָא קַדִּישָׁא עִלָּאָה יַקִּירָא דְּאִסְתַּלָּק מִנֵּיהּ. וַהֲדַס אִיהוּ קִיוּמָא דְּנַפְשָׁא וַדַּאי. כְּגַוְונָא עִלָּאָה, דְּאִתְקַיְּימָא קִיוּמָא דְּנַפְשָׁא."],[[0,"וכד מברכינן על וכו':","וכשמברכים על הנר, צריכים להראות אחורי האצבעות בצפרנים, הרומזים על ד' מרכבות הנ\"ל, שיאירו מתוך נר ההוא, הרומז על מלכות. אבל הפנים של האצבעות אין צריכים להראותם שיאירו מתוך נר ההוא, שהוא מלכות, כי הם אינם מאירים אלא מתוך נר העליון למעלה למעלה, שהוא חכמה דז\"א, שהיא מכוסה וגנוזה, שהחכמה שלה אינה מתגלה כלל. והם אינם מאירים מתוך הנר שנתגלה, שהיא המלכות, שהחכמה מגולה בה (כנ\"ל ב\"א דף רע\"ו ד\"ה וזה). וע\"כ צריכים להראות אחורי האצבעות בצפרנים שעליהם, להיותם ממשיכי החכמה מן הנר ההוא שהוא המלכות, ופנים של האצבעות לא צריכים להראות לפני נר הזה, כי נסתרים הם ומאירים בנסתר ואין מקבלים חכמה מנר הזה. כי פנימיות הם ומאירים מפנימיות, עליונים הם, ומאירים מעליונים. אשריהם ישראל בעולם הזה ובעולם הבא."],[0,"","פירוש. האדם הוא מרכבה לזו\"ן, והידים הם חסד וגבורה הנעשים לחכמה ובינה בעת גדלות, בסוד שאו ידיכם קדש. ובכל יד ג' פרקים שה\"ס חב\"ד. וג' פרקי ימין הם חב\"ד דחכמה, וג' פרקי שמאל הם חב\"ד דבינה, אשר הקבורת המחובר לכתף ה\"ס דעת, והזרוע היא בינה, ופרק האצבעות הוא חכמה. הרי שהאצבעות של אדם רומזים על חכמה. ונודע שאין מדרגה שלא יהיה בה פנים ואחורים. כי בכל מדרגה יש ע\"ס כח\"ב תו\"מ, אשר הכתר וחכמה וחצי בינה נחשב לפנים של המדרגה, ותחתיהם יש פרסה, שבקטנות מוציאה חצי מדרגה למדרגה שמתחתיה, שהם חצי בינה ות\"ת ומלכות, ובגדלות יורדת המסך דמלכות מן הפרסה למקומה למטה ומחזרת החצי בינה ותו\"מ למדרגה (כנ\"ל ב\"א דף צ' ד\"ה בגין) וע\"כ אותם בינה ותו\"מ שנפלו בקטנות המדרגה מכונים אחורים של מדרגה גם בעת גדלות אחר שחזרו למדרגה."],[0,"","וגם מדרגת האצבעות נחלקת לב' חצאים האמורים, שהם פנים, ואחורים. אשר כו\"ח וחצי בינה שבהן, הנבחנים לפנים של האצבעות, הם ראשי האצבעות בצד הבשר. ובינה ותו\"מ שנפלו ממדרגה בעת הקטנות וחזרו לעת גדלות הנבחנים לאחורים, הם ראשי האצבעות בצד הצפרנים. \u0003והצפרנים\u0004 עצמן ה\"ס הפרסא המבדלת בין כלים דפנים לכלים דאחורים."],[0,"","והנה המלכות בדרך כלל, נבחנת לבחינת אחורים של ז\"א. ובדרך פרט, כל בחינות של אחורים שיש בז\"א ניתנו למלכות בסוד הנסירה (המבוארת בעשי\"ת בשער הכוונות) וע\"כ כל בחינה שבאצבעות מקבלת מבחינה שכנגדה, הפנים של האצבעות מקבלת מחכמה דז\"א שה\"ס פנים, ואשר החכמה אינה מתגלית בו, וז\"ש, \u0003ופנימאי דאצבען לא אצטריכו לאחזאה לון לאתנהרא מגו ההוא שרגא,\u0004 כי הם אין להם שייכות אל המלכות אלא מקבלים מבחינה שכנגדם בז\"א. וז\"ש, \u0003דהא אינון לא נהרין אלא מגו שרגא עלאה דלעילא לעילא,\u0004 דהיינו מחכמה דז\"א, שהיא הבחינה שכנגדן המיוחסת להן. אבל האחורים של האצבעות, מקבלות מחכמה שבמלכות, שהיא הבחינה שכנגדם המיוחסת להם כנ\"ל. ז\"ש, \u0003וכד מברכינן על שרגא בעי לאחזאה אחורי אצבען בטופרין לאתנהרא מגו ההוא שרגא,\u0004 כי הם המקבלים מן הנר שהיא המלכות, להיותה הבחינה שכנגדם."],[1,"ובעי לארחא בבוסמין וכו':","וצריך להריח בבשמים, כשיוצא השבת, משום שנסתלק רוח ההוא מן האדם, שהוא תוספת נשמה של שבת, והנפש של האדם נשארת ערומה, מכח הסתלקות ההיא שנסתלק הרוח ממנה. וכבר העמידוהו."],[2,"כתיב וירח את וגו':","כתוב וירח את ריח בגדיו ויברכהו וגו'. מקרא זה העמידוהו, ולמדנו. אבל בוא וראה, הריח הוא קיום של הנפש, משום שהוא דבר הנכנס אל הנפש ולא לגוף. בוא וראה, כתוב, וירח את ריח בגדיו, הרי העמידוהו, שהם הלבושים של אדם הראשון היו, שנתן לו הקב\"ה ללבוש אותם."],[3,"בגין דהא כד וכו':","משום, כשחטא אדם, הוסר ממנו לבוש היקר שהתלבש בו בתחילה כשהכניסו הקב\"ה לגן עדן. ואחר שחטא הלבישו בלבוש אחר. לבוש הראשון שאדם נתלבש בו תחלה בגן עדן, היה מאלו המרכבות הנקראות אחורים, שהם הלבושים הנקראים לבושי צפרן."],[4,"וכד הוה בגנתא וכו':","וכשהיה בגן עדן, כל אלו המרכבות וכל אלו המחנות הקדושים כולם היו מסבבים את אדם, ונשמר מהכל, ולא היה יכול דבר רע להתקרב אליו, כיון שחטא והוסרו ממנו אלו הלבושים של צפורן, היה מתירא מדברים רעים ומרוחות רעים, ונסתלקו ממנו אלו מחנות הקדושים שהיו מסבבים ושומרים אותו, ולא נשארו מאלו הלבושים, אלא אלו צפרנים שבראשי האצבעות, וזוהמא דסטרא אחרא מקפת הצפרנים מסביב להם."],[4,"","פירוש. כבר ידעת, שהצפרנים ה\"ס הפרסא המבדלת בין הכלים דפנים לכלים דאחורים, (כנ\"ל אות רס\"ט) והיא דבוקה על הכלים דאחורים, להיותה שורש הארתם, כי כל הארתם באה מכח שהפרסה הורידה המלכות המסיימת ממנה אל מקומה, שעי\"ז עלו הכלים דבינה ותו\"מ ממקום נפילתם אל מדרגתם, ונעשו שמה לשמאל, ולכלים דאחורים. הרי שהפרסא שורש אל הארתם וע\"כ היא דבוקה בהם, כמו שהצפרנים דבוקים על ראשי האצבעות. וכמו שהפרסא היא שורש לכלים דאחורים, כן היא שורש להארת מדרגה התחתונה, כי בעת שעולים הכלים דאחורים שהם בינה ותו\"מ למדרגתם הם לוקחים עמהם יחד גם את מדרגה התחתונה ומעלים אותה עמהם למדרגתם. (כנ\"ל בהקדמת ספר הזהר דף כ' ד\"ה ואמא) ונמצא שהפרסא נעשתה לשורש גם אל מדרגה תחתונה כמו שהיא שורש לכלים דאחורים, וע\"כ הפרסא דבוקה גם בכלים דמדרגה התחתונה."],[4,"","והנה נשמות אדם וחוה הם ממדרגה תחתונה אל זו\"ן, להיותן משתלשלות ויוצאות מהן. (כנ\"ל בספרא דצניעותא אות מ\"ד) ונמצא שבעת שהפרסא דזו\"ן העלתה את הכלים דבינה ותו\"מ שלהם שהיו נפולים בנשמות אדם וחוה, עלו עמהם גם נשמות אדם וחוה למקום המלכות דאצילות, שנקראת גן עדן. שז\"ס הכתוב, \u0003ויקח ה' אלקים את האדם ויניחהו בגן עדן.\u0004 ונמצא שאותה הפרסא דמלכות דאצילות, הדבוקה על הכלים דאחורים, שהם בינה ותו\"מ שלה, דבוקה ג\"כ על אדם, שהיא שורש אליו כמו שהיא שורש אל הכלים דאחורים. וז\"ש, \u0003לבושא קדמאה דאתלבש ביה אדם בגנתא דעדן,\u0004 וכו' \u0003דאקרון לבושי טופרא,\u0004 כי כמו שהצפרנים דבוקים על הכלים דאחורים של המלכות, כך היו מלבישים כל קומתו של אדם הראשון, משום שהצפרנים היו שורש להארתם, כנ\"ל. שלבוש הזה היה חשוב מאד מאד, להיותו בחינת הפרסא דמלכות דאצילות, שעל הכלים דאחורים שלה. וז\"ש, \u0003כיון דחב ואתעדו מניה אינון לבושין וכו' ולא אשתארו ביה אלא אינון ראשי טופרי דאצבעאן.\u0004 כי אחר החטא אבד הנשמה מאצילות, שהגיעה לו מכח הפרסא, וממילא אבד גם הלבוש של צפורן הבא מפרסא, וכפי השיעור הקטן שנשאר בו מנשמתו הגבוהה נשאר בו גם כן חלק מה מלבוש הצפורן, שה\"ס השיור של הצפרנים שעל ראשי האצבעות. ומתוך שהצפרנים הם מבחינת כלים דאחורים, יש כח לס\"א להדבק בהם ולינק מהם, וז\"ס החלק של הצפרנים, שאינו דבוק בבשר האצבע, ששם נמצא תמיד זוהמא, שה\"ס סטרא אחרא היונקת משם. וע\"כ אסור לגדלם עד שיצאו למעלה מבשר האצבע."],[5,"ובגין כך לא וכו':","ומשום זה, אין צריך האדם לגדל הצפרנים שיש בהם זוהמא, כי כמו שהם גדלים כך גדל עליו כח הדין, מכח הקליפות היונקים מצפרנים העודפים על הבשר, וידאג על זה כל יום, וצריך לחתוך אותם, ולא ישליכם, כדי שלא לנהוג בזיון במקום ההוא, להיות שורשם ממקום גבוה כנ\"ל בדבור הסמוך, כי אדם ההוא יכול להיות ניזוק מזה. והכל הוא כעין של מעלה כי בכל הכלים דאחורים למעלה מסבב עליהם סטרא אחרא. וע\"כ, גם בצפרנים מקיף הזוהמא את הצפרנים, להיותם נמשכים מאחורים, כנ\"ל בסמוך, ולא צריכים להיות במקום העולם, דהיינו במקום ישוב."],[6,"לבתר עבד ליה וכו':","אח\"כ עשה הקב\"ה לאדם לבושים אחרים מעלי האלנות שבגן עדן. ואע\"פ שכתוב, ויעש וגו' כתנות עור, אמנם בתורתו של ר' מאיר כתנות אור כתוב, והיינו מחמת שהיו מעלי אילנות שבג\"ע, שהם אורות. כי מתחלה היו הלבושים של אדם מאחורים של הגן שלמעלה, שהוא המלכות דאצילות, דהיינו מהפרסא שלה (כנ\"ל אות רע\"ד) ועתה, לאחר החטא, היו מגן עדן הארץ, שבעולם עשיה, ויוצאים מן הגן. ואלו הלבושים, היו מעלים ריחות ובשמים של הגן, שהנפש מתישב בהם ושמח בהם. ז\"ש, וירח את ריח בגדיו ויברכהו. כי נתישבו נפשו ורוחו של יצחק בריח ההוא."],[7,"בג\"ד כד נפק וכו':","משום זה, כשיצא השבת, צריכים להריח בבשמים, שנפשו תתישב בריח ההוא, תמורת ריח העליון הקדוש ההוא שנסתלק ממנו, וריח המשובח שבבשמים, הוא הדס. כי הקיום של מקום הקדוש, דהיינו מלכות, שהנשמות יוצאות ממנה הוא הדס. וזה הוא ג\"כ הקיום של נפש האדם, כמו של מעלה, להתקיים מן העירום ההוא שנשארה בו, אחר הסתלקות, התוספת נשמה של שבת."],[7,"","פירוש. חג\"ת דז\"א מכונים הדסים. מבחינת מה שמשפיעים הארת חכמה אל המלכות. כי הארת החכמה מכונה ריח. ונמצא שהדסים אלו מקיימים את המלכות, שעיקרה היא הארת חכמה. וז\"ש \u0003דהא קיומא דאתר קדישא,\u0004 שהוא המלכות הנקראת מקום, \u0003הוא הדס,\u0004 דהיינו חג\"ת דז\"א המעלים ריח, שה\"ס הארת חכמה, להשפיע להמלכות. וע\"כ לוקחים הדס לקיים נפשו של אדם במוצאי שבת, אחר הסתלקות הנשמה יתירה."],[8,"כד נפק שבתא וכו':","כשיצא השבת, נתלבש אדם הראשון באלו הלבושים דג\"ע הארץ, הנ\"ל, המעלים ריחות ובשמים לקיים נפשו, במקום, רוח הקדוש העליון היקר, שה\"ס זיהרא עלאה דאצילות, שנסתלק ממנו. והדס הוא קיום הנפש ודאי, כמו בעליון שנתקיים קיום הנפש שהיא המלכות. כמ\"ש בסמוך."]],[[0,"","וּכְשֶׁמְּבָרְכִים עַל הַנֵּר, צָרִיךְ לְהַרְאוֹת אֶת אֲחוֹרֵי הָאֶצְבָּעוֹת בַּצִּפָּרְנַיִם, לְקַבֵּל אוֹר מִתּוֹךְ אוֹתוֹ הַנֵּר, וְאֶת פְּנִים הָאֶצְבָּעוֹת לֹא צָרִיךְ לִכְפּוֹת (להראות) אוֹתָן שֶׁיָּאִירוּ מִתּוֹךְ אוֹתוֹ נֵר, שֶׁהֲרֵי אֵינָן מְאִירוֹת אֶלָּא מִתּוֹךְ הַנֵּר הָעֶלְיוֹן שֶׁלְּמַעְלָה לְמַעְלָה, שֶׁהוּא טָמִיר וְגָנוּז וְשֶׁלֹּא נִגְלֶה כְּלָל. וְאֵינָן מְאִירוֹת מִתּוֹךְ נֵר שֶׁגָּלוּי כְּלָל. מִשּׁוּם כָּךְ צָרִיךְ לְהַרְאוֹת אֶת אֲחוֹרֵי הָאֶצְבָּעוֹת בַּצִּפָּרְנַיִם, וְאֶת פְּנִים הָאֶצְבָּעוֹת לֹא צָרִיךְ לְהַרְאוֹת לִפְנֵי הַנֵּר הַזֶּה. טְמִירוֹת הֵן, וּבַסֵּתֶר הֵן מְאִירוֹת. פְּנִימִיּוֹת הֵן, וּמִפְּנִימִיִּים מְאִירוֹת. עֶלְיוֹנוֹת הֵן, וּמֵעֶלְיוֹנִים הֵן מְאִירוֹת. אַשְׁרֵיהֶם יִשְׂרָאֵל בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא."],[1,"","וְצָרִיךָ לְהָרִיחַ בִּבְשָׂמִים כְּשֶׁיּוֹצֵאת שַׁבָּת עַל שֶׁהִסְתַּלְּקָה אוֹתָהּ רוּחַ, וְנֶפֶשׁ הָאָדָם נִשְׁאֶרֶת עֲרֻמָּה (משתגית בבקעים) מִשּׁוּם אוֹתוֹ סִלּוּק שֶׁהִסְתַּלְּקָה הָרוּחַ מִמֶּנּוּ, וַהֲרֵי פֵּרְשׁוּהָ."],[2,"","כָּתוּב (בראשית כז) וַיָּרַח אֶת רֵיחַ בְּגָדָיו וַיְבָרֲכֵהוּ וְגוֹ'. פָּסוּק זֶה פֵּרְשׁוּהוּ וְנִתְבָּאֵר. אֲבָל בּא וּרְאֵה, הָרֵיחַ הוּא קִיּוּם הַנֶּפֶשׁ, מִשּׁוּם שֶׁהוּא דָּבָר שֶׁנִּכְנָס לַנֶּפֶשׁ וְלֹא לַגּוּף. בֹּא וּרְאֵה, כָּתוּב וַיָּרַח אֶת רֵיחַ בְּגָדָיו, הֲרֵי פֵּרְשׁוּהוּ שֶׁאֵלּוּ הָיוּ אוֹתָם לְבוּשֵׁי אָדָם הָרִאשׁוֹן שֶׁנָּתַן לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְלָבְשָׁם."],[3,"","מִשּׁוּם שֶׁהֲרֵי כְּשֶׁחָטָא אָדָם, הָעֳבַר מִמֶּנּוּ אוֹתוֹ לְבוּשׁ נִכְבָּד שֶׁהִתְלַבֵּשׁ בּוֹ בָּרִאשׁוֹנָה כְּשֶׁהִכְנִיסוֹ לְגַן עֵדֶן, וְאַחַר שֶׁחָטָא הִלְבִּישׁ אוֹתוֹ בִּלְבוּשׁ אַחֵר. הַלְּבוּשׁ הָרִאשׁוֹן שֶׁהִתְלַבֵּשׁ בּוֹ אָדָם בְּגַן עֵדֶן, הוּא הָיָה (מאותם מלבושים) מֵאוֹתָן מֶרְכָּבוֹת שֶׁנִּקְרְאוּ אֲחוֹרַיִם, וְאוֹתָם לְבוּשִׁים שֶׁנִּקְרְאוּ לְבוּשֵׁי צִפֹּרֶן."],[4,"","וּכְשֶׁהָיָה בְּגַן עֵדֶן, כָּל אוֹתָן מֶרְכָּבוֹת וְכָל אוֹתָם מַחֲנוֹת קְדוֹשִׁים, כֻּלָּם הִקִּיפוּ אֶת אָדָם, וְנִשְׁמַר מֵהַכֹּל, וְלֹא הָיָה יָכוֹל דָּבָר רַע לִקְרַב אֵלָיו. וְכֵיוָן שֶׁחָטָא וְהָעָבְרוּ מִמֶּנּוּ אוֹתָם לְבוּשִׁים, (והתלבש בלבושי חל מדברים) פָּחַד מִדְּבָרִים רָעִים וְרוּחוֹת רָעוֹת, וְהִסְתַּלְּקוּ מִמֶּנּוּ אוֹתָם מַחֲנוֹת קְדוֹשִׁים. וְלֹא נִשְׁאֲרוּ בוֹ אֶלָּא אוֹתָם רָאשֵׁי צִפָּרְנֵי הָאֶצְבָּעוֹת שֶׁסּוֹבְבִים אֶת הַצִּפָּרְנַיִם סְבִיב זֻהֲמָה אַחֶרֶת."],[5,"","וּמִשּׁוּם כָּךְ לֹא צָרִיךְ לְאָדָם לְגַדֵּל אוֹתָן צִפָּרְנַיִם שֶׁל זֻהֲמָה, שֶׁהֲרֵי כַּמָּה שֶׁמִּתְרַבּוֹת, כָּךְ גַּם מַרְבֶּה עָלָיו זֻהֲמָה, וְיִדְאַג בְּכָל יוֹם וְצָרִיךְ לִגְזר אוֹתָן, וְלֹא יִזְרֹק אוֹתָן, שֶׁלֹּא יַעֲשֶׂה קָלוֹן בְּאוֹתוֹ מָקוֹם, שֶׁיָּכוֹל אוֹתוֹ אָדָם לְהִנָּזֵק. וְהַכֹּל כְּמוֹ שֶׁלְּמַעְלָה. שֶׁהֲרֵי לְכָל אֲחוֹרַיִם מַקִּיף הַצַּד הָאַחֵר, וְלֹא צְרִיכִים אוֹתוֹ בַּמָּקוֹם שֶׁל הָעוֹלָם."],[6,"","אַחַר כָּךְ עָשָׂה לְאָדָם לְבוּשִׁים אֲחֵרִים מֵהֶעָלִים שֶׁל עֲצֵי גַּן הָעֵדֶן שֶׁבָּאָרֶץ. שֶׁהֲרֵי בָּרִאשׁוֹנָה הָיוּ אוֹתָם לְבוּשִׁים מֵאוֹתָם אֲחוֹרַיִם שֶׁל הַגָּן שֶׁלְּמַעְלָה, וְעַכְשָׁו מֵהַגָּן שֶׁל הָאָרֶץ, וְיָצְאוּ מֵהַגָּן. וְאוֹתָם לְבוּשִׁים הָיוּ מַעֲלִים רֵיחוֹת וּבְשָׂמִים שֶׁל הַגָּן שֶׁהַנֶּפֶשׁ מִתְיַשֶּׁבֶת בָּהֶם וּשְׂמֵחָה בָהֶם. זֶהוּ שֶׁכָּתוּב וַיָּרַח אֶת רֵיחַ בְּגָדָיו וַיְבָרֲכֵהוּ, שֶׁהֲרֵי הִתְיַשְּׁבָה נַפְשׁוֹ וְרוּחוֹ שֶׁל יִצְחָק בְּאוֹתוֹ רֵיחַ."],[7,"","מִשּׁוּם כָּךְ, כְּשֶׁיּוֹצֵאת שַׁבָּת, צָרִיךְ לְהָרִיחַ בַּבְּשָׂמִים לְיַשֵּׁב אֶת נַפְשׁוֹ בְּאוֹתוֹ רֵיחַ עַל אוֹתוֹ רֵיחַ עֶלְיוֹן קָדוֹשׁ שֶׁהִסְתַּלֵּק מִמֶּנּוּ, וְאוֹתוֹ רֵיחַ הַמְעֻלֶּה שֶׁבַּבְּשָׂמִים הוּא הֲדַס, שֶׁהֲרֵי קִיּוּם הַמָּקוֹם הַקָּדוֹשׁ שֶׁמִּמֶּנּוּ יוֹצְאוֹת הַנְּשָׁמוֹת הוּא הֲדַס. וְזֶהוּ קִיּוּם הַנֶּפֶשׁ כְּמוֹ שֶׁלְּמַעְלָה, כְּדֵי לְהִתְקַיֵּם מֵאוֹתָהּ הִתְעַרְטְלוּת שֶׁנִּשְׁאֲרָה."],[8,"","כְּשֶׁיּוֹצֵאת הַשַּׁבָּת, הִתְלַבֵּשׁ אָדָם בְּאוֹתָם לְבוּשֵׁי גַּן עֵדֶן שֶׁל הָאָרֶץ שֶׁמַּעֲלִים רֵיחַ וּבְשָׂמִים, לְקַיֵּם אֶת הַנֶּפֶשׁ עַל אוֹתָהּ רוּחַ קְדוֹשָׁה עֶלְיוֹנָה נִכְבָּדָה שֶׁהִסְתַּלְּקָה מִמֶּנּוּ. וַהֲדַס הוּא וַדַּאי קִיּוּם הַנֶּפֶשׁ, כְּדֻגְמָא עֶלְיוֹנָה, שֶׁהִתְקַיְּמָה קִיּוּם הַנֶּפֶשׁ."]]],[["הַהוּא רוּחָא עִלָּאָה דְּנָחִית עָלֵיהּ דְּבַר נָשׁ בְּחֵדוּ, וְחַדֵּי לְנַפְשֵׁיהּ, כְּדֵין קַיְימָא נַפְשָׁא דְּבַר נָשׁ, כְּגַוְונָא דְּעָלְמָא דְּאָתֵי, דְּזַמִּין לְאִתְהֲנָאָה מִנֵּיהּ, כְּמָה דְּבַר נָשׁ, אַהֲנִי לְהַאי רוּחָא בְּעָלְמָא דָּא. הָכִי הַהוּא רוּחָא אַהֲנִי לֵיהּ לְבַר נָשׁ, לְעָלְמָא דְּאָתֵי, דִּכְתִּיב, (ישעיהו נ״ח:י״א) אָז תִּתְעַנַּג עַל יְיָ' וְגוֹ'. וּכְתִיב וְהִשְׁבִּיעַ בְּצַחְצָחוֹת נַפְשֶׁךָ. כְּמָה דְּבַר נָשׁ, רַוֵי לְהַהוּא עִנּוּגָא, וְאַהֲנֵי לֵיהּ, הָכִי נָמֵי אִיהוּ רַוֵי לֵיהּ לְעָלְמָא דְּאָתֵי. כְּדֵין כַּד בַּר נָשׁ זָכֵי, וְאַשְׁלִים שְׁלִימוּ דִּיְקָרָא דְּשַׁבְּתָא כִּדְקָאָמְרָן, קוּדְשָׁא בְּרִיךְ הוּא קָארֵי עָלֵיהּ וְאָמַר, (ישעיהו מ״ט:ג׳) וַיֹּאמֶר לִי עַבְדִּי אָתָּה יִשְׂרָאֵל אֲשֶׁר בְּךָ אֶתְפָּאָר.","קָם רִבִּי אַבָּא, וּשְׁאַר חַבְרַיָּיא, וְנַשְׁקוּ רֵישֵׁיהּ. בָּכוּ וְאָמְרוּ, זַכָּאָה חוּלָקָנָא דְּאָרְחָא דָּא זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לָקֳבְלָן. אָמַר רִבִּי אַבָּא, לִי זַמִּין קוּדְשָׁא בְּרִיךְ הוּא אָרְחָא דָּא, בְּגִין לְאִתְחַבְּרָא עִמְּכוֹן. זַכָּאָה אִיהוּ חוּלָקִי, דְּזָכֵינָא לְאָרְחָא דָּא.","אָמַר לְהוּ, אֵימָּא לְכוּ מַה דַּחֲמֵינָא, יוֹמָא דָּא נָפַקְנָא לְאָרְחָא, וַחֲמֵינָא נְהוֹרָא חֲדָא, וְאִתְפְּלַג לִתְלַת נְהוֹרִין, וְאָזְלוּ קָמָאי, וְאִתְטָמָרוּ. וַאֲמֵינָא וַדַּאי שְׁכִינְתָּא חֲמֵינָא, זַכָּאָה חוּלָקִי. וְהַשְׁתָּא אִינּוּן תְּלַת נְהוֹרִין דַּחֲמֵינָא, אַתּוּן אִינּוּן, וַדַּאי אַתּוּן נְהוֹרִין, וּבוּצִינִין עִלָּאִין, לְאַנְהָרָא בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי.","אָמַר רִבִּי אַבָּא עַד הָכִי לָא יְדַעְנָא, דְּכָל אִלֵּין מַרְגְּלָן סְתִימִין הֲווֹ תְּחוֹת יָדַיְיכוּ, כֵּיוָן דַּחֲמֵינָא, דְּהָא בִּרְעוּתָא דְּפִקּוּדָא דְּמָארֵיכוֹן אִתְאֲמָרוּ מִלִּין אִלֵּין, יְדַעְנָא, דְּכֻלְּהוּ מִלִּין סַלְּקִין יוֹמָא דָּא, לְגוֹ כּוּרְסְיָּיא עִלָּאָה, וְנָטִיל לוֹן הַהוּא מָארֵי דְּאַנְפִּין, וְעָבִיד מִינַּיְיהוּ עִטְרִין לְמָארֵיהּ. וְיוֹמָא דָּא מִתְעַטְּרִין (נ\"א שבעין) שִׁתִּין רְתִיכִין קַדִּישִׁין, לִיקָרָא דְּכֻרְסְיָיא, בְּאִלֵּין מִלִּין דְּאִתְאַמָּרוּ הָכָא, יוֹמָא דָּא.","אַדְּהָכִי זָקַף עֵינוֹי, וְחָמָא דְּאַעְרַב שִׁמְשָׁא. אָמַר רִבִּי אַבָּא, נְהַךְ לְגַבֵּי הַאי כְּפַר, דְּאִיהוּ קָרִיב לְגַבָּן בְּמַדְבְּרָא. אָזְלוּ וּבֵיתוֹ תַּמָּן. בְּפַלְגוּת לֵילְיָא, קָם רִבִּי אַבָּא וּשְׁאַר חַבְרַיָּיא, לְאִשְׁתַּדְּלָא בְּאוֹרַיְיתָא, אָמַר רִבִּי אַבָּא, מִכָּאן וּלְהָלְאָה נִימָא מִלִּין לְאִתְעַטְּרָא בְּהוּ צַדִּיקַיָּא דִּבְגִנְתָּא דְּעֵדֶן, דְּהַשְׁתָּא אִיהוּ זִמְנָא, דְּקוּדְשָׁא בְּרִיךְ הוּא וְכָל צַדִּיקַיָּא דִּבְגִנְתָּא דְּעֵדֶן, צַיְיתִין לְקָלֵיהוֹן דְּצַדִּיקַיָּא דִּי בְּאַרְעָא.","פָּתַח רִבִּי אַבָּא וְאָמַר, כְּתִיב (תהילים קט״ו:ט״ז) הַשָּׁמַיִם שָׁמַיִם לַיְיָ' וְהָאָרֶץ נָתַן לִבְנֵי אָדָם הַאי קְרָא אִית לְאִסְתַּכְּלָא בֵּיהּ, וְהָכִי אִצְטְרִיךְ לְמֵימַר הַשָּׁמַיִם לַיְיָ', וְהָאָרֶץ נָתַן לִבְנִי אָדָם. מַאי הַשָּׁמָיִם שָׁמַיִם. אֶלָּא הָכָא אִית לְאִסְתַּכְּלָא, בְּגִין דְּאִית שָׁמַיִם, וְאִית שָׁמַיִם. שָׁמַיִם לְתַתָּא, וְאֶרֶץ לְתַתָּא מִנַּיְיהוּ. שָׁמַיִם לְעֵילָּא, וְאֶרֶץ לְתַתָּא מִנַּיְיהוּ. וְכָל דַּרְגִּין עִלָּאִין וְתַתָּאִין, כֻּלְּהוּ כְּגַוְונָא דָּא, אִלֵּין בְּאִלֵּין.","שָׁמַיִם לְתַתָּא, אִינּוּן עֶשֶׂר יְרִיעוֹת, כְּמָה דְאַתְּ אָמֵר (תהילים ק״ד:ב׳) נוֹטֶה שָׁמַיִם כַּיְרִיעָה. וְקוּדְשָׁא בְּרִיךְ הוּא עֲבַד לוֹן, וּמַשִׁרְיָין דִּי בְּגַוַּויְיהוּ, לְאַנְהָגָא אַרְעָא תַּתָּאָה. תְּשִׁיעָאָה אַנְהִיג לְתַתָּאֵי, דְּסַחֲרָן כְּקוּפְטְרָא דְּקוּלְטָא. עֲשִׁירָאָה, אִיהוּ עִקָּרָא.","וּבְכֻלְּהוּ מַשִׁירְיָין מְמָנָן עַד שְׁבִיעָאָה. מִשְּׁבִיעָאָה וּלְהָלְאָה, אִית נְהוֹרָא דְּאִתְפָּשַּׁט לְתַתָּא, מִגּוֹ כּוּרְסְיָּיא עִלָּאָה, וְנָהִיר לַעֲשִׂירָאָה. וַעֲשִׂירָאָה, מֵהַהוּא נְהִירוּ דְּנַקְטָא, יָהִיב לִתְשִׁיעָאָה, וְאִיהוּ לִתְמִינָאָה וּלְתַתָּא.","הַאי תְּמִינָאָה, כַּד אִתְפַּקְדוּן חֵילֵי דְּכוֹכָבַיָּא, וְאַפִּיק לוֹן, הַהוּא נְהִירוּ, קַיְּימָא וְיָהִיב חֵילֵיהּ לְכָל חַד וְחַד, לְאִתְמַנָאָה בְּהַהוּא אֲתָר דְּאִצְטְרִיךְ. דִּכְתִּיב, (ישעיהו מ׳:כ״ו) הַמּוֹצִיא בְּמִסְפָּר צְבָאָם וְגוֹ', מֵרֹב אוֹנִים, דָּא אִיהוּ זֹהֲרָא דִּלְעֵילָּא, דְּאִקְרֵי רוֹב אוֹנִים.","וּבְכָל רְקִיעָא וּרְקִיעָא, אִית מְמָנָא, וְאִתְפְּקַד עַל עָלְמָא, וְעַל אַרְעָא, לְאַנְהָגָא כֹּלָּא. בַּר אַרְעָא דְּיִשְׂרָאֵל, דְּלָא אַנְהִיג לָהּ רְקִיעָא, וְלָא חֵילָא אַחֲרָא, אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי, וְהָא אוּקְמוּהָ. וְאִי תֵּימָא הֵיךְ שַׁרְיָא לְמַגָּנָא רְקִיעָא עַל אַרְעָא דְּיִשְׂרָאֵל, וְהָא מִטְרָא וְטָלָא מֵרְקִיעָא נָחִית עָלָה, כִּשְׁאַר כָּל אַרְעָא אַחֲרָא."],[[0,"ההוא רוחא עלאה","וכו': רוח העליון ההוא, דהיינו התוספת נשמה, היורד על האדם, בשבת, בשמחה, ומשמח את נפשו, אז נמצאת נפש האדם, כמו בעולם הבא, שנפשו עתיד להנות ממנו, מן הרוח. כמו שהאדם היה מהנה לרוח ההוא בעולם הזה, כך רוח ההוא מהנה את האדם לעולם הבא. שכתוב, אז תתענג על ה' וגו'. וכתוב, והשביע בצחצחות נפשך. כמו שהאדם רוה עונג ההוא, שהוא הרוח, ומענגו, כך הוא ירוה ממנו לעולם הבא. אז כשזוכה האדם ומשלים שלמות יקר השבת כמו שאמרנו, הקב\"ה קורא עליו ואומר, ויאמר לי עבדי אתה ישראל אשר בך אתפאר."],[1,"קם רבי אבא וכו':","קם ר\"א ושאר החברים, ונשקו ראשו של ר' יצחק. בכו ואמרו, אשרי חלקנו, שהזמין הקב\"ה לפנינו את דרך הזה, (עי' לעיל אות ס\"ו) אמר ר' אבא לי הזמין הקב\"ה דרך הזה כדי להתחבר עמכם, אשרי חלקי שזכיתי לדרך הזה."],[2,"אמר להו אימא וכו':","אמר להם, אומר לכם מה שראיתי ביום הזה שיצאתי לדרך, ראיתי אור אחד שנחלק לג' אורות, והלכו לפני, ונסתתרו. ואמרתי, ודאי שראיתי השכינה, אשרי חלקי. ועתה, אלו ג' אורות שראיתי, אתם הם. דהיינו ר' חייא ור' יוסי ור' יצחק, אתם אורות ומאורות עליונים להאיר בעולם הזה ובעולם הבא."],[3,"אמר רבי אבא וכו':","אר\"א, עד כאן לא ידעתי, שכל אלו מרגליות הסתומות היו תחת ידכם. כיון שראיתי שברצון מצות רבונכם נאמרו דברים האלו, אני יודע שכל הדברים עולים ביום הזה לכסא העליון שהוא בינה, ולוקח אותם שר הפנים, שהוא מטטרון, ועושה מהם עטרות לרבונו. ויום הזה מתעטר ששים מרכבות קדושות כנגד חג\"ת נה\"י, לכבוד הכסא, שהוא בינה, על ידי אלו הדברים שנאמרו כאן ביום הזה."],[4,"אדהכי זקף עינוי וכו':","בתוך כך, נשא עיניו, וראה שהעריב השמש. אמר ר' אבא, נלך לכפר ההוא במדבר שהוא קרוב לנו. הלכו ולנו שם. בחצות לילה, קם ר' אבא ושאר החברים לעסוק בתורה. אמר ר' אבא, מכאן ולהלאה נאמר דברים לעטר עמהם הצדיקים שבגן עדן. כי עתה הוא הזמן שהקב\"ה וכל הצדיקים שבגן עדן, מקשיבים לקולם של הצדיקים אשר בארץ."],[5,"פתח ר' אבא וכו':","פתח ר\"א ואמר, השמים שמים לה' והארץ נתן לבני אדם. במקרא הזה יש להסתכל בו, כי כך היה צריך לומר, השמים לה' והארץ נתן לבני אדם, מהו השמים שמים. ומשיב, אלא כאן יש להסתכל, משום שיש שמים ויש שמים, שיש שמים למטה בעולם עשיה וארץ למטה משמים, ויש שמים למעלה בעולם אצילות, וארץ למטה משמים. וכל המדרגות העליונות ותחתונות כולם כעין זה נמשכים אלו מאלו, וכל מה שיש למעלה יש למטה. ודומים זה לזה כמו חותם והנחתם ממנו, שכל מה שיש בחותם יש בנחתם ממנו, וכל אחד למטה מקבל מבחינה שכנגדו למעלה."],[6,"שמים לתתא אינון וכו':","השמים למטה בעולם עשיה, הן עשר יריעות, דהיינו עשר ספירות, כש\"א נוטה שמים כיריעה. ועשה אותם הקב\"ה ואת מחנות המלאכים שבהם, להנהיג ארץ התחתונה דעשיה. ורקיע התשיעי, שהוא חכמה, מנהיג התחתונים, ומסבבם כמחרוזת אבנים טובות, המסבבות הצואר, כלומר, שאין דבר נעשה בתחתונים זולת על ידו בסו\"ה, כולם בחכמה עשית, רקיע העשירי הוא עיקר כל הרקיעים, להיותו ספירת כתר, שהוא שורש ועיקר לכל ט\"ס תחתנות. \u0003קופטרא,\u0004 פירושו חוט, מלשון כקפטורין יוצאה מתוך הושט (תנחומא מקץ) \u0003דקרלהו,\u0004 פירושו אבנים טובות אדומות שחורזים אותם על חוט שנושאים סביב הצואר מלשון, גומין וקורלין. (ירושלמי שבת ז')."],[7,"ובכלהו משריין ממנן וכו':","ובכל הרקיעים יש מחנות ממונים עד רקיע השביעי, שהוא חסד. אבל בג\"ר דרקיעים אין ממונים. מרקיע השביעי והלאה, שהם ג\"ר, כח\"ב, יש אור המתפשט למטה מן הכסא העליון, שהוא מלכות דאצילות, ומאיר לרקיע העשירי, שהוא כתר דעשיה, ורקיע העשירי מאותו האור שקבל, הוא נותן לרקיע התשיעי, שהוא חכמה. ורקיע התשיעי מאיר לרקיע השמיני שהוא בינה, ולמטה."],[8,"האי תמינאה וכו':","רקיע השמיני הזה בו נמצאים הככבים, וכשמתפקדים צבאות הככבים, והוא מוציאם, אותו האור שקבל מרקיע החכמה, עומד ונותן כחו לכל אחד ואחד להתמנות במקום ההוא שצריך. שכתוב, המוציא במספר צבאם וגו'. \u0003מרב אונים,\u0004 זה הוא זהר העליון, שקבל מן רקיע החכמה, הנקרא רב אונים."],[9,"ובכל רקיעא ורקיעא וכו':","ובכל רקיע ורקיע יש ממונה שנתמנה על העולם ועל הארץ, להנהיג את כולם. חוץ בארץ ישראל, שאין רקיע מנהיג אותה, ולא כח אחר, אלא הקב\"ה בלבדו. וכבר העמידוהו. ואם תאמר, איך שורה הרקיע על ארץ ישראל בחנם, והרי מטר וטל יורד עליה מרקיע, כשאר כל ארץ אחרת."]],[[0,"","אוֹתָהּ רוּחַ עֶלְיוֹנָה שֶׁיּוֹרֶדֶת עַל אָדָם בְּשִׂמְחָה וּמְשַׂמַּחַת אֶת נַפְשׁוֹ, אָז עוֹמֶדֶת נֶפֶשׁ הָאָדָם כְּמוֹ הָעוֹלָם הַבָּא, שֶׁעָתִיד לֵהָנוֹת מִמֶּנּוּ. כְּמוֹ שֶׁאָדָם מְהַנֶּה אֶת הָרוּחַ הַזּוֹ בָּעוֹלָם הַזֶּה, כָּךְ אוֹתָהּ רוּחַ מְהַנָּה אוֹתוֹ לָעוֹלָם הַבָּא, שֶׁכָּתוּב (ישעיה נח) אָז תִּתְעַנַּג עַל ה' וְגוֹ'. וְכָתוּב וְהִשְׂבִּיעַ בְּצַחְצָחוֹת נַפְשֶׁךְ. כְּמוֹ שֶׁאָדָם מַרְוֶה אֶת אוֹתוֹ עֹנֶג וּמְהַנֶּה אוֹתוֹ, כָּךְ גַּם הוּא מַרְוֶה אוֹתוֹ לָעוֹלָם הַבָּא. אָז כְּשֶׁהָאָדָם זוֹכֶה וּמַשְׁלִים אֶת שְׁלֵמוּת כְּבוֹד שַׁבָּת כְּפִי שֶׁאָמַרְנוּ, הַקָּדוֹשׁ בָּרוּךְ הוּא קוֹרֵא עָלָיו וְאוֹמֵר, (שם מט) וַיֹּאמֶר לִי עַבְדִּי אָתָּה יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר."],[1,"","קָם רַבִּי אַבָּא וּשְׁאָר הַחֲבֵרִים וְנָשְׁקוּ רֹאשׁוֹ. בָּכוּ וְאָמְרוּ, אַשְׁרֵי חֶלְקֵנוּ שֶׁהַדֶּרֶךְ הַזּוֹ זִמֵּן הַקָּדוֹשׁ בָּרוּךְ הוּא לְפָנֵינוּ. אָמַר רַבִּי אַבָּא, לִי זִמֵּן הַקָּדוֹשׁ בָּרוּךְ הוּא הַדֶּרֶךְ הַזּוֹ כְּדֵי לְהִתְחַבֵּר עִמָּכֶם. אַשְׁרֵי חֶלְקִי שֶׁזָּכִיתִי לַדֶּרֶךְ הַ את."],[2,"","אָמַר לָהֶם, אֹמַר לָכֶם מַה שֶּׁרָאִיתִי, הַיּוֹם הַזֶּה יָצָאתִי לַדֶּרֶךְ, וְרָאִיתִי אוֹר אֶחָד שֶׁנֶּחֱלָק לִשְׁלֹשָׁה אוֹרוֹת, וְהָלְכוּ לְפָנַי וְנִטְמְנוּ. וְאָמַרְתִּי, וַדַּאי שְׁכִינָה רָאִיתִי, אַשְׁרֵי חֶלְקִי. וְעַכְשָׁו אוֹתָם שְׁלֹשֶׁת הָאוֹרוֹת שֶׁרָאִיתִי, אַתֶּם הֵם, וַדַּאי שֶׁאַתֶּם אוֹרוֹת וּמְנוֹרוֹת עֶלְיוֹנוֹת לְהָאִיר בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא."],[3,"","אָמַר רַבִּי אַבָּא, עַד כָּאן לֹא יָדַעְתִּי שֶׁכָּל הַמַּרְגָּלִיּוֹת הַנִּסְתָּרוֹת הַלָּלוּ הָיוּ תַחַת יְדֵיכֶם, כֵּיוָן שֶׁרָאִיתִי שֶׁהֲרֵי בִּרְצוֹן מִצְוַת רִבּוֹנְכֶם נֶאֶמְרוּ הַדְּבָרִים הַלָּלוּ, יָדַעְתִּי שֶׁכָּל הַדְּבָרִים עוֹלִים בְּיוֹם זֶה לְתוֹךְ הַכִּסֵּא הָעֶלְיוֹן וְלוֹקֵחַ אוֹתָם אוֹתוֹ בַּעַל הַפָּנִים וְעוֹשֶׂה מֵהֶם עֲטָרוֹת לַאֲדוֹנוֹ. וְהַיּוֹם הַזֶּה מִתְעַטְּרִים (שבעים) שִׁשִּׁים מֶרְכָּבוֹת קְדוֹשׁוֹת לִכְבוֹד הַכִּסֵּא בְּאוֹתָם דְּבָרִים שֶׁנֶּאֶמְרוּ כָּאן בַּיּוֹם הַזֶּה."],[4,"","בֵּין כָּךְ זָקַף אֶת עֵינָיו וְרָאָה שֶׁהֶעֱרִיב הַשֶּׁמֶשׁ. אָמַר רַבִּי אַבָּא, נֵלֵךְ לַכְּפָר הַזֶּה שֶׁהוּא קָרוֹב לָנוּ בַּמִּדְבָּר. הָלְכוּ וְלָנוּ שָׁם. בַּחֲצוֹת הַלַּיְלָה קָם רַבִּי אַבָּא וּשְׁאָר הַחֲבֵרִים לְהִשְׁתַּדֵּל בַּתּוֹרָה. אָמַר רַבִּי אַבָּא, מִכָּאן וָהָלְאָה נֹאמַר דְּבָרִים לְעַטֵּר בָּהֶם אֶת הַצַּדִּיקִים שֶׁבְּגַן עֵדֶן, שֶׁעַכְשָׁו הוּא הַזְּמַן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא וְכָל הַצַּדִּיקִים שֶׁל עֵדֶן מַקְשִׁיבִים לְקוֹלוֹת הַצַּדִּיקִים שֶׁבָּאָרֶץ."],[5,"","פָּתַח רַבִּי אַבָּא וְאָמַר, כָּתוּב (תהלים קטו) הַשָּׁמַיִם שָׁמַיִם לַה' וְהָאָרֶץ נָתַן לִבְנֵי אָדָם. בַּפָּסוּק הַזֶּה יֵשׁ לְהִתְבּוֹנֵן, וְכָךְ צָרִיךְ לוֹמַר: הַשָּׁמַיִם לַה', וְהָאָרֶץ נָתַן לִבְנֵי אָדָם. מַה זֶּה הַשָּׁמַיִם שָׁמַיִם? אֶלָּא כָּאן יֵשׁ לְהִתְבּוֹנֵן, מִשּׁוּם שֶׁיֵּשׁ שָׁמַיִם וְיֵשׁ שָׁמַיִם. שָׁמַיִם לְמַטָּה, וְאֶרֶץ לְמַטָּה מֵהֶם. שָׁמַיִם לְמַעְלָה, וְאֶרֶץ לְמַטָּה מֵהֶם. וְכָל הַדְּרָגוֹת הָעֶלְיוֹנוֹת וְהַתַּחְתּוֹנוֹת כֻּלָּן כְּמוֹ זֶה, אֵלֶּה בְּאֵלֶּה."],[6,"","שָׁמַיִם לְמַטָּה, הֵם עֶשֶׂר יְרִיעוֹת, כְּמוֹ שֶׁנֶּאֱמַר (שם קד) נוֹטֶה שָׁמַיִם כַּיְרִיעָה. וְהַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה אוֹתָם וְאֶת הַמַּחֲנוֹת שֶׁבְּתוֹכָם לְהַנְהִיג אֶת הָאָרֶץ הַתַּחְתּוֹנָה. הַתְּשִׁיעִי מַנְהִיג אֶת הַתַּחְתּוֹנִים, שֶׁסּוֹבְבִים כַּעֲבוֹתוֹת הָעֲגָלָה. הָעֲשִׂירִי הוּא הָעִקָּר."],[7,"","וּבְכָל הַמַּחֲנוֹת מְמֻנִּים יֵשׁ עַד לַשְּׁבִיעִי. וּמֵהַשְּׁבִיעִי וָהָלְאָה יֵשׁ אוֹר שֶׁהִתְפַּשֵּׁט לְמַטָּה מִתּוֹךְ הַכִּסֵּא הָעֶלְיוֹן, וּמֵאִיר לָעֲשִׂירִי, וְהָעֲשִׂירִי, מֵאוֹתוֹ הָאוֹר שֶׁהוּא לוֹקֵחַ, נוֹתֵן לַתְּשִׁיעִי, וְהוּא לַשְּׁמִינִי וָמַטָּה."],[8,"","הַשְּׁמִינִי הַזֶּה, כְּשֶׁנִּפְקָדִים כֹּחוֹת הַכּוֹכָבִים וּמוֹצִיא אוֹתָם, אוֹתוֹ הָאוֹר עוֹמֵד וְנוֹתֵן כֹּחוֹ לְכָל אֶחָד וְאֶחָד לְהִתְמַנּוֹת בְּאוֹתוֹ מָקוֹם שֶׁצָּרִיךְ, שֶׁכָּתוּב (ישעיה מ) הַמּוֹצִיא בְמִסְפָּר צְבָאָם וְגוֹ'. מֵרֹב אוֹנִים - זֶהוּ הַ הַר שֶׁלְּמַעְלָה שֶׁנִּקְרָא רֹב אוֹנִים."],[9,"","וּבְכָל רָקִיעַ וְרָקִיעַ יֵשׁ מְמֻנֶּה, וְנִפְקָד עַל הָעוֹלָם וְעַל הָאָרֶץ לְהַנְהִיג אֶת הַכֹּל. פְּרָט לְאֶרֶץ יִשְׂרָאֵל, שֶׁלֹּא מַנְהִיג אוֹתָהּ לֹא רָקִיעַ וְלֹא כֹּחַ אַחֵר, אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא לְבַדּוֹ, וַהֲרֵי פֵּרְשׁוּהָ. וְאִם תֹּאמַר, אֵיךְ שָׁרוּי לְחִנָּם רָקִיעַ עַל אֶרֶץ יִשְׂרָאֵל, וַהֲרֵי טַל וּמָטָר יוֹרֵד עָלֶיהָ מֵהָרָקִיעַ כִּשְׁאָר כָּל אֶרֶץ אַחֶרֶת?"]]],[["אֶלָּא, בְכָל רְקִיעָא וּרְקִיעָא אִית מְמָנָן שַׁלְטִין עַל עָלְמָא, וְהַהוּא מְמָנָא דְּשַׁלְטָא עַל הַהוּא רְקִיעָא, יָהִיב מֵחֵילָא דְּאִית לֵיהּ לְהַהוּא רְקִיעָא בְּגִין לְמֵיחָב לְתַתָּא, וְהַהוּא רְקִיעָא נָקִיט מֵהַהוּא מְמָנָא, וְיָהִיב לְתַתָּא לְאַרְעָא. וְהַהוּא מְמָנָא לָא נָקִיט, אֶלָּא מִתַּמְצִית דִּלְעֵילָּא. אֲבָל אַרְעָא קַדִּישָׁא, לָא שַׁלִּיט עַל הַהוּא רְקִיעָא דְּעָלֵיהּ מְמָנָא אַחֲרָא, וְלָא חֵילָא אַחֲרָא, אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי וְאִיהוּ פָּקִיד לְאַרְעָא קַדִּישָׁא בְּהַהוּא רְקִיעָא.","בְּכָל רְקִיעָא וּרְקִיעָא, אִית פִּתְחִין יְדִיעָן, וְשׁוּלְטָנוּ דְּכָל מְמָנָן, מִפִּתְחָא לְפִתְחָא רְשִׁימָא, וּמֵהַהוּא פִּתְחָא וּלְהַלָּן, לָא שַׁלְטָא אֲפִילּוּ כִּמְלֹא נִימָא, וְלָא עָאל דָּא, (אפילו) בִּתְחוּמָא דְּפִתְחָא דְּחַבְרֵיהּ, בַּר כַּד אִתְיְהִיב לֵיהּ רְשׁוּ, לְשַׁלְּטָאָה חַד עַל חַבְרֵיהּ. כְּדֵין, שַׁלְטִין מַלְכִין דִּי בְּאַרְעָא, חַד עַל חַבְרֵיהּ.","בְּאֶמְצָעִיתָא דְּכֻלְּהוּ רְקִיעִין, אִית פִּתְחָא חֲדָא, דְּאִקְרֵי גְּבִילוֹ\"ן, וּתְחוֹת הַאי פִּתְחָא, אִית שִׁבְעִין פִּתְחִין אַחֲרָנִין לְתַתָּא, וְשִׁבְעִין מְמָנִין נַטְרִין, מֵרָחִיק תְּרֵי אַלְפִין אַמִּין, דְּלָא קְרָבִין לְגַבֵּיהּ. וּמֵהַהוּא פִּתְחָא אָרְחָא סָלִיק לְעֵילָּא לְעֵילָּא, עַד דִּי מָטָא לְגוֹ כּוּרְסְיָּיא עִלָּאָה, וּמֵהַהוּא פִּתְחָא לְכָל סִטְרִין דִּרְקִיעָא, עַד תַּרְעָא דְּפִתְחָא דְּאִקְרֵי מַגְדוֹ\"ן, (ס\"א מנדו\"ן) דְּתַּמָּן אִיהוּ סִיּוּמָא דִּרְקִיעָא דִּתְחוּמָא דְּאַרְעָא דְּיִשְׂרָאֵל.","וְכָל אִינּוּן ע' פִּתְחִין, דִּרְשִׁימִין גּוֹ הַהוּא פִּתְחָא דְּאִקְרֵי גְּבִילוֹ\"ן, כֻּלְּהוּ רְשִׁימִין בְּכוּרְסְיָּיא קַדִּישָׁא, וְכֻלְּהוּ קָרִינָן לוֹן שַׁעֲרֵי צֶדֶק, דְּלָא שַׁלִּיט אַחֲרָא עָלַיְיהוּ. וְקוּדְשָׁא בְּרִיךְ הוּא פָּקִיד לְאַרְעָא דְּיִשְׂרָאֵל בְּהַהוּא רְקִיעָא, מִפִּתְחָא לְפִתְחָא, בִּפְקִידוּ כְּמָה דְּאִצְטְרִיךְ. (קמ\"א ע\"א) וּמִתַמְצִיתָא דְּהַהוּא פְּקִידָא, נַטְלִין אִינּוּן שִׁבְעִין מְמָנָן, וְיָהֲבִין לְכֻלְּהוּ מְמָנָן אַחֲרָנִין.","בְּגִנְתָּא דְּעֵדֶן דִּלְתַתָּא, רְקִיעָא דְּקַיְּימָא עָלֵיהּ, אִית בֵּיהּ רָזִין עִלָּאִין, כַּד עֲבַד קוּדְשָׁא בְּרִיךְ הוּא רְקִיעָא אַיְיתֵי אֵשׁ וּמַיִם, מִגּוֹ כּוּרְסֵי יְקָרֵיהּ, וְשִׁתֵּף לוֹן כַּחֲדָא, וְעֲבַד מִנְּהוֹן רְקִיעָא לְתַתָּא, וְאִתְפָּשָׁטוּ עַד דְּמָטוּ לְהַהוּא אֲתָר דְּגִּנְתָּא דְּעֵדֶן, וְיָתְבוּ. מַה עֲבַד קוּדְשָׁא בְּרִיךְ הוּא. נָטַל מִשָּׁמַיִם עִלָּאִין קַדִּישִׁין, אֵשׁ וּמַיִם אַחֲרָנִין דְּמִשְׁתַּכְּחִין וְלָא מִשְׁתַּכְּחִין, דְּאִתְגַּלְּיָין וְלָא אִתְגַּלְּיָין, וּמֵאִינּוּן אֵשׁ וּמַיִם, דְּאִתְנְטָלוּ מִשָּׁמַיִם עִלָּאִין, עֲבַד מִנַּיְיהוּ מְתִיחוּ דִּרְקִיעָא, וּמָתַח לֵיהּ עַל הַאי גִּנְתָּא דִּלְתַתָּא, וּמִתְחַבֵּר גּוֹ רְקִיעָא אַחֲרָא.","אַרְבַּע גַּוְונִין, בְּהַהוּא מְתִיחוּ דִּרְקִיעָא דְּעַל גִּנְתָּא, חִיוָּר וְסוּמָק יָרוֹק וְאוּכָם. לְגַבֵּי הָנֵי גַּוְונִין, אִית אַרְבַּע פִּתְחִין, לְתַתָּא מֵהַהוּא מְתִיחוּ דִּרְקִיעָא. וְאִינּוּן פְּתִחִין לְאַרְבַּע סִטְרִין דִּרְקִיעָא דְּעַל גַּבֵּי גִּנְתָּא. מֵאִינּוּן אֵשׁ וּמַיִם, דְּאִתְעָבִיד מִנְּהוֹן הַהוּא רְקִיעָא. מִתְפַּתְּחִין בְּאַרְבַּע פִּתְחִין, אַרְבַּע נְהוֹרִין.","לִסְטַר יְמִינָא בְּהַהוּא פִּתְחָא, מִגּוֹ מְתִיחוּ דִּסְטָר (נ\"א מיא) יְמִינָא, נַהֲרִין תְּרֵין נְהוֹרִין, בְּאִינּוּן תְּרֵין פִּתְחִין, בְּפִתְחָא דִּימִינָא, וּבְפִתְחָא דְּאִיהוּ (נ\"א לגו נפקא נהורא ואיהו אנפין) לָקֳבֵל אַנְפִּין.","גּוֹ נְהוֹרָא דְּנָהִיר לִסְטַר יְמִינָא, אִתְרְשִׁים אָת חַד, נָהִיר וּבָלִיט, (נ\"א ולהיט) וְנָצִיץ בִּנְצִיצוּ, מִגּוֹ הַהוּא נְהוֹרָא, וְאִיהוּ אָת מ', וְקַיְּימָא בְּאֶמְצָעִיתָא דְּהַהוּא נְהוֹרָא דְּפִתְחָא. אָת דָּא, סַלְּקָא וְנַחְתָּא, וְלָא קָאִים בַּאֲתָר חַד. הַהוּא נְהוֹרָא, נָטִיל לְהַהוּא אָת וְאַפִּיק לָהּ, בְּגִין כָּךְ לָא קַיְּימָא בַּאֲתָר חַד.","גּוֹ נְהוֹרָא דְּנָהִיר בְּסִטְרָא דְּאִיהוּ לָקֳבֵל אַנְפִּין, אִתְרְשִׁים אָת חַד, דְּנָהִיר וּבָלִיט וְנָצִיץ בִּנְצִיצוּ גּוֹ הַהוּא נְהוֹרָא, וְאִיהִי אָת ר', וּלְזִמְנִין אִתְחָזֵי ב' (נ\"א ד') וְקַיְּימָא בְּאֶמְצָעִיתָא דְּהַהוּא נְהוֹרָא דְּפִתְחָא. וְסַלְּקָא וְנַחְתָּא, לְזִמְנִין אִתְגַּלְיָא, וּלְזִמְנִין לָא אִתְגַּלְיָא, וְלָא קַיְּימָא בַּאֲתָר חַד. אִלֵּין תְּרֵין אַתְוָון קַיְימִין, וְכַד נִשְׁמְתָא דְּצַדִּיקַיָּא עָאלַת בְּגִנְתָּא דְּעֵדֶן, אִלֵּין תְּרֵין אַתְוָון נָפְקִין מִגּוֹ הַהוּא נְהוֹרָא, וְקַיְימִין עַל הַהִיא נִשְׁמְתָא, וְסַלְקֵי וְנַחְתֵּי.","כְּדֵין, מֵאִינּוּן תְּרֵין פִּתְחִין, מְקַדְּמֵי וְנַחְתֵּי מֵעֵילָּא, תְּרֵין רְתִיכִין. רְתִיכָא חֲדָא עִלָּאָה, דְּאִיהִי רְתִיכָא דְּמִיכָאֵל, רַב סְגָנִין. רְתִיכָא תִּנְיָינָא, דְּאִיהִי רְתִיכָא מֵהַהוּא רַב מְמָנָא, דְּאִקְרֵי בּוֹאֵ\"ל. וְדָא אִיהוּ שָׁמָשָׁא יַקִּירָא דְּאִקְרֵי רְפָאֵ\"ל. וְאִינּוּן נַחְתִּין וְקַיְימִין עַל נִשְׁמְתָא, (מ\"ז ע\"א) אַמְרִין לָהּ שָׁלוֹם בּוֹאֶךְ. (ישעיהו נ״ז:ב׳) יָבֹא שָׁלוֹם יָבֹא שָׁלוֹם. כְּדֵין אִינּוּן תְּרֵין אַתְוָון, סַלְּקִין וְקַיְימִין בְּאַתְרַיְיהוּ, וְאִתְגְּנִיזוּ גּוֹ הַהוּא נְהוֹרָא, דְּאִינּוּן פִּתְחִין."],[[0,"אלא בכל רקיע וכו':","ומשיב, אלא בכל רקיע ורקיע יש ממונים השולטים על העולם, ואותו הממונה השולט על רקיע ההוא נותן מן הכח שיש לו, אל רקיע ההוא ורקיע ההוא מקבל מאותו הממונה ונותן למטה לארץ. ואותו הממונה אינו מקבל אלא מתמצית האור שלמעלה. כי עמי העולם אינם נזונים אלא מתמצית. אבל ארץ הקדושה, אינו שולט ברקיע שעליה ממונה אחר, ולא כח אחר, אלא הקב\"ה בלבדו, והוא פוקד את ארץ הקדושה ברקיע ההוא שעליה."],[1,"בכל רקיעא ורקיעא וכו':","בכל רקיע ורקיע יש פתחים ידועים, והממשלה של כל ממונה רשומה מפתח לפתח, ומפתח הזו ולהלאה אינו שולט אפילו כמלא השערה, ואין זה נכנס בתחומו של פתח חבירו, חוץ כשניתנה לו רשות לשלוט אחד על חבירו, ואז גם המלכים בארץ שולטים אחד על חבירו. דהיינו המלכים בארץ המיוחסים לרקיעים וממונים האלו."],[2,"באמצעיתא דכלהו וכו':","באמצע כל הרקיעים, שהוא על ארץ ישראל שהיא באמצע העולם, יש פתח אחד הנקרא גבילון, ותחת פתח הזה יש ע' פתחים אחרים למטה, וע' ממונים שומרים מרחוק ב' אלפים אמה, שה\"ס תחום שבת, מפתח הנקרא גבילון, שאינם קרבים אליו. ומפתח הזה עולה דרך למעלה למעלה, עד שמגיע לכסא העליון, שהוא מלכות, ומפתח ההוא מתפשט שליטתו לכל צדדי הרקיע עד שער הפתח שנקרא מגדון, ששם הוא סיום הרקיע של ארץ ישראל. (וביאור הדברים עי' להלן בהסולם אות רצ\"ט בסופו, בד\"ה וכן מתבאר)."],[3,"וכל אינון ע' וכו':","וכל אלו ע' פתחים הרשומים בפתח ההוא שנקרא גבילון, כולם, רשומים בכסא הקדוש, שהוא המלכות, וכולם, קוראים אותם שערי צדק. על שם המלכות הנקראת צדק, כי אחר אינו שולט עליהם. והקב\"ה פוקד את ארץ ישראל ברקיע ההוא מפתח לפתח, דהיינו מפתח הנקרא גבילון, עד הפתח הנקרא מגדון. בפקידה כמו שצריך, דהיינו בהשפעה מלאה ככל הצורך, ומתמצית פקידה ההיא, לוקחים אלו ע' ממונים הנ\"ל, ונותנים לכל ממונים האחרים שעל עמי העולם."],[4,"בגנתא דעדן דלתתא וכו':","בגן עדן שלמטה, דהיינו ג\"ע הארץ, הרקיע העומד עליו יש בו סודות עליונים. כשעשה הקב\"ה את הרקיע, הביא אש ומים מכסא הכבוד, שהוא עולם הבריאה, וחברם יחד, ועשה מהם רקיע למטה. על הארץ שלנו. ונתפשטו עד שהגיעו למקום ההוא של גן עדן, וישבו. כלומר, שלא נתפשטו יותר. מה עשה הקב\"ה, לקח משמים עליונים הקדושים, שהם חו\"ב דז\"א הנקרא שמים דאצילות, אש ומים אחרים, הנמצאים ואינם נמצאים המתגלים ואינם מתגלים, ומאלו אש ומים שנלקחו משמים העליונים עשה מהם התפשטות הרקיע, ופרש אותם על גן עדן שלמטה, והרקיע הזה שהוא דעת, מתחבר עם הרקיע האחר. שעל הארץ שלנו, שהוא ת\"ת."],[4,"","ביאור המאמר. תחלה צריך שתבין, מה שלפעמים אנו מבארים, שהרקיע הוא סיום החדש שנעשה בכל מדרגה, מחמת עלית המלכות לבינה דכל מדרגה. ופעמים אנו אומרים, שקו האמצעי נקרא רקיע, שהוא השמים דהיינו ת\"ת. והענין הוא, כי הסיום החדש נעשה בסוד נקודת החולם, ששם עלתה המלכות לבינה. אמנם עם יציאת נקודת השורק, שהוא קו שמאל, נעשה מחלוקת, שרצה לבטל לגמרי הסיום הזה ולהאיר ממעלה למטה. עד שבא קו אמצעי והכריע שהשמאל יאיר רק ממטה למעלה, והסיום החדש לא יתבטל, שאז הוכרחו הבינה ותו\"מ שהיו למטה מסיום החדש, לעלות למעלה מסיום החדש ולהתחבר למדרגתם (כנ\"ל באות קל\"א בהסולם בז\"ה וזהו שאומר באות קכ\"ג) הרי שקו האמצעי עשה הסיום החדש הזה שנעשה בנקודת החולם, שיהיה קבוע וקיים תמיד. (כמ\"ש שם באורך) ונמצא שסיום החדש נעשה לקביעות בקו אמצעי, שהוא מסך דחירק. וע\"כ אנו קוראים פעם את הרקיע בשם סיום החדש דצמצום ב', ופעם בשם קו אמצעי."],[4,"","וזהו שאומר לעיל (אות רפ\"ג) \u0003שמים לתתא וארץ לתתא מנייהו, שמים לעילא וארץ לתתא מנייהו.\u0004 שכמו שיש שמים וארץ באצילות, שקו האמצעי, שנקרא ז\"א, הכולל חג\"ת נה\"י, נקרא שמים דאצילות, ומתחתיו הוא המלכות הכוללת, הנקראת ארץ. כן יש בעולם העשיה שמים וארץ, שהשמים ה\"ס קו אמצעי הכולל חג\"ת נה\"י, ומתחתיו הוא המלכות דעשיה הנקראת ארץ."],[4,"","וז\"ש (באות רפ\"ד) \u0003שמים לתתא אינון עשר יריעות.\u0004 כי אלו חג\"ת נה\"י שבקו האמצעי, כוללים עשר ספירות, כי החסד כולל כח\"ב, והיסוד שבו כולל מלכות דהיינו עטרת יסוד, והם עשר יריעות בסו\"ה נוטה שמים כיריעה. אמנם המלכות שבו שה\"ס עטרה אינה מלכות האמיתית, אלא שכלולה ביסוד, וע\"כ אנו חושבים אותם רק לתשעה רקיעים. והמלכות הוא הארץ שמתחת הרקיע לגמרי, שהוא העשירית."],[4,"","וכמו שהשמים דעשיה כולל עשר רקיעים כן הארץ דעשיה כוללת י' ספירות, שה\"ס ז' ארצות והעליונה שבהם הוא בינה הכוללת ג\"ר, והיא הארץ שאנו יושבים עליה. אמנם גם בינה זו דארצות דעשיה שאנו יושבים עליה, נחלקת לע\"ס, ואנו יושבים רק בז\"ת דבינה זו, שארץ ישראל היא יסוד שבהן והבינה דבינה הזו הכוללת ג\"ר, ה\"ס גן עדן הארץ."],[4,"","והנה נתבאר שכל עשר יריעות דשמים דעשיה, הם ע\"ס דת\"ת הכולל חג\"ת נה\"י. ויש לשאול לפי\"ז, מאין יצא קו האמצעי הזה, הלא קו האמצעי הוא תולדה מהכרעת ב' קוין ימין ושמאל שבבינה שה\"ס אש ומים, בסוד תלת נפקי מחד חד בתלת קיימא (לעיל ב\"א דף רפ\"ז ד\"ה תלת עש\"ה) ומאיזה בינה יצא קו האמצעי דעשיה, בעת שבינה אמיתית אינה לא בעשיה ולא ביצירה."],[4,"","וז\"ש (באות רצ\"ב) \u0003כד עבד קב\"ה רקיעא אייתי אש ומים מגו כורסי יקריה, ושתף לון כחדא ועבד מנהון רקיעא לתתא.\u0004 כלומר שמאש ומים שבבינה דעולם הבריאה הנקראת כסא הכבוד שקו האמצעי שתף וחבר אותם יחד, בסוד תלת נפקי מחד יצא מהם הרקיע למטה, שה\"ס עשרה רקיעים דעשיה, בסוד חד בתלת קיימא. ומבריאה נמשך לעולם עשיה. והוא מטעם, כי למטה מעולם הבריאה, אין קומת בינה שקו אמצעי יחבר ב' קוין שבה."],[4,"","אמנם קומת בינה שיש בעולם הבריאה נבחנת רק לחצוניות הבינה, אשר קו האמצעי היוצא ממנו אינו בחינת דעת, אלא בחינת ת\"ת, שה\"ס ז\"ס תחתונות, וזה מספיק להיות רקיעים על ז\"ת דארץ דעשיה, וגם על ארץ שאנו יושבים עליה שהיא ז\"ת דבינה דארץ דעשיה, אבל גן העדן שהוא בינה דבינה דארץ דעשיה, שקו אמצעי שלה צריך להיות בחינת דעת דהיינו קו אמצעי דג\"ר ממש, ואיך יספיק לזה קו אמצעי היוצא מאש ומים דבינה דבריאה, שהיא רק בחי' חיצוניות דהיינו ת\"ת."],[4,"","וז\"ש, \u0003ואתפשטו עד דמטו לההוא אתר דגנתא דעדן, ויתבו.\u0004 כי מתוך שהרקיעים ההם נמשכו מאש ומים דבינה דבריאה, שהם חצוניות ובחינת ת\"ת הכולל עשר יריעות, ואם כן איך יוכלו לחופף על גן עדן, שהוא בינה דבינה דארץ דעשיה, שקו האמצעי החופף עליו, צריך להיות קו אמצעי דג\"ר ממש, שהוא דעת. וע\"כ כיון שהגיעו לגן עדן הארץ, ישבו, ולא יכלו להתפשט על הג\"ע. ואע\"פ שגם הארץ שלנו היא מבחינת בינה דארץ דעשיה, אמנם הם רק מז\"ת דבינה זו, שהם ג\"כ רק חצוניות הבינה, וע\"כ מספיק להם קו האמצעי דאש ומים דבריאה. משא\"כ הג\"ע, שהיא הבינה של הבינה הזאת, שהוא ג\"ר ממש, צריכים לקו אמצעי מג\"ר ממש."],[4,"","וז\"ש, \u0003מה עבד קב\"ה, נטל משמים עלאין קדשין אש ומים אחרנין וכו':\u0004 דהיינו שלקח מקו האמצעי המכריע בין חו\"ב, דז\"א הנקרא שמים, שהוא קו האמצעי דג\"ר דז\"א הנקרא דעת, ומדעת הזה נתפשט הרקיע שעל גן העדן הארץ. וז\"ש \u0003עבד מנייהו מתיחו דרקיעא,\u0004 דהיינו הכרעה בין אש ומים שהוא קו אמצעי הנקרא רקיע, וה\"ס דעת כנ\"ל, \u0003ומתח ליה על גנתא דלתתא.\u0004 שהיא בינה דבינה דארץ דעשיה, \u0003ומתחבר גו רקיעא אחרא,\u0004 דהיינו כטבע הדעת המתחבר ומתפשט לחג\"ת נה\"י שהם ת\"ת, כן נתחבר רקיע הזה שהוא דעת עם שאר הרקיעים דעשיה שהם ת\"ת, כנ\"ל."],[4,"","ומה שאמר \u0003דמשתכחין ולא משתכחין, דאתגליין ולא אתגליין,\u0004 בא ללמד, שאש ומים אלו, שהם הו\"ב דז\"א, אינם דאו\"א עלאין דז\"א, שהם אינם נמצאים בהשגה כלל, שבהם אין מתגלה חכמה, (כנ\"ל ב\"א רנ\"א ד\"ה נחית) אלא שהם חו\"ב דישסו\"ת דז\"א, שבהם מתגלה החכמה בסוד הדעת, והם נמצאים בהשגה. אמנם לא במקומם בז\"א, אלא אחר שמתפשטים למלכות. וז\"ש, \u0003דמשתכחין ולא משתכחין דאתגליין ולא אתגליין,\u0004 שמצד אחד יצא בהם הי' מאויר ומתגלה החכמה בהם ונמצאים משום זה בהשגה. ומצד אחר, \u0003לא משתכחין ולא אתגליין,\u0004 שהרי במקום ז\"א אינם נמצאים בהשגה, אלא אחר התפשטותם למלכות, ששם מקום גילוי החכמה. (כנ\"ל ב\"א דף רע\"ו ד\"ה ועוד)."],[5,"ארבע גוונין בההוא וכו':","ארבעה צבעים בהתפשטות הרקיע ההוא שעל הגן, שהם לבן אדום ירוק ושחור. שהם ג' קוין ימין שמאל אמצע, שהם לבן אדום ירוק, ושחור הוא המלכות המקבלת ג' הקוין האלו, אצל אלו הגוונים יש ד' פתחים למטה מהתפשטות הרקיע. והם פתוחים לד' צדדי הרקיע שעל הגן. שדרום צפון הם חסד וגבורה, ומזרח ומערב הם ת\"ת ומלכות. מאלו אש ומים שהרקיע נעשה מהם, שהם חו\"ב דז\"א, כנ\"ל, נפתחים בארבע פתחים האלו, ד' אורות."],[6,"לסטר ימינא בההוא","וכו': לצד ימין בפתח ההוא, מתוך התפשטות צד המים שברקיע, שנעשה מאש ומים, דהיינו מאור החסדים, מאירים ב' אורות בב' פתחים, דהיינו בפתח שבימין שבצד דרום שהוא חסד, ובפתח שהוא כנגד הפנים, דהיינו בצד מזרח שהוא ת\"ת. כי מזרח מערב מכונים פנים ואחור. ואור החסדים מאיר גם בת\"ת כנודע."],[7,"גו נהורא דנהיר וכו':","בתוך האור המאיר לצד ימין, נרשמת אות אחת מאירה ובולטת ומתנוצצת בהתנוצצות מתוך האור הזה, והיא אות \u0003מ'\u0004 שה\"ס אות הראשונה של \u0003מ\u0004 יכאל ועומדת באמצע אור ההוא שבפתח. אות הזו עולה ויורדת ואינה עומדת במקום אחד, אור ההוא שבצד ימין, לוקח אות ההוא ומוציאה, וע\"כ אינה עומדת במקום אחד. שה\"ס והחיות רצוא ושוב, שאינן עומדות במקום אחד."],[8,"גו נהורא דנהיר וכו':","בתוך האור המאיר באותו צד שהוא כנגד הפנים, דהיינו צד מזרח, שהוא ת\"ת, נרשמת אות אחת המאירה ובולטת ומתנוצצת בהתנוצצות בתוך אור ההוא, והוא אות \u0003ר',\u0004 שהיא אות ראשונה של המלאך \u0003ר\u0004 פאל. ולפעמים נראה \u0003ב',\u0004 שהיא אות ראשונה של המלאך \u0003ב\u0004 ואל, (כמ\"ש לעיל תרומה אוה שפ\"ח) ועומדת באמצע אור ההוא של הפתח. ועולה ויורדת, לפעמים מתגלה ולפעמים אינה מתגלה. ואינה עומדת במקום אחד. שה\"ס והחיות רצוא ושוב, אלו ב' אותיות עומדות, באמצע אור ב' הפתחים, וכשנשמות הצדיקים באות לגן עדן, אלו ב' אותיות יוצאות מתוך אור ההוא ועומדות על נשמה ההיא. ועולות ויורדות. בסוד רצוא ושוב. ומה שמכנה המזרח בשם רפאל, בהיפך ממ\"ש בכמה מקומות שאוריאל הוא במזרח. עי' להלן (פקודי רנ\"ד ע\"א ד\"י)."],[9,"כדין מאינון תרין וכו':","אז מאלו ב' פתחים מקדימים ויורדים מלמעלה ב' מרכבות. מרכבה אחת עליונה, היא מרכבה של \u0003מיכאל\u0004 רב הסגנים, מרכבה השניה היא מרכבה של ממונה העליון ההוא שנקרא \u0003בואל,\u0004 וזה הוא משמש היקר שנקרא \u0003רפאל,\u0004 ואלו יורדים ועומדים על הנשמה, ואומרים לה שלום בואך. יבא שלום יבא שלום. אז אלו ב' אותיות עולות ועומדות במקומן ונגנזות תוך אור ההוא של הפתחים."]],[[0,"","אֶלָּא בְּכָל רָקִיעַ וְרָקִיעַ יֵשׁ מְמֻנִּים שֶׁשּׁוֹלְטִים עַל הָעוֹלָם, וְאוֹתוֹ מְמֻנֶּה שֶׁשּׁוֹלֵט עַל אוֹתוֹ רָקִיעַ נוֹתֵן מִן הַכֹּחַ שֶׁיֵּשׁ לוֹ לְאוֹתוֹ רָקִיעַ, (כדי לתת למטה) וְאוֹתוֹ רָקִיעַ לוֹקֵחַ מֵאוֹתוֹ מְמֻנֶּה, וְנוֹתֵן לְמַטָּה לָאָרֶץ. וְאוֹתוֹ הַמְמֻנֶּה אֵינוֹ לוֹקֵחַ אֶלָּא מֵהַתַּמְצִית שֶׁלְּמַעְלָה. אֲבָל הָאָרֶץ הַקְּדוֹשָׁה אֵין שׁוֹלֵט עַל אוֹתוֹ הָרָקִיעַ שֶׁעָלֶיהָ מְמֻנֶּה אַחֵר, וְלֹא כֹּחַ אַחֵר, אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא לְבַדּוֹ, וְהוּא פּוֹקֵד אֶת הָאָרֶץ הַקְּדוֹשָׁה בְּאוֹתוֹ רָקִיעַ."],[1,"","בְּכָל רָקִיעַ וְרָקִיעַ יֵשׁ פְּתָחִים יְדוּעִים וְשִׁלְטוֹן כָּל הַמְמֻנִּים מִפֶּתַח לְפֶתַח רָשׁוּם, וּמֵאוֹתוֹ פֶּתַח וָהָלְאָה לֹא שׁוֹלֵט אֲפִלּוּ כִּמְלֹא נִימָה, וְלֹא נִכְנָס זֶה (אפלו) לִתְחוּם פֶּתַח חֲבֵרוֹ פְּרָט לִכְשֶׁנִּתֶּנֶת לוֹ רְשׁוּת לִשְׁלֹט אֶחָד עַל חֲבֵרוֹ, וְאָז שׁוֹלְטִים הַמְּלָכִים שֶׁבָּאָרֶץ אֶחָד עַל חֲבֵרוֹ."],[2,"","בְּאֶמְצַע כָּל הָרְקִיעִים יֵשׁ פֶּתַח אֶחָד שֶׁנִּקְרָא גְּבִילוֹ\"ן, וְתַחַת הַפֶּתַח הַזֶּה יֵשׁ שִׁבְעִים פְּתָחִים אֲחֵרִים לְמַטָּה, וְשִׁבְעִים מְמֻנִּים שׁוֹמְרִים מֵרָחוֹק שֶׁל אַלְפַּיִם אַמָּה שֶׁלֹּא קְרֵבִים אֵלָיו. וּמֵאוֹתוֹ פֶּתַח עוֹלָה דֶּרֶךְ לְמַעְלָה לְמַעְלָה, עַד שֶׁמַּגִּיעָה לַכִּסֵּא הָעֶלְיוֹן, וּמֵאוֹתוֹ הַפֶּתַח לְכָל הַצְּדָדִים שֶׁבָּרָקִיעַ, עַד שַׁעַר הַפֶּתַח שֶׁנִּקְרָא מַגְדוֹ\"ן (מנדו\"ן), שֶׁשָּׁם הוּא סִיּוּם הָרָקִיעַ שֶׁל תְּחוּמָהּ שֶׁל אֶרֶץ יִשְׂרָאֵל."],[3,"","וְכָל אוֹתָם שִׁבְעִים פְּתָחִים שֶׁרְשׁוּמִים בְּתוֹךְ אוֹתוֹ פֶּתַח שֶׁנִּקְרָא גְּבִילוֹ\"ן, כֻּלָּם רְשׁוּמִים בַּכִּסֵּא הַקָּדוֹשׁ, וּלְכֻלָּם קוֹרְאִים שַׁעֲרֵי צֶדֶק, שֶׁלֹּא שׁוֹלֵט אַחֵר עֲלֵיהֶם. וְהַקָּדוֹשׁ בָּרוּךְ הוּא פּוֹקֵד אֶת הָאָרֶץ הַקְּדוֹשָׁה בְּאוֹתוֹ רָקִיעַ, מִפֶּתַח לְפֶתַח בִּפְקִידָה כְּמוֹ שֶׁצָּרִיךְ. וּמִתַּמְצִית אוֹתָהּ פְּקִידָה מְקַבְּלִים אוֹתָם שִׁבְעִים מְמֻנִּים, וְנוֹתְנִים לְכָל הַמְמֻנִּים הָאֲחֵרִים."],[4,"","בְּגַן עֵדֶן שֶׁלְּמַטָּה, בָּרָקִיעַ שֶׁעוֹמֵד עָלָיו, יֵשׁ בּוֹ סוֹד עֶלְיוֹנִים. כְּשֶׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָרָקִיעַ, הֵבִיא אֵשׁ וּמַיִם מִתּוֹךְ כִּסֵּא כְבוֹדוֹ וְשִׁתְּפָם כְּאֶחָד, וְעָשָׂה מֵהֶם רָקִיעַ לְמַטָּה, וְהִתְפַּשְּׁטוּ עַד שֶׁהִגִּיעוּ לְאוֹתוֹ מָקוֹם שֶׁל גַּן עֵדֶן וְיָשְׁבוּ. מֶה עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא? לָקַח מֵהַשָּׁמַיִם הָעֶלְיוֹנִים הַקְּדוֹשִׁים אֵשׁ וּמַיִם אֲחֵרִים שֶׁנִּמְצָאִים וְלֹא נִמְצָאִים, שֶׁנִּגְלִים וְלֹא נִגְלִים, וּמֵאוֹתָם אֵשׁ וּמַים שֶׁנִּטְּלוּ מֵהַשָּׁמַיִם הָעֶלְיוֹנִים, עָשָׂה מֵהֶם מְתִיחַת הָרָקִיעַ, וּמָתַח אוֹתוֹ עַל הַגָּן הַזֶּה שֶׁלְּמַטָּה, וּמִתְחַבֵּר לְתוֹךְ רָקִיעַ אַחֵר."],[5,"","אַרְבָּעָה גְוָנִים בְּאוֹתָהּ מְתִיחַת הָרָקִיעַ שֶׁעַל הַגָּן - לָבָן אָדם יָרֹק וְשָׁחֹר. לַגְּוָנִים הַלָּלוּ יֵשׁ אַרְבָּעָה פְתָחִים מִתַּחַת לְאוֹתָהּ מְתִיחַת הָרָקִיעַ, וְאוֹתָם הַפְּתָחִים לְאַרְבַּעַת צִדְדֵי הָרָקִיעַ שֶׁעַל גַּבֵּי הַגָּן. וּמֵאוֹתָם אֵשׁ מַיִם שֶׁנַּעֲשָׂה מֵהֶם אוֹתוֹ רָקִיעַ, נִפְתָּחִים בְּאַרְבָּעָה פְתָחִים אַרְבָּעָה אוֹרוֹת."],[6,"","לְצַד יָמִין בְּאוֹתוֹ פֶּתַח מִתּוֹךְ מְתִיחַת צַד (המים) הַיָּמִין מְאִירִים שְׁנֵי אוֹרוֹת בְּאוֹתָם שְׁנֵי פְּתָחִים, בְּפֶתַח הַיָּמִין, וּבַפֶּתַח שֶׁהוּא (בפניםיוצאאור, והוא פנים) כְּנֶגֶד הַפָּנִים."],[7,"","בְּתוֹךָ הָאוֹר הַמֵּאִיר לְצַד יָמִין רְשׁוּמָה אוֹת אַחַת מְאִירָה וּבוֹלֶטֶת (ולוהטת) וְנוֹצֶצֶת בְּהִתְנוֹצְצוּת מִתּוֹךְ אוֹתוֹ הָאוֹר, וְהִיא הָאוֹת מ', וְעוֹמֶדֶת בְּאֶמְצַע אוֹתוֹ הָאוֹר שֶׁל הַפֶּתַח. הָאוֹת הַזּוֹ עוֹלָה וְיוֹרֶדֶת, וְלֹא עוֹמֶדֶת בְּמָקוֹם אֶחָד. אוֹתוֹ הָאוֹר לוֹקֵחַ אוֹתָהּ אוֹת וּמוֹצִיא אוֹתָהּ, וּמִשּׁוּם כָּךְ אֵינָהּ עוֹמֶדֶת בְּמָקוֹם אֶחָד."],[8,"","בְּתוֹךָ הָאוֹר הַמֵּאִיר בַּצַּד שֶׁהוּא כְּנֶגֶד הַפָּנִים, רְשׁוּמָה אוֹת אַחַת שֶׁמְּאִירָה וּבוֹלֶטֶת וְנוֹצֶצֶת בְּהִתְנוֹצְצוּת בְּתוֹךְ אוֹתוֹ הָאוֹר, וְהִיא הָאוֹת ר', וְלִפְעָמִים נִרְאֵית ב' (ד'), וְעוֹמֶדֶת בְּאֶמְצַע אוֹתוֹ הָאוֹר שֶׁבַּפֶּתַח, וְעוֹלָה וְיוֹרֶדֶת, לִפְעָמִים גְּלוּיָה וְלִפְעָמִים לֹא גְלוּיָה, וְלֹא עוֹמֶדֶת בְּמָקוֹם אֶחָד. שְׁתֵּי הָאוֹתִיּוֹת הַלָּלוּ עוֹמְדוֹת, וּכְשֶׁנִּשְׁמוֹת הַצַּדִּיקִים נִכְנָסוֹת לְגַן עֵדֶן, שְׁתֵּי הָאוֹתִיּוֹת הַלָּלוּ יוֹצְאוֹת מִתּוֹךְ אוֹתוֹ הָאוֹר, וְעוֹמְדוֹת עַל אוֹתָהּ נְשָׁמָה, וְעוֹלִים וְיוֹרְדִים."],[9,"","וְאָז, מֵאוֹתָם שְׁנֵי הַפְּתָחִים, מַקְדִּימִים וְיוֹרְדִים מִלְמַעְלָה שְׁתֵּי מֶרְכָּבוֹת. מֶרְכָּבָה עֶלְיוֹנָה אַחַת, שֶׁהִיא מֶרְכַּבְתּוֹ שֶׁל מִיכָאֵל, גְּדוֹל הַסְּגָנִים. הַמֶּרְכָּבָה הַשְּׁנִיָּה, שֶׁהִיא מֶרְכַּבְתּוֹ שֶׁל אוֹתוֹ מְמֻנֶּה גָדוֹל שֶׁנִּקְרָא בּוֹאֵ\"ל. וְזֶה שַׁמָּשׁ נִכְבָּד שֶׁנִּקְרָא רְפָאֵ\"ל. וְהֵם יוֹרְדִים וְעוֹמְדִים עַל הַנְּשָׁמָה, אוֹמְרִים לָהּ: שָׁלוֹם בּוֹאֵךְ, יָבֹא שָׁלוֹם יָבֹא שָׁלוֹם. וְאָז אוֹתָן שְׁתֵּי הָאוֹתִיּוֹת עוֹלוֹת וְעוֹמְדוֹת בִּמְקוֹמָן, וְנִגְנָזוֹת לְתוֹךְ אוֹתוֹ הָאוֹר שֶׁל אוֹתָם פְּתָחִים."]]],[["תְּרֵין פִּתְחִין אַחֲרָנִין, תְּרֵין נְהוֹרִין אַחֲרָנִין קָא מְלַהֲטִין, מִנְהִירוּ דְּאֶשָּׁא, בְּאִינּוּן פִּתְחִין חַד לִסְטַר שְׂמָאלָא, וְחַד לַאֲחוֹרָא. תְּרֵין אַתְוָון אַחֲרָנִין, מְלַהֲטִין בְּאִינּוּן נְהוֹרִין, וּנְצִיצִין בְּגַּוַּויְיהוּ, אָת חַד ג', וְאָת חַד נ', וְכַד אַתְוָון קַדְמָאֵי מִתְהַדְּרָן לְאַתְרַיְיהוּ, אִלֵּין תְּרֵין אַחֲרָנִין נִצוֹצִין, סַלְּקִין וְנַחְתִּין, נָפְקִין מֵאִינּוּן נְהוֹרִין, וְקַיְימִין עַל נִשְׁמְתָא.","כְּדֵין נַחְתִּין תְּרֵין רְתִיכִין, מֵאִינּוּן תְּרֵין פִּתְחִין. רְתִיכָא חֲדָא אִיהוּ רְתִיכָא דְּגַבְרִיאֵל, רַב מְמָנָא וְיַקִּירָא. רְתִיכָא תִּנְיָינָא, אִיהִי רְתִיכָא אַחֲרָא קַדִּישָׁא דְּנוּרִיאֵ\"ל רַב מְמָנָא, וְנַחְתִּין מֵאִינּוּן פִּתְחִין, וְקַיְימִין עַל נִשְׁמְתָא, וְאַתְוָון מִתְהַדְּרָן לְאַתְרַיְיהוּ.","כְּדֵין, אִלֵּין תְּרֵין רְתִיכִין, עָאלִין לְגוֹ הֵיכָלָא חֲדָא טְמִירָא דְּגִּנְתָּא, דְּאִקְרֵי אֲהָלוֹ\"ת, וְתַמָּן (קל\"ב ע\"א) תְּרִיסָר זִינֵי בּוּסְמִין גְּנִיזִין, דִּכְתִּיב, (שיר השירים ד׳:י״ד) נִרְדְּ וְכַרְכֹּם קָנֶה וְקִנָּמוֹן וְגוֹ'. וְאִינּוּן תְּרֵיסָר זִינֵי דְּבוּסְמִין דִּלְתַתָּא.","וְתַמָּן כָּל אִינּוּן לְבוּשִׁין דְּנִשְׁמָתִין, דְּאִתְחָזוּן לְאִתְלַבְּשָׁא בְּהוּ, כָּל חַד וְחַד, כַּדְקָא חֲזֵי. בְּהַהוּא לְבוּשָׁא, אִתְרְשִׁימוּ כָּל אִינּוּן עוֹבָדִין טָבִין, דְּעֲבַד בְּהַאי עָלְמָא. וְכֻלְּהוּ רְשִׁימִין בֵּיהּ, וּמַכְרִיזֵי הַאי אִיהוּ לְבוּשָׁא דִּפְלַנְיָא, וְנַטְלִין לְהַהוּא לְבוּשָׁא וְאִתְלַבְּשַׁת בֵּיהּ הַהִיא נִשְׁמְתָא דְּצַדִּיקַיָּא (ויחי רכ\"ד ע\"ב) דִּבְגִנְתָּא, כְּגַוְונָא דְּדִיּוּקְנָא דְּהַאי עָלְמָא.","וְהָנֵי מִילֵי, מִתְּלָתִין יוֹמִין וְאֵילָךְ, דְּהָא כָּל תְּלָתִין יוֹמִין, לֵית לָךְ נִשְׁמְתָא דְּלָא תְּקַבֵּל עוֹנְשָׁא, עַד לָא תֵּיעוּל לְגִנְתָּא דְּעֵדֶן. כֵּיוָן דְּקַבִּילַת עוֹנְשָׁא, עָאלַת לְגִנְתָּא דְּעֵדֶן, כְּמָה דְּאוּקְמוּהָ. לְבָתַר דְּאִתְלַבְּנַת, אִתְלַבְּשַׁת כֵּיוָן דְּאִתְלַבְּשַׁת בְּהַאי לְבוּשָׁא, יַהֲבִין לָהּ אֲתָר כְּמָה דְּאִתְחָזֵי לָהּ. כְּדֵין, כָּל אִינּוּן אַתְוָון, נַחְתִּין, וְסַלְּקִין אִינּוּן רְתִיכִין.","הַהוּא רְקִיעָא אָהֲדַּר תְּרֵין זִמְנִין בְּכָל יוֹמָא, בְּהַהוּא נְטִילוּ דְּהַאי רְקִיעָ אַחֲרָא, דְּמִתְדָּבַק בֵּיהּ. וְהַאי רְקִיעָא לָא נָפִיק לְבַר מִגִּנְתָּא. רְקִיעָא דָּא, מְרֻקְּמָא בְּכָל זִינֵי גַּוְונִין.","תְּרֵין וְעֶשְׂרִין אַתְוָון רְשִׁימִין מְחַקְּקָן, בְּהַהוּא רְקִיעָא, כָּל אָת וְאָת, נָטִיף מִמָנָא (ס\"א מטלא), מִטַּלָּא דִּלְעֵילָּא עַל גִּנְתָּא. וּמֵהַהוּא טַלָּא דְּאַתְוָון אִתְסַחְיָין אִינּוּן נִשְׁמָתִין, וּמְתַסְּיָין, בָּתַר דְּטָבְלוּ בִּנְהַר דִּינוּר לְאִתְדְכָּאָה. וְטַלָא לָא נָחִית, אֶלָּא מִגּוֹ אַתְוָון דִּרְשִׁימִין וּמְחַקְּקָן בְּהַהוּא רְקִיעָא, בְּגִין דְּאִינּוּן אַתְוָון כְּלָלָא דְּאוֹרַיְיתָא. וְהַהוּא רְקִיעָא רָזָא דְּאוֹרַיְיתָא, דְּהָא מֵאֵשׁ וּמַיִם דְּאוֹרַיְיתָא אִתְעָבִיד.","וְעַל דָּא אִינּוּן נַגְדִּין טַלָּא, עַל כָּל אִינּוּן דְּאִשְׁתַּדְּלוּ בְּאוֹרַיְיתָא לִשְׁמָהּ בְּהַאי עָלְמָא. וְאִלֵּין מִלִּין רְשִׁימִין בְּגִנְתָּא דְּעֵדֶן, וְסַלְּקִין עַד הַהוּא רְקִיעָא וְנַטְלִין מֵאִינּוּן אַתְוָון הַהוּא טַלָּא, לְאַתְּזָנָא הַהִיא נִשְׁמְתָא. הֲדָא הוּא דִּכְתִּיב, (דברים ל״ב:ב׳) יַעֲרֹף כַּמָּטָר לִקְחִי תִּזַּל כַּטַּל אִמְרָתִי.","בְּאֶמְצָעִיתָא דְּהַאי רְקִיעָא, קַיְּימָא פִּתְחָא חֲדָא, לָקֳבֵל פִּתְחָא דְּהֵיכְלָא דִּלְעֵילָּא, דִּבְהַהוּא פִּתְחָא, פַּרְחִין נִשְׁמָתִין מִגִּנְתָּא דִּלְתַתָּא לְעֵילָּא, בְּחַד עַמּוּדָא דְּנָעִיץ (ויחי רי\"ט ע\"א) בְּגִנְתָּא, עַד הַהוּא פִּתְחָא.","גּוֹ הַהוּא רְקִיעָא (נ\"א עמודא) בְּהַהוּא פִּתְחָא דְּאִיהוּ בְּאֶמְצָעִיתָא דִּרְקִיעָא דִּבְגִנְתָּא, עָאלִין בְּגַוָהּ תְּלַת גַּוְונִין דִּנְהוֹרָא כְּלִילָן כַּחֲדָא, וְנָהֲרָן לִגְוָונִין דְּהַהוּא עַמּוּדָא. וּכְדֵין רְקִיעָא (נ\"א עמודא) דָּא, נָצִיץ וְאִתְלְהִיט בְּכַמָּה גַּוְונִין (נ\"א נהורין) דְּמִתְלָהֲטָן. בְּכָל שַׁעֲתָא, נַהֲרִין צַדִּיקַיָּא, מֵהַהוּא זִיוָא עִלָּאָה. אֲבָל בְּכָל שַׁבְּתָא וְשַׁבְּתָא, וּבְכָל רֵישׁ יַרְחָא, אִתְגַּלְיָיא שְׁכִינְתָּא, יַתִּיר מִשְּׁאָר זְמַנִי בְּהַאי רְקִיעָא, וְאַתְיָין כֻּלְּהוּ צַדִּיקַיָּא, וְסַגְדִּין לְגַבֵּיהּ.","זַכָּאָה חוּלָקֵיהּ, מַאן דְּזָכֵי לְהָנֵי לְבוּשֵׁי דְּקָאָמַרָן, דְּמִתְלַבְּשָׁן בְּהוּ צַדִּיקַיָּא בְּגִנְתָּא דְּעֵדֶן (לתתא). אִלֵּין מֵעוֹבָדִין טָבִין, דְּעָבִיד בַּר נָשׁ, בְּהַאי עָלְמָא, בְּפִקּוּדֵי אוֹרַיְיתָא. וּבְהוֹן קַיְּימָא נִשְׁמְתָא בְּגִנְתָּא דְּעֵדֶן לְתַתָּא, וְאִתְלַבְּשַׁת בְּהָנֵי לְבוּשִׁין יַקִּירִין."],[[0,"תרין פתחין אחרנין וכו':","ב' פתחים אחרים הנה ב' אורות אחרים לוהטים מאור האש באלו הפתחים, ד' לצד שמאל, וא' לאחור, ב' אותיות אחרות לוהטים באלו האורות ומתנוצצות בתוכם אות אחת \u0003ג',\u0004 ואות אחת \u0003נ'\u0004 שהן אותיות ראשונות של המלאך \u0003ג\u0004 בריאל, ושל המלאך \u0003נ\u0004 וריאל. וכשהאותיות הראשונות חוזרות למקומם, אלו ב' אותיות אחרות מתנוצצות ועולות ויורדות, יוצאות מאלו האורות שבפתחים, ועומדות על הנשמה."],[1,"כדין נחתין תרין וכו':","אז יורדות שתי מרכבות מב' פתחים האלו, מרכבה אחת הוא מרכבה של \u0003גבריאל\u0004 ממונה עליון ויקר, מרכבה השניה היא מרכבה אחרת קדושה של \u0003נוריאל\u0004 ממונה עליון. ויורדים מפחתים האלו ועומדים על הנשמה. והאותיות ג' נ', חוזרות למקומן."],[1,"","באור המאמר. תחלה צריך להבין אלו ד' פתחים שמתחת הרקיעים מה הם. וכבר נתבאר זה באורך לעיל (אות ק\"ל בהסולם) שהסיום החדש שנעשה באמצע המדרגה, בסוד נקודת החולם מחמת עלית המלכות לבינה, סיום זה נעשה פתח בשביל התחתון שיוכל לעלות לעליון ולקבל ממנו המוחין. ולולא סיום החדש הזה שנעשה באמצע כל מדרגה, לא היה שום מבוא ופתח שיוכל התחתון להתרומם משהו למעלה ממדרגתו. עש\"ה."],[1,"","ולהלאה (באות שי\"א) מפרש הזהר יותר. וזה לשונו, \u0003כמה דהאי נהר אתפרש ונפיק מגו עדן לאשקאה לגנתא דלעילא, הכי נמי מגו ההוא פתחא דאמצעיתא נפיק חד נהורא דאתפרש לד' סטרין בד' פתחין דקאמרן.\u0004 הרי שתחילה נעשה פתח באמצע, ומפתח ההוא נתפשטו ויצאו ד' פתחים לד' צדדים מתחת הרקיעים."],[1,"","וסוד הרקיע, כבר ידעת שה\"ס קו האמצעי המקיים את הסיום החדש שנעשה באמצע המדרגה, בסוד נקודת החירק, במקום בינה שבה. באופן שאפילו אחר שחזרה המלכות וירדה ממקום בינה למקומה עצמה, לא נתבטל הסיום החדש מחמת זה, ואותם חצי בינה ותו\"מ שנטהרו מסיום החדש מכח ירידת המלכות אינם מתחברים למדרגתם בהיותם במקומם, אלא צריכים לעלות למעלה מסיום החדש, ושם הם מתחברים למדרגתם, כנ\"ל (באות קל\"א בהסולם) ונמצא שרקיע האחרון דט' רקיעים, שהוא יסוד, (כנ\"ל באות רצ\"ב בהסולם) נמצא במקום סיום החדש שנקבע, דהיינו באמצע המדרגה במקום בינה של המדרגה. ומכאן תבין שפתח הזה שנעשה, שהיא בחינת סיום החדש עצמו, שנתהפך לפתח בשביל התחתון, הוא עומד באמצע המדרגה, דהיינו במקום סיום החדש, והוא תחת כל ט' הרקיעים, דהיינו ברקיע היסוד בסיומו, ששם עומד סיום החדש שבאמצע המדרגה."],[1,"","וז\"ש להלן (באות שי\"א) \u0003מגו ההוא פתחא דאמצעיתא\u0004 דהיינו הפתח שנעשה בשביל התחתון במקום סיום החדש העומד באמצע המדרגה, במקום בינה, \u0003נפיק חד נהורא,\u0004 שמשם יוצא האור אל התחתון שהם חו\"ג תו\"מ, דהייני שתחלה עולה התחתון דרך פתח ההוא לעליון, עם הבינה ותו\"מ דעליון, (כנ\"ל אות ק\"ל) דהיינו מרקיע ולמעלה, ושם מקבל האורות חו\"ג תו\"מ, ואח\"כ יורד התחתון למקומו עם המוחין האלו. \u0003דאתפרש לד' סטרין,\u0004 שהם חו\"ג תו\"מ, \u0003בד' פתחין,\u0004 שלכל מוח נבחן פתח מיוחד, שלמוח החסד מאיר הפתח שבדרום, ולמוח הגבורה מאיר הפתח שבצפון, ולמוח הת\"ת מאיר הפתח שבמזרח, ולמוח המלכות מאיר הפתח שבמערב."],[1,"","וזה אמרו, (באות רצ\"ג) \u0003ארבע גוונין בההוא מתיחו דרקיעא דעל גנתא,\u0004 שהם ד' מוחין חו\"ג תו\"מ, שה\"ס ג' קוים ומלכות המקבלתם, שהם מאירים בתוך הרקיע שעל הגן שהוא בינה דבינה דמלכות דעשיה, וגם הרקיע הזה מתחלק לט' רקיעים. ומקבל הארתו מחו\"ב דז\"א דאצילות. כנ\"ל (אות רצ\"ב). \u0003לגבי הני גוונין אית ארבע פתחין לתתא מההוא מתיחו דרקיעא.\u0004 ואין הפתחים במקום הגוונים. כי הגוונים הם ברקיע עצמו דהיינו מיסוד דרקיע ולמעלה, אבל הפתחים הם תחת יסוד הרקיע, כלומר בסיומו ממש, שה\"ס סיום החדש שנעשה באמצע המדרגה שנתהפך לפתח בשביל מדרגה התחתונה, שהיא נשמות הצדיקים שבגן עדן. וע\"כ אומר \u0003לתתא\u0004 מההוא מתיחו דרקיעא. והם מקבלים הארות ד' גוונים שבתוך הרקיעים, ע\"כ אומר \u0003לגבי\u0004 הני גוונים. דהיינו שממשיכים מהם, אבל הפתחים אינם עומדים עמהם במקום אחד."],[1,"","וז\"ש, \u0003מאינון אש ומים\u0004 וכו' \u0003ומתפתחין בד' פתחין ד' נהורין,\u0004 כי אלו אש ומים ה\"ס ב' קוין ימין ושמאל דז\"א דאצילות, אשר הרקיע דז\"א שה\"ס הדעת, הוא קו האמצעי המיחדם, וה\"ס ג' גוונים לבן אדום וירוק, הנ\"ל, והמלכות המחוברת בדעת, ה\"ס גוון אוכם הנ\"ל ומאורות אלו נמשכים אל הפתחים, חו\"ג תו\"מ כנ\"ל, שכל מוח מאיר דרך הפתח שבצד שלו. וד' אלו מתחלקים לב' בחינות, שהם מים ואש, מים הם הארת חסדים, שהם אור החסד שבדרום, ואור הת\"ת שבמזרח. ואש ה\"ס הארת חכמה, שהם אור הגבורה שבצפון ואור המלכות שבמערב. ומתחילה מאירים על הנשמה אלו ב' אורות שהם בחינת מים, דהיינו שבדרום ובת\"ת, שהם חסדים, ואחר כך מאירים ב' אורות שהם בחינת אש, דהיינו שבצפון ובמערב, שהם הארת חכמה."],[1,"","והנה נתבאר המקום שמשם מקבל \u0003השמים\u0004 דגן עדן, שהוא הרקיע שעל הגן, דהיינו \u0003מאינון אש ומים דאתנטלו משמים עלאין,\u0004 שהוא ז\"א דאצילות הנקרא שמים. אמנם יש לשאול מאיזה מקום מקבלת \u0003הארץ\u0004 שבגן עדן, דהיינו הגן עצמו. וז\"ש לעיל (באות רפ\"ג) \u0003אית שמים ואית שמים, שמים לתתא וארץ לתתא מנייהו. שמים לעילא וארץ לתתא מנייהו\u0004 שזה מלמד, שכל בחינה מקבלת מבחינה שכנגדה למעלה. ולפיכך, כמו שהשמים דגן עדן מקבלים מאש ומים דשמים עלאין שהוא ז\"א, כך הארץ שבגן עדן, דהיינו הגן עצמו מקבל מארץ שלמעלה, שהיא המלכות דאצילות, והיינו על ידי המרכבה שלה. שה\"ס ד' מלאכים מיכאל גבריאל רפאל ונוריאל, שעליהם רוכבת ומתגלית המלכות, הנקראים ד' מרכבות. אמנם גם הם אינם יכולים להתפשט ולהאיר למטה אל הנשמות שבגן, זולת דרך ד' הפתחים הנ\"ל. כי אלו ד' המלאכים הם ג\"כ ד' בחינות חו\"ג תו\"מ, וע\"כ מיכאל מאיר דרך הפתח שבצד דרום שברקיע, וגבריאל מאיר דרך הפתח שבצד צפון שברקיע, ורפאל מאיר דרך הפתח שבצד מזרח שברקיע, ונוריאל מאיר דרך הפתח שבצד מערב. גם יש לדעת שאלו ד' מלאכים מאירים בעצמם אל הנשמות כל זמן שלא גמרו השפעתם, אבל אחר שגמרו השפעתם חוזרים למקומם למעלה, ומשאירים במקומם בד' הפתחים רק ד' בחינות רשימות בלבד, שה\"ס האותיות הראשונות של שמותיהם, דהיינו \u0003מ'\u0004 ממיכאל, \u0003ר'\u0004 מרפאל, \u0003ג'\u0004 מגבריאל, \u0003נ'\u0004 מנוריאל."],[1,"","והטעם הוא, כי רשימו היא בכל מקום בחינת נפש, וד' אותיות שבכל מלאך, הן ד' כלים לד' אורות נרנ\"ח שבהם, ונודע שיש ערך הפכי בין כלים לאורות, שבשעה שאין במדרגה רק בחינת נפש דאורות צריכה להתלבש בכלי היותר גדול, (כנ\"ל בפתיחה לחכמת הקבלה אות כ\"ד) וע\"כ כיון שלא נשאר מכל מלאך אלא רשימה מאורו, שה\"ס נפש שלו, ע\"כ היה צריך להשאר אות ראשון משמו לבחינת כלי לרשימה הזו. כי אות ראשון היא הכלי היותר גדול מכל האותיות שבשמו."],[1,"","ולפיכך יש להבחין בפתחים אלו שברקיע שעל הגן, ב' מיני אורות, א) ממה שהרקיעים עצמם מקבלים משמים עליונים שהם ז\"א דאצילות, וז\"ש \u0003מאינון אש ומים דאתעביד מנהון ההוא רקיעא ומתפתחין בארבע פתחין ארבע נהורין.\u0004 ב) הם רשימות האורות שהארץ דגן עדן, דהיינו הגן עצמו מקבל מארץ העליונה, שהיא המלכות על ידי ד' המלאכים הנ\"ל, שהרשימות אלו הן אותיות ראשונות משמותם, כנ\"ל, וז\"ש (באות רצ\"ה) \u0003גו נהורא דנהיר לסטר ימינא,\u0004 דהיינו אור החסד המקובל משמים עליונים, המאיר בפתח שבצד ימין של הרקיע, \u0003אתרשים את חד\u0004 וכו' \u0003ואיהו את מ' וקיימא באמצעיתא דההוא נהורא דפתחא.\u0004 ועד\"ז בשאר ג' פתחים כמו שמפרש לפנינו. הרי שיש ב' מיני אורות בפתחים אלו. א', משמים העליונים. ב', מארץ העליונה."],[1,"","וז\"ש (באות רצ\"ו) \u0003וכד נשמתא דצדיקיא עאלת בגנתא דעדן אלין תרין אתוון נפקין מגו ההוא נהורא וקיימין על ההיא נשמת\u0004 כי תיכף בביאת נשמת הצדיק לגן עדן, מאירים לו ד' הרשימות של ד' המלאכים שנשארו בפתחים מהשפעה שעברה. ואח\"כ \u0003מאינון תרין פתחין מקדמי ונחתי מעילא תרין רתיכין\u0004 וכו', דהיינו המלאכים עצמם באים להשפיע אל הנשמה שבגן עדן, כנ\"ל. ומחלק ד' המלאכים לשנים שנים, ב' לצד החסדים שהם בדרום ומזרח, שהם מיכאל ורפאל, דהיינו חסד ותפארת, וב' לצד הגבורות המאירים בהארת חכמה, שהם בצפון ומערב שהם גבריאל ונוריאל. ואלו השנים מיכאל ורפאל המאירים בחסדים, \u0003נחתין וקיימין על נשמתא ואמרין לה שלום בואך, יבא שלום יבא שלום.\u0004 דהיינו שמאירים לו אור החסדים שבימין, ע\"י קו האמצעי, שהוא משים שלום בין הקוין ימין ושמאל. \u0003כדין אינון תרין אתוון סלקין\u0004 וכו' \u0003ואתגניזו גו ההוא נהורא דאינון פתחין,\u0004 כי מאחר שבאו המלאכים עצמם אין צורך ברשימות שלהם. ועד\"ז מפרש גם ב' אותיות \u0003ג' נ'\u0004 והמלאכים גבריאל נוריאל, שהם בצפון ומערב. דהיינו גבורה ומלכות. וזכור דברים אלו לכל ההמשך ולמאמרים הסמוכים. כי לא אכפיל הדברים."],[1,"","וכן מתבאר בזה המאמר הקודם דרקיעים דעשיה. וז\"ש שם (באות רפ\"ח) \u0003באמצעיתא דכלהו רקיעין אית פתחא חדא.\u0004 היינו סיום החדש שבאמצע המדרגה שנעשה לפתח בשביל התחתון שיוכל לעלות ולקבל מן העליון, (כנ\"ל בסמוך בד\"ה וסוד הרקיע) \u0003ותחות האי פתחא אית ע' פתחין אחרנין לתתא,\u0004 היינו לקבל דרך שם בחינת ע' שמות שבמלכות דאצילות, שה\"ס הארת השם ע\"ב (כנ\"ל פרשת וירא אות רע\"ד) \u0003ושבעין ממנן\u0004 וכו' היינו ע' שרים של ע' אומות. \u0003ומההוא פתחא ארחא סליק\u0004 וכו' \u0003לגו כורסיא עלאה,\u0004 כי דרך שם אפשר לעלות עד המלכות דאצילות, כמ\"ש לעיל בעלית התפלה (באות קל\"א) \u0003ומההוא פתחא לכל סטרין דרקיעא,\u0004 היינו שמפתח הזה מתפשט ד' פתחים לכל צד שברקיע שהם ד' בחינות חו\"ג תו\"מ, (כנ\"ל בסמוך ד\"ה וז\"ש להלן) \u0003עד תרעא דפתחא דאקרי מגדון, דתמן איהו סיומא דרקיעא,\u0004 היינו הפתח שבצד מערב, שהיא בחינת המלכות, ששם מסתיים המדרגה. והשאר מובן וא\"צ פירוש."],[2,"כדין אלין תרין וכו':","אז אלו ב' מרכבות עולות לתוך היכל נסתר אחד הנקרא אהלות, ושם י\"ב מיני בשמים גנוזים, שכתוב, נרד וכרכם קנה וקנמון וגו' שהם י\"ב מינים כנגד י\"ב גבולי אלכסון שבז\"א, אלא שהם בשליטת החכמה שממטה למעלה המכונים בשמים וריח. וגם הם י\"ב מיני בשמים שבג\"ע שלמטה. ולהיות שרשם מז\"א, ע\"כ הם גנוזים כי הארת החכמה אינה מתגלה בז\"א. אלא ב' מרכבות אלו גבריאל ונוריאל שהם מבחינת השמאל שבמלכות שהחכמה מתגלה בה, שגבריאל הוא גבורה ממנה, ונוריאל הוא מלכות ממנה, יש להם רשות להכנס שם, ולקבל לבושים להתלבשות הנשמה. כמ\"ש להלן. שהם בחינות הארת חכמה הנמשכת מי\"ב מיני בשמים האמורים."],[3,"ותמן כל אינון וכו':","ושם כל אלו הלבושים של הנשמות הראויות להתלבש בהם כל אחת ואחת כראוי לה. בלבוש ההוא נרשמו כל המעשים טובים שעשה בעולם הזה. וכולם רשומים בו, ומכריזים, זה הוא הלבוש של פלוני. והמלאכים לוקחים לבוש ומתלבשות בו נשמות הצדיקים שבגן, כעין הצורה שבעולם הזה."],[4,"והני מילי מתלתין וכו':","והדברים אמורים רק משלשים יום והלאה. כי כל שלשים הימים לזוהר הפטירה, אין לך נשמה שלא תקבל עונש מטרם שתבא לגן עדן כיון שקבלה עונשה, נכנסת לגן עדן, כמו שהעמידוהו. ולאחר שהתלבנה, דהיינו אחר שנטהרה מזוהמת עולם הזה ע\"י העונש, התלבשה בלבוש הנ\"ל, כיון שנתלבשה בלבוש הזה נותנים לה מקום כפי הראוי לה. אז, אחר שהנשמה קבלה מקומה, כל אלו האותיות \u0003מרג\"נ,\u0004 שהם ראשי תיבות של שמות המלאכים הנ\"ל, יורדים, והמרכבות של ד' מלאכים הנ\"ל עולים למקומם. כי אחר שהמלאכים חוזרים, צריך להשאר הרשימות של הארתם, שה\"ס ד' אותיות מרג\"נ (כנ\"ל בסולם אות רצ\"ט)."],[5,"ההוא רקיעא אהדר וכו':","רקיע הזה חוזר ב' פעמים בכל יום בנסיעה ההוא של רקיע האחר שמתדבק בו. ורקיע הזה אינו יוצא לחוץ מן גן העדן. שאינו חופף רק על הג\"ע בלבד, רקיע זה מרוקם מכל מיני צבעים. שהם לבן אדום ירוק שחור, שהם חו\"ג תו\"מ."],[5,"","פירוש. כבר ידעת שהרקיע דגן עדן הוא דעת, והרקיעים דעולם העשיה הם ת\"ת הכולל חג\"ת נה\"י, (כנ\"ל בסולם אות רצ\"ב ד\"ה אמנם, ע\"ש ההמשך) והרקיע הזה דגן עדן מתחבר עם הרקיע דעשיה על דרך הדעת המתפשט אל חג\"ת נה\"י דגוף, (כמ\"ש לעיל בסולם אות רצ\"ב ד\"ה וז\"ש מה עביד) אמנם אין הדעת מתפשט אל הו\"ק דת\"ת אלא אם כן שהוא עולה אליו בבחינת קו אמצעי, דהיינו שהדעת מתחלק בעצמו לב' קוין חו\"ב, ימין ושמאל, והת\"ת שעלה אליו נעשה לקו אמצעי המחברם זה בזה ומלבישם זב\"ז, ואותו שיעור הארה שהת\"ת גרם שיתוסף בדעת, מקבל אותו הת\"ת. כי כל השיעור שהתחתון גורם לצאת בעליון זוכה בו התחתון, (כנ\"ל ב\"א דף רפ\"ז ד\"ה תלת) ואחר שהת\"ת קבל הארת הדעת, הוא מתפשט למקומו לגוף. והארה זו נקראת דעת המתפשט. גם ידעת, שג' קוין נקראים ג' זמני או ג' דוכתי, (כנ\"ל ב\"א דף כ' ד\"ה שמא) וגילוי הארתם הוא רק בבחינת נסיעה. (כנ\"ל בשלח ל\"ט ד\"ה וג')."],[5,"","וז\"ש \u0003ההוא רקיע אהדר תרין זמנין בכל יומא,\u0004 דהיינו שהרקיע דגן עדן שה\"ס דעת, מתחלק ומאיר בב' קוין ימין ושמאל, \u0003בההוא נטילו דהאי רקיע אחרא דמתדבק ביה\u0004 וב' הקוין דדעת מתחברים בנסיעה ההוא של רקיע האחר דעשיה שנתדבק בו, כלומר שרקיע דעשיה שהוא ת\"ת נעשה לקו אמצעי המחבר ב' קוים דדעת, בסוד הנסיעה, אשר אז מתפשטת הארת הרקיע שעל הג\"ע, אל שאר הרקיעים דעשיה שהם בחינת ת\"ת, כדרך הדעת המתפשט אל הגוף. אבל, \u0003והאי רקיע לא נפיק לבר מגנתא,\u0004 שהוא עצמו אינו יוצא לחוץ מג\"ע אל הרקיעים דעשיה, אלא הארתו מתפשט עד\"ז שאמרנו."],[6,"תרין ועשרין אתוון וכו':","כ\"ב אותיות רשומות וחקוקות ברקיע ההוא, שעל הג\"ע, כל אות ואות נוטפת טל, מטל שלמעלה, על הגן. ומטל ההוא, שהוא הארת החסדים, רוחצות אלו הנשמות, ונרפאות, אחר שטבלו עצמן בנהר דינור להטהר. והטל אינו יורד אלא מתוך אותיות הרשומות והחקוקות ברקיע ההוא, משום שאלו האותיות הן כלל התורה, שנמשכות מז\"א דאצילות הנקרא תורה, כי מאש ומים של התורה נעשה, דהיינו מאש ומים דז\"א דאצילות (כנ\"ל אות רצ\"ב)."],[7,"וע\"ד אינון נגדין וכו':","וע\"כ הם מזילים טל על כל אלו שעוסקים בתורה לשמה בעולם הזה. שאלו המלות רשומות בג\"ע, ועולות עד רקיע ההוא שעל הג\"ע, ולוקחות מאלו האותיות, כ\"ב, אשר שם, טל ההוא להזין הנשמה ההיא. ז\"ש, יערוף כמטר לקחי תזל כ \u0003טל\u0004 אמרתי."],[8,"באמצעיתא דהאי רקיע וכו':","באמצע רקיע הזה נמצא פתח אחד כנגד פתח ההיכל שלמעלה ביצירה, שבפתח ההוא פורחות הנשמות מגן עדן התחתון למעלה, בעמוד אחד הנעוץ בארץ של הג\"ע, ומגיע עד פתח ההוא."],[8,"","פירוש, כבר נתבאר לעיל (אות רצ\"ט) ענין הפתח שנעשה באמצע הרקיע, שהוא הסיום החדש שנעשה באמצע המדרגה של השמים דג\"ע, מחמת עלית המלכות במקום בינה, שמשום הסיום הזה נפלה חצי המדרגה, דהיינו בינה ותו\"מ, לבחינת המדרגה שלמטה, שהוא הארץ דג\"ע, אשר לעת גדלות, כשחוזרת המלכות למקומה ובינה ותו\"מ עולים למעלה למדרגתם לרקיע, לוקחים עמהם גם המדרגה התחתונה, דהיינו אותם הנשמות שהם בבחינת הארץ דג\"ע, ונמצא, שסיום החדש שנעשה בבינה נתהפך להיות ל \u0003פתח\u0004 בשביל התחתון, שיוכל דרך שם לעלות לעליון. ותדע, שאותם בינה ותו\"מ שנפלו תחילה למטה לארץ דג\"ע, הם הנבחנים, \u0003בחד עמודא דנעיץ בגנתא,\u0004 כי התדבקותם במדרגת הארץ דג\"ע, נבחן כמו שהם \u0003נעוצים\u0004 בתוך קרקע הגן, והם עצמם נבחנים כ \u0003עמוד\u0004 גבוה המגיע \u0003עד ההוא פתחא\u0004 שבאמצע הרקיע, שדרך העמוד הזה עולות הנשמות מארץ דג\"ע אל הרקיע דגן עדן, דהיינו לעת גדלות כשהבינה ותו\"מ, הנבחנים \u0003לעמוד.\u0004 עולים בחזרה לרקיע דג\"ע, לוקחים עמהם גם את הנשמות שבארץ דג\"ע, ומעלה אותם לרקיע דג\"ע."],[9,"גו ההוא רקיעא וכו':","בתוך רקיע הזה, בפתח ההוא שהוא באמצע הרקיע שעל הגן, נכנסים בו ג' גוונים של אור כלולים יחד, שהם חב\"ד, ומאירים לגוונים של עמוד ההוא שעלה שם, ואז עמוד הזה נוצץ ומתלהט בכמה גוונים הלוהטים. והצדיקים שעלו עם העמוד ההוא לרקיע, מקבלים האורות מן הרקיע דרך עמוד הזה. ובכל שעה מאירים הצדיקים מזיו העליון ההוא, כלומר, שזה נוהג תמיד, אבל בכל שבת ושבת ובכל ראש חדש מתגלה השכינה ברקיע הזה יותר מבשאר הזמנים, וכל הצדיקים באים ומשתחוים אליה."],[10,"זכאה חולקיה מאן וכו':","אשרי חלקו מי שזכה לאלו הלבושים שאמרנו (באות ש\"א) אלו הלבושים הם ממעשים טובים שעשה האדם בעולם הזה במצות התורה, דהיינו מצות התלויות במעשה, ובהם עומדת הנשמה בגן עדן התחתון ומתלבשת באלו הלבושים היקרים."]],[[0,"","שְׁנֵי פְּתָחִים אֲחֵרִים, שְׁנֵי אוֹרוֹת אֲחֵרִים לוֹהֲטִים מֵאוֹר הָאֵשׁ בְּאוֹתָם פְּתָחִים, אֶחָד לְצַד שְׂמֹאל וְאֶחָד לְאָחוֹר. שְׁתֵּי אוֹתִיּוֹת אֲחֵרוֹת לוֹהֲטוֹת בְּאוֹתָם אוֹרוֹת וְנוֹצְצִים בְּתוֹכָם. אוֹת אַחַת ג' וְאוֹת אַחַת נ'. וּכְשֶׁהָאוֹתִיּוֹת הָרִאשׁוֹנוֹת חוֹזְרוֹת לִמְקוֹמָן, שְׁתֵּי הָאֲחֵרוֹת הַלָּלוּ נוֹצְצוֹת, עוֹלוֹת וְיוֹרְדוֹת, יוֹצְאוֹת מֵאוֹתָם אוֹרוֹת וְעוֹמְדוֹת עַל הַנְּשָׁמָה."],[1,"","אָז יוֹרְדוֹת שְׁתֵּי מֶרְכָּבוֹת מֵאוֹתָם שְׁנֵי פְתָחִים. מֶרְכָּבָה אַחַת הִיא מֶרְכַּבְתּוֹ שֶׁל גַּבְרִיאֵל, מְמֻנֶּה גָדוֹל וְנִכְבָּד. הַמֶּרְכָּבָה הַשְּׁנִיָּה הִיא מֶרְכָּבָה אַחֶרֶת קְדוֹשָׁה שֶׁל נוּרִיאֵ\"ל הַמְמֻנֶּה הַגָּדוֹל, וְיוֹרְדוֹת מֵאוֹתָם פְּתָחִים וְעוֹמְדוֹת עַל הַנְּשָׁמָה, וְהָאוֹתִיּוֹת חוֹזְרוֹת לִמְקוֹמָן."],[2,"","אָז, שְׁתֵּי הַמֶּרְכָּבוֹת הַלָּלוּ נִכְנָסוֹת לְתוֹךְ הֵיכָל אֶחָד טָמִיר שֶׁבַּגָּן שֶׁנִּקְרָא אֲהָלוֹ\"ת, וְשָׁם שְׁנֵים עָשָׂר מִינֵי בְשָׂמִים גְּנוּזִים, שֶׁכָּתוּב (שיר ד) נֵרְדְּ וְכַרְכֹּם קָנֶה וְקִנָּמוֹן וְגוֹ'. וְאוֹתָם שְׁנֵים עָשָׂר מִינֵי בְשָׂמִים שֶׁלְּמַטָּה."],[3,"","וְשָׁם כָּל אוֹתָם לְבוּשֵׁי הַנְּשָׁמוֹת שֶׁרְאוּיִים לְהִתְלַבֵּשׁ בָּהֶם כָּל אֶחָד וְאֶחָד כָּרָאוּי. בְּאוֹתוֹ לְבוּשׁ נִרְשְׁמוּ כָּל אוֹתָם מַעֲשִׂים טוֹבִים שֶׁעָשָׂה בָּעוֹלָם הַזֶּה, וְכֻלָּם רְשׁוּמִים בּוֹ וּמַכְרִיזִים: זֶהוּ לְבוּשׁוֹ שֶׁל פְּלוֹנִי. וְנוֹטְלִים אֶת אוֹתוֹ לְבוּשׁ, וּמִתְלַבֶּשֶׁת בּוֹ אוֹתָהּ נִשְׁמַת הַצַּדִּיק שֶׁבַּגָּן כְּמוֹ בַּדְּיוֹקָן שֶׁבָּעוֹלָם הַזֶּה."],[4,"","וְהַדְּבָרִים הַלָּלוּ מִשְּׁלֹשִׁים יוֹם וְאֵילָךְ, שֶׁהֲרֵי כָּל שְׁלֹשִׁים הַיָּמִים אֵין לְךְ נְשָׁמָה שֶׁלֹּא תְקַבֵּל עֹנֶשׁ טֶרֶם שֶׁתִּכָּנֵס לְגַן עֵדֶן. כֵּיוָן שֶׁקִּבְּלָה עֹנֶשׁ, נִכְנֶסֶת לְגַן עֵדֶן, כְּמוֹ שֶׁבֵּאֲרוּהָ. אַחַר שֶׁהִתְלַבְּנָה, מִתְלַבֶּשֶׁת. כֵּיוָן שֶׁהִתְלַבְּשָׁה בַּלְּבוּשׁ הַזֶּה, נוֹתְנִים לָהּ מָקוֹם כָּרָאוּי לָהּ. אָז כָּל אוֹתָן הָאוֹתִיּוֹת יוֹרְדוֹת, וְעוֹלוֹת אוֹתָן מֶרְכָּבוֹת."],[5,"","אוֹתוֹ רָקִיעַ חוֹזֵר פַּעֲמַיִם בְּכָל יוֹם בְּאוֹתָהּ נְטִילַת הָרָקִיעַ הָאַחֵר הַזֶּה שֶׁנִּדְבָּק בּוֹ. וְהָרָקִיעַ הַזֶּה אֵינוֹ יוֹצֵא מִחוּץ לַגָּן. הָרָקִיעַ הַזֶּה רָקוּם בְּכָל מִינֵי גְוָנִים."],[6,"","עָשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת רְשׁוּמוֹת חֲקוּקוֹת בְּאוֹתוֹ רָקִיעַ, כָּל אוֹת וָאוֹת נוֹטֶפֶת מֵהַמָּן (מהטל), מֵהַטַּל שֶׁלְּמַעְלָה עַל הַגָּן, וּמֵאוֹתוֹ הַטַּל שֶׁל הָאוֹתִיּוֹת רוֹחֲצוֹת אוֹתָן נְשָׁמוֹת וְנִרְפָּאוֹת, אַחַר שֶׁטָּבְלוּ בִּנְהַר דִּינוּר לְהִטָּהֵר. וְהַטַּל אֵינוֹ יוֹרֵד אֶלָּא מִתּוֹךְ אוֹתִיּוֹת שֶׁרְשׁוּמוֹת וַחֲקוּקוֹת בְּאוֹתוֹ רָקִיעַ, מִשּׁוּם שֶׁאוֹתָן אוֹתִיּוֹת הֵן כְּלַל הַתּוֹרָה, וְאוֹתוֹ הָרָקִיעַ הַסּוֹד שֶׁל הַתּוֹרָה, שֶׁהֲרֵי מֵאֵשׁ וּמַיִם שֶׁל הַתּוֹרָה נַעֲשָׂה."],[7,"","וְעַל כֵּן הֵם שׁוֹפְעִים טַל עַל כָּל אוֹתָם שֶׁהִשְׁתַּדְּלוּ בַתּוֹרָה לִשְׁמָהּ בָּעוֹלָם הַזֶּה. וְהַדְּבָרִים הַלָּלוּ רְשׁוּמִים בְּגַן עֵדֶן וְעוֹלִים עַד אוֹתוֹ רָקִיעַ, וְנוֹטְלִים מֵאוֹתָן אוֹתִיּוֹת אוֹתוֹ הַטַּל לְהָזִין אֶת הַנְּשָׁמָה הַזּוֹ. זֶהוּ שֶׁכָּתוּב (דברים לב) יַעֲרֹף כַּמָּטָר לִקְחִי תִּזַּל כַּטַּל אִמְרָתִי."],[8,"","בְּאֶמְצַע הָרָקִיעַ הַזֶּה עוֹמֵד פֶּתַח אֶחָד כְּנֶגֶד הַפֶּתַח שֶׁאָמַרְנוּ שֶׁל הַהֵיכָל שֶׁלְּמַעְלָה, שֶׁבְּאוֹתוֹ פֶּתַח הַנְּשָׁמוֹת פּוֹרְחוֹת מֵהַגָּן שֶׁלְּמַטָּה לְמַעְלָה בְּעַמּוּד אֶחָד הַנָּעוּץ בַּגָּן עַד לְאוֹתוֹ פֶּתַח."],[9,"","בְּתוֹךָ אוֹתוֹ רָקִיעַ (עמוד) בְּאוֹתוֹ פֶּתַח, שֶׁהוּא בְּאֶמְצַע הָרָקִיעַ שֶׁבַּגָּן, נִכְנָסִים לְתוֹכָהּ שְׁלֹשָׁה גְוָנִים שֶׁל אוֹר כְּלוּלִים כְּאֶחָד, וּמְאִירִים לְצוּרוֹת אוֹתוֹ הָעַמּוּד. וְאָז הָרָקִיעַ (העמוד) הַזֶּה נוֹצֵץ וּמִתְלַהֵט בְּכַמָּה גְוָנִים (אורות) שֶׁמִּתְלַהֲטִים. בְּכָל שָׁעָה מְאִירִים הַצַּדִּיקִים מֵאוֹתוֹ זִיו עֶלְיוֹן. אֲבָל בְּכָל שַׁבָּת וְשַׁבָּת וּבְכָל רֹאשׁ חֹדֶשׁ מִתְגַּלָּה הַשְּׁכִינָה יוֹתֵר מִשְּׁאָר הַזְּמַנִּים בְּאוֹתוֹ רָקִיעַ, וְכָל הַצַּדִּיקִים בָּאִים וּמִשְׁתַּחֲוִים לָהּ."],[10,"","אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁזּוֹכֶה לַלְּבוּשִׁים הַלָּלוּ שֶׁאָמַרְנוּ, שֶׁמִּתְלַבְּשִׁים בָּהֶם הַצַּדִּיקִים בְּגַן עֵדֶן (שלמטה). אֵלֶּה מִמַּעֲשִׂים טוֹבִים שֶׁעָשָׂה אָדָם בָּעוֹלָם הַזֶּה בְּמִצְווֹת הַתּוֹרָה, וּבָהֶם עוֹמֶדֶת הַנְּשָׁמָה בְּגַן עֵדֶן שֶׁלְּמַטָּה, וּמִתְלַבֶּשֶׁת בַּלְּבוּשִׁים הַנִּכְבָּדִים הַלָּלוּ."]]],[["כַּד (רכ\"ט ע\"ב) סַלְּקָא נִשְׁמְתָא בְּהַהוּא פִּתְחָא דִּרְקִיעָא לְעֵילָּא, אִזְדַּמְּנָן לָהּ לְבוּשִׁין אַחֲרָנִין יַקִּירִין עִלָּאִין, דְּאִינּוּן מֵרְעוּתָא וְכַוָּנָה דְּלִבָּא בְּאוֹרַיְיתָא וּבִצְלוֹתָא, דְּכַד סַלְּקָא הַהוּא רְעוּתָא לְעֵילָּא, מִתְעַטָּר בָּהּ מַאן דְּמִתְעַטְּרָא, וְאִשְׁתְּאַר חוּלָקָא לְהַהוּא בַּר נָשׁ, וְאִתְעָבֵד מִנֵּיהּ לְבוּשִׁין דִּנְהוֹרָא, לְאִתְלַבְּשָׁא בְּהוּ נִשְׁמְתָא. לְסַלְּקָא לְעֵילָּא. וְאַף עַל גַּב דְּאוּקְמוּהָ, דְּאִינּוּן לְבוּשִׁין בְּעוֹבָדִין תַּלְיָין. אִלֵּין לָא תַּלְיָין אֶלָּא בִּרְעוּתָא דְּרוּחָא, כְּמָה דְּאִתְּמַר, לְקַיְּימָא גּוֹ מַלְאֲכִין רוּחִין קַדִּישִׁין וְדָא אִיהוּ בְּרִירוּ דְּמִלָּה. וּבוּצִינָא קַדִּישָׁא, אוֹלִיף הָכִי מֵאֵלִיָּהוּ, לְבוּשִׁין דִּלְתַתָּא בְּגִנְתָּא דְּאַרְעָא בְּעוֹבָדִין. לְבוּשִׁין דִּלְעֵילָּא, (ס\"א ברוחא ברעותא וכוונא דלבא) בִּרְעוּתָא וְכַוָּונָא דְּרוּחָא בְּלִבָּא.","(בראשית ב׳:י׳) (ויקרא י\"א ע\"א) וְנָהָר יוֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן וְגוֹ', הָא אוּקְמוּהָ, אֲבָל בְּהַאי גִּנְתָּא דִּלְתַתָּא, נָהָר יוֹצֵא מֵעֵדֶן וַדַּאי. וְאִצְטְרִיךְ לְמִנְדַּע, הַאי נָהָר דְּנָפִיק בְּגִנְתָּא דִּלְתַתָּא, בְּאָן אֲתָר עִקָּרָא וְשָׁרְשָׁא דִּילֵיהּ. בְּאָן אֲתָר, בְּעֵדֶן. עֵדֶן דָּא רָזָא עִלָּאָה אִיהוּ, וְלָא אִתְיְיהִיב רְשׁוּ לְשַׁלְּטָאָה בֵּיהּ עֵינָא דְּסֻכְלְתָנוּ. וְרָזָא דְּמִלָּה אִלְמָלֵי אֲתָר דָּא אִתְמְסַר לְתַתָּא לְאִתְגַלָאָה, אֲתָר דְּעֵדֶן עִלָּאָה קַדִּישָׁא, אִתְמְסַר אוּף הָכִי לְמִנְדַּע. אֶלָּא (נ\"א אבל) בְּגִין טְמִירוּ דִּיְקָרָא דְּעֵדֶן עִלָּאָה קַדִּישָׁא, אִתְטָמַר וְאִתְגְּנִיז עֵדֶן תַּתָּאָה, דְּהַהוּא נָהָר נָגִיד וְנָפִיק מִנֵּיהּ. וְעַל דָּא לָא אִתְמְסַר לְאִתְגַּלָּאָה, אֲפִילּוּ לְאִינּוּן נִשְׁמָתִין דִּבְגִנְתָּא דְּעֵדֶן.","כְּמָה דְּהַאי נָהָר אִתְפְּרַשׁ וְנָפִיק מִגּוֹ עֵדֶן, לְאַשְׁקָאָה לְגִנְתָּא דִּלְעֵילָּא, הָכִי נָמֵי מִגּוֹ הַהוּא פִּתְחָא דְּאֶמְצָעִיתָא נָפִיק חַד נְהוֹרָא, דְּאִתְפְּרַשׁ לְד' סִטְרִין, בְּד' פִּתְחִין דְּקָאָמַרָן. אֲתָר דְּקַיְימִין אִינּוּן אַתְוָון רְשִׁימָן. וְהַהוּא נְהוֹרָא דְּאִתְפְּרַשׁ לְאַרְבַּע נְהוֹרִין, בְּד' אַתְוָון דְּנִיצוֹצִין, (נ\"א ונפקין) נָפִיק מֵעֵדֶן, אֲתָר דְּזָהֲרָא נְקוּדָה לְעֵילָּא.","וְהַהוּא נְקוּדָה אִתְנְהִיר, וְאִתְעָבִיד עֵדֶן לְאַנְהָרָא. וְלָא אִית מַאן דְּשַׁלִּיט לְמֵחמֵי וּלְמִנְדַּע לְהַאי נְקוּדָה, בַּר הַהוּא נְהִירוּ דְּאִתְפָּשַּׁט מִנֵּיהּ, דְּסַגְדִּין לְקַמֵּיהּ אִינּוּן צַדִּיקַיָּא דִּבְגִנְתָּא דְּעֵדֶן, כְּמָה דְּאִתְּמַר. וְהַאי נְקוּדָה תַּתָּאָה, אִיהִי גִּנְתָּא לְגַבֵּי עֵדֶן עִלָּאָה, אֲתָר דְּלָא אִתְיְיהִיב לְמִנְדַּע וּלְאִסְתַּכְּלָא.","עַל כָּל דָּא כְּתִיב, (ישעיהו ס״ד:ג׳) עַיִן לא רָאָתָה אֱלֹהִים זוּלָתְךָ. שְׁמָא דָּא אִתְפְּרַשׁ, אֱלֹהִים זוּלָתְךָ, דָּא נְקוּדָה תַּתָּאָה קַדִּישָׁא, דְּאִיהוּ יָדַע הַאי עֵדֶן דִּלְתַתָּא, דְּטָמִיר בְּגִנְתָּא, וְלֵית אַחֲרָא מַאן דְּיָדַע לֵיהּ. (בראשית כ\"ו ע\"א) אֱלֹהִים זוּלָתְךָ, דָּא עֵדֶן עִלָּאָה עַל כֹּלָּא, דְּאִיהוּ רָזָא דְּעָלְמָא דְּאָתֵי, דְּאִיהוּ יָדַע לִנְקוּדָה תַּתָּאָה, בְּחַד צַדִּיק דְּנָפִיק מִנֵּיהּ, נָהָר דְּרַוֵּי לֵיהּ, וְלֵית מַאן דְּיָדַע לֵיהּ בַּר אִיהוּ, דִּכְתִּיב אֱלֹהִים זוּלָתְךָ, דְּאִיהוּ אָחִיד לְעֵילָּא לְעֵילָּא עַד אֵין סוֹף.","וְהַאי נָהָר דְּנָפִיק מֵעֵדֶן לְתַתָּא, רָזָא אִיהוּ לְחַכִּימִין, בְּרָזָא דִּכְתִּיב, (ישעיהו נ״ח:י״א) וְהִשְׁבִּיעַ בְּצַחְצָחוֹת נַפְשֶׁךָ. וּמִלָּה דָּא אִתְפְּרַשׁ לְעֵילָּא וְתַתָּא. נִשְׁמְתָא דְּנַפְקָא מֵהַאי עָלְמָא דְּחַשׁוֹכָא, אִיהִי תָּאִיבַת לְמֵחמֵי בִּנְהִירוּ דְּעָלְמָא עִלָּאָה, כְּהַאי בַּר נָשׁ דְּתָאִיב לְמִשְׁתֵּי בִּתְאִיבוּ לְמַיָּא, הָכִי כָּל חַד וְחַד, אִיהוּ צַחְצָחוֹת, כְּמָה דְּאַתְּ אָמַר, (ישעיהו ה׳:י״ג) צִחֵה צָמָא. צָמָא, מֵאִינּוּן צָחוֹת דִּנְהוֹרִין דְּגִּנְתָּא וּרְקִיעָא וְהֵיכָלִין דְּגִּנְתָּא.","וְהַהוּא נָהָר דְּנָפִיק מֵעֵדֶן, כָּל אִינּוּן נִשְׁמָתִין בִּלְבוּשֵׁי יְקָר, יַתְבִין עַל הַהוּא נָהָר, וְאִלְמָלֵא הַהוּא לְבוּשָׁא, לָא יַכְלִין לְמִסְבַּל. וּכְדֵין מִתְיַישְּׁבָן, וְרַוָּון בְּאִינּוּן צָחוֹת, וְיַכְלֵי לְמִסְבַּל. וְהַהוּא נָהָר אִיהוּ תִּקּוּנָא דְּנִשְׁמָתִין, לְאִתְיַישְּׁבָא, וּלְאִתְּזְנָא וּלְאִתְהֲנָאָה, מֵאִינּוּן צָחוֹת וְנִשְׁמָתִין אִתְהַקְּנָן (נ\"א אתתקנן) עַל הַהוּא נָהָר, וּמִתְיַישְּׁבָן בֵּיהּ.","הַהוּא נָהָר עִלָּאָה דִּלְעֵילָּא, אַפִּיק נִשְׁמָתִין, וּפַרְחִין מִנֵּיהּ, לְגוֹ גִּנְתָּא, דְּהַאי נָהָר דִּלְתַתָּא בְּגִנְתָּא דְּאַרְעָא, אַתְקִין נִשְׁמָתִין, לְאִתְתַּקְּנָא לְאִתְיַישְּׁבָא, בְּאִינּוּן צָחוֹת. כְּגַוְונָא דָּא בְּהַאי עָלְמָא לְבַר, בְּרֵיחָא דְּמַיָיא מִתְיַישְּׁבָא נַפְשָׁא לְאִתְנַהֲרָא, דְּהָא מֵעִיקָּרָא כְּגַוְונָא דָּא נָפְקָא. וּבְגִין דְּמִתַּתְקְנִין נִשְׁמָתִין עַל הַהוּא נָהָר דְּנָגִיד וְנָפִיק מֵעֵדֶן, יַכְלִין לְאִתְיַישְּׁבָא בְּאִינּוּן צָחוֹת עִלָּאִין, וּלְסַלְּקָא לְעֵילָּא. בְּהַהוּא פִּתְחָא דְּאֶמְצָעִיתָא דִּרְקִיעָא (ויחי רי\"ט ע\"א) וְחַד עַמּוּדָא דְּקָאִים בְּאֶמְצָעוּת גִּנְתָּא דְּקָאָמַרָן."],[[0,"כד סלקא נשמתא וכו':","כשעלתה הנשמה דרך פתח הרקיע למעלה, מזדמנים לה לבושים אחרים יקרים עליונים שהם נעשים על ידי מצות התלויות ברצון וכוונת הלב בתורה ותפלה, כי כשעולה הרצון ההוא למעלה, מתעטר בה מי שמתעטר, וחלק ממנו נשאר לאדם ההוא, ונעשה ממנו לבושי אור שתתלבש בהם הנשמה לעלות למעלה. ואע\"פ שהעמידו שאלו לבושים של הנשמה בג\"ע התחתון תלוים במעשה, כנ\"ל בסמוך, אבל אלו שעולות לרקיע למעלה, אינם תלוים אלא ברצון של הרוח, כמו שאמרנו כדי לעמוד בין המלאכים שהם רוחות קדושים. וזה הוא בירורו של הדבר, והמאור הקדוש, שהוא ר\"ש, כך למד מאליהו, הלבושים של מטה בג\"ע הארץ תלוים במעשה, לבושים שלמעלה תלוים ברצון וכוונת הרוח בלב."],[1,"ונהר יוצא מעדן להשקות את הגן וגו':","הרי העמידוהו. אבל בגן הזה שלמטה, דהיינו בג\"ע התחתון. נהר יוצא מעדן שלו ודאי. וצריכים לדעת נהר זה היוצא בגן שלמטה, באיזה מקום הוא, העיקר והשורש שלו. ומשיב, אין שאלה באיזה מקום, כי הוא בעדן, כמו הנהר היוצא מעדן שבאצילות. שהוא חכמה דאצילות, אבל \u0003עדן\u0004 הוא סוד עליון ולא ניתנה רשות לעין השכל לשלוט בו. וסוד הדבר הוא, אם מקום זה, דהיינו העדן, שהוא חכמה שברקיעים שבג\"ע שלמטה, היה נמסר להתגלות למטה, היה נמסר גם כן המקום של עדן העליון הקדוש לדעת אותו, אלא משום סתר כבוד עדן העליון הקדוש, שהוא חכמה דאצילות, שלא יתגלה, נסתר ונגנו גם עדן התחתון, שהוא חכמה שברקיעים שבג\"ע התחתון, שאותו נהר שבג\"ע נמשך ממנו, וע\"כ לא נמסר עדן זה להתגלות אפילו לנשמות שבגן עדן."],[1,"","פירוש. החכמה, שה\"ס חכמה דא\"א הנעלמת באו\"א עלאין דאצילות נקרא \u0003עדן\u0004 וחכמה זו נסתמה מתחתונים. ואין בה שום השגה כלל וכלל. והחכמה המתגלה לתחתונים היא מבינה שיצאה לחוץ מראש דא\"א, הנקראת \u0003נהר יוצא מעדן,\u0004 מסבת המלכות שעלתה במקום בינה, ואח\"כ כשחזרה לראש בעת גדלות היא מקבלת חכמה מחכמה סתימאה שבראש דא\"א, ואז חזרה הבינה ונעשתה לחכמה, והארת חכמה שלה מתגלה במקום המלכות וממלכות לתחתונים."],[1,"","וענין זה נוהג בכל מדרגה עד עולם עשיה והרקיעים שבג\"ע. כי בכל מדרגה יש עשר ספירות, שהחכמה שבהן נקראת \u0003עדן,\u0004 והיא עצמה סתומה כמו חכמה סתימאה דא\"א למעלה, אלא מכח עלית המלכות למקום בינה שבמדרגה, ובינה ותו\"מ נופלים למדרגה שמתחתיה, שהם נקראים משום זה, \u0003נהר יוצא מעדן\u0004 שבאותו מדרגה. ולעת גדלות שבינה ותו\"מ אלו חוזרים למדרגתם אז הם מקבלים מעדן שלהם חכמה, ומהם יוצאת החכמה להמלכות שבאותה המדרגה."],[1,"","וזה אמרו, \u0003אלמלי אתר דא אתמסר לתתא לאתגלאה,\u0004 שאם העדן, שברקיעים דגן עדן, היה נמסר להתגלות, \u0003אתר דעדן עלאה קדישא אתמסר אוף הכי למנדע.\u0004 כי החכמה שבכל המדרגות היא בחינת עדן שבהן, ואם היתה מגולה לדעת את העדן דמדרגה התחתונה, היתה מגלה עמה את העדן דמדרגה העליונה, עד חכמה סתימאה. ולפיכך כל בחינת ג\"ר שבכל מדרגה אין בהן שום השגה."],[1,"","וצריך שתבין מה שאנו מכנים את הנהר היוצא מעדן, פעם בשם בינה ותו\"מ, ופעם בשם ת\"ת, ופעם בשם יסוד. והענין הוא, כי הכל הולך אל מקום אחד. כי \u0003בינה ותו\"מ\u0004 אלו אינם אלא חצי בינה ותו\"מ, כי ג\"ר דבינה אינם נחשבים ליוצאים מעדן, רק ז\"ת דבינה, שפירושם תו\"מ הכלולים בבינה, ונמצא שאין כאן בחינת בינה אלא תו\"מ, וע\"כ נבחנים כולם רק \u0003לתפארת.\u0004 ומבחינת הפרצוף שעשר ספירות שלו נחלקות לראש תוך סוף, נבחן שבינה ותו\"מ הנופלים ממדרגה מתחילים מחזה ולמטה, כי החג\"ת דגוף נבחנים לג\"ר דגוף, שגם הם לא יצאו מעדן שלהם, אלא רק נה\"י דגוף. וכיון שעקרם של נה\"י הוא קו אמצעי יסוד, ע\"כ אנו מכנים לבינה ותו\"מ שנפלו ממדרגה בשם \u0003יסוד.\u0004 הרי שהכל הולך אל מקום אחד. וזכור זאת לכל המקומות."],[2,"כמה דהאי נהר וכו':","כמו שנהר הזה שהוא בינה ותו\"מ, נפרד ויצא מעדן, שהוא חכמה שבראש דא\"א, כדי להשקות הגן שלמעלה, שהוא מלכות דאצילות, יוצא גם כן מפתח ההוא שבאמצע הרקיעים שבגן, אור אחד שנחלק לד' צדדים בד' פתחים שאמרנו (באות רצ\"ג) המקום שעומדים שם אלו אותיות מגר\"ן הרשומות (כנ\"ל אות רצ\"ה רצ\"ו רצ\"ח). ואור הזה, הנחלק לד' אורות וד' אותיות המתנוצצות, יוצא מעדן, שהוא מקום שמאירה הנקודה שלמעלה, דהיינו חכמה דרקיעים שבגן עדן הארץ שהיא בחינת נקודה עליונה אשר שם."],[3,"וההוא נקודה אתנהיר וכו':","ונקודה עליונה ההיא, האירה ונעשה \u0003עדן\u0004 להאיר. ואין מי שישלוט לראות ולדעת נקודה ההיא, חוץ מן האור שמתפשט ממנו, ע\"י הפתח שבאמצע הרקיעים כנ\"ל בסמוך, שמשתחוים לפניו הצדיקים שבגן עדן, כמו שלמדנו, ונקודה תתאה זו, שהוא המלכות שבג\"ע, היא \u0003גן,\u0004 אל עדן העליון, שהיא נקודה עליונה, חכמה, שהוא מקום שלא ניתן לדעת ולהסתכל."],[4,"על כל דא וכו':","על כל זה כתוב, עין לא ראתה אלקים זולתך. שם זה, אלקים, מתבאר, א) \u0003אלקים זולתך,\u0004 זה נקודה תחתונה הקדושה, שהיא מלכות דאצילות הנקראת אלקים, שהיא יודעת את עדן הזה שלמטה, בג\"ע הארץ. הנסתר בגן, ואין אחר מי שיודע אותו, זולת המלכות דאצילות. ב) \u0003אלקים זולתך\u0004 זה הוא עדן העליון על כל, שהוא סוד עולם הבא, כלומר חכמה דאצילות שהוא עדן העליון, שהיא מתגלה בבינה דאצילות הנקרא עולם הבא, שנקראת \u0003אלקים,\u0004 שהוא יודע את נקודה התחתונה, דהיינו מלכות דאצילות, ע\"י צדיק אחד שיוצא ממנה, שהוא הנהר המרוה אותה, דהיינו הנהר היוצא מעדן שהוא יסוד, (עי' לעיל אות ש\"י בסולם בסופו) הנקרא צדיק. ואין מי שיודע אותה חוץ ממנו, שכתוב, אלקים זולתך. וכהוא אחוז למעלה למעלה עד א\"ס."],[4,"","פירוש. \u0003עין\u0004 ה\"ס חכמה, \u0003ראיה,\u0004 ה\"ס השפעת החכמה. ואומר ב' פירושים על עין לא ראתה אלקים זולתך. א) שרומז על מלכות דאצילות הנקראת \u0003אלקים,\u0004 אשר החכמה אינה מתגלה בשום ספירה חוץ ממנה (כנ\"ל ב\"א דף רע\"ו ד\"ה ועוד). ושיעור הכתוב, \u0003עין לא ראתה,\u0004 להשפיע חכמה אל עדן שבג\"ע הארץ, זולת \u0003אלקים\u0004 שהוא מלכות, שבה מתגלה החכמה. ב) שרומז על בינה דאצילות שנקראת ג\"כ \u0003אלקים,\u0004 ושיעור הכתוב, \u0003עין לא ראתה,\u0004 להשפיע חכמה למלכות דאצילות, זולת אלקים שהוא בינה דאצילות, שממנה מתחיל השורש של אור החכמה שבמלכות, ולא מספירה אחרת. כי המלכות נבנתה מקו שמאל דבינה, שמשם מקבלת החכמה שבה."],[5,"והאי נהר דנפיק מעדן וכו':","ונהר הזה היוצא מעדן בג\"ע שלמטה, הוא סוד לחכמים, בסוד שכתוב, והשביע בצחצחות נפשך. ודבר זה מתבאר למעלה ולמטה. כי הנשמה היוצאת מעולם הזה החושך, היא משתוקקת לראות באור של עולם העליון, כאדם הזה המשתוקק לשתות מים בצמאונו, כך כל אחת ואחת היא צחצחות, כש\"א צחה צמא, כן צחצחות פירושו צחה צחות, שהיא צמאה אחר צחות האורות של הגן, והרקיע, והיכלות שבגן."],[6,"וההוא נהר וכו':","ונהר ההוא היוצא מעדן, כל אלו הנשמות יושבות בלבושי יקר על נהר ההוא, ולולא לבוש ההוא לא היו יכולות לסבול את האורות, ואז מתישבות ורוות בצחות האלו, ויכולות לסבול. ונהר ההוא הוא תקון של הנשמות להתישב ולהזון ולהנות מצחות האלו, והנשמות מתתקנות על נהר ההוא ומתישבות בו."],[7,"ההוא נהר עלאה וכו':","כמו נהר ההוא העליון, דהיינו יסוד דז\"א, מוציא נשמות ופורחות ממנו אל הגן, שהא מלכות דאצילות, כך, נהר הזה שלמטה, שבג\"ע הארץ, מתקן את הנשמות להתתקן ולהתישב בצחות האלו. בדומה לעולם הזה החיצון, שמתישבות הנפשות להאיר בריח של מים, שהוא משום שבתחלה יצאו באפן זה, כמו שאמרנו. ומשום שהנשמות מתתקנות על נהר ההוא הנמשך ויוצא מעדן, הן יכולות להתישב \u0003בצחות אלו העליונות, ולעלות למעלה,\u0004 בפתח ההוא שבאמצע הרקיע, ובעמוד אחד העומד באמצע הגן, כמו שאמרנו לעיל אות ש\"ו) ונתבאר הכתוב, והשביע בצחצחות, למעלה ולשטה, בצחצחות שלמעלה, כמ\"ש כאן. ובצחצחות שלמטה, שהן האורות של הגן והרקיעים וההיכלות כמ\"ש (באות שי\"ד) ושניהם נעשים ע\"י הנהר היוצא מעדן."]],[[0,"","כְּשֶׁעוֹלָה הַנְּשָׁמָה בְּאוֹתוֹ פֶּתַח הָרָקִיעַ לְמַעְלָה, מִזְדַּמְּנִים לָהּ לְבוּשִׁים אֲחֵרִים נִכְבָּדִים עֶלְיוֹנִים, שֶׁהֵם מֵרָצוֹן וְכַוָּנַת הַלֵּב בַּתּוֹרָה וּבִתְפִלָּה, שֶׁכְּשֶׁעוֹלֶה אוֹתוֹ רָצוֹן לְמַעְלָה, מִתְעַטֵּר בָּהּ מִי שֶׁמִּתְעַטֵּר, וְנִשְׁאָר חֵלֶק לְאוֹתוֹ אָדָם, וְנַעֲשֶׂה מִמֶּנּוּ לְבוּשִׁים שֶׁל אוֹר לְהַלְבִּישׁ בָּהֶם הַנְּשָׁמָה לַעֲלוֹת לְמַעְלָה. וְאַף עַל גַּב שֶׁבֵּאֲרוּהָ שֶׁאוֹתָם לְבוּשִׁים תְּלוּיִים בַּמַּעֲשִׂים - אֵלֶּה לֹא תְלוּיִים אֶלָּא בִּרְצוֹן הָרוּחַ, כְּמוֹ שֶׁנִּתְבָּאֵר, לַעֲמֹד בְּתוֹךְ מַלְאָכִים וְרוּחוֹת קְדוֹשׁוֹת, וְזֶהוּ בֵּרוּר הַדָּבָר. וְהַמְּנוֹרָה הַקְּדוֹשָׁה לָמַד כָּךְ מֵאֵלִיָּהוּ: הַלְּבוּשִׁים שֶׁלְּמַטָּה בַּגָּן שֶׁבָּאָרֶץ בְּמַעֲשִׂים, וְהַלְּבוּשִׁים שֶׁלְּמַעְלָה, (ברוח ורצון וכונת הלב) בְּרָצוֹן וְכַוָּנַת הָרוּחַ בַּלֵּב."],[1,"","וְנָהָר יֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן וְגוֹ' (בראשית ב), הֲרֵי פֵּרְשׁוּהָ, אֲבָל בַּגָּן הַזֶּה שֶׁלְּמַטָּה, נָהָר יֹצֵא מֵעֵדֶן וַדַּאי. וְצָרִיךְ לָדַעַת, הַנָּהָר הַזֶּה שֶׁיּוֹצֵא בַּגָּן שֶׁלְּמַטָּה, בְּאֵיזֶה מָקוֹם הוּא עִקָּרוֹ וְשָׁרְשׁוֹ. בְּאֵיזֶה מָקוֹם? בְּעֵדֶן. הָעֵדֶן הַזֶּה הוּא סוֹד עֶלְיוֹן, וְלֹא נִתְּנָה רְשׁוּת לְעֵין הַשֵּׂכֶל לִשְׁלֹט בּוֹ. וְסוֹד הַדָּבָר - אִלְמָלֵא הַמָּקוֹם הַזֶה נִמְסָר לְמַטָּה לְהִתְגַּלּוֹת, הַמָּקוֹם שֶׁל הָעֵדֶן הָעֶלְיוֹן הַקָּדוֹשׁ נִמְסָר גַּם כֵּן לָדַעַת. אֶלָּא (אבל) מִשּׁוּם הַהַסְתָּרָה שֶׁל כְּבוֹד הָעֵדֶן הָעֶלְיוֹן הַקָּדוֹשׁ, נִטְמָן וְנִגְנָז הָעֵדֶן הַתַּחְתּוֹן שֶׁאוֹתוֹ נָהָר שׁוֹפֵעַ וְיוֹצֵא מִמֶּנּוּ, וְלָכֵן לֹא נִמְסָר לְהִתְגַּלּוֹת אֲפִלּוּ לְאוֹתָן הַנְּשָׁמוֹת שֶׁבְּגַן עֵדֶן."],[2,"","כְּמוֹ שֶׁהַנָּהָר הַזֶּה נִפְרָד וְיוֹצֵא מִתּוֹךְ עֵדֶן לְהַשְׁקוֹת אֶת הַגָּן שֶׁלְּמַעְלָה, כָּךְ גַּם מִתּוֹךְ אוֹתוֹ הַפֶּתַח שֶׁל הָאֶמְצַע יוֹצֵא אוֹר אֶחָד שֶׁנִּפְרָד לְאַרְבָּעָה צְדָדִים, בְּאַרְבָּעָה פְתָחִים שֶׁאָמַרְנוּ. הַמָּקוֹם שֶׁעוֹמְדוֹת אוֹתָן הָאוֹתִיּוֹת הָרְשׁוּמוֹת. וְאוֹתוֹ הָאוֹר שֶׁנִּפְרָד לְאַרְבָּעָה אוֹרוֹת, בְּאַרְבַּע אוֹתִיּוֹת שֶׁנּוֹצְצוֹת (ויוצאות) יוֹצֵא מֵעֵדֶן, מָקוֹם שֶׁזּוֹהֶרֶת הַנְּקֻדָּה שֶׁלְּמַעְלָה."],[3,"","וְאוֹתָהּ נְקֻדָּה מְאִירָה, וְנַעֲשֶׂה עֵדֶן לְהָאִיר, וְאֵין מִי שֶׁשּׁוֹלֵט לִרְאוֹת וְלָדַעַת אֶת הַנְּקֻדָּה הַזּוֹ פְּרָט לְאוֹתוֹ אוֹר שֶׁמִּתְפַּשֵּׁט מִמֶּנָּה, שֶׁמִּשְׁתַּחֲוִים לְפָנָיו אוֹתָם הַצַּדִּיקִים שֶׁבְּגַן עֵדֶן, כְּמוֹ שֶׁנִּתְבָּאֵר. וְהַנְּקֻדָּה הַתַּחְתּוֹנָה הַזּוֹ הִיא גַּן אֶל הָעֵדֶן הָעֶלְיוֹן, הַמָּקוֹם שֶׁלֹּא נִתָּן לָדַעַת וּלְהִתְבּוֹנֵן."],[4,"","עַל כָּל זֶה כָּתוּב, (ישעיה סה) עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ. הַשֵּׁם הַזֶּה הִתְפָּרֵשׁ. אֱלֹהִים זוּלָתְךְ - זוֹ הַנְּקֻדָּה הַתַּחְתּוֹנָה הַקְּדוֹשָׁה, שֶׁהוּא יוֹדֵעַ אֶת הָעֵדֶן הַזֶּה שֶׁלְּמַטָּה שֶׁטָּמוּן בַּגָּן, וְאֵין אַחֵר שֶׁמַּכִּיר אוֹתוֹ. אֱלֹהִים זוּלָתְךְ - זֶהוּ הָעֵדֶן הָעֶלְיוֹן עַל הַכֹּל, שֶׁהוּא סוֹד הָעוֹלָם הַבָּא, שֶׁהוּא מַכִּיר אֶת הַנְּקֻדָּה הַתַּחְתּוֹנָה בְּצַדִּיק אֶחָד שֶׁיּוֹצֵא מִמֶּנּוּ, נָהָר שֶׁמַּרְוֶה אוֹתָהּ, וְאֵין מִי שֶׁמַּכִּיר אוֹתָהּ פְּרָט לוֹ, שֶׁכָּתוּב אֱלֹהִים זוּלָתְךְ, שֶׁהוּא אָחוּז לְמַעְלָה לְמַעְלָה עַד אֵין סוֹף."],[5,"","וְהַנָּהָר הַזֶּה שֶׁיּוֹצֵא מֵעֵדֶן לְמַטָּה הוּא סוֹד לַחֲכָמִים בְּסוֹד הַכָּתוּב, וְהִשְׂבִּיעַ בְּצַחְצָחוֹת נַפְשֶׁךְ. וְהַדָּבָר הַזֶּה הִתְפָּרֵשׁ לְמַעְלָה וָמַטָּה. הַנְּשָׁמָה שֶׁיּוֹצֵאת מֵעוֹלַם הַחֹשֶׁךְ הַזֶּה, הִיא תְאֵבָה לִרְאוֹת בְּאוֹר הָעוֹלָם הָעֶלְיוֹן כְּאָדָם הַזֶּה שֶׁתָּאֵב לִשְׁתּוֹת מַיִם בְּתַאֲוָה. כָּךְ כָּל אֶחָד וְאֶחָד הוּא צַחְצָחוֹת, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה ה) צִחֵה צָמָא. צָמָא, מֵאוֹתָם צָחוֹת שֶׁל אוֹרוֹת שֶׁל הַגָּן וְהָרָקִיעַ וְהַהֵיכָלוֹת שֶׁל הַגָּן."],[6,"","וְאוֹתוֹ נָהָר שֶׁיּוֹצֵא מֵעֵדֶן, כָּל אוֹתָן נְשָׁמוֹת בִּלְבוּשֵׁי כָבוֹד יוֹשְׁבוֹת עַל אוֹתוֹ נָהָר, וְאִלְמָלֵא אוֹתוֹ לְבוּשׁ, לֹא יְכוֹלִים לִסְבֹּל, וְאָז מִתְיַשְּׁבוֹת וְרָווֹת בְּאוֹתָם צָחוֹת וִיכוֹלוֹת לִסְבֹּל. וְאוֹתוֹ נָהָר הוּא תִּקּוּן הַנְּשָׁמוֹת לְהִתְיַשֵּׁב וּלְהִזּוֹן וְלֵהָנוֹת מֵאוֹתָן צָחוֹת, וְהַנְּשָׁמוֹת נֶהֱנוֹת (מתתקנות) עַל אוֹתוֹ נָהָר וּמִתְיַשְּׁבוֹת בּוֹ."],[7,"","אוֹתוֹ נָהָר עֶלְיוֹן שֶׁלְּמַעְלָה מוֹצִיא נְשָׁמוֹת, וְהֵן פּוֹרְחוֹת מִמֶּנּוּ לְתוֹךְ הַגָּן, שֶׁהַנָּהָר הַזֶּה שֶׁלְּמַטָּה בַּגָּן שֶׁבָּאָרֶץ מַתְקִין נְשָׁמוֹת לְהִתְתַּקֵּן וּלְהִתְיַשֵּׁב בְּאוֹתָן צָחוֹת. כְּמוֹ כֵן בָּעוֹלָם הַזֶּה בַּחוּץ, בְּרֵיחַ הַמַּיִם מִתְיַשֶּׁבֶת הַנֶּפֶשׁ לְהָאִיר, שֶׁהֲרֵי מֵהָעִקָּר כְּמוֹ זֶה יוֹצֵא. וּמִשּׁוּם שֶׁהַנְּשָׁמוֹת מִתְתַּקְּנוֹת עַל אוֹתוֹ נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא מֵעֵדֶן, יְכוֹלוֹת לְהִתְיַשֵּׁב בְּאוֹתָן צָחוֹת עֶלְיוֹנוֹת וְלַעֲלוֹת לְמַעְלָה בְּאוֹתוֹ פֶּתַח שֶׁבְּאֶמְצַע הָרָקִיעַ, וְעַמּוּד אֶחָד שֶׁעוֹמֵד בְּאֶמְצַע הַגָּן, כְּפִי שֶׁאָמַ רְנוּ."]]],[["בְּהַהוּא עַמּוּדָא סַלְּקִין לְעֵילָּא, בְּגּוֹ הַהוּא פִּתְחָא דִּרְקִיעָא, וּבֵיהּ סַחֲרָנֵיהּ, אִית בֵּיהּ (ישעיהו ד׳:ה׳) עָנָן וְעָשָׁן וְנֹגַהּ. וְאַף עַל גַּב דְּאוּקְמוּהָ לְהַאי קְרָא, אֲבָל עָנָן וְעָשָׁן אִלֵּין מִלְּבַר, וְנֹגַהּ מִלְּגָו. וְדָא אִיהוּ לְחַפְיָיא עַל אִינּוּן דְּסַלְּקִין לְעֵילָּא, דְּלָא יִתְחֲזוּן מִקַּמֵּי אִינּוּן דְּיַתְבִין לְתַתָּא.","וְהָא הָכָא רָזָא דְּרָזִין, כַּד (נ\"א בעי קודשא בריך הוא לאתתקנא האי נקודה וכו') הַאי נְקוּדָה בָּעָא לְאִתְתַּקְנָא בְּתִקּוּנוֹי, וּלְאִתְקַשְּׁטָא, בְּשַׁבָּתֵי וּבִזְמַנִּי וּבְחַגֵּי, מְשַׁדֵּר אַרְבַּע אַנְפִּין דְּנֶשֶׁר, וְקַיְימִין עַל הֵיכָלָא דְּאִקְרֵי דְּרוֹר, וְהַיְינוּ מָר דְּרוֹר. וּבְגִין דָּא בְּשַׁתָּא דְּיוֹבְלָא, בָּעֵינָן לְאַכְרְזָא דְּרוֹר, כְּמָה דְאַתְּ אָמֵר (ויקרא כ״ה:י׳) וּקְרָאתֶם דְּרוֹר. וְאִינּוּן אַרְבַּע אַנְפִּין יַהֲבִין קָלָא, וְלֵית מַאן דְּיִשְׁמַע לֵיהּ, בַּר אִינּוּן נִשְׁמָתִין דְּאִתְחָזוּן לְסַלְּקָא, וְאִינּוּן מִתְכַּנְּשִׁין תַּמָּן, וְנַטְלֵי לוֹן אִלֵּין ד' אַנְפִּין, וְאַעֲלִין לוֹן לְגוֹ, בְּהַהוּא עַמּוּדָא דְּקַיְּימָא בְּאֶמְצָעִיתָא.","וּבְהַהִיא שַׁעֲתָא סַלְּקָא הַהוּא עַמּוּדָא, דְעֲנָנָא וְאֶשָּׁא וּתְנָנָא, וְנֹגַהּ מִלְּגָו. וְאִלֵּין תְּרֵין אִקְרוּן, (ישעיהו ד׳:ה׳) מְכוֹן הַר צִיּוֹן וּמִקְרָאֶיהָ. מְכוֹן הַר צִיּוֹן, דָּא אִיהוּ תִּקּוּנָא דִּלְעֵילָּא, כַּד נְקוּדָה תַּתָּאָה מִתְקַשְּׁטָא, וְאִינּוּן מִקְרָאֶיהָ דְּהַהִיא נְקוּדָה לְאִתְקַשְּׁטָא.","כֵּיוָן דְּסַלְּקִין אִלֵּין נִשְׁמָתִין עַד הַהוּא פִּתְחָא דִּרְקִיעָא, כְּדֵין, הַהוּא רְקִיעָא סָחֲרָא סַחֲרָנֵי דְּגִנְתָּא, תְּלַת זִמְנִין. וּמִקָל נְעִימוּ דְּסָחֲרָא הַהוּא רְקִיעָא, נָפְקִין כָּל אִינּוּן נִשְׁמָתִין וְשַׁמְעִין הַהוּא נְעִימוּ דְּהַהוּא רְקִיעָא, וְחָמָאן הַהוּא עַמּוּדָא, דְּסַלְּקָא אֶשָּׁא וַעֲנָנָא וּתְנָנָא וְנֹגַהּ דְּלָהִיט, וְסַגְדִּין כֻּלְּהוּ. כְּדֵין נִשְׁמָתִין סַלְּקִין בְּהַהוּא פִּתְחָא, עַד דְּסַלְּקִין לְגוֹ עִגּוּלָא, דְּסַחֲרָא בְּהַהִיא (נ\"א לההוא) נְקוּדָה. כְּדֵין חָמָאן מַה דְּחָמָאן. וּמִגּוֹ נְהִירוּ וְחֶדְוָותָא מֵהַהוּא דְּחָמָאן, סַלְּקִין וְנַחְתִּין קַרְבִין וְרָחֲקִין.","וְאִיהִי תָּאִיבָא לְגַבַּיְיהוּ, וּמִתְקַשְּׁטָא בִּנְהִירוּ. כְּדֵין אַלְבִּישׁ קִנְאָה (מנהורא) חַד צַדִּיק עִלָּאָה, וְאִסְתָּכַּל בִּנְהוֹרָא וּשְׁפִירוּ דְּהַאי נְקוּדָה, וּבְתִקוּנָהָא, וְאָחִיד בָּהּ, וְסָלִיק לָהּ לְגַבֵּיהּ, וְנָהִיר נְהוֹרָא בִּנְהוֹרָא, וַהֲווּ חַד. כָּל חֵילָא דִּשְׁמַיָּיא פַּתְחֵי בְּהַהִיא שַׁעֲתָא וְאַמְרֵי, זַכָּאִין אַתּוּן צַדִּיקַיָּיא, נַטְרֵי אוֹרַיְיתָא, זַכָּאִין אִינּוּן דְּמִשְׁתַּדְּלִין בְּאוֹרַיְיתָא, דְּהָא חֶדְוָותָא דְּמָארֵיכוֹן הֲוִי בְּכוּ, דְּהָא עָטָרָא דְּמָארֵיכוֹן, מִתְעַטֵּר בְּכוֹן.","כְּדֵין כֵּיוָן דְּנַהֲרִין נְהוֹרָא בִּנְהוֹרָא, תְּרֵין נְהוֹרִין מִתְחַבְּרָן כַּחֲדָא, וְנַהֲרִין. לְבָתַר אִינּוּן גַּוְונִין נַחְתִּין, וְאִסְתַּכְּלָן לְאִשְׁתַּעְשְׁעָא בְּאִינּוּן נִשְׁמָתִין דְּצַדִּיקַיָּיא, וּמְתַקְּנִי לוֹן לְעַטְרָא לְעֵילָּא. וְעַל דָּא אִתְּמַר, עַיִן לא רָאָתָה אֱלקִים זוּלָתְךָ יַעֲשֶׂה לִמְחַכֵּה לוֹ.","פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, כְּתִיב (יחזקאל א׳:כ״ב) וּדְמוּת עַל רָאשֵׁי הַחַיָּה רָקִיעַ כְּעֵין הַקֶרַח הַנּוֹרָא נָטוּי עַל רָאשֵׁיהֶם מִלְּמָעְלָה. הַאי קְרָא אוּקְמוּהָ, אֲבָל אִית רָקִיעַ וְאִית רָקִיעַ, רָקִיעַ דִּלְתַתָּא אִיהוּ קַיְּימָא עַל גַּבֵּי ד' חֵיוָון. וּמִתַּמָּן אִתְפָּשַׁט וְשָׁארִי דִּיּוּקְנָא דְּחָד נוּקְבָּא, דְּאֲחוֹרֵי דְּכוּרָא, וְדָא אִיהוּ רָזָא דִּכְתִּיב, (שמות ל״ג:כ״ג) וְרָאִיתָ אֶת אֲחוֹרָי. כְּמָה דְאַתְּ אָמֵר, (תהילים קל״ט:ה׳) אָחוֹר וָקֶדֶם צַרְתָּנִי. וּכְתִיב (בראשית ב׳:כ״א) וַיִּקַּח אַחַת מִצַּלְעוֹתָיו.","רָקִיעַ דִּלְעֵילָּא אִיהוּ קַיְּימָא עַל גַּבֵּי חֵיוָון עִלָּאִין, וּמִתַּמָּן אִתְפָּשַׁט וְשָׁארִי דִּיּוּקְנָא דְּחָד דְּכוּרָא, דְּאִיהוּ רָזָא עִלָּאָה. וְהָנִי תְּרֵין רְקִיעִין, חַד אִקְרֵי קְצֵה הַשָּׁמַיִם. וְחַד אִקְרֵי מִקְצֵה הַשָּׁמָיִם. דִּכְתִּיב, (דברים ד׳:ל״ב) וּלְמִקְצֵה הַשָּׁמָיִם וְעַד קְצֵה הַשָּׁמָיִם. רָאשֵׁי הַחַיָּה דִּלְתַתָּא אִינּוּן אַרְבַּע חֵיוָון, דְּאִינּוּן רְשִׁימִין (נ\"א נהורין) עִלָּאִין, עַל אִינּוּן אַרְבַּע אַתְוָון רְשִׁימִין, דִּי בְּגוֹ אִינּוּן אַרְבַּע פִּתְחִין, דִּבְגִנְתָּא דְּעֵדֶן."],[[0,"בההוא עמודא סלקין וכו':","בעמוד ההוא שבאמצע הגן עולים למעלה, דרך פתח ההוא שברקיע דג\"ע, נשמות הצדיקים. ובו מסביב, יש בו ענן ועשן ונוגה. בסוה\"כ, וברא ה' על כל מכון הר ציון ועל מקראיה ענן יומם ועשן ונגה וגו', ואע\"פ שהעמידו מקרא הזה, אבל ענן ועשן אלו היו מבחוץ ונגה מבפנים, וזה היה כדי לכסות על אותם העולים למעלה, שלא יתראו לאלו היושבים למטה."],[1,"והא הכא רזא וכו':","והרי כאן סוד הסודות. כי כשנקודה הזו, דהיינו הגן, שהיא מלכות דבינה דארץ דעשיה, הנקראת נקודה, רצתה להתתקן בתקוניה ולהתקשט בשבת ובזמנים ובחגים, שולח לה הקב\"ה ד' פנים של נשר, ועומדים על ההיכל שנקרא דרור, והיינו מר דרור. ומשום זה בשנת היובל צריכים להכריז דרור, כמש\"א וקראתם דרור לכל יושביה. ואלו ד' פנים נותנים קול, דהיינו שקוראים דרור לכל יושבי הגן, ואין מי שישמע אותו, חוץ מאלו הנשמות הראויות לעלות, והם מתאספים שם בהיכל הדרור, ואלו ד' פנים לוקחים אותם ומכניסים אותם לפנים בעמוד ההוא העומד באמצע הגן."],[1,"","ביאור הדברים, בשבת ויו\"ט ור\"ח מאירים מוחין גדולים בכל העולמות, ונודע שאינם מתפשטים ממעלה למטה אלא שהתחתונים עולים במקום מדרגות העליונות ושם מקבלים המוחין ההם ולא במקומם. ובכדי שכל תחתון יוכל לעלות לעליון צריכים לפתיחת הפתחים שבאמצע הרקיעים, שדרך שם עולה התחתון למקום העליון, ופתיחה זו נעשה ע\"י ג' שמות אהיה, המורידה המלכות ממקום בינה למקומה עצמה ואז נפתח אותו הגבול של סיום החדש שהיה במקום בינה, שה\"ס הרקיע, ויכולים בינה ותו\"מ שנפלו מעליון לחזור למדרגתם והם לוקחים עמהם גם את התחתון שהיו דבוקים בו בעת נפילתם ומעלים אותו לעליון, כמו שנתבאר זה באורך לעיל (אות קל\"א) ע\"ש כל ההמשך. ורק שינוי אחד יש כאן, שמה שנקראים שם אויר, דהיינו בינה ותו\"מ דעליון, מכונה כאן עמוד דקאים באמצע גנתא, וכמו שנאמר שם שהאויר נושא את התחתון ומעלהו לעליון, נאמר כאן שעמודא דקאים באמצעיתא נושא התחתון ומעלהו לעליון. כי היינו הך."],[1,"","וזה אמרו, \u0003האי נקודה\u0004 וכו' \u0003ולאתקשטא בשבתי ובזמני וחגי,\u0004 דהיינו לקבל הארות ג' אהי' המבטלות הגבול שבסיום הרקיע, כי מחזירות המלכות משם למקומה. \u0003משדר ד' אנפין דנשר,\u0004 שהם חו\"ג תו\"מ שבקו אמצעי הנקרא פני נשר, שבחו\"ג תו\"מ אלו מלובשות ג' אהיה, שהארתן מורידה המלכות מסיום הרקיע למקומה, (כמ\"ש לעיל אות קל\"א ד\"ה והארה זו, עש\"ה) ומבטלת בזה כל הדינים והגבול מעל הגן, וז\"ש \u0003וקיימין על היכלא דאקרי דרור,\u0004 דהיינו שהארתם היא הארת דרור וחירות, ונקרא היכל דרור, המשחררת כל הדינים והגבולים מן כל המציאות שבגן, על ידי זה שמעלה אותם מסיום הרקיע ולמעלה ע\"י עמוד האמצעי שבגן כנ\"ל, והארה זו דומה להארת היובל שנאמר בו וקראתם דרור לכל יושביה, אף כאן \u0003ואינון ארבע אנפין יהבין קלא,\u0004 דהיינו קריאת הדרור לכל יושבי הגן, שנתבטלו כל הדינים, והגבול, וכל אחד יכול לעלות למעלה עם עמודא דקיימא באמצעיתא, \u0003ולית מאן דישמע ליה בר אינון נשמתין דאתחזון לסלקא\u0004 ואותן שאינן ראויות לעלות אינן מרגישות כלל מן דרור הזה. \u0003ואינון מתכנשין תמן\u0004 בהיכל הדרור, \u0003ונטלי לון אלין ד' אנפין ואעלין לון לגו בההוא עמודא דקיימא באמצעיתא\u0004 דהיינו שמתחברות בבינה ותו\"מ דרקיעים הנפולים ונעוצים בגן. (כנ\"ל אות ש\"ו) שעם עמוד הזה עולות מרקיע ולמעלה כפי מדרגתן. שה\"ס ושבתם איש אל אחוזתו."],[2,"ובההיא שעתא סלקא וכו':","ובשעה ההיא מעלה עמוד ההוא ענן ואש ועשן ונגה מבפנים, ושנים אלו הארת הדרור והנשמות, נקראים, מכון הר ציון ומקראיה, שעליהם אומר הכתוב וברא ה' על כל מכון הר ציון ועל מקראיה ענן ימם עשן ונגה אש להבה לילה וגו', \u0003כי מכון הר ציון,\u0004 היא תקון שלמעלה כשנקודה התחתונה מתקשטת, דהיינו הארת הדרור ע\"י ד' אנפין דנשר שלמעלה. והן, הנשמות, הן מקראיה של נקודה ההיא, להתקשט, דהיינו אותן הנשמות ששמעו קריאת הדרור, נקראות מקראיה. מלשון קרואיה."],[2,"","פירוש. כי נתבאר לעיל (אות ק\"ל ד\"ה וזה שאומר באות קכ\"ג) שאע\"פ שהמלכות ירדה ממקום בינה למקומה עוד לא נתבטל משם הסיום והגבול שנעשה בסבת עלית המלכות, כי קו אמצעי מקיים את הגבול בכח מסך דחירק שבו, והבינה ותו\"מ שמתחברים למדרגתם אינם מתחברים בעמדם למטה מסיום החדש, אלא מוכרחים לעלות למעלה מסיום החדש ולהעשות קו שמאל לכתר וחכמה שנשארו במדרגה, עש\"ה. (וכמ\"ש באורך לעיל אות רצ\"ב ד\"ה ביאור הדברים)."],[2,"","ואלו הדינים הנמשכים מקיום הגבול ע\"י מסך דחירק שבקו אמצעי נקראים \u0003עננא ואשא ותננא ונגה,\u0004 שבסבתם אין הארת הדרור נמשכת מסיום הרקיעים ולמטה לתוך הגן, אלא שמאירה מסיום הרקיעים ולמעלה, וע\"כ מחויבים הנשמות יושבי הגן, לעלות עם עמודא דקיימא באמצעיתא לתוך הרקיע ושם מקבלים הארתן."],[2,"","וז\"ש למעלה (באות שי\"ז) \u0003בההוא עמודא\u0004 וכו' \u0003וביה סחרניה אית ביה ענן ועשן ונגה\u0004 וכו' \u0003ודא איהו לחפיא על אינון דסלקין לעילא דלא יתחזון מקמי אינון דיתבין לתתא\u0004 כי אם היה הגבול מתבטל לגמרי והארת הרקיעים היה נמשך למטה לגן, אז היו כל הנשמות מקבלים הארה העליונה, בלי צורך לשום הכנה. אבל עתה כשמתקיים הגבול ע\"י ענן ועשן וכו' אין הארה העליונה מתפשטת למטה אלא שהנשמות צריכות לעלות עם העמוד למעלה לרקיע. ע\"כ הנשמות שאינן ראויות לזה אינן יודעות כלום מהארת הדרור, ואינן עולות, ורק הנשמות הראויות לזה שומעות כרוז מהארת הדרור ועולות. נמצא שקיום הגבול שנעשה ע\"י ענן ועשן ונגה, מכסה על אותן הנשמות שאינן ראויות שאינן יודעות מעליות הנשמות הראויות למעלה. משום שהאור לא נמשך כלום למקום הנשמות למטה. וז\"ש, \u0003ודא איהו לחפיא על אינון דסלקין לעילא\u0004 וכו', וז\"ש כאן, \u0003ובההיא שעתא סלקא ההוא עמודא דעננא ואשא ותננא\u0004 וגו'. שמשום זה לא יוכל העמוד להשאר למטה, כי לא יוכל להתחבר עם כתר וחכמה דרקיעים עד שיעלה למעלה מסיום הרקיעים, נמצא שענן ואש ועשן הם מכריחים את העמוד, שהוא בינה ותו\"מ שנפלו מרקיעים, שלא יעמוד במקומו אלא עולה למעלה, ואז הוא לוקח עמו כל הנשמות שבגן הראויות לזה ומעלה אותן עמו למעלה לרקיעים. וז\"ש \u0003ואינון מתכנשין\u0004 וכו' \u0003בההוא עמודא\u0004 וכו', ובכדי שהעמוד יעלה למעלה לרקיעים, \u0003סלקא ההוא עמודא דעננא ואשא ותננא ונגה מלגו.\u0004 שמחמת זה הוא מוכרח לעלות למעלה, ולוקח עמו הנשמות. אמנם צריכים לזכור שאין העדר ברוחני, ואע\"פ שהעמוד עולה למעלה, נבחן ג\"כ שנשאר למטה כמו שהיה. וע\"כ נבחן שעמוד הזה נעוץ תמיד בגן, אע\"פ שעולה למעלה."],[2,"","וזה שיעור הכתוב, \u0003וברא ה',\u0004 דהיינו בקו האמצעי, במסך דחירק שבו, \u0003על כל מכון הר ציון,\u0004 שהיא הארת הדרור. \u0003ועל מקראיה,\u0004 שהן הנשמות הזוכות לשמוע הקריאה של הדרור, \u0003ענן יומם ועשן\u0004 וגו'. שיגבילו שאורות עליונים ומלמעלה ברקיע לא ימשכו למטה. שבזה נעלמת הארת הדרור מן הנשמות שאינן ראויות. כמבואר."],[3,"כיון דסלקין אלין וכו':","כיון שעולות הנשמות עד פתח ההוא שברקיע, אז רקיע ההוא מסבב עצמו מסביב הגן ג' פעמים, דהיינו שהרקיע נוסע בג' דוכתי, בסוד ג' קוין, שעיקר הארתם הוא רק בעת הנסיעה (כנ\"ל בשלח דף ל\"ט ד\"ה וג'). ומקול הנעימות של סבוב הרקיע על ג' הקוין, יוצאות כל הנשמות שבפתח הרקיע, ושומעות נעימות ההיא של הרקיע, ורואות את עמוד ההוא שהעלה אותן, שהוא מעלה אש וענן ועשן ונגה הלוהט, דהיינו הדינים הלוהטים ממסך דחירק שבקו אמצעי המקיים את הגבול באופן שלא ימשכו האורות ממעלה למטה, כנזכר לעיל בדבור הסמוך, אלא ממטה למעלה בלבד, וכולן משתחוות. כלומר שמרכינות ראשן שזה יורה שמקבלות הגבול שלא ימשכו ממעלה למטה, שהוא בחי' ג\"ר המכונה \u0003ראש,\u0004 אלא שממעטות ראשן, שלא יקבלו האור רק בבחינת ממטה למעלה, שהוא הארת ו\"ק דחכמה ולא ג\"ר דחכמה. ואחר שהנשמות קבלו עליהן את הגבול שלא ימשכו אלא ממטה למעלה, אז עולות הנשמות דרך פתח ההוא, עד שעולות לתוך העגול המסבב נקודה ההיא, דהיינו לתוך הרקיע, המסבב את הגן הנקרא נקודה, שרקיע הזה ה\"ס החכמה, אז רואות מה שרואות דהיינו שמקבלות הארת חכמה הנקראת ראיה, ומתוך האורה והשמחה ממה שרואות, הן עולות ויורדות מתקרבות ומתרחקות, בסוד רצוא ושוב."],[4,"ואיהי תאיבא לגבייהו וכו':","והחכמה שה\"ס נקודה עלאה, משתוקקת אליהן, ומתקשטת בהן באורה, כלומר, שהנשמות שעלו אליה נעשות בה לבחינת מ\"ן, אז הלביש קנאה צדיק אחד עליון, דהיינו יסוד דעולם היצירה, ומסתכל באור ויופי של נקודה הזו ובתקוניה, ואוחז בה ומעלה אותה אליו, ליצירה, ומאיר אור באור, דהיינו אור החסדים שביסוד מאיר באור החכמה שבנקודה, ונעשו אחד. כלומר שמתחברים. כל צבאות השמים פותחים ואומרים בשעה ההיא, אשריכם צדיקים שומרי התורה, אשריכם שאתם עוסקים בתורה, כי שמחת אדונכם הוא בכם, כי עטרת אדונכם מתעטר בכם. כי הם שגרמו לזווג ההוא. ומ\"ש, \u0003אלביש קנאה חד צדיק.\u0004 הפירוש הוא, שאז האהבה בתכלית השלמות, כמ\"ש לעיל (פרשת ויחי אות תשל\"ג) \u0003כל מאן דרחים ולא קשיר עמו קנאה, לאו רחימותיה רחימותא.\u0004 ומהות הקנאה הוא, שלא יתאחזו בה החצונים, מחמת חסרון חסדים."],[5,"כדין כיון דנהרין וכו':","אז כיון שמאירים אור באור, דהיינו אור החסדים באור החכמה, ב' האורות מתחברים יחד ומאירים. אח\"כ אלו גוונים, דהיינו האורות של הזווג הזה, יורדים ומסתכלים להשתעשע באלו נשמות הצדיקים, שעלו למ\"ן כנ\"ל, ומתקנים אותם שיתעטרו למעלה. ועל זה נאמר, עין לא ראתה אלקים זולתך יעשה למחכה לו."],[6,"פתח ר\"ש ואמר וכו':","פר\"ש ואמר כתיב, ודמות על ראשי החיה רקיע כעין הקרח הנורא נטוי על ראשיהם מלמעלה. מקרא זה העמידוהו. אבל יש רקיע ויש רקיע, רקיע שלמטה, היינו הפרסא שבמקום החזה דז\"א, עומד על ד' חיות, שהם ד' חיות שבמלכות, שה\"ס מיכאל גבריאל רפאל נוריאל. ומשם מרקיע הזה, שהוא פרסא דז\"א, מתפשטת ושורה צורת נוקבא אחת שהיא מלכות באחורי הדכר, שהוא ז\"א, וזה הוא סוד וראית את אחורי, שפירושו המלכות שהוא באחורי ז\"א. כמש\"א אחור וקדם צרתני, שרומז על ז\"א ומלכות, שז\"א הוא קדם ומלכות היא אחור. וכן כתוב, ויקח אחת מצלעותיו, שרומז על ז\"א ומלכות שהיו תחילה דו פרצופין אחור וקדם, וננסרו, שעל זה רומז ויקח אחת מצלעותיו."],[7,"רקיע דלעילא איהו וכו':","הרקיע שלמעלה, שהוא הפרסא, שבמקום החזה דבינה, שהיא ישסו\"ת, הוא עומד על חיות עליונות, שהן חג\"ת דז\"א, ומשם, מן הרקיע הזה, מתפשטת ושורה צורת דכר אחד, שהוא סוד עליון על הנוקבא, דהיינו ז\"א. ואלו שני רקיעים, אחד נקרא \u0003קצה השמים\u0004 דהיינו הפרסא שבמקום החזה דז\"א, שהיא קצה וסיום של ז\"א הנקרא שמים. ואחד נקרא \u0003מקצה השמים,\u0004 דהיינו הפרסא שבחזה דבינה, שמשם מתחיל ז\"א הנקרא שמים. שכתוב, ולמקצה השמים ועד קצה השמים. ראשי החיה שלמטה, במלכות הם ד' חיות שהם אורות עליונים על אלו ד' אותיות הרשומות בד' פתחים אלו שבגן עדן. (כנ\"ל אות רצ\"ה ורצ\"ט בהסולם ע\"ש) וארבע חיות אלו ה\"ס ד' מלאכים כנ\"ל בסמוך."],[7,"","פירוש. כבר ידעת שרקיע פירושו סיום החדש שנקבע באמצע המדרגה מחמת שעלתה המלכות דכל מדרגה לבינה דכל מדרגה. (כמ\"ש לעיל אות רצ\"ב ד\"ה ביאור) וסיום הזה נקרא ג\"כ פרסא שבגוי מעוהי, העומדת באמצע הת\"ת שה\"ס בינה דגוף, במקום החזה, דהיינו באמצע המדרגה, ושם מסיימת המדרגה. ופרסא זו, כוללת בתוכה ג' הספירות חצי ת\"ת ונה\"י, שה\"ס בינה ותו\"מ שנפלו מכל מדרגה למדרגה שמתחתיה. (עי' לעיל אות ש\"י ד\"ה וצריך). וע\"כ כל תחתון מלביש ג' ספירות נה\"י דעליון, כי נפלו למקומו מחמת הסיום שנקבע במקום הפרסא. וז\"ס אשר ז\"א מלביש מפרסא שבאמצע ישסו\"ת ולמטה, דהיינו חצי ת\"ת ונה\"י שלהם, להיותם בחינת בינה ותו\"מ דישסו\"ת שנפלו למקומו. שמחמת אין העדר ברוחני, נשארו שם בקביעות. ועד\"ז המלכות מלבשת מפרסא שבאמצע ז\"א ולמטה, דהיינו חצי ת\"ת ונה\"י שלו, שנפלו מז\"א למקומה. ונמצא שז\"א מתחיל ברקיע דישסו\"ת, שהיא הפרסא שבאמצעו, וה\"ס \u0003רקיע העליון,\u0004 ומסתיים ברקיע של עצמו, שהוא הפרסא שבאמצעו של ז\"א, כי משם ולמטה הוא מלובש במלכות, וזה נקרא \u0003רקיע התחתון.\u0004 וזסו\"ה, ולמקצה השמים עד קצה השמים. אשר ולמקצה השמים, היא רקיע דישסו\"ת שמשם מתחיל ז\"א הנקרא שמים. וקצה השמים, הוא רקיע של ז\"א ששם הוא מסתיים."]],[[0,"","בְּאוֹתוֹ עַמּוּד עוֹלִים לְמַעְלָה בְּתוֹךְ אוֹתוֹ פֶּתַח שֶׁל הָרָקִיעַ, וּבוֹ סְבִיבוֹ יֵשׁ בּוֹ (ישעיה ד) עָנָן (יומם) וְעָשָׁן נֹגַהּ. וְאַף עַל גַּב שֶׁבֵּאֲרוּהוּ לְזֶה הַפָּסוּק, אֲבָל עָנָן וְעָשָׁן אֵלּוּ מִבַּחוּץ, וְנֹגַהּ מִבִּפְנִים. וְזֶה הוּא לְחַפּוֹת עַל אֵלּוּ שֶׁעוֹלִים לְמַעְלָה, שֶׁלֹּא יֵרָאוּ מִלִּפְנֵי אֵלּוּ שֶׁיּוֹשְׁבִים לְמַטָּה."],[1,"","וַהֲרֵי כָּאן סוֹד הַסּוֹדוֹת. כַּאֲשֶׁר (רוצה הקדוש ברוך הוא לתקן הגקדה הזו) הַנְּקֻדָּה הַזּוֹ רוֹצָה לְהִתְתַּקֵּן בְּתִקּוּנֶיהָ וּלְהִתְקַשֵּׁט בְּשַׁבָּתוֹת וּזְמַנִּים וּבְחַגִּים, שׁוֹלַחַת אַרְבַּע פְּנֵי נֶשֶׁר, וְעוֹמְדִים עַל הַהֵיכָל שֶׁנִּקְרָא דְּרוֹר, וְהַיְנוּ מָר דְּרוֹר. וּבִגְלַל כָּךְ בִּשְׁנַת הַיּוֹבֵל צְרִיכִים לְהַכְרִיז דְּרוֹר, כְּמוֹ שֶׁנֶּאֱמַר (ויקרא כה) וּקְרָאתֶם דְּרוֹר. וְאוֹתָם אַרְבַּע פָּנִים נוֹתְנִים קוֹל, וְאֵין מִי שֶׁיִּשְׁמַע אוֹתוֹ פְּרָט לְאוֹתָן הַנְּשָׁמוֹת הָרְאוּיוֹת לַעֲלוֹת, וְהֵן מִתְכַּנְּסוֹת שָׁם, וְלוֹקְחִים אוֹתָם אַרְבַּע הַפָּנִים הַלָּלוּ, וּמַכְנִיסִים אוֹתָם פְּנִימָה בְּאוֹתוֹ עַמּוּד שֶׁעוֹמֵד בָּאֶמְצַע."],[2,"","וּבְאוֹתָהּ שָׁעָה עוֹלֶה אוֹתוֹ עַמּוּד, עָנָן וְאֵשׁ וְעָשָׁן, וְנֹגַהּ מִבִּפְנִים. וּשְׁנֵי אֵלֶּה נִקְרָאִים מְכוֹן הַר צִיּוֹן וּמִקְרָאֶיהָ. מְכוֹן הַר צִיּוֹן - זֶהוּ הַתִּקּוּן שֶׁלְּמַעְלָה, כְּשֶׁהַנְּקֻדָּה הַתַּחְתּוֹנָה מִתְקַשֶּׁטֶת, וְהֵם מִקְרָאֶיהָ שֶׁל אוֹתָהּ נְקֻדָּה לְהִתְקַשֵּׁט."],[3,"","כֵּיוָן שֶׁעוֹלוֹת הַנְּשָׁמוֹת הַלָּלוּ עַד לְאוֹתוֹ פֶּתַח הָרָקִיעַ, אֲזַי אוֹתוֹ רָקִיעַ סוֹבֵב סְבִיב הַגָּן שָׁלֹשׁ פְּעָמִים, וּמִקּוֹל נְעִימוּת שֶׁל סִבּוּב אוֹתוֹ רָקִיעַ יוֹצְאוֹת כָּל אוֹתָן נְשָׁמוֹת וְשׁוֹמְעוֹת אוֹתוֹ נֹעַם שֶׁל אוֹתוֹ רָקִיעַ, וְרוֹאִים אוֹתוֹ הָעַמּוּד שֶׁמַּעֲלֶה אֵשׁ וְעָנָן וְעָשָׂן וְנֹגַהּ שֶׁלּוֹהֵט, וְכֻלָּם מִשְׁתַּחֲוִים. וְאָז הַנְּשָׁמוֹת עוֹלוֹת בְּאוֹתוֹ הַפֶּתַח, עַד שֶׁעוֹלִים לְתוֹךְ הָעִגּוּל שֶׁסּוֹבֵב בְּאוֹתָהּ נְקֻדָּה, וְאָז רוֹאִים מַה שֶּׁרוֹאִים. וּמִתּוֹךְ הָאוֹר וְהַשִּׂמְחָה מִמַּה שֶּׁרָאוּ, עוֹלִים וְיוֹרְדִים, מִתְקָרְבִים וּמִתְרַחֲקִים."],[4,"","וְהִיא מִשְׁתּוֹקֶקֶת אֲלֵיהֶם וּמִתְקַשֶּׁטֶת בְּאוֹר. וְאָז לוֹבֵשׁ קִנְאָה (מאור) צַדִּיק עֶלְיוֹן אֶחָד, וּמִסְתַּכֵּל בָּאוֹר וְיֹפִי שֶׁל הַנְּקֻדָּה הַזּוֹ וּבְתִקּוּנֶיהָ, וְאוֹחֵז בָּהּ וּמַעֲלֶה אוֹתָהּ אֵלָיו, וּמֵאִיר אוֹר בְּאוֹר וְנִהְיִים אֶחָד. וְכָל חֵילוֹת הַשָּׁמַיִם פּוֹתְחִים בְּאוֹתָהּ שָׁעָה וְאוֹמְרִים: אַשְׁרֵיכֶם הַצַּדִּיקִים שׁוֹמְרֵי הַתּוֹרָה, אַשְׁרֵיהֶם הַמִּשְׁתַּדְּלִים בַּתּוֹרָה, שֶׁהֲרֵי שִׂמְחַת אֲדוֹנְכֶם הִיא בָכֶם, שֶׁהֲרֵי עֲטֶרֶת רִבּוֹנְכֶם מִתְעַטֶּרֶת בָּכֶם."],[5,"","וְאָז, כֵּיוָן שֶׁמְּאִירִים אוֹר בְּאוֹר, שְׁנֵי אוֹרוֹת מִתְחַבְּרִים כְּאֶחָד וּמְאִירִים. אַחַר כָּךְ יוֹרְדִים אוֹתָם גְּוָנִים וּמִתְבּוֹנְנִים לְהִשְׁתַּעֲשֵׁעַ בְּאוֹתָן נִשְׁמוֹת הַצַּדִּיקִים, וּמְתַקְּנִים אוֹתָם לְעַטֵּר לְמַעְלָה. וְעַל זֶה נֶאֱמַר עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ יַעֲשֶׂה לִמְחַכֵּה לוֹ."],[6,"","פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, כָּתוּב (יחזקאל א) וּדְמוּת עַל רָאשֵׁי הַחַיָּה רָקִיעַ כְּעֵין הַקֶּרַח הַנּוֹרָא נָטוּי עַל רָאשֵׁיהֶם מִלְמָעְלָה. פָּסוּק זֶה פֵּרְשׁוּהוּ. אֲבָל יֵשׁ רָקִיעַ וְיֵשׁ רָקִיעַ. הָרָקִיעַ שֶׁלְּמַטָּה הוּא עוֹמֵד עַל גַּבֵּי אַרְבַּע חַיּוֹת, וּמִשָּׁם מִתְפַּשֵּׁט וּמַתְחִיל דְּיוֹקָן שֶׁל נְקֵבָה אַחַת שֶׁאֲחוֹרֵי הַזָּכָר, וְזֶהוּ סוֹד הַכָּתוּב (שמות לג) וְרָאִיתָ אֶת אֲחֹרָי, כְּמוֹ שֶׁנֶּאֱמַר (תהלים לט) אָחוֹר וָקֶדֶם צַרְתָּנִי. וְכָתוּב (בראשיתב) וַיִּקַּח אַחַת מִצַּלְעֹתָיו."],[7,"","הָרָקִיעַ שֶׁלְּמַעְלָה הוּא עוֹמֵד עַל גַּבֵּי הַחַיּוֹת הָעֶלְינוֹת, וּמִשָּׁם מִתְפַּשֵּׁט וּמַתְחִיל הַדְּיוֹקָן שֶׁל זָכָר אֶחָד, שֶׁהוּא סוֹד עֶלְיוֹן. וּשְׁנֵי הָרְקִיעִים הַלָּלוּ, אֶחָד נִקְרָא קְצֵה הַשָּׁמַיִם, וְאֶחָד נִקְרָא מִקְצֵה הַשָּׁמַיִם, שֶׁכָּתוּב (דברים ד) וּלְמִקְצֵה הַשָּׁמַיִם וְעַד קְצֵה הַשָּׁמָיִם. רָאשֵׁי הַחַיָּה שֶׁלְּמַטָּה הֵם אַרְבַּע חַיּוֹת, שֶׁהֵן רְשׁוּמוֹת (אורות) עֶלְיוֹנוֹת עַל אוֹתָן אַרְבַּע אוֹתִיּוֹת רְשׁוּמוֹת שֶׁבְּתוֹךְ אוֹתָם אַרְבָּעָה פְתָחִים שֶׁבְּגַן עֵדֶן."]]],[["וְאַף עַל גַּב דְּאַמָרָן עֵדֶן דִּלְתַתָּא בְּאַרְעָא, הָכִי הוּא וַדַּאי. אֲבָל כֹּלָּא רָזָא עִלָּאָה אִיהוּ, כְּמָה דְּאִתְּמַר דְּהַאי נְקוּדָה דְּקָאָמַרָן, כְּמָה דְּאִית לָהּ חוּלָקָא לְעֵילָּא, הָכִי נָמֵי אִית לָהּ חוּלָקָא לְתַתָּא בְּאַרְעָא. וְהַאי גִּנְתָּא לְתַתָּא, אִיהוּ חוּלָקָא דְּהַהִיא נְקוּדָה לְאִשְׁתַּעְשְׁעָא בְּרוּחֵי דְּצַדִּיקַיָּיא בְּאַרְעָא, וְאִתְהֲנֵי בְּכָל סִטְרִין לְעֵילָּא (ויצא קנ\"ז ע\"ב) וְתַתָּא. לְעֵילָּא בְּצַדִּיק. לְתַתָּא בְּהַהוּא אִיבָּא דְּצַדִּיק, וְלָא אִשְׁתְּכַח שַׁעְשׁוּעָא עֵילָּא וְתַתָּא אֶלָּא בְּצַדִּיק. וְהַאי גִּנְתָּא אִיהוּ, מֵהַהִיא נְקוּדָה דְּאִקְרֵי עֵדֶן (נקודה דנטלא מאימא עילאה טמירא איהי גן עדן דארעא).","אִינּוּן רָאשֵׁי הַחַיָּה, אִלֵּין אַרְבַּע רֵישֵׁי אַנְפִּין. חַד אַרְיֵה, דִּכְתִּיב, (יחזקאל א׳:י׳) וּפְנֵי אַרְיֵה אֶל הַיָּמִין. וְחַד שׁוֹר, דִּכְתִּיב וּפְנֵי שׁוֹר מֵהַשְּׂמֹאל. וְחַד נֶשֶׁר, דִּכְתִּיב וּפְנֵי נֶשֶׁר לְאַרְבַּעְתָּן. אָדָם כְּלָלָא דְּכֹלָּא, דִּכְתִּיב וּדְמוּת פְּנֵיהֶם פְּנִי אָדָם. וְאִלֵּין אַרְבַּע רֵישֵׁי נַהֲרִין דְמָטוּלֵיהוֹן (ס\"א חיוון דנטלין) לְכוּרְסְיָיא קַדִּישָׁא, וּמִגּוֹ מָטוּלָא דִּילְהוֹן זָעִין. וּמֵהַהוּא זִיעָא דְּמָטוּלָא דִּילְהוֹן, אִתְעָבִיד הַהוּא נָהָר דִּי נוּר. דִּכְתִּיב, (דניאל ז׳:י׳) נְהַר דִּי נוּר נָגֵד וְנָפֵק מִן קֳדָמוֹהִי אֶלֶף אַלְפִין יְשַׁמְשׁוּנִהּ.","וְנִשְׁמָתִין כַּד סַלְּקִין, אִתְסַחְיָין בְּהַהוּא נָהָר דִּי נוּר, וְסַלְּקִין לְקוּרְבְּנָא וְלָא אִתּוֹקְדָן, אֶלָּא אִתְסַחְיָין. תָּא חֲזֵי מִסַּלָּמַנְדְּרָא, דְּעַבְדִין מִנָּהּ לְבוּשָׁא. וּמִגּוֹ דְּאִיהִי מִנּוּרָא, לָא אִתְסַחְיָיא הַהוּא לְבוּשָׁא, אֶלָּא בְּנוּרָא, אֶשָּׁא אָכִיל זוּהֲמָא דְּבֵיהּ, וְאִתְסַחֵי הַהוּא לְבוּשָׁא. הָכִי נָמֵי נִשְׁמְתָא דִּי נוּר דְּאִתְנְטִילַת מִגּוֹ כּוּרְסְיָּיא קַדִּישָׁא. דִּכְתִיב בָּהּ (דניאל ז׳:ט׳) כָּרְסְיֵהּ שְׁבִיבִין דִּי נוּר. בְּזִמְנָא דְּבַעְיָיא לְאִתְסַחְיָיא מֵהַהוּא זוּהֲמָא דְּבָהּ, אִתְעַבְּרַת בְּנוּרָא וְאִתְסַחְיָיא. וְנוּרָא אַכְלָא כָּל הַהוּא זוּהֲמָא דִּי בְּנִשְׁמְתָא. וְנִשְׁמְתָא אִתְסַחְיָיא וְאִתְלַבְּנַת.","וְאִי תֵּימָא אִי הָכִי עוֹנְשָׁא לֵית לָהּ לְנִשְׁמְתָא בְּהַאי. תָּא חֲזֵי, וַוי לְנִשְׁמְתָא דְּסַבְלָת אֶשָּׁא נוּכְרָאָה, וְאַף עַל גַּב דְּאִיהִי אִתְלַבְּנָא. אֲבָל כַּד זוּהֲמָא אִיהוּ סַגִּי עָלָהּ, וַוי לְנִשְׁמְתָא דְּסַבְלַת הַהוּא עוֹנְשָׁא, בְּגִין דְּהַהוּא זוּהֲמָא בִּתְרִי זִמְנֵי אִתְלַבְּנַת בְּנוּרָא.","זִמְנָא קַדְמָאָה כֵּיוָן דְּקַבִּילַת עוֹנְשָׁא בְּגוּפָא, אַזְלָא נִשְׁמְתָא, וְנַטְלֵי לָהּ, וְאַעֲלִין לָהּ בְּגוֹ אֲתָר חַד דְּאִקְרֵי בֶּן הִנֹּם, וַאֲמַאי אִקְרֵי בֶּן הִנֹּם. אֶלָּא אֲתָר חַד אִיהוּ בְּגֵיהִנָּם, דְּתַמָּן אִתְצְרִיפוּ נִשְׁמָתִין, בְּצִרוּפָא, לְאִתְלַבְּנָא עַד לָא עָאלִין בְּגִנְתָּא דְּעֵדֶן. (ואי זכאין אינון נשמתין כד אעלין לון בההוא אתר) תְּרֵין מַלְאֲכִין שְׁלִיחָן זְמִינִין בְּגִנְתָּא דְּעֵדֶן, וְקַיְימִין לְתַרְעָא, וְצַוְוחִין לְגַבֵּי אִינּוּן מְמָנָן דִּבְהַהוּא אֲתָר דְּגֵיהִנָּם, בְּגִין לְקַבְּלָא הַהִיא נִשְׁמְתָא.","וְהַהִיא נִשְׁמְתָא עַד לָא אִתְלַבְּנַת בְּנוּרָא, אִינּוּן שְׁלִיחָן צַוְוחִין לְגַבַּיְיהוּ, וְאַמְרֵי הִנֹּם. וּבְזִמְנָא דְּהִיא אִתְלַבְּנַת, אִינּוּן מְמָנָן נָפְקִין עִמָּהּ מֵהַהוּא אֲתָר, וּזְמִינִי לָהּ לְגַבֵּי פִּתְחָא דְּגִּנְתָּא דְּעֵדֶן, דְּתַמָּן אִינּוּן שְׁלִיחָן וְאַמְרֵי לוֹן הִנֹּם. הָא אִינּוּן נִשְׁמָתִין דְּהָא אִתְלַבְּנוּ, כְּדֵין אַעְלִין לְהַהִיא נִשְׁמְתָא בְּגִנְתָּא דְּעֵדֶן.","וְכַמָּה אִיהִי תְּבִירָא מִגּוֹ הַהוּא תְּבִירוּ דְּאִתְלַבְּנוּתָא דְּגֵיהִנָּם. (ס\"א דהוא) דְּהַהִיא תְּבִירוּ דְּאֶשָּׁא תַּתָּאָה. וְאַף עַל גַּב דְּנָחִית מִלְעֵילָּא, (אבל) כֵּיוָן דְּמָטָא לְאַרְעָא לְתַתָּא, אִיהוּ אֶשָּׁא דְּלָא דָּקִיק, וְנִשְׁמְתָא אִתְעַנְשָׁא בֵּיהּ, וְאִתְבָּרַת. כְּדֵין קוּדְשָׁא בְּרִיךְ הוּא אַפִּיק שִׁמְשָׁא דְּנָהִיר מֵאִינּוּן אַרְבַּע פִּתְחִין דְּנָהֲרִין בִּרְקִיעָא דְּעַל גִּנְתָּא, וּמָטָא לְהַהִיא נִשְׁמְתָא וְאִתְּסִיאַת. הֲדָא הוּא דִכְתִיב, (מלאכי ג׳:כ׳) וְזָרְחָה לָכֶם יִרְאֵי שְׁמִי שֶׁמֶשׁ צְדָקָה וּמַרְפֵּא בִּכְנָפֶיהָ.","זִמְנָא תִּנְיָינָא, לְבָתַר דְּיָתְבָא בְּגִנְתָּא דְּעֵדֶן דִּלְתַתָּא, כָּל הַהוּא זִמְנָא דְּיָתְבָא וְעַד כְּעַן לָא אִתְפָּרְשַׁת מֵאִינּוּן מִלִּין דְּחֵיזוּ דְּהַאי עָלְמָא מִכֹּל וָכֹל. וְכַד סַלְּקִין לָהּ לְעֵילָּא, אִצְטְרִיךְ לְאִתְפָּרְשָׁא, מִכָּל חֵיזוּ וּמִכָּל מִלִּין דִּלְתַתָּא. וְאַעְבְּרוּ לָהּ בְּהַהוּא נְהַר דִּי נוּר, כְּדֵין נִשְׁמְתָא אִתְלַבְּנַת בֵּיהּ מִכֹּל וָכֹל. וְנַפְקַת וְאִתְחֲזִיאַת קַמֵּי מָארֵי דְּעָלְמָא בְּרֵיכָא (ד\"א ברירא) מִכָּל סִטְרִין. כֵּיוָן דְּאִסְתַּכְּלַת בְּהַהוּא נְהוֹרָא אַתְּסִיאַת וְאִשְׁתְּלִימַת מִכֹּלָּא. וּכְדֵין קַיְימִין אִינּוּן נִשְׁמָתִין בִּלְבוּשִׁין, מִתְעַטְּרִין קַמֵּי מָארֵיהוֹן. זַכָּאָה חוּלָקֵיהוֹן דְּצַדִּיקַיָּיא בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי."],[[0,"ואע\"ג דאמרן עדן וכו':","ואע\"פ שאמרנו שעדן שלמטה היא בארץ, והגן מקבל מעדן שלמטה. ואתה אומר שהגן מקבל מארבע חיות. ומשיב, אבל הכל הוא סוד עליון, כמו שלמדנו. כי נקודה זו שאמרנו, דהיינו מלכות דאצילות, כמו שיש לה חלק למעלה באצילות, כן יש לוק חלק למטה בארץ, דהיינו כמו שהיא חלק העשירי באצילות כן היא חלק העשירי בארץ, דהיינו הגן, והגן שלמטה הוא חלק הנקודה הזו שבארץ, להשתעשע ברוחות הצדיקים בארץ, ונהנית מכל הצדדים, למעלה ולמטה, למעלה נהנית מצדיק, שהוא יסוד דז\"א, למטה נהנית מפריו של הצדיק, שהם הנשמות של הצדיקים הנולדות מיסוד דז\"א, ולא נמצא שעשוע למעלה ולמטה אל המלכות אלא בצדיק. כי פריו נחשבים ג\"כ לבחינת צדיק כמוהו. וע\"כ כמו שמלכות שלמעלה רוכבת על ד' חיות, כן המלכות שלמטה, שהיא הגן, מקבלת מד' חיות כמו שאמרנו, וגן הזה היא נמשך מנקודה ההיא שנקראת עדן. דהיינו ג\"כ כמו מלכות שלמעלה, כי נבחנת לחכמה תתאה משום שנמשכת מעדן העליון, כן הגן שהיא מלכות שלמטה נמשכת מעדן התחתון. באפן שמקבל משניהם, אלא ד' חיות הן מעצם המלכות, ועדן הוא אור העליון הנמשך למלכות, הן למעלה והן למטה."],[1,"אינון ראשי החיה וכו':","ראשי החיה אלו הן ד' ראשי פנים, אחד הוא אריה, שכתוב, ופני אריה אל הימין. שהוא חסד, דהיינו מיכאל. ואחד שור, שכתוב, ופני שור מהשמאל, שהוא גבורה, דהיינו גבריאל. ואתר נשר, שכתוב, ופני נשר לארבעתן. שהוא תפארת, דהיינו רפאל, אדם, הוא כלל הכל, שכתוב, ודמות פניהם פני אדם. שהוא מלכות המקבלת מכולן, דהיינו נוריאל. ומבחינה אחרת מיכאל לימין אריה, גבריאל משמאל שור, ואוריאל באמצע, ת\"ת, ורפאל הוא פני אדם. (עי' להלן פקודי דף רנ\"ד ע\"א, ד\"י) ואלו הן ארבע ראשי החיות הנושאות את כסא הקדוש, שהוא המלכות, ומשום המשא שלהם הם מזיעים, ומזיעה ההיא של המשא שלהם, נעשה הנהר דינור, שכתוב, נהר דינור נגיד ונפק מן קדמוהי, אלף אלפין ישמשונה."],[1,"","פירוש. הכסא הקדוש שה\"ס המלכות נקראת חכמה תתאה, שע\"י ארבע החיות הנושאות אותה, כמו שנתבאר זה היטב לעיל (בראשית א' דף צ' ד\"ה כורסיא, ע\"ש) עי\"ז מתגלה החכמה שבה, שז\"ס המשא שהחיות נושאות ואין גילוי החכמה רק בגילוי הדינים דנקודת השורק, (כנ\"ל פרשת וירא דף ס\"ד ד\"ה וז\"ש חד, ע\"ש). וגילוי הדינים אלו ה\"ס הזיעה של החיות מחמת משאם, דהיינו מחמת גילוי החכמה. ומדינים אלו נתהוה הנהר די נור."],[2,"ונשמתין כד וכו':","וכשעולות הנשמות הן רוחצות בנהר דינור ההוא ועולות לקרבן, ואינן נשרפות אלא מתרחצות, בוא וראה מסלמבדרא, שעושים ממנה לבוש, ומתוך שהיא נולדה מאש, לא נרחץ לבוש ההוא אלא מאש, האש אוכלת הזוהמא שבו והלבוש נרחץ. אף הנשמה שהיא מאש שנלקחת מכסא הקדוש, שהוא מלכות, שכתוב בה, כרסיה שביבין די נור, בזמן שצריכה להתרחץ מהזוהמא שבה נעברת באש ונרחצת והאש אוכלת כל זוהמא ההיא שבנשמה, והנשמה נרחצת ומתלבנת."],[3,"ואי תימא אי וכו':","ואם תאמר א\"כ, אין בזה עונש לנשמה. שהרי היא רק מתרחצת. בוא וראה, אוי לנשמה הסובלת אש זרה, אע\"פ שהיא מתלבנת בזה. אבל כשהזוהמא נתרבה עליה אוי לנשמה שסובלת עונש ההוא, כי זוהמא ההיא מתלבנת באש שתי פעמים."],[4,"זמנא קדמאה וכו':","פעם הראשון הוא, אחר שקיבל עונש הגוף, הולכת הנשמה ולוקחים אותה ומכניסים אותה במקום אחד שנקרא, \u0003בן הנם.\u0004 ולמה נקרא בן הנם. משום שמקום אחד יש בגיהנם ששם נצרפות הנשמות במצרף להתלבן, מטרם שנכנסות בגן עדן, ושני מלאכים שליחים מוכנים בגן עדן ועומדים בשער וצווחים אל הממונים שעל מקום ההוא שבגיהנם, שיקבלו נשמה ההיא."],[5,"וההיא נשמתא וכו':","ונשמה ההיא, מטרם שנתלבנת באש השליחים צווחים אל הממונים ואומרים, \u0003הנם,\u0004 ובזמן שנתלבנת, יוצאים הממונים עמה ממקום ההוא, ומעמידים אותה בפתח גן עדן, ששם עומדים אותם השליחים, והממונים אומרים לשליחים \u0003הנם,\u0004 דהיינו, הנה אלו הנשמות אשר נתלבנו. אז מכניסים הנשמה ההיא לגן עדן. ולפיכך נקרא אותו המקום שבגיהנם, \u0003בן הנם.\u0004"],[6,"וכמה איהי תבירא וכו':","וכמה הנשמה שבורה, משבירה ההוא של התלבנות בגיהנם, כי היא שבירה מאש תחתונה. ואע\"פ שיורדת מלמעלה מנהר דינור, אבל כיון שמגיעה לארץ למטה. נעשית אש שאינה דקה, והנשמה נענשה בה ונשברת. אז הקב\"ה מוציא השמש, דהיינו אור עליון, המאיר מאלו ד' הפתחים המאירים ברקיע שעל הג\"ע, (כנ\"ל אות רצ\"ט בהסולם) ומגיע לנשמה ההיא ומתרפאת. ז\"ש, וזרחה לכם יראי שמי שמש צדקה ומרפא בכנפיה."],[7,"זמנא תנינא וכו':","פעם שניה, הנשמה מתלבנת באש, (כנ\"ל אות שכ\"ח) אחר שישבה בגן עדן התחתון כמה שישבה, אשר עד עתה עוד לא נפרדה מכל וכל מן הדברים שבמראה עולם הזה, וכשמעלים אותה למעלה, לגן עדן העליון, צריכה להפרד מכל מראה ומכל דבר שלמטה, וע\"כ מעבירים אותה בנהר דינור ההוא, אז הנשמה מתלבנת בו מכל וכל, ויוצאת ונראית לפני רבון העולם, כשהיא ברורה מכל הצדדים. כיון שהסתכלה באור הזה, נתרפאת ונשלמת מכל. ואז עומדות נשמות אלו בלבושים ומתעטרים לפני רבונם. אשרי חלקם של הצדיקים בעולם הזה ובעולם הבא."]],[[0,"","וְאַף עַל גַּב שֶׁאָמַרְנוּ שֶׁעֵדֶן שֶׁלְּמַטָּה הוּא בָּאָרֶץ - כָּךְ זֶה וַדַּאי. אֲבָל הַכֹּל הוּא סוֹד עֶלְיוֹן, כְּמוֹ שֶׁנִּתְבָּאֵר שֶׁהַנְּקֻדָּה הַזּוֹ שֶׁאָמַרְנוּ, כְּמוֹ שֶׁיֵּשׁ לָהּ חֵלֶק לְמַעְלָה - כָּךְ גַּם יֵשׁ לָהּ חֵלֶק לְמַטָּה בָּאָרֶץ. וְהַגָּן הַזֶּה לְמַטָּה הוּא חֶלְקָהּ שֶׁל אוֹתָהּ נְקֻדָּה לְהִשְׁתַּעֲשֵׁעַ בְּרוּחוֹת הַצַּדִּיקִים בָּאָרֶץ, וְנֶהֱנֵית בְּכָל הַצְּדָדִים, לְמַעְלָה וָמַטָּה. לְמַעְלָה בְּצַדִּיק, וּלְמַטָּה בְּאוֹתוֹ פְּרִי הַצַּדִּיק. וְלֹא נִמְצָא שַׁעֲשׁוּעַ מַעְלָה וָמַטָּה אֶלָּא בְּצַדִּיק. וְהַגָּן הַזֶּה הוּא מֵאוֹתָהּ נְקֻדָּה שֶׁנִּקְרֵאת עֵדֶן. (נקדה שגוטלת מאמא עליונה הטמונה בגן עדן של הארץ)."],[1,"","אוֹתָם רָאשֵׁי הַחַיָּה אֵלּוּ אַרְבָּעָה רָאשֵׁי פָנִים. אֶחָד אַרְיֵה, שֶׁכָּתוּב (יחזקאל א) וּפְנֵי אַרְיֵה אֶל הַיָּמִין. וְאֶחָד שׁוֹר, שֶׁכָּתוּב וּפְנֵי שׁוֹר מֵהַשְּׂמֹאול. וְאֶחָד נֶשֶׁר, שֶׁכָּתוּב וּפְנֵי נֶשֶׁר לְאַרְבַּעְתָּן. וְאָדָם כְּלָל שֶׁל הַכֹּל, שֶׁכָּתוּב וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם. וְאַרְבָּעָה רָאשֵׁי הָאוֹרוֹת הַלָּלוּ שֶׁמַּשָּׂאָם (חיות שגוטלות) אֶת הַכִּסֵּא הַקָּדוֹשׁ, וּמִתּוֹךְ הַמַּשָּׂא שֶׁלָּהֶם הֵם מַזִּיעִים. וּמֵאוֹתָהּ זֵעָה שֶׁל מַשָּׂאָם, נַעֲשֶׂה אוֹתוֹ נְהַר דִּינוּר, שֶׁכָּתוּב (דניאלז) נְהַר דִּינוּר שׁוֹפֵעַ וְיוֹצֵא מִלְּפָנָיו אֶלֶף אֲלָפִים יְשַׁמְּשׁוּהוּ."],[2,"","וּכְשֶׁעוֹלוֹת הַנְּשָׁמוֹת, הֵן רוֹחֲצוֹת בְּאוֹתוֹ נְהַר דִּינוּר, וְעוֹלוֹת לְקָרְבָּן וְאֵינָן נִשְׂרָפוֹת, אֶלָּא רוֹחֲצוֹת. בֹּא וּרְאֵה מִסַּלָּמַנְדְּרָא, שֶׁעוֹשִׂים מִמֶּנָּה לְבוּשׁ, וּמִתּוֹךְ שֶׁהִיא מֵאֵשׁ, אֵין רוֹחֲצִים אוֹתוֹ לְבוּשׁ אֶלָּא בְּאֵשׁ. הָאֵשׁ אוֹכֶלֶת הַזֻּהֲמָה שֶׁבּוֹ, וְנִרְחָץ אוֹתוֹ לְבוּשׁ. כָּךְ גַּם הַנְּשָׁמָה מֵאֵשׁ שֶׁנִּלְקְחָה מִתּוֹךְ הַכִּסֵּא הַקָּדוֹשׁ, שֶׁכָּתוּב בָּהּ (שם) כִּסְאוֹ שְׁבִיבֵי אֵשׁ, בִּזְמַן שֶׁרוֹצָה לִרְחֹץ מֵאוֹתָהּ זֻהֲמָה שֶׁבָּהּ, עוֹבֶרֶת בָּאֵשׁ וְנִרְחֶצֶת, וְהָאֵשׁ אוֹכֶלֶת כָּל אוֹתָהּ הַזֻּהֲמָה שֶׁבַּנְּשָׁמָה, וְהַנְּשָׁמָה רוֹחֶצֶת וּמִתְלַבֶּנֶת."],[3,"","וְאם תֹּאמַר, אִם כָּךְ, אֵין לַנְּשָׁמָה עֹנֶשׁ כָּזֶה - בּא וּרְאֵה, אוֹי לַנְּשָׁמָה שֶׁסּוֹבֶלֶת אֵשׁ זָרָה, וְאַף עַל גַּב שֶׁמִּתְלַבֶּנֶת. אֲבָל כְּשֶׁהַזֻּהֲמָה רַבָּה עָלֶיהָ, אוֹי לַנְּשָׁמָה שֶׁסּוֹבֶלֶת אוֹתוֹ עֹנֶשׁ, מִשּׁוּם שֶׁאוֹתָהּ זֻהֲמָה בְּפַעֲמַיִם מִתְלַבֶּנֶת בָּאֵשׁ."],[4,"","בַּפַּעַם הָרִאשׁוֹנָה, כֵּיוָן שֶׁקִּבְּלָה עֹנֶשׁ בַּגּוּף, הוֹלֶכֶת הַנְּשָׁמָה, וְנוֹטְלִים אוֹתָהּ וּמַכְנִיסִים אוֹתָהּ לְתוֹךְ מָקוֹם אֶחָד שֶׁנִּקְרָא בֶּן הִנֹּם. וְלָמָּה נִקְרָא בֶּן הִנֹּם? אֶלָּא מָקוֹם אֶחָד הוּא בַּגֵּיהִנֹּם שֶׁשָּׁם נִצְרָפוֹת הַנְּשָׁמוֹת בְּצֵרוּף לְהִתְלַבֵּן טֶרֶם שֶׁנִּכְנָסוֹת לְגַן עֵדֶן. (ואם זכאיות אותן נשמות, כאשר מכניסים אותן באותו מקום) שְׁנֵי מַלְאָכִים שְׁלוּחִים מְזֻמָּנִים בְּגַן עֵדֶן, וְעוֹמְדִים בַּשַּׁעַר, וְצוֹוְחִים לְאוֹתָם הַמְמֻנִּים שֶׁבְּאוֹתוֹ מָקוֹם שֶׁבַּגֵּיהִנֹּם כְּדֵי לְקַבֵּל אוֹתָהּ הַנְּשָׁמָה."],[5,"","וְאוֹתָהּ הַנְּשָׁמָה, בְּטֶרֶם תִּתְלַבֵּן בָּאֵשׁ, אוֹתָם שְׁלוּחִים צוֹוְחִים אֲלֵיהֶם וְאוֹמְרִים: הִנֹּם. וּבִזְמַן שֶׁמִּתְלַבֶּנֶת, אוֹתָם מְמֻנִּים יוֹצְאִים עִמָּהּ מֵאוֹתוֹ מָקוֹם, וּמַזְמִינִים אוֹתָהּ לְפִתְחוֹ שֶׁל גַּן עֵדֶן שֶׁשָּׁם אוֹתָם שְׁלִיחִים, וְאוֹמְרִים לָהֶם: הִנֹּם. אֵלֶּה הֵם הַנְּשָׁמוֹת שֶׁהִתְלַבְּנוּ. וְאָז מַכְנִיסִים אוֹתָהּ נְשָׁמָה בְּגַן עֵדֶן."],[6,"","וְכַמָּה הִיא שְׁבוּרָה מִתּוֹךְ אוֹתוֹ שֶׁבֶר שֶׁל הַהִתְלַבְּנוּת שֶׁל הַגֵּיהִנֹּם (של אותו) שֶׁל אוֹתוֹ שֶׁבֶר שֶׁל הָאֵשׁ הַתַּחְתּוֹנָה. וְאַף עַל גַּב שֶׁיּוֹרֶדֶת מִלְמַעְלָה, (אבל) כֵּיוָן שֶׁמַּגִּיעָה לָאָרֶץ לְמַטָּה, הִיא אֵשׁ שֶׁאֵינֶנָּה דַקִּיקָה, וְהַנְּשָׁמָה נֶעֱנֶשֶׁת בָּהּ וְנִשְׁבֶּרֶת. וְאָז הַקָּדוֹשׁ בָּרוּךְ הוּא מוֹצִיא שֶׁמֶשׁ שֶׁמְּאִירָה מֵאוֹתָם אַרְבָּעָה פְתָחִים שֶׁמְּאִירִים בָּרָקִיעַ שֶׁמֵּעַל הַגָּן, וּמַגִּיעַ לְאוֹתָהּ נְשָׁמָה וְנִרְפֵּאת. זֶהוּ שֶׁכָּתוּב (מלאכי ג) וְזָרְחָה לָכֶם יִרְאֵי שְׁמִי שֶׁמֶשׁ צְדָקָה וּמַרְפֵּא בִּכְנָפֶיהָ."],[7,"","בַּפַּעִם הַשְּׁנִיָּה, אַחַר שֶׁיָּשְׁבָה בְּגַן עֵדֶן שֶׁלְּמַטָּה, כָּל אוֹתוֹ זְמַן שֶׁיָּשְׁבָה וְעַד עַכְשָׁו אֵינָהּ נִפְרֶדֶת מֵאוֹתָם דְּבָרִים שֶׁל מַרְאֵה הָעוֹלָם הַזֶּה מִכֹּל וָכֹל. וּכְשֶׁמַּעֲלִים אוֹתָהּ לְמַעְלָה, צְרִיכָה לְהִפָּרֵד מִכָּל מַרְאֶה וּמִכָּל הַדְּבָרִים שֶׁלְּמַטָּה. וּמַעֲבִירִים אוֹתָהּ בְּאוֹתוֹ נְהַר דִּינוּר, וְאָז הַנְּשָׁמָה מִתְלַבֶּנֶת בּוֹ מִכֹּל וָכֹל, וְיוֹצֵאת וְנִרְאֵית לִפְנֵי רִבּוֹן הָעוֹלָם בְּרוּכָה (ברורה) מִכָּל הַצְּדָדִים. כֵּיוָן שֶׁמִּסְתַּכֶּלֶת בְּאוֹתוֹ אוֹר, נִרְפֵּאת וְנִשְׁלֶמֶת מֵהַכֹּל. וְאָז עוֹמְדוֹת אוֹתָן נְשָׁמוֹת בִּלְבוּשִׁים, מִתְעַטְּרִים לִפְנֵי רִבּוֹנָם. אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא."]]],[["וְאִינּוּן נִשְׁמָתִין דִּבְגִנְתָּא דְּעֵדֶן דִּלְתַתָּא, שָׁטָאן בְּכָל רֵישֵׁי יַרְחֵי וְשַׁבַּתֵּי, וְסַלְּקִין עַד הַהוּא אֲתָר דְּאִקְרֵי חוֹמוֹת יְרוּשָׁלַ ם. דְּתַמָּן כַּמָה מְמָנָן וּרְתִיכִין דְּנַטְרֵי אִינּוּן חוֹמוֹת. דִּכְתִּיב, (ישעיהו ס״ב:ו׳) עַל חוֹמוֹתַיִךְ יְרוּשָׁלַם הִפְקַדְתִּי שׁוֹמְרִים. וְסַלְּקִין עַד הַהוּא אֲתָר, וְלָא עָאלִין לְגוֹ, עַד דְּאִתְלַבְּנַן. וְתַמָּן סַגְדִּין, וְחַדָּאן מֵהַהוּא נְהִירוּ, וְתַיְיבִין לְגוֹ גִּנְתָּא.","נָפְקִין מִתַּמָּן וְשָׁטָאן בְּעָלְמָא, וְחָמָאן בְּאִינּוּן גּוּפִין דְּחַיָּיבַיָּא, בְּהַהוּא עוֹנְשָׁא דִּילְהוֹן, (קנ\"א ע\"א) דִּכְתִּיב, (ישעיהו ס״ו:כ״ד) וְיָּצְאוּ וְרָאוּ בְּפִגְרֵי הָאֲנָשִׁים הַפּוֹשְׁעִים בִּי כִּי תוֹלַעְתָּם לֹא תָמוּת וְאִשָּׁם לא תִכְבֶּה וְהָיוּ דֵרָאוֹן לְכָל בָּשָׂר. מַאי לְכָל בָּשָׂר. לְאִינּוּן שְׁאָר גּוּפִין דִּבְסָחֲרָנַיְיהוּ, וְהָא אוּקְמוּהָ. וּלְבָתַר מְשַׁטְּטֵי וּמִסְתַּכְּלָן בְּאִינּוּן מָארֵיהוֹן דִּכְאֵבִין, וּבְנֵי מַרְעִין, וְאִינּוּן דְּסַבְלִּין עַל יִחוּדָא דְּמָארֵיהוֹן, וְתָבִין וְאָמְרִין לֵיהּ לִמְשִׁיחָא.","בְּשַׁעֲתָא דְּאַמְרִין לֵיהּ לִמְשִׁיחָא צַעֲרָא דְּיִשְׂרָאֵל בְּגָלְוּתְהוֹן, וְאִינּוּן חַיָּיבַיָּא דִּי בְּהוֹן, דְּלָא מִסְתַּכְּלֵי לְמִנְדַּע לְמָארֵיהוֹן, אָרִים קָלָא וּבָכֵי, עַל אִינּוּן חַיָּיבִין דִּבְהוּ. הֲדָא הוּא דִכְתִיב, (ישעיהו נ״ג:ה׳) וְהוּא מְחוֹלָל מִפְּשָׁעֵינוּ מְדוּכָּא מֵעֲוֹנוֹתֵינוּ תַּיְיבִין אִינּוּן נִשְׁמָתִין וְקַיְימִין בְּאַתְרַיְיהוּ.","בְּגִנְתָּא דְּעֵדֶן אִית הֵיכָלָא חֲדָא, דְּאִקְרֵי הֵיכָלָא דִּבְנִי מַרְעִין. כְּדֵין מָשִׁיחַ עָאל בְּהַהוּא הֵיכָלָא, וְקָרֵי לְכָל מַרְעִין וְכָל כְּאֵבִין, כָּל יִסּוּרֵיהוֹן דְּיִשְׂרָאֵל, דְּיֵיתוּן עָלֵיהּ, וְכֻלְּהוּ אַתְיָין עָלֵיהּ. וְאִלְמָלֵא דְּאִיהוּ אָקִיל מֵעָלַיְיהוּ דְּיִשְׂרָאֵל, וְנָטִיל עָלֵיהּ, לָא הֲוֵי בַּר נָשׁ דְּיָכִיל לְמִסְבַּל יִסּוּרֵיהוֹן דְּיִשְׂרָאֵל, עַל עוֹנְשֵׁי דְּאוֹרַיְיתָא. הֲדָא הוּא דִכְתִיב (ישעיהו נ״ג:ד׳) אָכֵן חֳלָיֵינוּ הוּא נָשָׁא וְגוֹ'. כְּגַוְונָא דָּא רִבִּי אֶלְעָזָר בְּאַרְעָא.","בְּגִין דְּלֵית חוּשְׁבָּנָא, לְאִינּוּן יִסּוּרִין דְּקַיְימִין עָלֵיהּ דְּבַּר נָשׁ בְּכָל יוֹמָא, עַל עוֹנְשֵׁי דְּאוֹרַיְיתָא, וְכֻלְּהוּ נַחְתוּ לְעָלְמָא, בְּשַׁעֲתָא דְּאִתְיְהִיבַת אוֹרַיְיתָא. וְכַד הֲווֹ יִשְׂרָאֵל בְּאַרְעָא קַדִּישָׁא, בְּאִינּוּן פּוּלְחָנִין וְקָרְבְּנִין דַּהֲווֹ עַבְדֵי, הֲווֹ מְסַלְּקִין כָּל אִינּוּן מַרְעִין וְיִסוּרִין מֵעָלְמָא. הַשְׁתָּא מָשִׁיחַ מְסָלַק לוֹן מִבְּנֵי עָלְמָא, עַד דְּנָפִיק בַּר נָשׁ מֵהַאי עָלְמָא, וּמְקַבֵּל עוֹנְשֵׁיהּ, כְּמָה דְּאִתְּמַר. כַּד אִינּוּן חוֹבִין יַתִּיר דְּעַיְילִין לוֹן לְגוֹ בְּגוֹ גֵּהִינָּם, בְּאִינּוּן מָדוֹרִין תַּתָּאִין אַחֲרָנִין, וּמְקַבְּלִין עוֹנְשָׁא סַגִּי מִסְּגִיאוּת זוּהֲמָא דִּי בְּנִשְׁמְתָא, כְּדֵין אַדְלִיקוּ נוּרָא יַתִּיר, לְמֵיכַל הַהוּא זוּהֲמָא. (ווי לההיא נשמתא דסבלת ההוא עונשא. ועל דא אינון מלאכי חבלה דבגיהנם מטרדין לון בחוטרין דאשא לנערא ההוא זוהמא. ווי לנשמתא דסבלת ההוא עונש).","זַכָּאִין אִינּוּן דְּנַטְרֵי פִּקּוּדֵי אוֹרַיְיתָא. הַהִיא נְקוּדָה קַדִּישָׁא, דְּאִיהִי בַּעְיָא לְאִשְׁתַּעְשְׁעָא לְעֵילָּא וּלְתַתָּא בְּרוּחֵיהוֹן דְּצַדִּיקַיָּיא, כְּמָה (רי\"א ע\"ב) דְּאִתְּמַר. כַּד הַהִיא נְקוּדָה בָּעָא לְאִשְׁתַּעְשְׁעָא לְתַתָּא בְּרוּחֵיהוֹן דְּצַדִּיקַיָּיא, כְּאִמָּא דְּחַדָּאת עַל בְּנָהָא, וְאִשְׁתַּעְשְׁעָא בְּהוֹן, הָכִי נָמֵי בְּפַלְגוּת לֵילְיָא אִיהִי נַחְתָּא וְאִשְׁתַּעְשְׁעָא בְּהוּ.","רָקִיעַ דְּקַאמְרָן דְּקַיְּימָא עַל גִּנְתָּא, אִיהִי קַיְּימָא עַל ד' רֵישֵׁי חֵיוָון, וְאִינּוּן ד' אַתְוָון (רי\"א ע\"א) דְּקָאָמְרָן, אִינּוּן רָזָא דְּד' חֵיוָן. וְהַאי רְקִיעָא קַיְּימָא לְתַתָּא (ס\"א עלייהו), כְּמָה דְּאִתְּמַר. רָקִיעַ דְּהַהִיא נְקוּדָה, קַיְּימָא לְעֵילָּא, עַל אִינּוּן ד' חֵיוָון עִלָּאִין דְּקָאָמְרָן, וְהַהוּא רְקִיעָא (כגוונא דא מן דא) אִיהוּ אִתְרְקָם בִּגְוָונִין קַדִּישִׁין.","בְּהַאי רָקִיעַ אִסְתַּכְּלָן אַרְבַּע חֵיוָון, וְכָל אִינּוּן חַיָּילִין לְתַתָּא. כַּד הַאי רָקִיעַ אַנְהִיר בִּגְוָונוֹי וְנָצִיץ, כְּדֵין יַדְעִין כָּל אִינּוּן רְתִיכִין, וְכָל אִינּוּן חַיָּילִין וּמַשִׁירְיָין, דְּהָא טַרְפָּא דִּילְהוֹן אִזְדָּמַן. רְקִיעָא דָּא מְרֻקְּמָא בְּכָל גַּוְונִין קַדִּישִׁין, בֵּיהּ קַיְימִין אַרְבַּע פִּתְחִין רְשִׁימִין, בְּאַרְבַּע אַתְוָון מְנַצְצָן.","פִּתְחָא חֲדָא רְשִׁימָא לִסְטַר מִזְרָח, וּבֵיהּ קַיְּימָא בְּהַהוּא פִּתְחָא אָת חַד, וְהַהוּא אָת אִיהוּ א', וְדָא נָצִיץ וְסָלִיק וְנָחִית בְּהַאי פִּתְחָא. פִּתְחָא דָּא נָהִיר וְנָצִיץ מִנְצִיצוּ עִלָּאָה. וְהַאי אָת נָצִיץ וּבָלִיט (ס\"א ולהיט) בְּגַוֵיהּ, וְאִיהִי נַחְתָּא וְסַלְּקָא, וְאִתְרְשִׁים בְּהַהוּא פִּתְחָא."],[[0,"ואינון נשמתין דבגנתא וכו':","ואלו הנשמות שבגן עדן התחתון משוטטות בכל ראשי חדשים ושבתות, ועולות עד מקום ההוא שנקרא חומות ירושלים, דהיינו חצוניות המלכות דאצילות, ששם כמה ממונים ומרכבות השומרים חומות האלו, שכתוב, על חומותיך ירושלים הפקדתי שומרים. ועולות עד מקום ההוא ואינן נכנסות לפנים המלכות עד שמתלבנות, ושם הן משתחוות, ושמחות מאור ההיא, וחוזרות לגן עדן התחתון."],[1,"נפקין מתמן ושטאן וכו':","יוצאות משם מג\"ע, ומשוטטות בעולם ורואות באלו גופות של הרשעים בעונש ההיא שלהם, שכתוב, ויצאו וראו בפגרי האנשים הפושעים בי כי תולעתם לא תמות ואשם לא תכבה והיו דראון לכל בשר. מהו לכל בשר. הוא לכל שאר הגופות שמסביב להם. וכבר העמידוהו. (תרומה אות תנ\"ד) ואח\"כ משוטטות ומסתכלות בבעלי מכאובים וחולים ואלו שסובלים על יחוד אדונם וחוזרות לגן עדן ואומרות למשיח. שהוא בג\"ע."],[2,"בשעתא דאמרין ליה וכו':","בשעה שאומרים למשיח צערם של ישראל בגלותם, ואלו הרשעים שבהם, שאינם מסתכלים לדעת רבונם, הוא מרים קולו ובוכה על אלו הרשעים שבהם. ז\"ש, והוא מחולל מפשעינו מדוכא מעונותינו. חוזרות הנשמות ועומדות במקומן."],[3,"בגנתא דעדן אית וכו':","בגן עדן יש היכל אחד, שנקרא היכל החולים. אז משיח נכנס בהיכל ההוא, וקורא כל המחלות וכל המכאובים וכל היסורים של ישראל, שיבואו עליו. וכולם באים עליו. ולולא שהוא מקל מעל ישראל ולוקחם עליו, לא היה אדם שיכול לסבול יסוריהם של ישראל על עונשי התורה. ז\"ש, אכן חליינו הוא נשא וגו'. כעין זה רבי אלעזר בארץ, היה מקבל עליו יסורים בשביל ישראל (ב\"מ פד ע\"ב)."],[4,"בגין דלית חושבנא וכו':","משום שאין מספר אל היסורין שעומדים על האדם בכל יום מעונשי התורה, וכולם ירדו לעולם בשעה שניתנה התורה, וכשישראל היו בארץ הקדושה, באלו עבודות והקרבנות שהיו עושים, היו מעבירים כל אלו המחלות והיסורים מן העולם, עתה, משיח מעבירם מן העולם, עד שנפטר האדם מעולם הזה ומקבל ענשו. כמו שלמדנו, ואם העונות מרובים, מכניסים אותם בתוך הגיהנם, באלו מדורים תחתונים האחרים, ומקבלים שם עונש גדול מרוב הזוהמא אשר בנשמה, אז מדליקים יותר אש שתאכל הזוהמא ההיא."],[5,"זכאין אינון דנטרי וכו':","אשרי הם השומרים מצות התורה. כי נקודה הקדושה ההיא, שהיא מלכות, רוצה להשתעשע למעלה במקומה, ולמטה בגן עדן, ברוחיהם של הצדיקים, כמו שלמדנו, כשהנקודה רוצה להשתעשע למטה, בגן עדן, עם נשמות הצדיקים, היא כאם השמחה על בניה ומשתעשעת בהם. אף כך בחצות לילה היא יורדת לג\"ע, ומשתעשעת בהם."],[6,"רקיע דקאמרן דקיימא וכו':","הרקיע העומד על הגן שאמרנו, הוא עומד על ד' ראשי חיות, והן ד' אותיות מרג\"נ, שאמרנו (באות רצ\"ב עד אות רצ\"ט) שה\"ס ד' חיות, דהיינו מיכאל גבריאל רפאל נוריאל. (כמ\"ש בהסולם אות רצ\"ט) ורקיע הזה עומד עליהם כמו שאמרנו. רקיע של נקודה ההיא, דהיינו הרקיע שעל המלכות, עומד למעלה על אלו ד' חיות עליונים שאמרנו, (כנ\"ל אות שכ\"ד) והם נקראים עליונים כלפי אלו שבגן עדן התחתון. ורקיע ההוא שעל המלכות דאצילות, נתרקם בגוונים קדושים. דהיינו בדומה לרקיע שעל הגן למטה שיש בו ד' גוונים, (כנ\"ל אות רצ\"ג) וכן הרקיע העליון שעל המלכות נרקם בגוונים. והזהר הולך ומפרש לפנינו שכל הבחינות שאמר לעיל הנוהגים ברקיע שעל גן עדן התחתון, נוהגים גם ברקיע העליון שעל המלכות דאצילות."],[7,"בהאי רקיע אסתכלן וכו':","ברקיע ההוא שעל המלכות העליונה, מסתכלים ארבע חיות וכל אלו צבאות שלמטה. כשרקיע ההוא מאיר בגווניו ומתנוצץ, דהיינו ד' גוונים שנתבארו לעיל (אות רצ\"ז ד\"ה וז\"ש מאינון) שהם חו\"ג תו\"מ שברקיע עצמו המאירים דרך הפתחים. אז יודעים כל המרכבות וכל הצבאות והמחנות שטרף שלהם נזדמן. כי הם מקבלים מן הפתחים. רקיע זה מרוקם בכל גוונים הקדושים, שהם ד' אורות חו\"ג תו\"מ כנ\"ל, בו עומדים ארבע פתחים, שבכל פתח מאיר גוון אחד. והאורות הם רשומות בארבע אותיות מתנוצצות. כל זה כבר נתבאר בהסולם אות רצ\"ט ע\"ש בכל ההמשך."],[8,"פתחא חדא וכו':","פתח אחד עומד לצד מזרח שהוא ת\"ת, ובו בפתח ההוא עומדת אות אחת, כמו ברקיע שעל הגן, אלא ששם עומדת אות \u0003ר'\u0004 שהוא ראש המלה של רפאל, וכאן אות ההוא הוא אות \u0003א',\u0004 דהיינו ראש השם אדנ\"י, ואות זו מתנוצצת ועולה ויורדת בפתח זה. פתח זה מאיר ומתנוצץ מהתנוצצות עליון, דהיינו מגוון אחד שבחו\"ג תו\"מ שבאורות הרקיע עצמו, ואות \u0003א\u0004 הזו מתנוצצת ובולטת בתוכו. (כנ\"ל בסולם אות רצ\"ט) והיא עולה ויורדת ונרשמת בפתח ההוא."]],[[0,"","וְאוֹתָן נְשָׁמוֹת שֶׁבְּגַן עֵדֶן שֶׁלְּמַטָּה מְשׁוֹטְטוֹת בְּכָל רָאשֵׁי חֳדָשִׁים וְשַׁבָּתוֹת, וְעוֹלוֹת עַד אוֹתוֹ מָקוֹם שֶׁנִּקְרָא חוֹמוֹת יְרוּשָׁלַיִם, שֶׁשָּׁם כַּמָּה מְמֻנִּים וּמֶרְכָּבוֹת שֶׁשּׁוֹמְרִים אוֹתָם הַחוֹמוֹת, שֶׁכָּתוּב (ישעיה סב) עַל חוֹמֹתַיִךְ הִפְקַדְתִּי שּמְרִים. וְעוֹלִים עַד אוֹתוֹ מָקוֹם, וְלֹא נִכְנָסוֹת פְּנִימָה עַד שֶׁמִּתְלַבְּנוֹת, וְשָׁם מִשְׁתַּחֲווֹת וּשְׂמֵחוֹת מֵאוֹתוֹ אוֹר, וְשָׁבוֹת לְתוֹךְ הַגָּן."],[1,"","יוֹצְאוֹת מִשָּׁם וּמְשׁוֹטְטוֹת בָּעוֹלָם, וְרוֹאוֹת בְּאוֹתָם הַגּוּפוֹת שֶׁל הָרְשָׁעִים וּבְאוֹתוֹ עֹנֶשׁ שֶׁלָּהֶם, שֶׁכָּתוּב (ישעיה סו) וְיָצְאוּ וְרָאוּ בְּפִגְרֵי הָאֲנָשִׁים הַפֹּשְׁעִים בִּי כִּי תוֹלַעְתָּם לֹא תָמוּת וְאִשָּׁם לֹא תִכְבֶּה וְהָיוּ דֵרָאוֹן לְכָל בָּשָׂר. מַה זֶּה לְכָל בָּשָׂר? לְאוֹתָם שְׁאָר הַגּוּפִים שֶׁסְּבִיבָם, וַהֲרֵי פֵּרְשׁוּהָ. וְאַחַר מְשׁוֹטְטִים וּמִסְתַּכְּלִים בְּאוֹתָם בַּעֲלֵי מַכְאוֹבִים וּבְנֵי מַחֲלוֹת, וְאוֹתָם שֶׁסּוֹבְלִים עַל הַיִּחוּד שֶׁל רִבּוֹנָם, וְשָׁבִים וְאוֹמְרִים לַמָּשִׁיחַ."],[2,"","בְּשָׁעָה שֶׁאוֹמְרִים לוֹ לַמָּשִׁיחַ אֶת צַעַר יִשְׂרָאֵל בְּגָלוּתָם, וְאוֹתָם הָרְשָׁעִים שֶׁבָּהֶם שֶׁאֵינָם מִתְבּוֹנְנִים לָדַעַת אֶת רִבּוֹנָם, הוּא מֵרִים קוֹל וּבוֹכֶה עַל אוֹתָם הָרְשָׁעִים שֶׁבָּהֶם. זֶהוּ שֶׁכָּתוּב (שם נג) וְהוּא מְחֹלָל מִפְּשָׁעֵינוּ מְדֻכָּא מֵעֲונֹתֵינוּ. שָׁבוֹת אוֹתָן נְשָׁמוֹת וְעוֹמְדוֹת בִּמְקוֹמָן."],[3,"","בְּגַן עֵדֶן יֵשׁ הֵיכָל אֶחָד שֶׁנִּקְרָא הֵיכַל בְּנֵי הַמַּחֲלוֹת. אָז הַמָּשִׁיחַ נִכְנָס לְאוֹתוֹ הֵיכָל, וְקוֹרֵא לְכָל הַמַּחֲלוֹת וְהַמַּכְאוֹבִים וְכָל יִסּוּרֵי יִשְׂרָאֵל שֶׁיָּבֹאוּ עָלָיו, וְכֻלָּם בָּאִים עָלָיו. וְאִלְמָלֵא שֶׁהוּא מֵקֵל מֵעַל יִשְׂרָאֵל וְנוֹטֵל עָלָיו, לֹא הָיָה אָדָם שֶׁיָּכוֹל לִסְבֹּל אֶת יִסּוּרֵי יִשְׂרָאֵל עַל עָנְשֵׁי הַתּוֹרָה. זֶהוּ שֶׁכָּתוּב (שם) אָכֵן חֳלָיֵנוּ הוּא נָשָׂא וְגוֹ'. כְּמוֹ כֵן רַבִּי אֶלְעָזָר בָּאָרֶץ."],[4,"","מִשּׁוּם שֶׁאֵין חֶשְׁבּוֹן לְאוֹתָם יִסּוּרִים שֶׁעוֹמְדִים עַל אָדָם בְּכָל יוֹם עַל עָנְשֵׁי הַתּוֹרָה, וְכֻלָּם יָרְדוּ לָעוֹלָם בְּשָׁעָה שֶׁנִּתְּנָה תוֹרָה. וּכְשֶׁהָיוּ יִשְׂרָאֵל בָּאָרֶץ הַקְּדוֹשָׁה בְּאוֹתָן עֲבוֹדוֹת וְקָרְבָּנוֹת שֶׁהָיוּ עוֹשִׂים, הָיוּ מְסַלְּקִים אֶת כָּל אוֹתָן מַחֲלוֹת וְיִסּוּרִים מִן הָעוֹלָם, וְעַכְשָׁו הַמָּשִׁיחַ מְסַלֵּק אוֹתָם מִבְּנֵי הָעוֹלָם טֶרֶם שֶׁיּוֹצֵא מֵהָעוֹלָם הַזֶּה, וּמְקַבֵּל עָנְשׁוֹ, כְּמוֹ שֶׁנִּתְבָּאֵר. כְּשֶׁאוֹתָם חֲטָאִים יְתֵרִים שֶׁמַּכְנִיסִים אוֹתָם לְתוֹךְ בִּפְנִים הַגֵּיהִנֹּם בְּאוֹתָם מָדוֹרִים תַּחְתּוֹנִים אֲחֵרִים, וּמְקַבְּלִים עֹנֶשׁ רַב מֵרֹב הַזֻּהֲמָה שֶׁבַּנְּשָׁמָה, אָז מַדְלִיקִים אֵשׁ יוֹתֵר, לֶאֱכֹל אוֹתָהּ זֻהֲמָה. (אוי לאותה נשמה שסובלת אותו הענש. ועל זה אותם מלאכי חבלה שבגיהגם מטרידים אותו במקלות של אש לנער את אותה הזהמה. אוי לגשמה שסובלת אותו ענש)."],[5,"","אַשְׁרֵיהֶם שֶׁשּׁוֹמְרִים אֶת מִצְווֹת הַתּוֹרָה. אוֹתָהּ נְקֻדָּה קְדוֹשָׁה שֶׁרוֹצָה לְהִשְׁתַּעֲשֵׁעַ לְמַעְלָה וּלְמַטָּה בְּרוּחוֹת הַצַּדִּיקִים, כְּמוֹ שֶׁנִּתְבָּאֵר. כְּשֶׁאוֹתָהּ נְקֻדָּה רוֹצָה לְהִשְׁתַּעֲשֵׁעַ לְמַטָּה בְּרוּחוֹת הַצַּדִּיקִים כְּאֵם שֶׁשְּׂמֵחָה עִם בָּנֶיהָ וּמִשְׁתַּעֲשַׁעַת בָּהֶם, כָּךְ גַּם בַּחֲצוֹת הַלַּיְלָה הִיא יוֹרֶדֶת וּמִשְׁתַּעֲשַׁעַת בָּהֶם."],[6,"","הָרָקִיעַ שֶׁאָמַרְנוּ שֶׁעוֹמֵד עַל הַגָּן, הִיא עוֹמֶדֶת עַל אַרְבָּעָה רָאשֵׁי הַחַיּוֹת, וְאוֹתָן אַרְבַּע אוֹתִיּוֹת שֶׁאָמַרְנוּ הֵם סוֹד שֶׁל אַרְבַּע הַחַיּוֹת. וְהָרָקִיע הַזֶּה עוֹמֵד לְמַטָּה (עליהן), כְּמוֹ שֶׁנִּתְבָּאֵר. הָרָקִיעַ שֶׁל אוֹתָהּ נְקֻדָּה עוֹמֵד לְמַעְלָה עַל אוֹתָן אַרְבַּע חַיּוֹת עֶלְיוֹנוֹת שֶׁאָמַרְנוּ, וְאוֹתוֹ רָקִיעַ (כדגמתזה מזה) נִרְקָם בִּגְוָנִים קְדוֹשִׁים."],[7,"","בָּרָקִיעַ הַזֶּה מִסְתַּכְּלוֹת אַרְבַּע הַחַיּוֹת, וְכָל אוֹתָם חֲיָלוֹת לְמַטָּה. כְּשֶׁהָרָקִיעַ הַזֶּה מֵאִיר בִּגְוָנָיו וְנוֹצֵץ, אָז יוֹדְעוֹת כָּל אוֹתָן מֶרְכָּבוֹת וְכָל אוֹתָם חֲיָלוֹת וּמַחֲנוֹת שֶׁהֲרֵי טַרְפָּם הִזְדַּמֵּן. הָרָקִיעַ הַזֶּה רָקוּם בְּכָל הַגְּוָנִים הַקְּדוֹשִׁים, וּבוֹ עוֹמְדִים אַרְבַּע פְּתָחִים רְשׁוּמִים בְּאַרְבַּע אוֹתִיּוֹת נוֹצְצוֹת."],[8,"","פֶּתַח אֶחָד רָשׁוּם לְצַד מִזְרָח, וּבוֹ עוֹמֶדֶת בְּאוֹתוֹ פֶּתַח אוֹת אַחַת, וְאוֹתָהּ אוֹת הִיא א'. וְזֶה נוֹצֵץ וְעוֹלֶה וְיוֹרֵד בַּפֶּתַח הַזֶּה. הַפֶּתַח הַזֶּה מֵאִיר וְנוֹצֵץ מֵהִתְנוֹצְצוּת עֶלְיוֹנָה, וְהָאוֹת הַזּוֹ נוֹצֶצֶת וּבוֹלֶטֶת (ולוהטת) בְּתוֹכָהּ, וְהִיא יוֹרֶדֶת וְעוֹלָה וְנִרְשֶׁמֶת בְּאוֹתוֹ פֶּתַח."]]],[["פִּתְחָא תִּנְיָינָא, רְשִׁימָא לִסְטָר צָפוֹן, וּבֵיהּ קַיְּימָא אָת חַד, וְאִיהִי אָת ד'. וְדָא קַיְּימָא וְנָצְצָא, סַלְּקָא וְנַחְתָּא, וְלָהֲטָא בְּהַהוּא פִּתְחָא. לְזִמְנִין נָצִיץ בִּנְצִיצוּ, וּלְזִמְנִין אִתְטָמַר הַהוּא נְהוֹרָא, וְלָא נָהִיר. וְעַל דָּא, אָת דָּא לָא קַיְּימָא בְּקִיוּמָא תָּדִיר, וְאָת דָּא אִתְרְשִׁים בְּהַהוּא פִּתְחָא.","פִּתְחָא תְּלִיתָאָה, אִיהוּ פִּתְחָא דְּקַיְּימָא לִסְטַר מַעֲרָב, וּבֵיהּ קַיְּימָא אָת חַד, דְּאִתְרְשִׁים וְאִתְנְהִיר בְּהַהוּא פִּתְחָא. וְדָא אִיהוּ אָת נ', וְהַאי אָת נָצִיץ בִּנְצִיצוּ בְּהַהוּא פִּתְחָא.","פִּתְחָא רְבִיעָאָה, דָּא אִיהוּ פִּתְחָא דְּקַיְּימָא לִסְטַר דָּרוֹם, וּבֵיהּ קַיְּימָא רְשִׁימוּ דְּחָד נְקוּדָה תַּתָּאָה זְעִירָא, דְּאִתְחָזֵי וְלָא אִתְחָזֵי, וְדָא אִיהִי אָת י', וְאִלֵּין אַרְבַּע אַתְוָון לְאַרְבַּע סִטְרִין, (נ\"א נציצין) נָצְצִין בְּהַהוּא רָקִיעַ, בְּאִינּוּן פִּתְחִין.","בְּהַאי רָקִיעַ רְשִׁימִין אַתְוָון אַחֲרָנִין, (ד\"א לד' סטרין) בְּכִתְרִין עַל רֵישַׁיְיהוּ. וְאִינּוּן עֶשְׂרִין וּתְרֵין אַתְוָון, מִתְעַטְּרָן בְּכִתְרִין. רְקִיעָא דָּא נָטִיל וְסָחֲרָא עַל גַּבֵּי חֵיוָון, בִּרְשִׁימוּ דְּאַתְוָון, רָזָא דְּחוּשְׁבָּן דְּיִחוּדָא, בְּרָזָא דְּצֵרוּפָא חֲדָא וְאִינּוּן: א\"ט ב\"ח ג\"ז ד\"ו.","אִלֵּין אַתְוָון סָחֲרָן בְּהַהוּא רָקִיעַ, בְּרָזָא דְּאַתְוָון אַחֲרָנִין, (דרתיכי) עִלָּאִין קַדִּישִׁין סְתִימִין. וְאִינּוּן אַתְוָון אַחֲרָנִין (ס\"א עלאין) סְתִימִין, סָחֲרִין לְהַהוּא רָקִיעַ, וּכְדֵין אִתְחַזְיָין אִלֵּין אַתְוָון בְּגִלְגּוּלָא, (ס\"א דהאי רקיעא) דְּאִינּוּן א\"ט ב\"ח, וּרְשִׁימִין בְּהַאי רְקִיעָא.","בְּשַׁעֲתָא דְּאִתְנְהִיר הַאי רְקִיעָא, אִתְנָהֲרָן בֵּיהּ אַרְבַּע רָזִין דִּשְׁמָהָן קַדִּישִׁין, וְאִינּוּן צִרוּפָא בְּצֵרוּפִין דִּתְלָתִין וּתְרֵין שְׁבִילִין. כְּדֵין נָחִית טַלָּא מֵהַאי רְקִיעָא, בְּאִינּוּן אַתְוָון דְּרָזָא דִּשְׁמָא קַדִּישָׁא, וְאִתְּזָנוּ כָּל אִינּוּן רְתִיכִין, וְכָל אִינּוּן חַיָּילִין וּמַשִׁירְיָין קַדִּישִׁין, וְנַטְלֵי כֻּלְּהוּ בְּחֶדְוָה.","בְּשַׁעֲתָא דְּדִינָא תַּלְיָיא, אִלֵּין אַתְוָון אִתְטְמָרוּ, וְאִתְגְּנִיזוּ ד' גּוֹ ד', וְאִינּוּן ט\"ח ז\"ו. בְּשַׁעֲתָא דְּאִלֵּין אִתְגְּנִיזוּ וְאִתְטָמָרוּ, כְּדֵין קָלָא דִּסְטָר צָפוֹן אִתְּעַר, וְיַדְעֵי דְּדִינָא שַׁרְיָיא עַל עָלְמָא. וּבְהַאי רְקִיעָא אִתְרְשִׁים גַּוְונָא חֲדָא, דְּכָלִיל כָּל גַּוְונִין.","כַּד נָטִיל הַאי רְקִיעָא מִסִּטְרָא דְּמִזְרָח, אִינּוּן אַרְבַּע רֵישִׁין דְּקָאָמְרָן, בְּאַרְבַּע (אנפין) אַתְוָון, נַטְלִין כֻּלְּהוּ בְּמַטְלָנִין, וְסַלְקֵי בִּסְלִיקוּ לְעֵילָּא. וְכַד אִינּוּן נַטְלִין וְסַלְּקִין לְעֵילָּא, אִסְתַּלְּקַת מַאן דְּאִסְתַּלְּקַת. וְאַתְוָון אִתְהַדְרוּ וְאִתְחַזְיָין בִּשְׁלִימוּ, בְּרָזָא קַדְמָאָה, א\"ט ב\"ח ג\"ז ד\"ו, וְאִתְרְקָם הַהוּא רְקִיעָא, כְּדֵין אִתְנְהִיר בִּנְהִירוּ.","וְכַד הַאי רְקִיעָא אִתְנְהִיר כְּמִלְּקַדְמִין, בְּאִלֵּין אַתְוָון, כּוּלְּהוּ אִתְהֲדָרוּ וְשָׁאֲגֵי לְמִטְרַף טַרְפָּא וּמְזוֹנָא. כֵּיוָן דְּאִינּוּן שָׁאֲגֵי וְסַלְּקִין קָלָא, הַהוּא קָלָא אִשְׁתְּמַע לְעֵילָּא לְעֵילָּא, וּכְדֵין נַטְלָּא בִּרְכָאן וְקִדּוּשָׁן, מַאן דְּנַטְלָא.","סָחֲרָן אַתְוָון וּמִתְגַּלְגְּלָן, וְסָחֲרָן הַהוּא רְקִיעָא, וְקַיְימָן אִינּוּן אַתְוָון לִסְטַר דָּרוֹם. כֵּיוָן דְּקַיְימִין אִינּוּן אַתְוָון לִסְטַר דָּרוֹם, סַלְּקִין וְנַצְצָן בִּנְצִיצוּ וְלָהֲטִין. כְּדֵין בְּאֶמְצָעִיתָא דְּהַהוּא רְקִיעָא, רְשִׁימוּ חַד אִתְרְשִׁים, וְהַהוּא רְשִׁימוּ אִיהוּ אָת חַד, וְאִיהוּ י'. כֵּיוָן דְּאָת דָּא אִתְרְשִׁים וְאִתְחַזְיָיא, כְּדֵין לָהֲטִין אֲבַתְרֵיהּ, תְּלַת אַתְוָון אַחֲרָנִין, וְאִינּוּן הו\"ה.","אִלֵּין אַתְוָון מְנַצְצָן בְּאֶמְצִעוּ דְּהַאי רְקִיעָא, סַלְּקִין וְנַחְתִּין, מְלַהֲטִין בִּתְלֵיסַר (נ\"א בתריסר) לַהֲטִין. כְּדֵין לְבָתַר דְּאִלֵּין תְּלֵיסַר זִמְנִין מְלַהֲטָן, נַחְתָּא מַאן דְּנַחְתָּא, וְאִתְכְּלִילַת בְּאִינּוּן אַתְוָון, וְאִתְעַטְּרַת בְּהוּ, וְלָא אִתְיְידָעַת. כְּדֵין, כֻּלְּהוּ חַיָּילִין, וְכֻלְּהוּ מַשִׁירְיָין, בְּחֵידוּ. וְסַלְּקִין שִׁירִין וְתוּשְׁבְּחָן.","רְקִיעָא דָּא נַטְלָא תִּנְיָינוּת, וְסָחֲרָא וּמִתְגַּלְגְּלָא, וְאִינּוּן אַתְוָון קַדְמָאֵי דְּקָאָמְרָן, דְּאִינּוּן א\"ט ב\"ח, כֻּלְּהוּ אִתְכְּלִילוּ בְּאִינּוּן אַתְוָון עִלָּאִין, רָזָא דִּשְׁמָא קַדִּישָׁא דְּקָאָמְרָן, וְסָחֲרָן הַהוּא רְקִיעָא, וְקַיְימִין אִינּוּן אַתְוָון דַּהֲווֹ בְּאֶמְצָעִיתָא רָזָא דִּשְׁמָא קַדִּישָׁא, כֻּלְּהוּ אִתְרְשִׁימוּ לִסְטַר צָפוֹן, וְאִתְרְשִׁימוּ וְלָא אִתְרְשִׁימוּ. לֵית מַאן דְּיִסְתָּכַּל בְּהַהוּא סִטְרָא, כֻּלְּהוּ אִתְחַפְיָין, וְאַמְרֵי בְּקַל נְעִימוּ בָּרוּךְ כְּבוֹד יְיָ' מִמְּקוֹמוֹ. אִתְחַפְיָּין מִסִּטְרָא דְּצָפוֹן (ס\"א דאנפין) וְאָמְרִין דָּא אִתְחַפְיָּין מִכָּל סִטְרִין וְאַמְרִין דָּא."],[[0,"פתחא תניינא וכו':","פתח השני רשום לצד צפון, שהוא גבורה, ובו עומדת אות אחת, והיא אות \u0003ד'\u0004 של השם אדנ\"י. וזו עומדת ומתנוצצת עולה ויורדת ולוהטת בפתח ההוא שבצפון. לפעמים נוצצת בהתנוצצות, ולפעמים מסתתר אור ההוא ואינו מאיר. פירוש, כי \u0003ד\u0004 זו היא הפתח בצפון שהוא קו שמאל, וכשיש לו חסדים הוא מאיר. וכשאין לו חסדים מימין אינו מאיר. וע\"כ נקרא דלת, שהוא לשון דלות. כי החכמה שבשמאל אינה מאירה בלי חסדים. וע\"כ אות זו אינה עומדת בקיומה תמיד. ואות זו נרשמה בפתח ההוא."],[1,"פתחא תליתאה וכו':","פתח השלישי הוא פתח העומד לצד מערב, שהוא מלכות, ובו עומדת אות אחת שנרשמה ומאירה בפתח ההוא, וזו היא אות \u0003נ'\u0004 שבשם אדנ\"י, ואות הזו נוצצת בהתנוצצות בפתח ההוא."],[2,"פתחא רביעאה וכו':","פתח הרביעי, זה הוא פתח העומד לצד דרום, שהוא חסד, ובו עומדת רשימו של נקודה תחתונה אחת קטנה, הנראית ואינה נראית, וזו היא אות \u0003י',\u0004 שבשם אדנ\"י. פירוש, כשהמלכות היא ביחוד עם ז\"א בסוד השלוב של ב' שמות יאהדונה\"י, אז נראית היוד דאדני, כי אז היא מקבלת חכמה מיוד הראשונה. ואם אינה בחבור עם הויה, אינה נראית. ואלו ארבע אותיות \u0003אדנ\"י,\u0004 מתנוצצים לארבעה צדדים ברקיע הזה, באלו ד' הפתחים שבסיומו."],[3,"בהאי רקיע רשימין וכו':","ברקיע הזה רשומות אותיות אחרות בכתרים על ראשם, והם כ\"ב אותיות מתעטרות בכתרים. שכ\"ב אותיות ה\"ס ז\"א הכלול ברקיע המלכות הזה, והכתרים שעליהן, הם בחינת בינה, שהיא כתר ז\"א, כי השורש שלכל אות הנקרא כתר, הוא מבינה. רקיע הזה נוסע וסובב על חיות, שהם ברשימות האותיות בסוד החשבון של היחוד, בסוד צירוף אחד של אלפא ביתא, שהן, \u0003א\"ט ב\"ח ג\"ז ד\"ו.\u0004"],[3,"","פירוש. ד' צרופים א\"ט ב\"ח ג\"ז ד\"ו, הם רומזים על ג' קוין ימין שמאל אמצע, שהם חב\"ד, ומלכות המקבלתם, שה\"ס \u0003ארבע חיות\u0004 המסבבים את הרקיע הזה, שהוא רקיע של המלכות דאצילות, אשר \u0003א\"ט\u0004 רומז על חכמה, שיש לה \u0003ט'\u0004 ספירות המתחילות מחכמה ולמטה, והכתר שהוא השורש שלה מלובש בפנימיותן, שה\"ס \u0003א',\u0004 באפן, אשר \u0003א\"ט\u0004 רומז לכתר המלובש בתוך ט' ספירות החכמה. וה\"ס קו ימין ופני אריה. \u0003ב\"ח\u0004 רומז על בינה, שיש לה \u0003ח'\u0004 ספירות המתחילות מבינה ולמטה, וכתר חכמה שהם השורשים שלה מלובשים בפנימיותן וכתר חכמה אלו הם \u0003ב',\u0004 באפן, אשר \u0003ב\"ח\u0004 רומז ל \u0003ב'\u0004 ספירות כתר וחכמה המלובשות בפנימיות \u0003ח'\u0004 ספירות הבינה. וה\"ס קו שמאל ופני שור. \u0003ג\"ז\u0004 רומז על דעת, שיש לה \u0003ז'\u0004 ספירות המתחילות מחסד ולמטה, וכתר חכמה בינה, שהם השורשים שלה, מלובשים בפנימיותן, וכתר חכמה בינה אלו הם סוד \u0003ג'.\u0004 באפן אשר \u0003ג\"ז\u0004 רומז ל \u0003ג'\u0004 ספירות כח\"ב, המלובשות בפנימיות \u0003ז'\u0004 ספירות הדעת. וה\"ס קו אמצעי, ופני נשר. \u0003ד\"ו\u0004 רומז על מלכות, שיש לה ד' ספירות שמחזה ולמטה דז\"א שהם תנהי\"מ, וששה ספירות חב\"ד חג\"ת מלובשות בפנימיותן, וחב\"ד חג\"ת אלו שה\"ס \u0003ו'.\u0004 באפן אשר \u0003ד\"ו\u0004 רומז ל \u0003ו'\u0004 ספירות חב\"ד חג\"ת, המלובשות בפנימיות \u0003ד'\u0004 ספירות המלכות, והיא מקבלת מכל ג' פנים אריה שור נשר, והיא עצמה פני אדם. וז\"ש \u0003רקיע דא נטיל וסחרא על גבי חיוון\u0004 וכו' \u0003ואינון א\"ט ב\"ח ג\"ז ד\"ו.\u0004"],[4,"אלין אתוון סחרן וכו':","אלו האותיות א\"ט ב\"ח ג\"ז ד\"ו, מסבבים את הרקיע ההוא בסוד אותיות אחרות עליונות קדושות סתומות, שהן מבינה, ואלו אותיות האחרות הסתומות מסבבות לרקיע ההוא, ואז נראות בגלגול אלו האותיות א\"ט ב\"ח ג\"ז ד\"ו, דהיינו שמתגלגלות מדוכתא לדוכתא בזה אחר זה בסדר ג' קוין, המכונה גלגול, (כנ\"ל בהסולם פרשת ויחי אות תק\"ז ע\"ש) ורשומות ברקיע הזה."],[5,"בשעתא דאתנהיר האי וכו':","בשעה שהאיר רקיע הזה. מאירים בו ארבע סודות, דהיינו ארבע אותיות הויה. של שמות הקדושים שהן צרופות בצירופים, דהיינו י\"ב צירופי שמות הויה (כמ\"ש להלן באות שנ\"ב) דל\"ב שבילים. כלומר שמאיר בי\"ב שמות אלו, ל\"ב שבילי החכמה. אז יורד טל, דהיינו שפע קדוש, מרקיע הזה, באלו האותיות דסוד השם הקדוש, דהיינו בי\"ב צירופי הויה הנ\"ל, וניזונים כל המרכבות וכל הצבאות והמחנות הקדושים, ומקבלים כולם בשמחה."],[6,"בשעתא דדינא תליא וכו':","בשעה שהדין תולה, אלו האותיות מסתתרות ונגנזות תוך הד', דהיינו אותיות \u0003אבג\"ד\u0004 שהם השורשים, נעלמות ונגנזות, והן נשארו \u0003טחז\"ו,\u0004 דהיינו ענפים בלי שרשים. בשעה שאלו אבג\"ד נגנזו ונסתתרו, אז נתעורר קול אחד מצד צפון, ששם הדינים, ויודעים שהדין שורה על העולם. ברקיע הזה, נרשם גוון אחד הכלול כל הגוונים. דהיינו המלכות, המקבלת מכל ג' הקוים, שה\"ס ג' גוונין."],[7,"כד נטיל האי וכו':","כשנוסע רקיע ההוא מצד מזרח, שהוא קו האמצעי, אלו ארבע ראשים, דהיינו ד' השרשים, שאמרנו בארבע אותיות, אבג\"ד, נוסעות כולן במסעות ועולות בעליה של מעלה, דהיינו שמסתלקות, וכשאלו נוסעות ומסתלקות למעלה, מסתלקת מי שמסתלקת, דהיינו שהארה חכמה מסתלקת, מסבת הסתלקות השרשים של א\"ט ב\"ח ג\"ז ד\"ו. ואחר כך, האותיות אבג\"ד, חוזרות ונראות בתוך הענפים בשלמות כמו בסוד הראשון, \u0003אט ב\"ח גז דו\u0004 ונרקם מהם הרקיע, אז הוא מאיר באור החכמה."],[7,"","פירוש. בהופעת קו האמצעי שה\"ס צד מזרח, יש ב' פעולות, א' למעט כל החכמה שבקו שמאל ע\"י גילוי המנעולא שבמסך שלו, ופעולה ב' להמתיק המנעולא בבחינת מפתחא, שבזה מחזיר הו\"ק דחכמה שתאיר בקו שמאל ע\"י חבורו עם הימין. (כמ\"ש פרשת לך דף י\"ג ד\"ה לפיכך ע\"ש)."],[7,"","וז\"ש \u0003כד נטיל האי רקיעא מסטרא דמזרח\u0004 דהיינו הופעת קו האמצעי, \u0003אינון ד' רישין\u0004 וכו' \u0003וסלקי בסליקו לעילא,\u0004 דהיינו פעולה א' של קו האמצעי, שבסבתה מסתלקת כל החכמה, ואז מסתלקים כל ד' השורשים אבג\"ד מן ענפים \u0003ט' ח' ז' ו'. וכד אלין נטלין וסלקין לעילא, אסתלקת מאן דאסתלקת.\u0004 דהיינו כל הארת החכמה. ואח\"כ בפעולה ב' אחר שממשיך המפתחא ומיחד ב' הקוין זה בזה וחוזר החכמה להתגלות כנ\"ל זהו שאומר, \u0003ואתוון אתהדרו ואתחזיין בשלימו,\u0004 שהן חוזרות ומתגלות עם שרשיהן, \u0003א\"ט ב\"ח\u0004 וכו'."],[8,"וכד האי רקיעא וכו':","וכשרקיע ההוא האיר כבתחילה באותיות אלו, א\"ט ב\"ח וכו', כולם חוזרים ושאגים לטרוף טרף ומזון. כיון שהם שאגים ומעלים קול, קול ההוא נשמע למעלה למעלה, ואז לוקח ברכות וקדושות מי שראוי לקחת."],[9,"סחרן אתוון ומלמגלגלן וכו':","האותיות א\"ט ב\"ח וכו' מסתובבות ומתגלגלות, על ג' קוין (כנ\"ל אות שמ\"ו ע\"ש). ומסבבות רקיע ההוא, שעל המלכות, והן עומדות לצד דרום. כיון שאלו האותיות עומדות לצד דרום, עולות ונוצצות בהתנוצצות ולוהטות. אז באמצע רקיע ההוא נתרשמה רשימה אחת, ורשימה ההיא היא אות אחת, שהיא \u0003י'.\u0004 כיון שאות זו נרשמת ונראית, אז לוהטות אחריה ג' אותיות אחרות שהם \u0003הו\"ה.\u0004 ומאיר שם הוי\"ה."],[10,"אלין אתוון מנצצן וכו':","אלו האותיות הוי\"ה, נוצצות באמצע רקיע הזה, עולות ויורדות ולוהטות בי\"ב להטים, דהיינו בי\"ב צירופי הויה, (כנ\"ל אות שמ\"ה) אז אחר שאלו לוהטות י\"ב פעמים, יורדת מי שיורדת, דהיינו הארת החכמה, ונכללת באלו האותיות של י\"ב צירופי הויה, ומתעטרת בהן ואינה נודעת אז כל החיילות וכל המחנות בשמחה ומעלים שירות ותשבחות."],[11,"רקיעא דא נטלא וכו':","רקיע הזה נוסע שנית, ומסבב ומתגלגל על ג' קוין (כנ\"ל אות שמ\"ו) ואלו אותיות הראשונות שאמרנו, שהם \u0003א\"ט ב\"ח\u0004 וכו', כולן נכללות באלו אותיות עליונות שהן סוד השם הקדוש הויה שאמרנו, ומסבבים רקיע ההיא, ואלו האותיות הויה, שהיו עומדות באמצע, שהן סוד השם הקדוש, נרשמו לצד צפון, שהוא שמאל, ונרשמו ולא נרשמו, כי אין מי שיסתכל בצד ההוא, דהיינו להמשיך חכמה, שה\"ס ראיה, כולם מתכסים מחכמה ואומרים בקול נעימות, ברוך כבוד ה' ממקומו. מתכסים בצד צפון, שה\"ס קו השמאל, ואומרים זה, ומתכסים בכל הצדדים ואומרים זה. דהיינו ברוך כבוד ה' ממקומו. כי צד צפון כלול בכל ג' הצדדים. והטעם הוא כי אין החכמה מגולה אלא במלכות המקבלת מג' קוין, ולא בג' קוין עצמם. (כנ\"ל בא דף רע\"ו ד\"ה ועוד)."]],[[0,"","פֶּתַח שֵׁנִי רָשׁוּם לְצַד צָפוֹן, וּבוֹ עוֹמֶדֶת אוֹת אַחַת, וְהִיא הָאוֹת ד'. וְזוֹ עוֹמֶדֶת וְנוֹצֶצֶת, עוֹלָה וְיוֹרֶדֶת, וְלוֹהֶטֶת בְּאוֹתוֹ פֶּתַח. לִפְעָמִים נוֹצֶצֶת בְּהִתְנוֹצְצוּת, וְלִפְעָמִים נִטְמָן אוֹתוֹ אוֹר וְלֹא מֵאִיר. וְלָכֵן הָאוֹת הַזּוֹ אֵינָהּ עוֹמֶדֶת בְּקִיּוּם מַתְמִיד, וְהָאוֹת הַזּוֹ נִרְשֶׁמֶת בְּאוֹתוֹ פֶּתַח."],[1,"","הַפֶּתַח הַשְּׁלִישִׁי הוּא פֶּתַח שֶׁעוֹמֵד לְצַד מַעֲרָב, וּבוֹ עוֹמֶדֶת אוֹת אַחַת שֶׁרְשׁוּמָה וּנְאוֹרָה בְּאוֹתוֹ פֶּתַח, וְזוֹהִי הָאוֹת נ', וְהָאוֹת הַזּוֹ נוֹצֶצֶת בְּהִתְנוֹצְצוּת בְּאוֹתוֹ הַפֶּתַח."],[2,"","הַפֶּתַח הָרְבִיעִי זֶהוּ הַפֶּתַח שֶׁעוֹמֵד לְצַד דָרוֹם, וּבוֹ עוֹמֵד רֹשֶׁם שֶׁל נְקֻדָּה תַחְתּוֹנָה קְטַנָּה שֶׁנִּרְאֵית וְלֹא נִרְאֵית, וְזוֹהִי הָאוֹת י', וְאַרְבַּע הָאוֹתִיּוֹת הַלָּלוּ לְאַרְבָּעָה צְדָדִים, (נוצצים) בְּאוֹתוֹ רָקִיעַ בְּאוֹתָם פְּתָחִים."],[3,"","בָּרָקִיעַ הַזֶּה רְשׁוּמוֹת אוֹתִיּוֹת אֲחֵרוֹת (לד' צדדים) בִּכְתָרִים עַל רָאשֵׁיהֶם, וְאוֹתָן עֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת מִתְעַטְּרוֹת בִּכְתָרִים. הָרָקִיעַ הַזֶּה נוֹסֵעַ וְסוֹבֵב עַל גַּבֵּי הַחַיּוֹת בָּרֹשֶׁם שֶׁל הָאוֹתִיּוֹת, הַסּוֹד שֶׁל חֶשְׁבּוֹן הַיִּחוּד בְּסוֹד שֶׁל צֵרוּף אֶחָד, וְהֵם: א\"ט ב\"ח ג\"ז ד\"ו."],[4,"","הָאוֹתִיּוֹת הַלָּלוּ סוֹבְבוֹת בְּאוֹתוֹ רָקִיעַ בְּסוֹד שֶׁל אוֹתִיּוֹת אֲחֵרוֹת (של מרכבות) עֶלְיוֹנוֹת קְדוֹשׁוֹת נִסְתָּרוֹת, וְאוֹתָן אוֹתִיּוֹת אֲחֵרוֹת (עליונות) שֶׁנִּסְתָּרוֹת סוֹבְבוֹת אֶת אוֹתוֹ רָקִיעַ, וְאָז נִרְאוֹת הָאוֹתִיּוֹת הַלָּלוּ בְּגִלְגּוּל (של הרקיע הזה), שֶׁהֵם א\"ט ב\"ח, וּרְשׁוּמוֹת בָּרָקִיעַ הַזֶּה."],[5,"","בְּשָׁעָה שֶׁמֵּאִיר הָרָקִיעַ הַזֶּה, מְאִירִים בּוֹ אַרְבָּעָה סוֹדוֹת שֶׁל הַשֵּׁמוֹת הַקְּדוֹשִׁים, וְהֵם צֵרוּף בַּצֵּרוּפִים שֶׁל שְׁלֹשִׁים וּשְׁנַיִם שְׁבִילִים. אָז יוֹרֵד טַל מֵהָרָקִיעַ הַזֶּה בְּאוֹתָן הָאוֹתִיּוֹת שֶׁל סוֹד הַשֵּׁם הַקָּדוֹשׁ, וְכָל אוֹתָן מֶרְכָּבוֹת נִזּוֹנוֹת, וְכָל אוֹתָם הַחֲיָלוֹת וְהַמַּחֲנוֹת הַקְּדוֹשִׁים, וְכֻלָּם מְקַבְּלִים בְּשִׂמְחָה."],[6,"","בְּשָׁעָה שֶׁהַדִּין תָּלוּי, הָאוֹתִיּוֹת הַלָּלוּ נִטְמָנוֹת וְנִגְנָזִים אַרְבַּע בְּתוֹךְ אַרְבַּע, וְהֵם ט\"ח ז\"ו. בְּשָׁעָה שֶׁאֵלֶּה נִגְנְזוּ וְנִטְמְנוּ, אָז הַקּוֹל שֶׁל צַד צָפוֹן מִתְעוֹרֵר, וְיוֹדְעִים שֶׁהַדִּין שָׁרוּי עַל הָעוֹלָם. וּבָרָקִיעַ הַזֶּה נִרְשָׁם גָּוֶן אֶחָד שֶׁכּוֹלֵל אֶת כָּל הַגְּוָנִים."],[7,"","כְּשֶׁנּוֹסֵעַ הָרָקִיעַ הַזֶּה מִצַּד הַמִּזְרָח, אוֹתָם אַרְבָּעָה הָרָאשִׁים שֶׁאָמַרְנוּ בְּאַרְבַּע (פנים) אוֹתִיּוֹת, נוֹסְעִים כֻּלָּם בְּמַסָּעוֹת, וְעוֹלִים בָּעֲלִיָּה לְמַעְלָה. וּכְשֶׁנּוֹסְעִים וְעוֹלִים לְמַעְלָה, מִסְתַּלֶּקֶת מִי שֶׁמִּסְתַּלֶּקֶת, וְחוֹזְרוֹת הָאוֹתִיּוֹת וְנִרְאוֹת בִּשְׁלֵמוּת בַּסּוֹד הָרִאשׁוֹן, א\"ט ב\"ח ג\"ז ד\"ו, וְנִרְקָם אוֹתוֹ רָקִיעַ, וְאָז מֵאִיר בְּאוֹר."],[8,"","וּכְשֶׁהָרָקִיעַ הַזֶּה מֵאִיר כְּמִקֹּדֶם בָּאוֹתִיּוֹת הַלָּלוּ, כֻּלָּם שָׁבִים וְשׁוֹאֲגִים לִטְרֹף טֶרֶף וּמָזוֹן. כֵּיוָן שֶׁהֵם שׁוֹאֲגִים וּמַעֲלִים קוֹלוֹת, אוֹתוֹ קוֹל נִשְׁמָע לְמַעְלָה לְמַעְלָה, וְאָז נוֹטֵל בְּרָכוֹת וּקְדֻשּׁוֹת מִי שֶׁנּוֹטֵל."],[9,"","סוֹבְבוֹת הָאוֹתִיּוֹת וּמִתְגַּלְגְּלוֹת, וְסוֹבְבוֹת אֶת אוֹתוֹ רָקִיעַ, וְעוֹמְדוֹת אוֹתָן אוֹתִיּוֹת לְצַד דָּרוֹם. כֵּיוָן שֶׁעוֹמְדוֹת אוֹתָן אוֹתִיּוֹת לְצַד דָּרוֹם, עוֹלוֹת וְנוֹצְצוֹת בְּהִתְנוֹצְצוּת וְלוֹהֲטוֹת, וְאָז בְּאֶמְצַע אוֹתוֹ רָקִיעַ רֹשֶׁם אֶחָד נִרְשָׁם, וְאוֹתוֹ הָרֹשֶׁם הוּא אוֹת אַחַת, וְהִיא י'. כֵּיוָן שֶׁהָאוֹת הַזּוֹ נִרְשְׁמָה וְנִרְאֵית, אָז לוֹהֲטוֹת אַחֲרֶיהָ שָׁלֹשׁ אוֹתִיּוֹת אֲחֵרוֹת, וְהֵן הו\"ה."],[10,"","אֵלּוּ הָאוֹתִיּוֹת מְנַצְנְצוֹת בְּאֶמְצַע הָרָקִיעַ הַזֶּה, עוֹלוֹת וְיוֹרְדוֹת, לוֹהֲטוֹת בִּשְׁלֹשָׁה עָשָׂר (בשנים עשר) לְהָטִים. אָז אַחַר שֶׁאֵלּוּ הַשְּׁלֹשׁ עֶשְׂרֵה פְּעָמִים לוֹהֲטוֹת, יוֹרֵד מִי שֶׁיּוֹרֵד, וְנִכְלֶלֶת בְּאוֹתָן אוֹתִיּוֹת וּמִתְעַטֶּרֶת בָּהֶן וְלֹא נוֹדַעַת. אָז כָּל הַחֲיָלוֹת וְכָל הַמַּחֲנוֹת בְּשִׂמְחָה, וִעוֹלִים שִׁירִים וְתִשְׁבָּחוֹת."],[11,"","הָרָקִֹיעַ הַזֶּה נוֹסֵעַ שֵׁנִית וְסוֹבֵב וּמִתְגַּלְגֵּל, וְאוֹתָן הָאוֹתִיּוֹת הָרִאשׁוֹנוֹת שֶׁאָמַרְנוּ, שֶׁהֵן א\"ט ב\"ח, כֻּלָּן נִכְלָלוֹת בְּאוֹתָן אוֹתִיּוֹת עֶלְיוֹנוֹת, סוֹד הַשֵּׁם הַקָּדוֹשׁ שֶׁאָמַרְנוּ, וְסוֹבְבוֹת לְאוֹתוֹ הָרָקִיעַ, וְעוֹמְדוֹת אוֹתָן אוֹתִיּוֹת שֶׁהָיוּ בְּאֶמְצַע סוֹד הַשֵּׁם הַקָּדוֹשׁ, כֻּלָּן נִרְשָׁמוֹת לְצַד צָפוֹן, וְנִרְשָׁמוֹת וְאֵינָן נִרְשָׁמוֹת. אֵין מִי שֶׁיִּסְתַּכֵּל בְּאוֹתוֹ הַצַּד. כֻּלָּן מְכֻסּוֹת, וְאוֹמֵר בְּקוֹל נֹעַם: בָּרוּךְ כְּבוֹד ה' מִמְּקוֹמוֹ. וּמִתְכַּסּוֹת מִצַּד צָפוֹן (של הפנים) וְאוֹמְרוֹת אֶת זֶה, מִתְכַּסּוֹת מִכָּל הַצְּדָדִים וְאוֹמְרוֹת אֶת זֶה."]]],[["רְקִיעָא דָּא סָחֲרָא כְּמִלְּקַדְמִין, וְאִתְגַּלְגְּלָא מִסִּטְרָא לְסִטְרָא. כְּדֵין קָל נְעִימוּ דְּמַשִׁירְיָין סַגִּיאִין בְּסִטְרָא דָּא, וְקָל נְעִימוּ דְּמַשִׁירְיָין סַגִּיאִין בְּסִטְרָא דָּא, וְכֵן לְד' סִטְרִין. בְּהַהִיא שַׁעֲתָא הַהוּא רְקִיעָא אִתְנְהִיר בִּנְהִירוּ אַחֲרָא, יַתִּיר מִכְּמָּה דְּהֲוָה, וְקַיְּימָא בִּנְהִירוּ בְּגָוֶון אַחֲרָא, כְּלִילָא בְּכָל גַּוְונִין.","וְאִלֵּין אַתְוָון דְּקָאָמְרָן, סַלְּקִין לְעֵילָּא בְּהַהוּא רְקִיעָא, וּמְקַבְּלִין לְאָת חַד דְּאִיהִי עִלָּאָה, דְּקָא מִתְחַבְּרָא בִּשְׁמָא דָּא, דְּאִלֵּין אַתְוָון. בְּגִין דְּאַף עַל גַּב דְּאִלֵּין אַתְוָון דִּשְׁמָא קַדִּישָׁא, הַאי אִיהוּ שְׁמָא דְּאִתְכְּלִיל לְתַתָּא, בְּגִין דְּרָזָא דָּא אִתְכְּלִיל לְעֵילָּא, וְאִתְכְּלִיל לְתַתָּא, וְכַד אִתְכְּלִיל לְתַתָּא, אִלֵּין אַתְוָון סַלְּקִין לְקַבְּלָהּ לְאָת חַד (ד\"א יו\"ד) דְּהָא מֵהַהוּא אָת אִתְּזָנוּ אִלֵּין אַתְוָון לְתַתָּא, וְהַהוּא אָת אִיהוּ ו'. וְנָחִית וְאִתְחֲבְּרוּ אִלֵּין אַתְוָון. בְּהַהוּא אָת, וּכְדֵין כֻּלְּהוּ בְּעִטּוּרָא חֲדָא, וְאִתְעָבִיד שְׁמָא שְׁלִים.","לְתַתָּא, שְׁמָא שְׁלִים וְלָא שְׁלִים. שְׁמָא שְׁלִים בַּחֲמֵשׁ אַתְוָון (ד\"א ולא שלים דתשע אתוון, שמא שלים בחמש אתוון) אִיהוּ, (רכ\"ו ע\"ב) וַיְדוָֹ\"ד. רָזָא דְּכַר וְנוּקְבָּא בִּרְמִיזוּ. שְׁמָא שְׁלִים בִּתְשַׁע אַתְוָון, אִינּוּן יְדוָֹ\"ד אֱלהִים. דָּא אִיהוּ שְׁמָא שְׁלִים מִכֹּלָּא. שְׁמָא אַחֲרָא אִיהוּ בִּרְמִיזוּ, וְאִיהוּ בְּחָמֵשׁ כִּדְקָאָמְרָן. אֲבָל דָּא אִיהוּ שְׁלִים (בראשית מ\"ה ע\"ב) בְּכֹלָּא.","כֵּיוָן דְּמִתְחַבְּרָן אִלֵּין אַתְוָון, הַהוּא רְקִיעָא אַנְהִיר בִּתְלָּתִין וּתְרֵין נְהוֹרִין, כְּדֵין כֹּלָּא אִיהוּ בְּחֶדְוָוה, כֹּלָּא קָאִים בְּרָזָא חֲדָא עֵילָּא וְתַתָּא. כָּל אִינּוּן רְתִיכִין, וְכָל אִינּוּן מַשִׁירְיָין, כֻּלְּהוּ קַיְימִין בְּרָזָא דִּשְׁלִימוּ. וְכָל דַּרְגִּין מְתַקְּנָן עַל אַתְרַיְיהוּ, כָּל חַד וְחַד כְּדְקָא יֵאוֹת.","בְּהַאי רְקִיעָא קָאִים לִסְטַר צָפוֹן, חַד שַׁלְהוֹבָא נָהִיר, דְּלָא שָׁכִיךְ תָּדִיר, וְאִיהוּ רָשִׁים בְּאַתְוָון אַחֲרָנִין, לִיָמִין, וְאִינּוּן עֶשֶׂר שְׁמָהָן, וְסַלְּקִין לְשִׁבְעִין שְׁמָהָן, וְכֻלְּהוּ רְשִׁימִין בְּהַאי רְקִיעָא, וְנַהֲרִין כֻּלְּהוּ כַּחֲדָא.","מְהַאי רְקִיעָא, נַטְלִין כָּל אִינּוּן רְקִיעִין דִּלְתַתָּא, דְּלִסְטַר קְדוּשָּׁה, עַד דְּמָטוּ לְאִינּוּן רְקִיעִין אַחֲרָנִין דְּלִסְטַר אַחֲרָא, וְאִלֵּין אִקְרוּן יְרִיעוֹת עִזִּים, כְּמָה דְאַתְּ אָמֵר וַיַּעַשׂ יְרִיעוֹת עִזִּים לְאֹהֶל עַל הַמִּשְׁכָּן.","בְּגִין דְּאִית יְרִיעוֹת וְאִית יְרִיעוֹת, יְרִיעוֹת הַמִּשְׁכָּן, אִינּוּן יְרִיעוֹת דְּאִקְרוּן רְקִיעֵי חֵיוָון דְּמַשְׁכְּנָא קַדִּישָׁא. יְרִיעוֹת עִזִּים. אִינּוּן רְקִיעִין (ד\"א יריעות) אַחֲרָנִין דְּסִטְרָא אַחֲרָא. אִלֵּין רְקִיעִין בְּרָזָא דִּרְתִּיכִין דְּרוּחִין קַדִּישִׁין. וְאִלֵּין רְקִיעִין דִּלְבַר, דְּקַיְימִין בְּמִלִּין דְּעָלְמָא, וְאִינּוּן סִטְרִין דְּתִיּוּבְתִּין, וְעוֹבָדִין דְּגוּפָא. וְאִלֵּין חַפְיָין עַל אִינּוּן רְקִיעִין דִּלְגוֹ, כִּקְלִיפָה עַל מוֹחָא. רְקִיעִין דִּלְגוֹ אִינּוּן הַהוּא קְלִישׁוּ, דְּקַיְּימָא עַל מוֹחָא, וְאִלֵּין אִקְרוּן שָׁמַיִם לַיְיָ'. לִשְׁמָא חֲדָא דָּא דִּלְתַתָּא.","רְקִיעִין אַחֲרָנִין לְעֵילָּא, וְאִינּוּן רְקִיעִין פְּנִימָאִין, דְּאִקְרוּן רְקִיעֵי הַחַיּוֹת, דְּאִינּוּן רָזָא דִּשְׁמָא קַדִּישָׁא, בְּרָזָא דְּחֵיוָון רַבְרְבָן עִלָּאִין, וְאִלֵּין אִינּוּן רָזִין דְּאַתְוָון (ס\"א רזין עלאין) עִלָּאִין, בְּרָזֵי דְּאוֹרַיְיתָא, כְּלָלָא דְּעֶשְׂרִין וּתְרֵין אַתְוָון, מְחַקְּקָן רְשִׁימִין, דְּנַפְקֵי מִגּוֹ רְקִיעָא עִלָּאָה תְּמִינָאָה. דְּאִיהוּ רָקִיעַ דְּעַל גַּבֵּי חֵיוָון עִלָּאִין, וְהַאי אִיהוּ דְּלֵית לֵיהּ חֵיזוּ. הַאי אִיהוּ טָמִיר וְגָנִיז, לֵית בֵּיהּ גּוָֹון.","כָּל גַּוְונִין מִנֵּיהּ נַפְקֵי. בֵּיהּ לֵית גּוָֹון, לָא אִתְחָזֵי, וְלָא אִתְגַלְיָיא, הַאי אִיהוּ דְּאַפִּיק כָּל נְהוֹרִין. בֵּיהּ לָא אִתְחָזֵי, לָא נְהִירוּ, וְלָא חָשׁוּךְ, וְלָא גּוָֹון כְּלַל, בַּר נִשְׁמָתִין דְּצַדִּיקַיָּיא, דְּחָמָאן מִגּוֹ רְקִיעָא תַּתָּאָה, כְּמִבָּתַר כּוֹתָלָא, נְהִירוּ דְּאַפִּיק וְנָהִיר הַאי רְקִיעָא עִלָּאָה, וְהַהוּא נְהִירוּ דְּלָא פָּסַק, לֵית מַאן דְּיֵדַע לֵיהּ, לֵית מַאן דְּקָאִים בֵּיהּ.","מִתְּחוֹת דָּא, כָּל אִינּוּן רְקִיעִין אִתְכְּלִילוּ בִּשְׁמָא דָּא אִקְרֵי שָׁמַיִם וְאִלֵּין (ד\"א שמא קדישא) (תקון קט\"ו ע\"ב) אִקְרוּן הַשָּׁמַיִם אִינּוּן דִּשְׁמָא עִלָּאָה אִקְרֵי בְּהוֹן, אִינּוּן דִּשְׁמָא קַדִּישָׁא אִתְעֲטָּר בְּהוֹן. וְעַל דָּא כְּתִיב, (תהילים קט״ו:ט״ז) הַשָּׁמַיִם שָׁמַיִם לַיְיָ', לְהַהוּא גְּנִיזוּ דִּרְקִיעָא עִלָּאָה, דְּקָאִים עָלַיְיהוּ."],[[0,"רקיע דא סחרא וכו':","אחר שביאר הפעולות שנעשו ברקיע בג' צדדים מזרח דרום צפון, שהם ג' קוין, שהפעולות בשליטת צד מזרח, ביאר (באות שמ\"ט) וצד דרום (באות שנ\"א) וצד צפון (באות שנ\"ג) מבאר עתה הפעולות הנעשות ברקיע בשליטת צד המערב, שהיא המלכות המקבלת מכל ג' הצדדים ביחד, ואומר, רקיע הזה מסבב כמקודם ומתגלגל מצד לצד בכל ד' צדדים, דהיינו עד המערב שהיא מלכות, אז עולה קול נעימות של מחנות מלאכים רבים מצד זה, וקול נעימות מחנות רבים מצד זה, וכן לכל ד' הצדדים, מזרח דרום צפון ומערב. בשעה ההיא, הרקיע מאיר באור אחר גדול יותר ממה שהיה מאיר בג' צדדים, כי בו מתגלה אור החכמה, שאין מקום גילויה אלא במלכות (כנ\"ל בא דף רע\"ו ד\"ה ועוד) ועומד בהארה בגוון אחר הכלול מכל הגוונים. כי המלכות כלולה מכל ג' גוונים שבג' קוין."],[1,"ואלין אתוון דקאמרן וכו':","ואלו האותיות הוי\"ה שאמרנו עולות למעלה ברקיע ההוא, שעולות לז\"א, ומקבלים שם אות אחת שהוא עליון, דהיינו מז\"א, המתחברת בשם זה של אלו האותיות הויה, כי אע\"פ שאלו האותיות הן של שם הקדוש, דהיינו הויה, עכ\"ז, זה הוא שם שנכלל למטה, דהיינו ברקיע של המלכות, משום שסוד שם הזה נכלל למעלה בז\"א ונכלל למטה במלכות, וכשהשם נכלל למטה, במלכות, עולות אלו האותיות הויה לקבל אות אחת, מז\"א, כי מאות הזו נזונות אלו האותיות הויה שלמטה במלכות, ואות ההיא היא אות \u0003ו',\u0004 שיורדת למלכות, ומתחברות האותיות הויה באות הזו, דהיינו, והויה, שה \u0003ו'\u0004 תורה על ז\"א, המחובר עם הויה שבמלכות, בסוד הוא ובית דינו. ואז כולן בעטרה אחת ונעשה שם שלם."],[2,"לתתא שמא שלים וכו':","השם הויה, למטה, שלם ואינו שלם, כי הוא שלם, מבחינתו עצמו, ואינו שלם, להיותו כלול בבחינת מלכות, שם שלם, הוא בחמש אותיות \u0003והויה,\u0004 שה \u0003ו'\u0004 מז\"א מחוברת בהויה, שיורה על ז\"א ובית דינו שהוא המלכות, שהוא סוד דכר ונוקבא ברמז, כי ה \u0003ו'\u0004 רומזת על דכר, הויה רומזת על נוקבא, שמא שלם לגמרי, הוא בתשע אותיות, שהן \u0003הויה אלהים,\u0004 שהויה רומזת על דכר ואלקים על נוקבא. זה הוא שם שלם לגמרי. שם האחר, והויה, הוא רק ברמז, שה \u0003ו'\u0004 רומזת על דכר, והוא בחמש אותיות כמו שאמרנו. אבל זה, של תשע אותיות, הויה אלקים, הוא שלם לגמרי."],[3,"כיון דמתחברן אינון וכו':","כיון שמתחברים אלו האותיות, דהיינו, והויה, מאיר רקיע ההוא בל\"ב אורות, דהיינו ל\"ב נתיבות החכמה, אז הכל הם בשמחה, הכל עומדים בסוד אחד, למעלה ולמטה, כל אלו המרכבות וכל אלו המחנות כולם עומדים בסוד השלמות, וכל המדרגות מתוקנות על מקומן, כל אחת ואחת כראוי."],[4,"בהאי רקיעא קאים וכו':","ברקיע הזה של המלכות עומד בצד צפון, שהוא מקום הארת החכמה שבמלכות, שלהבת אחת המאירה שאינו נשקט לעולם. דהיינו בחינת גזרא דדינא, שמשם מתגלה החכמה, (כנ\"ל וירא ס\"ד ד\"ה וז\"ש חד) שהדין הזה מכונה שלהבת. והוא רשום באותיות אחרות לימין, והם עשר שמות ועולים לשבעים שמות, כמ\"ש לעיל (וירא אות רע\"ד) שהם יוצאים מן ע\"ב שמות של השם ע\"ב, כמ\"ש שם שה\"ס ע' סנהדרין וב' סהדי. וכולם רשומים ברקיע הזה, ומאירים כולם יחד."],[5,"מהאי רקיעא נטלין וכו':","מרקיע הזה נוסעים כל הרקיעים שלמטה שלצד הקדושה עד שמגיעים לאלו רקיעים אחרים דצד האחר, והם נקראים יריעות עזים, כש\"א, ויעש יריעות עזים לאהל על המשכן."],[6,"בגין דאית יריעות וכו':","משום שיש יריעות ויש יריעות, \u0003יריעות המשכן,\u0004 הן יריעית הנקראות רקיעי החיות של משכן הקדוש. \u0003יריעות עזים,\u0004 הן רקיעים אחרים דצד האחר. אלו רקיעים דמשכן הם בסוד המרכבות של רוחות הקדושים, ואלו רקיעים שמבחוץ, דהיינו יריעות עזים, הם מאירים בדברי העולם, שהם בחינות תשובה ועבודת הגוף של בני העולם. ואלו מכסים על הרקיעים שבפנים, שהם יריעות המשכן, כקליפה המכסה על המוח. רקיעים שבפנים הם קרום קלוש העומד על המוח, והם נקראים \u0003שמים להויה,\u0004 דהיינו לשם אחד הויה, הזה שלמטה במלכות. (כנ\"ל אות שנ\"ה)."],[7,"רקיעין אחרנין לעילא וכו':","רקיעים אחרים יש למעלה, והם רקיעים פנימיים, שהם רקיעים דז\"א, הנקראים רקיעי החיות, שהם סוד השם הקדוש, הויה, בסוד חיות הגדולות העליונות, שהם חג\"ת ומלכות שמחזה ולמעלה דז\"א, ואלו הם סוד אותיות העליונות בסודות התורה, דהיינו הכלל של כ\"ב אותיות חקוקות ורשומות, היוצאות מן רקיע השמיני, שהוא בינה, שהוא רקיע שעל חיות עליונות, חו\"ג תו\"מ דז\"א, ורקיע הזה הוא שאין לו מראה, זה סתור וגנוז אין בו גוון."],[8,"כל גוונין מניה וכו':","כל הגוונים יוצאים ממנו, מרקיע השמיני שהוא בינה, ובו עצמו אין גוון, אינו נראה ואינו מתגלה. זה הוא שהוציא כל המאורות, כי כל המוחין מג' קוין דבינה יוצאים, ובו עצמו אינו נראה לא אור ולא חשך ולא שום גוון כלל. חוץ מנשמות הצדיקים הרואות מן הרקיע התחתון, דהיינו רקיע של המלכות, כמאחורי הכותל, את האור שמוציא ומאיר רקיע העליון הזה, שהוא בינה ואור ההוא של הבינה שאינו נפסק אין מי שידע אותו, אין מי שיעמוד בו."],[9,"מתחות דא כל וכו':","מתחת רקיע זה דבינה, כל הרקיעים נשתכללו בשם זה שנקראים שמים, ואלו נקראים בכתוב, השמים, אלו שהשם העליון נקרא בהם, שהוא הויה שבז\"א, אלו שהשם הקדוש, שהוא מלכות, נתעטר בהם, כי הרקיעים דמלכות מקבלים מרקיעים דז\"א, וע\"כ כתוב השמים שמים להויה, דהיינו לגניזה זו שברקיע העליון, שהוא בינה, העומד עליהם."]],[[0,"","הָרָקִיעַ הַזֶּה סוֹבֵב כְּמִקֹּדֶם וּמִתְגַּלְגֵּל מִצַּד לְצַד, וְאָז קוֹל נְעִימַת הַמַּחֲנוֹת הָרַבִּים בְּצַד זֶה, וְקוֹל נְעִימַת מַחֲנוֹת רַבִּים בְּצַד זֶה, וְכֵן לְאַרְבָּעָה צְדָדִים. בְּאוֹתָהּ שָׁעָה אוֹתוֹ הָרָקִיעַ מֵאִיר בְּאוֹר אַחֵר, יוֹתֵר מִכְּמוֹ שֶׁהָיָה, וְעוֹמֵד בְּאוֹר בְּגָוֶן אַחֵר כָּלוּל מִכָּל הַגְּוָנִים."],[1,"","וְאֵלּוּ הָאוֹתִיּוֹת שֶׁאָמַרְנוּ עוֹלוֹת לְמַעְלָה בְּאוֹתוֹ רָקִיעַ, וּמְקַבְּלִים אוֹת אַחַת שֶׁהִיא עֶלְיוֹנָה, שֶׁמִּתְחַבֶּרֶת בְּשֵׁם זֶה שֶׁל אֵלּוּ הָאוֹתִיּוֹת. מִשּׁוּם שֶׁאַף עַל גַּב שֶׁהָאוֹתִיּוֹת הַלָּלוּ הֵן שֶׁל הַשֵּׁם הַקָּדוֹשׁ, זֶהוּ שֵׁם שֶׁנִּכְלָל לְמַטָּה, מִשּׁוּם שֶׁסּוֹד זֶה נִכְלָל לְמַעְלָה וְנִכְלָל לְמַטָּה, וּכְשֶׁנִּכְלָל לְמַטָּה, אֵלּוּ הָאוֹתִיּוֹת עוֹלוֹת לְקַבֵּל אוֹת אַחַת (יו\"ד), שֶׁהֲרֵי מֵאוֹתָהּ הָאוֹת נִזּוֹנוּ אֵלּוּ הָאוֹתִיּוֹת לְמַטָּה, וְאוֹתָהּ הָאוֹת הִיא ו'. וְיוֹרְדוֹת וּמִתְחַבְּרוֹת הָאוֹתִיּוֹת הַלָּלוּ בְּאוֹתָהּ הָאוֹת, וְאָז כֻּלָּן בְּעִטּוּר אֶחָד, וְנַעֲשֶׂה שֵׁם שָׁלֵם."],[2,"","לְמַטָה, שֵׁם שָׁלֵם וְלֹא שָׁלֵם. שֵׁם שָׁלֵם בְּחָמֵשׁ אוֹתִיּוֹת (ולא שלם של תשע אותיות, שם שלם בחמש אותיות) הוּא - וַיהֹוָ\"ה. סוֹד שֶׁל זָכָר וּנְקֵבָה בְּרֶמֶז. הַשֵּׁם שָׁלֵם הוּא בְּתֵשַׁע אוֹתִיּוֹת, וְהֵם יְהֹוָ\"ה אֱלֹהִים. זֶהוּ שֵׁם שָׁלֵם מֵהַכֹּל. שֵׁם אַחֵר הוּא בְּרֶמֶז, וְהוּא בְּחָמֵשׁ כְּפִי שֶׁאָמַרְנוּ. אֲבָל זֶהוּ שָׁלֵם בַּכֹּל."],[3,"","כֵּיוָן שֶׁמִּתְחַבְּרוֹת הָאוֹתִיּוֹת הַלָּלוּ, אוֹתוֹ רָקִיעַ מֵאִיר בִּשְׁלֹשִׁים וּשְׁנַיִם אוֹרוֹת, וְאָז הַכֹּל הוּא בְּשִׂמְחָה, הַכֹּל עוֹמֵד בְּסוֹד אֶחָד מַעְלָה וָמַטָּה. כָּל אוֹתָן מֶרְכָּבוֹת וְכָל אוֹתָן מַחֲנוֹת, כֻּלָּם עוֹמְדִים בְּסוֹד שֶׁל שְׁלֵמוּת, וְכָל הַדְּרָגוֹת מְתֻקָּנוֹת עַל מְקוֹמָן, כָּל אַחַת וְאַחַת כָּרָאוּי."],[4,"","בָּרָקִיעַ הַזֶּה עוֹמֶדֶת לְצַד צָפוֹן שַׁלְהֶבֶת אַחַת מְאִירָה שֶׁאֵינָהּ שׁוֹכֶכֶת תָּמִיד, וְהִיא רְשׁוּמָה בְּאוֹתִיּוֹת אֲחֵרוֹת לְיָמִין, וְהֵם עֲשָׂרָה שֵׁמוֹת, וְעוֹלוֹת לְשִׁבְעִים שֵׁמוֹת, וְכֻלָּן רְשׁוּמוֹת בָּרָקִיעַ הַזֶּה, וּמְאִירוֹת כֻּלָּן כְּאֶחָד."],[5,"","מֵהָרָקִיעַ הַזֶּה נוֹסְעִים כָּל אוֹתָם הָרְקִיעִים שֶׁלְּמַטָּה שֶׁלְּצַד הַקְּדֻשָּׁה, עַד שֶׁמַּגִּיעִים לְאוֹתָם הָרְקִיעִים הָאֲחֵרִים שֶׁלְּצַד אַחֵר, וְאֵלֶּה נִקְרָאִים יְרִיעוֹת עִזִּים, כְּמוֹ שֶׁנֶּאֱמַר וַיַּעַשׂ יְרִיעֹת עִזִים לְאֹהֶל עַל הַמִּשְׁכָּן."],[6,"","מִשּׁוּם שֶׁיֵּשׁ יְרִיעוֹת וְיֵשׁ יְרִיעוֹת. יְרִיעוֹת הַמִּשְׁכָּן הֵן יְרִיעוֹת שֶׁנִּקְרָאוֹת רְקִיעֵי הַחַיּוֹת שֶׁל הַמִּשְׁכָּן הַקָּדוֹשׁ. יְרִיעוֹת עִזִּים הֵם רְקִיעִים (יריעות) אֲחֵרִים שֶׁל הַצַּד הָאַחֵר. אֵלֶּה רְקִיעִים בְּסוֹד הַמֶּרְכָּבוֹת שֶׁל רוּחוֹת קְדוֹשׁוֹת, וְאֵלֶּה רְקִיעִים שֶׁבַּחוּץ שֶׁעוֹמְדִים בְּדִבְרֵי הָעוֹלָם, וְהֵם צְדָדִים שֶׁל תְּשׁוּבָה וּמַעֲשִׂים שֶׁל הַגּוּף. וְאֵלֶּה מְכַסִּים עַל אוֹתָם רְקִיעִים שֶׁלִּפְנִים, כְּמוֹ קְלִפָּה עַל הַמֹּחַ. הָרְקִיעִים שֶׁלִּפְנִים הֵם אוֹתוֹ קָלוּשׁ שֶׁעוֹמֵד עַל הַמֹּחַ, וְאֵלּוּ נִקְרָאִים שָׁמַיִם לַה'. לַשֵּׁם אֶחָד זֶה שֶׁלְּמַטָּה."],[7,"","רְקִיעִים אֲחֵרִים לְמַעְלָה, וְהֵם רְקִיעִים פְּנִימִיִּים שֶׁנִּקְרָאִים רְקִיעֵי הַחַיּוֹת, שֶׁהֵם סוֹד הַשֵּׁם הַקָּדוֹשׁ בְּסוֹד הַחַיּוֹת הַגְּדוֹלוֹת הָעֶלְיוֹנוֹת, וְאֵלֶּה הֵם הַסּוֹדוֹת שֶׁל הָאוֹתִיּוֹת (סודות עליונים) הָעֶלְיוֹנוֹת בְּסוֹדוֹת הַתּוֹרָה, כְּלָל שֶׁל עֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת חֲקוּקוֹת רְשׁוּמוֹת שֶׁיּוֹצְאוֹת מִתּוֹךְ הָרָקִיעַ הָעֶלְיוֹן הַשְּׁמִינִי, שֶׁהוּא רָקִיעַ עַל גַּבֵּי הַחַיּוֹת הָעֶלְיוֹנוֹת, וְזֶהוּ שֶׁאֵין לוֹ מַרְאֶה. זֶהוּ טָמִיר וְגָנוּז, וְאֵין בּוֹ גָּוֶן."],[8,"","כָּל הַגְּוָנִים יוֹצְאִים מִמֶּנּוּ. אֵין בּוֹ גָּוֶן, וְלֹא נִרְאָה וְלֹא הִתְגַּלָּה. זֶהוּ שֶׁמּוֹצִיא אֶת כָּל הָאוֹרוֹת. בּוֹ לֹא נִרְאֶה לֹא אוֹר וְלֹא חֹשֶׁךְ וְלֹא גָוֶן כְּלָל, פְּרָט לְנִשְׁמוֹת הַצַּדִּיקִים שֶׁרוֹאוֹת מִתּוֹךְ הָרָקִיעַ הַתַּחְתּוֹן כְּמֵאַחַר הַכֹּתֶל, אוֹר שֶׁמּוֹצִיא וּמֵאִיר הָרָקִיעַ הָעֶלְיוֹן הַזֶּה, וְאוֹתוֹ אוֹר שֶׁלֹּא פוֹסֵק, אֵין מִי שֶׁמַּכִּיר אוֹתוֹ וְאֵין מִי שֶׁעוֹמֵד בּוֹ."],[9,"","מִתַּחַת לָזֶה, כָּל אוֹתָם הָרְקִיעִים נִכְלְלוּ בַשֵּׁם הַזֶּה נִקְרָא שָׁמַיִם, וְאֵלּוּ (השם הקדוש) נִקְרָאִים הַשָּׁמַיִם אוֹתָם שֶׁהַשֵּׁם הָעֶלְיוֹן נִקְרָא בָהֶם, אוֹתָם שֶׁהַשֵּׁם הַקָּדוֹשׁ הִתְעַטֵּר בָּהֶם. וְעַל זֶה כָּתוּב, (תהלים קטו) הַשָּׁמַיִם שָׁמַיִם לַה', לְאוֹתָהּ גְּנִיזַת הָרָקִיעַ הָעֶלְיוֹן שֶׁעוֹמֵד עֲלֵיהֶם."]]],[["עַד הָכָא רֶמֶז לִשְׁמָא קַדִּישָׁא, (נ\"א רזא דשמים קדישין) דְּקוּדְשָׁא בְּרִיךְ הוּא אִקְרֵי בִּשְׁמָהָן. מִכָּאן וּלְהָלְאָה, לֵית חַכִּים בְּסָכְלְתָנוּ, דְּיָכִיל לְמִנְדַּע וּלְאִתְדַּבְּקָא כְּלָל. בַּר נְהִירוּ חַד זְעֵיר בְּלָא קִיוּמָא, (נ\"א קיומא דכלא) לְאִתְיַישְּׁבָא בֵּיהּ. זַכָּאָה חוּלָקֵיהּ מַאן דְּעָאל וְנָפַק, וְיָדַע לְאִסְתַּכְּלָא בְּרָזִין דְּמָארִיהּ, וּלְאִתְדַּבְּקָא בֵּיהּ.","בְּרָזִין אִלֵּין יָכִיל בַּר נָשׁ לְאִתְדַּבְּקָא בְּמָארֵיהּ, לְמִנְדַּע שְׁלִימוּ דְּחָכְמָה בְּרָזָא עִלָּאָה, כַּד פָּלַח לְמָארֵיהּ בִּצְלוֹתָא, בִּרְעוּתָא, בְּכִוּוּן לִבָּא, אַדְבַּק רְעוּתֵיהּ כְּנוּרָא בְּגַחַלְתָּא, לְיַיחֵדָא אִינּוּן רְקִיעִין תַּתָּאִין דְּסִטְרָא דִּקְדוּשָּׁה, לְאַעְטְרָא לוֹן בִּשְׁמָא חֲדָא תַּתָּאָה. וּמִתַּמָּן וּלְהָלְאָה לְיַיחֲדָא אִינּוּן רְקִיעִין עִלָּאִין פְּנִימָאִין, לְמֶהוֵי כֻּלְּהוּ חַד, בְּהַהוּא רְקִיעָא עִלָּאָה (רל\"ט ע\"א) דְּקַיְּימָא עָלַיְיהוּ.","וּבְעוֹד דְּפוּמֵיהּ וְשִׂפְוָותֵיהּ מְרַחְשָׁן, לִבֵּיהּ יְכַוֵּון, וּרְעוּתֵיהּ יִסְתָּלַק לְעֵילָּא לְעֵילָּא, לְיַיחֲדָא כֹּלָּא בְּרָזָא דְּרָזִין, דְּתַמָּן תְּקִיעוּ דְּכָל רְעוּתִין וּמַחֲשָׁבִין בְּרָזָא דְּקַיְּימָא בְּאֵין סוֹף, וּלְכַוְּונָא בְּהַאי בְּכָל צְלוֹתָא וּצְלוֹתָא, בְּכָל יוֹמָא וְיוֹמָא לְאַעְטְרָא כָּל יוֹמוֹי, בְּרָזָא דְּיוֹמִין עִלָּאִין בְּפוּלְחָנִיהּ.","בְּלֵילְיָא יְשַׁוֵּי רְעוּתֵיהּ, דְּהָא אִתְפְּטַר מֵעָלְמָא דָּא, וְנִשְׁמָתֵיהּ נַפְקַת מִנֵּיהּ, וְיִהֲדָּר לָהּ לְמָארֵי דְּכֹלָּא, בְּגִין דְּכָל לֵילְיָא וְלֵילְיָא, (ס\"א ההיא נקודה קיימא, לאכללא בגווה אינון נשמתין דצדיקייא).","רָזָא דְּרָזִין לְמִנְדַּע לְאִינּוּן חַכִּימֵי לִבָּא. רְקִיעָא דָּא תַּתָּאָה, בְּרָזָא דְּהַהִיא נְקוּדָה קַיְּימָא, כְּמָה דְּאַמָרָן. הַהוּא רְקִיעָא אִיהוּ כָּלִיל מֵעֵילָּא (ויצא קנ\"ג ע\"ב) וּמִתַּתָּא, וִיסוֹדָא דִּילֵיהּ לְתַתָּא כְּהַאי שְׁרָגָא דְּסַלְּקָא נְהוֹרָא אוּכָמָא, (בראשית נ\"א ע\"א) לְאִתְאַחֲדָא בִּנְהוֹרָא חִוָּורָא, וִיסוֹדָא דִּילָהּ אִיהוּ לְתַתָּא, בְּהַהִיא פְּתִילָה בְּמִשְׁחָא. אוּף הָכִי לְתַתָּא, הַהִיא נְקוּדָה. בִּימָמָא אִתְכְּלִילַת מִלְּעֵילָּא, וּבְלֵילְיָא אִתְכְּלִילַת מִתַּתָּא, בְּאִינּוּן נִשְׁמָתִין דְּצַדִּיקַיָּיא.","וְכָל מִלִּין דְּעָלְמָא, אָהַדְרוּ כֻּלְּהוּ, לְעִקָרָא וִיסוֹדָא וְשָׁרָשָׁא, דְּנַפְקוּ מִנֵּיהּ. וְכַמָּה לֵילָוָון זְמִינִין לְנַטְלָא כָּל חַד וְחַד מַה דְּאִתְחָזֵי לֵיהּ. כְּמָה דְאַתְּ אָמֵר (תהילים ט״ז:ז׳) אַף לֵילוֹת יִסְּרוּנִי כִלְיוֹתָי. נַפְשָׁא אַזְלַת וְשָׁטָאת, וְתָבַת לְהַהוּא עִקָרָא דְּאִתְחָזֵי לָהּ. גּוּפָא קָאִים שָׁכִיךְ כְּאַבְנָא, וְאַהְדָר לְהַהוּא אֲתָר דְּאִתְחָזֵי לֵיהּ, לְמִשְׁרֵי עֲלוֹי, וּבְגִין כַּךְ תָּב גּוּפָא לְסִטְרֵיהּ, וְנַפְשָׁא לְסִטְרָהּ.","גּוּפָא שָׁרֵי עֲלוֹי רָזָא דְּסִטְרָא אַחֲרָא, וּבְגִין כַּךְ אִסְתָּאֲבוּ יְדוֹי, וּבָעֵי לְאַסְחָאָה לוֹן. כְּמָה דְּאוֹקִימְנָא, דְּהָא בְּלֵילְיָא כֹּלָּא תָּב לְאַתְרֵיהּ, וְנִשְׁמָתֵהוֹן דְּצַדִּיקַיָּיא סַלְּקִין וְאִתְהַדְּרָן לְאַתְרַיְיהוּ, וְאִתְעַטְּרַת (בהו) מַה דְּאִתְעַטְּרַת, וְאִתְכְּלִילַת מִכָל סִטְרִין, כְּדֵין סַלְּקָא יְקָרָא דְּקוּדְשָׁא בְּרִיךְ הוּא וְאִתְעַטָּר מִכֹּלָּא.","בְּלֵילְיָא שַׁלְטָאָן מְמָנָן דְּאִתְפְּקָדוּ עַל אִינּוּן נִשְׁמָתִין דְּצַדִּיקַיָּיא, לְסַלְּקָא לוֹן לְעֵילָּא, וּלְקָרְבָא לוֹן קָרְבָּן נַיְיחָא, לְגַבֵּי מָארֵיהוֹן. הַהוּא מְמָנָא דְּאִתְפְּקַד עַל כָּל אִינּוּן מַשִׁירְיָין, (רנ\"ג ע\"א קנ\"ד ע\"א) סוֹרִיָ\"א שְׁמֵיהּ רַב מְמָנָא. כֵּיוָן דְּנִשְׁמְתָא סַלְּקָא בְּכָל אִינּוּן רְקִיעִין, כְּדֵין מְקָרְבִין לָהּ לְגַבֵּיהּ, וְאָרַח בָּהּ כְּמָה דְּאַתְּ אָמַר, (ישעיהו י״א:ג׳) וַהֲרִיחוֹ בְּיִרְאַת יְיָ'. כְּמָה דְּזַמִּין מַלְכָּא מְשִׁיחָא לְמֶעְבַּד בְּעָלְמָא, וְעַל יְדֵיהּ אַעְבָּרוּ כֻּלְּהוּ בְּפִקְדוֹנָא עַל יְדֵיהּ, לְאִתְקָרְבָא לְהָלְאָה.","וְכֻלְּהוּ נִשְׁמָתִין כַּד אִתְקְרִיבוּ לְהַהוּא אֲתָר דְּאִתְקְרִיבוּ, וְאִתְחָזוּן תַּמָּן, דָּא אִיהוּ רָזָא, כֻּלְּהוּ נִשְׁמָתִין אִתְכְּלִילוּ בְּהַהִיא נְקוּדָה, וְנַטְלָא לוֹן זִמְנָא חֲדָא, כְּמַאן דְּבָלַע בְּלִיעוּ דְּמִלָּה, וְאִתְעַבְּרָא כְּאִתְּתָא דְּמִתְעַבְּרָא. רָזָא דָּא לְמָארֵי מְדִין. כַּד הַאי נְקוּדָה אִתְעַבְּרַת, כְּאִתְּתָא דְּמִתְעַבְּרָא, אִתְהֲנֵי מֵהַהִיא הֲנָאוּתָא, דְּאִתְכְּלִילַת נִשְׁמְתָא מְהַאי עָלְמָא, בְּאִינּוּן עוֹבָדִין, וּבְהַהִיא אוֹרַיְיתָא דְּאִשְׁתַּדָּלַת בָּהּ בִּימָמָא. וְנַטְלָא הַהוּא רְעוּ דְּהַאי עָלְמָא, וּבֵיהּ אִתְהֲנֵי בְּחֶדְוָה, וְאִתְכְּלִילַת מִכָּל סִטְרִין.","לְבָתַר אַפִּיקַת לוֹן לְבַר, וְאוֹלִידַת לוֹן כְּמִלְּקַדְּמִין, וְנִשְׁמְתָא אִיהִי חַדְתָּא הַשְׁתָּא כְּמִלְּקַדְמִין, וְרָזָא דָּא (איכה ג׳:כ״ג) חֲדָשִׁים לַבְּקָרִים. חֲדָשִׁים וַדַּאי כְּמָה דְּאִתְּמַר. מַה טַעַם אִינּוּן חֲדָשִׁים. בְּגִין רָזָא דִּכְתִּיב, רַבָּה אֱמוּנָתֶךָ. רַבָּה וַדַּאי, (בראשית י\"ט ע\"ב) דְּיַכְלָא לְאַכְלְלָא לוֹן, וּלְאַעֲלָא לוֹן לְגַוָּוהּ, וְאַפִּיקַת לוֹן וְאִינּוּן חַדְתִּין. וְעַל דָּא נַקְטָא אַחֲרָנִין מִלְּעֵילָּא בִּימָמָא. זַכָּאִין אִינּוּן צַדִּיקַיָּיא בְּעָלְמָא דֵּין, וּבְעָלְמָא דְּאָתֵי."],[[0,"עד הכא רמז וכו':","עד כאן, עד הרקיע דבינה, רמז, בכתוב השמים שמים להויה, לשם הקדוש הויה, כי הקב\"ה, שהוא בינה, נקרא בשמות, ושם, פירושו השגה, כי כל מה שלא נשיג לא נקראהו בשם. מכאן ולהלאה, אחר הבינה, אין חכם שבתבונתו יוכל לדעת ולהשיג כלל, חוץ מהארה אחת מועטת, שאינו מספיק להתישב בו. אשרי חלקו מי שנכנס ויצא וידע להסתכל בסודות רבונו, ולהתדבק בו."],[1,"ברזין אלין יכיל וכו':","בסודות אלו יכול האדם להתדבק באדונו לדעת שלמות החכמה בסוד עליון כשעובד לאדונו, בתפלה, ברצון בכוונת הלב הוא מדבק רצונו כאש בגחלת, ליחד אלו רקיעים התחתונים שמצד הקדושה, שהם ממלכות, לעטר אותם בשם, הויה, אחד תחתון (כנ\"ל אות שנ\"א) שברקיעים דמלכות, ומשם ולהלאה, ליחד אלו רקיעים העליונים הפנימים, שהם רקיעים דז\"א, שיהיו כולם אחד ברקיע ההוא העליון דבינה, העומד עליהם."],[2,"ובעוד דפומיה ושפוותיה וכו':","ובעוד שפיו ושפתיו נעות, יכוון לבו, ורצונו יעלה למעלה למעלה, ליחד הכל בסוד הסודות, ששמה נתקעים כל הרצונות והמחשבות, הנמצא בסוד אין סוף. ולכוון בזה בכל תפלה ותפלה בכל יום ויום, לעטר כל ימיו בסוד הימים העליונים, חג\"ת נהי\"מ, בעבודתו."],[3,"בליליא ישוי רעותיה","וכו': בלילה ישום רצונו, שהוא נפטר מעולם הזה, ונשמתו יוצאת ממנו, ויחזירה לאדון כל. משום שבכל לילה ולילה, עומדת נקודה ההיא, שהיא המלכות לכלול בתוכה אלו נשמות הצדיקים. כלומר, שנשמות הצדיקים עולים למלכות בסוד מ\"נ בכל לילה."],[4,"רזא דרזין למנדע וכו':","סוד הסודות לדעת לאלו חכמי לב. רקיע זה התחתון, בסוד נקודה ההיא עומד, שהיא המלכות, כמו שאמרנו, (באות של\"ט) רקיע ההוא כלול מלמעלה ומלמטה, והיסוד שלו למטה, כנר הזה, המעלה אור שחור, להתאחד באור לבן, שעל אור השחור, דהיינו מלמעלה, ויסוד שלו הוא למטה, בפתילה בשמן, (כנ\"ל בראשית ב' אות רמ\"ט ובהמשך) אף כך נקודה ההיא, שהיא המלכות, יסודה למטה. ביום היא נכללת מלמעלה, מז\"א, בלילה נכללת מלמטה, מאלו נשמות הצדיקים."],[5,"וכל מלין דעלמא וכו':","וכל דברי העולם חוזרים כולם אל העיקר והשורש שמשם יצאו וכמה לילות עתידים כל אחד ואחד לקחת מה שראוי לו. כש\"א, אף לילות יסרוני כליותי. כי בלילה הולך כל דבר לשורשו, כי הנפש הולכת ומשוטטת וחוזרת לשורש ההוא שראוי לה, למעלה, והגוף נשאר שקט כאבן וחוזר למקום הראוי לו שישרה עליו, דהיינו הס\"א שישרה עליו לאחר מותו. ומשום זה הגוף חוזר לצד שלו, והנפש חוזרת לצד שלה."],[6,"גופא שרי עלוי וכו':","הגוף, שחזר לצד שלו, שורה עליו סוד הסטרא אחרא, ומשום זה נטמאו ידיו, וצריך לרחוץ אותן, כמו שהעמדנו, כי בלילה חוזר כל דבר למקומו, לשורשו. ונשמות הצדיקים, עולות וחוזרות למקומן, לשורשם, שהיא המלכות שמשם נולדו, ונתעטרת בהן מי שמתעטרת, דהיינו המלכות, ונכללת מכל הצדדים, דהיינו מלמעלה ומלמטה. אז עולה כבוד הקב\"ה ומתעטר מכל."],[7,"בליליא שלטאן ממנן וכו':","בלילה שולטים ממונים שנתמנו על אלו נשמות הצדיקים, להעלותן למעלה, ולהקריבן קרבן ניחוח אל אדונם. ממונה ההוא שנתמנה על אלו המחנות, שמו \u0003סוריא,\u0004 ממונה עליון. כיון שהנשמה עולה בכל אלו הרקיעים, אז מקרבים אותה אליו, אל סוריא, ומריח בה, כמו שאתה אומר והריחו ביראת ה', דהיינו כמו שעתיד לעשות בעולם המלך המשיח, כן עושה הממונה סוריא. ועל ידו, של סוריא, עוברות כל הנשמות, שהן בפקדון על ידו, להתקרב להלאה, אל המלכות."],[8,"וכלהו נשמתין כד וכו':","וכל הנשמות כשנתקרבו למקום ההוא שנתקרבו, דהיינו להמלכות, ונראות שמה, זה הוא סוד, אז כל הנשמות נכללות בנקודה ההיא, שהיא המלכות, ולוקחת אותן בפעם אחת, כמי שבולע דבר הנבלע, והיא מתעברת עמהן כאשה המתעברת. סוד זה ליושבי על מדין, כשהנקודה הזו מתעברת כאשה המתעברת, היא נהנית מהנאה ההיא שנכללה בה נשמה מעולם הזה, באלו המעשים ובתורה ההיא שעסקה בה ביום. ולוקחת רצון ההוא של עולם הזה ונהנית בו בשמחה ונכללת מכל הצדדים. מלמעלה ומלמטה."],[9,"לבתר אפיקת לון וכו':","אחר כך המלכות מוציאה אותם לחוץ, ומולידה אותן כבתחילה, כי הנשמות הן תולדות המלכות, והנשמה היא עתה חדשה כבתחילת לידתה. וזה סוד, חדשים לבקרים. שסובב על הנשמות, שהן חדשות ודאי בכל בקר, כמו שאמרנו. מה הטעם שהן חדשות, הוא משום סוד הכתוב, רבה אמונתיך. שהמלכות הנקראת אמונה, היא רבה ודאי שיכלה לכלול אותן הנשמות ולהכניסן לתוכה ולהוציאן כשהן חדשות. (כנ\"ל ב\"א צ\"ד ד\"ה וטעם). וע\"כ מקבלת אחרות מלמעלה ביום. אשריהם הצדיקים בעולם הזה ובעולם הבא."]],[[0,"","עַד כָּאן רֶמֶז לַשֵּׁם הַקָּדוֹשׁ, (סוד של השמים הקדושים) שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נִקְרָא בְשֵׁמוֹת. מִכָּאן וָהָלְאָה אֵין חָכָם בְּהַשְׂכֵּל שֶׁיָּכוֹל לָדַעַת וּלְהִדָּבֵק כְּלָל, פְּרָט לְאוֹר אֶחָד קָטָן בְּלִי קִיּוּם (קיום הכל) לְהִתְיַשֵּׁב בּוֹ. אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁנִּכְנָס וְיוֹצֵא, וְיוֹדֵעַ לְהִסְתַּכֵּל בְּסוֹדוֹת אֲדוֹנוֹ וְלִדְבֹּק בּוֹ."],[1,"","בַּסּוֹדוֹת הַלָּלוּ יָכוֹל אָדָם לִדְבֹּק בַּאֲדוֹנוֹ, לָדַעַת אֶת שְׁלֵמוּת הַחָכְמָה בְּסוֹד עֶלְיוֹן כְּשֶׁעוֹבֵד לַאֲדוֹנוֹ בִּתְפִלָּה, בְּרָצוֹן וּבְכַוָּנַת הַלֵּב, מַדְבִּיק רְצוֹנוֹ כְּאֵשׁ בְּגַחֶלֶת לְיַחֵד אוֹתָם רְקִיעִים תַּחְתּוֹנִים שֶׁל צַד הַקְּדֻשָּׁה לְעַטְּרָם בְּשֵּׁם אֶחָד תַּחְתּוֹן. וּמִשָּׁם וָהָלְאָה לְיַחֵד אוֹתָם רְקִיעִים עֶלְיוֹנִים פְּנִימִיִּים לִהְיוֹת כֻּלָּם אֶחָד בְּאוֹתוֹ רָקִיעַ עֶלְיוֹן שֶׁעוֹמֵד עֲלֵיהֶם."],[2,"","וּבְעוֹד שֶׁפִּיו וְשִׂפְתוֹתָיו מְרַחֲשׁוֹת, לִבּוֹ יְכַוֵּן, וּרְצוֹנוֹ יִתְעַלֶּה לְמַעְלָה לְמַעְלָה, לְיַחֵד אֶת הַכֹּל בְּסוֹד הַסּוֹדוֹת, שֶׁשָּׁם תְּקוּעִים כָּל הָרְצוֹנוֹת וְהַמַּחֲשָׁבוֹת בְּסוֹד שֶׁעוֹמֵד בְּאֵין סוֹף, וּלְכַוֵּן בָּזֶה בְּכָל תְּפִלָּה וּתְפִלָּה, בְּכָל יוֹם וָיוֹם, לְעַטֵּר אֶת כָּל יָמָיו בְּסוֹד הַיָּמִים הָעֶלְיוֹנִים בַּעֲבוֹדָתוֹ."],[3,"","בַּלַּיְלָה יָשִׂים רְצוֹנוֹ, שֶׁהֲרֵי נִפְטָר מֵהָעוֹלָם, וְנִשְׁמָתוֹ יוֹצֵאת מִמֶּנּוּ, וְיַחֲזִירֶנָּה לְרִבּוֹן הַכֹּל. מִשּׁוּם שֶׁכָּל לַיְלָה וְלַיְלָה (אותה נקדה עומדת לכלל בתוכה אותן נשמות הצדיקים)."],[4,"","סוֹד הַסּוֹדוֹת לָדַעַת לְאוֹתָם חַכְמֵי לֵב. הָרָקִיעַ הַזֶּה הַתַּחְתּוֹן, בְּסוֹד אוֹתָהּ הַנְּקֻדָּה הוּא עוֹמֵד, כְּמוֹ שֶׁאָמַרְנוּ. אוֹתוֹ הָרָקִיעַ הוּא כָּלוּל מִמַּעְלָה וּמִמַּטָּה, וִיסוֹדוֹ לְמַטָּה כַּנֵּר הַזֶּה שֶׁמַּעֲלֶה אוֹר שָׁחֹר, לְהֵאָחֵז בָּאוֹר הַלָּבָן, וְהַיְסוֹד שֶׁלָּהּ הוּא לְמַטָּה בְּאוֹתָהּ פְּתִילָה בְּשֶׁמֶן. אַף כָּךְ לְמַטָּה אוֹתָהּ נְקֻדָּה - בַּיּוֹם נִכְלֶלֶת מִלְמַעְלָה, וּבַלַּיְלָה נִכְלֶלֶת מִמַּטָּה בְּאוֹתָן נִשְׁמוֹת הַצַּדִּיקִים."],[5,"","וְכָל דִּבְרֵי הָעוֹלָם, כֻּלָּם חוֹזְרִים לָעִקָּר וְהַיְסוֹד וְהַשֹּׁרֶשׁ שֶׁמִּמֶּנּוּ יָצְאוּ. וְכַמָּה לֵילוֹת עֲתִידִים לִטֹּל כָּל אֶחָד וְאֶחָד מַה שֶּׁרָאוּי לוֹ, כְּמוֹ שֶׁנֶּאֱמַר (תהליםטז) אַף לֵילוֹת יִסְּרוּנִי כִלְיוֹתָי. הַנֶּפֶשׁ הוֹלֶכֶת וּמְשׁוֹטֶטֶת וְשָׁבָה אֶל אוֹתוֹ עִקָּר שֶׁרָאוּי לָהּ. הַגּוּף עוֹמֵד שָׁקֵט כְּאֶבֶן, וְחוֹזֵר לְאוֹתוֹ מָקוֹם שֶׁרָאוּי לוֹ לִשְׁרוֹת עָלָיו, וּמִשּׁוּם כָּךְ שָׁב הַגּוּף לַצַּד שֶׁלּוֹ, וְהַנֶּפֶשׁ לַצַּד שֶׁלָּהּ."],[6,"","עֵל הַגּוּף שׁוֹרֶה סוֹד הַצַּד הָאַחֵר, וְלָכֵן נִטְמָאִים יָדָיו, וְצָרִיךְ לִרְחֹץ אוֹתָם. כְּמוֹ שֶׁבֵּאַרְנוּ, שֶׁהֲרֵי בַּלַּיְלָה הַכֹּל שָׁב לִמְקוֹמוֹ, וְנִשְׁמוֹת הַצַּדִּיקִים עוֹלוֹת וְחוֹזְרוֹת לִמְקוֹמָן, וּמִתְעַטֶּרֶת (בהם) מַה שֶּׁמִּתְעַטֶּרֶת, וְנִכְלֶלֶת מִכָּל הַצְּדָדִים, וְאָז עוֹלֶה כְּבוֹד הַקָּדוֹשׁ בָּרוּךְ הוּא וּמִתְעַטֵּר מֵהַכֹּל."],[7,"","בַּלַּיְלָה שׁוֹלְטִים הַמְמֻנִּים שֶׁנִּפְקְדוּ עַל אוֹתָן נִשְׁמוֹת הַצַּדִּיקִים לְהַעֲלוֹתָן לְמַעְלָה וּלְהַקְרִיבָן קָרְבַּן מְנַחֵם לַאֲדוֹנָם. אוֹתוֹ מְמֻנֶּה שֶׁנִּפְקָד עַל כָּל אוֹתָם מַחֲנוֹת, שְׁמוֹ סוֹרִיּ\"א מְמֻנֶּה גָּדוֹל. כֵּיוָן שֶׁעוֹלָה הַנְּשָׁמָה לְכָל אוֹתָם רְקִיעִים, אָז מַקְרִיבִים אוֹתָהּ אֵלָיו וּמֵרִיחַ בָּהּ, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה יא) וַהֲרִיחוֹ בְּיִרְאַת ה'. כְּמוֹ שֶׁעָתִיד מֶלֶךְ הַמָּשִׁיחַ לַעֲשׂוֹת בָּעוֹלָם, וְעַל יָדוֹ עוֹבְרִים כֻּלָּם בְּפִקָּדוֹן עַל יָדוֹ לְהִתְקָרֵב הָלְאָה."],[8,"","וְכָל הַנְּשָׁמוֹת, כְּשֶׁנִּקְרָבוֹת לְאוֹתוֹ מָקוֹם שֶׁנִּקְרָבוֹת וְנִרְאוֹת שָׁם, זֶהוּ סוֹד, כָּל הַנְּשָׁמוֹת נִכְלָלוֹת בְּאוֹתָהּ נְקֻדָּה, וְלוֹקַחַת אוֹתָם פַּעַם אַחַת, כְּמוֹ מִי שֶׁבּוֹלֵעַ בְּלִיעַת דָּבָר, וּמִתְעַבֶּרֶת כְּמוֹ אִשָּׁה שֶׁמִּתְעַבֶּרֶת. הַסּוֹד הַזֶּה לְבַעֲלֵי מִדּוֹת. כְּשֶׁנְּקֻדָּה זוֹ מִתְעַבֶּרֶת כְּאִשָּׁה שֶׁמִּתְעַבֶּרֶת, נֶהֱנֵית מֵאוֹתָהּ הֲנָאָה שֶׁמַּכְלִילָה נְשָׁמָה מֵהָעוֹלָם הַזֶּה בְּאוֹתָם מַעֲשִׂים וּבְאוֹתָהּ תּוֹרָה שֶׁהִשְׁתַּדְּלָה בָּהּ בַּיּוֹם, וְנוֹטֶלֶת אוֹתוֹ רָצוֹן שֶׁל הָעוֹלָם הַזֶּה, וּבוֹ נֶהֱנֵית בְּשִׂמְחָה, וְנִכְלֶלֶת מִכָּל הַצְּדָדִים."],[9,"","אַחַר כָּךְ הִיא מוֹצִיאָה אוֹתָם הַחוּצָה וּמוֹלִידָה אוֹתָם כְּמִקֹּדֶם, וְהַנְּשָׁמָה הִיא חֲדָשָׁה כָּעֵת כְּמִקֹּדֶם, וְסוֹד זֶה - (איכה ג) חֲדָשִׁים לַבְּקָרִים. חֲדָשִׁים וַדַּאי, כְּמוֹ שֶׁנִּתְבָּאֵר. מָה הַטַּעַם הֵם חֲדָשִׁים? מִשּׁוּם סוֹד הַכָּתוּב רַבָּה אֱמוּנָתֶךְ. רַבָּה וַדַּאי, שֶׁיָּכְלָה לְהַכְלִילָם וּלְהַכְנִיסָם לְתוֹכָהּ, וּמוֹצִיאָה אוֹתָם וְהֵם חֲדָשִׁים, וְלָכֵן לוֹקַחַת אֲחֵרִים מִלְמַעְלָה בַּיּוֹם. אַשְׁרֵי הַצַּדִּיקִים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא."]]],[["אַדְּהָכִי נָהָר יְמָמָא, אָמַר רִבִּי אַבָּא, נְקוּם וּנְהַךְ, וְנוֹדֶה לְרִבּוֹן עָלְמָא. קָמוּ וְאָזְלוּ, וְצַלוּ, וּלְבָתַר אָהַדְרוּ חַבְרַיָּיא לְגַבֵּיהּ, אֲמַרוּ לֵיהּ, מַאן דְּשָׁרֵי, לְסַיֵּים שְׁבָחָא. זַכָּאָה חוּלָקָנָא בְּאוֹרְחָא דָּא, דְּכָל הַאי זָכִינָא לְאַעְטְרָא לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, בְּרָזִין דְּחָכְמְתָא.","פָּתַח רִבִּי אַבָּא וְאָמַר, (שמות ל״ז:א׳) וַיַּעַשׂ בְּצַלְאֵל אֶת הָאָרוֹן עֲצֵי שִׁטִּים וְגוֹ'. הָכָא, אַף עַל גַּב דְּכָל רָזִין דְּמַשְׁכְּנָא הָא אוּקְמוּהָ חַבְרַיָּיא בְּאִדָּרָא קַדִּישָׁא. הָכָא אִית לְאִסְתַּכְּלָא, דְּהָא רָזָא דָּא מִתְעַטְּרָא בְּכַמָּה רָזִין, לְמֵילַף חָכְמְתָא. אָרוֹן דָּא אִיהוּ רָזָא לְמֵיעַל תּוֹרָה שֶׁבִּכְתָּב. וְאִתְגְּנִיז בֵּיהּ בְּשִׁית לוּחִין (ס\"א ואתגניזן ביה שית לוחין ואינון שית מסחרין) מְסַחֲרִין, וְדָא אִקְרֵי אָרוֹן. כַּד סָחֲרָן אִינּוּן שִׁית לְמֶהוֵי כַּחֲדָא, כְּדֵין אִיהוּ גּוּפָא חַד לְאַעֲלָא בֵּיהּ רָזָא דְּאוֹרַיְיתָא, בְּשִׁית סִטְרִין וַאָרוֹן.","לוּחִין אִינּוּן חָמֵשׁ, וְעָאלִין בֵּיהּ חָמֵשׁ סְפָרִים, וְאִינּוּן חָמֵשׁ אִינּוּן שִׁית, בְּחַד דַּרְגָּא דְּאָעִיל בָּהּ בִּגְנִיזוּ, דְּאִקְרֵי רָזָא דְּכֹלָּא, וְהַאי אִיהוּ רָזָא דִּבְרִית. כַּד עָאל דָּא, גּוֹ אִינּוּן חָמֵשׁ לוּחִין, כְּדֵין קַיְּימָא אֲרוֹנָא וְאוֹרַיְיתָא, בְּרָזָא דִּתְשַׁע דַּרְגִּין, (רי\"ג ע\"א) דְּאִינּוּן תְּרֵין שְׁמָהָן, יְהוָֹ\"ה אֱלהִי\"ם. וּלְבָתַר קַיְּימָא לוּחָא חֲדָא, רָזָא עִילָאָה דְחַפְיָא עַל כֹלָּא וְהַהוּא הֲוֵי רָזָא דְּהַהוּא רְקִיעָא דְסַחָרָא וְחַפֵי עַל כֹּלָּא וְכֻלְּהוּ קַיְימֵי בִּגְנִיזוּ.","הָכָא אִית לָן לְאִסְתַּכְּלָא, וּלְמִנְדַּע רָזִין דַּאֲרוֹנָא, אִית אָרוֹן וְאִית אָרוֹן, דָּא לָקֳבֵל דָּא. פָּתַח וְאָמַר, (שמואל ב כ״ד:כ״ג) הַכֹּל נָתַן אֲרַוְנָה הַמֶּלֶךְ לַמֶּלֶךְ וְגוֹ'. וְכִי אֲרַוְנָה מֶלֶךְ הֲוָה וְאַף עַל גַּב דְּחַבְרַיָּיא אוּקְמוּהָ, אֶלָּא דָּוִד, דִּכְתִּיב בֵּיהּ (שמואל ב ה׳:ח׳) כָּל מַכֵּה יְבוּסִי וְיִּגַּע בַּצִּנּוֹר וְגוֹ' וְאִיהוּ נָטַל וְתָּפִיס לִיְרוּשָׁלַ ם, וּמִדִּידֵיהּ הֲוָה, אֲמַאי קָנָה בְּכַסְפָּא. וְאִי תֵּימָא אַף עַל גַּב דַּהֲוַות יְרוּשָׁלַם דִּידֵיהּ דְּדָוִד, הַהוּא אֲתָר אַחֲסַנְתֵּיהּ דַּאֲרַוְנָה הֲוָה, כְּמָה דְּהֲוָה בְּנָבוֹת הַיִּזְרְעֵאלִי, דְּאַף עַל גַּב דְּשַׁלִּיט אַחְאָב, וַהֲוָה מַלְכָּא, אִצְטְרִיךְ לְמִתְבַּע לְנָבוֹת הַהוּא כֶּרֶם, אוּף הָכִי דָּוִד.","אֶלָּא וַדַּאי אֲרַוְנָה מַלְכָּא הֲוָה, וְהַהוּא אֲתָר בִּרְשׁוּתֵיהּ הֲוָה, וַהֲוָה שַׁלִּיט עֲלוֹי, וְכַד מָטָא זִמְנָא לְנָפְקָא מִתְּחוֹת יְדֵיהּ, לָא נָפִיק אֶלָּא בִּסְגִיאוּת דָּמָא וְקָטוֹלָא בְּיִשְׂרָאֵל. לְבָתַר קָאִים הַהוּא מַלְאָכָא מְחַבְּלָא עַל הַהוּא אֲתָר, וְתַמָּן כַּד הֲוָה קָטִיל, וְקָאִים בְּהַהוּא אֲתָר, לָא הֲוָה יָכִיל, וְתָשַׁשׁ חֵילֵיהּ.","וְהַהוּא אֲתָר, אֲתָר דְּאִתְעֲקַד בֵּיהּ יִצְחָק הֲוָה, דְּתַמָּן בָּנָה אַבְרָהָם מַדְבְּחָא, וְעָקַד לֵיהּ לְיִצְחָק בְּרֵיהּ. כֵּיוָן דְּחָמָא קוּדְשָׁא בְּרִיךְ הוּא הַהוּא אֲתָר, אִתְמְלֵי רַחֲמִין, הֲדָא הוּא דִכְתִיב, (דברי הימים א כא) רָאָה יְיָ' וַיִּנָּחֵם וְגוֹ'. מַהוּ רָאָה יְיָ'. חָמָא עֲקֵידַת יִצְחָק בְּהַהוּא אֲתָר, וְתָב וְרִיחַם עֲלַיְיהוּ מִיַּד.","וַיֹּאמֶר לַמַּלְאַךְ הַמַּשְׁחִית רַב עַתָּה וְגוֹ'. מַהוּ רַב. הָא אוּקְמוּהָ, טוֹל הָרַב. אֶלָּא הָכִי הוּא, כְּתִיב הָכָא רַב, וּכְתִיב הָתָם, (דברים א׳:ו׳) רַב לָכֶם שֶׁבֶת בָּהָר הַזֶּה. אוּף הָכִי נָמֵי רַב, רַב לָךְ לְמֶהֱוֵי הַאי אֲתָר תְּחוֹת יְדָךְ, שְׁנִין סַגִּיאִין הֲוָה תְּחוֹת יְדָךְ, מִכָּאן וּלְהָלְאָה רַב, אָהֲדַר אַתְרָא לְמָארֵיהּ. וְעִם כָּל דָּא (בדמא) בְּמוֹתָא וּמָמוֹנָא נָפַק מִתְּחוֹת יְדֵיהּ.","אֲמַאי אִקְרֵי אֲרַוְנָה. אֶלָּא כְּתִיב אֲרַוְנָה וּכְתִיב אָרְנָן. בְּעוֹד דְּהַהוּא אֲתָר הֲוָה תְּחוֹת יְדֵיהּ, אִקְרֵי אֲרַוְנָה אֲרוֹן דְּסִטְרָא אַחֲרָא. וְעַל דְּאִתּוֹסָפוּ בֵּיהּ אַתְוָון יַתִּיר, הָכִי אִצְטְרִיךְ (קס\"ד ע\"ב) לְאִתּוֹסְפָא לְהַהוּא רַע עַיִן, רָזָא דְּסִטְרָא אַחֲרָא, וְהַהוּא תּוֹסֶפֶת אִיהוּ גְּרִיעוּתָא לְגַבֵּיהּ."],[[0,"אדהכי נהיר יממא וכו':","בתוך כך האיר היום. אמר ר' אבא נקום ונלך ונודה לרבון העולם. קמו והלכו והתפללו, ואח\"כ חזרו החברים אליו, לר\"א, אמרו לו מי שהתחיל הוא יסיים השבח. אשרי חלקנו בדרך הזה שזכינו כל כך לעטר להקב\"ה בסודות החכמה."],[1,"פתח ר' אבא וכו':","פר\"א, ויעש בצלאל את הארון עצי שטים וגו'. כאן, אע\"פ שכל הסודות של המשכן העמידו החברים באדרא קדישא, כאן יש להסתכל, כי סוד זה מתעטר בכמה סודות ללמוד חכמה. \u0003ארון\u0004 זה הוא סוד להכניס בו תורה שבכתב. כי ארון ה\"ס מלכות, ותורה שבכתב ה\"ס ז\"א. והתורה נגנזה בו בשש לוחות מסבבים, כי הארון נעשה משש לוחות, ד' לוחות מסבבים מד' צדדיו, ולוח אחד למעלה ולוח אחד למטה, הרי ששה וזה נקרא ארון. כשמסבבין אלו ששה לוחות, שה\"ס חג\"ת נה\"י דמלכות, להיות אחד, אז הוא גוף אחד להכניס בו סוד התורה, שהיא בששה קצוות, חג\"ת נה\"י, דהיינו ז\"א."],[2,"ואינון לוחין אינון וכו':","ואלו הלוחות של הארון, הם חמשה, ד' לוחות שבצדדים ואחד למטה, שהם כנגד חג\"ת נ\"ה כי הלוח שלמעלה ה\"ס הכפורת שעליו, ואינו מן הארון, ונכנסים בו חמשה ספרים, דהיינו חמשה חומשי תורה, שה\"ס חג\"ת נ\"ה דז\"א. ואלו חמשה לוחות הם ששה, עם מדרגה אחת הנכנס בהם בסתר, הנקראת סוד הכל, וזה היא סוד הברית, שהוא יסוד, ולהיותו בסתר, אין כנגדו לוח בארון. כשזה נכנס תוך אלו חמשה לוחות, אז עומדים הארון והתורה בסוד ט' מדרגות שהם ב' שמות הויה אלקים, שיש בהם ט' אותיות. ואחר כך עומד לוח אחד שהוא סוד עליון, דהיינו הכפורת, שהוא מכסה על הכל. וזה, הוא סוד רקיע ההוא המסבב ומכסה על הכל, דהיינו רקיע השמיני שהוא בינה (כנ\"ל אות שס\"א) ומשום זה, שהכפורת מכסה עליהם, עומדים הכל בגניזה, כלומר שאינם נראים."],[3,"הכא אית לאסתכלא וכו':","כאן יש להסתכל ולדעת סוד הארון. כי יש ארון, ויש ארון, דהיינו מלכות דקדושה, ומלכות דסטרא אחרא, זה לעומת זה. פתח ואמר, הכל נתן ארונה המלך למלך וגו'. שואל, וכי ארונה היה מלך. אע\"פ שהחברים העמידוהו, אלא דוד שכתוב בו כל מכה יבוסי ויגע בצנור וגו' שהוא לקח וכבש את ירושלים, ומקום המקדש שלו היה, למה קנה אותו בכסף מן ארונה. ואם תאמר, אע\"פ שירושלים היתה שלו, של דוד, עכ\"ז, מקום ההוא היה נחלת ארונה, והיה צריך לקנותו, כמו שהיה בנבות היזרעאלי, שאע\"פ שאחאב היה שולט והיה מלך היה צריך לבקש כרם ההוא ממנו, אף דוד כך."],[4,"אלא ודאי ארונה וכו':","ומשיב. אלא ודאי ארונה היה מלך, ומקום ההוא היה ברשותו והיה שולט עליו, וכשהגיע הזמן לצאת מתחת ידיו, לא יצא אלא בהרבה דם והריגה בישראל, דהיינו ע\"י מלחמה ואח\"כ עמד מלאך המחבל ההוא על מקום ההוא, ושם, כשהיה הורג ועומד במקום ההוא, לא היה יכול להרוג ותש כחו."],[5,"וההוא אתר אתר וכו':","ומקום ההוא היה המקום שנעקד בו יצחק, ששם בנה אברהם את המזבח ועקד את יצחק בנו. כיון שראה הקב\"ה את מקום ההוא, נתמלא רחמים. ז\"ש ראה ה' וינחם וגו'. מה ראה ה'. ראה עקדת יצחק במקום ההוא, ושב ורחם עליהם מיד."],[6,"ויאמר למלאך המשחית רב עתה וגו':","מהו \u0003רב.\u0004 הרי העמידוהו, קח את הרב (ברכות סב:) אלא כך הוא, כתוב כאן, רב, וכתוב שם, \u0003רב\u0004 לך שבת בהר הזה, שפירושו די, אף כך, גם \u0003רב\u0004 שבכאן פירושו, די לך שיהיה מקום הזה תחת ידך, שנים רבות היה תחת ידך, מכאן ולהלאה, רב, דהיינו די, החזיר המקום לבעליו. ועם כל זה, במות ובכסף יצא מתחת ידו."],[7,"אמאי אקרי ארונה וכו':","שואל, למה נקרא ארונה. ומשיב, אלא כתוב, ארונה, וכתוב, ארנן, הפירוש הוא, בעוד שהמקום ההוא היה תחת ידו הוא נקרא ארונה, שרומז על ארון דסטרא אחרא, שהוא המלכות שלהם, ומה שנתוספו בו אותיות יותר, על המלה ארון, שנקרא ארונה, כך צריך להתוסף לרע עין, שהוא סוד הסטרא אחרא, כי תוספת ההיא היא אצלו לגרעון."]],[[0,"","בֵּין כָּךְ הֵאִיר הַיּוֹם. אָמַר רַבִּי אַבָּא, נָקוּם וְנֵלֵךְ וְנוֹדֶה לְרִבּוֹן הָעוֹלָם. קָמוּ וְהָלְכוּ וְהִתְפַּלְלוּ, וְאַחַר כָּךְ חָזְרוּ אֵלָיו הַחֲבֵרִים. אָמְרוּ לוֹ, מִי שֶׁהִתְחִיל - שֶׁיְּסַיֵּם אֶת הַשֶּׁבַח. אַשְׁרֵי חֶלְקֵנוּ בַּדֶּרֶךְ הַזּוֹ, שֶׁכָּל זֶה זָכִינוּ לְעַטֵּר אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בְּסוֹדוֹת הַחָכְמָה."],[1,"","פָּתַח רַבִּי אַבָּא וְאָמַר, וַיַּעַשׂ בְּצַלְאֵל אֶת הָאָרוֹן עֲצֵי שִׁטִּים וְגוֹ'. כָּאן, אַף עַל גַּב שֶׁכָּל סוֹדוֹת הַמִּשְׁכָּן הֲרֵי פֵּרְשׁוּהָ הַחֲבֵרִים בַּחֶדֶר הַקָּדוֹשׁ, כָּאן יֵשׁ לְהִסְתַּכֵּל, שֶׁהֲרֵי סוֹד זֶה מִתְעַטֵּר בְּכַמָּה סוֹדוֹת לִלְמֹד חָכְמָה. אָרוֹן זֶה הוּא סוֹד לְהַכְנִיס תּוֹרָה שֶׁבִּכְתָב, וְנִגְנְזָה בּוֹ בְּשִׁשָּׁה לוּחוֹת (ונגנזו בו ששה לוחות, והם ששה מסובבים) מְסוֹבָבִים, וְזֶה נִקְרָא אָרוֹן. כְּשֶׁסּוֹבְבִים אוֹתָם שִׁשָּׁה לִהְיוֹת כְּאֶחָד, אָז הוּא גוּף אֶחָד לְהַכְנִיס בּוֹ סוֹד הַתּוֹרָה בְּשִׁשָּׁה צְדָדִים וַאָרון."],[2,"","וְהַלּוּחוֹת הֵם חֲמִשָּׁה, וּמַכְנִיסִים בּוֹ חֲמִשָּׁה סְפָרִים, וְאוֹתָם חֲמִשָּׁה הֵם שִׁשָּׁה בְּדַרְגָּה אַחַת שֶׁנִּכְנֶסֶת בָּהּ בְּנִסְתָּר, שֶׁנִּקְרֵאת סוֹד הַכֹּל, וְזֶהוּ סוֹד הַבְּרִית. כְּשֶׁזֶּה נִכְנָס לְתוֹךְ אוֹתָם חֲמִשָּׁה לוּחוֹת, אָז עוֹמֵד הָאָרוֹן וְהַתּוֹרָה בְּסוֹד שֶׁל תֵּשַׁע דְּרָגוֹת, שֶׁהֵן שְׁנֵי שֵׁמוֹת, יְהֹוָ\"ה אֱלֹהִי\"ם. וְאַחַר כָּךְ עוֹמֵד לוּחַ אֶחָד, סוֹד עֶלְיוֹן שֶׁמְּכַסֶּה עַל הַכֹּל, וְהוּא אוֹתוֹ הַסּוֹד שֶׁל אוֹתוֹ רָקִיעַ שֶׁמְּסוֹבֵב וּמְכַסֶּה עַל הַכֹּל, וְכֻלָּם עוֹמְדִים בַּסֵּתֶר."],[3,"","כָּאן יֵשׁ לְהִסְתַּכֵּל וְלָדַעַת אֶת סוֹדוֹת הָאָרוֹן. יֵשׁ אָרוֹן וְיֵשׁ אָרוֹן, זֶה כְּנֶגֶד זֶה. פָּתַח וְאָמַר, (שמואל ב כב) הַכֹּל נָתַן אֲרַוְנָה הַמֶּלֶךְ לַמֶּלֶךְ וְגוֹ'. וְכִי אֲרַוְנָה הָיָה מֶלֶךְ? וְאַף עַל גַּב שֶׁבֵּאֲרוּהָ הַחֲבֵרִים, אֶלָּא דָּוִד, שֶׁכָּתוּב בּוֹ (שם ה) כָּל מַכֵּה יְבֻסִי וְיִגַּע בַּצִּנּוֹר וְגוֹ', וְהוּא נָטַל וְתָפַס אֶת יְרוּשָׁלַיִם וּמִשֶּׁלּוֹ הָיָה, וְלָמָּה קָנָה בְּכֶסֶף? וְאִם תֹּאמַר, שֶׁאַף עַל גַּב שֶׁיְּרוּשָׁלַיִם הָיְתָה שֶׁל דָּוִד - אוֹתוֹ מָקוֹם הָיָה נַחֲלָתוֹ שֶׁל אֲרַוְנָה, כְּמוֹ שֶׁהָיָה בְּנָבוֹת הַיִּזְרְעֵאלִי (מלכים א כא), שֶׁאַף עַל גַּב שֶׁשָּׁלַט אַחְאָב וְהָיָה מֶלֶךְ, הִצְטָרֵךְ לְבַקֵּשׁ אוֹתוֹ כֶּרֶם מִנָּבוֹת, אַף כָּךְ דָּוִד?"],[4,"","אֶלָּא וַדַּאי אֲרַוְנָה הָיָה מֶלֶךְ, וְאוֹתוֹ מָקוֹם הָיָה בִּרְשׁוּתוֹ וְהָיָה שׁוֹלֵט עָלָיו, וּכְשֶׁהִגִּיעַ זְמַן לָצֵאת מִתַּחַת יָדוֹ, לֹא יָצָא אֶלָּא בְּהַרְבֵּה דָם וְהָרַג בְּיִשְׂרָאֵל, וְאַחַר כָּךְ עָמַד הַמַּלְאָךְ הַמַּשְׁחִית עַל אוֹתוֹ מָקוֹם, וְשָׁם, כְּשֶׁהָיָה הוֹרֵג וְעוֹמֵד בְּאוֹתוֹ מָקוֹם, לֹא הָיָה יָכוֹל, וְתָשַׁשׁ כֹּחוֹ."],[5,"","וְאוֹתוֹ מָקוֹם, הַמָּקוֹם שֶׁנֶּעֱקַד בּוֹ יִצְחָק הָיָה, שֶׁשָּׁם בָּנָה אַבְרָהָם מִזְבֵּחַ וְעָקַד אֶת יִצְחָק בְּנוֹ. כֵּיוָן שֶׁרָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹתוֹ מָקוֹם, הִתְמַלֵּא רַחֲמִים. זֶהוּ שֶׁכָּתוּב רָאָה ה' וַיִּנָּחֶם וְגוֹ'. מַה זֶּה רָאָה ה'? רָאָה עֲקֵדַת יִצְחָק בְּאוֹתוֹ מָקוֹם, וְשָׁב וְרִחֵם עֲלֵיהֶם מִיָּד."],[6,"","וַיֹּאמֶר לַמַּלְאָךְ הַמַּשְׁחִית רַב עַתָּה וְגוֹ'. מַה זֶּה רַב? הֲרֵי פֵּרְשׁוּהָ, קַח אֶת הָרַב. אֶלָּא כָּךְ הוּא, כָּתוּב כָּאן רַב, וְכָתוּב שָׁם רַב לָכֶם שֶׁבֶת בָּהָר הַזֶּה. אַף כָּךְ גַּם רַב - רַב לְךְ שֶׁיִּהְיֶה מָקוֹם זֶה תַּחַת יָדְךְ. שָׁנִים רַבּוֹת הָיָה תַחַת יָדְךְ, מִכָּאן וָהָלְאָה רַב, הַחֲזֵר אֶת הַמָּקוֹם לִבְעָלָיו. וְעִם כָּל זֶה, (בדם) בְּמָוֶת וּבְמָמוֹן יָצָא מִתַּחַת יָדוֹ."],[7,"","וְלָמָּה נִקְרָא אֲרַוְנָה? אֶלָּא כָּתוּב אֲרַוְנָה, וְכָתוּב אָרְנָן. בְּעוֹד שֶׁאוֹתוֹ מָקוֹם הָיָה תַחַת יָדוֹ, נִקְרָא אֲרַוְנָה, אָרוֹן שֶׁל הַצַּד הָאַחֵר. וְעַל שֶׁנּוֹסְפוּ בוֹ אוֹתִיּוֹת יְתֵרוֹת, כָּךְ צָרִיךְ לְהוֹסִיף לְאוֹתוֹ רַע עַיִן, סוֹד שֶׁל הַצַּד הָאַחֵר, וְאוֹתָהּ תּוֹסֶפֶת הִיא חִסָּרוֹן לוֹ."]]],[["בִּסְטַר קְדוּשָּׁה גַּרְעִין לֵיהּ אַתְוָון, וְאִתּוֹסָף קְדוּשָׁתֵיהּ. וְדָא רָזָא דִּכְתִּיב, (מלכים א ז׳:כ״ה) עַל שְׁנֵי עָשָׂר בָּקָר. גָּרַע מֵ\"ם דְּלָא כְּתִיב שְׁנַיִם, אֶלָּא שְׁנֵי. וּלְסִטְרָא (קס\"ד ע\"ב) אַחֲרָא יַהֲבִין לֵיהּ תּוֹסֶפֶת אַתְוָון, דִּכְתִּיב וַיַּעַשׂ יְרִיעוֹת עִזִּים לְאֹהֶל עַל הַמִּשְׁכָּן עֲשְׁתֵּי עֶשְׂרֵה יְרִיעוֹת, תּוֹסֶפֶת אַתְוָון וְאִיהוּ גְּרִיעוּתָא. וּבְסִטְרָא דִּקְדוּשָּׁה, שְׁנִי עָשָׂר וְלָא יַתִּיר. וְהָכָא עֲשְׁתֵּי עֶשְׂרֵה. וְכֹלָּא אִיהוּ גְּרִיעוּ לְגַבֵּיהּ, וְהָכִי אִצְטְרִיךְ לְהַהוּא רַע עַיִן, לְאַשְׁלְמָא עֵינֵיהּ וְאִיהוּ בִּגְרִיעוּ. (כגוונא דא ארונה, תוספת אתוון ולא כתיב ארון)","תָּא חֲזֵי, סִטְרָא דִּקְדוּשָּׁה אִקְרֵי אֲרוֹן הַבְּרִית. וְהַהוּא אֲרוֹן הַבְּרִית, אִתְחָזֵי לְגוּפָא לְמֵיעַל בֵּיהּ דִּיּוּקְנָא דְּאָדָם. וְעַל רָזָא דָּא, אִינּוּן חֲסִידֵי קַדִּישִׁין, כַּד הָווֹ מִפְטְרֵי מֵהַאי עָלְמָא, הָווֹ אַעְלִין לוֹן בְּאָרוֹן. דְּהָא סִטְרָא אַחֲרָא לָא מִתְתָּקַּן בְּגוּפָא, וְלָאו אִיהִי בִּכְלָלָא דְּגוּפָא דְּאָדָם. וּבְגִין דָּא לָא אִתְבְּרוּן גּוּפַיָּיא לְהַהוּא סִטְרָא אַחֲרָא, בְּגִין דְּלָאו אִינּוּן (הקדמה ו' ע\"ב) בִּכְלָלָא דְּגוּפָא דְּאָדָם.","בְּיוֹסֵף מַה כְּתִיב, (בראשית נ׳:כ״ו) וַיִּישֶם בָּאָרוֹן תְּרֵין יוֹדִין אֲמַאי. אֶלָּא דְּאִתְחַבָּר בְּרִית בִּבְרִית. רָזָא דִּלְתַתָּא בְּרָזָא דִּלְעֵילָּא. וְעָאל בַּאֲרוֹנָא. מַאי טַעֲמָא. (ס\"א תא חזי סטרא דקדשה אקרי ארון הברית וההוא ארון הברית אתתקן לאעלא ביה רזא דאורייתא דאיהי רזא דדיוקנא דגופא קדישא. כגוונא דא לתתא אתתקן ארונא לאעלא ביה דיוקנא דגופא רזא דאדם ומאן איהו דקאים ברזא דאדם מאן דנטיר את קיימא קדישא ועל רזא דא אינון חסידי קדישין כד הוו מפטרי מהאי עלמא הוו עאלין לון בארונא בגין דלא אתחזי למיעל בארונא אלא מאן דנטיר להאי ברית את קיימא קדישא. ביוסף מה כתיב ויישם בארון) בְּגִין דְּנָטַר בְּרִית קַדִּישָׁא, וְאִתְקָיָּים בֵּיהּ. לְהָכִי אִתְחָזֵי לְאַעֲלָה בַּאֲרוֹנָא, וְכֹלָּא כַּדְקָא חֲזֵי.","בָּכָה רִבִּי אַבָּא וְאָמַר, וַוי לִבְנֵי עָלְמָא, דְּלָא יַדְעֵי לְהַהוּא כִּסּוּפָא. וַוי לְהַהוּא עוֹנְשָׁא, דְּכָל מַאן דְּבָעֵי עָאל בַּאֲרוֹנָא. בְּגִין דְּלָא אִצְטְרִיךְ לְמֵיעַל בַּאֲרוֹנָא, בַּר צַדִּיק, דְּיָדַע בְּנַפְשֵׁיהּ, וְאִשְׁתְּמוֹדַע בְּגַרְמֵיהּ, דְּלָא חָטָא בְּהַהוּא בְּרִית, אָת קַיָּימָא קַדִּישָׁא, מֵעוּלְמוֹי, וְקָא נָטִיר לֵיהּ כַּדְקָא יָאוּת. וְאִי לָאו, לָא אִצְטְרִיךְ לֵיהּ לְמֵיעַל בַּאֲרוֹנָא, וּלְמִפְגַם אֲרוֹנָא.","רָזָא אִצְטְרִיךְ לְאִתְחַבְּרָא בְּאָת קַיָּימָא קַדִּישָׁא דְּאִיהוּ רָזָא דְּאִתְחָזֵי לֵיהּ, וְלָא לְאַחֲרָא. דְּהָא אֲרוֹן לָא אִתְחֲבָּר אֶלָּא בְּצַדִּיק, דְּנָטִיר אָת קַיָּימָא קַדִּישָׁא. וּמַאן דְּפָגִים בְּרִית וְעָאל בַּאֲרוֹנָא, וַוי לֵיהּ, דְּפָגִם לֵיהּ בְּחַיּיוֹי. וַוי לֵיהּ דְּפָגִים לֵיהּ בְּמִיתָתֵיהּ. וַוי לֵיהּ מֵהַהוּא עוֹנְשָׁא. וַוי לֵיהּ דְּפָגִים אָת וְאָרוֹן קַיָּימָא קַדִּישָׁא. וַוי לֵיהּ לְהַהוּא כִּסּוּפָא, דְּנַקְמִין מִנֵּיהּ נִקְמַת עָלְמִין, נוּקְמָא דְּעָלְמָא דָּא, וְנוּקְמָא דְּהַהוּא פְּגִימוּ. וְרָזָא דָּא כְּתִיב (תהילים קכ״ה:ג׳) כִּי לא יָנוּחַ שֵׁבֶט הָרֶשַׁע עַל גּוֹרַל הַצַּדִיקִים.","בְּשַׁעֲתָא דְּדַיְינִין לֵיהּ בְּהַהוּא עָלְמָא, מִסְתַּכְּלָן בְּעוֹבָדוֹי, אִי הֲוָה פָּגִים רָזָא דִּבְרִית קַדִּישָׁא דְחָתִים בִּבְשָׂרֵיהּ. וְהַשְׁתָּא פָּגִים אֲרוֹנָא (דברית) דִּילֵיהּ בְּהַאי. הַאי לֵית לֵיהּ חוּלָקָא בְּצַדִּיקַיָּיא. מִסְתַּכְּלִן בֵּיהּ, וְדַיְינִין לֵיהּ, וּמַפְּקֵי לֵיהּ לְבַר מִכְּלָלָא דְּאָדָם. כֵּיוָן דְּאַפְקֵי לֵיהּ מִכְּלָלָא דְּאָדָם, אַפְקֵי לֵיהּ מִכְּלָלָא דְּכֻלְּהוּ אַחֲרָנִין, דְּאִתְעַתְּדוּ לְחַיֵּי עָלְמָא, וְיַהֲבֵי לֵיהּ לְהַהוּא (ארון) סִטְרָא דְּלָא אִתְכְּלִיל בְּרָזָא דְּגוּפָא דְּאָדָם. כֵּיוָן דְּאִתְּמְסַר לְהַהוּא סִטְרָא, וַוי לֵיהּ, דְּאַעֲלִין לֵיהּ בְּגֵיהִנָם, וְלָא נָפִיק מִנֵּיהּ לְעָלְמִין. עַל דָּא כְּתִיב (ישעיהו ס״ו:כ״ד) וְיָּצְאוּ וְרָאוּ בְּפִגְרֵי הָאֲנָשִׁים הַפּוֹשְׁעִים בִּי וְגוֹ'. אִינּוּן דְּאִשְׁתָּאָרוּ מִכְּלָלָא דְּאָדָם.","וְהָנֵי מִלֵי כַּד לָא עָבֵד תִּיוּבְתָּא שְׁלֵימָתָא. תִּיוּבְתָּא דְּאִיהִי אִתְחַזְיָיא לְחַפְיָיא עַל כָּל עוֹבָדוֹי. וְעִם כָּל דָּא טַב לֵיהּ דְּלָא יֵעוּל בַּאֲרוֹנָא, דְּהָא כָּל זִמְנָא דְּגוּפָא קַיָּים, נִשְׁמְתָא אִתְדְּנָת, וְלָא עָאלַת לְאַתְרָהּ. בַּר אִינּוּן חֲסִידֵי עֶלְיוֹנִין קַדִּישִׁין, דְּאִתְחָזוּן לְסַלְּקָא בְּגוּפֵיהוֹן, זַכָּאָה חוּלָקֵיהוֹן בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי.","בְּגִין דְּלֵית חוֹבָא דְּקַשְׁיָא קַמֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא, כְּהַאי מַאן דִּמְשַׁקֵּר וּפָגִים לְהַאי אָת קַיָּימָא קַדִּישָׁא. וְדָא לָא חָמֵי אַנְפֵּי שְׁכִינְתָּא, עַל חוֹבָא דָּא כְּתִיב (בראשית ל״ח:ז׳) וַיְהִי עֵר בְּכוֹר יְהוּדָה רַע בְּעֵינֵי יְיָ'. וּכְתִיב (תהילים ה׳:ה׳) לא יְגוּרְךָ רָע.","מַה כְּתִיב הָכָא, וַיַּעַשׂ בְּצַלְאֵל אֶת הָאָרוֹן. וְכִי אֲמַאי לָא עָבְדוּ אִינּוּן חַכִּימִין, דְּעָבְדוּ מַשְׁכְּנָא, יַת אֲרוֹנָא. אֶלָּא בְּצַלְאֵל, סִיּוּמָא דְּגוּפָא דְּאִיהוּ (רע\"ד ע\"א) רָזָא דִּבְרִית קַדִּישָׁא, וְנָטַר לֵיהּ, וְאִיהוּ קָאִים בְּעַדְבָא דְּחוּלָקֵיהּ. אִיהוּ אִשְׁתְּדַּל בְּעוֹבָדָא דִּילֵיהּ, וְלָא אַחֲרָא. אָתוּ כֻּלְּהוּ חַבְרַיָּיא, וְנַשְּׁקוּ לֵיהּ."],[[0,"בסטר קדושה גרעין וכו':","בצד הקדושה גורעים לו אותיות ונתוסף קדושתו, וז\"ס שכתוב על שני עשר בקר גרע \u0003ם',\u0004 שלא כתוב שנים אלא \u0003שני,\u0004 חסר \u0003ם',\u0004 ולסטרא אחרא נותנים לו תוספת אותיות, שכתוב, ויעש יריעת עזים לאהל על המשכן \u0003עשתי עשרה\u0004 יריעות, שהוא תוספת אותיות שנתאפה \u0003ע'\u0004 על \u0003שתי עשרה,\u0004 והיא גרעון, כי \u0003עשתי\u0004 הוא פחות \u0003א'\u0004 מ \u0003שתי עשרה.\u0004 ובצד הקדושה כתוב \u0003שני עשר\u0004 חסר \u0003ם',\u0004 ולא יותר, וכאן עשתי עשרה, שנתוספה \u0003ע',\u0004 והכל הוא חסרון אצלו, וכך צריך להיות לרע \u0003עין\u0004 ההוא, שהוא רוצה למלאות עינו, דהיינו \u0003ע'\u0004 שלו, והוא נגרע. בסוד כל המוסיף גורע."],[1,"ת\"ח סטרא דקדושה וכו':","בוא וראה, צד הקדושה, נקרא ארון הברית, הרומז על מלכות דקדושה, וארון הברית ההוא, שהוא מלכות, המחוברת בברית שהוא יסוד, ראוי אל הגוף, שהוא ז\"א, להכניס בו צורת אדם, דהיינו הוי\"ה במילוי אלפין שהוא בגימטריא אדם. ועל סוד הזה, אלו חסידים הקדושים, כשנפטרו מעולם הזה, היו מכניסים אותם בארון לרמז היחוד של ז\"א בארון הברית. כי הסטרא אחרא אינו מתתקן בגוף, והוא אינו בכלל גוף האדם, הרומז על ז\"א, ומשום זה לא נבראו גופים לס\"א (כנ\"ל בהקסה\"ז אות רמ\"ח) משום שאינם בכלל גוף אדם."],[2,"ביוסף מה כתיב וכו':","מה כתוב ביוסף, ויישם בארון. שואל, למה כתוב ויישם, עם שתי יודין. ומשיב, אלא שנתחבר ברית בברית, ש \u0003י'\u0004 רומזת על ברית, דהיינו יסוד, וכתוב ב' יודין כנגד ב' בריתות, סוד ברית שלמטה שהוא יוסף, בסוד ברית שלמעלה, שהוא ארון הברית, ונכנס בארון מהו הטעם שנכנס בארון. הוא משום ששמר ברית קדש, והוא נתקיים בו, ע\"כ היה ראוי לכנוס בארון. והכל כראוי."],[3,"בכה ר' אבא וכו':","בכה ר\"א ואמר, אוי לבני העולם, שאינם יודעים בזיון ההוא, אוי לעונש ההוא שנענשים, שכל מי שרוצה נכנס בארון, לאחר מיתתו, כי אינו צריך להכנס בארון חוץ מצדיק שיודע בנפשו ומכיר בעצמו שלא חטא בברית ההוא, אות ברית קדש מעודו, ושמר אותו כראוי. ואם לא, אינו צריך להכנס בארון, אחר מותו, ולפגום בזה את הארון. שהפגם מגיע עד ארון הברית."],[4,"רזא אצטריך לאתחברא וכו':","הסוד הוא, שהאדם צריך להתחבר באות ברית קדש, שהוא הסוד הראוי לו, הרומז ליסוד ז\"א, ולא לאחר, לס\"א, כי הארון, הרומז על מלכות, אינו מתחבר אלא בצדיק השומר אות ברית קדש. ומי שפוגם בברית ונכנס בארון, אוי לו, שפגם אותו בחייו, אוי לו, שפגם אותו במיתתו. אוי לו מעונש זה, אוי לו שפגם אות ברית, וארון הברית הקדוש. אוי לו לאותו בזיון, שנוקמים ממנו נקמת עולם, נקמת עולם הזה ונקמת פגם ההוא וזה סוד שכתוב, כי לא ינוח שבט הרשע על גורל הצדיקים."],[5,"בשעתא דדיינין ליה וכו':","בשעה שדנים אותו בעולם ההוא, מסתכלים במעשיו, אם היה פוגם סוד ברית קדש החתום בבשרו, ועתה פוגם הארון שלו, לזה, אין לו חלק בצדיקים, מסתכלים בו ודנים אותו, ומוציאים אותו מחוץ מכלל אדם, כיון שהוציאו אותו מכלל אדם, הוציאו אותו מכלל כל האחרים הנועדים לחיי עולם, ונותנים אותו לצד ההוא שלא נכלל בסוד אדם, דהיינו הסטרא אחרא כנ\"ל, כיון שנמסר לצד ההוא, אוי לו שמכניסים אותו בגיהנם, ואינו יוצא ממנו לעולם. על זה כתוב, ויצאו וראו בפגרי האנשים הפושעים בי וגו'. הם שנשארו, מכלל אדם. דהיינו שנשארו ולא נכללו בכלל אדם."],[6,"והני מילי כד וכו':","והדברים אמורים, רק כשלא עשה תשובה שלמה, תשובה שהיא ראויה לכסות על כל מעשיו. ועם כל זה, טוב לו שלא יכנס בארון, כי כל זמן שהגוף קיים נדונת הנשמה ואינה נכנסת למקומה חוץ מאלו חסידים העליונים הקדושים הראוים לעלות למעלה בגופם, אשרי חלקם בעולם הזה ובעולם הבא."],[7,"בגין דלית חובא וכו':","משום שאין עבירה שקשה לפני הקב\"ה, כמי שמשקר ופוגם אות ברית קודש. וזה אינו רואה פני השכינה, על עון זה כתוב, ויהי ער בכור יהודה רע בעיני ה'. וכתוב, לא יגורך רע. כי עון זה נקרא רע."],[8,"מה כתיב הכא וכו':","מה כתוב כאן, ויעש בצלאל את הארון. שואל, למה אלו חכמים שעשו את המשכן, לא עשו את הארון. ומשיב, אלא בצלאל היה במדרגת סיום הגוף, שהוא סוד ברית קודש (כנ\"ל תרומה אות תע\"ט), ושמר אותו, וע\"כ הוא עומד בנחלת חלקו, שהיא הארון שעשה. דהיינו המלכות. הוא השתדל במעשה שלו ולא אחר. באו כל החברים ונשקו לו לר' אבא."]],[[0,"","בְּצַד הַקְּדֻשָּׁה גּוֹרְעִים לוֹ אוֹתִיּוֹת, וְנוֹסֶפֶת קְדֻשָּׁתוֹ. וְזֶהוּ סוֹד הַכָּתוּב, (מלכים א ז) עַל שְׁנֵי עָשָׂר בָּקָר. גָּרַע מֵ\"ם, שֶׁלֹּא כָתוּב שְׁנֵים, אֶלָּא שְׁנֵי. וְלַצַּד הָאַחֵר נוֹתְנִים תּוֹסֶפֶת אוֹתִיּוֹת, שֶׁכָּתוּב וַיַּעַשׂ יְרִיעֹת עִזִּים לְאֹהֶל עַל הַמִּשְׁכָּן עַשְׁתֵּי עֶשְׂרֵה יְרִיעֹת. תּוֹסֶפֶת אוֹתִיּוֹת, וְהוּא חִסָּרוֹן. וּבְצַד הַקְּדֻשָּׁה שְׁנֵי עָשָׂר וְלֹא יוֹתֵר. וְכָאן עַשְׁתֵּי עֶשְׂרֵה, וְהַכֹּל הוּא חִסָּרוֹן אֵלָיו. וְכָךְ צָרִיךְ לְאוֹתוֹ רַע עַיִן לְהַשְׁלִים אֶת הָעַיִן שֶׁלּוֹ, וְהוּא בְּחִסָּרוֹן. (כדגמא זו ארונה, תוספת אותיות, ולא כתוב ארון)."],[1,"","בֹּא וּרְאֵה, צַד הַקְּדֻשָּׁה נִקְרָא אֲרוֹן הַבְּרִית, וְאוֹתוֹ אֲרוֹן הַבְּרִית רָאוּי לַגּוּף לְהַכְנִיס בּוֹ דְּיוֹקַן אָדָם. וְעַל סוֹד זֶה, אוֹתָם חֲסִידִים קְדוֹשִׁים, כְּשֶׁהָיוּ נִפְטָרִים מֵהָעוֹלָם הַזֶּה, הָיוּ מַכְנִיסִים אוֹתָם בְּאָרוֹן, שֶׁהֲרֵי הַצַּד הָאַחֵר אֵינוֹ מְתֻקָּן בְּגוּף וְאֵינוֹ בִּכְלָל שֶׁל גּוּף הָאָדָם. וְלָכֵן לֹא נִבְרְאוּ גוּפִים לְאוֹתוֹ צַד הָאַחֵר, מִשּׁוּם שֶׁאֵינָם בִּכְלָל שֶׁל גּוּף אָדָם."],[2,"","מַה כָּתוּב בְּיוֹסֵף? וַיִּישֶׂם בָּאָרוֹן. לָמָּה שְׁתֵּי יוֹדִי\"ם? אֶלָּא שֶׁהִתְחַבְּרָה בְּרִית בִּבְרִית, סוֹד שֶׁלְּמַטָּה בַּסּוֹד שֶׁלְּמַעְלָה, וְנִכְנַס בְּאָרוֹן. (בא וראה, צד הקדשה נקרא ארון הברית, ואותו ארון הברית נתקן להכניס בו סוד התורה, שהיא סוד של הצורה של הגוף הקדוש. כמו כן למטה נתקן ארון להכניס בתוכו צורת הגוף, סודהאדם. ומי הואשגמצאבסוד אדם, 'מי ששומר אות ברית הקדוש, ועל סוד זה אותם חסידים קדושים, כאשר היו נפטרים מעולם הזה, היו מכניסים אותם בארון, משום שלא ראוי להכנסבארוןאלאמיששמרלבריתזו, אותקיום הקדוש. ביוסף מה כתוב, ' ויישם בארון) מָה הַטַּעַם? מִשּׁוּם שֶׁשָּׁמַר הַבְּרִית הַקָּדוֹשׁ וְהִתְקַיֵּם בּוֹ. לָכֵן רָאוּי לְהִכָּנֵס בְּאָרוֹן, וְהַכֹּל כָּרָאוּי."],[3,"","בָּכָה רַבִּי אַבָּא וְאָמַר, אוֹי לִבְנֵי הָעוֹלָם שֶׁלֹּא יוֹדְעִים אוֹתָהּ בּוּשָׁה! אוֹי לְאוֹתוֹ עֹנֶשׁ שֶׁל כָּל מִי שֶׁרוֹצֶה לְהִכָּנֵס לְאָרוֹן, כִּי לֹא צָרִיךְ לְהַכְנִיס לְאָרוֹן, פְּרָט לְצַדִּיק שֶׁיּוֹדֵעַ בְּנַפְשׁוֹ וְנוֹדָע בְּעַצְמוֹ שֶׁלֹּא חָטָא בְּאוֹתָהּ בְּרִית, אוֹת הַבְּרִית הַקָּדוֹשׁ, מֵעֲלוּמָיו, וְשָׁמַר אוֹתוֹ כָּרָאוּי. וְאִם לֹא, לֹא צָרִיךְ לְהִכָּנֵס לְאָרוֹן וְלִפְגֹּם אֶת הָאָרוֹן."],[4,"","הַסּוֹד שֶׁצָּרִיךְ לְהִתְחַבֵּר בְּאוֹת בְּרִית קֹדֶשׁ הוּא הַסּוֹד הָרָאוּי לוֹ, וְלֹא לְאַחֵר. שֶׁהֲרֵי אָרוֹן אֵינוֹ מִתְחַבֵּר אֶלָּא בְּצַדִּיק שֶׁשּׁוֹמֵר בְּרִית קֹדֶשׁ. וּמִי שֶׁפּוֹגֵם אֶת הַבְּרִית וְנִכְנָס בְּאָרוֹן - אוֹי לוֹ שֶׁפָּגַם אוֹתוֹ בְּחַיָּיו, וְאוֹי לוֹ שֶׁפָּגַם אוֹתוֹ בְּמִיתָתוֹ. אוֹי לוֹ מֵאוֹתוֹ עֹנֶשׁ. אוֹי לוֹ שֶׁפָּגַם הָאוֹת וַאֲרוֹן הַבְּרִית הַקָּדוֹשׁ, אוֹי לוֹ מֵאוֹתָהּ בּוּשָׁה, שֶׁנּוֹקְמִים מִמֶּנּוּ נִקְמַת עוֹלָמִים - נְקָמָה שֶׁל הָעוֹלָם הַזֶּה, וּנְקָמָה שֶׁל אוֹתוֹ פְּגָם. וְסוֹד זֶה כָּתוּב, (תהלים קכה) כִּי לֹא יָנוּחַ שֵׁבֶט הָרֵשַׁע עַל גּוֹרַל הַצַּדִּיקִים."],[5,"","בְּשָׁעָֹה שֶׁדָּנִים אוֹתוֹ בְּאוֹתוֹ עוֹלָם, מִסְתַּכְּלִים בְּמַעֲשָׂיו. אִם הָיָה פּוֹגֵם אֶת סוֹד בְּרִית הַקֹּדֶשׁ שֶׁחָתוּם בִּבְשָׂרוֹ, וְעַכְשָׁו פּוֹגֵם אֶת הָאָרוֹן (הברית) שֶׁלּוֹ בָּזֶה - לָזֶה אֵין חֵלֶק בַּצַּדִּיקִים. מִסְתַּכְּלִים בּוֹ וְדָנִים אוֹתוֹ, וּמוֹצִיאִים אוֹתוֹ מִכְּלָל שֶׁל אָדָם. כֵּיוָן שֶׁהוֹצִיאוּ אוֹתוֹ מִכְּלָל שֶׁל אָדָם, מוֹצִיאִים אוֹתוֹ מִכְּלָל שֶׁל כָּל הָאֲחֵרִים שֶׁנּוֹעֲדוּ לְחַיֵּי עוֹלָם, וְנוֹתְנִים אוֹתוֹ לְאוֹתוֹ (ארון) צַד שֶׁאֵינוֹ נִכְלָל בַּסּוֹד שֶׁל גּוּף הָאָדָם. כֵּיוָן שֶׁנִּמְסָר לְאוֹתוֹ צַד - אוֹי לוֹ שֶׁמַּכְנִיסִים אוֹתוֹ לַגֵּיהִנֹּם, וְלֹא יוֹצֵא מִשָּׁם לְעוֹלָמִים. עַל זֶה כָּתוּב, (ישעיה סו) וְיָצְאוּ וְרָאוּ בְּפִגְרֵי הָאֲנָשִׁים הַפֹּשְׁעִים בִּי וְגוֹ'. אוֹתָם שֶׁנִּשְׁאֲרוּ מִכְּלָל שֶׁל אָדָם."],[6,"","וְהַדְּבָרִים הַלָּלוּ, כְּשֶׁלֹּא עָשָׂה תְשׁוּבָה שְׁלֵמָה, תְּשׁוּבָה שֶׁרְאוּיָה לְכַסּוֹת עַל כָּל מַעֲשָׂיו. וְעִם כָּל זֶה, טוֹב לוֹ שֶׁלֹּא יִכָּנֵס לְאָרוֹן, שֶׁהֲרֵי כָּל זְמַן שֶׁהַגּוּף עוֹמֵד, הַנְּשָׁמָה נִדּוֹנֵית וְלֹא נִכְנֶסֶת לִמְקוֹמָהּ, פְּרָט לְאוֹתָם חֲסִידִים עֶלְיוֹנִים קְדוֹשִׁים שֶׁרְאוּיִים לַעֲלוֹת עִם גּוּפָם. אַשְׁרֵי חֶלְקָם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא."],[7,"","מִשּׁוּם שֶׁאֵין חֵטְא קָשֶׁה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כְּמוֹ זֶה שֶׁמְּשַׁקֵּר וּפוֹגֵם אֶת אוֹת בְּרִית הַקֹּדֶשׁ, וְזֶה אֵינוֹ רוֹאֶה פְּנֵי שְׁכִינָה, וְעַל חֵטְא זֶה כָּתוּב, (בראשית לח) וַיְהִי עֵר בְּכוֹר יְהוּדָה רַע בְּעֵינֵי ה'. וְכָתוּב, (תהלים ה) לֹא יְגֻרְךְ רָע."],[8,"","מַה כָּתוּב כָּאן? וַיַּעַשׂ בְּצַלְאֵל אֶת הָאָרֹן. וְכִי לָמָּה לֹא עָשׂוּ אוֹתָם הַחֲכָמִים שֶׁעָשׂוּ אֶת הַמִּשְׁכָּן אֶת הָאָרוֹן? אֶלָּא בְּצַלְאֵל סִיּוּם הַגּוּף, שֶׁהוּא סוֹד הַבְּרִית הַקָּדוֹשׁ, וְשָׁמַר אוֹתוֹ, וְהוּא עוֹמֵד בְּנַחֲלַת חֶלְקוֹ. הוּא הִשְׁתַּדֵּל בַּמַּעֲשֶׂה שֶׁלּוֹ וְלֹא אַחֵר. בָּאוּ כָּל הַחֲבֵרִים וְנָשְׁקוּ אוֹתוֹ."]]],[["כַּד מָטוּ לְגַבֵּי דְּרִבִּי שִׁמְעוֹן, וְסַדְּרוּ מִלִּין אִלֵּין קַמֵּיהּ, כָּל מַה דְּאִתְּמַר בְּהַהוּא אוֹרְחָא. פָּתַח וְאָמַר, (משלי ד׳:י״ח) וְאוֹרַח צַדִּיקִים כְּאוֹר נֹגַהּ הוֹלֵךְ וְאוֹר עַד נְכוֹן הַיּוֹם. הַאי קְרָא אִתְּמַר. אֲבָל הַאי קְרָא אִית לְאִסְתַּכְּלָא בֵּיהּ, וְאוֹרַח צַדִּיקִים, הַהוּא אוֹרְחָא דְּצַדִּיקַיָּיא אָזְלוּ בֵּיהּ, אִיהוּ אֹרַח קְשׁוֹט. אוֹרְחָא דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרְעֵי בֵּיהּ. אוֹרְחָא דְּאִיהוּ אָזִיל קָמַיְיהוּ, וְכָל אִינּוּן רְתִיכִין, אַתְיָין לְמִשְׁמַע מִלִּין דְּאִינּוּן מְמַלְּלָן וְאָמְרֵי בְּפוּמַיְיהוּ. כְּאוֹר נֹגַהּ: דְּנָהִיר וְאָזִיל, וְלָא אִתְחֲשָׁךְ (ס\"א כלל), כְּאוֹרַח דְּאִינּוּן חַיָּיבַיָּא, דְּאוֹרַח דִּילְהוֹן אִתְחֲשָׁךְ תָּדִיר, כְּמָה דְאַתְּ אָמֵר (משלי ד׳:י״ט) דֶּרֶךְ רְשָׁעִים כָּאֲפֵלָה וְגוֹ'.","דָּבָר אַחֵר וְאוֹרַח צַדִּיקִים. מַה בֵּין אוֹרַח לְדֶרֶךְ, הָא אוּקְמוּהָ. אֲבָל (קל\"ז ע\"א ויקרא פ\"ח ע\"א) אוֹרַח הוּא, דְּהַשְׁתָּא אִתְפְּתַח וְאִתְגַּלְיָיא, וְאִתְעָבִיד בְּהַהוּא אֲתָר אוֹרַח, דְּלָא כְּתִישׁוּ בֵּיהּ רַגְלִין מִקַּדְמַת דְּנָא. דֶּרֶךְ: כְּמָה דְאַתְּ אָמֵר (ישעיה סג) כְּדוֹרֵךְ בְּגַת, דְּכַתְשִׁין בֵּיהּ רַגְלִין כָּל מַאן דְּבָעֵי.","וְעַל דָּא לְצַדִּיקַיָּיא קָארֵי אֹרַח, דְּאִינּוּן הֲווֹ קַדְמָאֵי לְמִפְתַּח הַהוּא אֲתָר. וְלָא עַל אֲתָר אִיהוּ אֶלָּא אַף עַל גַּב דְּאַחֲרָנִין בְּנֵי עָלְמָא אָזְלֵי בְּהַהוּא אֲתָר, הַשְׁתָּא דְּאַזְלִין בֵּיהּ צַדִּיקַיָּיא, אִיהוּ אֲתָר חַדְתָּא, דְּהַשְׁתָּא חַדְתָּא אִיהוּ הַהוּא אֲתָר כְּמָה דְּלָא אָזִיל בֵּיהּ בַּר נָשׁ אַחֲרָא לְעָלְמִין. בְּגִין דְּצַדִּיקַיָּיא עַבְדִּין חַדְתָּא לְכָל הַהוּא אֲתָר, בְּכַמָּה מִלִּין עִלָּאִין דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרְעֵי בְּהוֹן.","וְתוּ, דִּשְׁכִינְתָּא אַזְלָא בְּהַהוּא אֲתָר, מַה דְּלָא הֲוַות מִקַּדְמַת דְּנָא. וּבְּגִין כָּךְ אֹרַח צַדִּיקִים אִקְרֵי, בְּגִין דְּאִתְאָרַח בֵּיהּ אוּשְׁפִּיזָא עִלָּאָה קַדִּישָׁא. דֶּרֶךְ: אִיהוּ פָּתוּחַ לְכֹלָּא, וְכַתְשִׁין בֵּיהּ כָּל מַאן דְּבָעֵי, אֲפִילּוּ אִינּוּן חַיָּיבִין. דֶּרְךְ, רָזָא דָּא, (ישעיהו מ״ג:ט״ז) הַנּוֹתֵן בַּיָּם דָּרֶךְ, בְּגִין דְּדָרִיךְ בֵּיהּ סִטְרָא אַחֲרָא, דְּלָא אִצְטְרִיךְ, וְשָׁלִיט לְסַאֲבָא מַשְׁכְּנָא. וְעַל דָּא, צַדִּיקַיָּיא בִּלְחוֹדַיְיהוּ, קַיְימֵי וְשַׁלְטֵי בְּהַהוּא אֲתָר דְּאִקְרֵי אוֹרַח. כְּמָה דְּאוֹקִימְנָא דֶּרֶךְ פָּתוּחַ לְכֹלָּא, לְהַאי סִטְרָא וּלְהַאי סִטְרָא.","וְאַתּוּן קַדִּישֵׁי עֶלְיוֹנִין, אוֹרַח קַדִּישָׁא עִלָּאָה אִזְדָּמַן לְגַבַּיְיכוּ, וְאָרַחְתּוּן בֵּיהּ וּמִלִּין מְעַלְּיָין עִלָּאִין (נ\"א אלין) אִתְסָדָּרוּ קָמֵי עַתִּיק יוֹמִין. זַכָּאָה חוּלָקֵיכוֹן.","פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (דברים לה) וִיהוֹשֻׁעַ בִּן נוּן מָלֵא רוּחַ חָכְמָה כִּי סָמַךְ מֹשֶׁה וְגוֹ', בְּכַמָּה אֲתָר תָּנֵינָן, דְּמֹשֶׁה אַנְפּוֹי כְּאַנְפֵּי שִׁמְשָׁא, וִיהוֹשֻׁעַ כְּאַנְפֵּי סִיהֲרָא. דְּלֵית נְהוֹרָא לְסִיהֲרָא, אֶלָּא נְהוֹרָא דְּשִׁמְשָׁא כַּד נָהַר לְסִיהֲרָא, וְסִיהֲרָא מִגּוֹ שִׁמְשָׁא אִתְמַלְּיָיא. וְכַד אִתְמַלְּיָיא, כְּדֵין קַיְּימָא בְּאַשְׁלְמוּתָא.","אִשְׁתְּלִימוּתָא דְּסִיהֲרָא, מַאן אִיהוּ. רָזָא דְּכֹלָּא, דְּאִקְרֵי דְּמוּת בְּרָזָא דִּשְׁמָא עִלָּאָה יְיָ'. דְּהָא בִּשְׁמָא דָּא לָא קָאִים, בַּר בְּזִמְנָא דְּקַיְּימָא בְּאַשְׁלְמוּתָא. דְּהָא כַּמָה שְׁמָהָן אִינּוּן דְּאַחֲסִינָא, וְאִתְקְרֵי בְּהוּ כַּךְ כְּפוּם שַׁעֲתָא דְּקַיְּימָא בֵּיהּ, (וכפום שעתא דקיימא ביה) הָכִי אִקְרֵי בְּהַהוּא שְׁמָא מַמָּשׁ. וְכַד קַיְּימָא בְּרָזָא דְּאַשְׁלָמוּתָא וְאִשְׁתְּלִימַת מִכָּל סִטְרִין, כְּדֵין אִקְרֵי יְדוָֹ\"ד אַשְׁלְמוּתָא דִּילָהּ, כְּאַשְׁלָמוּתָא דִּלְעֵילָּא. (ק ע\"ב) דְּיָרְתָא בְּרָתָא לְאִמָּהּ.","וְהַיְינוּ (ד\"א נהירו) בַּחֲמֵיסָר יוֹמִין, דִּכְתִּיב, (ויקרא כ״ג:ל״ד) בַּחֲמִשָּׁה עָשָׂר יוֹם לַחֹדֶשׁ הַשְּׁבִיעִי הַזֶּה. וּכְתִיב (ויקרא כ״ג:כ״ז) אַךְ בֶּעָשׂוֹר (יום) לַחֹדֶשׁ הַשְּׁבִיעִי. וְכֹלָּא רָזָא חֲדָא, כַּד קַיְּימָא עָלְמָא דְּאָתֵי בְּרָזָא דְּכָל עֶשֶׂר אֲמִירָן, עַל הַאי חֹדֶשׁ, אִקְרֵי (קפ\"ה ע\"ב) בֶּעָשׂוֹר. וְכַד אִתְרְשִׁימַת סִיהֲרָא בְּאַשְׁלְמוּתָא חֲדָא בֵּינַיְיהוּ, אִקְרֵי בַּחֲמִשָּׁה עָשָׂר, דְּהָא ה' אִתְחַבְּרַת וְאִתְחַקְקַת בֵּינַיְיהוּ.","וְרָזָא דָּא י\"ה וְכַד קַיְּימָא בִּשְׁמָא דָּא, כְּדֵין אִתְחַבָּר בְּה', וְאִיהִי אִתוֹסְפָא (ד\"א לגביה תתאי למיזן לון ולמיהב לון טרפייהו ואתוספא) אִיהִי, בְּרָזָא דְּאָת ה' כְּמִלְּקַדְמִין. חֲדָא, לְאִתְחַקְּקָא וּלְאִתְחַבְּרָא בְּרָזָא דִּלְעֵילָּא. וַחֲדָא לְמֵיהַב מְזוֹנָא לְתַתָּא. וּכְדֵין קַיְּימָא סִיהֲרָא בְּאַשְׁלְמוּתָא לְכָל סִטְרִין, עֵילָּא וְתַתָּא, בְּרָזָא דִּשְׁמָא דָּא, לְמֶהֱוֵי כֹּלָּא רָזָא חֲדָא, וּשְׁלִימוּ חַד.","יְהוֹשֻׁעַ דָּא אִיהוּ רָזָא דְּאַשְׁלָמוּתָא דְּסִיהֲרָא, בְּאִלֵּין אַתְוָון בִּן נוּ\"ן, נוּ\"ן וַדַּאי דְּהָא נוּן רָזָא דְּסִיהֲרָא אִיהִי. מָלֵא בְּרָזָא דְּאַשְׁלָמוּתָא דִּשְׁמָא קַדִּישָׁא, כְּדֵין אִיהוּ מָלֵא רוּחַ חָכְמָה וַדַּאי.","בְּגִין דִּנְקוּדָה עִלָּאָה דְּאִיהִי י', אִתְפָּשַׁט וְאַפִּיק רוּחַ, וְהַהוּא רוּחַ עָבִיד הֵיכָלָא. וְהַהוּא רוּחַ אִתְפָּשַׁט, וְאִתְעָבִיד שִׁית סִטְרִין. הַהוּא רוּחַ אִתְפָּשַׁט, בְּרָזָא דְּכָל אִלֵּין. וְאַמְלֵי וְעָבִיד הֵיכָלָא לְתַתָּא, וְאִתְמְלֵּי כֹּלָּא, וְאִתְעָבִיד רָזָא דִּשְׁמָא קַדִּישָׁא, בְּאַשְׁלְמוּתָא חֲדָא."],[[0,"כד מטו לגבי וכו':","כשהגיעו לר' שמעון וסדרו דברים אלו לפניו כל מה שנאמר בדרך ההוא, פתח ואמר, וארח צדיקים כאור נגה הולך ואור עד נכון היום. מקרא זה נתבאר. אבל במקרא הזה יש להסתכל בו. \u0003וארח צדיקים,\u0004 היינו, הארח שצדיקים הולכים בו הוא דרך אמת, דרך, שהקב\"ה רוצה בו. דרך, שהקב\"ה הולך לפניהם וכל המרכבות באות לשמוע הדברים שהם מדברים ואומרים בפיהם. \u0003כאור נגה,\u0004 שמאיר והולך, ואינו נחשך כדרך הרשעים, שהדרך שלהם נחשך תמיד. כש\"א דרך רשעים כאפלה וגו'."],[1,"ד\"א וארה צדיקים וכו':","פירוש אחר על, וארח צדיקים מה ההפרש בין ארח לדרך, הרי העמידוהו. אבל \u0003ארח\u0004 הוא, שעתה נפתח ונגלה ונעשה במקום ההיא ארח, שלא דרכו בו רגלים מקודם לכן. \u0003דרך,\u0004 הוא כמו שאתה אומר, כדורך בגת. שדרכו עליו רגלי כל מי שרוצה."],[2,"וע\"ד לצדיקיא קארי וכו':","וע\"כ לצדיקים, קורא לדרך ארח, שהם היו ראשונים לפתוח מקום ההוא. ולא על המקום נאמר שפתחו אותו, אלא אע\"פ שאחרים בני העולם הולכים באותו מקום, עתה שהלכו בו צדיקים, הוא מקום חדש, כמו שנפתח עתה, שמקום ההוא הוא חדש עתה, כמו שלא הלך בו אדם אחר לעולם. משום שהצדיקים מחדשים את כל מקום ההוא בכמה דברים חדשים עליונים, שהקב\"ה רוצה בהם."],[3,"ותו דשכינתא אזלא וכו':","ועוד, שהשכינה הולכת במקום ההוא, מה שלא היה מקודם לכן, וע\"כ נקרא ארח צדיקים, משום שנתארח בו אורח עליון קדוש, דהיינו השכינה. דרך הוא פתוח לכל, ודורכים עליו כל מי שרוצה, ואפילו הרשעים. דרך, הוא סוד, הנותן בים דרך שהדרך בו אינו בטוח, משום שדורך בו הסטרא אחרא שאינו צריך, ושולט לטמאות המשכן. וע\"כ הצדיקים בלבד עומדים ושולטים באותו מקום שנקרא ארח. כמו שהעמדתי. כי דרך פתוח לכל לצד זה ולצד זה, לקדושה ולטומאה."],[4,"ואתון קדישי עליונין וכו':","ואתם קדושים עליונים, ארח קדוש עליון נזדמן לכם ונתארחתם בו, ודברים משובחים עליונים נסדרו לפני עתיק יומין. אשרי חלקכם."],[5,"פתח ר\"ש ואמר וכו':","פר\"ש ואמר, ויהושע בן נון מלא רוח חכמה כי סמך משה וגו'. בכמה מקומות למדנו, שמשה, פניו כפני השמש. שהוא ז\"א. ויהושע כפני הלבנה, שהיא המלכות, שאין אור ללבנה אלא מאור השמש, מז\"א, כשמאיר ללבנה שהוא המלכות, והלבנה מתמלאה מן השמש. וכשהיא נתמלאה, אז עומדת בשלמות."],[6,"אשתלמותא דסיהרא מאן וכו':","שואל, מהו התמלאות הלבנה. ומשיב, הוא סוד הכל, שהדמות, שה\"ס המלכות, נקראת בסוד שם העליון, \u0003הוי\"ה,\u0004 שאינה עומדת בשם זה, הויה, אלא בזמן שנמצאת במילואה. שהרי כמה שמות הם שהיא יורשת, ונקראת בהם, כך כפי השעה שעומדת בה כן היא נקראת בשם ההוא ממש. וכשהיא עומדת בסוד המילוא, ונשלמת מכל הצדדים, אז נקראת \u0003הוי\"ה.\u0004 כי ההשלמה שלה היא כהשלמה של מעלה, שהוא ז\"א, שנקרא הוי\"ה, וע\"כ נקראת גם המלכות בשם הוי\"ה. כי הבת ירשה לאמה. דהיינו שקבלה כל המוחין מאמא, שהוא בינה. על ידי ז\"א."],[7,"והיינו בחמיסר יומין וכו':","והיינו שהמלכות נקראת בשם הויה, היא בחמשה עשר יום, שכתוב, בחמשה עשר יום לחדש השביעי הזה. וכתוב, אך בעשור לחדש השביעי. והכל הוא סוד אחד, כשעומד עולם הבא, שהוא בינה, בסוד כל עשר מאמרות, שהם עשר ספירות שלה, על חדש הזה, שהיא המלכות, היא נקראת \u0003בעשור.\u0004 וכאשר נרשמה הלבנה ביניהם של ע\"ס דבינה, בהשלמה אחת, המלכות נקראת \u0003בחמשה עשר,\u0004 כי ה' שהיא מלכות, נתחברה ונחקקה בין ע\"ס דבינה."],[8,"ורזא דא י\"ה ו\"ה וכו':","וזה סוד שהמלכות נקראת י\"ה ו\"ה, (כנ\"ל אות שצ\"ז) וכאשר עומדת בשם הזה, הויה, אז היא מתחברת ב \u0003ה'\u0004 אחרונה של \u0003הוי\"ה\u0004 זו, והיא נוספת להיות בסוד אות \u0003ה'\u0004 של הויה כמתחילה, ונמצא שהיא בסוד כל שם הויה, והיא בסוד \u0003ה'\u0004 אחרונה דהויה, א', היא להתחקק ולהתחבר בסוד של מעלה, ומבחינה זו לוקחת המלכות כל השם הויה. וא', לתת מזונות למטה, ומבחינה זו היא מתחברת ב \u0003ה'\u0004 אחרונה של הויה. ואז עומדת הלבנה בהשלמה לכל הצדדים למעלה ולמטה בסוד שם הזה, הויה, שיהיה הכל סוד אחד ושלמות אחת."],[9,"יהושע דא איהו וכו':","יהושע זה הוא סוד ההשלמה של הלבנה באלו האותיות בן \u0003נון\u0004, נון ודאי, דהיינו בסוד נ' שערים כמו בינה, כי נון הוא סוד הלבנה כשהיא מלאה בסוד ההשלמה של שם הקדוש הויה, אז הוא מלא רוח חכמה ודאי, דהיינו סוד ו\"ק דחכמה הנקראים רוח."],[10,"בגין דנקודה עלאה וכו':","משום שנקודה עליונה, שהיא \u0003י'\u0004 דהויה, דהיינו חכמה, נתפשטה והוציאה רוח, דהיינו ו\"ק דחכמה, ורוח ההוא עשה היכל, שהוא בינה. ורוח ההוא נתפשט מן ההיכל ונעשה ששה קצוות, דהיינו ז\"א, ורוח ההוא נתפשט בסוד כל אלו דהיינו בבחינת ו\"ק דחכמה, ובינה, ומילא ועשה היכל למטה, דהיינו המלכות במילואה, ונתמלא הכל ונעשה בהמלכות סוד שם הקדוש הויה, בהשלמה אחת."]],[[0,"","כְּשֶׁהִגִּיעוּ לְרַבִּי שִׁמְעוֹן וְסִדְּרוּ הַדְּבָרִים הַלָּלוּ לְפָנָיו, כָּל מַה שֶּׁנֶּאֱמַר בְּאוֹתָהּ דֶּרֶךְ, פָּתַח וְאָמַר, (משלי ד) וְאֹרַח צַדִּיקִים כְּאוֹר נֹגַהּ הוֹלֵךְ וָאוֹר עַד נְכוֹן הַיּוֹם. הַפָּסוּק הַזֶּה נִתְבָּאֵר. אֲבָל בַּפָּסוּק הַזֶּה יֵשׁ לְהִתְבּוֹנֵן, וְאֹרַח צַדִּיקִים, אוֹתָהּ דֶּרֶךְ שֶׁהַצַּדִּיקִים הָלְכוּ בָהּ, הִיא דֶּרֶךְ אֲמִתִּית, דֶּרֶךְ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה בָּהּ, הַדֶּרֶךְ שֶׁהוּא הוֹלֵךְ לִפְנֵיהֶם, וְכָל אוֹתָן מֶרְכָּבוֹת בָּאוֹת לִשְׁמֹעַ דְּבָרִים שֶׁהֵם מְדַבְּרִים וְאוֹמְרִים בְּפִיהֶם. כְּאוֹר נֹגַהּ, שֶׁמֵּאִיר וְהוֹלֵךְ, וְלֹא נֶחְשָׁךְ (כלל), כְּדֶרֶךְ אוֹתָם הָרְשָׁעִים שֶׁדַּרְכָּם תָּמִיד חֲשׁוּכָה, כְּמוֹ שֶׁנֶּאֱמַר, דֶּרֶךְ רְשָׁעִים כָּאֲפֵלָה וְגוֹ'."],[1,"","דָּבָר אַחֵר וְאֹרַח צַדִּיקִים - מַה בֵּין אֹרַח לְדֶרֶךְ? הֲרֵי פֵּרְשׁוּהָ. אֲבָל דֶּרֶךְ הִיא שֶׁעַכְשָׁו נִפְתְּחָה וְנִגְלְתָה, וְנַעֲשֶׂה בְּאוֹתוֹ מָקוֹם דֶּרֶךְ שֶׁלֹּא כָתְשׁוּ בָהּ רַגְלַיִם מִקֹּדֶם לָכֵן. דֶּרֶךְ - כְּמוֹ שֶׁנֶּאֱמַר, (ישעיה סג) כְּדֹרֵךְ בְּגַת, שֶׁכּוֹתְשִׁים בּוֹ רַגְלַיִם כָּל מִי שֶׁרוֹצֶה."],[2,"","וְעַל זֶה לַצַּדִּיקִים קוֹרֵא אֹרַח, שֶׁהֵם הָיוּ רִאשׁוֹנִים לִפְתֹּחַ אוֹתוֹ מָקוֹם, וְלֹא כָּל הַמָּקוֹם הַהוּא. אֶלָּא אַף עַל גַּב שֶׁאֲחֵרִים בְּנֵי הָעוֹלָם הוֹלְכִים בְּאוֹתוֹ מָקוֹם - עַכְשָׁו שֶׁהוֹלְכִים בָּהּ צַדִּיקִים, הוּא מָקוֹם חָדָשׁ, שֶׁעַכְשָׁו אוֹתוֹ מָקוֹם הוּא חָדָשׁ כְּמוֹ מִי שֶׁלֹּא הָלַךְ בּוֹ אָדָם אַחֵר לְעוֹלָמִים, מִשּׁוּם שֶׁצַּדִּיקִים עוֹשִׂים חִדּוּשׁ לְכָל אוֹתוֹ מָקוֹם בְּכַמָּה דְבָרִים עֶלְיוֹנִים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְרַצֶּה בָהֶם."],[3,"","וְעוֹד, שֶׁשְּׁכִינָה הוֹלֶכֶת בְּאוֹתוֹ מָקוֹם מַה שֶּׁלֹּא הָיָה מִקֹּדֶם לָכֵן. וּמִשּׁוּם כָּךְ נִקְרָא אֹרַח צַדִּיקִים, מִשּׁוּם שֶׁהִתְאָרַח בּוֹ אוֹרֵחַ עֶלְיוֹן קָדוֹשׁ. דֶּרֶךְ הִיא פְּתוּחָה לַכֹּל, וְכוֹתְשִׁים בָּהּ כָּל מִי שֶׁרוֹצֶה, אֲפִלּוּ אוֹתָם הָרְשָׁעִים. דֶּרֶךְ, סוֹד זֶה - (שם מג) הַנֹּתֵן בַּיָּם דָּרֶךְ. מִשּׁוּם שֶׁדּוֹרֵךְ בּוֹ הַצַּד הָאַחֵר שֶׁלֹּא צָרִיךְ, וְשׁוֹלֵט לְטַמֵּא אֶת הַמִּשְׁכָּן. וְעַל זֶה צַדִּיקִים לְבַדָּם עוֹמְדִים וְשׁוֹלְטִים בְּאוֹתוֹ מָקוֹם שֶׁנִּקְרָא אֹרַח. כְּמוֹ שֶׁבֵּאַרְנוּ, דֶּרֶךְ פְּתוּחָה לַכֹּל, לְצַד זֶה וּלְצַד זֶה."],[4,"","וְאַתֶּם, קְדוֹשִׁים עֶלְיוֹנִים, דֶּרֶךְ קְדוֹשָׁה עֶלְיוֹנָה הִזְדַּמְּנָה לָכֶם וְהִתְאָרַחְתֶּם בָּהּ, וּדְבָרִים מְעֻלִּים עֶלְיוֹנִים (אלו) הִסְתַּדְּרוּ לִפְנֵי עַתִּיק הַיָּמִים. אַשְׁרֵי חֶלְקְכֶם."],[5,"","פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (דברים לד) וִיהוֹשֻׁעַ בִּן נוּן מָלֵא רוּחַ חָכְמָה כִּי סָמַךְ מֹשֶׁה וְגוֹ'. בְּכַמָּה מְקוֹמוֹת מָצָאנוּ שֶׁפְּנֵי מֹשֶׁה כִּפְנֵי הַשֶּׁמֶשׁ, וִיהוֹשֻׁעַ כִּפְנֵי הַלְּבָנָה. שֶׁאֵין אוֹר לַלְּבָנָה אֶלָּא אוֹר הַשֶּׁמֶשׁ כְּשֶׁמֵּאִיר לַלְּבָנָה, וְהַלְּבָנָה מִתְמַלֵּאת מִתּוֹךְ הַשֶּׁמֶשׁ. וּכְשֶׁמִּתְמַלֵּאת, אָז עוֹמֶדֶת בִּשְׁלֵמוּתָהּ."],[6,"","הִשְׁתַּלְּמוּת הַלְּבָנָה מִי הוּא? סוֹד שֶׁל הַכֹּל שֶׁנִּקְרָא דְמוּת בְּסוֹד הַשֶּׁמֶשׁ הָעֶלְיוֹן יְיָ. שֶׁהֲרֵי בַּשֵּׁם הַזֶּה אֵינוֹ עוֹמֵד, רַק בִּזְמַן שֶׁעוֹמֶדֶת בִּשְׁלֵמוּת. שֶׁהֲרֵי כַּמָּה שֵׁמוֹת הֵם שֶׁיָּרְשָׁה, וְנִקְרֵאת בָּהֶם כְּפִי הַשָּׁעָה שֶׁעוֹמֶדֶת בָּהּ, (וכפי השעה עומדת בה) כָּךְ נִקְרֵאת בְּאוֹתוֹ שֵׁם מַמָּשׁ. וּכְשֶׁעוֹמֶדֶת בְּסוֹד הַשְּׁלֵמוּת וְנִשְׁלֶמֶת מִכָּל הַצְּדָדִים, אָז נִקְרָא יְדוָ\"ד. הַשְׁלָמָתָהּ כַּהַשְׁלָמָה שֶׁלְּמַעְלָה, שֶׁיָּרְשָׁה הַבַּת אֶת אִמָּהּ."],[7,"","וְהַיְנוּ (הארה) בַּחֲמִשָּׁה עָשָׂר יָמִים, שֶׁכָּתוּב (ויקראכג) בַּחֲמִשָּׁה עָשָׂר יוֹם לַחֹדֶשׁ הַשְּׁבִיעִי הַזֶּה. וְכָתוּב (שם) אַךְ בֶּעָשׂוֹר (יום) לַחֹדֶשׁ הַשְּׁבִיעִי. וְהַכֹּל סוֹד אֶחָד. כְּשֶׁעוֹמֵד הָעוֹלָם הַבָּא בַּסּוֹד שֶׁל כָּל עֶשֶׂר הָאֲמִירוֹת עַל הַחֹדֶשׁ הַזֶּה, נִקְרָא בֶּעָשׂוֹר. וּכְשֶׁנִּרְשֶׁמֶת הַלְּבָנָה בִּשְׁלֵמוּת אַחַת בֵּינֵיהֶן, נִקְרָא בַּחֲמִשָּׁה עָשָׂר, שֶׁהֲרֵי ה' הִתְחַבְּרָה וְנֶחְקְקָה בֵינֵיהֶם."],[8,"","וְסוֹד זֶה י\"ה, וּכְשֶׁעוֹמֶדֶת בְּשֵׁם זֶה, אָז מִתְחַבֶּרֶת בְּה', וְהִיא נוֹסֶפֶת (אל התחתונים לזון אותם ולתת להם טרפם, ומתוספת) הִיא בְּסוֹד הָאוֹת ה' כְּמִקֹּדֶם. אֶחָד, לְהֵחָקֵק וּלְהִתְחַבֵּר בַּסּוֹד שֶׁלְּמַעְלָה, וְאֶחָד, כְּדֵי לָתֵת מָזוֹן לְמַטָּה, וְאָז עוֹמֶדֶת הַלְּבָנָה בִּשְׁלֵמוּת לְכָל הַצְּדָדִים, מַעְלָה וָמַטָּה, בְּסוֹד הַשֵּׁם הַזֶּה, לִהְיוֹת הַכֹּל סוֹד אֶחָד וּשְׁלֵמוּת אַחַת."],[9,"","יְהוֹשֻׁעַ זֶהוּ סוֹד שֶׁל הַשְׁלָמַת הַלְּבָנָה בָּאוֹתִיּוֹת הַלָּלוּ בִּן נוּ\"ן. נוּ\"ן וַדַּאי, שֶׁהֲרֵי נוּן הִיא סוֹד הַלְּבָנָה, מָלֵא בְּסוֹד הַהַשְׁלָמָה שֶׁל הַשֵּׁם הַקָּדוֹשׁ, וְאָז הוּא מָלֵא רוּחַ חָכְמָה וַדַּאי."],[10,"","מִשּׁוּם שֶׁהַנְּקֻדָּה הָעֶלְיוֹנָה, שֶׁהִיא י', מִתְפַּשֶּׁטֶת וּמוֹצִיאָה רוּחַ, וְאוֹתָהּ רוּחַ עוֹשָׂה הֵיכָל. וְאוֹתָהּ רוּחַ מִתְפַּשֶּׁטֶת וְנַעֲשֵׂית לְשִׁשָּׁה צְדָדִים. אוֹתָהּ רוּחַ מִתְפַּשֶּׁטֶת בַּסּוֹד שֶׁל כָּל אֵלֶּה. וּמְמַלֵּא וְעוֹשֶׂה הֵיכָל לְמַטָּה, וְהַכֹּל מִתְמַלֵּא, וְנַעֲשֶׂה סוֹד הַשֵּׁם הַקָּדוֹשׁ בְּהַשְׁלָמָה אַחַת."]]],[["וּבְגִין דָּא יְהוֹשֻׁעַ מָלֵא רוּחַ חָכְמָה, בְּגִין כִּי סָמַךְ מֹשֶׁה אֶת יָדָיו עָלָיו, דְּאִיהוּ אָרִיק בִּרְכָאן עָלֵיהּ, וְאִתְמְלֵי בֵּירָא מִנֵּיהּ. וְאַתּוּן קַדִּישֵׁי עֶלְיוֹנִין, כָּל חַד מִנַּיְיכוּ אִתְמְלֵי רוּחַ חָכְמָה, וְקַיְּימָא בְּאַשְׁלְמוּתָא, בְּרָזִין דְּחָכְמְתָא. בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא הוּא אִתְרְעֵי בְּכוּ, וְאַסְמִיךְ יְדוֹי עָלַיְיכוּ. זַכָּאָה חוּלָקִי דְּעֵינַי חָמוּ דָּא, וְחָמוּ שְׁלִימוּ דְּרוּחַ חָכְמְתָא בְּכוּ.","פָּתַח וְאָמַר, כְּתִיב (ויקרא י״ט:כ״ו) לא תֹאכְלוּ עַל הַדָּם לֹא תְנַחֲשׁוּ וְלֹא תְעוֹנֵנוּ. הַאי קְרָא אוּקְמוּהָ, וְרָזָא דְּמִלָּה, הַאי מַאן דְּאָכִיל בְּלָא צְלוֹתָא, דִּיצָלֵי (ד\"א קדם דאכיל) עַל דָּמֵיהּ, שָׁקִיל אִיהוּ כִּמְנַחֵשׁ וּמְעוֹנֵן.","בְּגִין דִּבְלֵילְיָא נִשְׁמְתָא סַלְקַת וְאִשְׁתַּטְחָת לְמֵחמֵי בְּרָזָא דִּיְקָרָא עִלָּאָה, כָּל חַד וְחַד כְּמָה דְּאִתְחָזֵי לֵיהּ. וְאִשְׁתְּאַר בַּר נָשׁ בְּהַהוּא חֵילָא דְאִשְׁתַתָף (נ\"א דאתפשט) גּוֹ דָּמָא, לְאִתְקַיְּימָא גּוּפָא. וְעַל דָּא (ס\"א ועם כל דא) טָעִים טַעֲמָא דְּמוֹתָא, וְהַהוּא חֵילָא לָא מִתְעַתְּדָא לְאִתְּעָרָא גּוֹ הַהוּא חֵילָא דְּנִשְׁמְתָא, וּלְקַבְּלָא לֵיהּ. וְכַד אִתְעָר בַּר נָשׁ, לָאו אִיהוּ דָּכִי. וְהָא אוֹקִימְנָא, דְּסִטְרָא אַחֲרָא שַׁלִּיט, עַל אֲתָר דְּקַיְּימָא בְּלָא נִשְׁמְתָא.","כֵּיוָן דְּאִתְדָכֵּי בְּמַיָּא, וְאַף עַל גַּב דְּאִשְׁתָּדַּל בַּר נָשׁ בְּאוֹרַיְיתָא, (נ\"א טעים טעמא דמותא, דסטרא אחרא שליט על אתר דקיימא בלא נשמתא וכד אתער בר נש אף על גב דאשתדל באורייתא) הַהִיא נִשְׁמְתָא לָא אִתְקַיָּימַת בְּאַתְרָהּ, וְלָא שַׁלְטָא בֵּיהּ בְּבַּר נָשׁ, בַּר חֵילָא דְּדָמָא בִּלְחוֹדוֹי, דְּאִקְרֵי נֶפֶשׁ, הַהִיא דְּאִתְפַּשְּׁטָא בְּדָמָא תָּדִיר, וְהָא אוֹקִימְנָא. וְכַד יִצָלֵי בַּר נָשׁ צְלוֹתָא דְּפוּלְחָנָא דְּמָארֵיהּ, כְּדֵין מִתְיַישְּׁבָא חֵילָא דְּדָמָא בְּאַתְרֵיהּ, וְאִתְגַּבָּר חֵילָא דְּנִשְׁמְתָא, וְאִתְיָישְׁבָא עַל הַהוּא אֲתָר. וּכְדֵין בַּר נָשׁ אִשְׁתְּלִים קַמֵּי מָארֵיהּ, כְּמָה דְּאִצְטְרִיךְ, נֶפֶשׁ לְתַתָּא, וְרָזָא דְּמִלָּה דְּנִשְׁמְתָא לְעֵילָּא.","וְעַל דָּא, מַאן דְּצַלֵּי צְלוֹתָא עַד לָא יֵיכוּל, קָאִים גַּרְמֵיהּ כְּמָה דְּאִצְטְרִיךְ, וְסַלְּקָא נִשְׁמְתָא עַל אֲתָר מוֹתְבָה כְּמָה דְּאִצְטְרִיךְ, וְאִי אָכִיל עַד לָא צַלֵי צְלוֹתֵיהּ לְאִתְיַישְּׁבָא דָּמָא עַל אַתְרֵיהּ, הָא אִיהוּ כִּמְנַחֵשׁ וּמְעוֹנֵן. בְּגִין דְּהָא אִיהוּ אָרְחֵיהּ דִּמְנַחֵשׁ, לְסַלְּקָא לִסְטַר אַחֲרָא, וּלְמָאֲכָא סִטְרָא דִּקְדוּשָּׁה.","אֲמַאי אִקְרֵי בַּר נָשׁ הַהוּא דְּאִשְׁתָּדַּל בְּהַהוּא סִטְרָא מְנַחֵשׁ. עַל דְּאִשְׁתָּדַּל בְּהַהוּא נָחָשׁ, לְאַתָּקְפָא חֵילֵיהּ וּלְאִתְגַּבְּרָא. וְדָא אִיהוּ כְּמַאן דְּפָלַח לֵאלֹהִים אֲחֵרִים. וְכֵן הַאי פָּלַח לְהַהוּא חֵילָא דְּדָמָא, וְלָא פָּלַח לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, לְאַתָּקְפָא סִטְרָא דְּנִשְׁמְתָא, סִטְרָא דִּקְדוּשָּׁה.","מְעוֹנֵן, דְּאִשְׁתָּדַּל בְּחוֹבָא, וְלָא אִשְׁתָּדַּל בִּזְכוּ. וְאִי תֵּימָא הָא קַיְּימָא נ' בְּאֶמְצָעִיתָא. הָכִי הוּא וַדַּאי, דְּהָא לָא יַכְלִין לְשַׁלְּטָאָה בְּהַהוּא סִטְרָא אַחֲרָא, עַד דְּאִתְעַרְבֵי בֵּיהּ עֵרוּבָא דִּסְטָר קְדוּשָּׁה, כְּחוּטָא חַד דָּקִיק. מַאן (הקדמה ב ע\"ב) דְּבָעֵי לְקַיְּימָא שִׁקְרָא, יְעָרַב בָּהּ מִלָּה דִּקְשׁוֹט, בְּגִין דְּיִתְקַיֵּים הַהוּא שִׁקְרָא. וְעַל דָּא עָוֹן מִלָּה דְּשֶׁקֶר הוּא, וּבְגִין לְקַיְּימָא לֵיהּ, עָאלִין בָּהּ מִלָּה דִּקְשׁוֹט, וְדָא אִיהוּ נ', בְּדָא מְקַיְּימֵי לְהַהוּא שֶׁקֶר. וּמַאן דְּלָא צַלֵי צְלוֹתָא לְקַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, עַד לָא יֵיכוּל עַל דָּמֵיהּ, כִּמְנַחֵשׁ וּמְעוֹנֵן.","צְלוֹתָא דְּבַר נָשׁ, כְּמָה דְּאָמַרְתּוּן אַתּוּן קַדִּישֵׁי עֶלְיוֹנִין, זַכָּאָה חוּלָקֵיכוֹן, דְּהָא בִּצְלוֹתָא מִתַתְּקָּן גּוּפֵיהּ וְנַפְשֵׁיהּ דְּבַר נָשׁ, וְאִתְעָבִיד שְׁלִים. צְלוֹתָא אִיהִי תִּקּוּנִין מְתַקְּנָן דְּמִתְתַּקְּנָן כַּחֲדָא, וְאִינּוּן אַרְבַּע. תִּקּוּנָא קַדְמָאָה, תִּקּוּנָא דְּגַרְמֵיהּ, לְאִשְׁתַּלְּמָא. תִּקּוּנָא תִּנְיָינָא, תִּקּוּנָא דְּהַאי עָלְמָא. תִּקּוּנָא תְּלִיתָאָה, תִּקּוּנָא דְּעָלְמָא לְעֵילָּא, בְּכָל אִינּוּן חֵילֵי שְׁמַיָא. תִּקּוּנָא רְבִיעָאָה, תִּקּוּנָא דִּשְׁמָא קַדִּישָׁא, בְּרָזָא דִּרְתִּיכִין קַדִּישִׁין, וּבְרָזָא דְּעָלְמִין כֻּלְּהוּ, עֵילָּא וְתַתָּא בְּתִקּוּנָא (דרזין דשמא קדישא) כְּדְקָא יָאוּת.","תִּקּוּנָא קַדְמָאָה תִּקּוּנָא דְּגַרְמֵיהּ, בְּגִין דְּאִצְטְרִיךְ לְאַתְקְנָא גַּרְמֵיהּ, בְּמִּצְוָה וּקְדוּשָּׁה, וּלְאִתְּתַקְנָא בְּקָרְבְּנִין וְעִלָּוָון לְאִתְדַכָּאָה. תִּקּוּנָא תִּנְיָינָא, בְּתִקּוּנָא דְּקִיּוּמָא דְּהַאי עָלְמָא, בְּעוֹבָדָא דִּבְרֵאשִׁית, לְבָרְכָא לְקוּדְשָׁא בְּרִיךְ הוּא, עַל כָּל עוֹבָדָא וְעוֹבָדָא, בְּאִינּוּן הַלְלוּיָהּ, (תהילים קמ״ח:ג׳-ד׳) הַלְלוּהוּ כָּל כֹּכְבֵי אוֹר הַלְלוּהוּ שְׁמֵי הַשָּׁמַיִם וְגוֹ' לְקַיְּימָא קִיוּמָא דְּהַאי עָלְמָא. וְעַל דָּא בְּבָרוּך שֶׁאָמַר, בָּרוּךְ, בָּרוּךְ עַל כֹּלָּא."],[[0,"ובגין דא יהושע וכו':","ומשום זה יהושע מלא רוח חכמה, משום, כי סמך משה את ידיו עליו, שמשה שהוא בחינת פני חמה שהוא ז\"א, הריק ברכותיו עליו, ונתמלא הבאר ממנו. שהיא המלכות, דהיינו יהושע שהיא פני הלבנה, נתמלא מז\"א, כנ\"ל. ואתם קדושים עליונים, כל אחד מכם נתמלא רוח חכמה, ועומד במילואה בסודות החכמה, משום שהקב\"ה הוא רוצה בכם וסמך ידיו עליכם. אשרי חלקי שעיני ראו זאת, וראו בכם השלמות של רוח חכמה."],[1,"פתח ואמר כתיב וכו':","פו\"א כתוב, לא תאכלו על הדם לא תנחשו ולא תעוננו, מקרא זה העמידוהו, וסוד הדבר כך הוא. מי שאוכל בלי תפלה שיתפלל על דמו הוא שקול כמנחש ומעונן."],[2,"בגין דבליליא נשמתא וכו':","משום שבלילה הנשמה עולה לראות בסוד הכבוד העליון, כל אחת ואחת כמו שראוי לה, ונשאר האדם בכח ההוא שנתפשט בתוך הדם לקיים הגוף. וע\"כ הוא טועם טעם המות, שכח הדם ההוא אינו מוכן להתעורר לכח ההוא של הנשמה ולקבל אותה, וע\"כ כשהעיר האדם משנתו, אינו טהור. והעמדנו שהס\"א שולט על המקום הנמצא בלי נשמה."],[3,"כיון דאתדכי במיא וכו':","כיון שנטהר במים, ואע\"פ שהאדם עסק בתורה, נשמה ההיא אינה מתקיימת במקומה ואינה שולטת בו באדם, רק כח הדם בלבד, שנקרא נפש, נפש ההיא המתפשטת תמיד בתוך הדם. וכבר העמדנו. וכשמתפלל האדם תפלה לעבודת רבונו, אז מתיישב כח הדם במקומו, ומתגבר כח הנשמה, ומתיישבת במקום ההוא בגוף, ואז נשלם האדם לפני רבונו כמו שצריך הנפש למטה, וסוד דבר הנשמה למעלה."],[4,"ועל דא מאן וכו':","ועל כן מי שמתפלל תפלה מטרם שיאכל, העמיד עצמו כמו שצריך, והנשמה עולה על מקום מושבה כמו שצריך. ואם אוכל מטרם שמתפלל תפלתו, שיתיישב הדם על מקומו. הרי הוא כמנחש ומעונן. למה. הוא משום שוה דרכו של מנחש, להעלות הסטרא אחרא ולהשפיל צד הקדושה."],[5,"אמאי אקרי בר נש וכו':","שואל, למה נקרא אדם ההוא שהשתדל בצד ההוא, דהיינו שאכל קודם תפלתו, בשם מנחש. הוא משום שהשתדל בנחש ההוא, דקליפות, להגדיל כחו ולהתגבר. וזה הוא כמי שעובד לאלהים אחרים, וכן זה, עבד לכח הדם ההוא, ולא עבד להקב\"ה להגדיל צד הנשמה, צד הקדושה."],[6,"מעונן, דאשתדל בחובה וכו':","שואל, למה נקרא האוכל קודם תפלתו בשם, מעונן. ומשיב, משום שהשתדל \u0003בעון\u0004, ולא השתדל בזכיות, כי מעונן, הוא אותיות מן עון. ואם תאמר, הרי נ' עומדת באמצע המלה, מעונן, והיה צריך לומר לפי\"ז, מעון, בלי נ' באמצע. ומשיב, כך הוא ודאי, שאין יכולים לשלוט בסטרא אחרא, עד שמערבים בה ערוב מן צד הקדושה, כחוט דק אחד. מי שרוצה לקיים דבר שקר יערוב בה דבר אמת, כדי שיתקיים שקר ההוא. ועל כן \u0003עון,\u0004 הוא דבר שקר, וכדי לקיימו, מכניסים בה דבר אמת, וזה היא \u0003נ\u0004 שבאמצע המלה, מעון, בזה מקיימים השקר. וע\"כ, מי שלא התפלל תפלה לפני הקב\"ה על דמו, מטרם שיאכל, הוא כמנחש וכמעונן."],[7,"צלותא דבר נש וכו':","התפלה של האדם, היא כמו שאמרתם, אתם קדושים עליונים אשרי חלקכם. דהיינו מה שאמרו לעיל (אות ק\"כ) ולהלאה במאמר עלית התפלה, כי בתפלה מתתקן גופו ונפשו של אדם ונעשה שלם. תפלה היא תקונים מתתקנים, שמתתקנים כאחד, והם ארבע תקונים. תקון א', הוא תקון עצמו להשתלם. תקון השני, הוא תקון עולם הזה. תקון השלישי, הוא תקון עולם העליון בכל צבאות השמים. תקון רביעי, הוא תקון השם הקדוש בסוד המרכבות הקדושות, ובסוד העולמות כולם למעלה ולמטה בתקון, כראוי."],[8,"תקונא קדמאה וכו':","ומפרש דבריו, תקון הראשון שאמרתי שהוא תקון של עצמו, הוא, משום שצריך לתקן עצמו במצוה וקדושה, ולהתתקן בקרבנות ועולות להטהר. שציצית ה\"ס מצוה, ותפלין ה\"ס קדושה, ובאמירת קרבנות ועולות מתתקן כמו שהקריב קרבנות. תקון השני, שהוא, תקון של עולם הזה, היינו, במעשה בראשית לברך להקב\"ה על כל מעשה ומעשה באלו, הללויה, הללוהו כל ככבי אור, הללוהו שמי השמים וגו'. שהוא נאמר, לקיים קיום עולם הזה. ועל זה בברוך שאמר, שברוך פירושו ברוך על הכל."]],[[0,"","וּמִשּׁוּם כָּךְ יְהוֹשֻׁעַ מָלֵא רוּחַ חָכְמָה, מִשּׁוּם - כִּי סָמַךְ מֹשֶׁה אֶת יָדָיו עָלָיו, שֶׁהוּא הֵרִיק עָלָיו בְּרָכוֹת וְנִתְמַלְּאָה הַבְּאֵר מִמֶּנּוּ. וְאַתֶּם, קְדוֹשִׁים עֶלְיוֹנִים, כָּל אֶחָד מִכֶּם הִתְמַלֵּא רוּחַ חָכְמָה, וְעוֹמֵד בִּשְׁלֵמוּת בְּסוֹדוֹת הַחָכְמָה, מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְרַצָּה בָכֶם וְסָמַךְ יָדוֹ עֲלֵיכֶם. אַשְׁרֵי חֶלְקִי שֶׁעֵינַי רָאוּ אֶת זֶה וְרָאוּ אֶת שְׁלֵמוּת רוּחַ הַחָכְמָה בָּכֶם."],[1,"","פָּתַח וְאָמַר, כָּתוּב (ויקרא יט) לֹא תֹאכְלוּ עַל הַדָּם לֹא תְנַחֲשׁוּ וְלֹא תְעוֹנֵנוּ. פָּסוּק זֶה פֵּרְשׁוּהוּ, וְסוֹד הַדָּבָר - זֶה מִי שֶׁאוֹכֵל בְּלִי תְפִלָּה, שֶׁיִּתְפַּלֵּל (קדםשאוכל) עַל דָּמוֹ, שָׁקוּל הוּא כִּמְנַחֵשׁ וּמְעוֹנֵן."],[2,"","מִשּׁוּם שֶׁבַּלַּיְלָה הַנְּשָׁמָה עוֹלָה (ומשתטחת) לִרְאוֹת בְּסוֹד הַכָּבוֹד הָעֶלְיוֹן, כָּל אֶחָד וְאֶחָד כְּמוֹ שֶׁרָאוּי לוֹ, וְנִשְׁאָר הָאָדָם בְּאוֹתוֹ כֹּחַ שֶׁהִשְׁתַּתֵּף (שהתפשט) בְּתוֹךְ הַדָּם לְקַיֵּם הַגּוּף, וְלָכֵן (ועם כל זה) טוֹעֵם טַעַם שֶׁל מָוֶת. וְאוֹתוֹ כֹּחַ לֹא נוֹעָד לְהִתְעוֹרֵר לְתוֹךְ אוֹתוֹ כֹּחַ שֶׁל הַנְּשָׁמָה וּלְקַבֵּל אוֹתוֹ. וּכְשֶׁמִּתְעוֹרֵר הָאָדָם, אֵינוֹ טָהוֹר, וַהֲרֵי בֵּאַרְנוּ שֶׁצַּד הָאַחֵר שׁוֹלֵט עַל מָקוֹם שֶׁעוֹמֵד בְּלִי נְשָׁמָה."],[3,"","כֵּיוָן שֶׁנִּטְהַר בְּמַיִם, וְאַף עַל גַּב שֶׁהִשְׁתַּדֵּל אָדָם בַּתּוֹרָה, (טוֹעֵם טַעַם מִיתָה, שֶׁהַצַּד הָאַחֵר שׁוֹלֵט בְּמָקוֹם שֶׁנִּמְצָא בְּלֹא נְשָׁמָה, וּכְשֶׁמִּתְעוֹרֵר בֶּן אָדָם, אַף עַל גַּב שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה) אוֹתָהּ נְשָׁמָה לֹא חוֹזֶרֶת לִמְקוֹמָהּ וְלֹא שׁוֹלֶטֶת בָּאָדָם, פְּרָט לְכֹחַ הַדָּם לְבַדּוֹ שֶׁנִּקְרָא נֶפֶשׁ, אוֹתָהּ שֶׁמִּתְפַּשֶּׁטֶת בְּדָם תָּמִיד, וַהֲרֵי בֵּאַרְנוּ. וּכְשֶׁיִּתְפַּלֵּל אָדָם תְּפִלָּה שֶׁל עֲבוֹדַת אֲדוֹנוֹ, אָז מִתְיַשֵּׁב כֹּחַ הַדָּם בִּמְקוֹמוֹ, וּמִתְגַּבֵּר כֹּחַ הַנְּשָׁמָה וּמִתְיַשֶּׁבֶת עַל אוֹתוֹ מָקוֹם. וְאָז אָדָם מֻשְׁלָם לִפְנֵי אֲדוֹנוֹ, כְּמוֹ שֶׁצָּרִיךְ נֶפֶשׁ לְמַטָּה, וְסוֹד הַדָּבָר שֶׁהַנְּשָׁמָה לְמַעְלָה."],[4,"","וְעַל כָּךְ, מִי שֶׁמִּתְפַּלֵּל תְּפִלָּה טֶרֶם שֶׁיֹּאכַל, מַעֲמִיד עַצְמוֹ כְּמוֹ שֶׁצָּרִיךְ, וְעוֹלָה הַנְּשָׁמָה עַל מְקוֹם מוֹשָׁבָהּ כְּמוֹ שֶׁצָּרִיךְ. וְאִם אָכַל טֶרֶם שֶׁיִּתְפַּלֵּל תְּפִלָּתוֹ, שֶׁיִּתְיַשֵּׁב הַדָּם עַל מְקוֹמוֹ, זֶהוּ כִּמְנַחֵשׁ וּמְעוֹנֵן. מִשּׁוּם שֶׁזּוֹ דַּרְכּוֹ שֶׁל מְנַחֵשׁ לַעֲלוֹת לַצַּד הָאַחֵר, וּלְהַנְמִיךְ אֶת הַצַּד שֶׁל הַקְּדֻשָּׁה."],[5,"","לָמָּה נִקְרָא אוֹתוֹ אָדָם שֶׁמִּשְׁתַּדֵּל בְּאוֹתוֹ צַד מְנַחֵשׁ? עַל שֶׁהִשְׁתַּדֵּל עִם אוֹתוֹ נָחָשׁ לְחַזֵּק כֹּחוֹ וּלְהַגְבִּירוֹ. וְזֶהוּ כְּמִי שֶׁעוֹבֵד אֱלֹהִים אֲחֵרִים. וְכֵן זֶה עוֹבֵד לְאוֹתוֹ כֹּחַ שֶׁל הַדָּם, וְלֹא עוֹבֵד אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא לְחַזֵּק אֶת צַד הַנְּשָׁמָה, הַצַּד שֶׁל הַקְּדֻשָּׁה."],[6,"","מְעוֹנֵן, שֶׁמִּשְׁתַּדֵּל בְּחֵטְא וְלֹא מִשְׁתַּדֵּל בִּזְכֻיּוֹת. וְאִם תֹּאמַר, הֲרֵי עוֹמֶדֶת נ' בָּאֶמְצַע - כָּךְ זֶה וַדַּאי, שֶׁהֲרֵי לֹא יְכוֹלִים לִשְׁלֹט בְּאוֹתוֹ הַצַּד הָאַחֵר, עַד שֶׁמְּעָרְבִים בָּהּ עֵרוּב שֶׁל צַד הַקְּדֻשָּׁה כְּחוּט אֶחָד דַּקִּיק. מִי שֶׁרוֹצֶה לְהַעֲמִיד שֶׁקֶר, יְעָרֵב בּוֹ דְּבַר אֱמֶת כְּדֵי שֶׁיִּתְקַיֵּם אוֹתוֹ שֶׁקֶר. וְעַל זֶה עֲוֹן דְּבַר שֶׁקֶר הוּא, וּכְדֵי לְהַעֲמִידוֹ, מַכְנִיסִים בּוֹ דְּבַר אֱמֶת, וְזוֹהִי נ'. בָּזֶה מַעֲמִידִים אֶת אוֹתוֹ שֶׁקֶר. וּמִי שֶׁלֹּא מִתְפַּלֵּל תְּפִלָּה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא טֶרֶם שֶׁיֹּאכַל עַל דָּמוֹ, כִּמְנַחֵשׁ וּמְעוֹנֵן."],[7,"","תְּפִלַּת אָדָם, כְּפִי שֶׁאֲמַרְתֶּם אַתֶּם קְדוֹשִׁים עֶלְיוֹנִים, אַשְׁרֵי חֶלְקְכֶם, שֶׁהֲרֵי בִּתְפִלָּה מִתְתַּקְּנִים גּוּפוֹ וְנַפְשׁוֹ שֶׁל אָדָם וְנַעֲשֶׂה שָׁלֵם. תְּפִלָּה הִיא תִּקּוּנִים מְתֻקָּנִים שֶׁמִּתְתַּקְּנִים כְּאֶחָד, וְהֵם אַרְבָּעָה. תִּקּוּן רִאשׁוֹן - תִּקּוּן שֶׁל עַצְמוֹ לְהִשְׁתַּלֵּם. תִּקּוּן שֵׁנִי - תִּקּוּן שֶׁל הָעוֹלָם הַזֶּה. תִּקּוּן שְׁלִישִׁי - תִּקּוּן שֶׁל הָעוֹלָם שֶׁלְּמַעְלָה בְּכָל אוֹתָם חֵילוֹת הַשָּׁמַיִם. תִּקּוּן רְבִיעִי - תִּקּוּן שֶׁל הַשֵּׁם הַקָּדוֹשׁ בְּסוֹד הַמֶּרְכָּבוֹת הַקְּדוֹשׁוֹת, וּבְסוֹד כָּל הָעוֹלָמוֹת, מַעְלָה וָמַטָּה בִּתִקּוּן (של סודות השם הקדוש) כָּרָאוּי."],[8,"","תִּקֹּוּן רִאשׁוֹן, תִּקּוּן שֶׁל עַצְמוֹ - מִשּׁוּם שֶׁצָּרִיךְ לְתַקֵּן אֶת עַצְמוֹ בְּמִצְוָה וּקְדֻשָּׁה, וּלְהִתְתַּקֵּן בְּקָרְבָּנוֹת וְעוֹלוֹת לְהִטָּהֵר. תִּקּוּן שֵׁנִי, בַּתִּקּוּן שֶׁל הַקִּיּוּם שֶׁל הָעוֹלָם הַזֶּה, בְּמַעֲשֵׂה בְרֵאשִׁית לְבָרֵךְ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא עַל כָּל מַעֲשֶׂה וּמַעֲשֶׂה בְּאוֹתָם הַלְלוּיָהּ, (תהלים קמח) הַלְלוּהוּ כָּל כּוֹכְבֵי אוֹר הַלְלוּהוּ שְׁמֵי הַשָּׁמַיִם וְגוֹ', לְהַעֲמִיד אֶת קִיּוּם הָעוֹלָם הַזֶּה. וְעַל זֶה בְּבָרוּךְ שֶׁאָמַר, בָּרוּךְ - בָּרוּךְ עַל הַכֹּל."]]],[["תִּקּוּנָא תְּלִיתָאָה, דְּאִיהוּ תִּקּוּנָא לְעָלְמָא לְעֵילָּא, בְּכָל אִינּוּן חַיָּילֵי חַיָּילִין וּמַשִׁרְיָין. יוֹצֵר מְשָׁרְתִים וַאֲשֶׁר מְשָׁרְתָיו וְגוֹ', וְהָאוֹפַנִּים וְחַיּוֹת הַקֹּדֶשׁ. תִּקּוּנָא רְבִיעָאָה, תִּקּוּנָא דִּצְלוֹתָא, בְּתִקּוּנָא דְּרָזָא דִּשְׁמָא קַדִּישָׁא כַּדְקָא אָמַרְתּוּן, זַכָּאָה חוּלָקֵיכוֹן. וְהָכָא רָזָא דְּתִקוּנָא דִּשְׁמָא שְׁלִים. זַכָּאָה חוּלָקִי עִמְּכוֹן בְּהַאי עָלְמָא וּבְעָלְמָא דְּאָתֵי.","פִּקּוּדֵי אוֹרַיְיתָא (ר\"ב ע\"ב) דְּאָמַרְתּוּן בִּצְלוֹתָא וַדַּאי הָכִי הוּא. פָּתַח וְאָמַר, כְּתִיב (דברים י׳:כ׳) אֶת יְיָ' אֱלֹהֶיךָ תִּירָא אוֹתוֹ תַעֲבוֹד. וּכְתִיב, (ויקרא י״ט:י״ד) וְיָרֵאתָ מֵּאֱלהֶיךָ. הַאי קְרָא אִית לְמֵימַר הָכִי, וְיָרֵאתָ אֱלֹהֶיךָ, בְּגִין דְּהָא כְּתִיב אֶת יְיָ' אֱלהֶיךָ תִּירָא, מַהוּ מֵּאֱלֹהֶיךָ. אֶלָּא רָזָא אִיהוּ, מֵּאֱלהֶיךָ וַדַּאי, מֵהַהוּא אֲתָר דְּאִתְחַבָּר וְסָחֲרָא לְמוֹחָא דִּלְגוֹ, וְדָא אִיהוּ מֵּאֱלֹהֶיךָ, דְּחִילוּ דָּא לְמִדְחַל לֵיהּ, דְּהָא תַּמָּן שַׁרְיָיא דִּינָא, וְאִיהוּ דִּינָא דְּאִשְׁתְּאִיב מִגּוֹ דִּינָא דִּלְעֵילָּא, בְּהַאי אֲתָר.","(אית אשא ואית אשא) תְּלַת גְּוָונֵי אֶשָּׁא הָכָא. אֶשָּׁא קַדְמָאָה, אִיהוּ אֶשָּׁא דְּקַבִּיל אֶשָּׁא בְּחֵידוּ, וְחַדָּאן דָּא בְּדָא בִּרְחִימוּ. אֶשָּׁא תִּנְיָינָא, אִיהוּ אֶשָּׁא דִּכְתִּיב בֵּיהּ (יחזקאל א׳:י״ג) וְנֹגַהּ לָאֵשׁ דְּאִתְחָזֵי בֵּיהּ נֹגַהּ. וְדָא אִיהוּ אֶשָּׁא, דְּקַיְּימָא גּוֹ אֶשָּׁא פְּנִימָאָה בְּחֵידוּ, כְּמָה (ר\"ג ע\"ב) דְּאִתְּמַר. אֶשָּׁא תְּלִיתָאָה, אִיהוּ אֶשָּׁא (דלבר) דְּסַחֲרָא לְהַהוּא נֹגַהּ. וּבְהַאי אֶשָּׁא שַׁארִי דְּחִילוּ דְּדִינָא, לְאַלְקָאָה חַיָּיבַיָּא.","וְאַף עַל גַּב דְּתָנֵינָן, דְּאַרְבָּעָה גְּוָונִי אֶשָּׁא נִינְהוּ, וְאִינּוּן אַרְבַּע דְּאִינּוּן חַד. אֲבָל הָכָא בְּהַהוּא אֶשָּׁא דְּקָאָמְרָן, שַׁאֲרִי דְּחִילוּ דְּדִינָא, וְעַל דָּא כְּתִיב, וְיָרֵאתָ מֵּאֱלהֶיךָ, מֵהַהוּא עוֹנְשָׁא דִּילֵיהּ.","וּבְהַהוּא יִרְאָה בָּעֵי לְשַׁוָּואָה רְעוּתֵיהּ, בִּדְחִילוּ וּרְחִימוּ כַּחֲדָא, לְמִדְחַל בְּהַאי סִטְרָא, וּלְמִרְחַם בְּהַאי סִטְרָא. וּבְאִינּוּן גַּוְונִין דְּקָאָמְרָן, וְהַהוּא דְּחִילוּ לֶהוֵי לְמִדְחַל מֵעוֹנְשָׁא. דְּמַאן דְּעָבַר עַל פִּקּוּדֵי אוֹרַיְיתָא, אִתְעַנָּשׁ בְּהַהוּא סִטְרָא דְּכַד שַׁארִי הַהוּא סִטְרָא לְאַלְקָאָה, לָא שָׁכִיךְ עַד דְּשָׁצֵי לֵיהּ מֵהַאי עָלְמָא, וּמֵעָלְמָא דְּאָתֵי. וּבְּגִין כָּךְ בָּעֵי לְמִדְחַל מֵהַאי אֶשָּׁא, דִּדְחִילוּ שַׁרְיָיא בֵּיהּ.","וּמִנֵּיהּ אִתְפָּשַׁט אֶשָּׁא לְבַר דְּדַחֲלָא אַחֲרָא, וְעַל דָּא כְּתִיב, (שופטים ו׳:י׳) לֹא תִּירָאוּ אֶת אֱלֹהֵי הָאֱמוֹרִי, דְּאָסִיר לְמִדְחַל מִנֵּיהּ. וְהַאי אֶשָּׁא דִּדְחִילוּ דְּקָאָמְרָן, אִיהוּ קֹדֶשׁ וְאִשְׁתָּתַּף בִּקְדוּשָּׁה, וְהַאי אִיהוּ דְּסָחֲרָא לְהַהוּא נֹגַהּ דְּקָאָמְרָן. וְהַהִיא אֶשָּׁא אַחֲרָא דִּלְבַר, אִיהוּ דְּאִתְחַבָּר בְּהַאי לְזִמְנִין. וּלְזִמְנִין אִתְעַבָּר מִנֵּיהּ, וְלָא אִתְחֲבָּר בַּהֲדֵיהּ. וְכַד גָּרִים דְּאִתְחַבָּר בְּהַאי, כְּדֵין הוּא אֶשָּׁא דְּחָשׁוּךְ, וְאַחְשִׁיךְ וְכַסֵּי נְהִירוּ דְּאִלֵּין אַחֲרָנִין. וְסִימָנִיךְ (יחזקאל א׳:ד׳) וְאֵשׁ מִתְלַקַּחַת, וְלָא דְּקַיְּימָא תָּדִיר, וְהָא אִתְּמַר","לְבָתַר אַהֲבָה, כְּמָה דְּאוּקְמוּהָ דְּאַהֲבָה שַׁרְיָיא לְבָתַר יִרְאָה. וְרָזָא דְּמִלָּה, כֵּיוָן דְּשָׁארִי יִרְאָה עַל רֵישֵׁיהּ דְּבַר נָשׁ, אִתְּעַר לְבָתַר אַהֲבָה, דְּאִיהוּ יְמִינָא. דְּמַאן דְּפָלַח מִגּוֹ אַהֲבָה, אִתְדַּבָּק בַּאֲתָר עִלָּאָה לְעֵילָּא, וְאִתְדַּבָּק בִּקְדוּשָּׁה דְּעָלְמָא דְּאָתֵי, בְּגִין דְּהָא סָלִיק לְאִתְעַטְּרָא וּלְאִתְדַּבְּקָא בִּסְטַר יְמִינָא.","וְאִי תֵּימָא דְּפוּלְחָנָא דְּאִיהוּ מִסִּטְרָא דְּיִרְאָה לָאו אִיהוּ פּוּלְחָנָא. פּוּלְחָנָא יַקִּירָא אִיהוּ, אֲבָל לָא סָלִיק לְאִתְדַּבְּקָא לְעֵילָּא. וְכַד פָּלַח מֵאַהֲבָה, סָלִיק וְאִתְעַטָּר לְעֵילָּא, וְאִתְדַּבָּק בְּעָלְמָא דְּאָתֵי, וְדָא אִיהוּ בַּר נָשׁ דְּאִזְדָּמָן לְעָלְמָא דְּאָתֵי, זַכָּאָה חוּלָקֵיהּ דְּהָא שַׁלִיט עַל אֲתָר דְּיִרְאָה, דְּהָא לֵית מַאן דְּשַׁלִּיט עַל דַּרְגָּא דְּיִרְאָה, אֶלָּא אַהֲבָה, רָזָא דִּימִינָא.","רָזָא דְּיִחוּדָא דְּאִצְטְרִיךְ לֵיהּ לְהַהוּא דְּאִתְחָזֵי לְעָלְמָא דְּאָתֵי, לְיַחֲדָא שְׁמָא דְּקוּדְשָׁא בְּרִיךְ הוּא, וּלְיַיחֲדָא שַׁיְיפִין וְדַרְגִּין עִלָּאִין וְתַתָּאִין, לְאַכְלְלָא כֻּלְּהוּ, וּלְאַעְלָאָה בַּאֲתָר דְּאִצְטְרִיךְ לְקַשְּׁרָא קִשְׁרָא. וְדָא אִיהוּ רָזָא דִּכְתִיב, (דברים ו׳:ד׳) שְׁמַע יִשְׂרָאֵל יְיָ' אֱלהֵינוּ יְיָ' אֶחָד.","וְרָזָא (ק\"ס ע\"ב) דִּשְׁמַע, שֵׁם דְּסָלִיק לְע' שְׁמָהָן, וְדָא כְּלָלָא חֲדָא. יִשְׂרָאֵל: יִשְׂרָאֵל סָבָא, בְּגִין דְּאִית (מ\"ג ע\"א) זוּטָא, דִּכְתִּיב (הושע י״א:א׳) נַעַר יִשְׂרָאֵל וָאֹהֲבֵהוּ. וְדָא אִיהוּ יִשְׂרָאֵל סָבָא, רָזָא חֲדָא בִּכְלָלָא חֲדָא. שְׁמַע יִשְׂרָאֵל, הָכָא אִתְכְּלִילַת אִתְּתָא בְּבַעְלָהּ."],[[0,"תקונא תליתאה וכו':","תקון השלישי, שהוא תקון עולם העליון בכל אלו צבאות ומחנות, היינו השבח, יוצר משרתים ואשר משרתיו וגו'. וכן, והאופנים וחיות הקדש. תקון הרביעי, הוא תקון התפלה של שמונה עשרה, שוהא תקון הסוד של השם הקדוש, כמו שאמרתם (במאמר עלית התפלה) אשרי חלקכם. וכאן סוד התקון של שם שלם. אשרי חלקי עמכם בעולם הזה ובעולם הבא."],[1,"פקודי אורייתא דאמרתון וכו'",": מצות התורה שאמרתם, (לעיל מאות קנ\"א עד קנ\"ו) בתפלה, ודאי כך הוא. פתח ואמר, כתוב, את ה' אלהיך תירא ואותו תעבד. וכתוב, ויראת מאלקיך. מקרא זה היה צריך לומר כך, ויראת אלקיך, משום שהרי כתוב, את ה' אלקיך תירא ולא כתוב מאלקיך תירא. מהו מאלקיך. ומשיב, אלא סוד הוא, מאלקיך ודאי, דהיינו ממקום ההוא המתחבר ומקיף למוח שמבפנים שהוא השכינה, הנקראת אלקים, ומסביבתה מקיף אש, בסוד אש המקיף לנגה, שמשם נמשך הדין לרשעים כמ\"ש לפנינו. וזהו מאלקיך, דהיינו אש המקיף, יש יראה זו לירא מפניו, כי שם שורה הדין. והוא דין הנשאב מדין של מעלה שבמקום הזה. כמ\"ש לפנינו."],[2,"תלת גווני אשא וכו':","ג' מיני אש יש כאן. אש הראשונה היא אש המקבלת אש בשמחה, ושמחים זה בזה באהבה. אש השניה, היא אש שכתוב בה, \u0003ונגה לאש,\u0004 שנראה בה הנגה, שהיא השכינה, וזה היא אש העומדת בשמחה תוך אש הפנימית, שאמרנו, דהיינו אש הראשונה. אש השלישית, היא אש המסבבת לנגה ההיא, שהיא השכינה, ובאש הזו שורה יראת הדין להכות הרשעים."],[2,"","פירוש. יש ב' פירושים על נגה, פירוש א' שהיא קליפה הקרובה לקדושה שחציה טוב וחציה רע. פירוש ב' שהשכינה נקראת נגה. ולפעמים אוחז הזהר פירוש הא' ולפעמים פירוש הב', וכאן אוחז הזהר פירוש הב' שנגה היא השכינה, שה\"ס חכמה תתאה. ויש ג' בחינת אש, שפירושו דינים, אש אחת, היא בקו ימין, הנמשך מנקודת החולם. אש שניה, היא בקו שמאל, הנמשך מנקודת השורק, מטעם חוסר חסדים. אש שלישית היא מקו האמצעי, הנמשך מנקודת החירק, (כנ\"ל ב\"א ט\"ו ד\"ה ההיא) שמסבתו נעשה היחוד של ימין ושמאל. ומגביל השמאל שלא יאיר אלא ממטה למעלה. (כנ\"ל ב\"א דף ט' ד\"ה מחלוקת)."],[2,"","וזה אמרו \u0003אשא קדמאה איחו אשא דקביל אשא בחדו וחדאן דא בדא ברחימו.\u0004 שהיא האש שבקו ימין, המקבלת האש שבקו שמאל בשמחה רבה, כי האש דקו שמאל משלמת אותה בהארת החכמה וכן אש השמאל מקבלת אש הימין בשמחה, שהיא נשלמת על ידה בחסדים. וע\"כ \u0003חדאן דא בדא ברחימו.\u0004 כי משלימים זו את זו. \u0003אשא תניינא, איהו אשא דכתיב ביה ונגה לאש,\u0004 נגה היא השכינה כנ\"ל שה\"ס חכמה תתאה המקבלת מקו שמאל, ונודע שאין החכמה מתגלה אלא בעת גילוי הדינים דנקודת השורק, (כנ\"ל וירא דף ס\"ד ד\"ה וז\"ש חד) שז\"ס \u0003ונגה לאש\u0004 דהיינו \u0003דאתחזי ביה נגה,\u0004 שהנגה שה\"ס חכמה תתאה אינה נראית אלא באש דנקודת השורק הנמשך אליה מקו שמאל. וז\"ש, \u0003ודא איהו אשא דקיימא גו אשא פנימאה בחידו\u0004. כי היא אותה האש דקו שמאל מנקודת השורק העומד עם אש הפנימית דקו ימין בשמחה גדולה, כנ\"ל בסוד אשא תניינא. \u0003אשא תליתאה איהו אשא דסחרא לההוא נגה.\u0004 מסחרא, פירושו, שמסבבה ומגבילה שלא תאיר ממעלה למטה, אלא ממטה למעלה, שהוא האש דקו האמצעי המקיף את הנגה ומגבילה כנ\"ל. \u0003ובהאי אשא שארי דחילו דדינא לאלקאה חייביא,\u0004 דהיינו שמענישת הרשעים העוברים על גבול שלה הנ\"ל."],[3,"ואע\"ג דתנינן דארבעה וכו':","ואע\"פ שלמדנו, שהן ארבעה גווני אש, דהיינו לבן אדום ירוק שחור, ואלו ארבעה הם אחד, שכל אחד נכלל מאלו ד' גוונים, שהם חו\"ג תו\"מ, אבל כאן באש ההיא שאמרנו, לא באנו לומר, אלא המקום ששורה שם יראת הדין, שע\"כ הוכרחנו לפרט ג' אשים, ולא יותר. ועל זה כתוב, ויראת מאלקיך, שפירושו מעונש ההוא שלו. וע\"כ כתוב מאלקיך, עם מ', (כנ\"ל אות ת\"י)."],[4,"ובההוא יראה בעי וכו':","וביראה ההיא צריך לשום רצונו ביראה ואהבה ביחד, לירא בצד זה הנמשך משמאל, ולאהוב בצד זה הנמשך מימין, ובאלו הגוונים שאמרנו, שגם במלכות יש אלו ד' גוונים חו\"ג תו\"מ. ויראה ההיא תהיה לירא מעונש, שהיא יראה תחתונה, שמי שעובר על מצות התורה, נענש בצד ההוא שמשמאל, כי כשמתחיל צד ההוא להכות אינו נשקט, עד שמכלה אותו מעולם הזה ומעולם הבא. וע\"כ צריך לירא מאש הזה, שהיראה שורה בו."],[5,"ומניה אתפשט אשא וכו':","וממנו, מאשא תליתאה, מתפשטת אש לחוץ של אלהים אחרים. ועל זה כתוב, לא תראו את אלהי האמורי. כי אסור לירא ממנו. ואש הזה של היראה, דהיינו אשא תליתאה, שאמרנו, היא קדש ומשתתפת בקדושה, וזו היא שמסבבת לנגה ההיא שאמרנו, שלולא אש הזאת, לא היה מתיחד הימין עם השמאל כנ\"ל, וע\"כ היא קדושה, אע\"פ שמגבילה את הנגה, שלא תאיר אלא ממטה למעלה כנ\"ל. אבל אש אחרת ההיא שמבחוץ, היא שמתחברת לפעמים באש הזאת של היראה, ולפעמים נעברת ממנה, ואינה מתחברת עמה. וכשהעונות גורמים שאש החיצונית מתחברת באש הזו של היראה, אז היא אש חשכה ומחשכת ומכסית האורות של אלו האחרים שבנגה, והסימן שלך, ואש מתלקחת, ואינה עומדת תמיד בקביעות. והרי נתבאר."],[6,"לבתר אהבה כמה וכו':","אחר זה, היא אהבה. כמו שהעמידוהו, שאהבה שורה לאחר שזכה ביראה. וסוד הדבר, כיון ששורה יראה על ראשו של אדם, שהוא משמאל כנ\"ל, מתעורר אחר כך אהבה שהוא ימין, דהיינו ז\"א מבחינת החסד שבו. שמי שעובד מתוך אהבה, מתדבק במקום עליון למעלה, ומתדבק בקדושה של עולם הבא, שהיא בינה, משום שהוא עולה להתעטר ולהתדבק בצד ימין. שהוא חסד דז\"א, שעליו שורה הבינה."],[7,"ואי תימא דפולחנא וכו':","ואם תאמר שעבודה שהוא מצד היראה אינה עבודה. אינו כך, אלא עבודה יקרה היא, אבל אינה עולה להתדבק למעלה בז\"א. וכשעובד מאהבה, עולה ומתעטר למעלה ומתדבק בעולם הבא. וזה הוא אדם המזומן לעולם הבא. אשרי חלקו. כי הוא שולט על מקום היראה, כי אין מי ששולט על מדרגת היראה אלא אהבה, שהוא סוד הימין, סוד היחוד. דז\"א ומלכות."],[8,"דאצטריך ליה לההוא","וכו': כי צריך לו, לאותו שראוי לעולם הבא, ליחד שם הקב\"ה, וליחד אברים, שהם זו\"ן, ומדרגות עליונות שהם או\"א, העליונים ותחתונים לכללם כולם, ולהכניס כולם במקום שצריך, דהיינו בא\"ס ב\"ה, לקשור קשרים. וזה הוא סוד שכתוב, שמע ישראל ה' אלקינו ה' אחד."],[9,"ורזא דשמע, שם וכו':","וסוד המלה \u0003שמע,\u0004 הוא שם שהיא המלכות, העולה לע' שמות שהוא השם ע\"ב שבמרכבה העליונה, דהיינו חגת\"ם דז\"א שלמעלה מחזה, וזה כלל אחד, דהיינו שהמלכות הנקראת \u0003שם\u0004 נכללת בז\"א שלמעלה מחזה, שה\"ס \u0003ע'\u0004 גדולה. \u0003ישראל,\u0004 היינו ישראל סבא, שהוא ו\"ק דבינה, משום שיש ישראל זוטא, שהוא ז\"א, שכתוב נער ישראל ואהבהו. אבל זה הוא ישראל סבא, סוד אחד בכלל אחד. שז\"א ומלכות הנרמזים בשמע, הם בכלל אחד עם ישראל סבא. שעולים אליו ומתיחדים בו. \u0003שמע ישראל,\u0004 יורה שכאן, בישראל סבא, נכללו אשה בבעלה, דהיינו המלכות בז\"א."]],[[0,"","תִּקּוּן שְׁלִישִׁי, שֶׁהוּא תִּקּוּן שֶׁל הָעוֹלָם לְמַעְלָה בְּכָל אוֹתָם חֲיָלוֹת חַיָּלִים וּמַחֲנוֹת - יוֹצֵר מְשָׁרְתִים וַאֲשֶׁר מְשָׁרְתָיו וְגוֹ', וְהָאוֹפַנִּים וְחַיּוֹת הַקֹּדֶשׁ. תִּקּוּן רְבִיעִי, תִּקּוּן הַתְּפִלָּה בַּתִּקּוּן שֶׁל סוֹד הַשֵּׁם הַקָּדוֹשׁ כְּמוֹ שֶׁאֲמַרְתֶּם, אַשְׁרֵי חֶלְקְכֶם. וְכָאן סוֹד הַתִּקּוּן שֶׁל הַשֵּׁם הַשָּׁלֵם. אַשְׁרֵי חֶלְקִי עִמָּכֶם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא."],[1,"","מִצְווֹת הַתּוֹרָה שֶׁאֲמַרְתֶּם בַּתְּפִלָּה וַדַּאי כָּךְ הוּא. פָּתַח וְאָמַר, כָּתוּב (דברים י) אֶת ה' אֱלֹהֶיךְ תִּירָא אֹתוֹ תַעֲבֹד. וְכָתוּב, (ויקרא יט) וְיָרֵאתָ מֵּאֱלֹהֶיךְ. בְּפָסוּק זֶה יֵשׁ לוֹמַר כָּךְ: וְיָרֵאתָ מֵּאֱלֹהֶיךְ, מִשּׁוּם שֶׁהֲרֵי כָּתוּב אֶת ה' אֱלֹהֶיךְ תִּירָא. מַה זֶּה מֵאֱלֹהֶיךְ? אֶלָּא סוֹד הוּא, מֵאֱלֹהֶיךְ וַדַּאי, מֵאוֹתוֹ מָקוֹם שֶׁהִתְחַבֵּר וְסוֹבֵב אֶת הַמֹּחַ שֶׁלִּפְנִים, וְזֶהוּ מֵאֱלֹהֶיךְ. יִרְאָה זוֹ לִפְחֹד מִמֶּנּוּ, שֶׁהֲרֵי שָׁם שׁוֹרֶה הַדִּין, וְהוּא דִּין שֶׁנִּשְׁאָב מִתּוֹךְ הַדִּין שֶׁלְּמַעְלָה בַּמָּקוֹם הַזֶּה."],[2,"","(יש אש ויש אש) שְׁלֹשָׁה גּוֹנֵי אֵשׁ כָּאן. אֵשׁ רִאשׁוֹנָה הִיא אֵשׁ שֶׁקִּבְּלָה אֵשׁ בְּשִׂמְחָה, וּשְׂמֵחִים זֶה עִם בְּאַהֲבָה. הָאֵשׁ הַשְּׁנִיָּה הִיא הָאֵשׁ שֶׁכָּתוּב בָּהּ (יחזקאל א) וְנֹגַהּ לָאֵשׁ, שֶׁנִּרְאֶה בָּהּ נֹגַהּ, וְזוֹהִי אֵשׁ שֶׁעוֹמֶדֶת בְּתוֹךְ הָאֵשׁ הַפְּנִימִית בְּשִׂמְחָה, כְּמוֹ שֶׁנִּתְבָּאֵר. הָאֵשׁ הַשְּׁלִישִׁית הִיא אֵשׁ (שבחוץ) שֶׁסּוֹבֶבֶת אוֹתוֹ נֹגַהּ, וּבְזוֹ הָאֵשׁ הִתְחִילָה יִרְאַת הַדִּין לְהַלְקוֹת הָרְשָׁעִים."],[3,"","וְאַף עַל גַּב שֶׁשָּׁנִינוּ שֶׁאַרְבָּעָה צְבָעִים שֶׁל אֵשׁ הֵם, וְאֵלּוּ אַרְבָּעָה שֶׁהֵם אֶחָד. אֲבָל כָּאן בָּאֵשׁ הַהִיא שֶׁאָנוּ אוֹמְרִים, מַתְחִיל פַּחַד הַדִּין, וְעַל זֶה כָּתוּב וְיָרֵאתָ מֵּאֱלֹהֶיךְ, מֵאוֹתוֹ הָעֹנֶשׁ שֶׁלּוֹ."],[4,"","וּבְאוֹתָהּ יִרְאָה צָרִיךְ לָשִׂים רְצוֹנוֹ בְּיִרְאָה וְאַהֲבָה כְּאֶחָד, לְפַחֵד בְּצַד זֶה - וְלֶאֱהֹב בְּצַד זֶה, וּבְאוֹתָם גְּוָנִים שֶׁאָמַרְנוּ, וְאוֹתוֹ הַפַּחַד לִהְיוֹת פּוֹחֵד מֵעֹנֶשׁ. שֶׁמִּי שֶׁעוֹבֵר עַל מִצְווֹת הַתּוֹרָה נֶעֱנָשׁ בְּאוֹתוֹ צַד. שֶׁכְּשֶׁמַּתְחִיל אוֹתוֹ צַד לְהַלְקוֹת, לֹא שׁוֹקֵט עַד שֶׁמְּכַלֶּה אוֹתוֹ מֵהָעוֹלָם הַזֶּה וּמֵהָעוֹלָם הַבָּא. וּמִשּׁוּם כָּךְ צָרִיךְ לִפְחֹד מֵהָאֵשׁ הַ את שֶׁשָּׁרוּי בָּהּ הַפַּחַד."],[5,"","וּמִמֶּנָּה מִתְפַּשֶּׁטֶת אֵשׁ לַחוּץ שֶׁל יִרְאָה אַחֶרֶת, וְעַל זֶה כָּתוּב (שופטים ו) לֹא תִירְאוּ אֶת אֱלֹהֵי הָאֱמֹרִי, שֶׁאָסוּר לִפְחֹד מִמֶּנּוּ. וְהָאֵשׁ הַזּוֹ שֶׁל יִרְאָה שֶׁאָמַרְנוּ הִיא קֹדֶשׁ וּמִשְׁתַּתֶּפֶת בִּקְדֻשָּׁה, וְזוֹהִי שֶׁסּוֹבֶבֶת אוֹתוֹ נֹגַהּ שֶׁאָמַרְנוּ. וְאוֹתָהּ אֵשׁ אַחֶרֶת שֶׁבַּחוּץ, מִתְחַבֶּרֶת בָּזוֹ לִפְעָמִים, וְלִפְעָמִים מָעֳבֶרֶת מִמֶּנָּה וְלֹא מִתְחַבֶּרֶת עִמָּהּ. וּכְשֶׁגּוֹרֵם שֶׁתִּתְחַבֵּר בָּזוֹ, אֲזַי הוּא אֵשׁ שֶׁל חֹשֶׁךְ, וּמַחֲשִׁיכָה וּמְכַסָּה אֶת הָאוֹר שֶׁל הָאֲחֵרוֹת הַלָּלוּ, וְסִימָנְךְ - וְאֵשׁ מִתְלַקַּחַת, וְלֹא שֶׁתָּמִיד עוֹמֶדֶת, וַהֲרֵי זֶה נִתְבָּאֵר."],[6,"","אַחַר כָּךְ הִיא אַהֲבָה, כְּמוֹ שֶׁבֵּאֲרוּהָ שֶׁאַהֲבָה שׁוֹרָה לְאַחַר יִרְאָה. וְסוֹד הַדָּבָר - כֵּיוָן שֶׁהִתְחִילָה יִרְאָה עַל רֹאשׁוֹ שֶׁל הָאָדָם, מִתְעוֹרֶרֶת אַחַר כָּךְ אַהֲבָה, שֶׁהִיא יָמִין, שֶׁמִּי שֶׁעוֹבֵד מִתּוֹךְ אַהֲבָה, נִדְבָּק בְּמָקוֹם עֶלְיוֹן לְמַעְלָה וְנִדְבָּק בִּקְדֻשַּׁת הָעוֹלָם הַבָּא, מִשּׁוּם שֶׁהֲרֵי עוֹלָה לְהִתְעַטֵּר וּלְהִדָּבֵק בְּצַד הַיָּמִין."],[7,"","וְאִם תֹּאמַר שֶׁעֲבוֹדָה שֶׁהִיא מִצַּד הַיִּרְאָה אֵינָהּ עֲבוֹדָה - עֲבוֹדָה נִכְבָּדָה הִיא, אֲבָל לֹא עוֹלָה לְהִדָּבֵק לְמַעְלָה. וּכְשֶׁעוֹבֵד מֵאַהֲבָה, עוֹלֶה וּמִתְעַטֵּר לְמַעְלָה וְנִדְבָּק בָּעוֹלָם הַבָּא, וְזֶהוּ אָדָם שֶׁמְּזֻמָּן לָעוֹלָם הַבָּא. אַשְׁרֵי חֶלְקוֹ, שֶׁהוּא שׁוֹלֵט עַל מְקוֹם הַיִּרְאָה, שֶׁהֲרֵי אֵין מִי שֶׁשּׁוֹלֵט עַל דַּרְגַּת הַיִּרְאָה, אֶלָּא רַק אַהֲבָה, סוֹד הַיָּמִין."],[8,"","סוֹד הַיִּחוּד שֶׁצָּרִיךְ לְאוֹתוֹ שֶׁרָאוּי לָעוֹלָם הַבָּא, לְיַחֵד אֶת שְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וּלְיַחֵד הָאֵיבָרִים וְהַדְּרָגוֹת הָעֶלְיוֹנוֹת וְהַתַּחְתּוֹנוֹת, לְהַכְלִיל אֶת כֻּלָּם וּלְהַכְנִיסָם לְמָקוֹם שֶׁצָּרִיךְ לִקְשֹׁר קֶשֶׁר. וְזֶהוּ סוֹד הַכָּתוּב, (דברים ו) שְׁמַע יִשְׂרָאֵל ה' אֱלֹהֵינוּ ה' אֶחָד."],[9,"","וְסוֹד שֶׁל שְׁמַע - שֵׁם שֶׁעוֹלֶה לְשִׁבְעִים שֵׁמוֹת, וְזֶה כְּלָל אֶחָד. יִשְׂרָאֵל - יִשְׂרָאֵל סָבָא, מִשּׁוּם שֶׁיֵּשׁ קָטָן, שֶׁכָּתוּב (הושע יא) נַעַר יִשְׂרָאֵל וָאֹהֲבֵהוּ. וְזֶהוּ יִשְׂרָאֵל סָבָא, סוֹד אֶחָד בִּכְלָל אֶחָד. שְׁמַע יִשְׂרָאֵל - כָּאן נִכְלֶלֶת אִשָּׁה בְּבַעְלָהּ."]]],[["וּלְבָתַר דְּאִתְכְּלִילוּ דָּא בְּדָא בִּכְלָלָא חֲדָא, כְּדֵין אִצְטְרִיכוּ לְיַיחֲדָא שַׁיְיפִין, וּלְחַבְרָא תְּרֵין מַשְׁכְּנִין כַּחֲדָא, בְּכֻלְּהוּ שַׁיְיפִין, בִּרְעוּ דְּלִבָּא, לְאִסְתַּלְּקָא בִּדְבֵקוּתָא דְּאֵין סוֹף, לְאִתְדַּבְּקָא כֹּלָּא תַּמָּן, לְמֶהֱוֵי רְעוּתָא חֲדָא עִלָּאֵי וְתַתָּאֵי.","וְרָזָא דָּא יִהְיֶה, כְּמָה דְאַתְּ אָמֵר (זכריה יד) יִהְיֶה יְיָ' אֶחָד, בְּרָזָא דְּיִהְיֶה. י', לְיַחֲדָא וּלְאִתְדַּבְּקָא בה', דְּאִיהוּ הֵיכָלָא פְּנִימָאָה, לְאֲתָר (נ\"א אתר) גְּנִיזוּ דְּהַאי נְקוּדָה עִלָּאָה, דְּאִיהִי י'. וְדָא אִיהוּ רָזָא יְדוָֹ\"ד אֱלהֵינוּ. אִלֵּין תְּרֵין אַתְוָון (נ\"א שמהן) דְּאִינּוּן יָ\"ה.","וּלְאַכְלְלָא כָּל שַׁיְיפִין בְּהַהוּא אֲתָר דְּנַפְקוּ מִנֵּיהּ, דְּאִיהוּ הֵיכָלָא פְּנִימָאָה, לְאַתְבָא מִלִּין לְאַתְרֵיהוֹן, לְעִקָרָא וִיסוֹדָא וְשָׁרְשָׁא דִּילְהוֹן, עַד הַהוּא אֲתָר דְּשָׁרְשָׁא דִּבְרִית.","וּלְבָתַר אִינּוּן תְּרֵין אַתְוָון אַחֲרָנִין (דאיהו י\"ה) לְיַחֲדָא וּלְאִתְדַּבְּקָא י' בְּה'. י' אִיהוּ רָזָא דִּבְרִית קַדִּישָׁא. וְהַאי ה' אִיהוּ הֵיכָלָא, אֲתָר גְּנִיזוּ דְהַאי רָזָא דִּבְרִית קַדִּישָׁא דְּאִיהוּ י'. וְאַף עַל גַּב דְּאוֹקִימְנָא דְּאִיהוּ ו' תִּנְיָינָא. אֲבָל י', רָזָא דִּילֵיהּ לְיַחֲדָא לוֹן כַּחֲדָא.","אֶחָד, לְיַחֲדָא מִתַּמָּן וּלְעֵילָּא, כֹּלָּא כַּחֲדָא, וּלְסַלְּקָא רְעוּתָא לְאִתְקַשְּׁרָא כֹּלָּא (מתתא לעילא) בְּקִשּׁוּרָא חַד. לְסַלְּקָא רְעוּתֵיהּ בִּדְחִילוּ וּרְחִימוּ לְעֵילָּא לְעֵילָּא עַד אֵין סוֹף וְלָא יִשְׁתְּבַק רְעוּתָא מִכָּל אִינּוּן דַּרְגִּין וְשַׁיְיפִין, אֶלָּא בְּכֻלְּהוּ יִסְתְּלַק רְעוּתֵיהּ לְאַדְבְּקָא לוֹן, וּלְמֶהֱוֵי כֹּלָּא קִשּׁוּרָא חֲדָא בְּאֵין סוֹף.","וְדָא הוּא יִחוּדָא דְּרַב הַמְנוּנָא סָבָא, דְּאוֹלִיף מֵאָבוֹי, וַאֲבוֹי מֵרַבֵּיהּ, עַד פּוּמָא דְּאֵלִיָּהוּ, וְשַׁפִּיר אִיהוּ, וְיִחוּדָא בְּתִקּוּנָא. וְאַף עַל גַּב דְּאֲנָן אוֹקִימְנָא לְהַאי בְּכַמָּה רָזִין, כֻּלְּהוּ רָזִין סַלְּקִין לְחַד. אֲבָל רָזָא דָּא אַשְׁכַּחְנָא בְּסִפְרֵיהּ, וְשַׁפִּיר אִיהוּ, וְיִחוּדָא בְּתִקּוּנָא. וְהָא אֲנָן בְּיִחוּדָא דְּרָזָא אַחֲרָא אִתְּעַרְנָא מִלִּין, וְאִיהוּ שַׁפִּיר, וְיִחוּדָא כַּדְקָא חֲזֵי וְהָכִי הוּא. אֲבָל יִחוּדָא דָּא, יִחוּדָא בְּתִקּוּנָא, וְדָא אִיהוּ יִחוּדָא דְּרַב הַמְנוּנָא סָבָא.","וְתוּ הֲוָה אָמַר, מַאן דִּרְעוּתֵיהּ לְאַכְלְלָא כָּל רָזִין דְּיִחוּדָא בְּמִלָּה דְּאֶחָד שַׁפִּיר טְפֵי. וּלְהָכִי אֲנָן מַאֲרִיכִין בְּאֶחָד, לְסַלְּקָא רְעוּתֵיהּ מֵעֵילָּא לְתַתָּא, וּמִתַּתָּא לְעֵילָּא, לְמֶהוֵי כֹּלָּא חַד. אֲבָל בְּרָזָא דָּא יִהְיֶ\"ה, סִימָנָא (בעלמא) אִיהוּ לְהַאי.","וְהָא דְּתָנֵינָן אֶחָד (למהוי ד') רָזָא עֵילָּא וְתַתָּא, וְאַרְבַּע סִטְרִין דְּעָלְמָא, הָכִי אִיהוּ. לְיַחֲדָא עֵילָּא וְתַתָּא כְּמָה דְּאִתְּמַר (ס\"א ולארבע) וְאַרְבַּע סִטְרִין דְּעָלְמָא, אִלֵּין אִינּוּן רָזָא רְתִיכָא עִלָּאָה, לְאִתְכַּלְּלָא כֹּלָּא כַּחֲדָא, בְּקִשְׁרָא חֲדָא, בְּיִחוּדָא חֲדָא עַד אֵין סוֹף, כְּמָה דְּאוֹקִימְנָא.","רָזָא לְאַדְכְּרָא יְצִיאַת מִצְרַיִם לְבָתַר. בְּגִין דַּהֲוַות שְׁכִינְתָּא בְּגָלוּתָא, וּבְזִמְנָא דְּאִיהִי בְּגָלוּתָא, לָאו אִיהוּ חִבּוּרָא, לְאִתְחַבְּרָא דָּא בְּדָא עָלְמָא תַּתָּאָה בְּעָלְמָא עִלָּאָה, וּלְאַחֲזָאָה חֵירוּ דְּהַהִיא גְּאוּלָה, דַּהֲוַות בְּכַמָּה אָתִין, בְּכַמָּה נִסִּין דְּעֲבַד קוּדְשָׁא בְּרִיךְ הוּא. וְאִצְטְרִיךְ הַהוּא פּוּרְקָנָא לְאִתְדַכְּרָא, וּלְאִתְחֲזָאָה דְּאַף עַל גַּב דַּהֲוַות בְּגָלוּתָא, הַשְׁתָּא חֵירוּ אִית לָהּ, מִיּוֹמָא דְּאִינּוּן קִשְׁרִין בְּמִצְרַיִם אִשְׁתְּרִיאוּ, אִינּוּן אָתִין וְנִסִּין אִתְעָבִידוּ.","וְאִצְטְרִיךָ לְאַחֲזָאָה חֵירוּ דִּילָהּ, בְּגִין דְּאִתְחַבְּרָא בְּבַעְלָהּ וּבְגִין לְאַסְמְכָא גְּאוּלָה לִתְפִלָּה, לְמֶהוֵי כֹּלָּא חַד בְּלָא פִּרוּדָא, וְלָא לְאַחֲזָאָה תִּרוּכִין, וְסִימָנִיךְ (ויקרא כ״א:ז׳) וְאִשָּׁה גְּרוּשָׁה מֵאִישָׁהּ לֹא יִקְחוּ.","וְאִי תֵּימָא, וְהָא בְּגָלוּתָא אִיהִי, וְהָא אִתְתַּרְכַת, לָאו הָכִי, אֶלָּא וַדַּאי בְּגָלוּתָא אִיהִי, לְדַיְּירָא עִמְּהוֹן דְּיִשְׂרָאֵל, וּלְאַגָּנָא עָלַיְיהוּ, אֲבָל לָא אִתְתַּרְכַת. וְהָא שְׁכִינְתָּא לָא אִתְחָזֵי בְּבַיִת רִאשׁוֹן וּבְבֵית שֵׁנִי. עַד דְּלָא גָּלוּ יִשְׂרָאֵל סַלְּקָא לְעֵילָּא, וּלְבָתַר אִיהִי שָׁוִיאַת מָדוֹרָה עִמְּהוֹן. אֲבָל תִּרוּכִין לָא הֲוַות לְעָלְמִין.","וּבְגִין דָּא בָּעֵי לְאַחֲזָאָה פּוּרְקָנָא, דְּאִית בָּה אַרְבַּע גְאוּלוֹת. וְרָזָא הָכָא, בְּשַׁעֲתָא דְּנָפְקָא שְׁכִינְתָּא מִגָּלוּתָא דְּמִצְרַיִם, תַּבְעַת מְקּוּדְשָׁא בְּרִיךְ הוּא, דְּיִפְרוֹק לָהּ הַשְׁתָּא ד' זִמְנִין, דְּאִינּוּן ד' גְאוּלוֹת, לָקֳבֵל אַרְבַּע גָּלֻיוֹת. בְּגִין דְּתְהֵא בַּת חוֹרִין, וְלָא תְּהֵא מִתְתַּרְכָא. וּבְהַהִיא שַׁעֲתָא קַיְּימָא וְאִתְפָּרְקַת אַרְבַּע גְאוּלוֹת, בְּהַהִיא יְצִיאַת מִצְרַיִם. וְהַשְׁתָּא דְּאִצְטְרִיכַת בְּתִקּוּנָהָא לְאִתְחַבְּרָא בְּבַעְלָהּ, אִצְטְרִיךְ לְאַחֲזָאָה הַהִיא גְּאוּלַת מִצְרַיִם, דְּאִית בָּה אַרְבַּע גְאוּלוֹת."],[[0,"ולבתר דאתכלילו דא וכו':","ולאחר שנכללו ז\"א ומלכות זה בזה בכלל אחד בישראל סבא אז צריכים ליחד האברים, ו\"ק דז\"א ומלכות, ולחבר ב' משכנות יחד בכל האברים, שמשכן העליון ה\"ס י\"ה, ומשכן התחתון ה\"ס ו\"ה. ברצון הלב לעלות בדבקות דאין סוף, שיתדבק שם הכל להיות רצון אחד, העליונים ותחתונים."],[1,"ורזא דא יהיה וכו':","וזה סוד \u0003יהיה,\u0004 כמש\"א, \u0003יהיה\u0004 ה' אחד. דהיינו אחד בסוד \u0003יהיה. י'\u0004 דיהיה, שה\"ס חכמה, ליחד ולדבק ב \u0003ה'\u0004 דיהיה, שהיא היכל פנימי, בינה, למקום גניזה של נקודה עליונה שהיא \u0003י'\u0004 חכמה. וזה הוא סוד \u0003הויה אלקינו.\u0004 אלו ב' שמות הם \u0003י\"ה\u0004 חו\"ב, שהוי\"ה היא חכמה, ואלקינו הוא בינה."],[2,"ולאכללא כל שייפין וכו':","ולכלול כל האיברים, שהם ו\"ק דז\"א ומלכות במקום ההוא שיצאו ממנו, שהוא היכל הפנימי, הנ\"ל, שהוא בינה, להשיב הדברים למקומו, אל העיקר והיסוד והשורש שלהם. עד מקום ההוא שהוא שורש הברית, דהיינו אבא."],[3,"ולבתר אינון תרין וכו':","ואחר כך, אלו ב' אותיות אחרות של יהי\"ה ליחד ולדבק \u0003י'\u0004 ב \u0003ה'.\u0004 ה \u0003י',\u0004 הוא סוד ברית קדש, דהיינו יסוד דז\"א, ו \u0003ה'\u0004 זו, הוא היכל ומקום גניזה של ברית קדש שהוא \u0003י',\u0004 דהיינו המלכות, שהיא היכל ליסוד, כמו בינה שהיא היכל לחכמה כנ\"ל. ואע\"פ שהעמדנו שהיסוד הוא \u0003ו'\u0004 שניה של \u0003ו\"ו\u0004 במילואו, ש \u0003ו'\u0004 ראשונה הוא ת\"ת ו \u0003ו'\u0004 השניה הוא יסוד. ולמה נאמר כאן שהוא \u0003י'.\u0004 ומשיב, אבל \u0003י',\u0004 הסוד שלה היא ליחד אותם כאחד. כלומר בסוד היחוד עם המלכות נקרא היסוד \u0003י'.\u0004"],[4,"אחד, ליחדא מתמן וכו':","הכוונה של המלה \u0003אחד,\u0004 הוא, ליחד משם ולמעלה, דהיינו ממלכות ולמעלה, הכל יחד ולהעלות הרצון לקשר את הכל בקשר אחד, להעלות הרצון ביראה ואהבה עד אין סוף. ולא יעזוב רצון העליה לאין סוף, מכל אלו מדרגות ואברים, אלא בכולם יעלה רצונו, אף אחד מהם לא יחסר, להדביקם, ושיהיו כולם קשר אחד, באין סוף."],[5,"ודא הוא יחודא וכו':","וזה הוא היחוד של רב המנונא סבא שלמד מאביו ואביו מרבו עד פיו של אליהו. ויפה הוא והוא יחוד בתקון. ואע\"פ שאנו העמדנו את יחוד הזה בכמה סודות בדרכים אחרים, כל הסודות עולים לאחד. אבל סוד זה מצאתי בספרו ויפה הוא שהוא יחוד בתקון. והרי אנו הערנו דברים ביחוד סוד אחר, (עי' בהקסה\"ז במסורת הזהר אות א') והוא יפה, והיחוד הוא כראוי, וכך הוא. אבל יחוד הזה הוא יחוד בתקון, וזה הוא יחוד דרב המנונא סבא."],[6,"ותו הוה אמר וכו':","ועוד הוא אומר, מי שרוצה לכלול כל סודות היחוד בהמלה \u0003אחד,\u0004 הוא יותר טוב. וע\"כ אנו מאריכים באחד להעלות הרצון להמשיך ממעלה למטה ולהעלות ממטה למעלה, שיהיה הכל אחד. אבל בסוד זה יהי\"ה, שאמרנו סימן הוא לזה."],[7,"והא דתנינן אחד וכו':","וזה שלמדנו שבהמלה \u0003אחד,\u0004 הוא סוד, מעלה ומטה וארבע רוחות העולם. כך הוא. שצריכים ליחד מעלה ומטה כמו שאמרנו, שהם או\"א וזו\"ן. וארבע רוחות העולם, אלו הם הסוד של מרכבה עליונה, שהיא חגת\"ם דז\"א שלמעלה מחזה לכלול הכל יחד, בקשר אחד, ביחוד אחד עד אין סוף. כמו שהעמדנו."],[8,"רזא לאדכרא יציאת וכו':","לאחר כך דהיינו לאחר כוונת שמע, הוא סוד, להזכיר יציאת מצרים. משום שהיתה השכינה בגלות ובזמן שהיא בגלות אין חיבור שיתחברו זה בזה, עולם העליון, שהוא ז\"א, בעולם התחתון, שהיא המלכות, וצריכים להראות חירות של גאולה ההיא, דמצרים, שהיתה בכמה אותות בכמה נסים שעשה הקב\"ה, וגאולה זו צריכה להזכר ולהראות שאע\"פ שהיתה בגלות, עתה יש לה חירות, מן היום שנפתחו הקשרים שבמצרים, ואלו אותות ונסים שנעשו."],[9,"ואצטריך לאחזאה וכו':","וצריכים להראות החירות שלה, של המלכות, משום שנתחברה בבעלה, ז\"א, וכדי להסמיך גאולה, שה\"ס יסוד, לתפלה, שה\"ס מלכות, שיהיה הכל אחד בלי פרוד ולא להראות גרושין, לומר שהמלכות גרושה בגלות מאישה, ז\"א, והסימן שלך, ואשה גרושה מאשה לא יקחו."],[10,"ואי תימא והא וכו':","ואם תאמר, הרי בגלות היא, והיא מגורשת מאישה ז\"א. אינו כן, אלא ודאי היא בגלות לדור עם ישראל, כי בכל מקום שגלו ישראל שכינה עמהם, כדי להגן עליהם, אבל לא נגרשה מז\"א. והרי השכינה לא נראתה בבית ראשון ובבית שני בזמן שחטאו ישראל, ועכ\"ז, לא היה נחשב זה לגלות, מכל שכן לגרושין. אלא עד שלא גלו ישראל, אם חטאו, נסתלקה השכינה למעלה, ולאחר כך, שגלו, לא עלתה למעלה אלא עשתה דירתה עם ישראל. אבל גרושין לא היו מעולם."],[11,"ובגין דא בעי וכו':","ומשום זה צריכים להראות גאולה, שיש בה ארבע גאולות. וסוד כאן, כי בשעה שיצאה השכינה מגלות מצרים, בקשה מהקב\"ה, שיגאול אותה עתה ארבע פעמים, שהם ארבע גאולות, כנגד ארבע גליות, כדי שתהא בת חירות ולא תהיה עוד נגרשת. וע\"כ בשעה ההיא, של גאולת מצרים, עמדה ונגאלה ארבע גאולות ביציאת מצרים ההוא, כלומר עם קבלת המוחין דיציאת מצרים, נגאלה השכינה מכל ד' מלכיות, דהיינו מכל הגליות עד ביאת המשיח, באפן שלא תהיה נחשבת עוד לגרושה מאישה, ז\"א. ועתה שהשכינה צריכה תקון להתחבר בבעלה ז\"א, צריכים להראות גאולת מצרים ההיא, שיש בה ארבע גאולות. ועם התעוררות המוחין דיציאת מצרים, היא מתוקנת להתחבר בבעלה, כי נעשית חירות מכל ד' מלכיות."]],[[0,"","וְאַחַר שֶׁנִּכְלְלוּ זֶה בָּזוֹ בִּכְלָל אֶחָד, אֲזַי צְרִיכִים לְיַחֵד אֶת הָאֵיבָרִים וּלְחַבֵּר שְׁנֵי מִשְׁכָּנוֹת כְּאֶחָד בְּכָל הָאֵיבָרִים בִּרְצוֹן הַלֵּב, לַעֲלוֹת בַּדְּבֵקוּת שֶׁל אֵין סוֹף, לְהִתְדַּבֵּק הַכֹּל שָׁם, לִהְיוֹת רָצוֹן אֶחָד שֶׁל עֶלְיוֹנִים וְתַחְתּוֹנִים."],[1,"","וְסוֹד זֶה יִהְיֶה, כְּמוֹ שֶׁנֶּאֱמַר יִהְיֶה ה' אֶחָד, בְּסוֹד שֶׁל יִהְיֶה. י', לְיַחֵד וּלְהִדָּבֵק בְּה', שֶׁהוּא הֵיכָל הַפְּנִימִי, לִמְקוֹם (מקום) גְּנִיזַת הַנְּקֻדָּה הָעֶלְיוֹנָה הַזּוֹ שֶׁהִיא י'. וְזֶהוּ סוֹד יְהֹוָ\"ה אֱלֹהֵינוּ. אֵלּוּ שְׁתֵּי אוֹתִיּוֹת (שמות) שֶׁהֵם יָ\"הּ."],[2,"","וְלִכְלל כָּל הָאֵיבָרִים בְּאוֹתוֹ מָקוֹם שֶׁיָּצְאוּ מִמֶּנּוּ, שֶׁהוּא הֵיכָל הַפְּנִימִי, לְהַחֲזִיר דְּבָרִים לִמְקוֹמָם לָעִקָּר וִיסוֹד וְשֹׁרֶשׁ שֶׁלָּהֶם, עַד הַמָּקוֹם הַהוּא שֶׁל שֹׁרֶשׁ הַבְּרִית."],[3,"","וּלְבַסּוֹף אֵלּוּ שְׁתֵּי אוֹתִיּוֹת אֲחֵרוֹת לְיַחֵד וּלְהַדְבִּיק י' בְּה'. אוֹת י' הִיא סוֹד הַבְּרִית הַקָּדוֹשׁ. וְאוֹת ה' הַזּוֹ הִיא הֵיכָל, מְקוֹם גְּנִיזָה שֶׁל סוֹד הַבְּרִית הַקָּדוֹשׁ הַזֶּה, שֶׁהוּא י'. וְאַף עַל גַּב שֶׁבֵּאַרְנוּ שֶׁהִיא ו' הַשְּׁנִיָּה. אֲבָל י', הַסּוֹד שֶׁלּוֹ לְיַחֲדָם כְּאֶחָד."],[4,"","אֶחָד - לְיַחֵד מִשָּׁם וָמַעְלָה הַכֹּל כְּאֶחָד, וּלְהַעֲלוֹת רָצוֹן לְהִתְקַשֵּׁר הַכֹּל (ממטה למעלה) בְּקֶשֶׁר אֶחָד. לְהַעֲלוֹת רְצוֹנוֹ בְּיִרְאָה וְאַהֲבָה לְמַעְלָה לְמַעְלָה עַד אֵין סוֹף, וְלֹא יַשְׁאִיר רָצוֹן מִכָּל אוֹתָן דְּרָגוֹת וְאֵיבָרִים, אֶלָּא בְּכֻלָּם יַעֲלֶה רְצוֹנוֹ לְהַשִּׂיגָם, וְשֶׁיִּהְיוּ כֻלָּם קֶשֶׁר אֶחָד בָּאֵין סוֹף."],[5,"","וְזְהִוּ הַיִּחוּד שֶׁל רַב הַמְנוּנָא סָבָא שֶׁלָּמַד מֵאָבִיו, וְאָבִיו מֵרַבּוֹ, עַד פִּיו שֶׁל אֵלִיָּהוּ, וְיָפֶה הוּא, וְהוּא יִחוּד בְּתִקּוּן. וְאַף עַל גַּב שֶׁאָנוּ בֵּאַרְנוּ אֶת זֶה בְּכַמָּה סוֹדוֹת, כָּל הַסּוֹדוֹת עוֹלִים לְאֶחָד. אֲבָל הַסּוֹד הַזֶּה מָצָאנוּ בְּסִפְרוֹ, וְיָפֶה הוּא, וְהוּא יִחוּד בְּתִקּוּן. וַהֲרֵי אָנוּ בְּיִחוּד שֶׁל סוֹד אַחֵר הֵעַרְנוּ דְבָרִים, וְהוּא יָפֶה, וְהַיִּחוּד כָּרָאוּי וְכָךְ הוּא. אֲבָל הַיִּחוּד הַזֶּה יִחוּד בְּתִקּוּן, וְזֶהוּ יִחוּדוֹ שֶׁל רַב הַמְנוּנָא סָבָא."],[6,"","וְעוֹד הָיָה אוֹמֵר, מִי שֶׁרְצוֹנוֹ לְהַכְלִיל אֶת כָּל סוֹדוֹת הַיִּחוּד בְּדָבָר אֶחָד יוֹתֵר יָפֶה. וְלָכֵן אָנוּ מַאֲרִיכִים בְּאֶחָד, לַעֲלוֹת רְצוֹנוֹ מִמַּעְלָה לְמַטָּה, וּמִמַּטָּה לְמַעְלָה, לִהְיוֹת הַכֹּל אֶחָד. אֲבָל בְּסוֹד זֶה יִהְיֶ\"ה, סִימָן (בעלמא) הוּא לָזֶה."],[7,"","וְזְהִ שֶׁשָּׁנִינוּ, אֶחָד (להיות ד') - סוֹד מַעְלָה וּמַטָּה וְאַרְבַּעַת צִדְדֵי הָעוֹלָם, כָּךְ הוּא, לְיַחֵד מַעְלָה וּמַטָּה כְּמוֹ שֶׁנִּתְבָּאֵר, (ולארבעה) וְאַרְבַּעַת צִדְדֵי הָעוֹלָם אֵלּוּ הֵם סוֹד הַמֶּרְכָּבָה הָעֶלְיוֹנָה לְהַכְלִיל הַכֹּל כְּאֶחָד, בְּקֶשֶׁר אֶחָד, בְּיִחוּד אֶחָד עַד אֵין סוֹף, כְּמוֹ שֶׁבֵּאַרְנוּ."],[8,"","הַסּוֹד שֶׁל לְהַזְכִּיר אֶת יְצִיאַת מִצְרַיִם אַחַר כָּךְ, מִשּׁוּם שֶׁשְּׁכִינָה הָיְתָה בַּגָּלוּת, וּבִזְמַן שֶׁהִיא בַּגָּלוּת, אֵינוֹ חִבּוּר לְחַבֵּר זֶה בָּזֶה, הָעוֹלָם הַתַּחְתּוֹן בָּעוֹלָם הָעֶלְיוֹן, וּלְהַרְאוֹת חֵרוּת שֶׁל אוֹתָהּ גְּאֻלָּה שֶׁהָיְתָה בְּכַמָּה אוֹתוֹת, בְּכַמָּה נִסִּים שֶׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא. וְצָרִיךְ לְהַזְכִּיר אוֹתָהּ גְּאֻלָּה, וּלְהַרְאוֹת שֶׁאַף עַל גַּב שֶׁהָיְתָה בַּגָּלוּת - עַכְשָׁו יֵשׁ לָהּ חֵרוּת. מִיּוֹם שֶׁהֻתְּרוּ אוֹתָם הַקְּשָׁרִים בְּמִצְרַיִם, אוֹתָם אוֹתוֹת וְנִסִּים נַעֲשׂוּ."],[9,"","וְצָרִיךָ לְהַרְאוֹת אֶת חֵרוּתָהּ, מִשּׁוּם שֶׁהִתְחַבְּרָה עִם בַּעְלָהּ, וּכְדֵי לְהַסְמִיךְ גְּאֻלָּה לִתְפִלָּה, שֶׁיִּהְיֶה הַכֹּל אֶחָד לְלֹא פֵרוּד, וְלֹא לְהַרְאוֹת גֵּרוּשִׁים. וְסִימָנְךְ - וְאִשָּׁה גְּרוּשָׁה מֵאִישָׁהּ לֹא יִקָּחוּ."],[10,"","וְאִם תֹּאמַר, וַהֲרֵי הִיא בַּגָּלוּת, וַהֲרֵי גֹּרְשָׁה - לֹא כָּךְ. אֶלָּא וַדַּאי שֶׁהִיא בַּגָּלוּת לָדוּר עִם יִשְׂרָאֵל וּלְהָגֵן עֲלֵיהֶם, אֲבָל לֹא גֹרְשָׁה. וַהֲרֵי שְׁכִינָה לֹא נִרְאֲתָה בְּבַיִת רִאשׁוֹן וּבְבַיִת שֵׁנִי. טֶרֶם שֶׁגָּלוּ יִשְׂרָאֵל עָלְתָה לְמַעְלָה, וְאַחַר כָּךְ שָׂמָה אֶת מְדוֹרָהּ עִמָּם, אֲבָל גֵּרוּשִׁים לֹא הָיוּ לְעוֹלָמִים."],[11,"","וּמִשּׁוּם כָּךְ צָרִיךְ לְהַרְאוֹת גְּאֻלָּה שֶׁיֵּשׁ בָּהּ אַרְבַּע גְּאֻלּוֹת. וְסוֹד כָּאן - בְּשָׁעָה שֶׁיָּצְאָה שְׁכִינָה מִגָּלוּת מִצְרַיִם, בִּקְשָׁה מֵהַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיִּפְדֶּה אוֹתָהּ עַכְשָׁו אַרְבַּע פְּעָמים, שֶׁהֵן אַרְבַּע גְּאֻלּוֹת כְּנֶגֶד אַרְבַּע גָּלֻיּוֹת, כְּדֵי שֶׁתִּהְיֶה בַּת חוֹרִין וְלֹא תִהְיֶה מְגֹרֶשֶׁת. וּבְאוֹתָהּ שָׁעָה עָמְדָה וְנִגְאֲלָה אַרְבַּע גְּאֻלּוֹת, בְּאוֹתָהּ יְצִיאַת מִצְרַיִם. וְעַכְשָׁו שֶׁהִצְטָרְכָה בְּתִקּוּנֶיהָ לְהִתְחַבֵּר עִם בַּעְלָהּ, צָרִיךְ לְהַרְאוֹת אוֹתָהּ גְּאֻלַּת מִצְרַיִם שֶׁיֵּשׁ בָּהּ אַרְבַּע גְּאֻלּוֹת."]]],[["וְעַל דָּא אִית לְאַדְכְּרָא בְּהַהִיא גְּאוּלָה, ד' זִמְנִין אֱמֶת. אֱמֶת. אֱמֶת. אֱמֶת. עַד עֶזְרַת אֲבוֹתֵינוּ. דְּדָא הוּא עֶזְרָה וְסֶמֶךְ לְיִשְׂרָאֵל כֻּלְּהוּ. וּמִתַּמָּן וּלְהָלְאָה אַרְבַּע זִמְנִין אַחֲרָנִין, אֱמֶת, אֱמֶת, אֱמֶת, אֱמֶת. לְמֶהֱוֵי אַרְבַּע גְאוּלוֹת אִלֵּין בְּקִיּוּמָא תַּקִּיף, בְּחוֹתָמָא תַּקִּיף דְּגוּשְׁפַּנְקָא דְּמַלְכָּא. ד' גְאוּלוֹת כְּפוּלִין בְּקִיּוּמָא.","וְכֻלְּהוּ בְּהַהִיא יְצִיאַת מִצְרַיִם, דְּאִילּוּ לָא אִשְׁתְּכָחוּ אִינּוּן ד' גְאוּלוֹת בְּהַהִיא יְצִיאַת מִצְרַיִם, כָּל זִמְנָא דְּלִהוֵי גָּלוּתָא, לָא אִתְחַבְּרַת בְּתִקּוּנָהָא לְאִתְיַיחֲדָא שְׁמָא קַדִּישָׁא. וְעַל דָּא אִית לְאַדְכְּרָא גְּאוּלָה דְּמִצְרַיִם תָּדִיר, בְכָל קִדּוּשִׁין דְּקוּדְשָׁא בְּרִיךְ הוּא, בְּרִיךְ שְׁמֵיהּ לְעָלַם וּלְעָלְמֵי עָלְמַיָּיא.","רָזָא דִּקְדוּשָּׁה (דשמיה) הָא אוֹקִימְנָא, דְּהָא בִּקְדוּשָּׁה מִתְקַדְּשֵׁי כֹּלָּא, עֵילָּא וְתַתָּא, וְכָל דַּרְגִּין, וְכָל רְתִיכִין עִלָּאִין וְתַתָּאִין, כֻּלְּהוּ מִתְקַדְּשֵׁי בִּקְדוּשָׁתָא דָּא. וּבִקְדוּשָּׁה דָּא, אוֹקִימְנָא רָזִין עִלָּאִין, לְאִינּוּן מָארֵי רָזִין דְּמִסְתַּכְּלִין בִּקְדוּשָּׁה דְּמָארֵיהוֹן, זַכָּאָה חוּלָקֵיהוֹן.","רָזָא לְמִמְסַר נַפְשָׁא לְמָארֵיהּ, שַׁפִּיר אִיהוּ, דְּקָא (ר' ע\"ב) אֲמַרְתּוּן חַבְרַיָּיא, זַכָּאָה חוּלָקֵיכוֹן, וְזַכָּאִין עֵינַי דְּחָמוּ כַּךְ, דְּזָכֵינָא בְּחַיֵּי, דְּמִתְעָרִין מִלִּין קַדִּישִׁין אִלֵּין בְּהַאי עָלְמָא, (ס\"א בגין דכלהו) וְכֻלְּהוּ כְּתִיבֵי לְעֵילָּא קַמֵי מַלְכָּא קַדִּישָׁא.","פָּתַח וְאָמַר (מלאכי ג׳:ט״ז) אָז נִדְבְּרוּ יִרְאֵי יְיָ' אִישׁ אֶל רֵעֵהוּ וַיַּקְשֵׁב יְיָ' וַיִּשְׁמָע וַיִּכָּתֵב סֵפֶר זִכָּרוֹן לְפָנָיו לְיִרְאֵי יְיָ' וּלְחוֹשְׁבֵי שְׁמוֹ. הַאי קְרָא אִית לְאִסְתַּכְּלָא בֵּיהּ, אָז נִדְבְּרוּ, אָז דִּבְּרוּ מִבָּעֵי לֵיהּ, מַאי נִדְבְּרוּ. אֶלָּא נִדְבְּרוּ לְעֵילָּא, מִכָּל אִינּוּן רְתִיכִין קַדִּישִׁין, וְכָל אִינּוּן חַיָּילִין קַדִּישִׁין.","בְּגִין דְּאִינּוּן מִלִּין קַדִּישִׁין, סַלְּקִין לְעֵילָּא, וְכַמָּה אִינּוּן דִּמְקַדְּמֵי וְנַטְלִין לוֹן קַמֵּי מַלְכָּא קַדִּישָׁא, וּמִתְעַטְּרָן בְּכַמָּה עִטְרִין, בְּאִינּוּן נְהוֹרִין עִלָּאִין, וְכֻלְּהוּ נִדְבְּרוּ מִקַּמֵּי מַלְכָּא עִלָּאָה. מַאן חָמֵי חֶדְוָון, מַאן חָמֵי תּוּשְׁבְּחָן, דְּסַלְּקִין בְכָל אִינּוּן רְקִיעִין, כַּד סַלְּקִין מִלִּין אִלֵּין, וּמַלְכָּא קַדִּישָׁא מִסְתָּכַּל בְּהוּ, וְאִתְעַטָּר בְּהוּ, וְאִינּוּן סַלְּקִין (נ\"א על רישיה דהוו עטרה ונחתין ויתבין וכו') וְיַתְבִין עַל חֵיקֵיהּ, וּמִשְׁתַּעֲשָׁע בְּהוּ, מִתַּמָּן סַלְּקִין עַל רֵישֵׁיהּ, וַהֲווּ עֲטָרָה. וְעַל דָּא אָמְרָה אוֹרַיְיתָא, (משלי ח׳:ל׳) וָאֶהְיֶה שַׁעֲשׁוּעִים יוֹם יוֹם. וְהָיִיתִי לָא כְּתִיב, אֶלָּא וָאֶהְיֶה, בְכָל זְמָן, וּבְכָל עִידָּן, דְּמִלִּין עִלָּאִין סַלְּקִין קַמֵּיהּ.","תְּרֵי זִמְנֵי כְּתִיב יִרְאֵי יְיָ' יִרְאֵי יְיָ'. אֶלָּא יִרְאֵי יְיָ' לְעֵילָּא, יִרְאֵי יְיָ' לְתַתָּא. יִרְאֵי יְיָ' קַיְימִין לְתַתָּא, וְאִינּוּן מִלִּין קַיְימִין בְּדִיּוּקְנֵיהוֹן לְעֵילָּא. וְרָזָא דָּא אַשְׁכַּחְנָא בְּסִפְרָא דְּחֲנוֹךְ, דְּכָל מִלִּין דְּצַדִּיקַיָּיא דִּי בְּאַרְעָא, אִינּוּן מִתְעַטְּרָן, וְקַיְימָן קַמֵּי מַלְכָּא, וּמִשְׁתַּעֲשָׁע בְּהוּ קוּדְשָׁא בְּרִיךְ הוּא. וּלְבָתַר אִינּוּן נַחְתֵּי, וְקַיְימִין קַמֵּיהּ בְּדִיּוּקְנָא דְּהַהוּא צַדִּיק דְּקָאָמַר לוֹן, וְאִשְׁתַּעֲשַׁע קוּדְשָׁא בְּרִיךְ הוּא בְּהַהוּא דִּיּוּקְנָא. וּלְבָתַר אַכְתִּיבוּ בְּסֵפֶר זִכָּרוֹן לְפָנָיו, לְקַיְּימָא קַמֵּיהּ בְּקִיּוּמָא תָּדִיר.","וּלְחוֹשְׁבֵי שְׁמוֹ, מַאי וּלְחוֹשְׁבֵי שְׁמוֹ. הָא אוּקְמוּהָ, (אבל) כָּל אִינּוּן דִּמְחַשְּׁבֵי מִלִּין דְּאוֹרַיְיתָא, לְאַדְבְּקָא לְמָארֵיהוֹן בְּרָזָא דִּשְׁמָא קַדִּישָׁא, בְּגִין לְמִנְדַּע לֵיהּ, וּלְאִתְתַּקְנָא חָכְמָה דִּשְׁמֵיהּ בְּלִבַּיְיהוּ, דִּכְתִּיב וּלְחוֹשְׁבֵי שְׁמוֹ, דְּהוּא רָזָא דִּשְׁמָא קַדִּישָׁא.","כְּתִיב (יחזקאל א׳:כ״ו) וּמִמַּעַל לָרָקִיעַ אֲשֶׁר עַל רֹאשָׁם כְּמַרְאֵה אֶבֶן סַפִּיר דְּמוּת כִּסֵּא, הַאי קְרָא הָא אוּקְמוּהָ. אֲבָל וּמִמַּעַל לָרָקִיעַ, בְּהַהוּא רָקִיעַ לְתַתָּא, כְּמָה דְּאָמַרְתּוּן חַבְרַיָּיא, זַכָּאָה חוּלָקִי, וְזַכָּאָה חוּלָקֵיכוֹן. (בההוא רקיע לתתא) דְּהָא בִּרְקִיעָא דִּלְעֵילָּא, לֵית מַאן דְּאִסְתָּכַּל בֵּיהּ. וּמִלְּעֵילָּא מִנֵּיהּ קַיְּימָא הַהוּא אֶבֶן סַפִּיר, דְּהָא אִתְּעַרְנָא בֵּיהּ בְּרָזָא דְּהַהוּא מַרְגָּלִית טָבָא יַקִּירָא, כְּמָה דְּאוֹקִימְנָא.","דְּמוּת כִּסֵּא, וְלָא כְּתִיב דְּמוּת הַכִּסֵּא. בְּגִין דְּאִית כִּסֵּא, וְאִית כִּסֵּא. הַכִּסֵּא: עִלָּאָה טְמִירָא גְּנִיזָא דְּלָא אִתְגַּלְיָיא, וְלֵית מַאן דְּקַיְּימָא בֵּיהּ לְמִנְדַּע וּלְאִסְתַּכְּלָא. וְעַל דָּא כְּתִיב כִּסֵּא סְתָמָא, דָּא כִּסֵּא דִּלְתַתָּא.","דְּמוּת כְּמַרְאֵה אָדָם, כֵּיוָן דְּאָמַר דְּמוּת, אֲמַאי כְּמַרְאֵה, דְּהָא סַגִּי לֵיהּ דְּמוּת אָדָם. אֶלָּא דְּמוּת אָדָם, דָּא אִיהוּ רָזָא עִלָּאָה, בְּהַהוּא כָּבוֹד עִלָּאָה, דִּיּוּקְנָא דְּאָדָם. אֲבָל הָא דְּאִתּוֹסָף כְּמַרְאֵה, לְאַכְלְלָא אִינּוּן דִּיוּקְנִין דְּמִלִּין דְּחָכְמְתָא, וְאִינּוּן רָזִין דְּחָכְמְתָא דְּסַלְקָן וּמִתְעַטְּרָן לְעֵילָּא, וּלְבָתַר קַיְימִין בְּדִיּוּקְנָא דְּאָדָם בְּהַהוּא דִּיּוּקְנָא דְּצַדִּיקַיָּיא דִּמְעַטְּרִין לוֹן, וּבְכֻלְּהוּ אִשְׁתֲּעְשָׁע קוּדְשָׁא בְּרִיךְ הוּא בְּעִטְרוֹי."],[[0,"ועל דא אית וכו':","וע\"כ יש להזכיר בגאולה ההיא ד' פעמים: אמת אמת אמת אמת, עד עזרת אבותינו. שהם כנגד ד' גאולות, שהם עזרה וסמך לכל ישראל. ומשעזרת אבותינו ולהלאה, יש ארבע פעמים אחרות, אמת אמת אמת אמת, והם נכפלו, כדי שתהיינה ד' גאולות אלו בקיום חזק בחותם חזק של טבעת המלך. וע\"כ ד' גאולות כפולים בקיום."],[1,"וכלהו בההיא יציאת וכו':","וכל ד' הגאולות הן ביציאת מצרים ההיא, כי אלו לא נמצאו אלו ד' גאולות ביציאת מצרים ההיא, לא היתה מתחברת בתקוניה, עם ז\"א, בכל פעם שתהיה גלות, שהשם הקדוש יתיחד. וע\"כ יש להזכיר גאולת מצרים תמיד בכל הקדושות של הקב\"ה. ברוך שמו לעולם ולעולמי עולמים."],[2,"רזא דקדושה וכו':","הסוד של הקדושה, דהיינו קדוש קדוש קדוש שאנו אומרים, הרי העמדנו שבקדושה, מתקדשים כולם למעלה ולמטה, המלאכים וישראל, וכל המדרגות וכל המרכבות עליונות ותחתונות, כולם מתקדשים בקדושה זו, ובקדושה זו העמדנו סודות עליונים לאלו בעלי הסוד המסתכלים בקדושת רבונם, אשרי חלקם."],[3,"רזא לממסר נפשא וכו':","הסוד למסור נפשו לאדונו שאמרתם (לעיל אות קי\"ב) יפה הוא. חברים: אשרי חלקכם, ואשרי עיני שראו כך, שזכיתי בחיי, שיתעוררו דברים קדושים אלו בעולם הזה. וכולם כתובים למעלה לפני המלך הקדוש."],[4,"פתח ואמר וכו':","פו\"א, אז נדברו יראי ה' איש אל רעהו ויקשב ה' וישמע ויכתב ספר זכרון לפניו ליראי ה' ולחשבי שמו. מקרא זה יש להסתכל בו. כתוב, אז נדברו. אז דברו היה צריך לומר מהו נדברו. ומשיב, אלא נדברו למעלה, כל אלו המרכבות הקדושות וכל אלו צבאות הקדושים, נדברו זה אל זה לפני הקב\"ה."],[5,"בגין דאינון מלין וכו':","משום שאלו מלים הקדושות שאמרו עולות למעלה, וכמה הם שמקדימים ונושאים אותן לפני המלך הקדוש, ומתעטרות בכמה עטרות באלו אורות עליונים וכולם נדברו מלפני מלך העליון מי ראה שמחות, ומי ראה תשבחות העולות בכל אלו הרקיעים כשעולות מלים אלה, והמלך הקדוש מסתכל בהם, ומתעטר בהם, והן עולות ויושבות על חיקו, ומשתעשע בהן. משם, מחיקו, עולות על ראשו ונעשו עטרה. וע\"כ אמרה התורה, ואהיה שעשועים יום יום, והייתי לא כתוב, אלא ואהיה, לשון עתיד היינו ובכל זמן בכל עת שמלים העליונות עולות לפניו."],[5,"","פירוש. כי במקרא הקודם לזה כתוב, אמרתם שוא עבוד אלקים ומה בצע כי שמרנו משמרתו וגו'. ועל זה מסיים הכתוב, אז נדברו יראי ה' איש אל רעהו ויקשב ה' וישמע וגו' וחמלתי עליהם כאשר יחמול איש על בנו העובד אותו. ולכאורה הדברים תמוהים, כי באותו עת שאמרו איש אל רעהו דברי כפירה כאלו, דהיינו שוא עבוד אלקים ומה בצע וגו', יאמר עליהם אז נדברו יראי ה' איש אל רעהו ויקשב ה' וישמע, ולא עוד אלא שחביבים כל כך, עד שנכתבים ספר זכרון לפניו ליראי ה' ולחשבי שמו."],[5,"","אמנם הכתוב מדבר באותם הצדיקים שזכו לתשובה מאהבה, אשר אז הזדונות נהפכו לזכיות, וכל שעבירה היתה יותר גדולה נהפכה לזכות יותר גדולה. ונמצא בעת שהצדיקים הללו היו בבחינת תוהים על הראשונות, שאמרו, שוא עבוד אלקים וגו', שאין עוד עון חמור יותר מזה, הרי דברי כפירה האלו נהפכו עתה, מכח התשובה מאהבה שעשו, לזכיות גדולות ונחשבים עתה כמו שדברו אז יראי אלקים איש אל רעהו דברי כפירה האלו, שהרי נהפכו לזכיות, ומכח ההפיכה הגדולה הזו נעשו שעשועים גדולים לפני הקב\"ה."],[5,"","וז\"ש (באות תל\"ו) \u0003מאי נדברו. אלא נדברו לעילא, מכל אינון רתיכין קדישין\u0004 וכו' כי אותן המלים שאמרו בעת שהיו רשעים, שוא עבוד אלקים וגו' נתעלו למעלה על ידי המלאכים והמרכבות שהם ידעו שאותם הרשעים יעשו תשובה מאהבה, וסופם של דברים אלו יהיו לזכיות ולאורות גדולים ולשעשועים לפני הקב\"ה. וז\"ש \u0003בגין דאינון מלין קדישין,\u0004 שהם שוא עבוד וגו' שלאחר תשובה מאהבה נעשו קדושים, \u0003סלקין לעילא,\u0004 ע\"י המלאכים תיכף בעת שאמרו אותן, \u0003וכמה אינון דמקדמי ונטלין לון קמי מלכא קדישא\u0004 וכו'. שעוד מטרם שעשו תשובה מאהבה מקדימים המלאכים ומביאים המלים לפני המלך הקדוש, משום שלמעלה כבר ידוע שיעשו תשובה מאהבה על כל מלה ומלה שאמרו, וכל מלה תתהפך לזכות ולאור גדול. והשעשועים גדולים מאד, וז\"ש, \u0003מאן חמי חדוון מאן חמי תושבחן\u0004 וכו'. וז\"ש \u0003ויתבין על חיקיה,\u0004 כי בחינת ההסתר של הקב\"ה נבחן לחיקו, וכיון שעוד לא עשו תשובה מאהבה, הרי המלים שאמרו, יושבות על חיקו של הקב\"ה, דהיינו בבחינת ההסתר פנים, אמנם כיון שידוע לפניו ית' שיעשו תשובה מאהבה, ע\"כ, \u0003ומשתעשע בהו מתמן,\u0004 מן בחינת חיקו, כי אחר שיעשו תשובה, \u0003סלקין על רישיה והוו עטרה.\u0004"],[6,"תרי זמני כתיב וכו':","שתי פעמים כתוב, יראי ה' יראי ה', דהיינו אז נדברו \u0003יראי ה',\u0004 ויכתב ספר זכרון לפניו \u0003ליראי ה'\u0004 וגו'. אלא, הפירוש הוא, שיראי ה' למעלה, היינו בעת שעושים תשובה מאהבה המה עומדים למעלה לפני הקב\"ה. יראי ה' למטה, דהיינו שאח\"כ יורדים למקומם לארץ למטה. ואפילו יראי ה' כבר הם למטה במקומם, אלה המלים עומדות בצורתן למעלה. וסוד זה מצאתי בספרו של חנוך, שכל המלים, שהצדיקים שבארץ מתעטרים בהן ועומדים לפני המלך, דהיינו בעת שעושים תשובה מאהבה, שאז מתעטרים בזדונות שנעשו לזכיות, כנ\"ל, ועומדות בעצמן למעלה לפני המלך והקב\"ה משתעשע בהן. ואחר זה הצדיקים יורדים, והמלים נשארות עומדות לפניו באותו צורה של ההפיכה מזדונות לזכיות, שהצדיק אמר אותם, והקב\"ה משתעשע בצורה ההיא. ואח\"כ נכתבו בספר זכרון לפניו, שיעמדו לפניו תמיד בקיום."],[7,"ולחשבי שמו:","שואל, מהו ולחשבי שמו. ומשיב, הרי העמידוהו, שכל אלו המחשיבים דברי תורה להדביק לאדונם בסוד השם הקדוש, כדי לדעת אותו, שיתתקן החכמה של שמו בלבם, עליהם כתוב ולחשבי שמו. שהוא סוד השם הקדוש."],[8,"כתיב וממעל לרקיע וגו':","כתוב, וממעל לרקיע אשר על ראשם כמראה אבן ספיר דמות כסא. מקרא זה העמידוהו. אבל \u0003וממעל לרקיע,\u0004 היינו ברקיע ההוא שלמטה, שמתחת המלכות כמו שאמרתם חברים (לעיל אות שכ\"א) שאמרו בשם ר\"ש, אשרי חלקי, ואשרי חלקכם. כי ברקיע של מעלה, שהוא בינה, אין מי שיסתכל בו. אבל על רקיע התחתון שבמלכות נאמר עליה, וראית את אחורי, כמ\"ש שם, ומלמעלה מרקיע הזה עומד אבן ספיר ההוא, שהערנו בו, שהיא המלכות, בסוד שהיא מרגלית טובה ויקרה, כמו שהעמדתי."],[9,"דמות כסא:","ולא כתוב דמות הכסא. משום שיש כסא ויש כסא. \u0003הכסא,\u0004 היא עליון, צפון וגנוז שאינו מתגלה, ואין מי שיעמוד בו לדעת ולהסתכל. שהוא בינה. וע\"כ כתוב כאן \u0003כסא\u0004 סתם בלי ה' הידיעה, שזהו כסא שלמטה דהיינו המלכות."],[10,"דמות כמראה אדם:","שואל כיון שאמר, דמות למה נאמר עוד, כמראה שהיה די שיאמר, דמות אדם. ומשיב, אלא \u0003דמות אדם,\u0004 זה הוא סוד עליון בכבוד עליון ההוא, שהוא ז\"א בהויה דאלפין שבגימטריא \u0003אדם,\u0004 שהוא צורת אדם היושב על הכסא שהוא מלכות, וזה שנתוסף, \u0003כמראה,\u0004 הוא לכלול אלו צורות שבדברי החכמה, המכונות ראיה או מראה. שהחכמה נקראת כך. והם סודות החכמה העולות ומתעטרות למעלה בז\"א, ואח\"כ הם עומדים בצורת אדם, דהיינו בצורה ההיא שהצדיקים מעטרים אותם. ובכולם משתעשע הקב\"ה בעטרותיו."]],[[0,"","וְעַל זֶה יֵשׁ לְהַזְכִּיר בְּאוֹתָהּ גְּאֻלָּה אַרְבַּע פְּעָמִים אֱמֶת, אֱמֶת, אֱמֶת, אֱמֶת, עַד עֶזְרַת אֲבוֹתֵינוּ, שֶׁזּוֹהִי עֶזְרָה וְסֶמֶךְ לְיִשְׂרָאֵל כֻּלָּם. וּמִשָּׁם וָהָלְאָה אַרְבַּע פְּעָמִים אֲחֵרוֹת אֱמֶת, אֱמֶת, אֱמֶת, אֱמֶת, לִהְיוֹת אַרְבַּע הַגְּאֻלּוֹת הַלָּלוּ בְּקִיּוּם חָזָק בְּחוֹתָם חָזָק שֶׁל טַבַּעַת הַמֶּלֶךְ, אַרְבַּע גְּאֻלּוֹת כְּפוּלוֹת בְּקִיּוּם."],[1,"","וְכֻלָּן בְּאוֹתָהּ יְצִיאַת מִצְרַיִם, שֶׁאִלּוּ לֹא נִמְצְאוּ אוֹתָן אַרְבַּע גְּאֻלּוֹת בְּאוֹתָהּ יְצִיאַת מִצְרַיִם, כָּל פַּעַם שֶׁתִּהְיֶה גָלוּת, לֹא מִתְחַבֶּרֶת בְּתִקּוּנֶיהָ לְהִתְיַחֵד בַּשֵּׁם הַקָּדוֹשׁ, וְלָכֵן צָרִיךְ תָּמִיד לְהַזְכִּיר אֶת גְּאֻלַּת מִצְרַיִם בְּכָל הַקְּדֻשּׁוֹת שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא בָּרוּךְ שְׁמוֹ לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים."],[2,"","סוֹד הַקְּדֻשָּׁה (של שמו) הֲרֵי בֵּאַרְנוּ, שֶׁהֲרֵי בִּקְדֻשָּׁה הַכֹּל מִתְקַדְּשִׁים - מַעְלָה וּמַטָּה, וְכָל הַדְּרָגוֹת, וְכָל הַמֶּרְכָּבוֹת עֶלְיוֹנוֹת וְתַחְתּוֹנוֹת, כֻּלָּם מִתְקַדְּשִׁים בַּקְּדֻשָּׁה הַזּוֹ. וּבַקְּדֻשָּׁה הַזּוֹ בֵּאַרְנוּ סוֹדוֹת עֶלְיוֹנִים לְאוֹתָם בַּעֲלֵי סוֹדוֹת שֶׁמִּתְבּוֹנְנִים בִּקְדֻשַּׁת רִבּוֹנָם, אַשְׁרֵי חֶלְקָם."],[3,"","הַסּוֹד לִמְסֹר הַנֶּפֶשׁ לַאֲדוֹנוֹ הוּא יָפֶה שֶׁאֲמַרְתֶּם הַחֲבֵרִים. אַשְׁרֵי חֶלְקְכֶם, וְאַשְׁרֵי עֵינַי שֶׁרָאוּ כָּךְ, שֶׁרָאִיתִי בְּחַיַּי שֶׁמְּעוֹרְרִים דְּבָרִים קְדוֹשִׁים אֵלּוּ בָּעוֹלָם הַזֶּה, (משום שכלם) וְכֻלָּם כְתוּבִים לְמַעְלָה לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ."],[4,"","פָּתַח וְאָמַר, (מלאכי ג) אָז נִדְבְּרוּ יִרְאֵי ה' אִישׁ אֶל רֵעֵהוּ וַיַּקְשֵׁב ה' וַיִּשְׁמָע וַיִּכָּתֵב סֵפֶר זִכָּרוֹן לְפָנָיו לְיִרְאֵי ה' וּלְחֹשְׁבֵי שְׁמוֹ. בְּפָסוּק זֶה יֵשׁ לְהִתְבּוֹנֵן, אָז נִדְבְּרוּ?! אָז דִּבְּרוּ הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה נִדְבְּרוּ? אֶלָּא נִדְבְּרוּ לְמַעְלָה מִכָּל אוֹתָן מֶרְכָּבוֹת קְדוֹשׁוֹת וְכָל אוֹתָם חֲיָלוֹת קְדוֹשִׁים."],[5,"","מִשּׁוּם שֶׁאוֹתָם דְּבָרִים קְדוֹשִׁים עוֹלִים לְמַעְלָה, וְכַמָּה הֵם שֶׁמַּקְדִּימִים וְנוֹטְלִים אוֹתָם לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, וּמִתְעַטְּרִים בְּכַמָּה עֲטָרוֹת בְּאוֹתָם אוֹרוֹת עֶלְיוֹנִים, וְכֻלָּם נִדְבְּרוּ מִלִּפְנֵי הַמֶּלֶךְ הָעֶלְיוֹן. מִי רָאָה אֶת הַשְּׂמָחוֹת? מִי רָאָה אֶת הַתִּשְׁבָּחוֹת שֶׁעוֹלוֹת בְּכָל אוֹתָם רְקִיעִים, כְּשֶׁהַדְּבָרִים הַלָּלוּ עוֹלִים (לפני המלך הקדוש), וְהַמֶּלֶךְ הַקָּדוֹשׁ מִסְתַּכֵּל בָּהֶם וּמִתְעַטֵּר בָּהֶם, וְהֵם עוֹלִים (על ראשו, והיו עטרה ויורדים ויושבים) וְיוֹשְׁבִים עַל חֵיקוֹ וּמִשְׁתַּעֲשֵׁעַ בָּהֶם, וּמִשָּׁם עוֹלִים עַל רֹאשׁוֹ וְנִהְיִים עֲטָרָה. וְעַל זֶה אָמְרָה תוֹרָה, (משלי ח) וָאֶהְיֶה שַׁעֲשׁוּעִים יוֹם יוֹם. לֹא כָתוּב וְהָיִיתִי, אֶלָּא וָאֶהְיֶה, בְּכָל זְמַן וּבְכָל עֵת שֶׁדְּבָרִים עֶלְיוֹנִים עוֹלִים לְפָנָיו."],[6,"","פַּעָמַיִם כָּתוּב יִרְאֵי ה', יִרְאֵי ה'. אֶלָּא יִרְאֵי ה' לְמַעְלָה, יִרְאֵי ה' לְמַטָּה. יִרְאֵי ה' עוֹמְדִים לְמַטָּה, וְאוֹתָם דְּבָרִים עוֹמְדִים בִּדְיוֹקְנֵיהֶם לְמַעְלָה. וְסוֹד זֶה מָצָאנוּ בְּסִפְרוֹ שֶׁל חֲנוֹךְ, שֶׁכָּל דִּבְרֵי הַצַּדִּיקִים שֶׁבָּאָרֶץ הֵם מִתְעַטְּרִים וְעוֹמְדִים לִפְנֵי הַמֶּלֶךְ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מִשְׁתַּעֲשֵׁעַ בָּהֶם. וְאַחַר כָּךְ הֵם יוֹרְדִים וְעוֹמְדִים לְפָנָיו בִּדְיוֹקַן אוֹתוֹ הַצַּדִּיק שֶׁאָמַר אוֹתָם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מִשְׁתַּעֲשֵׁעַ בְּאוֹתוֹ דְיוֹקָן, וְאַחַר כָּךְ נִכְתָּבִים בְּסֵפֶר זִכָּרוֹן לְפָנָיו, לַעֲמֹד לְפָנָיו בְּקִיּוּם תְּמִידִי."],[7,"","וּלְחֹשְׁבֵי שְׁמוֹ, מַה זֶּה וּלְחֹשְׁבֵי שְׁמוֹ? הֲרֵי פֵּרְשׁוּהָ, (אבל) כָּל אוֹתָם שֶׁמְּחַשְּׁבִים דִּבְרֵי תוֹרָה לְהַשִּׂיג אֶת אֲדוֹנָם בְּסוֹד הַשֵּׁם הַקָּדוֹשׁ כְּדֵי לְהַכִּיר אוֹתוֹ וּלְהַתְקִין אֶת חָכְמַת שְׁמוֹ בְּלִבָּם, שֶׁכָּתוּב וּלְחֹשְׁבֵי שְׁמוֹ, שֶׁהוּא סוֹד הַשֵּׁם הַקָּדוֹשׁ."],[8,"","כָּתוּב (יחזקאל א) וּמִמַּעַל לָרָקִיעַ אֲשֶׁר עַל רֹאשָׁם כְּמַרְאֵה אֶבֶן סַפִּיר דְּמוּת כִּסֵּא. פָּסוּק זֶה הֲרֵי פֵּרְשׁוּהוּ. אֲבָל וּמִמַּעַל לָרָקִיעַ, בְּאוֹתוֹ רָקִיעַ לְמַטָּה, כְּמוֹ שֶׁאֲמַרְתֶּם הַחֲבֵרִים. אַשְׁרֵי חֶלְקִי וְאַשְׁרֵי חֶלְקְכֶם (באותו רקיע למעלה). שֶׁהֲרֵי בָּרָקִיעַ שֶׁלְּמַעְלָה אֵין מִי שֶׁמִּתְבּוֹנֵן בּוֹ, וּמִלְמַעְלָה מִמֶּנּוּ עוֹמֵד אוֹתוֹ אֶבֶן סַפִּיר, שֶׁהֲרֵי הִתְעוֹרַרְנוּ בוֹ בְּסוֹד שֶׁל אוֹתָהּ מַרְגָּלִית טוֹבָה נִכְבָּדָה, כְּמוֹ שֶׁבֵּאַרְנוּ."],[9,"","דְּמוּת כִּסֵּא, וְלֹא כָתוּב דְּמוּת הַכִּסֵּא, מִשּׁוּם שֶׁיֵּשׁ כִּסֵּא וְיֵשׁ כִּסֵּא. הַכִּסֵּא - הָעֶלְיוֹן הַטָּמִיר וְהַגָּנוּז שֶׁלֹּא הִתְגַּלָּה וְאֵין מִי שֶׁעוֹמֵד בּוֹ לָדַעַת וּלְהִתְבּוֹנֵן. וְלָכֵן כָּתוּב כִּסֵּא סְתָם, זֶהוּ הַכִּסֵּא שֶׁלְּמַטָּה."],[10,"","דְּמוּת כְּמַרְאֵה אָדָם. כֵּיוָן שֶׁאָמַר דְּמוּת, אָז לָמָּה כְּמַרְאֵה, שֶׁהֲרֵי דַּי לוֹ דְּמוּת אָדָם? אֶלָּא דְּמוּת אָדָם זֶהוּ סוֹד עֶלְיוֹן בְּאוֹתוֹ כָּבוֹד עֶלְיוֹן, דְּיוֹקָן שֶׁל אָדָם. אֲבָל זֶה שֶׁנּוֹסָף כְּמַרְאֵה - לְהַכְלִיל אוֹתָם דְּיוֹקְנָאוֹת שֶׁל דִּבְרֵי חָכְמָה וְאוֹתָם סוֹדוֹת שֶׁל חָכְמָה שֶׁעוֹלוֹת וּמִתְעַטְּרוֹת לְמַעְלָה, וְאַחַר כָּךְ עוֹמְדוֹת בִּדְיוֹקָן שֶׁל אָדָם בְּאוֹתוֹ הַדְּיוֹקָן שֶׁל הַצַּדִּיקִים שֶׁמְּעַטְּרִים אוֹתָם, וּבְכֻלָּם מִשְׁתַּעֲשֵׁעַ הַקָּדוֹשׁ בָּרוּךְ הוּא בְּעַטְרוֹתָיו."]]],[["וְאַתּוּן חַבְרַיָּיא, הָא קוּדְשָׁא בְּרִיךְ הוּא אִשְׁתֲּעְשָׁע הַשְׁתָּא, בְּאִינּוּן מִלִּין דְּקָא אַמְרִיתּוּ, מִתְעַטְּרָן בְּהַהוּא אוֹרְחָא. וְהָא קְיַּימְתּוּן קַמֵּי מָארֵיכוֹן בְּדִיּוּקְנַיְיכוּ קַדִּישִׁין, דְּהָא אֲנָא בְּשַׁעֲתָא דַּחֲמֵינָא לְכוּ, וְאִסְתַּכַּלְנָא בְּדִיּוּקְנַיְיכוּ, חֲמֵינָא בְּכוּ דְּאַתּוּן רְשִׁימִין בְּרָזָא דְּאָדָם, וְיָדַעְנָא דְּהָא דִּיּוּקְנָא דִּילְכוֹן אִתְעַתְּדָא לְעֵילָּא. וְהָכִי אִזְדַמְּנָן צַדִּיקַיָּיא לְזִמְנָא דְּאָתֵי, לְאִשְׁתְּמוֹדְעָא לְעֵינֵיהוֹן דְּכֹלָּא, וּלְאַחֲזָאָה פַּרְצוּפָא קַדִּישָׁא לְקָמֵי כָּל עָלְמָא, הֲדָא הוּא דִכְתִיב, (ישעיהו ס״א:ט׳) כָּל רוֹאֵיהֶם יַכִּירוּם כִּי הֵם זֶרַע בֵּרַךְ יְיָ'.","אַדְּהָכִי חָמָא לְרִבִּי יוֹסֵי, דְּהֲוָה מְהַרְהֵר בְּמִלֵּי דְּעָלְמָא. אָמַר לֵיהּ, יוֹסֵי קוּם אַשְׁלִים דִּיּוּקְנָךְ, דְּאָת חַד חָסֵר בָּךְ. קָם רִבִּי יוֹסֵי וְחַדֵּי בְּמִלִּין דְּאוֹרַיְיתָא, וְקָם קַמֵּיהּ, אִסְתָּכַּל בֵּיהּ רַבִּי שִׁמְעוֹן, אֲמַר לֵיהּ, רִבִּי יוֹסֵי, הַשְׁתָּא אַנְתְּ שְׁלִים קַמֵּי עַתִּיק יוֹמִין, וְדִיּוּקְנָךְ שְׁלִים.","פָּתַח וְאָמַר, (שמות כ״ח:י״ד) וַיַּעַשׂ אֶת צִיץ נְזֶר הַקֹּדֶשׁ זָהָב טָהוֹר וְגוֹ'. אֲמַאי אִקְרֵי צִיץ. אִסְתַּכְּלוּתָא לְאִסְתַּכְּלָא בֵּיהּ. וּבְגִין דְּהֲוָה קַיְּימָא עַל אִסְתַּכְּלוּתָא דְּבַר נָשׁ, אִקְרֵי צִיץ. וְכָל מַאן דְּאִסְתָּכַּל בֵּיהּ בְּהַהוּא צִיץ אִשְׁתְּמוֹדְעָא בֵּיהּ.","בַּצִיץ הֲווֹ אַתְוָון דִּשְׁמָא קַדִּישָׁא גְּלִיפָן בְּגִלּוּפָא, וּמְחַקְּקָן בֵּיהּ. וְאִי זַכָּאָה הֲוָה הַהוּא דְּקַיְּימָא קַמֵּיהּ, אִינּוּן אַתְוָון דִּמְחַקְּקָן בֵּיהּ גּוֹ דַּהֲבָא, הֲווֹ בַּלְטִין מִתַּתָּא לְעֵילָּא, וְסַלְּקִין מֵהַהוּא גְּלִיפוּ בִּנְהִירוּ, וַהֲווּ נָהֲרִין בְּאַנְפִּין דְּהַהוּא בַּר נָשׁ.","נָצִיץ נְצִיצוּ בֵּיהּ, וְלָא נַצְצִין. בְּשַׁעֲתָא קַדְמִיתָא דְּאִסְתָּכַּל כַּהֲנָא בֵּיהּ, הֲוָה חָמֵי נְהִירוּ דְּאַתְוָון כֻּלְּהוּ בְּאַנְפִּין. וְכַד הֲוָה מִסְתַּכְלָּא לְעַיְינָא בֵּיהּ, לָא הֲוָה חָמֵי מִדִי, אֶלָּא נְהִירוּ דְּאַנְפּוֹי דְּנָהִיר, כְּאִילּוּ נִיצוֹצָא דְּדַהֲבָא הֲוָה נָצִיץ בֵּיהּ, בַּר דְּכַהֲנָא הֲוָה יָדַע חֵיזוּ דְּאִסְתַּכְּלוּתָא קַדְמָאָה, דְּהֲוָה חָמֵי לְפוּם שַׁעֲתָא, דְּהָא רְעוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא הֲוָה בֵּיהּ בְּהַהוּא בַּר נָשׁ, וְיָדַע דְּאִיהוּ זַמִּין לְעָלְמָא דְּאָתֵי, בְּגִין דְּחֵיזוּ דָּא נָהֲרִין עָלֵיהּ מִלְּעֵילָּא, וְקוּדְשָׁא בְּרִיךְ הוּא הֲוָה אִתְרְעֵי בֵּיהּ. וְכַד מִסְתַּכְּלִין בֵּיהּ לָא חָמָאן מִדִי, בְּגִין דְּחֵיזוּ דִּלְעֵילָּא לָא אִתְגַּלְיָיא אֶלָּא לְפוּם שַׁעֲתָא.","וְאִי קַיְּימָא בַּר נָשׁ קַמֵּי הַהוּא צִיץ, וְאַנְפּוֹי לָא אִתְחַזְיָין לְפוּם שַׁעֲתָא, חֵיזוּ קַדִּישָׁא. הֲוָה יָדַע כַּהֲנָא דְּהָא אִיהוּ תַּקִּיף מִצְחָא, וּבָעֵי לְכַפְּרָא עָלֵיהּ, וּלְמִבָּעֵי עֲלוֹי רַחֲמִין.","(שמות מ) וַיַּעַשׂ אֶת צִיץ נֶזֶר הַקֹּדֶשׁ. רִבִּי יְהוּדָה פָּתַח קְרָא בְּרוּת, (רות ב׳:ט׳) עֵינַיִךְ בַּשָּׂדֶה אֲשֶׁר יִקְצֹרוּן וְגוֹ'. הַאי קְרָא אִית לְאִסְתַּכְּלָא בֵּיהּ, אֲמַאי אִצְטְרִיךְ הָכָא לְמִכְתַּב. אֲמַר לֵיהּ רִבִּי יִצְחָק, אִי הָכִי כַּמָּה קְרָאִין אִינּוּן בְּאוֹרַיְיתָא דְּאִתְחֲזִיאוּ דְּלָא אִצְטְרִיכוּ לְמִכְתַּב, וְחָמֵינָן דְּכֻלְּהוּ רָזִין עִלָּאִין. אָמַר רִבִּי יְהוּדָה, הַאי קְרָא מַאן דְּחָמֵי וְלָא אִסְתָּכַּל בֵּיהּ, כְּמָה דְּלָא טָעִים תַּבְשִׁילָא דָּמֵי.","אֶלָּא רָזָא הָכָא, וּבְרוּחַ קוּדְשָׁא אִתְּמַר, בְּגִין דְּחָמָא בֹּעַז דַּיָּינָא דְּיִשְׂרָאֵל, עַנְוָותָנוּתָא דְּהַהִיא צַדֶּקֶת, דְּלָא מְסַלְּקָא עֵינָא לְמֵחמֵי בַּאֲתָר אַחֲרָא, אֶלָּא לְקַמָּהּ. וְחָמָאת כָּל מַה דְּחָמָאת, בְּעֵינָא טָבָא, וְתּוּקְפָּא דְּמִצְחָא לָא הֲוָה בָּה, שִׁבַּח עֵינָהָא.","בְּגִין דְּאִית עַיְינִין דִּבְגִינֵיהוֹן לָא שַׁלְטָא בִּרְכָתָא בְּהַהוּא אֲתָר, וְאִיהוּ עֵינָא טָבָא חָמָא בָּה, דְּכָל מַה דְּאִסְתַּכְּלַת הֲוָה בְּעֵינָא טָבָא. וְתוּ, דְּחָמָא, דְּהֲוָה אַצְלַח בִּידָהָא, כָּל מַה דַּהֲוַות לַקְטָא, אִתּוֹסַף בְּחַקְלָא. וּבֹעַז אִסְתָּכַּל דְּרוּחָא קַדִּישָׁא שַׁרְיָיא עָלָהּ, כְּדֵין פָּתַח וְאָמַר, עֵינַיִךְ בַּשָּׂדֶה אֲשֶׁר יִקְצֹרוּן וְגוֹ'. אִי תֵּימָא בְּגִין אִינּוּן לַקְטִין כָל אִינּוּן אַחֲרָנִין, הֵיךְ אָמַר דְּתֵּהַךְ אֲבַתְרַיְיהוּ, לָא אִצְטְרִיךְ לְמִכְתַּב אֶלָּא וְלָקַטְתְּ אַחֲרֵיהֶן, מַאי וְהָלַכְתְּ אַחֲרֵיהֶן, אֶלָּא בְּגִין עֵינָהָא קָאָמַר. עֵינָהָא דַּהֲווֹ גַּרְמִין (נ\"א ברכאן סגיאין, ועל דא וכו'), בִּרְכָתָא לַקְטִין סַגִּיאִין וְעַל דָּא וְהָלַכְתְּ אַחֲרֵיהֶן, בָּתַר עֵינַיִךְ. כָּל שְׁאַר בְּנִי עָלְמָא לֵית לְהוּ רְשׁוּ לְמֵיהַךְ בָּתַר עֵינוֹי. וְאַנְתְּ לְבָתַר עֵינַיִךְ, דְּעֵינַיִךְ גַּרְמִין בִּרְכָאן סַגִּיאִין."],[[0,"ואתון חבריא הא וכו':","ואתם חברים, הרי הקב\"ה משתעשע עתה באלו הדברים שאמרתם המתעטרות בדרך ההוא. והרי קימתם צורת אדם לפני אדונכם בצורותיכם הקדושות, כי אני בשעה שראיתי אתכם והסתכלתי בצורתכם, ראיתי בכם שאתם רשומים בסוד אדם, וידעתי שהצורה שלכם מזומנת למעלה. וכך עתידים הצדיקים לעתיד לבא להיות ניכר לעיני כל ולהראות צורת פניהם הקדושה לפני כל העולם. ז\"ש, כל רואיהם יכירום כי הם זרע ברך ה'."],[1,"אדהכי חמא לר' יוסי וכו':","בתוך כך ראה את ר' יוסי, שהיה מהרהר בדברי העולם. אמר לו יוסי, קום השלם צורתך, כי אות אחת חסרה בך. שמשום שהרהר במילי דעלמא, קראו יוסי ולא רבי יוסי. קם ר' יוסי ושמח בדברי תורה וקם לפניו. הסתכל בו ר' שמעון, אמר לו, רבי יוסי, עתה, שלם אתה לפני עתיק יומין, וצורתך שלמה."],[2,"פתח ואמר ויעש וגו':","פו\"א, ויעש את ציץ נזר הקדש זהב טהור וגו', שואל, למה נקרא ציץ. ומשיב, משום שהוא הסתכלות להסתכל בו. ומשום שהוא נמצא להסתכלות בן אדם, נקרא ציץ. וכל מי שמסתכל בו בציץ ההוא, הוא ניכר בו. אם הוא צדיק או לא."],[3,"בציץ הוו אתוון וכו':","ומפרש דבריו. בציץ היו אותיות השם הקדוש מפותחות בפתוח וחקוקות בו. ואם צדיק הוא מי שעומד לפניו אלו האותיות החקוקות תוך הזהב, היו הארתן בולטות ועולות ממטה למעלה מחקיקה ההיא, והיו מאירות בפניו של אדם ההוא."],[4,"נציץ נציצו ביה וכו':","פעם היתה נוצצת ההתנוצצות בו, ופעם לא היו מתנוצצות. ומפרש. בפעם הראשונה שהכהן הסתכל בו, היה רואה הארות האותיות כולן בפנים. וכשהיה מסתכל לעיין בו, לא היה רואה כלום, אלא הארת פניו היה מאיר, בשיעור, כמו שניצוץ היוצא מן זהב התנוצץ בו, ולא יותר. רק הכהן היה יודע המראה של הסתכלות הראשון, שהיה רואה בשעתו, וכן כל אדם. שהוא משום שרצון הקב\"ה היה באדם ההוא המסתכל בציץ, וידע שהוא מזומן לעולם הבא, כי מראה הזו שהאירה מאותיות הציץ, האירו עליו מלמעלה, שהקב\"ה היה רוצה בו. וכאשר מסתכלים בו לאחר כך לעיין בו לא ראו כלום. משום שהמראה שלמעלה אינו מתגלה אלא לפי שעה."],[5,"ואי קיימא בר נש וכו':","ואם אדם עומד לפני ציץ ההוא ופניו אינם מראים, גם לפי שעה, המראה הקדוש. אז ידע הכהן שהוא עז מצח, וצריך לכפר עליו, ולבקש עליו רחמים."],[6,"ויעש את ציץ נזר הקדש:","ר' יהודה פתח קרא ברות. שכתוב, עיניך בשדה אשר יקצרון וגו'. מקרא זה יש להסתכל בו למה צריך כאן לכתוב את זה. אמר לו ר' יצחק אם כן, כמה מקראות הם בתורה, שנראה שאינם צריכים להכתב, ואנו רואים שכולם הם סודות עליונים. אמר ר' יהודה מקרא זה מי שרואה אותו ואינו מסתכל בו דומה למי שלא טעם תבשיל מעולם."],[7,"אלא רזא הכא וכו':","ומשיב, אלא יש כאן סוד. וברוח הקדש נאמר זה. משום שראה בעז, הדיין של ישראל את העניוות של צדקת ההיא, שאינה מגבהת עיניה לראות במקום אחר אלא מול פניה, וראה כל מה שראתה בעין טובה, ולא היתה בה עזות מצח, שיבח עיניה."],[8,"בגין דאית עיינין וכו':","משום שיש עינים שבשבילם אינה שולטת ברכה במקום ההוא. ובעז, עין טובה ראה בה, שכל מה שהסתכלה היתה בעין טובה, ועוד שראה שהיתה הצלחה בידיה, שכל מה שהיתה לוקטת, נתוסף בשדה. ובעז הסתכל שרוח הקדש שורה עליה, אז פתח ואמר, עיניך בשדה אשר יקצרון וגו'. אם תאמר, בשביל שהיו לוקטים אלו האחרים, ע\"כ אמר לרות עיניך בשדה אשר יקצרון והלכת אחריהן. א\"כ איך אמר, שתלך אחריהן, ולא היה צריך לכתוב אלא, ולקטת אחריהן. מהו והלכת אחריהן. אלא בשביל עיניה אמר, והלכת אחריהן, כי עיניה היו גורמות ברכות מרובות, וע\"כ והלכת אחריהן, אחר עיניך. כל בני העולם אין להם רשות ללכת אחרי עיניהם, ואת, תלכי אחרי עיניך כי עיניך גורמות ברכות מרובות."]],[[0,"","וְאַתֶּם הַחֲבֵרִים, הֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא מִשְׁתַּעֲשֵׁעַ כָּעֵת בְּאוֹתָם דְּבָרִים שֶׁאֲמַרְתֶּם, מִתְעַטְּרִים בְּאוֹתָהּ דֶּרֶךְ. וַהֲרֵי עֲמַדְתֶּם לִפְנֵי רִבּוֹנְכֶם בִּדְיוֹקְנֵיכֶם הַקְדוֹשִׁים, שֶׁהֲרֵי אֲנִי, בְּשָׁעָה שֶׁרָאִיתִי אֶתְכֶם וְהִסְתַּכַּלְתִּי בִּדְיוֹקְנֵיכֶם, רָאִיתִי בָכֶם שֶׁאַתֶּם רְשׁוּמִים בְּסוֹד שֶׁל אָדָם, וְיָדַעְתִּי שֶׁהֲרֵי דְּיוֹקְנֵיכֶם נוֹעָד לְמַעְלָה. וְכָךְ מְזֻמָּנִים הַצַּדִּיקִים לֶעָתִיד לָבֹא, שֶׁיִּהְיוּ נוֹדָעִים לְעֵין הַכֹּל, וּלְהַרְאוֹת פַּרְצוּף קָדוֹשׁ לִפְנֵי כָּל הָעוֹלָם. זֶהוּ שֶׁכָּתוּב (ישעיה סא) כָּל רֹאֵיהֶם יַכִּירוּם כִּי הֵם זֶרַע בֵּרַךְ ה'."],[1,"","בֵּין כָּךְ רָאָה אֶת רַבִּי יוֹסֵי שֶׁהָיָה מְהַרְהֵר בְּדִבְרֵי הָעוֹלָם. אָמַר לוֹ, יוֹסֵי, קוּם וְהַשְׁלֵם דְּיוֹקְנְךְ, שֶׁאוֹת אַחַת חֲסֵרָה בְּךְ. קָם רַבִּי יוֹסֵי וְשָׂמַח בְּדִבְרֵי תוֹרָה וְקָם לְפָנָיו. הִסְתַּכֵּל בּוֹ רַבִּי שִׁמְעוֹן. אָמַר לוֹ, רַבִּי יוֹסֵי, עַכְשָׁו אַתָּה שָׁלֵם לִפְנֵי עַתִּיק הַיָּמִים וּדְיוֹקְנְךְ שָׁלֵם."],[2,"","פָּתַח וְאָמַר, וַיַּעֲשׂוּ אֶת צִיץ נֵזֶר הַקֹּדֶשׁ זָהָב טָהוֹר וְגוֹ'. לָמָּה נִקְרָא צִיץ? הִסְתַּכְּלוּת לְהִסְתַּכֵּל בּוֹ. וּמִשּׁוּם שֶׁהָיָה עוֹמֵד עַל הִסְתַּכְּלוּת שֶׁל אָדָם, נִקְרָא צִיץ. וְכָל מִי שֶׁהִסְתַּכֵּל בּוֹ בְּאוֹתוֹ צִיץ, הָיָה נוֹדָע בּוֹ וּמֻכָּר."],[3,"","בַּצִיץ הָיוּ אוֹתִיּוֹת הַשֵּׁם הַקָּדוֹשׁ חֲקוּקוֹת בַּחֲקִיקָה וַחֲקוּקוֹת בּוֹ. וְאִם צַדִּיק הָיָה אוֹתוֹ שֶׁעוֹמֵד לְפָנָיו, אוֹתָן אוֹתִיּוֹת שֶׁחֲקוּקוֹת בְּתוֹךְ הַזָּהָב הָיוּ בּוֹלְטוֹת מִמַּטָּה לְמַעְלָה וְעוֹלוֹת מֵאוֹתָהּ חֲקִיקָה בְּאוֹר, וְהָיוּ מְאִירוֹת בִּפְנֵי אוֹתוֹ הָאָדָם."],[4,"","נוֹצֶצֶת בּוֹ הִתְנוֹצְצוּת, וְלֹא נוֹצְצִים. בַּשָּׁעָה הָרִאשׁוֹנָה שֶׁהִסְתַּכֵּל בּוֹ הַכֹּהֵן, הָיָה רוֹאֶה אֶת אוֹר הָאוֹתִיּוֹת כֻּלָּם בַּפָּנִים, וּכְשֶׁהָיָה מִסְתַּכֵּל לְעַיֵּן בּוֹ, לֹא הָיָה רוֹאֶה דָבָר, אֶלָּא אֶת אוֹר פָּנָיו שֶׁמֵּאִיר כְּאִלּוּ נִיצוֹץ שֶׁל זָהָב הָיָה נוֹצֵץ בּוֹ. רַק שֶׁהַכֹּהֵן הָיָה יוֹדֵעַ אֶת מַרְאֵה הַהִסְתַּכְּלוּת הָרִאשׁוֹנָה שֶׁהָיָה רוֹאֶה לְפִי שָׁעָה, שֶׁהֲרֵי רְצוֹנוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא הָיָה בְּאוֹתוֹ אָדָם, וְיוֹדֵעַ שֶׁהוּא מְזֻמָּן לָעוֹלָם הַבָּא, מִשּׁוּם שֶׁהַמַּרְאֶה הַזֶּה מְאִירִים עָלָיו מִלְמַעְלָה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא הָיָה מְרֻצֶּה בּוֹ. וּכְשֶׁמִּסְתַּכְּלִים בּוֹ לֹא רוֹאִים דָּבָר, מִשּׁוּם שֶׁהַמַּרְאֶה שֶׁלְּמַעְלָה אֵינוֹ מִתְגַּלֶּה אֶלָּא לְפִי שָׁעָה."],[5,"","וְאִם עוֹמֵד אָדָם לִפְנֵי אוֹתוֹ צִיץ וּפָנָיו אֵינָם מַרְאִים לְפִי שָׁעָה מַרְאֶה קָדוֹשׁ, הָיָה הַכֹּהֵן יוֹדֵעַ שֶׁהֲרֵי הוּא עַז מֵצַח, וְצָרִיךְ לְכַפֵּר עָלָיו וּלְבַקֵּשׁ עָלָיו רַחֲמִים."],[6,"","וַיַּעַשׂ אֶת צִיץ נֶזֶר הַקֹּדֶשׁ. רַבִּי יְהוּדָה פָּתַח הַפָּסוּק בְּרוּת (רות ב), עֵינַיִךְ בַּשָּׂדֶה אֲשֶׁר יִקְצֹרוּן וְגוֹ'. בַּפָּסוּק הַזֶּה יֵשׁ לְהִתְבּוֹנֵן, לָמָּה צָרִיךְ כָּאן לִכְתֹּב? אָמַר לוֹ רַבִּי יִצְחָק, אִם כָּךְ, כַּמָּה פְסוּקִים הֵם בַּתּוֹרָה שֶׁנִּרְאֶה שֶׁלֹּא הִצְטָרְכוּ לְהִכָּתֵב, וְרָאִינוּ שֶׁכֻּלָּם סוֹדוֹת עֶלְיוֹנִים. אָמַר רַבִּי יְהוּדָה, בְּפָסוּק זֶה מִי שֶׁרוֹאֶה וְלֹא מִתְבּוֹנֵן בּוֹ, כְּמִי שֶׁלֹּא טָעַם תַּבְשִׁיל הוּא דּוֹמֶה."],[7,"","אֶלָּא סוֹד כָּאן, וּבְרוּחַ הַקֹּדֶשׁ נֶאֱמַר. מִשּׁוּם שֶׁרָאָה בֹּעַז, הַדַּיָּן שֶׁל יִשְׂרָאֵל, אֶת עַנְוְתָנוּתָהּ שֶׁל אוֹתָהּ צַדֶּקֶת, שֶׁלֹּא מְרִימָה עֵינֶיהָ לִרְאוֹת בְּמָקוֹם אַחֵר אֶלָּא לְפָנֶיהָ, וְרָאֲתָה כָּל מַה שֶּׁרָאֲתָה בְּעַיִן טוֹבָה, וְעַזּוּת הַמֵּצַח לֹא הָיְתָה בָּהּ - שִׁבַּח אֶת עֵינֶיהָ."],[8,"","מִשּׁוּם שֶׁיֵּשׁ עֵינַיִם שֶׁבִּשְׁבִילָן אֵין שׁוֹלֶטֶת בְּרָכָה בְּאוֹתוֹ מָקוֹם, וְהוּא רָאָה בָּהּ עַיִן טוֹבָה, שֶׁעַל כָּל מַה שֶּׁהִסְתַּכְּלָה הָיָה בְּעַיִן טוֹבָה. וְעוֹד, שֶׁרָאָה שֶׁהָיָה מַצְלִיחַ בְּיָדָהּ כָּל מַה שֶּׁהָיְתָה לוֹקַחַת נוֹסָף בַּשָּׂדֶה. וּבעַז הִתְבּוֹנֵן שֶׁרוּחַ הַקֹּדֶשׁ שׁוֹרָה עָלֶיהָ, וְאָז פָּתַח וְאָמַר, עֵינַיִךְ בַּשָּׂדֶה אֲשֶׁר יִקְצֹרוּן וְגוֹ'. אִם תֹּאמַר, בִּשְׁבִיל אוֹתָם הַלּוֹקְטִים כָּל אוֹתָם הָאֲחֵרִים, אֵיךְ אָמַר שֶׁתֵּלֵךְ אַחֲרֵיהֶם? לֹא הָיָה צָרִיךְ לִכְתֹּב אֶלָּא וְלָקַטְתְּ אַחֲרֵיהֶן. מַה זֶּה וְהָלַכְתְּ אַחֲרֵיהֶן? אֶלָּא בִּשְׁבִיל עֵינֶיהָ הוּא אָמַר, עֵינֶיהָ שֶׁהָיוּ גוֹרְמוֹת (ברכות רבות, ועל כן) בְּרָכוֹת לְלוֹקְטִים רַבִּים, וְעַל כֵּן וְהָלַכְתְּ אַחֲרֵיהֶן, אַחַר עֵינַיִךְ. כָּל שְׁאָר בְּנֵי הָעוֹלָם אֵין לָהֶם רְשׁוּת לָלֶכֶת אַחַר עֵינֵיהֶם, וְאַתְּ אַחַר עֵינַיִךְ, שֶׁעֵינַיִךְ גּוֹרְמוֹת לִבְרָכוֹת רַבּוֹת."]]],[["דָּבָר אַחֵר עֵינַיִךְ בַּשָּׂדֶה אֲשֶׁר יִקְצֹרוּן. בֹּעַז חָמָא בְּרוּחַ קוּדְשָׁא, דִּזְמִינִין לְנָפְקָא מִינָּהּ מַלְכִין עִלָּאִין שַׁלִּיטִין דְּאִינּוּן עַיְינִין דְּכֹלָּא. כְּמָה דַּהֲוַות תָּמָר, דִּכְתִּיב בָּהּ, (בראשית ל״ח:י״ד) וַתֵּשֶׁב בְּפֶתַח עֵינַיִם. אִתְיַישְּׁבַת בְּפִתְחָא דְּנָפְקִין מִינָּהּ מַלְכִין שַׁלִּיטִין עִלָּאִין, דְּאִקְרוּן עַייְנִין, כְּמָה דְאַתְּ אָמֵר (במדבר ט״ו:כ״ד) אִם מֵעֵינֵי הָעֵדָה. כְּמָה דְּכָל שַׁיְיפֵי גּוּפָא לָא אָזְלִין אֶלָּא בָּתַר עַיְינִין, וְעַיְינִין אִינּוּן מִנְהָגִין לְכָל גּוּפָא. אוּף הָכִי מַלְכִין וְסַנְהֶדְרִין, וְכָל אִינּוּן שַׁלִּיטִין, כֹּלָּא אַזְלִין אֲבַתְרַיְיהוּ (ס\"א דאזלין שייפין בתר עיינין) וּבְגִין כַּךְ אָמַר לָהּ עֵינַיִךְ אִלֵּין מַלְכִין וְשַׁלִּיטִין, דִּזְמִינִין לְמֵיפַק מִינָּהּ.","בַּשָּׂדֶה. מַאן שָׂדֶה. דָּא צִיּוֹן וִיְרוּשָׁלַ ם, דִּכְתִּיב, (מיכה ג׳:י״ב) צִיּוֹן שָׂדֶה תֵחָרֵשׁ. וּכְתִיב (בראשית כ״ז:כ״ז) כְּרִיחַ שָׂדֶה אֲשֶׁר בֵּרַכוֹ יְיָ', דָּא יְרוּשָׁלַ ם. וְעַל דָּא כְּתִיב עֵינַיִךְ בַּשָּׂדֶה, דְּאִינּוּן עַיְינִין דִּילָהּ, דִּזְמִינִין לְמֵיפַק מִינָּהּ, לָא יְהוֹן שַׁלִּיטִין אֶלָּא בַּשָּׂדֶה. אֲשֶׁר יִקְצֹרוּן, דְּהָא מֵהַהוּא שָׂדֶה, הֲווֹ נַקְטִין כָּל בְּנֵי עָלְמָא תּוֹרָה, וּנְהוֹרָא דְּנָהִיר, דִּכְתִּיב, (ישעיהו ב׳:ג׳) כִּי מִצִּיּוֹן תֵּצֵא תּוֹרָה.","וְהָלַכְתְּ אַחֲרֵיהֶן, בְּאִלֵּין עוֹבָדִין דְּכַשְׁרָן, דַּאֲנָא חֲמֵינָא בְּךָ. הֲלֹא צִוִּיתִי אֶת הַנְּעָרִים וְגוֹ'. כְּמַשְׁמָעוֹ דִּילֵיהּ, בְּגִין דְּאִתְּתָא דַּעְתָּא קַלָה. וְצָמִית, לִישָׁנָא דִּנְקִיוּת נָקַט, וְצָמִית, דְּאִי תִּיאוּבְתִּךְ לְאַדְבְּקָא בְּבַר נָשׁ לְקַיְּימָא זַרְעָא בְּעָלְמָא, וְהָלַכְתְּ אֶל הַכֵּלִים, אִלֵּין אִינּוּן צַדִּיקַיָּיא, דְּאִקְרוּן כְּלֵי יְיָ', דִּכְתִּיב, (ישעיהו נ״ב:י״א) הִבָּרוּ נֹשְׂאֵי כְּלֵי יְיָ'. דִּזְמִינִין צַדִּיקַיָּיא לְאַיְיתָאָה לוֹן כָּל עָלְמָא, דּוֹרוֹנָא לְמַלְכָּא מְשִׁיחָא, וְאִינּוּן כְּלֵי יְיָ', מָאנִין דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְהֲנֵי בְּהוּ, אִלֵּין אִינּוּן מָאנִין תְּבִירִין, תְּבִירִין אִינּוּן בְּהַאי עָלְמָא, בְּגִין לְקַיְּימָא אוֹרַיְיתָא. וְשִׁימוּשָׁא דְּקוּדְשָׁא בְּרִיךְ הוּא אִשְׁתְּמַּשׁ בְּהוּ, לָא אִשְׁתָּמַּשׁ אֶלָּא מִגּוֹ הָנֵי כֵּלִים. וְכַד תִּתְדְּבַק בְּהוּ וְשָׁתִיתָ וְגוֹ'.","רִבִּי יוֹסֵי פָּתַח וְאָמַר, (רות ג׳:ז׳) וַיֹאכַל בֹּעַז וַיֵּשְׁתְּ וַיִּיטַב לִבּוֹ. מַהוּ וַיִּיטַב לִבּוֹ. דְּבָרִיךְ עַל מְזוֹנֵיהּ, וְאוּקְמוּהָ. וְדָא הוּא רָזָא, דְּמַאן דִּמְבָרֵךְ עַל מְזוֹנֵיהּ, דָּא אוֹטִיב לְלִבֵּיהּ, וּמַאן אוֹטִיב (נ\"א איהו) כְּמָה דִּכְתִּיב, (תהלים כז ח) לְךָ אָמַר לִבִּי. וּכְתִיב (תהילים ע״ג:כ״ו) צוּר לְבָבִי וְגוֹ'.","וּבְגִין דְּבִרְכַּת מְזוֹנָא חֲבִיבָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, כָּל מַאן דְּבָרִיךְ עַל שַׂבְעָא, אוֹטִיב וְחַדֵּי לַאֲתָר אַחֲרָא, וְסִימָנִךְ סְעוּדָתֵי דְּשַׁבָּת, דְּאֲתָר אַחֲרָא אִתְהֲנִי מֵהַהִיא בְּרָכָה (ר\"ד ע\"ב) דְּשַׂבְעָא וְחִידוּ. וְהָכָא אִתְהֲנֵי מֵהַהוּא בְּרָכָה דְּשַׂבְעָא דְּהַהוּא צַדִּיק בֹּעַז וְדָא וַיִּיטַב לִבּוֹ.","מַאי טַעְמָא. בְּגִין דִּמְזוֹנָא אִיהוּ קָשֶׁה קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא הַהוּא אֲתָר, וְכֵיוָן דְּבַר נָשׁ אָכִיל וְשָׁתֵי, וְקָא מְבָרֵךְ. הַהִיא בִּרְכָתָא סַלְּקָא, וְאִתְהֲנֵי מֵאִינּוּן מִלִּין דְּשַׂבְעָא דְּסַלְקִין, וְאִשְׁתְּכַח דְּאִתְהֲנֵי מִמְּזוֹנָא מִתַּתָּא וּמִלְּעֵילָּא.","וְדָא אִיהוּ רָזָא דְּבֵין חַבְרַיָּיא. רָזָא בְּחוֹל לָא אִתְהֲנֵי הַהוּא אֲתָר, אֶלָּא מֵאִינּוּן מִלִּין דְּסַלְקִין מִגּוֹ שַׂבְעָא, וְכֻלְּהוּ מִלִּין מִתְעַטְּרָן וְרַוָּון וְשַׂבְעִין בְּחֵידוּ, וְהַהוּא אֲתָר אִתְהֲנִי מִנַּיְיהוּ. בְּשַׁבָּת אִיהוּ רָזָא אָחֳרָא, בִּמְזוֹנָא מַמָּשׁ, וּבְהַהוּא חֶדְוָה דִּמְזוֹנָא דְּמִצְוָה דְּשַׁבָּת, וּבְכֹלָּא אִשְׁתְּכַח כְּלִילָא מֵעֵילָּא וְתַתָּא. וְרָזָא דָּא (דברי הימים א כט יד) כִּי מִמְּךָ הַכֹּל וּמִיָּדְךָ נָתַנּוּ לָךְ. וַדַּאי בַּהֲנָאוּתֵיהּ דָּא, וּבְהַהוּא חֶדְוָה דִּמְזוֹנָא דְּמִצְוָה דְּשַׁבָּת, כְּמָה דְּאוּקְמוּהָ.","מַאן דִּמְבָרֵךְ לְקוּדְשָׁא בְּרִיךְ הוּא מִגּוֹ שַׂבְעָא, בָּעֵי לְכַוְּונָא לִבֵּיהּ, וּלְשַׁוָּואָה רְעוּתֵיהּ בְּחֶדְוָה, וְלָא יִשְׁתְּכַּח עָצִיב, אֶלָּא דִּיבָרֵךְ בְּחֶדְוָה בְּרָזָא דָּא, וּלְשַׁוָּאָה רְעוּתֵיהּ דְּהָא אִיהוּ יָהִיב הַשְׁתָּא לְאַחֲרָא בְּחֶדְוָה, בְּעֵינָא טָבָא, וּכְמָּה דְּאִיהוּ מְבָרֵךְ בְּחֶדְוָה וּבָעֵינָא טָבָא. הָכִי יָהֲבִין לֵיהּ בְּחֶדְוָה וּבָעֵינָא טָבָא. וּבְּגִין כָּךְ לָא יִשְׁתְּכַּח עָצִיב כְּלָל, אֶלָּא בְּחֶדְוָה, וּבְמִלִּין דְּאוֹרַיְיתָא, וִישַׁוֵּי לִבֵּיהּ וּרְעוּתֵיהּ לְמֵיהַב בְּרָכָה דָּא, בְּרָזָא דְּאִצְטְרִיךְ.","רָזָא הָכָא, אַרְבַּע רְתִיכִין שַׁלִּיטִין, בְּד' סִטְרִין וּמַשִׁירְיָין, אִתְזָנוּ מֵהַהִיא בִּרְכָתָא דְּשַׂבְעָא, וּבְאִינּוּן מִלִּין דְּבָרוּךְ אַתָּה, אִתְהֲנִי וְאִתְרַבֵּי וְאִתְעַטָּר בֵּיהּ. וּמַאן דִּמְבָרֵךְ אִצְטְרִיךְ רְעוּתָא בְּחֶדְוָה, וּבְעֵינָא טָבָא, וְעַל דָּא כְּתִיב, (משלי כ״ב:ט׳) טוֹב עַיִן הוּא יְבוֹרָךְ."],[[0,"ד\"א עיניך בשדה וגו':","פירוש אחר על עיניך בשדה אשר יקצרון. בעז ראה ברוח הקדש שעתיד לצאת ממנה מלכים עליונים ושליטים, שהם עינים של הכל. כמו שהיתה תמר, שכתב בה, ותשב בפתח עינים, שנתישבה בפתח, שיצאו ממנה מלכים שליטים עליונים, הנקראים עינים, כש\"א, אם מעיני העדה. כי כמו שכל אברי הגוף אינם הולכים אלא אחרי העינים, והעינים מנהיגים לכל הגוף, אף כך, מלכים וסנהדרין וכל אלו השליטים, הכל הולכים אחריהם. ומשום זה אמר לה עיניך, שאלו הם המלכים והשליטים העתידים לצאת ממנה."],[1,"בשדה, מאן שדה וכו':","שואל, כתוב בשדה אשר יקצרון, מי הוא שדה. ומשיב. זהו ציון וירושלים, שכתוב, ציון \u0003שדה\u0004 תחרש. וכתוב כריח \u0003שדה\u0004 אשר ברכו ה', שזה ירושלים. וע\"כ כתוב, עיניך בשדה. שאלו העינים שלה העתידים לצאת ממנה, אינן שולטות אלא בשדה. \u0003אשר יקצרון,\u0004 כי משדה ההוא היו לוקחים כל בני עולם תורה, ואור המאיר, שכתוב, כי מציון תצא תורה."],[2,"והלכת אחריהן:","היינו באלו מעשים טובים שאני רואה בך. \u0003הלא צויתי את הנערים\u0004 וגו', כמשמעות שלו דהיינו כפשוטו כי האשה דעתה קלה, וע\"כ הזהיר הנערים שלא יגעו בה. \u0003וצמית,\u0004 תפש לשון נקי, וצמית, פירושו, שאם חשקך להתדבק באדם לקיים זרע בעולם, \u0003והלכת אל הכלים,\u0004 אלו הם הצדיקים שנקראים כלי ה'. שכתוב חברו נשאי כלי ה' שעתידים הצדיקים, שיביאו אותם כל העולם מתנה למלך המשיח. והם כלי ה' כלים שהקדוש ברוך הוא נהנה מהם. אלו הם כלים שבורים, שבורים הם בעולם הזה כדי לקיים התורה. והשימוש שהקב\"ה משתמש בהם אינו משתמש אלא מתוך כלים ההם. וכאשר תתדבק בהם \u0003ושתית,\u0004 וגו'."],[3,"ר' יוסי פתח וכו':","ר\"י פו\"א, ויאכל בעז וישת וייטב לבו. מהו וייטב לבו. היינו שבדך על מזונו. והעמידוהו, וזה הוא סוד שמי שמברך על מזונו הוא מטיב ללבו. ומי הוא. הוא כמו שכתוב, לך אמר לבי. וכתוב, צור לבבי, שפירושו המלכות, שנקראת לב."],[4,"ובגין דברכת מזונא וכו':","ומשום שברכת המזון חביבה לפני הקב\"ה, כל מי שמברך על השובע, מטיב ומשמח למקום אחר, דהיינו להמלכות, וסימנך, סעודות השבת, שמקום אחר, שהוא המלכות, נהנה מברכת השובע ההיא והשמחה. וכאן, נהנתה המלכות, מברכת השובע ההוא של הצדיק בעז. וזהו, וייטב לבו."],[5,"מ\"ט בגין דמזונא וכו':","מהו הטעם, שהמלכות נהנית מברכת המזון. הוא משום שמזון של אדם קשה לפני הקב\"ה, שהוא מקום ההוא דהיינו המלכות, וכיון שהאדם אכל ושתה ומברך ברכת המזון, ברכה ההיא עולה, ונהנית המלכות מאלו דברים הנאמרים על השובע שעולים, ונמצא שנהנה מן המזון למטה, האדם. ולמעלה, המלכות."],[6,"ודא איהו רזא וכו':","וזה הוא סוד בין החברים. הסוד, כי בחול אין מקום ההוא נהנה אלא מאלו הדיבורים העולים מתוך השובע, דהיינו מברכת המזון, וכל המלים מתעטרות ורוות ושבעות בשמחה, ומקום ההוא נהנה מהם. ובשבת, הוא סוד אחר. שבהמזון ממש ובשמחה ההיא של המזון של מצות שבת, נהנית המלכות, ונמצא המזון עצמו כלול לגמרי מלמעלה ומלמטה. וז\"ס, כי ממך הכל ומידך נתנו לך. ודאי, שהמלכות נהנית מהנאתו הזו של האדם ובשמחה זו שבמזון של מצות שבת כמו שהעמידוהו."],[7,"מאן דמברך לקב\"ה וכו':","מי שמברך להקב\"ה מתוך השובע, צריך לכוון לבו ולשום רצונו בשמחה, ולא יהיה עצב, אלא שיברך שמחה בסוד הזה, וישום רצונו שהוא נותן עתה לאחר, בשמחה ובעין טובה. וכמו שהוא מברך בשמחה בעין טובה כך יתנו לו בשמחה ובעין טובה וע\"כ לא יהיה עצב כלל, בשמחה ובדברי תורה. וישום לבו ורצונו לתת ברכה במקום שצריך. דהיינו למלכות."],[8,"רזא הכא ארבע וכו':","כאן סוד, ארבע מרכבות השולטות בארבע רוחות של המלכות, ומחנות המלאכים, נזונים מברכה ההיא שעל השובע, ובאלו המלות שבברוך אתה, שבברכת המזון, נהנה ונתגדל ונתעטר בו, המלכות, ומי שמברך, הרצון צריך להיות בשמחה ובעין טובה, וע\"כ כתוב טוב עין הוא יבורך."]],[[0,"","דָּבָר אַחֵר בַּשָּׂדֶה אֲשֶׁר יִקְצֹרוּן - בּעַז רָאָה בְּרוּחַ הַקֹּדֶשׁ שֶׁעֲתִידִים לָצֵאת מִמֶּנָּה מְלָכִים עֶלְיוֹנִים שַׁלִּיטִים, שֶׁהֵם הָעֵינַיִם שֶׁל הַכֹּל, כְּמוֹ שֶׁהָיְתָה תָּמָר, שֶׁכָּתוּב בָּהּ (בראשית לח) וַתֵּשֶׁב בְּפֶתַח עֵינַיִם. הִתְיַשְּׁבָה בַּפֶּתַח שֶׁיּוֹצֵא מִמֶּנּוּ מְלָכִים שַׁלִּיטִים עֶלְיוֹנִים שֶׁנִּקְרָאִים עֵינַיִם, כְּמוֹ שֶׁנֶּאֱמַר (במדבר טו) אִם מֵעֵינֵי הָעֵדָה. כְּמוֹ שֶׁכָּל אֶבְרֵי הַגּוּף לֹא הוֹלְכִים אֶלָּא אַחַר הָעֵינַיִם, וְהָעֵינַיִם מַנְהִיגוֹת אֶת כָּל הַגּוּף - אַף כָּךְ מְלָכִים וְסַנְהֶדְרִין וְכָל אוֹתָם שַׁלִּיטִים, הַכֹּל הוֹלְכִים אַחֲרֵיהֶם (שהולכים האיברים אחר העינים), וּמִשּׁוּם כָּךְ אָמַר לָהּ עֵינַיִךְ. אֵלּוּ הַמְּלָכִים וְהַשַּׁלִּיטִים שֶׁעֲתִידִים לָצֵאת מִמֶּנָּה."],[1,"","בַּשָּׂדֶה, אֵיזֶה שָׂדֶה? זֶה צִיּוֹן וִירוּשָׁלַיִם, שֶׁכָּתוּב (מיכה ג) צִיּוֹן שָׂדֶה תֵחָרֵשׁ. וְכָתוּב (בראשית כז) כְּרֵיחַ שָׂדֶה אֲשֶׁר בֵּרֲכוֹ ה', זוֹ יְרוּשָׁלַיִם. וְעַל כֵּן כָּתוּב עֵינַיִךְ בַּשָּׂדֶה, שֶׁהֵם הָעֵינַיִם שֶׁלָּהּ, שֶׁעֲתִידִים לָצֵאת מִמֶּנָּה, לֹא יִהְיוּ שַׁלִּיטִים אֶלָּא בַּשָּׂדֶה. אֲשֶׁר יִקְצֹרוּן, שֶׁהֲרֵי מֵאוֹתוֹ שָׂדֶה הָיוּ לוֹקְחִים כָּל בְּנֵי הָעוֹלָם תּוֹרָה וְאוֹר שֶׁמֵּאִיר, שֶׁכָּתוּב (ישעיה ב) כִּי מִצִּיּוֹן תֵּצֵא תוֹרָה."],[2,"","וְהָלַכְתְּ אַחֲרֵיהֶן, בַּמַּעֲשִׂים הַכְּשֵׁרִים הַלָּלוּ שֶׁאֲנִי רָאִיתִי בָךְ. הֲלוֹא צִוִּיתִי אֶת הַנְּעָרִים וְגוֹ', כְּמַשְׁמָעוֹ שֶׁלּוֹ, מִשּׁוּם שֶׁאִשָּׁה דַּעְתָּהּ קַלָּה. וְצָמִת, לְשׁוֹן נְקִיּוּת נָקַט. וְצָמִת, שֶׁאִם תְּשׁוּקָתֵךְ לִדְבּק בְּאָדָם לְקַיֵּם זֶרַע בָּעוֹלָם - וְהָלַכְתְּ אֶל הַכֵּלִים, אֵלֶּה הֵם הַצַּדִּיקִים שֶׁנִּקְרָאִים כְּלֵי ה', שֶׁכָּתוּב (שם נב) הִבָּרוּ נֹשְׂאֵי כְּלֵי ה'. שֶׁעֲתִידִים הַצַּדִּיקִים לְהָבִיא לָהֶם אֶת כָּל הָעוֹלָם דּוֹרוֹן לְמֶלֶךְ הַמָּשִׁיחַ. וְאוֹתָם כְּלֵי ה', כֵּלִים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נֶהֱנֶה בָהֶם, אֵלֶּה הֵם כֵּלִים שְׁבוּרִים, שְׁבוּרִים הֵם בָּעוֹלָם הַזֶּה כְּדֵי לְקַיֵּם אֶת הַתּוֹרָה. וְהַשִּׁמּוּשׁ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִשְׁתַּמֵּשׁ בָּהֶם לֹא מִשְׁתַּמֵּשׁ אֶלָּא מִתּוֹךְ הַכֵּלִים הַלָּלוּ. וּכְשֶׁתִּתְדַּבֵּק בָּהֶם, וְשָׁתִית וְגוֹ'."],[3,"","רַבִּי יוֹסֵי פָּתַח וְאָמַר, (רות ג) וַיֹּאכַל בּעַז וַיֵּשְׁתְּ וַיִּיטַב לִבּוֹ. מַה זֶּה וַיִּיטַב לִבּוֹ? שֶׁבֵּרַךְ עַל מְזוֹנוֹ, וּפֵרְשׁוּהָ. וְזֶהוּ סוֹד, שֶׁמִּי שֶׁמְּבָרֵךְ עַל מְזוֹנוֹ זֶה מֵיטִיב לְלִבּוֹ, וּמִי מוֹלִיךְ? (ומי הוא, ') כְּמוֹ שֶׁכָּתוּב (תהלים כז) לְךְ אָמַר לִבִּי. וְכָתוּב (שם עג) צוּר לְבָבִי וְגוֹ'."],[4,"","וּמִשּׁוּם שֶׁבִּרְכַּת הַמָּזוֹן חֲבִיבָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא - כָּל מִי שֶׁמְּבָרֵךְ עַל הַשּׂבַע, מֵיטִיב וּמְשַׂמֵּחַ לְמָקוֹם אַחֵר, וְסִימָנְךְ - סְעוּדַת הַשַּׁבָּת, שֶׁמָּקוֹם אַחֵר נֶהֱנֶה מֵאוֹתָהּ בְּרָכָה שֶׁל שּבַע וְשִׂמְחָה. וְכָאן נֶהֱנֶה מֵאוֹתָהּ בְּרָכָה שֶׁל שּׁבַע שֶׁל אוֹתוֹ צַדִּיק בּעַז, וְזֶהוּ וַיִּיטַב לִבּוֹ."],[5,"","מָה הַטַּעַם? מִשּׁוּם שֶׁהַמָּזוֹן הוּא קָשֶׁה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהוּא אוֹתוֹ מָקוֹם, וְכֵיוָן שֶׁאָדָם אוֹכֵל וְשׁוֹתֶה וּמְבָרֵךְ, אוֹתָהּ בְּרָכָה עוֹלָה, וְנֶהֱנֶה מֵאוֹתָם דְּבָרִים שֶׁל שּׁבַע שֶׁעוֹלִים, וְנִמְצָא שֶׁנֶּהֱנִים מִן הַמָּזוֹן מִמַּטָּה וּמִלְמַעְלָה."],[6,"","וְזְהִוּ הַסּוֹד שֶׁבֵּין הַחֲבֵרִים. הַסּוֹד שֶׁבַּחֹל לֹא נֶהֱנֶה אוֹתוֹ מָקוֹם, אֶלָּא מֵאוֹתָם דְּבָרִים שֶׁעוֹלִים מִתּוֹךְ שּׁבַע, וְכָל הַדְּבָרִים מִתְעַטְּרִים וְרוֹוִים וּשְׂבֵעִים בְּשִׂמְחָה, וְאוֹתוֹ מָקוֹם נֶהֱנֶה מֵהֶם. בְּשַׁבָּת הוּא סוֹד אַחֵר בַּמָּזוֹן מַמָּשׁ, וּבְאוֹתָהּ שִׂמְחָה שֶׁל הַמָּזוֹן שֶׁל מִצְוָה שֶׁל שַׁבָּת, וּבַכֹּל נִמְצָא כָּלוּל - מִמַּעְלָה וָמַטָּה. וְסוֹד זֶה - כִּי מִמְּךְ הַכֹּל וּמִיָּדְךְ נָתַנּוּ לָךְ. וַדַּאי מֵהֲנָאָתָהּ הַזּוֹ, וּבְאוֹתָהּ שִׂמְחָה שֶׁל מָזוֹן שֶׁל מִצְוַת הַשַּׁבָּת, כְּמוֹ שֶׁבֵּאֲרוּהָ."],[7,"","מִי שֶׁמְּבָרֵךְ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא מִתּוֹךְ שּׁבַע, צָרִיךְ לְכַוֵּן לִבּוֹ וְלָשִׂים רְצוֹנוֹ בְּשִׂמְחָה, וְלֹא יִמָּצֵא עָצוּב, אֶלָּא שֶׁיְּבָרֵךְ בְּשִׂמְחָה בְּסוֹד זֶה וְלָשִׂים רְצוֹנוֹ שֶׁהֲרֵי הוּא נוֹתֵן עַכְשָׁו לְאַחֵר בְּשִׂמְחָה, בְּעַיִן טוֹבָה. וּכְמוֹ שֶׁהוּא מְבָרֵךְ בְּשִׂמְחָה וּבְעַיִן טוֹבָה, כָּךְ נוֹתְנִים לוֹ בְּשִׂמְחָה וּבְעַיִן טוֹבָה. וּמִשּׁוּם כָּךְ לֹא יִמָּצֵא עָצוּב כְּלָל, אֶלָּא בְּשִׂמְחָה וּבְדִבְרֵי תוֹרָה, וְיָשִׂים לִבּוֹ וּרְצוֹנוֹ לָתֵת בְּרָכָה זוֹ בַּסּוֹד שֶׁצָּרִיךְ."],[8,"","סוֹד כָּאן, אַרְבַּע מֶרְכָּבוֹת שׁוֹלְטוֹת בְּאַרְבָּעָה צְדָדִים וּמַחֲנוֹת, נִזּוֹנוּ מֵאוֹתָהּ בִּרְכַּת הַשּׂבַע, וּבְאוֹתָם דְּבָרִים שֶׁל בָּרוּךְ אַתָּה, נֶהֱנֶה וּמִתְרַבֶּה וּמִתְעַטֵּר בּוֹ. וּמִי שֶׁמְּבָרֵךְ, צָרִיךְ רָצוֹן בְּשִׂמְחָה וּבְעַיִן טוֹבָה, וְעַל כֵּן כָּתוּב (משלי כב) טוֹב עַיִן הוּא יְבֹרָךְ."]]],[["וְהָכָא שָׁפִיל לְסֵיפֵיהּ דִּקְרָא, דִּכְתִּיב כִּי נָתַן מִלַּחְמוֹ לַדָּל. דְּאִי לָא תֵּימָא הָכִי, הַאי קְרָא לָאו רֵישֵׁיהּ סֵיפֵיהּ, וְלָאו סֵיפֵיהּ רֵישֵׁיהּ. אֶלָּא טוֹב עַיִן, כְּמָה דְּאוֹקִימְנָא, הוּא יְבָרֵךְ וַדַּאי, בְּעֵינָא טָבָא בְּחֶדְוָה. וְלָאו אִיהוּ לְמִגְנָא לְבָרְכָא בְּחֶדְוָה, דְּהָא מֵהַהִיא בִּרְכָתָא, וּמֵהַהוּא חֵידוּ נָתַן מִלַּחְמוֹ לַדָּל, אֲתָר דְּאִצְטְרִיךְ לְאִתְזָנָא מִכָּל סִטְרִין. אֲתָר דְּלֵית לֵיהּ מִגַּרְמֵיהּ כְּלוּם. אֲתָר דְּאִתְהֲנִי מִכָּל סִטְרִין וְאִתְכְּלִיל מִכָּל סִטְרִין. מִלִּין אִלֵּין לָא אִתְמְסָרוּ אֶלָּא לְחַכִּימִין דְּיַדְעִין רָזִין עִלָּאִין וְאוֹרְחִין דְּאוֹרַיְיתָא.","תָּא חֲזֵי, בֹּעַז טַב עֵינָא הֲוָה תּוּקְפָּא דְּמִצְחָא לָא הֲוָה בֵּיהּ לְעָלְמָא. מַה כְּתִיב, (רות ג׳:ז׳) וַיָּבֹא לִשְׁכַּב בִּקְצֵה הָעֲרֵמָה, רָזָא דִּכְתִּיב, (שיר השירים ז׳:ג׳) בִּטְנֵךְ עֲרֵמַת חִטִּים. מֵהָכָא אוֹלִיפְנָא, כָּל מַאן דִּמְבָרֵךְ בִּרְכַּת מְזוֹנָא כְּדְקָא יֵאוֹת, בְּחֶדְוָה בִּרְעוּתָא דְּלִבָּא, כַּד סָלִיק מֵהַאי עָלְמָא, אֲתָר אִתְתַּקְנָא לֵיהּ, גּוֹ רָזִין עִלָּאִין בְּהֵיכָלִין קַדִּישִׁין. זַכָּאָה אִיהוּ בַּר נָשׁ דְּנָטִיר פִּקּוּדֵי דְּמָארֵיהּ, וְיָדַע רָזָא דִּילְהוֹן, דְּלֵית לָךְ פִּקּוּדָא וּפִקּוּדָא בְּאוֹרַיְיתָא, דְּלָא תַּלְיָין בֵּיהּ רָזִין עִלָּאִין, וּנְהוֹרִין וְזִיוִין עִלָּאִין, וּבְנֵי נָשָׁא לָא יָדְעֵי, וְלָא מַשְׁגִּיחִין בִּיקָרָא דְּמָארֵיהוֹן. זַכָּאָה חוּלָקֵיהוֹן דְּצַדִּיקַיָּיא, אִינּוּן דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא זַכָּאִין אִינּוּן בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי.","תָּא חֲזֵי דְּהָא אָמְרוּ, דְּכָל אִינּוּן תַּקִיפֵי מִצְחָא, דְּלֵית לְהוּ כִּסּוּפָא, לֵית לְהוֹן חוּלָקָא בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי. כָּל אִינּוּן תַּקִיפֵי מִצְחָא דַּהֲווֹ בְּהוּ בְּיִשְׂרָאֵל, כַּד הֲווֹ מִסְתַּכְּלָן בְּהַהוּא צִיץ, הֲווֹ מִתַבְרָן לִבַּיְיהוּ, וּמִסְתַּכְּלָן בְּעוֹבָדַיְיהוּ. בְּגִין דְּצִיץ עַל אָת הֲוָה קָאִים, וְכָל מַאן דְּמִסְתַּכֵּל בֵּיהּ, הֲוָה מַכְסִיף בְּעוֹבָדוֹי. וְעַל דָּא צִיץ מְכַפְּרָא עַל אִינּוּן תַּקִיפֵי אַנְפִּין, תַּקִיפֵי מִצְחָא.","אַתְוָון דְּרָזָא דִּשְׁמָא קַדִּישָׁא דַּהֲווֹ גְּלִיפִין עַל צִיצָא, הֲווֹ נָהֲרִין וּבַלְטִין וְנָצְצִין. כָּל מַאן דְּהֲוָה מִסְתָּכַּל בְּהַהוּא נְצִיצוּ דְּאַתְוָון, אַנְפּוֹי נַפְלִין מֵאֵימָתָא, וַהֲוָה אִתְבַּר לִבֵּיהּ, וּכְדֵין צִיצָא מְכַפְּרָא עָלַיְיהוּ. כְּגַוְונָא דָּא כֵּיוָן דְּאִיהוּ גָּרִים לְתַּבְרָא לִבֵּיהּ, וּלְאִתְכַּנְּעָא מִקַּמֵּי מָארֵיהּ.","כְּגַוְונָא דָּא קְטֹרֶת, כָּל מַאן דְּאָרַח בְּהַהוּא תְּנָנָא, כַּד סָלִיק הַהוּא עַמּוּדָא מֵהַהוּא מַעֲלֶה עָשָׁן, הֲוָה מְבָרֵר לִבֵּיהּ, בִּבְרִירוּ בִּנְהִירוּ בְּחֶדְוָה לְמִפְלַח לְמָארֵיהּ, וְאַעְבָּר מִנֵּיהּ זוּהֲמָא דְּיֵצֶר הָרָע, וְלָא הֲוָה לֵיהּ אֶלָּא לִבָּא חֲדָא, לָקֳבֵל אֲבוּהָ דְּבִשְׁמַיָּא. בְּגִין דִּקְטֹרֶת, תְּבִירוּ דְּיֵצֶר הָרָע אִיהוּ וַדַּאי בְּכָל סִטְרִין. וּכְמָּה דְּצִיץ הֲוָה קָאִים עַל נִיסָא, אוּף קְטֹרֶת. דְּלֵית לָךְ מִלָּה בְּעָלְמָא, לְמִתְבַּר לֵיהּ לְסִטְרָא אַחֲרָא, בַּר קְטֹרֶת.","תָּא חֲזֵי מַה כְּתִיב, (במדבר י״ז:י״א) קַח אֶת הַמַּחְתָּה וְתֶן עָלֶיהָ אֵשׁ מֵעַל הַמִּזְבֵּחַ וְשִׂים קְטֹרֶת. מַאי טַעְמָא. כִּי יָצָא הַקֶּצֶף מִלִּפְנֵי יְיָ', הֵחֵל הַנָּגֶף. דְּהָא לֵית תְּבִירוּ לְהַהוּא סִטְרָא בַּר קְטֹרֶת. דְּלֵית לָךְ מִלָּה חֲבִיבָה קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, כִּקְטֹרֶת. וְקַיְּימָא לְבַטְּלָא חַרְשִׁין, וּמִלִּין בִּישִׁין מִבֵּיתָא. רֵיחָא וַעֲשָׁנָא דִּקְטֹרֶת דְּעַבְדֵי בְּנִי נָשָׁא, בְּהַהוּא עוֹבְדָּא אִיהוּ מְבַטֵּל, כָּל שֶׁכֵּן קְטֹרֶת.","מִלָּה דָּא גְּזֵרָה קַיְּימָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, דְּכָל מַאן דְּאִסְתָּכַּל וְקָרֵי בְּכָל יוֹמָא עוֹבְדָּא (נ\"א פרשתא) דִּקְטֹרֶת, יִשְׁתְּזִיב מִכָּל מִלִּין בִּישִׁין חַרְשִׁין דְּעָלְמָא. וּמִכָּל פְּגָעִין בִּישִׁין, וּמֵהִרְהוּרָא בִּישָׁא, וּמִדִּינָא בִּישָׁא, וּמִמוֹתָנָא, וְלָא יִתְזַק כָּל הַהוּא יוֹמָא, דְּלָא יָכִיל סִטְרָא אַחֲרָא לְשַׁלְטָא עָלֵיהּ, וְאִצְטְרִיךְ דִּיכַוֵּין בֵּיהּ.","אָמַר רַבִּי שִׁמְעוֹן, אִי בְּנֵי נָשָׁא הֲווֹ יַדְעֵי כַּמָה עִלָּאָה אִיהוּ עוֹבָדָא דִּקְטֹרֶת קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, הֲווֹ נַטְלֵי כָּל מִלָּה וּמִלָּה מִנֵּיהּ, וַהֲווּ סַלְקֵי לֵהּ עֲטָרָה עַל רֵישַׁיְיהוּ, כְּכִתְרָא דְּדַהֲבָא. וּמַאן דְּאִשְׁתָּדַּל בֵּיהּ, בָּעֵי לְאִסְתַּכְּלָא בְּעוֹבָדָא דִּקְטֹרֶת, וְאִי יְכַוֵין בֵּיהּ בְּכָל יוֹמָא, אִית לֵיהּ חוּלָקָא בְּהַאי עָלְמָא, וּבְעָלְמָא דְּאָתֵי, וְיִסְתָּלַּק מוֹתָנָא מִנֵּיהּ, וּמֵעָלְמָא, וְיִשְׁתְּזִיב מִכָּל דִּינִין דְּהַאי עָלְמָא, מִסִּטְרִין בִּישִׁין, וּמִדִּינָא דְּגֵיהִנָּם, וּמִדִּינָא דְּמַלְכוּ אַחֲרָא."],[[0,"והכא שפיל לסיפיה וכו':","וכאן תרד לסופו של המקרא, שכתוב, כי נתן מלחמו לדל. ואם לא תאמר כך, שתחלת הכתוב מדבר בברכת המזון, אין ראש הכתוב סופו, ואין סופו ראשו, שאין להם קשר זה בזה. אלא, \u0003טוב עין,\u0004 הוא כמו שהעמדנו, שהוא יברך ודאי בעין טובה בשמחה, ולא לחנם הוא מברך בשמחה, כי מברכה ההיא ומשמחה ההיא \u0003נתן מלחמו לדל,\u0004 דהיינו המקום הצריך להיות נזון מכל הצדדים, מימין ומשמאל, מקום שאין לו מעצמו כלום, מקום הנהנה מכל הצדדים ונכלל מכל הצדדים, שהוא המלכות. וע\"כ היא נקראת \u0003דל,\u0004 ועליה אומר כי נתן מלחמו לדל. דברים אלו אינם נמסרים אלא לחכמים היודעים סודות עליונים ודרכי התורה."],[1,"ת\"ח בעז טב וכו':","בוא וראה בעז היה טוב עין. עזות מצח לא היה בו לעולם. מה כתוב, ויבא לשכב בקצה הערמה, שהוא סוד הכתוב, בטנך ערמת חטים, הנאמר על המלכות. אף כאן, בקצה הערמה, היא המלכות. מכאן למדתי כל מי שמברך ברכת המזון כראוי, בשמחה, ברצון הלב, כשעולה מעולם הזה, מקום נתתקן לו תוך סודות עליונים בהיכלות הקדושים של המלכות הנקראת ערמה, שעל זה רומז הכתוב, \u0003ויבא לשכב\u0004 אחר שיפטר מן העולם \u0003בקצה הערמה,\u0004 שהיא המלכות. אשרי הוא האדם השומר מצות אדונו, ויודע הסודות שלהם, שאין לנו מצוה ומצוה בתורה, שאין תלויות בה סודות עליונים ואורות וזיוים עליונים, ובני אדם אינם יודעים ואינם משגיחים בכבוד אדונם. אשרי חלקם של הצדיקים, אותם העוסקים בתורה. אשרי הם בעולם הזה ובעולם הבא."],[2,"ת\"ח דהא אמרו וכו':","בוא וראה, כי אמרו, שכל אלו עזי מצח, שאין להם בושה, אין להם חלק בעולם הזה ובעולם הבא. כל אלו עזי מצח שהיו בישראל, כשהיו מסתכלים בציץ ההוא, היה נשבר לבם ומסתכלים במעשיהם. משום שהציץ היה עומד על אות, שהיה נחרת עליו קדש להויה, וכל מי שמסתכל בו היה בוש ממעשיו. וע\"כ הציץ מכפר על עזי פנים ועזי מצח."],[3,"אתוון דרזא דשמא וכו':","סוד אותיות של השם הקדוש שהיו חקוקות על הציץ, היו מאירות באור בולט ונוצץ, כל מי שהיה מסתכל בהתנוצצות ההיא של האותיות, פניו נופלים מאימה, והיה נשבר לבו, ואז הציץ מכפר עליהם, כאפן הזה, כיון שהוא גרם שישבור לבו ושיכנע לפני אדונו."],[4,"כגוונא דא קטורת וכו':","כעין זה קטורת. כל מי שהריח בעשן ההוא, כשעלה עמוד העשן ההוא מאותו מעלה עשן, היה מברר לבו בברור לעבוד לאדונו, ונעבר ממנו הזוהמא של היצר הרע, ולא היה לו אלא לב אחד כלפי אביו שבשמים. משום שקטרת הוא שבירת היצר הרע ודאי בכל הצדדים. וכמו שהציץ היה קם על נס, כך קטרת, שאין לך דבר בעולם לשבר את הסטרא אחרא חוץ מקטרת."],[5,"ת\"ח מה כתיב וכו':","בוא וראה מה כתוב, קח את המחתה ותן עליה אש מעל המזבח ושים קטרת, מהו הטעם, כי יצא הקצף מלפני ה' החל הנגף. כי אין שבירה לצד ההוא חוץ על ידי קטרת. שאין לך דבר חביב לפני הקב\"ה כקטרת. ועומדת לבטל כשוף ודברים רעים, מבית. ריח ועשן של קטרת שעושים בני אדם, הוא מבטל כשפים במעשה ההוא, כל שכן קטרת."],[6,"מלה דא גזרה וכו':","דבר זה, גזרה עומדת לפני הקב\"ה, שכל מי שמסתכל וקורא בכל יום מעשה הקטרת, ינצל מכל הדברים הרעים והכשפים שבעולם. ומכל פגעים רעים, ומהרהור רע, ומדין רע, ומות, ולא ינזק כל יום ההוא, כי אין סטרא אחרא יכולה לשלוט עליו. וצריך שיכון בו."],[7,"אר\"ש אי בני וכו':","א\"ר שמעון, אם בני אדם היו יודעים, כמה עליון הוא מעשה הקטרת לפני הקב\"ה, היו לוקחים כל מלה ומלה ממנו, והיו מעלים אותה עטרה על ראשם, ככתר של זהב. ומי שמשתדל בו, במעשה הקטרת, צריך להסתכל בו. ואם יכוון בו בכל יום, יש לו חלק בעולם הזה ובעולם הבא, ויסתלק מיתה ממנו ומעולם, וינצל מכל דינין שבעולם הזה, מצדדים רעים, ומדין של גיהנם, ומדינה של מלכות האחרת."]],[[0,"","וְכָאן רֵד לְסוֹף הַפָּסוּק, שֶׁכָּתוּב כִּי נָתַן מִלַּחְמוֹ לַדָּל. שֶׁאִם לֹא תֹאמַר כָּךְ - הַפָּסוּק הַזֶּה אֵין רֹאשׁוֹ סוֹפוֹ וְאֵין סוֹפוֹ רֹאשׁוֹ. אֶלָּא טוֹב עַיִן, כְּמוֹ שֶׁבֵּאַרְנוּ, הוּא יְבָרֵךְ וַדַּאי, בְּעַיִן טוֹבָה וּבְשִׂמְחָה. וְאֵינוֹ לְחִנָּם לְבָרֵךְ בְּשִׂמְחָה, שֶׁהֲרֵי מֵאוֹתָהּ בְּרָכָה וּמֵאוֹתָהּ שִׂמְחָה נָתַן מִלַּחְמוֹ לַדַּל, מָקוֹם שֶׁצָּרִיךְ לְהִזּוֹן מִכָּל הַצְּדָדִים. מָקוֹם שֶׁאֵין לוֹ מֵעַצְמוֹ כְּלוּם. מָקוֹם שֶׁנֶּהֱנֶה מִכָּל הַצְּדָדִים וְנִכְלָל מִכָּל הַצְּדָדִים. הַדְּבָרִים הַלָּלוּ לֹא נִמְסְרוּ אֶלָּא לַחֲכָמִים שֶׁיּוֹדְעִים סוֹדוֹת עֶלְיוֹנִים וְדַרְכֵי הַתּוֹרָה."],[1,"","בֹּא וּרְאֵה, בֹּעַז הָיָה טוֹב עַיִן, וְעַזּוּת מֵצַח מֵעוֹלָם לֹא הָיְתָה בּוֹ. מַה כָּתוּב? (רות ג) וַיָּבא לִשְׁכַּב בִּקְצֵה הָעֲרֵמָה. סוֹד הַכָּתוּב - (שיר ז) בִּטְנֵךְ עֲרֵמַת חִטִּים. מִכָּאן לָמַדְנוּ, שֶׁכָּל מִי שֶׁמְּבָרֵךְ בִּרְכַּת הַמָּזוֹן כָּרָאוּי בְּשִׂמְחָה וּבִרְצוֹן הַלֵּב, כְּשֶׁמִּסְתַּלֵּק מִן הָעוֹלָם הַזֶּה מְתֻקָּן לוֹ מָקוֹם בְּתוֹךְ סוֹדוֹת עֶלְיוֹנִים בְּהֵיכָלוֹת קְדוֹשִׁים. אַשְׁרֵי הָאִישׁ שֶׁשּׁוֹמֵר אֶת מִצְווֹת אֲדוֹנוֹ וְיוֹדֵעַ אֶת סוֹדָן, שֶׁאֵין לְךְ מִצְוָה וּמִצְוָה בַּתּוֹרָה שֶׁאֵין תְּלוּיִים בָּהּ סוֹדוֹת עֶלְיוֹנִים וְאוֹרוֹת וְזִיוִים עֶלְיוֹנִים, וּבְנֵי אָדָם לֹא יוֹדְעִים וְלֹא מַשְׁגִּיחִים בִּכְבוֹד רִבּוֹנָם. אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים, אוֹתָם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה. אַשְׁרֵיהֶם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא."],[2,"","בֹּא וּרְאֵה שֶׁהֲרֵי אָמְרוּ, שֶׁכָּל אוֹתָם עַזֵּי הַמֵּצַח שֶׁאֵין לָהֶם בּוּשָׁה, אֵין לָהֶם חֵלֶק בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. כָּל עַזֵּי הַמֵּצַח שֶׁהָיוּ בְּיִשְׂרָאֵל, כְּשֶׁהָיוּ מִסְתַּכְּלִים בְּאוֹתוֹ הַצִּיץ, הָיוּ מְשַׁבְּרִים אֶת לִבָּם וּמִסְתַּכְּלִים בְּמַעֲשֵׂיהֶם, מִשּׁוּם שֶׁצִּיץ הָיָה עוֹמֵד עַל אוֹת, וְכָל מִי שֶׁמִּסְתַּכֵּל בּוֹ הָיָה מִתְבַּיֵּשׁ בְּמַעֲשָׂיו. וְלָכֵן הַצִּיץ מְכַפֵּר עַל אוֹתָם עַזֵּי פָנִים, עַזֵּי מֵצַח."],[3,"","אוֹתִיּוֹת שֶׁל הַסּוֹד שֶׁל הַשֵּׁם הַקָּדוֹשׁ שֶׁהָיוּ חֲקוּקוֹת עַל הַצִּיץ, הָיוּ מְאִירוֹת וּבוֹלְטוֹת וְנוֹצְצוֹת. כָּל מִי שֶׁהָיָה מִסְתַּכֵּל בְּאוֹתָהּ הִתְנוֹצְצוּת שֶׁל הָאוֹתִיּוֹת, נוֹפְלוֹת פָּנָיו מֵאֵימָה וְהָיָה נִשְׁבָּר לִבּוֹ, וְאָז הַצִּיץ מְכַפֵּר עֲלֵיהֶם. כְּמוֹ זֶה, כֵּיוָן שֶׁהוּא גּוֹרֵם לִשְׁבֹּר לִבּוֹ וּלְהִכָּנַע מִלִּפְנֵי רִבּוֹנוֹ."],[4,"","כְּמוֹ כֵן הַקְּטֹרֶת, כָּל מִי שֶׁהֵרִיחַ בְּאוֹתוֹ עָשָׁן, כְּשֶׁעָלָה אוֹתוֹ עַמּוּד מֵאוֹתוֹ מַעֲלֶה עָשָׁן, הָיָה מְבָרֵר אֶת לִבּוֹ בְּבֵרוּר (באורהבשמחה) לַעֲבֹד אֶת רִבּוֹנוֹ וּמַעֲבִיר מִמֶּנּוּ זֻהֲמַת הַיֵּצֶר הָרָע, וְלֹא הָיָה לוֹ אֶלָּא לֵב אֶחָד כְּנֶגֶד אָבִיו שֶׁבַּשָּׁמַיִם, מִשּׁוּם שֶׁקְּטֹרֶת הִיא שֶׁבֶר לַיֵּצֶר הָרָע וַדַּאי בְּכָל הַצְּדָדִים. כְּמוֹ שֶׁצִּיץ הָיָה עוֹמֵד עַל נֵס - אַף קְטֹרֶת. שֶׁאֵין לְךְ דָּבָר בָּעוֹלָם לִשְׁבֹּר אֶת הַצַּד הָאַחֵר, פְּרָט לַקְּטֹרֶת."],[5,"","בֹּא וּרְאֵה מַה כָּתוּב, (במדבר יז) קַח אֶת הַמַּחְתָּה וְתֶן עָלֶיהָ אֵשׁ מֵעַל הַמִּזְבֵּחַ וְשִׂים קְטֹרֶת. מָה הַטַּעַם? כִּי יָצָא הַקֶּצֶף מִלִּפְנֵי ה' הֵחֵל הַנָּגֶף. שֶׁהֲרֵי אֵין שֶׁבֶר לְאוֹתוֹ הַצַּד פְּרָט לַקְּטֹרֶת, שֶׁאֵין לְךְ דָּבָר חָבִיב לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כְּמוֹ קְטֹרֶת, וְעוֹמֶדֶת לְבַטֵּל כְּשָׁפִים וּדְבָרִים רָעִים מֵהַבַּיִת. רֵיחַ וַעֲשַׁן הַקְּטֹרֶת שֶׁעוֹשִׂים בְּנֵי אָדָם, בְּאוֹתוֹ מַעֲשֶׂה הוּא מְבַטֵּל, כָּל שֶׁכֵּן הַקְּטֹרֶת."],[6,"","דָּבָר זֶה גְּזֵרָה עוֹמֶדֶת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּל מִי שֶׁמִּסְתַּכֵּל וְקוֹרֵא בְּכָל יוֹם אֶת מַעֲשֵׂה (פרשת) הַקְּטֹרֶת, יִנָּצֵל מִכָּל הַדְּבָרִים הָרָעִים וְכִשְׁפֵי הָעוֹלָם, וּמִכָּל הַפְּגָעִים הָרָעִים, וּמֵהִרְהוּר רַע וּמִדִּין רַע וּמִמָּוֶת, וְלֹא יִנָּזֵק כָּל אוֹתוֹ יוֹם, שֶׁלֹּא יָכוֹל הַצַּד הָאַחֵר לִשְׁלֹט עָלָיו, וְצָרִיךְ שֶׁיְּכַוֵּן בּוֹ."],[7,"","אָמַר רַבִּי שִׁמְעוֹן, אִם בְּנֵי אָדָם הָיוּ יוֹדִים כַּמָּה הוּא עֶלְיוֹן מַעֲשֵׂה הַקְּטֹרֶת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, הָיוּ נוֹטְלִים כָּל דִּבּוּר וְדִבּוּר מִמֶּנּוּ וְהָיוּ מַעֲלִים אוֹתוֹ עֲטָרָה עַל רָאשֵׁיהֶם כְּמוֹ כֶּתֶר שֶׁל זָהָב. וּמִי שֶׁמִּשְׁתַּדֵּל בּוֹ, צָרִיךְ לְהִסְתַּכֵּל בְּמַעֲשֵׂה הַקְּטֹרֶת, וְאִם יְכַוֵּן בּוֹ בְּכָל יוֹם, יֵשׁ לוֹ חֵלֶק בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, וְיִסְתַּלֵּק הַמָּוֶת מִמֶּנּוּ וּמֵהָעוֹלָם, וְיִנָּצֵל מִכָּל הַדִּינִים שֶׁל הָעוֹלָם הַזֶּה, וּמִצְּדָדִים רָעִים, וּמִדִּין הַגֵּיהִנֹּם וּמִדִּין הַמַּלְכוּת הָאַחֶרֶת."]]],[["בְּהַהוּא קְטֹרֶת כַּד הֲוָה סָלִיק תְּנָנָא בְּעַמּוּדָא, כַּהֲנָא הֲוָה חָמֵי אַתְוָון דְּרָזָא דִּשְׁמָא קַדִּישָׁא, פְּרִישָׂא (נ\"א פרחין) בַּאֲוִירָא, וְסַלְקֵי לְעֵילָּא בְּהַהוּא עַמּוּדָא. לְבָתַר כַּמָה רְתִיכִין קַדִּישִׁין סָחֲרִין לֵיהּ מִכָּל סִטְרִין, עַד דְּסָלִיק בִּנְהִירוּ וְחֶדְוָה, וְחַדֵּי לְמַאן דְּחַדֵּי, וְקָשַׁר קִשְׁרִין לְעֵילָּא וְתַתָּא לְיַחֲדָא כֹּלָּא, וְהָא אוֹקִימְנָא. וְדָא מְכַפֵּר עַל יֵצֶר הָרָע, וְעַל עֲבוֹדָה זָרָה, דְּאִיהוּ סִטְרָא אַחֲרָא. וְהָא אוֹקְמוּהָ.","פָּתַח וְאָמַר, (שמות לז) וַיַּעַשׂ מִזְבֵּחַ מִקְטַר קְטֹרֶת וְגוֹ'. הַאי קְרָא אִית לְאִסְתַּכְּלָא בֵּיהּ, בְּגִין דִּתְרֵין מַדְבְּחִין הֲווֹ, מַדְבְּחָא דְּעִלָּוָון, וּמַדְבְּחָא דִּקְטֹרֶת בּוּסְמִין, דָּא לְבַר, וְדָא לְגוֹ. הַאי מַדְבְּחָא דִּקְטֹרֶת, דְּאִיהוּ פְּנִימָאָה, אֲמַאי אִקְרֵי מִזְבֵּחַ, וְהָא לָא דַּבְחִין בֵּיהּ דִּבְחִין, וּמִזְבֵּחַ עַל דָּא אִקְרֵי.","אֶלָּא בְּגִין דְּבָטִיל וְכָפִית לְכַמָּה סִטְרִין בִּישִׁין, וּבְגִין דְּהַהוּא סִטְרָא בִּישָׁא כְּפִית לָא יָכִיל לְשַׁלְּטָאָה, וְלָא לְמֶהֱוֵי קַטֵּיגוֹרָא, וְעַל דָּא אִקְרֵי מִזְבֵּחַ. כַּד הַהוּא סִטְרָא בִּישָׁא הֲוָה חָמֵי (ס\"א עמודא דעשנא) עֲשָׁנָא דִּקְטֹרֶת דְּסָלִיק, אִתְכַּפְיָיא וְעָרַק, וְלָא יָכִיל לְקָרְבָא כְּלַל לְמַשְׁכְּנָא. וּבְגִין דָּא אִתְדָּכֵי וְלָא אִתְעֲרָב בְּהַהוּא חֶדְוָה דִּלְעֵילָּא, בַּר קוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי, וּבְגִין דְּחֲבִיבָא כָּל כַּךְ, לָא קָאִים הַהוּא מִזְבֵּחַ, אֶלָּא (ד\"א פנימאה) לְגוֹ. דְּהַאי אִיהוּ מִזְבֵּחַ דְּבִרְכָּאן אִשְׁתְּכָחוּ בֵּיהּ, וְעַל דָּא סָתִים מֵעֵינָא.","מַה כְּתִיב בְּאַהֲרֹן, (במדבר י״ז:י״ג) וַיַּעֲמוֹד בֵּין הַמֵּתִים וּבֵין הַחַיִּים וַתֵּעָצַר הַמַּגֵּפָה, דְּכָפִית לֵיהּ לְמַלְאַךְ הַמָּוֶת, דְּלָא יָכִיל לְשַׁלְּטָאָה כְּלַל, וְלָא לְמֶעְבַּד דִּינָא. סִימָנָא דָּא אִתְמְסַר בִּידָנָא, דִּי בְּכָל אֲתָר דְּקָאָמְרֵי בְּכַוָונָה, וּרְעוּתָא דְּלִבָּא עוֹבָדָא דִּקְטֹרֶת, דְּלָא שַׁלְטָא מוֹתָנָא בְּהַהוּא אֲתָר, וְלָא יִתְזַק, וְלָא יַכְלִין שְׁאַר עַמִּין לְשַׁלְּטָאָה עַל הַהוּא אֲתָר.","תָּא חֲזֵי מַה כְּתִיב, מִזְבֵּחַ מִקְטַר קְטֹרֶת. כֵּיוָן דִּכְתִּיב מִזְבֵּחַ, אֲמַאי אִקְרֵי מִקְטַר קְטֹרֶת. אֶלָּא בְּגִין דְּנַטְלֵי מֵהַאי אֲתָר לְאַקְטְרָא, כְּמָה דְּעֲבַד אַהֲרֹן. תּוּ, מִזְבֵּחַ אִצְטְרִיךְ לְאַקְטְרָא לְקַדְּשָׁא לֵיהּ בְּהַהוּא קְטֹרֶת, וְעַל דָּא מִקְטַר קְטֹרֶת. תּוּ, מִקְטַר קְטֹרֶת, כְּתַרְגּוּמוֹ, לְאַקְטְרָא קְטֹרֶת, דְּהָא אָסִיר לְאַקְטְרָא בַּאֲתָר אַחֲרָא קְטֹרֶת, בַּר מִמַּחְתָּה. (נ\"א ממחתה דיום הכפורים)","תָּא חֲזֵי, הַאי מַאן דְּדִינָא רָדִיף אֲבַתְרֵיהּ, אִצְטְרִיךְ לְהַאי קְטֹרֶת, וּלְאָתָבָא קַמֵּי מָארֵיהּ, דְּהָא סִיּוּעָא אִיהוּ לְאִסְתַּלְּקָא דִּינִין מִנֵּיהּ, וּבְהַאי וַדַּאי מִסְתַּלְּקִין מִנֵּיהּ, אִי הוּא רָגִיל בְּהַאי, לְאַדְכְּרָא תְּרֵין זִמְנִין בְּיוֹמָא, בְּצַפְרָא וּבְרַמְשָׁא, דִּכְתִּיב קְטֹרֶת סַמִּים בַּבֹּקֶר בַבֹּקֶר וּכְתִיב בֵּין הָעַרְבַּיִם יַקְטִירֶנָּה. וְדָא אִיהוּ קִיוּמָא דְּעָלְמָא תָּדִיר, דִּכְתִּיב, (שמות ל׳:ח׳) קְטֹרֶת תָּמִיד לִפְנִי יְיָ' לְדוֹרוֹתֵיכֶם וַדַּאי הוּא קִיוּמָא דְּעָלְמָא לְתַתָּא, וְקִיּוּמָא דְּעָלְמָא לְעֵילָּא.","בְּהַהוּא אֲתָר דְּלָא אִדְכַּר בְּכָל יוֹמָא עוֹבָדָא דִּקְטֹרֶת, דִּינִין דִּלְעֵילָּא שַׁרְיָין בֵּיהּ, וּמוֹתָנִין סַגִיאוּ בֵּיהּ, וְעַמִּין אַחֲרָנִין שַׁלְטִין עָלֵיהּ. בְּגִין דִּכְתִּיב, קְטֹרֶת תָּמִיד לִפְנֵי יְיָ'. תָּמִיד אִיהוּ קַיְּימָא לִפְנֵי יְיָ', יַתִּיר מִכָּל פּוּלְחָנִין אַחֲרָנִין, חֲבִיבָא אִיהוּ עוֹבָדָא דִּקְטֹרֶת, דְּהוּא יַקִּיר וְחָבִיב קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, יַתִּיר מִכָּל פּוּלְחָנִין וּרְעוּתִין (נ\"א ועובדין) דְּעָלְמָא. וְאַף עַל גַּב דִּצְלוֹתָא אִיהִי מְעַלְּיָיא מִכֹּלָּא, עוֹבָדָא דִּקְטֹרֶת הוּא יַקִּיר וְחָבִיב קָמֵי קוּדְשָׁא בְּרִיךְ הוּא.","תָּא חֲזֵי, מַה בֵּין צְלוֹתָא לְעוֹבָדָא דִּקְטֹרֶת. צְלוֹתָא אַתְקִינוּ לָהּ בַּאֲתָר דְּקָרְבְּנִין, דַּהֲווֹ עַבְדֵי יִשְׂרָאֵל, וְכָל אִינּוּן קָרְבְּנִין דַּהֲווֹ עַבְדִּין יִשְׂרָאֵל, לָאו אִינּוּן חֲשִׁיבִין כִּקְטֹרֶת. וְתוּ מַה בֵּין הַאי לְהַאי. אֶלָּא צְלוֹתָא אִיהוּ תִּקּוּנָא לְאַתְקְנָא מַה דְּאִצְטְרִיךְ, קְטֹרֶת עָבִיד יַתִּיר, מְתַקֵּין וְקָשִׁיר קִשְׁרִין, וְעָבִיד נְהִירוּ יַתִּיר מִכֹּלָּא. וּמַאן אִיהוּ דְּאַעְבַּר זוּהֲמָא וְאִידְכֵּי מַשְׁכְּנָא, וְכֹלָּא אִתְנְהִיר וְאִתְתָּקַּן וְאִתְקָשַּׁר כַּחֲדָא.","וְעַל דָּא בָּעֵינָן לְאַקְדְּמָא עוֹבָדָא דִּקְטֹרֶת לִצְלוֹתָא, בְּכָל יוֹמָא וְיוֹמָא, לְאַעְבְּרָא זוּהֲמָא מֵעָלְמָא, דְּאִיהוּ תִּקּוּנָא דְּכֹלָּא, בְּכָל יוֹמָא וְיוֹמָא. כְּגַוְונָא דְּהַהוּא קָרְבָּנָא חֲבִיבָא דְּאִתְרְעֵי בֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא.","מַה כְּתִיב בְּמֹשֶׁה (שמותל) וַיֹּאמֶר יְיָ' אֶל מֹשֶׁה קַח לְךָ סַמִּים נָטָף וְגוֹ' אַף עַל גַּב דְּאוֹקְמוּהָ, אֲבָל מַאי שְׁנָא בְּעוֹבָדָא דָּא יַתִּיר מִכָּל מַה דְּאָמַר לֵיהּ. אֶלָּא קַח לְךָ, לַהֲנָאָתָךְ וּלְתוֹעַלְתָּךְ. בְּגִין דְּכַד אִתְּתָא אִתְדַכְּאַת, הֲנָאוּתָא דְּבַעְלָהּ אִיהוּ. וְרָזָא דָּא קַח לְךָ סַמִּים, לְאַעְבְּרָא זוּהֲמָא, לְאִתְקַדְּשָׁא אִתְּתָא בְּבַעְלָהּ. זַכָּאָה חוּלָקֵיהּ דְּמֹשֶׁה."],[[0,"בההוא קטרת כד וכו':","בקטרת ההיא, כשהיה עולה העשן כעמוד, היה רואה הכהן אותיות של סוד השם הקדוש פורחות באויר ועולות למעלה כעמוד, לאחר כך, כמה מרכבות קדושות מסבבות אותה מכל הצדדים, עד שעולה באורה ושמחה ומשמח למי שמשמח, וקושרת קשרים דהיינו שמיחדת יחודים, למעלה ולמטה, ליחד הכל. וכבר העמידוהו. וזה מכפר על יצר הרע ועל עכו\"ם, שהוא סטרא אחרא. וכבר העמידוהו."],[1,"פתח ואמר ויעש מזבח וגו':","מקרא זה יש להסתכל בו. כי יש ב' מזבחות, מזבח לעולות ומזבח לקטרת הסמים זה בחוץ וזה בפגים. מזבח הקטרת הזה שהוא פנימי, למה נקרא מזבח, הרי אין מקריבים עליו זבחים, שיקרא משום זה מזבח."],[2,"אלא בגין דבטיל וכו':","אלא משום שביטל ואסר כמה צדדים רעים, ומשום שסטרא אחרא ההוא אסור אינו יכול לשלוט ולא להיות קטיגור וע\"כ נקרא מזבח. משום שהס\"א נאסר ונעקד עליו כמו קרבן. כשהס\"א היה רואה את עשן הקטרת עולה הוא נכנע ובורח, ואינו יכול לקרב כלל למשכן, ומשום זה נטהר, ולא נתערב אחר בשמחה ההיא שלמעלה חוץ מהקב\"ה בלבדו. ומשום שחביב כל כך, אינו עומד מזבח ההוא אלא בפנים, כי הוא מזבח שברכות נמצאות בו, וע\"כ הוא מכוסה מעין. דהיינו שעומד בפנים."],[3,"מה כתיב באהרן וכו':","מה כתוב באהרן, ויעמוד בין המתים ובין החיים ותעצר המגפה. כי אסר את מלאך המות, עד שלא יכול לשלוט כלל, ולא לעשות דין סימן זה נמסר בידינו, שבכל מקום שאומרים בכוונה וברצון הלב, מעשה הקטרת, אינו שולט המות במקום ההוא, ולא ינזק, ולא יכלו שאר העמים לשלוט על מקום ההוא."],[4,"ת\"ח מה כתיב וכו':","בוא וראה מה כתוב, מזבח מקטר קטרת, שואל, כיון שכתוב מזבח, למה נקרא מקטר קטרת, ומשיב, אלא משום שלוקחים אש ממקום הזה להקטיר קטרת, כמו שעשה אהרן, שנאמר קח את המחתה ותן עליה אש מעל המזבח. ועוד, משום שהמזבח, צריכים להקטיר ולקדש אותו בקטרת ההיא, וע\"כ נקרא מקטר קטרת. עוד טעם על מ\"ש מקטר קטרת, הוא כתרגומו, לאקטרא קטרת, כי אסור להקטיר קטרת במקום אחר, חוץ מבמחתה."],[5,"ת\"ח האי מאן וכו':","בוא וראה, זה, מי שדין רודף אחריו הוא צריך לקטרת הזו, ולשוב לפני אדוניו. כי הקטרת היא עזרה שיסתלקו הדינים ממנו. ובזה ודאי מסתלקים הדינים ממנו, דהיינו, אם דרכו בזה, להזכיר ב' פעמים ביום, בבקר ובערב. שכתוב, קטרת סמים בבקר בבקר. וכתוב, בין הערבים יקטירנה. וזה הוא קיום העולם תמיד, שכתוב, קטרת תמיד לפני ה' לדורותיכם. ודאי היא קיום העולם למטה, וקיום העולם למעלה."],[6,"בההוא אתר דלא וכו':","במקום ההוא שלא נזכר, דהיינו שאינם אומרים, בכל יום מעשה הקטרת, שורים עליו דינים שלמעלה, ומגפות רבות בו, ועמים אחרים שולטים עליו. משום שכתוב, קטרת תמיד לפני ה'. תמיד היא עומדת לפני ה', יותר מכל עבודות אחרות. חביב הוא מעשה הקטרת, שהוא יקר וחביב לפני הקב\"ה יותר מכל עבודות ורצונות שבעולם. ואע\"פ שהתפלה היא חשובה מכל, מעשה הקטרת יותר יקר וחשוב לפני הקב\"ה."],[7,"ת\"ח מה בין וכו':","בוא וראה, מה בין תפלה למעשה הקטרת. תפלה, התקינו אותה במקום הקרבנות שהיו עושים ישראל. וכל אלו הקרבנות שהיו עושים ישראל אינם חשובים כקטרת. ועוד, מה בין זה לזה. כי התפלה היא תקון לתקן מה שצריך, קטרת, עושה יותר, שמתקן וקושר קשרים, דהיינו יחודים, ועושה אורה יותר מהכל. ומה הוא. היינו שמעביר הזוהמא ומטהר המשכן והכל מזדהר ומתתקן ומתקשר יחד."],[8,"וע\"ד בעינן לאקדמא וכו':","וע\"כ צריכים להקדים מעשה הקטרת לתפלה בכל יום ויום, להעביר הזוהמא מן העולם, שהוא תקון הכל בכל יום ויום. כמו קרבן חביב שהקב\"ה רוצה בו."],[9,"מה כתיב במשה וכו':","מה כתוב במשה, ויאמר ה' אל משה קח לך סמים נטף וגו'. אע\"פ שהעמידוהו, אבל מה השינוי שבכאן שנאמר \u0003קח לך,\u0004 מכל מה שאמר לו ולא נאמר בו קח לך. ומשיב, אלא קח לך, פירושו להנאתך ולתועלתך. משום כשאשה נטהרת הוא הנאת בעלה. כי הקטרת מטהר המשכן שהיא מלכות כלת משה, כי משה היה מרכבה לז\"א. וז\"ס קח לך סמים להעביר הזוהמא, שיתקדש האשה מלכות, בבעלה ז\"א. אשרי חלקו של משה."]],[[0,"","בְּאוֹתָהּ קְטֹרֶת, כְּשֶׁהָיָה עוֹלֶה עָשָׁן בָּעַמּוּד, הַכֹּהֵן הָיָה רוֹאֶה הָאוֹתִיּוֹת שֶׁל הַשֵּׁם הַקָּדוֹשׁ פְּרוּשׂוֹת (פורחות) בָּאֲוִיר וְעוֹלוֹת לְמַעְלָה בְּאוֹתוֹ עַמּוּד. אַחַר כָּךְ כַּמָּה מֶרְכָּבוֹת קְדוֹשׁוֹת סוֹבְבוֹת אוֹתוֹ מִכָּל הַצְּדָדִים עַד שֶׁעוֹלֶה בְּאוֹר וְשִׂמְחָה, וּמְשַׂמֵּחַ אֶת מִי שֶׁמְּשַׂמֵּחַ, וְקוֹשֵׁר קְשָׁרִים לְמַעְלָה וּלְמַטָּה כְּדֵי לְיַחֵד הַכֹּל, וַהֲרֵי בֵּאַרְנוּ. וְזֶה מְכַפֵּר עַל יֵצֶר הָרָע וְעַל עֲבוֹדָה זָרָה, שֶׁהוּא הצַּד הָאַחֵר, וַהֲרֵי בֵּאַרְנוּ."],[1,"","פָּתַח וְאָמַר, (שמות ל) וַיַּעַשׂ מִזְבֵּחַ מִקְטַר קְטֹרֶת וְגוֹ'. בְּפָסוּק זֶה יֵשׁ לְהִתְבּוֹנֵן, מִשּׁוּם שֶׁהָיוּ שְׁנֵי מִזְבְּחוֹת - מִזְבַּח הָעוֹלוֹת וּמִזְבַּח קְטֹרֶת הַסַּמִּים, זֶה בַּחוּץ וְזֶה בִּפְנִים, מִזְבַּח הַקְּטֹרֶת הַזֶּה שֶׁהוּא פְּנִימִי, לָמָּה נִקְרָא מִזְבֵּחַ, וַהֲרֵי אֵין זוֹבְחִים בּוֹ זְבָחִים, וּמִזְבֵּחַ עַל כֵּן נִקְרָא?"],[2,"","אֶלָּא מִשּׁוּם שֶׁמְּבַטֵּל וְכוֹפֵת כַּמָּה צְדָדִים רָעִים, וּמִשּׁוּם שֶׁאוֹתוֹ הַצַּד הָרָע כָּפוּת, לֹא יָכוֹל לִשְׁלֹט וְלֹא לִהְיוֹת קָטֵגוֹר, וְעַל כֵּן נִקְרָא מִזְבֵּחַ. כְּשֶׁאוֹתוֹ הַצַּד הָרָע הָיָה רוֹאֶה (עמוד העשן) עֲשַׁן הַקְּטֹרֶת שֶׁעוֹלֶה - נִכְנָע וּבוֹרֵחַ, וְלֹא יָכוֹל לִקְרַב כְּלָל לַמִּשְׁכָּן. וּמִשּׁוּם זֶה נִטְהָר וְלֹא מִתְעָרֵב בְּאוֹתָהּ שִׂמְחָה שֶׁלְּמַעְלָה, פְּרָט לַקָּדוֹשׁ-בָּרוּךְ- הוּא לְבַדּוֹ, וּמִשּׁוּם שֶׁכָּל כָּךְ חֲבִיבָה, לֹא עוֹמֵד אוֹתוֹ מִזְבֵּחַ אֶלָּא (פנימי) לִפְנִים, שֶׁזֶּהוּ הַמִּזְבֵּחַ שֶׁנִּמְצָאוֹת בּוֹ בְּרָכוֹת, וְעַל כֵּן נִסְתָּר מִן הָעַיִן."],[3,"","מַה כָּתוּב בְּאַהֲרֹן? (במדבריז) וַיַּעֲמֹד בֵּין הַמֵּתִים וּבֵין הַחַיִּים וַתֵּעָצַר הַמַּגֵּפָה, שֶׁכָּפַת אֶת מַלְאַךְ הַמָּוֶת שֶׁלֹּא יָכוֹל לִשְׁלֹט כְּלָל וְלֹא לַעֲשׂוֹת דִּין. סִימָן זֶה נִמְסַר בְּיָדֵינוּ, שֶׁבְּכָל מָקוֹם שֶׁאוֹמְרִים בְּכַוָּנָה וּרְצוֹן הַלֵּב אֶת מַעֲשֵׂה הַקְּטֹרֶת, שֶׁאֵין שׁוֹלֵט הַמָּוֶת בְּאוֹתוֹ מָקוֹם וְלֹא יֻזַּק, וְלֹא יְכוֹלִים שְׁאָר הָעַמִּים לִשְׁלֹט עַל אוֹתוֹ הַמָּקוֹם."],[4,"","בֹּא וּרְאֵה מַה כָּתוּב, מִזְבֵּחַ מִקְטַר קְטֹרֶת. כֵּיוָן שֶׁכָּתוּב מִזְבֵּחַ, לָמָּה נִקְרָא מִקְטַר קְטֹרֶת? אֶלָא מִשּׁוּם שֶׁנּוֹטְלִים מֵהַמָּקוֹם הַזֶּה לְהַקְטִיר כְּמוֹ שֶׁעָשָׂה אַהֲרֹן. עוֹד, הַמִּזְבֵּחַ צָרִיךְ לְהַקְטִיר לְקַדְּשׁוֹ בְּאוֹתָהּ קְטֹרֶת, וְעַל כֵּן מִקְטַר קְטֹרֶת. עוֹד, מִקְטַר קְטֹרֶת כְּתַרְגּוּמוֹ, לְהַקְטִיר קְטֹרֶת. שֶׁהֲרֵי אָסוּר לְהַקְטִיר בְּמָקוֹם אַחֵר קְטֹרֶת, רַק מִמַּחְתָּה. (ממחתה של יום הכפורים)."],[5,"","בֹּא וּרְאֵה, זֶה מִי שֶׁדִּין רוֹדֵף אַחֲרָיו, צָרִיךְ אֶת הַקְּטֹרֶת הַזּוֹ וְלָשׁוּב לִפְנֵי רִבּוֹנוֹ, שֶׁהֲרֵי הוּא סִיּוּעַ לְסַלֵּק דִּינִים מִמֶּנּוּ, וּבָזֶה וַדַּאי הֵם מִסְתַּלְּקִים מִמֶּנּוּ, אִם הוּא רָגִיל בְּכָךְ לְהַזְכִּיר פַּעֲמִים בַּיּוֹם - בַּבֹּקֶר וּבָעֶרֶב, שֶׁכָּתוּב קְטֹרֶת סַמִּים בַּבֹּקֶר בַּבֹּקֶר, וְכָתוּב בֵּין הָעַרְבַּיִם יַקְטִירֶנָּה. וְזֶהוּ קִיּוּמוֹ שֶׁל הָעוֹלָם תָּמִיד, שֶׁכָּתוּב (שמות ל) קְטֹרֶת תָּמִיד לִפְנֵי ה' לְדֹרֹתֵיכֶם. וַדַּאי שֶׁהוּא קִיּוּם הָעוֹלָם לְמַטָּה וְקִיּוּם הָעוֹלָם לְמַעְלָה."],[6,"","בְּאוֹתוֹ מָקוֹם שֶׁלֹּא נִזְכָּר בְּכָל יוֹם מַעֲשֵׂה הַקְּטֹרֶת, הַדִּינִים שֶׁלְּמַעְלָה שְׁרוּיִים בּוֹ וּמַגֵּפוֹת רַבּוֹת בּוֹ, וְעַמִּים אֲחֵרִים שׁוֹלְטִים עָלָיו, מִשּׁוּם שֶׁכָּתוּב קְטֹרֶת תָּמִיד לִפְנֵי ה'. תָּמִיד הִיא עוֹמֶדֶת לִפְנֵי ה' יוֹתֵר מִכָּל הָעֲבוֹדוֹת הָאֲחֵרוֹת. חָבִיב הוּא מַעֲשֵׂה הַקְּטֹרֶת, שֶׁהוּא נִכְבָּד וְחָבִיב לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא יוֹתֵר מִכָּל הָעֲבוֹדוֹת וְהָרְצוֹנוֹת (והמעשים) שֶׁל הָעוֹלָם. וְאַף עַל גַּב שֶׁהַתְּפִלָּה מְעֻלָּה מֵהַכֹּל - מַעֲשֵׂה הַקְּטֹרֶת הוּא נִכְבָּד וְחָבִיב לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא."],[7,"","בֹּא וּרְאֵה מַה בֵּין תְּפִלָּה לְמַעֲשֵׂה הַקְּטֹרֶת. אֶת הַתְּפִלָּה תִּקְּנוּ בִּמְקוֹם קָרְבָּנוֹת שֶׁהָיוּ יִשְׂרָאֵל עוֹשִׂים, וְכָל אוֹתָם קָרְבָּנוֹת שֶׁהָיוּ עוֹשִׂים יִשְׂרָאֵל אֵינָם חֲשׁוּבִים כְּמוֹ הַקְּטֹרֶת. וְעוֹד, מַה בֵּין זֶה לָזֶה? אֶלָּא תְּפִלָּה הִיא תִּקּוּן לְתַקֵּן מַה שֶּׁצָּרִיךְ. קְטֹרֶת עוֹשָׂה יוֹתֵר, מְתַקֶּנֶת וְקוֹשֶׁרֶת קְשָׁרִים וְעוֹשָׂה אוֹר יוֹתֵר מֵהַכֹּל. וּמִי הוּא שֶׁמַּעֲבִיר זֻהֲמָה וּמְטַהֵר אֶת הַמִּשְׁכָּן, וְהַכֹּל מֵאִיר וְנִתְקָן וְנִקְשָׁר כְּאֶחָד."],[8,"","וְלָכֵן צְרִיכִים לְהַקְדִּים מַעֲשֵׂה הַקְּטֹרֶת לַתְּפִלָּה בְּכָל יוֹם וָיוֹם, לְהַעֲבִיר הַזֻּהֲמָה מֵהָעוֹלָם, שֶׁהִיא תִּקּוּן שֶׁל הַכֹּל בְּכָל יוֹם וָיוֹם, כְּמוֹ שֶׁאוֹתוֹ קָרְבָּן חָבִיב שֶׁמְּרֻצֶּה בּוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא."],[9,"","מַה כָּתוּב בְּמֹשֶׁה? (שם) וַיֹּאמֶר ה' אֶל מֹשֶׁה קַח לְךְ סַמִּים נָטָף וְגוֹ'. אַף עַל גַּב שֶׁבֵּאֲרוּהָ, אֲבָל מַה שּׁוֹנֶה בְּמַעֲשֶׂה זֶה יוֹתֵר מִכָּל מַה שֶּׁאָמַר לוֹ? אֶלָּא קַח לְךְ - לַהֲנָאָתְךְ וּלְתוֹעַלְתְּךְ. מִשּׁוּם שֶׁכְּשֶׁאִשָּׁה נִטְהֶרֶת, זוֹ הֲנָאָה לְבַעְלָהּ. וְסוֹד זֶה - קַח לְךְ סַמִּים, לְהַעֲבִיר הַזֻּהֲמָה, לְקַדֵּשׁ אִשָּׁה עִם בַּעְלָהּ. אַשְׁרֵי חֶלְקוֹ שֶׁל מֹשֶׁה."]]],[["כְּגַוְונָא דָּא (ויקרא ט׳:ב׳) קַח לְךָ עֵגֶל בֵּן בָּקָר, דְּאִתְּמַר לְאַהֲרֹן. לְכַפָּרָא עַל חוֹבֵיהּ, עַל הַהוּא עֵגֶל דְּאִיהוּ גָּרִים לוֹן לְיִשְׂרָאֵל. וְעַל דָּא כְּתִיב בְּמֹשֶׁה, קַח לְךָ, לַהֲנָאָתָךְ, וּלְתוֹעַלְתָּךְ. (ס\"א לכך אוקמוה בפסל לך, מההוא פסולת דלוח אבנא נתעשר משה אוף הכי לך להנאתך ולטובתך)","קְטֹרֶת קָשִׁיר קְשִׁירוּ, נָהִיר נְהִירוּ וְאַעְבַּר זוּהֲמָא. וְד' אִתְחַבָּר בה' (ד\"א ד' אתעביד ה'), ה' אִתְחַבָּר בְּו'. ו' סָלִיק וְאִתְעַטָּר בְּה'. ה' אִתְנְהִיר בְּי'. וְכֹלָּא סָלִיק רְעוּתָא לְאֵין סוֹף. וַהֲוֵי כֹּלָּא קְשִׁירוּ חַד, וְאִתְעָבִיד חַד קְשִׁירוּ, בְּרָזָא חֲדָא דְּאִיהוּ קִשְׁרָא עִלָּאָה דְּכֹלָּא.","מִכָּאן וּלְהָלְאָה, כֵּיוָן דְּכֹלָּא אִתְקַשְּׁרָא בְּהַאי קִשְׁרָא, אִתְעֲטָּר כֹּלָּא בְּרָזָא דְּאֵין סוֹף. וְרָזָא דִּשְׁמָא קַדִּישָׁא אִתְנְהִיר, וְאִתְעַטָּר בְּכָל סִטְרִין, וְעָלְמִין כֻּלְּהוּ בְּחֶדְוָה. וְאִתְנְהִירוּ בּוּצִינִין וּמְזוֹנִין וּבִרְכָּאן אִשְׁתְּכָחוּ בְּכָל עָלְמִין, וְכֹלָּא בְּרָזָא דִּקְטֹרֶת. וְאִי זוּהֲמָא לָא אִתְעַבָּר, כֹּלָּא לָא אִתְעָבִיד. דְּכֹלָּא בְּהַאי תַּלְיָיא.","תָּא חֲזֵי, קְטֹרֶת אִיהוּ קַדְמָאָה תָּדִיר, קֳדָם לְכֹלָּא. וּבְּגִין כָּךְ עוֹבָדָא דִּקְטֹרֶת אִצְטְרִיךְ לְאַקְדְּמָא לִצְלוֹתָא, לְשִׁירִין וְתוּשְׁבְּחָן. בְּגִין דְּכָל דָּא לָא סַלְּקָא, וְלָא אִתְתָּקַּן, וְלָא אִתְקָשָּׁר, עַד דְּאִתְעֲבָר זוּהֲמָא, מַה כְּתִיב (ויקרא ט״ז:ט״ז) וְכִפֶּר עַל הַקֹּדֶשׁ וְגוֹ' בְּקַדְמִיתָא, וּלְבָתַר וּמִפִּשְׁעֵיהֶם לְכָל חַטֹּאתָם. וְעַל דָּא בָּעֵינָן לְכַפְּרָא עַל קוּדְשָׁא, וּלְאַעְבְּרָא זוּהֲמָא, וּלְאִתְדַכְּאָה קֻדְשָׁא. וּלְבָתַר שִׁירִין וְתוּשְׁבְּחָאן וּצְלוֹתִין, כֹּלָּא כִּדְקָאָמְרָן.","זַכָּאִין אִינּוּן יִשְׂרָאֵל בְּעָלְמָא דֵּין, וּבְעָלְמָא דְּאָתֵי, דְּהָא אִינּוּן יַדְעִין לְתַקְּנָא תִּקּוּנָא דִּלְעֵילָּא וְתַתָּא, כִּדְבָעֵינָן לְתַקְּנָא תִּקּוּנָא מִתַּתָּא לְעֵילָּא עַד דְּאִתְקָשָּׁר כֹּלָּא כַּחֲדָא, בְּקִשּׁוּרָא חַד, בְּהַהוּא קִטוּרָא (ס\"א קשורא) עִלָּאָה כַּד בָּעֵינָן לְתַקְּנָא (תקונין לתתא בעינן לתקנא) בְּתִקּוּנָא דְּאַתְוָון רְשִׁימִין, דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְקְרֵי בְּהוֹן.","רַבִּי שִׁמְעוֹן וְרִבִּי אֶלְעָזָר בְּרֵיהּ, הָווֹ יַתְבֵי לֵילְיָא חַד, וְלָעָאן בְּאוֹרַיְיתָא. אָמַר רִבִּי אֶלְעָזָר לְרַבִּי שִׁמְעוֹן אֲבוֹי. הָא כְּתִיב (בראשית ג׳:ט״ז) וְאֶל הָאִשָּׁה אָמַר הַרְבָּה אַרְבֶּה עִצְּבוֹנִךְ וְהֵרוֹנִךְ בְּעֶצֶב תֵּלְדִי בָנִים וְאֶל אִישֵׁךְ תְּשׁוּקָתֵךְ וְגוֹ'. וְאוֹלִיפְנָא דְּדָא אִיהוּ רָזָא עִלָּאָה. תִּינָח לְתַתָּא, אֲבָל אִיהוּ כְּגַוְונָא דִּלְעֵילָּא, מַאי אִיכָּא לְמֵימַר.","פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (תהילים מ״ב:ב׳) כְּאַיָּל תַּעֲרֹג עַל אֲפִיקֵי מָיִם וְגוֹ'. הַאי קְרָא אוּקְמוּהָ. אֲבָל חַיָּה חֲדָא אִית בְּעָלְמָא, וְאִיהִי שַׁלְטָא בְּשֻׁלְטָנָא עַל אֶלֶף מַפְתְּחָן בְּכָל יוֹמָא. וְאִיהִי נוּקְבָּא וְתִיאוּבְתָּא דִּילָהּ תָּדִיר עַל אֲפִיקֵי מַיִם לְמִשְׁתֵּי וּלְאִתְרַוָואָה מִצַחוּתָא, דִּכְתִּיב כְּאַיָּל תַּעֲרוֹג עַל אֲפִיקֵי מַיִם.","הָכָא אִית לְאִסְתַּכְּלָא. בְּקַדְמִיתָא כְּתִיב כְּאַיָּל, וְלָא כְּתִיב כָּאַיֶּלֶת, וּלְבָתַר תַּעֲרוֹג, וְלָא כְּתִיב יַעֲרוֹג. אֲבָל רָזָא דָּא, דְּכַר וְנוּקְבָּא תַּרְוַויְיהוּ כַּחֲדָא דְּלָא לְאַפְרָשָׁא לוֹן, וְחַד אִיהוּ, דְּלָא אִצְטְרִיךְ לְסַלְּקָא דָּא מִן דָּא, אֶלָּא תַּרְוַויְיהוּ כַּחֲדָא. וְהַאי נוּקְבָּא, תַּעֲרוֹג עַל אֲפִיקֵי מַיִם, וְאִיהִי מִתְעַבְּרָא מִן דְּכוּרָא, וְקָשֵׁי עָלָהּ דְּהָא עַל דִּינָא קַיְּימָא.","וְכַד אוֹלִידַת קוּדְשָׁא בְּרִיךְ הוּא זַמִּין לָהּ חַד חִוְיָא עִלָּאָה רַבְרְבָא, וְאָתֵי וְנָשִׁיךְ לְגַבֵּי הַהוּא אֲתָר, וְאוֹלִידַת. וְרָזָא דָּא הַרְבָּה אַרְבֶּה עִצְּבוֹנֵךְ וְהֵרוֹנֵךְ, בְּגִין דְּאִיהִי מִתְחַלְחְלָא בְּכָל יוֹמָא, וּבְעַצִּיבוּ עַל עוֹבָדִין דְּעָלְמָא. בְּעֶצֶב תֵּלְדִי בָנִים. בְּעֶצֶב, דָּא רָזָא דְּחִוְיָיא, דְּעָצִיב אַנְפֵּיהוֹן דְּעָלְמָא.","וְאֶל אִישֵׁךְ תְּשׁוּקָתֵךְ, כְּמָה דְאַתְּ אָמֵר תַּעֲרוֹג עַל אֲפִיקֵי מַיִם. וְהוּא יִמְשָׁל בָּךְ, הָא אוֹקִימְנָא רָזָא, דְּאִיהוּ שַׁלִּיט עָלָהּ. וְכָל דָּא לָמָּה. בְּגִין דְּאָמְרָה סִיהֲרָא, כְּמָה דְּתָנֵינָן. וּבְּגִין כָּךְ אַזְעִירַת נְהוֹרָאָה, וְאַזְעִירַת שׁוּלְטָנָהָא, וְלֵית לָהּ רְשׁוּ מִגַּרְמָהּ, בַּר כַּד יָהֲבִין לָהּ חֵילָא.","בְּעֶצֶב תֵּלְדִי בָּנִים, כְּמָה דְּאוֹקִימְנָא. וְאִי תֵּימָא אֲמַאי אִצְטְרִיךְ חִוְיָא לְדָא. אֶלָּא דָּא פָּתַח אוֹרְחָא לְנַחְתָּא כָּל (ס\"א בכל) אִינּוּן נִשְׁמָתִין דְּעָלְמָא. דְּאִלְמָלֵא לָא פָּתַח אוֹרְחִין לְנַחְתָּא לְתַתָּא, לָא יִשְׁרֵי בְּגַוֵיהּ דְּבַר נָשׁ, מַה כְּתִיב לַפֶּתַח חַטָּאת רֹבֵץ. מַאי לַפֶּתַח. לְהַהוּא פֶּתַח דְּאִתְעַתְּדָא לְאוֹלָדָא, לְאַפָּקָא נִשְׁמָתִין לְעָלְמָא, אִיהוּ קָאִים לְגַבֵּי הַהוּא פֶּתַח.","וְכָל אִינּוּן נִשְׁמָתִין דְּאִצְטְרִיכוּ לְנַחְתָּא בְּגוּפִין קַדִּישִׁין, לָא קָאִים אִיהוּ לְהַהוּא פֶּתַח, וְלֵית לֵיהּ רְשׁוּ בְּהַהִיא נִשְׁמְתָא. וְאִי לָאו, הָא חִוְיָא נָשִׁיךְ, וְאִסְתְּאַב הַהוּא נָהָר (ס\"א אתר), וְלָאו אִיהִי נִשְׁמְתָא דְּאִתְדַּכְיָיא וְהָכָא אִיהוּ רָזָא עִלָּאָה, בְּעֶצֶב תֵּלְדִי בָנִים. רָזָא דָּא, דָּא נָחָשׁ, דְּהָא עִמֵּיהּ אוֹלִידַת נִשְׁמָתִין, בְּגִין (שלח ק\"ע ע\"א) דְּדָא אִיהוּ עַל גּוּפָא, וְדָא עַל נִשְׁמְתָא, וְתַרְוַויְיהוּ דָּא בְּדָא. דָּא נָקִיט נִשְׁמְתָא, וְדָא נָקִיט גּוּפָא."],[[0,"כגוונא דא קח וגו':","כעין זה, קח לך עגל בן בקר שנאמר לאהרן. פירושו ג\"כ להנאתך ולתועלתך, דהיינו לכפר על חטאו, על עגל ההוא שהוא גרם לישראל. ועל כן כתוב במשה קח לך, דהיינו להנאתך ולתועלתך."],[1,"קטרת קשיר קשירו וכו':","קטורת, קושר קשר, דהיינו שמיחד, מאיר אורה, ומעביר זוהמא, וה \u0003ד'\u0004 נעשה \u0003ה',\u0004 כי מטרם הזווג עם ז\"א, המלכות הוא \u0003דלת,\u0004 כי להיותה בלי חסדים אינה מאירה, והיא דלה, וכשז\"א נזדווג עמה מתלבשת החכמה שבה בחסדים ומאירה בכל השלמות ונעשית \u0003ה'.\u0004 והקטרת מיחדת יחוד ז\"א עם המלכות ע\"כ גורם שה \u0003ד'\u0004 נעשית \u0003ה'.\u0004 ש \u0003ה'\u0004 מתחברת על ידה עם \u0003ו',\u0004 שהוא ז\"א. וה \u0003ו'\u0004 עולה ומתעטרת ב \u0003ה'\u0004 ראשונה שהיא בינה, כדי לקבל שפע בשביל המלכות, וה \u0003ה'\u0004 שהיא בינה, מזדהרת ב \u0003י'\u0004 שהיא חכמה, כדי להשפיע לז\"א. והכל מעלים רצון לאין סוף ונעשו כולם, דהיינו חכמה בינה ז\"א ומלכות, שהם י\"ה ו\"ה, קשר אחד, ונעשה קשר אחד בסוד אחד, שהוא קשר עליון של הכל. וכל זה נעשה על ידי הקטרת."],[2,"מכאן ולהלאה כיון וכו':","מכאן ולהלאה, כיון שהכל נקשר בקשר ההוא, נתעטר הכל בסוד איז סוף, וסוד השם הקדוש נזדהר ונתעטר מכל הצדדים, והעולמות כולם הם בשמחה, והאירו הנרות, ומזון וברכות נמצאים בכל העולמות. והכל הגיע בסוד הקטרת. כי אם לא נעבר הזוהמא ע\"י הקטרת, הכל לא היה נעשה כי הכל תלוי בזה."],[3,"ה\"ה קטרת איהו וכו':","בוא וראה, קטרת הוא ראשונה תמיד, קודם הכל. ומשום זה צריכים להקדים מעשה הקטרת לתפלה, ושירות ותשבחות. משום שכל זה אינו עולה, ואינו מתתקן, ואינו מתקשר, עד שנעבר הזוהמא, ע\"י הקטרת. מה כתוב, וכפר על הקדש וגו' בתחילה, ואחר כך, ומפשעיהם לכל חטאתם. וע\"כ צריכים לכפר על הקדש, ולהעביר הזוהמא, ולטהר הקדש, ע\"י הקטרת, ואחר כך, שירות ותשבחות ותפלה, הכל כמו שאמרנו."],[4,"וכאין אינון ישראל וכו':","אשרי הם ישראל בעולם הזה ובעולם הבא, בי הם יודעים לתקן תקון של מעלה ומטה, כמו שצריכים לתקן התקון מלמטה למעלה, עד שנקשר הכל יחד בקשר אחד, בקשר ההוא העליון דהיינו הקטרת, כשצריכים לתקן בתקון של אותיות הרשומות, שהקב\"ה נקרא בהן, דהיינו הוי\"ה."],[5,"ר\"ש ור\"א בריה וכו':","ר' שמעון ור' אלעזר בנו, היו יושבים לילה אחד, ועוסקים בתורה. אמר ר' אלעזר לר\"ש אביו, הרי כתוב, ואל האשה אמר הרבה ארבה עצבונך והרונך בעצב תלדי בנים ואל אשך תשוקתך וגו'. ולמדנו שזה סוד עליון, כלומר שנוהג ג\"כ למעלה במלכות, הנה זה נכון למטה, באשה הגשמית, אבל אם הוא כעין של מעלה, דהיינו שגם האשה עליונה שהיא המלכות, נאמר לה בעצב תלדי בנים, מה יש כאן לומר."],[6,"פתח ר\"ש ואמר וכו':","פר\"ש ואמר, כאיל תערוג על אפיקי מים. מקרא זה העמידוהו. אבל חיה אחת יש בעולם, שהיא המלכות, והיא שולטת בשליטה על אלף מפתחות בכל יום, דהיינו הארת חכמה המכונה אלף בסו\"ה ואאלפך חכמה. והיא נקבה, ותשוקתה תמיד על אפיקי מים, דהיינו לחסדים דז\"א, שהחכמה שבה תתלבש בהם, לשתות ולהתרוות מצמא, כי החכמה שבה אינה יכולה להאיר בלי חסדים וע\"כ היא חשך וצמאה אחר אור החסדים שנקראים מים. שכתוב כאיל תערוג על אפיקי מים."],[7,"הכא אית לאסתכלא וכו':","כאן יש להסתכל, בתחילה כתוב כאיל, דהיינו זכר, ולא כתוב כאילת, נקבה, ואח\"כ כתוב, תערג, שהוא לשון נקבה, ולא כתוב, יערג שהוא לשון זכר. ומשיב, אבל סוד זה דכר ונוקבא יחד, שלא להפרידם, ואחד הוא, שלא צריך להעלותם זה מזה אלא שניהם הם ביחד. ונוקבא ההיא תערג על אפיקי מים, והיא מתעברת מן הדכר, וקשה לה, כי הוא עומד על דין."],[7,"","פירוש. כשהמלכות מתעברת מז\"א, דהיינו כשמקבלת ממנו מיין דכרין של הנשמות, המתחברים עם מיין נוקבין שלה, לבחינת נשמה אחת, אז היא מקבלת חכמה בשביל הנשמה מקו שמאל. ונודע, שבעת שהנוקבא באה תחת שליטת קו שמאל, היא נקפאת, ונסתמים כל פתחיה ושעריה. (כנ\"ל ב\"א אות שס\"ט בהסולם). ז\"ש \u0003ואיהי מתעברא מן דכורא וקשי עלה דהא על דינא קיימא.\u0004 דהיינו בקפאון, וסתימת כל השערים."],[8,"וכד אולידת וכו':","וכשמולידה, הקב\"ה מזמין לה נחש אחד עליון וגדול, ונושך למקום ההוא, ומולידה. וז\"ש הרבה ארבה עצבונך והרונך, משום שהיא מתחלחלת בכל יום, והיא בעצבות על מעשה העולם. \u0003בעצב תלדי בנים,\u0004 בעצב, הוא סוד הנחש שהעציב פניהם של העולם, שהביא עליהם המות ע\"י הפיתוי של עצה\"ד. ונזקקת אליו שיפתח הפתח שתוכל להוליד."],[8,"","ענין זה מבואר היטב בדברי הזהר משפטים (אות שכ\"ד ושכ\"ה, והארכנו שם בהסולם ד\"ה פנימיות עש\"ה) והקיצור הוא, שסתימת הרחם באה משליטת קו שמאל שאינו מתיחד בקו ימין, וע\"י קו אמצעי בסוד המסך דחירק הממעט את קו שמאל מג\"ר נכנע השמאל ומתיחד עם הימין, אמנם בשביל מיעוט ג\"ר של הנוקבא נופלים תנה\"י שלה לבריאה, והנחש יונק מיסוד שלה, שנפל לבריאה, באופן שפתיחת הרחם באה ע\"י נתינת רשות לנחש לינק מיסוד שלה, וע\"כ נבחן כמו שהנחש נושך ערייתא, והוא כדי לפתוח את רחם המלכות ע\"י חבורה עם החסדים שבימין, ותפתח מסתימתה, ותוליד את הנשמה. שז\"ס \u0003בעצב,\u0004 ע\"י יניקת הנחש מפתיחת הפתח, תלדי בנים. שאי אפשר בלאו הכי עש\"ה."],[9,"ואל אישך תשוקתך:","הוא כש\"א, תערוג על אפיקי מים. שמשתוקקת לז\"א שימשיע לה חסדים ותתרוה מצמאונה, (כנ\"ל אות תפ\"ו) \u0003והוא ימשל בך,\u0004 הרי העמדנו הסוד שהוא, ז\"א, שולט עליה, על המלכות. וכל זה למה משום שבתחילה היתה גדולה כמו ז\"א והוא לא שלט עליה, ומשום שאמרה הלבנה כמו שלמדנו, שהיא המלכות, שאמרה אי אפשר לב' מלכים שישתמשו בכתר אחד, ונאמר לה לכי ומעטי את עצמך, ומשום זה מיעטה אורה, והקטינה ממשלתה, ואין לה רשות מעצמה חוץ אם ז\"א נותן לה כח. ונמצא שהוא מושל עליה, כמ\"ש, והוא ימשל בך. (כמ\"ש כל זה לעיל פרשת בראשית א' דף ק\"ח ד\"ה וכבר ע\"ש)."],[10,"בעצב תלדי בנים:","הוא כמו שהעמדנו (באות תפ\"ו) שבעצב ה\"ס הנחש. ואם תאמר, למה צריכים נחש לזה. ומשיב, אלא זה פתח דרך, שירדו כל אלו הנשמות לעולם, ואם לא היה פתח דרכים שירדו הנשמות למטה, לא היו שורות הנשמות בתוך האדם (כמ\"ש זה לעיל אות תפ\"ו ע\"ש) מה כתוב, לפתח חטאת רובץ, מהו לפתח. היינו לפתח ההוא, של המלכות, הנועד להוליד ולהוציא נשמות לעולם. הוא, הנחש, עומד לפתח ההוא."],[11,"וכל אינון נשמתין וכו':","וכל אלו הנשמות שצריכים לרדת בגופים קדושים, דהיינו נשמות הנמשכות מקו ימין, אין הנחש עומד לפתח ההוא, כי אז אין המלכות צריכה למשוך חכמה משליטת השמאל, ואין שעריה נסתמים, שתהיה צריכה לפתיחת הנחש (כנ\"ל אות תפ\"ח) ואין להנחש רשות בנשמה ההוא. ואם לא, הרי הנחש נושך, ונטמא מקום ההוא (כמ\"ש בזהר משפטים אות שכ\"ב ושכ\"ג ע\"ש) ואין זו נשמה שנטהרה. ועליהן נאמר, בעצב תלדי בנים, שסוד זה הוא הנחש, שעמו מולידה נשמות, דהיינו ע\"י פתיחתו, כנ\"ל. כי זה, הנחש, הוא על הגוף. כי הגוף נולד מזוהמת הנחש. וזה, המלכות, היא על נשמה, שממנה נולדות נשמות, ושניהם מתלבשים זה בזה. זה אוחז בנשמה וזה אוחז בגוף."]],[[0,"","כְּמוֹ כֵן קַח לְךְ עֵגֶל בֶּן בָּקָר שֶׁנֶּאֱמַר לְאַהֲרֹן, לְכַפֵּר עַל חֶטְאוֹ עַל אוֹתוֹ עֵגֶל שֶׁהוּא גָּרַם לָהֶם לְיִשְׂרָאֵל. וְעַל זֶה כָּתוּב בְּמֹשֶׁה קַח לְךְ, לַהֲנָאָתְךְ וּלְתוֹעַלְתְּךְ. (לכךבארוה בפסל לך, מאותה פסלת של לוח אבן נתעשר משה. אף כאן לך להנאתך ולטובתך)."],[1,"","הַקְּטֹרֶת קוֹשֶׁרֶת קְשָׁרִים, מְאִירָה אוֹר וּמַעֲבִירָה זֻהֲמָה, וְד' מִתְחַבֶּרֶת בְּה' (ד' נעשית ה'), ה' מִתְחַבֶּרֶת בְּו', ו' עוֹלָה וּמִתְעַטֶּרֶת בְּה', ה' מְאִירָה בְּי', וְהַכֹּל מַעֲלֶה רָצוֹן לָאֵין סוֹף. וְנִהְיָה הַכֹּל קֶשֶׁר אֶחָד, וְנַעֲשֶׂה קֶשֶׁר אֶחָד בְּסוֹד אֶחָד, שֶׁהוּא קֶשֶׁר עֶלְיוֹן שֶׁל הַכֹּל."],[2,"","מִכָּאן וָהָלְאָה, כֵּיוָן שֶׁהַכֹּל נִקְשָׁר בַּקֶּשֶׁר הַזֶּה, אָז הַכֹּל מִתְעַטֵּר בְּסוֹד הָאֵין סוֹף, וְסוֹד הַשֵּׁם הַקָּדוֹשׁ נָאוֹר, וּמִתְעַטֵּר בְּכָל הַצְּדָדִים, וְכָל הָעוֹלָמוֹת בְּשִׂמְחָה, וּמְאִירִים הַמְּאוֹרוֹת, וּמְזוֹנוֹת וּבְרָכוֹת נִמְצָאוֹת בְּכָל הָעוֹלָמוֹת, וְהַכֹּל בְּסוֹד הַקְּטֹרֶת. וְאִם הַזֻּהֲמָה אֵינָהּ עוֹבֶרֶת, הַכֹּל לֹא נַעֲשֶׂה, שֶׁהַכֹּל תָּלוּי בָּזֶה."],[3,"","בֹּא וּרְאֵה, הַקְּטֹרֶת הִיא רִאשׁוֹנָה תָּמִיד לִפְנֵי הַכֹּל. וּמִשּׁוּם כָּךְ מַעֲשֵׂה הַקְּטֹרֶת צָרִיךְ לְהַקְדִּים לַתְּפִלָּה, לַשִּׁירוֹת וְתִשְׁבָּחוֹת, מִשּׁוּם שֶׁכָּל זֶה לֹא עוֹלֶה וְלֹא נִתְקָן וְלֹא נִקְשָׁר עַד שֶׁעוֹבֶרֶת הַזֻּהֲמָה. מָה כָּתוּב? (ויקרא טז) וְכִפֶּר עַל הַקֹּדֶשׁ וְגוֹ' - בָּרִאשׁוֹנָה, וְאַחַר כָּךְ - וּמִפִּשְׁעֵיהֶם לְכָל חַ אתָם. וְעַל כֵּן צְרִיכִים לְכַפֵּר עַל הַקֹּדֶשׁ וּלְהַעֲבִיר הַזֻּהֲמָה וּלְטַהֵר הַקֹּדֶשׁ, וְאַחַר כָּךְ שִׁירוֹת וְתִשְׁבָּחוֹת וּתְפִלּוֹת, הַכֹּל כְּפִי שֶׁאָמַרְנוּ."],[4,"","אַשְׁרֵיהֶם יִשְׂרָאֵל בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, שֶׁהֲרֵי הֵם יוֹדְעִים לְתַקֵּן תִּקּוּן שֶׁלְּמַעְלָה וָמַטָּה, כְּמוֹ שֶׁצְּרִיכִים לְתַקֵּן תִּקּוּן מִמַּטָּה לְמַעְלָה עַד שֶׁהַכֹּל נִקְשָׁר כְּאֶחָד בְּקֶשֶׁר אֶחָד בְּאוֹתוֹ קֶשֶׁר (קשור) עֶלְיוֹן כְּמוֹ שֶׁצְּרִיכִים לְתַקֵּן (תקונים שלמטה צריכים לתקן) בְּתִקּוּן שֶׁל הָאוֹתִיּוֹת הָרְשׁוּמוֹת שֶׁנִּקְרָא בָּהֶן הַקָּדוֹשׁ בָּרוּךְ הוּא."],[5,"","רַבִּי שִׁמְעוֹן וְרַבִּי אֶלְעָזָר בְּנוֹ הָיוּ יוֹשְׁבִים לַיְלָה אֶחָד וְעוֹסְקִים בַּתּוֹרָה. אָמַר רַבִּי אֶלְעָזָר לְרַבִּי שִׁמְעוֹן אָבִיו, הֲרֵי כָּתוּב (בראשית ב) וְאֶל הָאִשָּׁה אָמַר הַרְבָּה אַרְבֶּה עִצְּבוֹנֵךְ וְהֵרֹנֵךְ בְּעֶצֶב תֵּלְדִי בָנִים וְאֶל אִישֵׁךְ תְּשׁוּקָתֵךְ וְגוֹ'. וְלָמַדְנוּ שֶׁזֶּהוּ סוֹד עֶלְיוֹן. מֵילָא לְמַטָּה, אֲבָל הוּא כְּמוֹ שֶׁלְּמַעְלָה, מַה יֵּשׁ לוֹמַר?"],[6,"","פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (תהלים מב) כְּאַיָּל תַּעֲרֹג עַל אֲפִיקֵי מָיִם וְגוֹ'. פָּסוּק זֶה פֵּרְשׁוּהוּ. אֲבָל חַיָּה אַחַת יֵשׁ בָּעוֹלָם, וְהִיא שׁוֹלֶטֶת בְּשִׁלְטוֹן עַל אֶלֶף מַפְתְּחוֹת בְּכָל יוֹם. וְהִיא נְקֵבָה, וּתְשׁוּקָתָהּ תָּמִיד עַל אֲפִיקֵי מַיִם לִשְׁתּוֹת וּלְהִתְרַוּוֹת מִצִּמְאוֹנָהּ, שֶׁכָּתוּב כְּאַיָּל תַּעֲרֹג עַל אֲפִיקֵי מָיִם."],[7,"","כָּאן יֵשׁ לְהִתְבּוֹנֵן. בָּרִאשׁוֹנָה כָּתוּב כְּאַיָּל, וְלֹא כָתוּב כְּאַיֶּלֶת, וְאַחַר תַּעֲרֹג, וְלֹא כָתוּב יַעֲרֹג. אֲבָל סוֹד זֶה, זָכָר וּנְקֵבָה שְׁנֵיהֶם כְּאֶחָד שֶׁאֵין לְהַפְרִידָם, וְאֶחָד הוּא, שֶׁלֹּא צָרִיךְ לְהַעֲלוֹת אוֹתָם זֶה מִזֶּה, אֶלָּא שְׁנֵיהֶם כְּאֶחָד. וְהַנְּקֵבָה הַזּוֹ תַּעֲרֹג עַל אֲפִיקֵי מַיִם, וְהִיא מִתְעַבֶּרֶת מִן הַזָּכָר, וְקָשֶׁה עָלֶיהָ, שֶׁהֲרֵי עַל דִּין עוֹמֶדֶת."],[8,"","וּכְשֶׁמּוֹלִידָה, הַקָּדוֹשׁ בָּרוּךְ הוּא מַזְמִין לָהּ נָחָשׁ אֶחָד עֶלְיוֹן גָּדוֹל, וּבָא וְנוֹשֵׁךְ בְּאוֹתוֹ מָקוֹם וּמוֹלִידָה. וְסוֹד זֶה - הַרְבָּה אַרְבֶּה עִצְּבוֹנֵךְ וְהֵרֹנֵךְ, מִשּׁוּם שֶׁהִיא מִתְחַלְחֶלֶת בְּכָל יוֹם וּבְעֶצֶב עַל מַעֲשֵׂי הָעוֹלָם. בְּעֶצֶב תֵּלְדִי בָנִים. בְּעֶצֶב - זֶה סוֹד הַנָּחָשׁ, שֶׁמַּעֲצִיב פְּנֵיהֶם שֶׁל הָעוֹלָם."],[9,"","וְאֶל אִישֵׁךְ תְּשׁוּקָתֵךְ, כְּמוֹ שֶׁנֶּאֱמַר תַּעֲרֹג עַל אֲפִיקֵי מָיִם. וְהוּא יִמְשָׁל בָּךְ, הֲרֵי בֵּאַרְנוּ הַסּוֹד, שֶׁהוּא שׁוֹלֵט עָלֶיהָ. וְכָל זֶה לָמָּה? מִשּׁוּם שֶׁאָמְרָה הַלְּבָנָה, כְּמוֹ שֶׁשָּׁנִינוּ. וּמִשּׁוּם כָּךְ הִקְטִינָה אוֹרָהּ וְהִקְטִינָה שִׁלְטוֹנָהּ, וְאֵין לָהּ רְשׁוּת מֵעַצְמָהּ, פְּרָט לְכַאֲשֶׁר נוֹתְנִים לָהּ כֹּחַ."],[10,"","בְּעָצֶב תֵּלְדִי בָנִים, כְּמוֹ שֶׁבֵּאַרְנוּ. וְאִם תֹּאמַר, לָמָּה צָרִיךְ נָחָשׁ לָזֶה? אֶלָּא זֶה פָּתַח דֶּרֶךְ לְהוֹרִיד כָּל (בכל) אוֹתָן נְשָׁמוֹת שֶׁל הָעוֹלָם. שֶׁאִלְמָלֵא לֹא פָּתַח דְּרָכִים לְמַטָּה, לֹא יִשְׁרֶה בְּגוּף הָאָדָם. מַה כָּתוּב? לַפֶּתַח חַטָּאת רֹבֵץ. מַה זֶּה לַפֶּתַח? לְאוֹתוֹ פֶּתַח שֶׁנּוֹעָד לְהוֹלִיד וּלְהוֹצִיא נְשָׁמוֹת לָעוֹלָם, הוּא עוֹמֵד לְאוֹתוֹ פֶּתַח."],[11,"","וְכָל אוֹתָן נְשָׁמוֹת שֶׁהִצְטָרְכוּ לָרֶדֶת בְּגוּפִים קְדוֹשִׁים, הוּא אֵינוֹ עוֹמֵד לְאוֹתוֹ פֶּתַח, וְאֵין לוֹ רְשׁוּת בַּנְּשָׁמָה הַהִיא. וְאִם לֹא, הֲרֵי הַנָּחָשׁ נוֹשֵׁךְ, וְנִטְמָא אוֹתוֹ נָהָר (מקום), וְאֵינָהּ נְשָׁמָה שֶׁנִּטְהֳרָה, וְכָאן הוּא סוֹד עֶלְיוֹן. בְּעֶצֶב תֵּלְדִי בָנִים - סוֹד זֶה, זֶה נָחָשׁ, שֶׁהֲרֵי עִמּוֹ מוֹלִידָה נְשָׁמוֹת, מִשּׁוּם שֶׁזֶּה הוּא עַל הַגּוּף, וְזֶה עַל הַנְּשָׁמָה, וּשְׁנֵיהֶם זֶה בָּזֶה. זֶה לוֹקֵחַ נְשָׁמָה, וְזֶה לוֹקֵחַ הַגּוּף."]]],[["וּזְמִינָא דָּא חִוְיָא, לְאוֹלָדָא כָּל אִינּוּן גּוּפִין, עַד לָא יֵיתֵי זִמְנָא דִּילֵיהּ, הֲדָא הוּא דִכְתִיב, (ישעיהו ס״ו:ז׳) בְּטֶרֶם תָּחִיל יָלָדָה. זִמְנָא דְּחִוְיָא לְאוֹלָדָא בְּשֶׁבַע שְׁנִין, וְהָכָא בְּשִׁית, מַה דְּלָאו אִיהוּ זִמְנֵיהּ. וּבְהַהוּא זִמְנָא דְּאוֹלִיד לוֹן, מֵהַהוּא לֵידָה יָמוּת. דִּכְתִּיב, (ישעיהו כ״ה:ח׳) בִּלַע הַמָּוֶת לָנֶצַח. וּכְתִיב (ישעיהו כ״ו:י״ט) יִחְיוּ מֵתֶיךָ נְבֵלָתִי יְקוּמוּן.","אָמַר רַבִּי שִׁמְעוֹן, בְּהַהוּא זִמְנָא דְּיִתְעָרוּן מֵתֵי עָלְמָא, וְיִתְעַתְּדוּן בְּאַרְעָא קַדִּישָׁא, יְקוּמוּן חַיָּילִין חַיָּילִין, כֻּלְּהוּ עַל אַרְעָא דְּגָלִיל, בְּגִין דְּתַמָּן זַמִּין מַלְכָּא מְשִׁיחָא לְאִתְגַּלָּאָה, בְּגִין דְּאִיהוּ חוּלָקֵיהּ דְּיוֹסֵף, וְתַמָּן אִתְּבָּרוּ (אתחרב) בְּקַדְמִיתָא. וּמִתַּמָּן שָׁארוּ לְאַגְלָאָה מִכָּל אַתְרַיְיהוּ, וּלְאִתְבַּדְּרָא בֵּינֵי עֲמָמַיָא, כְּמָה דְאַתְּ אָמֵר (עמוס ו׳:ו׳) וְלֹא נֶחְלוּ עַל שֶׁבֶר יוֹסֵף.","וַאֲמַאי יְקוּמוּן תַּמָּן, בְּגִין דְּאִיהוּ חוּלָקֵיהּ דְּהַהוּא דְּאִשְׁתַּוֵי בַּאֲרוֹנָא, דִּכְתִּיב, (בראשית נ׳:כ״ו) וַיִּישֶם בָּאָרוֹן בְּמִצְרָיִם, וּלְבָתַר אִתְקְבַר בְּאַרְעָא קַדִּישָׁא, דִּכְתִּיב, (יהושע כ״ד:ל״ב) וְאֶת עַצְמוֹת יוֹסֵף אֲשֶׁר הֶעֱלוּ בְנִי יִשְׂרָאֵל מִמִּצְרַיִם קָבְרוּ בִשְׁכֶם. וְדָא אִיהוּ דְּקָאִים בְּקִיּוּמָא דִּבְרִית, יַתִּיר מִכֹּלָּא.","וּבְהַהוּא זִמְנָא דְּיִתְעָרוּן כֻּלְּהוּ חַיָּילִין חַיָּילִין, כֻּלְּהוּ יָהֲכוּן, דָּא לְחוּלָק אֲבָהַתְהוֹן, וְדָא לְחוּלָק אֲבָהַתְהוֹן, דִּכְתִּיב (ויקרא כ״ה:י׳) וְשַׁבְתֶּם אִישׁ אֶל אֲחוּזָּתוֹ. וְיִשְׁתְּמּוֹדְעוּן דָּא לְדָא. וְזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאַלְבָּשָׁא לוֹן לְכָל חַד וְחַד לְבוּשֵׁי מְרְקָּמָן, וְיֵיתוּן כֻּלְּהוּ וִישַׁבְּחוּן לְמָארֵיהוֹן בִּיְרוּשָׁלַ ם, וְיִתְחַבְּרוּן תַּמָּן אוּכְלוֹסִין אוּכְלוֹסִין, וִיְרוּשָׁלַ ם יִתְמְשַׁךְ לְכָל סִטְרִין, יַתִּיר מִמַּה דְּאִתְמְשָׁךְ כַּד אִתְחַבָּרוּ תַּמָּן מִגָּלוּתָא.","כֵּיוָן דְּיִתְחַבְּרוּן וִישַׁבְּחוּן לְמָארִיהוֹן, קוּדְשָׁא בְּרִיךְ הוּא יֶחְדֵּי עִמְּהוֹן, הֲדָא הוּא דִכְתִיב, (ירמיהו ל״א:י״ב) וּבָאוּ וְרִנְּנוּ בִמְּרוֹם צִיּוֹן, וּלְבָתַר וְנָהֲרוּ אֶל טוּב יְיָ' וְגוֹ', כָּל חַד וְחַד לְחוּלָקֵיהּ, וְחוּלָק אֲבָהֲתוֹי. וְאַחֲסָנְתְּהוֹן דְּיִשְׂרָאֵל תְּהֵא, עַד (נ\"א רמתא דרומא), דְּמָתָא דְּרוֹמָאֵי, וְתַמָּן יֵלְּפוּן אוֹרַיְיתָא, והָא אוּקְמוּהָ, וּכְתִיב (ישעיהו כ״ו:י״ט) הָקִיצוּ וְרַנְּנוּ שׁוֹכְנֵי עָפָר וגוֹ'. בָּרוּךָ ה' לְעוֹלָם אָמֵן וְאָמֵן."],[[0,"וזמינא דא חויא וכו':","ועתיד נחש הזה להוליד כל אלו הגופים מטרם שיבא הזמן שלו. ז\"ש, \u0003בטרם תחיל ילדה.\u0004 כי זמן של הנחש להוליד, הוא בז' שנים, וכאן מוליד בשש שנים, מה שאין זה זמנו. ובזמן ההוא שיוליד אותם, ימות מלידה ההיא, שכתוב, \u0003בלע המות לנצח.\u0004 וכתוב, \u0003יהיו מתיך\u0004 נבלתי יקומון."],[0,"","פירוש. יש כאן סוד גדול מקיף הכל. כי נודע שבשבירת הכלים, ואח\"כ ע\"י חטא דעצה\"ד ע\"י פיתוי הנחש, נתפזרו ש\"כ ניצוצי קדושה ונפלו לקליפות, שכל העבודה שלנו בתורה ומצות אינה יותר, אלא לחזור ולברר ש\"כ נצוצי קדושה אלו, ולהחזירם לקדושה, ואז יהיה גמר התקון, בסו\"ה בלע המות לנצח. אמנם לא כולם אנו צריכים לברר, אלא רפ\"ח ניצוצי קדושה בלבד מוטל עלינו לברר, אבל ל\"ב ניצוצי קדושה אחרונים, אין אנו צריכים לברר, כי עם בירור רפ\"ח ניצוצין הם נבררים מאליהם."],[0,"","ולהבין זה, צריכים לדעת מספר ש\"ך ניצוצין אלו מה הם. והענין הוא, כי שמונה מלכים נשברו, שהם דעת וחג\"ת נהי\"מ, ובכל מלך יש מ' בחינות, שהם עשר ספירות כח\"ב חג\"ת נהי\"מ, שבכל ספירה ד' בחינות חו\"ב תו\"מ, והם מ' בחינות, וח' פעם מ', הרי ש\"כ בחינות, ואלו הם הנקראים ש\"כ ניצוצין. ואם נחלקם על פי עשר הספירות שבהם, נמצא שיש ע\"ס כח\"ב חג\"ת נהי\"מ, שבכל ספירה ל\"ב בחינות, דהיינו שיש בכל ספירה ח' מלכים שבכל אחד ד' בחינות חו\"ב תו\"מ שהם ל\"ב ועשר פעמים ל\"ב הם ש\"ך."],[0,"","ואין לנו כח לברר אלא ט' ספירות ראשונות, שהם ט\"פ ל\"ב, שהם רפ\"ח ניצוצין, אבל אותם ל\"ב ניצוצין שבספירת המלכות אין לנו כח לברר, וגם אין צורך כלל לברר אותם, כי בהתברר הרפ\"ח ניצוצים בשלמות נבררים ל\"ב ניצוצי המלכות מאליהם. באפן שאין התקון תלוי אלא בבירור רפ\"ח ניצוצין, דהיינו עד ספירת היסוד. ול\"ב דמלכות נבררים עמהם מאליהם."],[0,"","וז\"ס שאמרו בזהר במקומות הרבה, שהגאולה וגמר התקון יהיו באלף הששי, שה\"ס ספירת היסוד. כי אחר שנשלם בירור היסוד, נשלמו בירורין של הרפ\"ח ניצוצין, ותיכף תהיה הגאולה וגמר התקון, ואין צריך לחכות עד אלף השביעי שה\"ס המלכות לברר גם ל\"ב ניצוצי המלכות, כי הם מבוררים עם הרפ\"ח שבאלף הששי. כנ\"ל."],[0,"","והנה הגופים נחשבים לתולדות הנחש, מטעם שהם נולדו מחמת פתוי הנחש לעץ הדעת, ואם לא חטא אדם בעצה\"ד לא היה מוליד גופים כי כדי לברר ולהחזיר כל רפ\"ח ניצוצי הקדושה שנפלו ע\"י חטא עצה\"ד, צריכים לגופים הרבה, ואחר שיולדו כל הגופים ויעשו מה שצריכים, תיכף יהיה גמר התקון."],[0,"","וזה אמרו, \u0003וזמינא דא חויא לאולדא כל אינון גופין עד עלא ייתי זמנא דיליה\u0004 וכו', \u0003זמנא דחויא לאולדא בז' שנין, והכא בשית,\u0004 כי לידת כל הגופים, פירושו, שהם יבררו כל הניצוצים שנפלו לקליפות מחמת חטא עצה\"ד, שהם ש\"כ ניצוצים, וא\"כ יהיה זמן הולדה שלה \u0003בז' שנין,\u0004 דהיינו בספירת המלכות שבאלף הז', שבה נגמרים הש\"כ ניצוצין. אבל \u0003והכא בשית\u0004 דהיינו באלף הששי, שהוא ספירת היסוד, שהוא אלף הששי, \u0003מה דלאו איהו זמניה,\u0004 שהרי בו נגמר בירור רפ\"ח ניצוצים בלבד. ולא כל הש\"ך אז יולדו כל הגופין, ויהיה גמר התקון. שזהו מטעם הנ\"ל, שבירור ניצוצי אלף השביעי אין צורך לבררם כלל, כי הם מבוררים עם רפ\"ח ניצוצים מאליהם וכיון שיגמרו רפ\"ח ניצוצים לשוב לקדושה בשלמות, תיכף יהיה גמר התקון."],[0,"","וז\"ש, \u0003ובההוא זמנא דאוליד לון, מההוא לידה ימות, דכתיב בלע המות לנצח\u0004 וכו': כי כיון שיהיה גמר התקון הרי יתבטל וימות הנחש ומלאך המות, שהנחש ומלאך המות היינו הך. ונמצא שהוא מת, מחמת שהוליד כל הגופים. בסו\"ה בלע המות לנצח. ואז יהיה תחיית המתים. כמ\"ש, \u0003יחיו מתיך נבלתי יקומון.\u0004"],[0,"","ואין לשאול, בית שלידת כל הגופין, יורה גמר התקון, א\"כ איך ניחס זה לנחש, שהוא ההיפך מתקון, והוא מלאך המות. אמנם ז\"ס מה שאמרו על הכתוב, והנה טוב מאד, שמאד יורה על מלאך המות שהוא טוב מאד. והענין הוא. כי אדם הראשון אע\"פ שהיה כולו קדש מטרם החטא, מ\"מ היה מחוסר שלמות, וז\"ש שאמרו ז\"ל על חטא עצה\"ד, שבעלילה באת עליו, כי ע\"י חטא עצה\"ד, הוליד גופים הרבה כנ\"ל, והם השלימו הכל. וע\"כ מיוחס זה אל הנחש, כי לולא הנחש שפיתה אותו לעץ הדעת, לא היו נולדים גופים מאדם הראשון, ולא היה נשלם התקון, הרי שיש לו יחס ישר אל גמר התקון, אלא מההוא לידה ימות."],[1,"אמר ר\"ש בההוא וכו':","אר\"ש, בזמן ההוא שיתעוררו מתי עולם ויזדמנו בארץ הקדושה, יקומו מחנות מחנות, כולם על ארץ הגליל, משום ששם עתיד מלך המשיח להתגלות משום שהוא חלקו של יוסף, ושם נשברו תחילה, שמשם הגלו תחילה מכל מקומותיהם ולהתפזר בין העמים כש\"א, ולא נחלו על שבר יוסף."],[2,"ואמאי יקומון תמן וכו':","ולמה יקומו שם העומדים לתחיה, משום שהוא חלקו של אותו שהושם בארון, שכתוב, ויישם בארון במצרים. ואח\"כ נקבר בארץ הקדושה, שכתוב, ואת עצמות יוסף אשר העלו בני ישראל ממצרים קברו בשכם. וזה, יוסף, עמד בקיום הברית יותר מכל השבטים."],[3,"ובההוא זמנא דיתערון וכו':","ובזמן ההוא שיתעוררו כולם מחנות מחנות, על ארץ הגליל, ילכו כולם זה לחלק אבותיו, וזה לחלק אבותיו. שכתוב ושבתם איש אל אחוזתו. ויכירו זה את זה. ועתיד הקב\"ה להלביש לכל אחד ואחד לבושים מעשה רוקם. ויבואו כולם וישבחו לאדונם בירושלים. ויתחברו שם המונים המונים, וירושלים תתפשט לכל הצדדים, יותר ממה שנתפשטה בעת שנתחברו שם בשובם מגלות."],[4,"כיון דיתחברון וישבחון וכו':","כיון שיתחברו וישבחו לרבונם, הקב\"ה ישמח עמהם, זה שכתוב, ובאו ורננו במרום ציון. ואחר כך, ונהרו אל טוב ה' וגו'. כל אחד ואחד לחלקו וחלק אבותיו. ונחלתם של ישראל תהיה עד רומי הגבוהה, ושם ילמדו תורה. וכבר העמידוהו, ברעיא מהימנא פנחס רנ\"ב ע\"א (ד\"י) וכתוב הקיצו ורננו שוכני עפר וגו'."],[4,"","פירוש. שרומי הגדולה אומר ברע\"מ הנ\"ל, שעליה נאמר גער חית קנה, וכד ייתי פורקנא דישראל יתבר ליה, ע\"ש. וע\"כ אומר כאן שנחלת ישראל תגיע עד רומי רבתא, ושם ילמדו תורה, דהיינו שיכבשוה וישיבו אותה לקדושה."]],[[0,"","וְעָתִיד הַנָּחָשׁ הַזֶּה לְהוֹלִיד כָּל אוֹתָם גּוּפִים טֶרֶם שֶׁיָּבֹא זְמַנּוֹ. זֶהוּ שֶׁכָּתוּב (ישעיה סו) בְּטֶרֶם תָּחִיל יָלָדָה. הַזְּמַן שֶׁל הַנָּחָשׁ לְהוֹלִיד הוּא בְּשֶׁבַע שָׁנִים, וְכָאן בְּשֵׁשׁ, מַה שֶּׁאֵינוֹ זְמַנּוֹ. וּבְאוֹתוֹ זְמַן שֶׁיּוֹלִיד אוֹתָם, יָמוּת מֵאוֹתָהּ לֵדָה, שֶׁכָּתוּב (שם כה) בִּלַּע הַמָּוֶת לָנֶצַח. וְכָתוּב (שם כו) יִחְיוּ מֵתֶיךְ נְבֵלָתִי יְקוּמוּן."],[1,"","אָמַר רַבִּי שִׁמְעוֹן, בְּאוֹתוֹ זְמַן שֶׁיֵּעוֹרוּ הַמֵּתִים שֶׁל הָעוֹלָם וְיִזְדַּמְּנוּ בָּאָרֶץ הַקְּדוֹשָׁה, יָקוּמוּ חֲיָלוֹת חֲיָלוֹת כֻּלָּם עַל אֶרֶץ הַגָּלִיל, מִשּׁוּם שֶׁשָּׁם עָתִיד מֶלֶךְ הַמָּשִׁיחַ לְהִתְגַּלּוֹת, מִשּׁוּם שֶׁהוּא חֶלְקוֹ שֶׁל יוֹסֵף וְשָׁם נִשְׁבְּרוּ (נחרב) בָּרִאשׁוֹנָה. וּמִשָּׁם הִתְחִילוּ לִגְלוֹת מִכָּל מְקוֹמוֹתֵיהֶם וּלְהִתְפַּזֵּר בֵּין הָעַמִּים, כְּמוֹ שֶׁנֶּאֱמַר (עמוס ו) וְלֹא נֶחְלוּ עַל שֶׁבֶר יוֹסֵף."],[2,"","וְלָמָּה יָקוּמוּ שָׁם? מִשּׁוּם שֶׁהוּא חֶלְקוֹ שֶׁל אוֹתוֹ שֶׁהוּשַׂם בְּאָרוֹן, שֶׁכָּתוּב (בראשית נ) וַיִּישֶׂם בָּאָרוֹן בְּמִצְרָיִם. וְאַחַר כָּךְ נִקְבַּר בָּאָרֶץ הַקְּדוֹשָׁה, שֶׁכָּתוּב (יהושע כד) וְאֶת עַצְמוֹת יוֹסֵף אֲשֶׁר הֶעֱלוּ בְנֵי יִשְׂרָאֵל מִמִּצְרַיִם קָבְרוּ בִשְׁכֶם. וְזֶהוּ שֶׁעָמַד בְּקִיּוּם הַבְּרִית יוֹתֵר מֵהַכֹּל."],[3,"","וּבְאוֹתוֹ זְמַן שֶׁיִּתְעוֹרְרוּ כֻלָּם חֲיָלוֹת חֲיָלוֹת, כֻּלָּם יֵלְכוּ, זֶה לְחֵלֶק אֲבוֹתָם וְזֶה לְחֵלֶק אֲבוֹתָם, שֶׁכָּתוּב (ויקרא כה) וְשַׁבְתֶּם אִישׁ אֶל אֲחֻזָּתוֹ, וְיַכִּירוּ זֶה אֶת זֶה. וְעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַלְבִּישָׁם כָּל אֶחָד וְאֶחָד לְבוּשִׁים רְקוּמִים, וְיָבאוּ כֻלָּם וִישַׁבְּחוּ אֶת רִבּוֹנָם בִּירוּשָׁלַיִם, וְיִתְחַבְּרוּ שָׁם הֲמוֹנִים הֲמוֹנִים, וִירוּשָׁלַיִם תִּמָּשֵׁךְ לְכָל הַצְּדָדִים יוֹתֵר מִמַּה שֶּׁנִּמְשְׁכָה כְּשֶׁהִתְחַבְּרוּ שָׁם מִן הַגָּלוּת."],[4,"","כֵּיוָן שֶׁיִּתְחַבְּרוּ וִישַׁבְּחוּ אֶת רִבּוֹנָם, הַקָּדוֹשׁ בָּרוּךְ הוּא יִשְׂמַח עִמָּהֶם. זֶהוּ שֶׁכָּתוּב (ירמיה לא) וּבָאוּ וְרִנְּנוּ בִמְרוֹם צִיּוֹן, וְאַחַר כָּךְ - וְנָהֲרוּ אֶל טוּב ה' וְגוֹ'. כָּל אֶחָד וְאֶחָד לְחֶלְקוֹ וְחֵלֶק אֲבוֹתָיו. וְנַחֲלַת יִשְׂרָאֵל תִּהְיֶה עַד (הרמה של רומא) עִיר הָרוֹמָאִים, וְשָׁם יִלְמְדוּ תוֹרָה, וַהֲרֵי פֵּרְשׁוּהָ, וְכָתוּב (ישעיה כו) הָקִיצוּ וְרַנְּנוּ שֹׁכְנֵי עָפָר וְגוֹ'. בָּרוּךְ ה' לְעוֹלָם אָמֵן וְאָמֵן."]]]]};
